    // click/dblclick をまとめて処理する（pointerdownからclickまでの間に別要因の
    // 再描画が挟まりクリックを取りこぼす問題への対策）。dockBar 自体は毎回 render
    // のたびに作り直されるDOMなので、このMapとリスナも同じ寿命で毎回作り直して
    // よい（同じ dockBar に重複登録される心配はない）。
    const _dockIconContexts = new Map();
    if (fixedSide === 'left') {
      // 左レールはフォルダツリー開閉とメインアプリ起動だけに限定する。
    } else groups.forEach((g) => {
      if (!g?.root) return;
      const isActiveGroup = g.id === panelsetNode.activeGroupId;

      // 各 group の間には視覚的な区切りとして空のスペーサーのみ置く。
      // 以前は clickable なドックタブ見出しだったが、タブアイコンクリックで
      // switchGroup されるためボタンとしては不要（スペーサーだけ残す）。
      if (multiGroup && !fixedSide) {
        const spacer = document.createElement('div');
        spacer.className = 'gb-dock-tab-spacer';
        dockBar.appendChild(spacer);
      }

      // 各パネル（pane）のタブをアイコン列挙
      const panes = _collectPanesInGroup(g.root);
      panes.forEach((pane) => {
        (pane.tabs || []).forEach((tab, tabIdx) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'gb-dock-icon';
          const isActiveTab = (pane.activeTabIndex === tabIdx) && isActiveGroup && (fixedSide || !panelsetNode.collapsed);
          if (isActiveTab) btn.classList.add('active');
          btn.dataset.paneId = pane.id;
          btn.dataset.tabId = tab.id || '';
          btn.dataset.groupId = g.id;
          btn.dataset.panelsetId = panelsetNode.id;
          btn.dataset.tabType = tab.type || '';
          btn.dataset.e2eId = `dock-${panelsetNode.id}-${g.id}-${pane.id}-${tab.id || tabIdx}`;
          btn.title = tab.label || '';
          btn.innerHTML = _dockTabTypeIcon(tab.type, 18);
          const preserveWorkActive = typeof GBLayout?.isPassivePaneType === 'function'
            && GBLayout.isPassivePaneType(tab.type, tab, pane);
          const activateFixedTab = () => {
            panelsetNode.activeGroupId = g.id;
            pane.activeTabIndex = tabIdx;
            if (panelsetNode.collapsed) {
              _setPanelsetCollapsed(panelsetNode, false, { skipActivePaneCallback: true });
            } else {
              if (typeof GBLayout?.render === 'function') GBLayout.render();
              if (typeof GBLayout?.saveLayout === 'function') GBLayout.saveLayout();
            }
          };
          // Phase 5: D4 仕様 (click/dblclick 分岐)
          //   折りたたみ時: click=ポップアップ / dblclick=展開+アクティブ化
          //   展開時:       click=アクティブ化 / dblclick=折りたたみ
          // 実処理は dockBar の委譲リスナ（このforEachの外）にまとめる。ここでは
          // クリック時に必要な文脈だけ btn 単位で登録する。
          _dockIconContexts.set(btn, { pane, tab, tabIdx, g, activateFixedTab, preserveWorkActive });
          if (fixedSide === 'right') {
            btn.setAttribute('aria-haspopup', 'menu');
            btn.addEventListener('contextmenu', (e) => _showRightRailToolMenu(e, activateFixedTab, tab));
            if (typeof addLongPressHandler === 'function') {
              addLongPressHandler(btn, (e) => _showRightRailToolMenu(e, activateFixedTab, tab));
            }
          }
          dockBar.appendChild(btn);
          _totalIconCount += 1;
        });
      });
    });
    // click/dblclick の委譲リスナ（dockBar 単位で1つ）。個々のボタンではなく
    // dockBar 側で e.target.closest('.gb-dock-icon') により対象を判定するため、
    // pointerdown〜click の間に別要因の再描画でボタンDOMが作り直されても、
    // 新しいボタン要素側で改めて発火したclickをここで確実に拾える。
    dockBar.addEventListener('click', (e) => {
      const btn = e.target.closest('.gb-dock-icon');
      if (!btn || !dockBar.contains(btn)) return;
      const ctx = _dockIconContexts.get(btn);
      if (!ctx) return;
      e.stopPropagation();
      const { pane, tab, tabIdx, g, activateFixedTab } = ctx;
      if (fixedSide) {
        activateFixedTab();
        return;
      }
      if (panelsetNode.collapsed) {
        // R7: 単体パネルのみポップアップ（ドック全体ではなく、対応タブをアクティブにしてポップアップ）
        if (typeof GBDockPopup?.open === 'function') {
          GBDockPopup.open({
            panelsetNode,
            groupId: g.id,
            paneNode: pane,
            tab,
            tabIdx,
            anchorEl: btn,
          });
        }
      } else {
        // 展開時: group をアクティブ化 + タブをアクティブ化
        switchGroup(panelsetNode, g.id);
        pane.activeTabIndex = tabIdx;
        if (typeof GBLayout?.render === 'function') GBLayout.render();
        if (typeof GBLayout?.saveLayout === 'function') GBLayout.saveLayout();
      }
    });
    dockBar.addEventListener('dblclick', (e) => {
      const btn = e.target.closest('.gb-dock-icon');
      if (!btn || !dockBar.contains(btn)) return;
      // rail-toggle/appボタン等（_dockIconContexts未登録）はdblclick対象外。
      // 旧実装でもこれらのボタンには個別のdblclickリスナが無かったため、
      // 挙動を変えないようここで context の有無を先に見る。
      const ctx = _dockIconContexts.get(btn);
      if (!ctx) return;
      if (!_isFreeLayoutUiEnabled()) {
        e.stopPropagation();
        return;
      }
      e.stopPropagation();
      const { pane, tabIdx, g, preserveWorkActive } = ctx;
      if (typeof GBDockPopup?.close === 'function') GBDockPopup.close();
      if (panelsetNode.collapsed) {
        panelsetNode.activeGroupId = g.id;
        pane.activeTabIndex = tabIdx;
        let revealed = false;
        if (typeof GBLayout?.revealPane === 'function') {
          revealed = !!GBLayout.revealPane(pane.id, { activate: !preserveWorkActive });
        }
        if (!revealed && panelsetNode.collapsed) {
          panelsetNode.collapsed = false;
          if (!preserveWorkActive && typeof GBLayout?.setActivePane === 'function') GBLayout.setActivePane(pane.id);
          if (typeof GBLayout?.render === 'function') GBLayout.render();
          if (typeof GBLayout?.saveLayout === 'function') GBLayout.saveLayout();
        }
      } else {
        panelsetNode.collapsed = true;
        if (typeof GBLayout?.render === 'function') GBLayout.render();
        if (typeof GBLayout?.saveLayout === 'function') GBLayout.saveLayout();
      }
    });
    if (fixedSide === 'right') {
      const optionButton = dockBar.querySelector('.gb-dock-icon[data-tab-type="detail"]');
      const firstPanelButton = dockBar.querySelector('.gb-dock-icon:not(.gb-dock-rail-toggle)');
      if (optionButton && firstPanelButton && optionButton !== firstPanelButton) {
        dockBar.insertBefore(optionButton, firstPanelButton);
      }
    }
    // ==== 本体 ====
    const body = document.createElement('div');
    body.className = 'gb-dock-body';
    body.style.flex = '1 1 auto';
    body.style.minWidth = '0';
    body.style.minHeight = '0';
    body.style.overflow = 'hidden';
    body.style.display = panelsetNode.collapsed ? 'none' : 'flex';
    body.style.flexDirection = 'column';
    const active = groups.find(g => g && g.id === panelsetNode.activeGroupId);
    if (active?.root && typeof GBLayout?.renderNode === 'function') {
      body.appendChild(GBLayout.renderNode(active.root, depth));
    }
    if (fixedSide) _assignRailIconPaletteIndexes(dockBar);
    if (fixedSide === 'left') col.appendChild(dockBar);
    col.appendChild(body);
    // ドックバーは右側に配置（body を先に、dockBar を後に追加）。
    // ただしアイコンが 1 件も無い場合（例: group.root が全てネスト panelset で
    // そちらが自前のドックバーを持つケース）は外側ドックバーを描画しない。
    // これを描画すると空の 32px バーが並び「ドックバーが二列」に見えてしまう。
