/* === gb-pane-default-layout.js === */
;
// gb-pane-default-layout.js — Meldex standard initial pane layout
(function() {
  'use strict';

  const DEFAULT_LEFT_DOCK_WIDTH_PX = 260;
  const DEFAULT_RIGHT_DOCK_WIDTH_PX = 360;
  const DEFAULT_MIN_WORK_WIDTH_PX = 400;
  // 右レールの既定パネル一覧（gb-layout.js の FIXED_RAIL_RIGHT_DEFAULTS と同じ並び）。
  // 片方だけに項目を足すと、初期レイアウトと欠損補填で並びがずれる。
  const UTILITY_PANE_TYPES = new Set([
    'outliner', 'detail', 'preview', 'subpanel', 'chat', 'timer',
    'history', 'annotation', 'sticky', 'tags', 'search', 'version',
  ]);

  function _clampRatio(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function _layoutWidth() {
    const rootEl = document.getElementById('gb-layout-root');
    const raw = rootEl?.clientWidth || window.innerWidth || 1600;
    return Math.max(1, raw);
  }

  function _dockRatios() {
    const totalWidth = _layoutWidth();
    const minWorkWidth = Math.min(DEFAULT_MIN_WORK_WIDTH_PX, Math.max(260, totalWidth * 0.25));
    let leftWidth = DEFAULT_LEFT_DOCK_WIDTH_PX;
    let rightWidth = DEFAULT_RIGHT_DOCK_WIDTH_PX;
    const requiredWidth = leftWidth + rightWidth + minWorkWidth;
    if (requiredWidth > totalWidth) {
      const scale = Math.max(0.35, (totalWidth - minWorkWidth) / (leftWidth + rightWidth));
      leftWidth *= scale;
      rightWidth *= scale;
    }
    const leftRatio = leftWidth / totalWidth;
    const remainingWidth = Math.max(1, totalWidth - leftWidth);
    const workRatio = Math.max(1, remainingWidth - rightWidth) / remainingWidth;
    return {
      leftRatio,
      workRatio,
      leftWidth: Math.round(leftWidth),
      rightWidth: Math.round(rightWidth),
    };
  }

  function _fallbackId(prefix) {
    return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  }

  function _group(root) {
    if (typeof GBPanelSet !== 'undefined' && typeof GBPanelSet.createGroup === 'function') {
      return GBPanelSet.createGroup(root);
    }
    return { id: _fallbackId('group-default'), root };
  }

  function _dock(root, options) {
    const group = _group(root);
    const dock = (typeof GBPanelSet !== 'undefined' && typeof GBPanelSet.createPanelSetNode === 'function')
      ? GBPanelSet.createPanelSetNode([group], group.id)
      : {
          type: 'panelset',
          id: _fallbackId('panelset-default'),
          groups: [group],
          activeGroupId: group.id,
        };
    dock.collapsed = !!options?.collapsed;
    if (Number.isFinite(options?.popupWidth) && options.popupWidth > 0) {
      dock.defaultPopupWidth = Math.round(options.popupWidth);
    }
    return dock;
  }

  function _panelset(roots, activeIndex, options) {
    const groups = (Array.isArray(roots) ? roots : []).filter(Boolean).map(root => _group(root));
    const activeGroup = groups[Math.max(0, Math.min(groups.length - 1, activeIndex || 0))];
    const dock = (typeof GBPanelSet !== 'undefined' && typeof GBPanelSet.createPanelSetNode === 'function')
      ? GBPanelSet.createPanelSetNode(groups, activeGroup?.id)
      : {
          type: 'panelset',
          id: _fallbackId('panelset-default-fixed'),
          groups,
          activeGroupId: activeGroup?.id || null,
        };
    dock.collapsed = !!options?.collapsed;
    if (Number.isFinite(options?.popupWidth) && options.popupWidth > 0) {
      dock.defaultPopupWidth = Math.round(options.popupWidth);
    }
    return dock;
  }

  function _tab(label, type) {
    return GBTabs.createTab(label, type, '');
  }

  function _pane(tabs) {
    return GBLayout.createPaneNode(null, tabs, 0);
  }

  function _activeTabType(pane) {
    const tab = pane?.tabs?.[pane.activeTabIndex];
    return tab?.type || '';
  }

  function _isContentPane(pane) {
    const type = _activeTabType(pane);
    return !type || !UTILITY_PANE_TYPES.has(type);
  }

  function resolveMainPaneId(options) {
    if (typeof GBLayout === 'undefined' || typeof GBLayout.getAllPanes !== 'function') return '';
    const opts = options || {};
    const root = opts.root || GBLayout.root;
    const allPanes = GBLayout.getAllPanes(root) || [];
    const visiblePanes = GBLayout.getAllPanes(root, { activeOnly: true }).filter((pane) => {
      if (!pane?.id) return false;
      return typeof GBLayout.isPaneVisible === 'function' ? GBLayout.isPaneVisible(pane.id) : true;
    });
    const isUsable = (pane) => pane?.id && (opts.allowLocked || !pane.locked);
    const pick = (...candidates) => {
      for (const pane of candidates) {
        if (isUsable(pane)) return pane.id;
      }
      return '';
    };
    return pick(
      visiblePanes.find(pane => pane.meldexRole === 'main' && _isContentPane(pane)),
      visiblePanes.find(pane => pane.id === 'pane-main' && _isContentPane(pane)),
      visiblePanes.find(_isContentPane),
      allPanes.find(pane => pane.meldexRole === 'main' && _isContentPane(pane)),
      allPanes.find(pane => pane.id === 'pane-main' && _isContentPane(pane)),
      allPanes.find(_isContentPane),
      opts.contentOnly ? null : visiblePanes[0],
      opts.contentOnly ? null : allPanes[0],
    );
  }

  function build(options) {
    if (typeof GBLayout === 'undefined' || typeof GBTabs === 'undefined') return null;
    const mainPane = options?.mainPane || GBLayout.createPaneNode('pane-main', [], -1);
    const ratios = _dockRatios();

    mainPane.meldexRole = 'main';
    mainPane.tabs = [_tab('フォルダ', 'folder')];
    mainPane.activeTabIndex = 0;

    const leftPane = _pane([_tab('フォルダツリー', 'outliner')]);
    leftPane.meldexRole = 'left-sidebar';
    const leftDock = _dock(leftPane, { collapsed: false, popupWidth: ratios.leftWidth });
    leftDock.meldexRole = 'left-sidebar';

    const rightPanes = [
      _pane([_tab('オプション', 'detail')]),
      _pane([_tab('ビューワー', 'preview')]),
      _pane([_tab('サブパネル', 'subpanel')]),
      _pane([_tab('バージョン管理', 'version')]),
      _pane([_tab('チャット', 'chat')]),
      _pane([_tab('タイマー', 'timer')]),
      _pane([_tab('ヒストリー', 'history')]),
      _pane([_tab('注釈', 'annotation')]),
      _pane([_tab('タグ', 'tags')]),
    ];
    rightPanes.forEach(pane => { pane.meldexRole = 'right-sidebar'; });
    const rightDock = _panelset(rightPanes, 0, { collapsed: false, popupWidth: ratios.rightWidth });
    rightDock.meldexRole = 'right-sidebar';

    const workDock = _dock(mainPane, { collapsed: false });
    workDock.meldexRole = 'main';
    const contentSplit = GBLayout.createSplitNode('horizontal', ratios.workRatio, [workDock, rightDock]);
    const rootSplit = GBLayout.createSplitNode('horizontal', ratios.leftRatio, [leftDock, contentSplit]);

    GBLayout.root = rootSplit;
    if (typeof GBLayout.revealPane === 'function') {
      GBLayout.revealPane(mainPane.id, { activate: true, deferRender: true });
    }
    GBLayout.render();
    GBLayout.setActivePane(mainPane.id);
    if (!options?.skipSave) GBLayout.saveLayout();
    return { root: rootSplit, activePaneId: mainPane.id, ratios };
  }

  window.GBPaneDefaultLayout = {
    build,
    resolveMainPaneId,
    constants: {
      DEFAULT_LEFT_DOCK_WIDTH_PX,
      DEFAULT_RIGHT_DOCK_WIDTH_PX,
      DEFAULT_MIN_WORK_WIDTH_PX,
    },
  };
})();

;

/* === gb-docking.js === */
;
/* ==============================
   gb-docking.js: D&Dドッキングシステム（v5.0）
   5ゾーンドロップインジケータ
   ============================== */

const GBDocking = (() => {
  let _indicator = null;
  let _currentZone = null;
  let _currentTarget = null;
  let _rootListenersAttached = false;
  const TOOL_DROP_LABELS = {
    page: 'ノート',
    database: 'シート',
    scriptnote: 'シナリオ',
    board: 'ボード',
    calendar: 'スケジュール',
    preview: 'ビューワー',
    'smart-db': 'スマートシート',
    folder: 'フォルダ',
    outliner: 'フォルダツリー',
    chat: 'チャット',
    history: 'ヒストリー',
    annotation: '注釈',
    detail: 'オプション',
    search: '検索',
  };

  function _hasLockedPane() {
    return typeof GBLayout.hasLockedPane === 'function' && GBLayout.hasLockedPane();
  }

  function _isFreeLayoutUiEnabled() {
    if (typeof GBLayout === 'undefined') return true;
    return typeof GBLayout.isFreeLayoutUiEnabled === 'function'
      ? !!GBLayout.isFreeLayoutUiEnabled()
      : true;
  }

  function _isLockedPane(paneId) {
    return typeof GBLayout.isPaneLocked === 'function' && GBLayout.isPaneLocked(paneId);
  }

  function _showLayoutLockedStatus(message) {
    if (typeof showStatus === 'function') showStatus(message || 'ロック中のパネルは移動できません', true);
  }

  function _findLayoutNode(nodeId) {
    return (nodeId && typeof GBLayout?.findNode === 'function')
      ? GBLayout.findNode(GBLayout.root, nodeId)?.node
      : null;
  }

  function _layoutNodeHasLockedPane(nodeId) {
    return _nodeHasLockedPane(_findLayoutNode(nodeId));
  }

  function _groupHasLockedPane(panelsetId, groupId) {
    const panelset = _findLayoutNode(panelsetId);
    if (!panelset || panelset.type !== 'panelset') return false;
    const group = (panelset.groups || []).find(g => g && g.id === groupId);
    return _nodeHasLockedPane(group?.root);
  }

  function _targetColumnIdForPane(paneId) {
    return (typeof GBLayout?._findColumnAncestorId === 'function')
      ? GBLayout._findColumnAncestorId(paneId)
      : null;
  }

  function _parseDropJson(e, type) {
    try { return JSON.parse(e.dataTransfer.getData(type) || '{}'); } catch { return {}; }
  }

  // ドロップゾーン判定
  function getDropZone(paneEl, clientX, clientY) {
    const rect = paneEl.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    const w = rect.width;
    const h = rect.height;

    // 端から25%以内なら方向ゾーン
    const edgePct = 0.25;

    if (y < h * edgePct) return 'top';
    if (y > h * (1 - edgePct)) return 'bottom';
    if (x < w * edgePct) return 'left';
    if (x > w * (1 - edgePct)) return 'right';
    return 'center';
  }

  // インジケータ要素の作成
  function createIndicator() {
    if (_indicator) return _indicator;
    _indicator = document.createElement('div');
    _indicator.className = 'gb-drop-indicator';
    _indicator.style.display = 'none';
    document.body.appendChild(_indicator);
    return _indicator;
  }

  // インジケータの位置更新
  function updateIndicator(paneEl, zone) {
    const ind = createIndicator();
    const raw = paneEl.getBoundingClientRect();
    const z = (typeof _getZoom === 'function') ? _getZoom() : (parseFloat(document.documentElement.style.zoom) || 1);
    const rect = { left: raw.left / z, top: raw.top / z, width: raw.width / z, height: raw.height / z, right: raw.right / z, bottom: raw.bottom / z };

    ind.style.display = 'block';
    switch (zone) {
      case 'top':
        ind.style.left = rect.left + 'px';
        ind.style.top = rect.top + 'px';
        ind.style.width = rect.width + 'px';
        ind.style.height = (rect.height * 0.4) + 'px';
        break;
      case 'bottom':
        ind.style.left = rect.left + 'px';
        ind.style.top = (rect.top + rect.height * 0.6) + 'px';
        ind.style.width = rect.width + 'px';
        ind.style.height = (rect.height * 0.4) + 'px';
        break;
      case 'left':
        ind.style.left = rect.left + 'px';
        ind.style.top = rect.top + 'px';
        ind.style.width = (rect.width * 0.4) + 'px';
        ind.style.height = rect.height + 'px';
        break;
      case 'right':
        ind.style.left = (rect.left + rect.width * 0.6) + 'px';
        ind.style.top = rect.top + 'px';
        ind.style.width = (rect.width * 0.4) + 'px';
        ind.style.height = rect.height + 'px';
        break;
      case 'center':
        ind.style.left = (rect.left + 4) + 'px';
        ind.style.top = (rect.top + 4) + 'px';
        ind.style.width = (rect.width - 8) + 'px';
        ind.style.height = (rect.height - 8) + 'px';
        break;
    }
  }

  function hideIndicator() {
    if (_indicator) _indicator.style.display = 'none';
    _currentZone = null;
    _currentTarget = null;
    _rootZone = null;
  }

  function _toolTabLabel(toolType) {
    return TOOL_DROP_LABELS[toolType] || toolType;
  }

  function _dropToolToPane(paneId, zone, toolType) {
    if (!paneId || !toolType) return;
    const label = _toolTabLabel(toolType);
    if (zone === 'center') {
      GBTabs.addTab(paneId, label, toolType, '');
      return;
    }
    const tab = GBTabs.createTab(label, toolType, '');
    const newPane = GBLayout.createPaneNode(null, [tab], 0);
    const newPaneId = GBLayout.splitPane(paneId, null, zone, newPane);
    if (newPaneId) {
      GBLayout.setActivePane(newPaneId);
    } else if (typeof showStatus === 'function') {
      showStatus('分割上限に達しました', true);
    }
  }

  function _dropToolToRoot(zone, toolType) {
    if (!zone || !toolType) return;
    const tab = GBTabs.createTab(_toolTabLabel(toolType), toolType, '');
    const newPane = GBLayout.createPaneNode(null, [tab], 0);
    if (!GBLayout.splitRoot(zone, newPane)) return;
    GBLayout.setActivePane(newPane.id);
  }

  function _isRootDockDrop(e) {
    const types = e.dataTransfer?.types;
    if (!types) return false;
    return types.includes('application/x-gb-tab') ||
      types.includes('application/meldex-tool') ||
      (types.includes('application/x-meldex-node') && e.ctrlKey);
  }

  // ドロップ処理
  function handleDrop(targetPaneId, zone, data) {
    if (!data) return;
    if (_isLockedPane(targetPaneId)) {
      if (typeof showStatus === 'function') showStatus('ロック中のパネルには追加できません', true);
      return;
    }

    if (data.tabId && data.paneId) {
      if (_isLockedPane(data.paneId) && (data.paneId !== targetPaneId || zone !== 'center')) {
        if (typeof showStatus === 'function') showStatus('ロック中のパネルからタブは移動できません', true);
        return;
      }
      // 同ペインへのcenterドロップは並べ替え扱い（moveTabが処理）
      // タブの移動
      if (zone === 'center') {
        // 既存ペインのタブとして追加
        GBTabs.moveTab(data.paneId, data.tabId, targetPaneId);
      } else {
        // 新しいスプリットを作成
        const paneInfo = GBLayout.findNode(GBLayout.root, data.paneId);
        if (!paneInfo) return;
        const pane = paneInfo.node;
        const tabIdx = pane.tabs.findIndex(t => t.id === data.tabId);
        if (tabIdx < 0) return;
        const sourceTab = pane.tabs[tabIdx];
        const duplicateSingleTab = data.paneId === targetPaneId && pane.tabs.length <= 1;
        const cloneTabState = (state) => {
          if (!state || typeof state !== 'object') return state || {};
          if (typeof structuredClone === 'function') {
            try { return structuredClone(state); } catch {}
          }
          try { return JSON.parse(JSON.stringify(state)); } catch {}
          return { ...state };
        };
        const before = typeof GBLayout.captureLayoutSnapshot === 'function' ? GBLayout.captureLayoutSnapshot() : null;
        const tab = duplicateSingleTab
          ? GBTabs.createTab(sourceTab.label, sourceTab.type, sourceTab.path, cloneTabState(sourceTab.state))
          : pane.tabs.splice(tabIdx, 1)[0];

        // 新ペインを作成してタブを配置
        const newPane = GBLayout.createPaneNode(null, [tab], 0);
        const splitResult = GBLayout.splitPane(targetPaneId, null, zone, newPane, { skipHistory: true });
        // MAX_DEPTH到達等でsplit失敗 → タブを元ペインに戻す
        if (!splitResult) {
          if (!duplicateSingleTab) pane.tabs.splice(tabIdx, 0, tab);
          showStatus && showStatus('分割上限に達しました', true);
          return;
        }

        // 元ペインが空になった場合
        if (!duplicateSingleTab && pane.tabs.length === 0) {
          if (pane.activeTabIndex >= 0) pane.activeTabIndex = -1;
          const allPanes = GBLayout.getAllPanes(GBLayout.root);
          if (allPanes.length > 1) {
            GBLayout.removePane(data.paneId, { skipHistory: true });
          }
        } else if (!duplicateSingleTab) {
          if (tabIdx < pane.activeTabIndex) {
            pane.activeTabIndex--;
          } else if (pane.activeTabIndex >= pane.tabs.length) {
            pane.activeTabIndex = pane.tabs.length - 1;
          }
          GBLayout.render();
          GBLayout.saveLayout();
        } else {
          GBLayout.render();
          GBLayout.saveLayout();
        }

        GBLayout.setActivePane(newPane.id);
        if (before && typeof GBLayout.pushLayoutHistory === 'function') {
          GBLayout.pushLayoutHistory('レイアウト: タブを分割移動', before, GBLayout.captureLayoutSnapshot(), tab.label || tab.path || '');
        }
      }
    } else if (data.paneId && !data.tabId) {
      // ペイン単独の移動。zone に応じてディスパッチ:
      //   center              → applyColumnDrop で対象カラムへマージ（panelset 化）
      //   top/bottom/left/right → ソースペインを detach し、対象ペインの該当位置に分割挿入
      if (data.paneId === targetPaneId) return;
      // ロック中のペインからは移動不可（タブ移動と同じガード）
      if (_isLockedPane(data.paneId)) {
        if (typeof showStatus === 'function') showStatus('ロック中のパネルからは移動できません', true);
        return;
      }
      const findCol = (id) => (typeof GBLayout._findColumnAncestorId === 'function'
        ? GBLayout._findColumnAncestorId(id) : null);
      const targetColumnId = findCol(targetPaneId);
      const sourceColumnId = findCol(data.paneId);

      if (zone === 'center') {
        if (typeof GBLayout?.applyColumnDrop !== 'function') return;
        const targetId = targetColumnId || targetPaneId;
        // 同一カラム内へのドロップは無効（applyColumnDrop の detach が target を巻き込んで破壊するため）
        if (sourceColumnId && sourceColumnId === targetId) return;
        if (data.paneId === targetId) return;
        GBLayout.applyColumnDrop(data.paneId, targetId);
        return;
      }

      // top/bottom/left/right: ソースペインのタブを新ペインに移動し、対象ペインの該当位置へ splitPane で挿入、
      // 元ペインが空になれば removePane で片付ける（タブ移動と同じフロー）。
      const sourceInfo = GBLayout.findNode(GBLayout.root, data.paneId);
      if (!sourceInfo) return;
      const sourcePane = sourceInfo.node;
      if (!sourcePane || !Array.isArray(sourcePane.tabs) || sourcePane.tabs.length === 0) return;
      const before = typeof GBLayout.captureLayoutSnapshot === 'function' ? GBLayout.captureLayoutSnapshot() : null;
      const movingTabs = sourcePane.tabs.splice(0, sourcePane.tabs.length);
      const savedActiveIdx = Math.max(0, Math.min(sourcePane.activeTabIndex || 0, movingTabs.length - 1));
      const newPane = GBLayout.createPaneNode(null, movingTabs, savedActiveIdx);
      const splitResult = GBLayout.splitPane(targetPaneId, null, zone, newPane, { skipHistory: true });
      if (!splitResult) {
        // 失敗時はロールバック: 元ペインのタブを復元
        sourcePane.tabs.push(...movingTabs);
        if (typeof showStatus === 'function') showStatus('分割上限に達しました', true);
        return;
      }
      // 元ペインが空になったので削除（ただし全ペイン数が 1 以下にならない場合のみ）
      const allPanes = GBLayout.getAllPanes(GBLayout.root);
      if (allPanes.length > 1) {
        GBLayout.removePane(data.paneId, { skipHistory: true });
      } else {
        GBLayout.render();
        GBLayout.saveLayout();
      }
      GBLayout.setActivePane(newPane.id);
      if (before && typeof GBLayout.pushLayoutHistory === 'function') {
        GBLayout.pushLayoutHistory('レイアウト: パネル移動', before, GBLayout.captureLayoutSnapshot(), newPane.id || '');
      }
    }
  }

  // ルートレベル横断ドロップ（ウィンドウ端30px以内）
  const ROOT_EDGE = 30;
  let _rootZone = null;

  function _getRootEdgeZone(clientX, clientY) {
    const layoutEl = document.getElementById('gb-layout-root');
    if (!layoutEl) return null;
    const rect = layoutEl.getBoundingClientRect();
    if (clientY - rect.top < ROOT_EDGE) return 'top';
    if (rect.bottom - clientY < ROOT_EDGE) return 'bottom';
    if (clientX - rect.left < ROOT_EDGE) return 'left';
    if (rect.right - clientX < ROOT_EDGE) return 'right';
    return null;
  }

  function _showRootIndicator(zone) {
    const layoutEl = document.getElementById('gb-layout-root');
    if (!layoutEl) return;
    const ind = createIndicator();
    const raw = layoutEl.getBoundingClientRect();
    const z = (typeof _getZoom === 'function') ? _getZoom() : (parseFloat(document.documentElement.style.zoom) || 1);
    const rect = { left: raw.left / z, top: raw.top / z, width: raw.width / z, height: raw.height / z, right: raw.right / z, bottom: raw.bottom / z };
    ind.style.display = 'block';
    const thickness = 6;
    switch (zone) {
      case 'top':
        ind.style.left = rect.left + 'px'; ind.style.top = rect.top + 'px';
        ind.style.width = rect.width + 'px'; ind.style.height = thickness + 'px'; break;
      case 'bottom':
        ind.style.left = rect.left + 'px'; ind.style.top = (rect.bottom - thickness) + 'px';
        ind.style.width = rect.width + 'px'; ind.style.height = thickness + 'px'; break;
      case 'left':
        ind.style.left = rect.left + 'px'; ind.style.top = rect.top + 'px';
        ind.style.width = thickness + 'px'; ind.style.height = rect.height + 'px'; break;
      case 'right':
        ind.style.left = (rect.right - thickness) + 'px'; ind.style.top = rect.top + 'px';
        ind.style.width = thickness + 'px'; ind.style.height = rect.height + 'px'; break;
    }
  }

  // 全ペインにドロップターゲットを設定
  // カラム D&D: Shift+ドラッグ（gb-layout.part01.js の dragHandle dragstart で
  // application/x-gb-column ペイロードをセット済み）。ドロップは各ペインの
  // dragover/drop で center ゾーン判定時に受理。
  // カラムドラッグ用のインジケーター: 対象カラム全体をハイライトする。
  // ペイン基準ではなく「カラム = 水平スプリットの直接の子」全体を覆う。
  function _columnElementById(columnId) {
    if (!columnId) return null;
    const id = CSS.escape(columnId);
    return document.querySelector(`[data-column-node-id="${id}"]`)
      || document.querySelector(`[data-pane-id="${id}"]`)
      || document.querySelector(`[data-split-id="${id}"]`);
  }

  function _openTypeForDroppedNode(type) {
    return type === 'database' ? 'pivot' : (type || 'page');
  }

  function _droppedMeldexItems(e) {
    const nodeData = e.ctrlKey ? e.dataTransfer.getData('application/x-meldex-node') : '';
    if (!nodeData) return [];
    try {
      const parsed = JSON.parse(nodeData);
      const rawItems = Array.isArray(parsed?.items) && parsed.items.length ? parsed.items : [parsed];
      return rawItems.map(item => ({
        name: String(item?.name || item?.path || 'ノート').trim() || 'ノート',
        path: String(item?.path || '').trim(),
        type: _openTypeForDroppedNode(item?.type || 'page'),
      })).filter(item => item.path);
    } catch {
      return [];
    }
  }

  function _tabForDroppedNode(item) {
    return GBTabs.createTab(item.name, item.type, item.path);
  }

  function _openDroppedNodesAtRoot(zone, items) {
    if (!Array.isArray(items) || !items.length) return false;
    const tabs = items.map(_tabForDroppedNode);
    const newPane = GBLayout.createPaneNode(null, tabs, 0);
    if (!GBLayout.splitRoot(zone, newPane)) return false;
    GBLayout.setActivePane(newPane.id, { sync: true });
    const active = items[0];
    if (active && typeof navOpen === 'function') navOpen({ type: active.type, label: active.name, path: active.path });
    return true;
  }

  function _openDroppedNodesInPane(paneId, zone, items) {
    if (!paneId || !Array.isArray(items) || !items.length) return false;
    if (zone === 'center') {
      let opened = false;
      let lastOpened = null;
      for (const item of items) {
        if (GBTabs.addTab(paneId, item.name, item.type, item.path)) {
          opened = true;
          lastOpened = item;
        }
      }
      if (opened && lastOpened && typeof navOpen === 'function') {
        navOpen({ type: lastOpened.type, label: lastOpened.name, path: lastOpened.path });
      }
      return opened;
    }
    const tabs = items.map(_tabForDroppedNode);
    const newPane = GBLayout.createPaneNode(null, tabs, 0);
    const newPaneId = GBLayout.splitPane(paneId, null, zone, newPane);
    if (!newPaneId) {
      if (typeof showStatus === 'function') showStatus('分割上限に達しました', true);
      return false;
    }
    GBLayout.setActivePane(newPaneId, { sync: true });
    const active = items[0];
    if (active && typeof navOpen === 'function') navOpen({ type: active.type, label: active.name, path: active.path });
    return true;
  }

  function _nodeHasLockedPane(node) {
    if (!node) return false;
    if (node.type === 'pane') return _isLockedPane(node.id);
    if (node.type === 'split' && Array.isArray(node.children)) {
      return node.children.some(child => _nodeHasLockedPane(child));
    }
    if (node.type === 'panelset' && Array.isArray(node.groups)) {
      return node.groups.some(group => _nodeHasLockedPane(group?.root));
    }
    return false;
  }

  function _columnHasLockedPane(columnId) {
    const info = (typeof GBLayout?.findNode === 'function')
      ? GBLayout.findNode(GBLayout.root, columnId)
      : null;
    return _nodeHasLockedPane(info?.node);
  }

  function _updateColumnIndicator(paneEl) {
    if (!paneEl) return;
    const targetColumnId = typeof GBLayout?._findColumnAncestorId === 'function'
      ? GBLayout._findColumnAncestorId(paneEl.dataset.paneId)
      : null;
    const columnEl = _columnElementById(targetColumnId);
    const refEl = columnEl || paneEl;
    const ind = createIndicator();
    const raw = refEl.getBoundingClientRect();
    const z = (typeof _getZoom === 'function') ? _getZoom() : (parseFloat(document.documentElement.style.zoom) || 1);
    const rect = { left: raw.left / z, top: raw.top / z, width: raw.width / z, height: raw.height / z };
    ind.style.display = 'block';
    ind.style.left = (rect.left + 4) + 'px';
    ind.style.top = (rect.top + 4) + 'px';
    ind.style.width = Math.max(0, rect.width - 8) + 'px';
    ind.style.height = Math.max(0, rect.height - 8) + 'px';
  }

  function _setupColumnDropOnPanes() {
    const panes = document.querySelectorAll('.gb-pane');
    panes.forEach((paneEl) => {
      const paneId = paneEl.dataset.paneId;
      paneEl.addEventListener('dragover', (e) => {
        const types = e.dataTransfer.types;
        const isColumn = types.includes('application/x-gb-column');
        const isGroup = types.includes('application/x-gb-panelset-group');
        if (!isColumn && !isGroup) return;
        const targetColumnId = _targetColumnIdForPane(paneId) || paneId;
        if (_columnHasLockedPane(targetColumnId)) {
          hideIndicator();
          return;
        }
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        // カラム/グループ両方で left/right 新カラム挿入、center で合流
        const z = getDropZone(paneEl, e.clientX, e.clientY);
        const zone = (z === 'left' || z === 'right') ? z : 'center';
        if (paneId !== _currentTarget || _currentZone !== ('col-' + zone)) {
          _currentTarget = paneId;
          _currentZone = 'col-' + zone;
          if (zone === 'center') {
            _updateColumnIndicator(paneEl);
          } else {
            _updateColumnEdgeIndicator(paneEl, zone);
          }
        }
      });
      paneEl.addEventListener('dragleave', (e) => {
        const types = e.dataTransfer.types;
        if (!types.includes('application/x-gb-column') && !types.includes('application/x-gb-panelset-group')) return;
        if (!paneEl.contains(e.relatedTarget)) {
          if (typeof _currentZone === 'string' && _currentZone.indexOf('col-') === 0) hideIndicator();
        }
      });
      paneEl.addEventListener('drop', (e) => {
        const types = e.dataTransfer.types;
        const isColumn = types.includes('application/x-gb-column');
        const isGroup = types.includes('application/x-gb-panelset-group');
        if (!isColumn && !isGroup) return;
        e.preventDefault();
        e.stopPropagation();
        hideIndicator();
        const targetColumnId = _targetColumnIdForPane(paneId) || paneId;
        if (_columnHasLockedPane(targetColumnId)) {
          if (typeof showStatus === 'function') showStatus('ロック中のパネルには追加できません', true);
          return;
        }
        try {
          const z = getDropZone(paneEl, e.clientX, e.clientY);
          const isEdge = (z === 'left' || z === 'right');
          if (isGroup) {
            const data = _parseDropJson(e, 'application/x-gb-panelset-group');
            if (!data.groupId || !paneId) return;
            if (_groupHasLockedPane(data.panelsetId, data.groupId)) {
              _showLayoutLockedStatus('ロック中のパネルを含むグループは移動できません');
              return;
            }
            if (isEdge && typeof GBPanelSet?.insertGroupAsColumn === 'function') {
              GBPanelSet.insertGroupAsColumn(data.panelsetId, data.groupId, paneId, z);
            } else if (typeof GBPanelSet?.dropGroupOnPane === 'function') {
              GBPanelSet.dropGroupOnPane(data.panelsetId, data.groupId, paneId);
            }
            return;
          }
          const data = _parseDropJson(e, 'application/x-gb-column');
          if (!data.nodeId || !paneId) return;
          if (_layoutNodeHasLockedPane(data.nodeId)) {
            _showLayoutLockedStatus('ロック中のパネルを含むカラムは移動できません');
            return;
          }
          const targetId = targetColumnId;
          if (data.nodeId === targetId) return;
          if (isEdge && typeof GBLayout?.insertColumnAround === 'function') {
            GBLayout.insertColumnAround(data.nodeId, targetId, z);
          } else if (typeof GBLayout?.applyColumnDrop === 'function') {
            GBLayout.applyColumnDrop(data.nodeId, targetId);
          }
        } catch {}
      });
    });
  }

  function _boundaryDropTarget(handleEl, e) {
    const leftId = handleEl?.dataset?.columnDropLeftId || '';
    const rightId = handleEl?.dataset?.columnDropRightId || '';
    if (!leftId || !rightId) return null;
    const rect = handleEl.getBoundingClientRect();
    const useLeftSide = e.clientX < rect.left + rect.width / 2;
    return useLeftSide
      ? { targetId: leftId, side: 'right' }
      : { targetId: rightId, side: 'left' };
  }

  function _setupColumnDropOnSplitHandles() {
    document.querySelectorAll('.gb-split-horizontal > .gb-split-handle[data-column-drop-left-id][data-column-drop-right-id]').forEach((handleEl) => {
      handleEl.addEventListener('dragover', (e) => {
        const types = e.dataTransfer?.types;
        const isColumn = types?.includes?.('application/x-gb-column');
        const isGroup = types?.includes?.('application/x-gb-panelset-group');
        if (!isColumn && !isGroup) return;
        const target = _boundaryDropTarget(handleEl, e);
        if (!target?.targetId || _columnHasLockedPane(target.targetId)) {
          hideIndicator();
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        e.dataTransfer.dropEffect = 'move';
        const key = `boundary-${target.targetId}-${target.side}`;
        if (_currentTarget !== target.targetId || _currentZone !== key) {
          _currentTarget = target.targetId;
          _currentZone = key;
          const columnEl = _columnElementById(target.targetId) || handleEl;
          showEdgeIndicator(columnEl, target.side);
        }
      });
      handleEl.addEventListener('dragleave', (e) => {
        const types = e.dataTransfer?.types;
        if (!types?.includes?.('application/x-gb-column') && !types?.includes?.('application/x-gb-panelset-group')) return;
        if (!handleEl.contains(e.relatedTarget)) hideIndicator();
      });
      handleEl.addEventListener('drop', (e) => {
        const types = e.dataTransfer?.types;
        const isColumn = types?.includes?.('application/x-gb-column');
        const isGroup = types?.includes?.('application/x-gb-panelset-group');
        if (!isColumn && !isGroup) return;
        const target = _boundaryDropTarget(handleEl, e);
        if (!target?.targetId) return;
        e.preventDefault();
        e.stopPropagation();
        hideIndicator();
        if (_columnHasLockedPane(target.targetId)) {
          if (typeof showStatus === 'function') showStatus('ロック中のパネルには追加できません', true);
          return;
        }
        try {
          if (isGroup) {
            const data = _parseDropJson(e, 'application/x-gb-panelset-group');
            if (!data.panelsetId || !data.groupId) return;
            if (_groupHasLockedPane(data.panelsetId, data.groupId)) {
              _showLayoutLockedStatus('ロック中のパネルを含むグループは移動できません');
              return;
            }
            if (typeof GBPanelSet?.insertGroupAsColumn === 'function') {
              GBPanelSet.insertGroupAsColumn(data.panelsetId, data.groupId, target.targetId, target.side);
            }
            return;
          }
          const data = _parseDropJson(e, 'application/x-gb-column');
          if (!data.nodeId || data.nodeId === target.targetId) return;
          if (_layoutNodeHasLockedPane(data.nodeId)) {
            _showLayoutLockedStatus('ロック中のパネルを含むカラムは移動できません');
            return;
          }
          if (typeof GBLayout?.insertColumnAround === 'function') {
            GBLayout.insertColumnAround(data.nodeId, target.targetId, target.side);
          }
        } catch {}
      });
    });
  }

  // カラムの該当辺(left/right)をハイライト（新カラム挿入位置を示す太い縦バー）
  function _updateColumnEdgeIndicator(paneEl, side) {
    if (!paneEl) return;
    const targetColumnId = typeof GBLayout?._findColumnAncestorId === 'function'
      ? GBLayout._findColumnAncestorId(paneEl.dataset.paneId)
      : null;
    const columnEl = _columnElementById(targetColumnId);
    const refEl = columnEl || paneEl;
    const ind = createIndicator();
    const raw = refEl.getBoundingClientRect();
    const z = (typeof _getZoom === 'function') ? _getZoom() : (parseFloat(document.documentElement.style.zoom) || 1);
    const rect = { left: raw.left / z, top: raw.top / z, width: raw.width / z, height: raw.height / z };
    ind.style.display = 'block';
    ind.style.top = (rect.top + 4) + 'px';
    ind.style.height = Math.max(0, rect.height - 8) + 'px';
    const barW = 6;
    if (side === 'left') {
      ind.style.left = (rect.left - barW / 2) + 'px';
      ind.style.width = barW + 'px';
    } else {
      ind.style.left = (rect.left + rect.width - barW / 2) + 'px';
      ind.style.width = barW + 'px';
    }
  }

  // グローバル安全網: 何らかの理由で個別 dragend が発火しなかった場合でも
  // ドラッグ終了時に必ずインジケーターを消す
  let _globalDragEndAttached = false;
  function _ensureGlobalDragEnd() {
    if (_globalDragEndAttached) return;
    _globalDragEndAttached = true;
    document.addEventListener('dragend', () => { hideIndicator(); }, true);
    // 一部ブラウザで dragend が発火しないケースの保険
    document.addEventListener('drop', () => { setTimeout(hideIndicator, 0); }, true);
  }

  function setupDropTargets() {
    if (!_isFreeLayoutUiEnabled()) {
      hideIndicator();
      return;
    }
    _ensureGlobalDragEnd();
    _setupColumnDropOnPanes();
    _setupColumnDropOnSplitHandles();
    // ルートレベルのエッジドロップ（1回だけ登録）
    const layoutEl = document.getElementById('gb-layout-root');
    if (layoutEl && !_rootListenersAttached) {
      _rootListenersAttached = true;
      // キャプチャフェーズで先に処理（ペインのdragoverより優先）
      layoutEl.addEventListener('dragover', (e) => {
        if (!_isRootDockDrop(e)) return;
        if (_hasLockedPane()) {
          if (_rootZone) { _rootZone = null; hideIndicator(); }
          return;
        }
        // タブバー内のドラッグはタブ並び替えに委ねる
        if (e.target.closest('.gb-pane-tabs')) {
          if (_rootZone) { _rootZone = null; hideIndicator(); }
          return;
        }
        const rz = _getRootEdgeZone(e.clientX, e.clientY);
        if (rz) {
          e.preventDefault();
          e.stopPropagation();
          if (rz !== _rootZone) { _rootZone = rz; _showRootIndicator(rz); }
        } else {
          if (_rootZone) { _rootZone = null; hideIndicator(); }
        }
      }, true);
      layoutEl.addEventListener('drop', (e) => {
        if (!_isRootDockDrop(e)) return;
        if (e.target.closest('.gb-pane-tabs')) return;
        const rz = _getRootEdgeZone(e.clientX, e.clientY);
        if (!rz) return;
        if (_hasLockedPane()) {
          hideIndicator();
          _rootZone = null;
          if (typeof showStatus === 'function') showStatus('ロック中のパネルがあるため外側へ新しいパネルを追加できません', true);
          return;
        }
        e.preventDefault();
        e.stopPropagation();
        hideIndicator();
        _rootZone = null;

        const toolType = e.dataTransfer.getData('application/meldex-tool');
        if (toolType) {
          _dropToolToRoot(rz, toolType);
          return;
        }

        // タブD&D
        const tabData = e.dataTransfer.getData('application/x-gb-tab');
        if (tabData) {
          try {
            const data = JSON.parse(tabData);
            const paneInfo = GBLayout.findNode(GBLayout.root, data.paneId);
            if (!paneInfo) return;
            const pane = paneInfo.node;
            const tabIdx = pane.tabs.findIndex(t => t.id === data.tabId);
            if (tabIdx < 0) return;
            const before = typeof GBLayout.captureLayoutSnapshot === 'function' ? GBLayout.captureLayoutSnapshot() : null;
            const [tab] = pane.tabs.splice(tabIdx, 1);
            const newPane = GBLayout.createPaneNode(null, [tab], 0);
            if (!GBLayout.splitRoot(rz, newPane, { skipHistory: true })) { pane.tabs.splice(tabIdx, 0, tab); return; }
            if (pane.tabs.length === 0) {
              const allPanes = GBLayout.getAllPanes(GBLayout.root);
              if (allPanes.length > 1) GBLayout.removePane(data.paneId, { skipHistory: true });
            } else {
              if (tabIdx < pane.activeTabIndex) pane.activeTabIndex--;
              else if (pane.activeTabIndex >= pane.tabs.length) pane.activeTabIndex = pane.tabs.length - 1;
            }
            GBLayout.setActivePane(newPane.id);
            if (before && typeof GBLayout.pushLayoutHistory === 'function') {
              GBLayout.pushLayoutHistory('レイアウト: 外側へタブ移動', before, GBLayout.captureLayoutSnapshot(), tab.label || tab.path || '');
            }
          } catch {}
          return;
        }
        // フォルダツリーノード Ctrl+ドロップ
        const droppedItems = _droppedMeldexItems(e);
        if (droppedItems.length) {
          _openDroppedNodesAtRoot(rz, droppedItems);
        }
      }, true);
      layoutEl.addEventListener('dragleave', (e) => {
        if (!layoutEl.contains(e.relatedTarget)) { hideIndicator(); _rootZone = null; }
      }, true);
    }

    const panes = document.querySelectorAll('.gb-pane');
    panes.forEach(paneEl => {
      const paneId = paneEl.dataset.paneId;

      paneEl.addEventListener('dragover', (e) => {
        // タブまたはペインのD&Dのみ受け入れ
        // フォルダツリーノードはCtrl+ドラッグ時のみ（通常は各ビュー固有ハンドラに委ねる）
        if (!e.dataTransfer.types.includes('application/x-gb-tab') &&
            !e.dataTransfer.types.includes('application/x-gb-pane') &&
            !e.dataTransfer.types.includes('application/meldex-tool') &&
            !(e.dataTransfer.types.includes('application/x-meldex-node') && e.ctrlKey)) return;

        // 編集領域上ではリンク挿入が優先（Ctrl+ドラッグ以外）
        if (e.target.closest('[contenteditable="true"]') &&
            !e.ctrlKey &&
            e.dataTransfer.types.includes('application/x-meldex-node')) {
          hideIndicator();
          return;
        }

        if (_isLockedPane(paneId)) {
          hideIndicator();
          return;
        }

        // タブバー内でのドラッグはタブ並び替え処理に委ねる（分割インジケータを出さない）
        if (e.target.closest('.gb-pane-tabs')) {
          // ただし drop を受け取れるよう preventDefault は呼ぶ
          e.preventDefault();
          hideIndicator();
          return;
        }

        e.preventDefault();
        e.dataTransfer.dropEffect = e.dataTransfer.types.includes('application/meldex-tool') ? 'copy' : 'move';

        const zone = getDropZone(paneEl, e.clientX, e.clientY);
        if (zone !== _currentZone || paneId !== _currentTarget) {
          _currentZone = zone;
          _currentTarget = paneId;
          updateIndicator(paneEl, zone);
        }
      });

      paneEl.addEventListener('dragleave', (e) => {
        if (!paneEl.contains(e.relatedTarget)) {
          hideIndicator();
        }
      });

      paneEl.addEventListener('drop', (e) => {
        // 編集領域上でのmeldex-nodeドロップ（Ctrl なし）はエディタ側に委ねる
        if (e.target.closest('[contenteditable="true"]') &&
            !e.ctrlKey &&
            e.dataTransfer.types.includes('application/x-meldex-node') &&
            !e.dataTransfer.types.includes('application/x-gb-tab') &&
            !e.dataTransfer.types.includes('application/meldex-tool')) {
          return;
        }

        e.preventDefault();
        hideIndicator();

        if (_isLockedPane(paneId)) {
          if (typeof showStatus === 'function') showStatus('ロック中のパネルには追加できません', true);
          return;
        }

        const zone = getDropZone(paneEl, e.clientX, e.clientY);

        const toolType = e.dataTransfer.getData('application/meldex-tool');
        if (toolType) {
          e.stopPropagation();
          _dropToolToPane(paneId, zone, toolType);
          return;
        }

        // タブD&D
        const tabData = e.dataTransfer.getData('application/x-gb-tab');
        if (tabData) {
          try {
            const data = JSON.parse(tabData);
            handleDrop(paneId, zone, data);
          } catch {}
          return;
        }

        // ペインD&D
        const paneData = e.dataTransfer.getData('application/x-gb-pane');
        if (paneData) {
          try {
            const data = JSON.parse(paneData);
            handleDrop(paneId, zone, data);
          } catch {}
          return;
        }

        // フォルダツリーノードD&D（Ctrl+ドロップ時のみファイルを開く）
        const droppedItems = _droppedMeldexItems(e);
        if (droppedItems.length) {
          _openDroppedNodesInPane(paneId, zone, droppedItems);
        }
      });
    });
  }

  // 任意の要素の左/右辺にエッジインジケータ（新カラム挿入位置）を表示する公開 API。
  // side: 'left' | 'right'
  function showEdgeIndicator(el, side) {
    if (!el) return;
    const ind = createIndicator();
    const raw = el.getBoundingClientRect();
    const z = (typeof _getZoom === 'function') ? _getZoom() : (parseFloat(document.documentElement.style.zoom) || 1);
    const rect = { left: raw.left / z, top: raw.top / z, width: raw.width / z, height: raw.height / z };
    ind.style.display = 'block';
    ind.style.top = (rect.top + 4) + 'px';
    ind.style.height = Math.max(0, rect.height - 8) + 'px';
    const barW = 6;
    if (side === 'left') {
      ind.style.left = (rect.left - barW / 2) + 'px';
    } else {
      ind.style.left = (rect.left + rect.width - barW / 2) + 'px';
    }
    ind.style.width = barW + 'px';
  }

  return {
    setupDropTargets,
    hideIndicator,
    getDropZone,
    showEdgeIndicator,
    hasLockedPaneInNode: _layoutNodeHasLockedPane,
    hasLockedPaneInGroup: _groupHasLockedPane,
  };
})();

;

/* === gb-dock-popup.js === */
;
// ============================================================================
// gb-dock-popup.js — ドックバーアイコンのポップアップ一時表示 (Phase 5)
// ============================================================================
// 対象パネルの DOM 要素を一時的にポップアップへ移動して表示。ポップアップを
// 閉じたら元の位置に戻す。8方向リサイズ / 外クリック / Escape / 再クリックで
// 閉じる。同時表示は1つのみ。
// ============================================================================
(function () {
  'use strict';

  const Z_INDEX = 10050;
  const MIN_W = 200;
  const MIN_H = 150;
  const DEFAULT_W_RATIO = 0.6;
  const DEFAULT_H_RATIO = 0.8;
  const DEFAULT_OUTLINER_W = 260;
  const DEFAULT_RIGHT_DOCK_W = 360;
  const POPUP_OWNED_FLOATING_SELECTORS = [
    '.gb-context-menu',
    '.ab-dropdown',
    '.tool-menu-dropdown',
    '.status-dropdown',
    '.cell-inline-dd',
    '.user-dropdown',
    '#chat-title-dropdown',
    '.gb-palette-popup',
    '.gb-fmt-popup',
    '.sn2-header-popup',
    '._note-ctx-menu',
    '.db-picker-popup',
    '.cmd-palette',
    '.modal-overlay',
    '.gb-modal-overlay',
    '.gb-cal-modal-overlay',
    '.link-modal-overlay',
  ];

  let _popup = null;          // DOM element
  let _state = null;          // { panelsetId, groupId, paneId, tabId, tabType, originalParent, originalNextSibling, paneEl }
  let _resizeState = null;    // 現在リサイズ中の状態
  let _clickListener = null;
  let _keyListener = null;
  let _resizeWindowListener = null;
  let _suppressOutsidePointerUntil = 0;

  function isOpen() { return !!_popup; }

  function _dockPopupZoom() {
    const z = (typeof _getZoom === 'function')
      ? Number(_getZoom())
      : parseFloat(document.documentElement.style.zoom || '1');
    return Number.isFinite(z) && z > 0 ? z : 1;
  }

  function _viewportCssSize() {
    const z = _dockPopupZoom();
    return {
      w: Math.max(MIN_W, (window.innerWidth || document.documentElement.clientWidth || MIN_W) / z - 16),
      h: Math.max(MIN_H, (window.innerHeight || document.documentElement.clientHeight || MIN_H) / z - 16),
    };
  }

  function _clampPopupSize(size) {
    const viewport = _viewportCssSize();
    const w = Number(size?.w);
    const h = Number(size?.h);
    return {
      w: Math.max(MIN_W, Math.min(Number.isFinite(w) ? w : MIN_W, viewport.w)),
      h: Math.max(MIN_H, Math.min(Number.isFinite(h) ? h : MIN_H, viewport.h)),
    };
  }

  function _clampPopupRect(rect) {
    const viewport = _viewportCssSize();
    const size = _clampPopupSize({ w: rect?.w, h: rect?.h });
    const maxLeft = Math.max(8, viewport.w - size.w - 8);
    const maxTop = Math.max(8, viewport.h - size.h - 8);
    const rawLeft = Number(rect?.left);
    const rawTop = Number(rect?.top);
    return {
      left: Math.max(8, Math.min(Number.isFinite(rawLeft) ? rawLeft : 8, maxLeft)),
      top: Math.max(8, Math.min(Number.isFinite(rawTop) ? rawTop : 8, maxTop)),
      w: size.w,
      h: size.h,
    };
  }

  function _applyPopupRect(popup, rect) {
    const next = _clampPopupRect(rect);
    popup.style.left = next.left + 'px';
    popup.style.top = next.top + 'px';
    popup.style.width = next.w + 'px';
    popup.style.height = next.h + 'px';
    return next;
  }

  function _collectPanelsetTabTypes(panelsetNode) {
    const types = [];
    const walk = (node) => {
      if (!node) return;
      if (node.type === 'pane') {
        (node.tabs || []).forEach(tab => { if (tab?.type) types.push(tab.type); });
        return;
      }
      if (node.type === 'split') (node.children || []).forEach(walk);
      if (node.type === 'panelset') (node.groups || []).forEach(group => walk(group?.root));
    };
    (panelsetNode?.groups || []).forEach(group => walk(group?.root));
    return types;
  }

  function _inferDefaultPopupWidth(panelsetNode) {
    const explicit = Number(panelsetNode?.defaultPopupWidth || 0);
    if (explicit > 0) return explicit;
    const types = _collectPanelsetTabTypes(panelsetNode);
    if (types.includes('outliner')) return DEFAULT_OUTLINER_W;
    const rightDockTypes = new Set(['preview', 'timer', 'detail', 'version', 'chat', 'calendar', 'history', 'annotation']);
    if (types.some(type => rightDockTypes.has(type))) return DEFAULT_RIGHT_DOCK_W;
    return 0;
  }

  function _defaultRect(anchorEl, panelsetNode) {
    // 初期レイアウト由来の既定幅がある場合はパネル幅と揃える。
    // ユーザーがリサイズした後は panelset.popupRect が優先される。
    const parent = anchorEl?.closest?.('.gb-dock') || anchorEl?.closest?.('.gb-column') || document.body;
    const rect = parent.getBoundingClientRect();
    const z = _dockPopupZoom();
    const defaultWidth = _inferDefaultPopupWidth(panelsetNode);
    const rawW = defaultWidth > 0 ? Math.max(MIN_W, Math.round(defaultWidth)) : Math.max(MIN_W, Math.floor((rect.width / z) * DEFAULT_W_RATIO));
    const rawH = Math.max(MIN_H, Math.floor((rect.height / z) * DEFAULT_H_RATIO));
    return _clampPopupSize({ w: rawW, h: rawH });
  }

  function _positionPopup(popup, anchorEl, size) {
    const safeSize = _clampPopupSize(size);
    const anchorRect = anchorEl?.getBoundingClientRect?.();
    if (!anchorRect) {
      _applyPopupRect(popup, { left: 100, top: 100, w: safeSize.w, h: safeSize.h });
      return;
    }
    const z = _dockPopupZoom();
    const vw = (window.innerWidth || document.documentElement.clientWidth) / z;
    const vh = (window.innerHeight || document.documentElement.clientHeight) / z;
    const cssAnchor = {
      left: anchorRect.left / z,
      right: anchorRect.right / z,
      top: anchorRect.top / z,
    };
    // ドックバーは右側にあるため、ポップアップはアンカーの左側に開く。
    // 左側に入らなければ右側へフォールバック。
    let left = cssAnchor.left - safeSize.w - 2;
    if (left < 8) left = Math.min(vw - safeSize.w - 8, cssAnchor.right + 2);
    if (left < 8) left = 8;
    let top = cssAnchor.top;
    if (top + safeSize.h > vh - 8) top = Math.max(8, vh - safeSize.h - 8);
    _applyPopupRect(popup, { left, top, w: safeSize.w, h: safeSize.h });
  }

  function _buildPopupDom(title) {
    const el = document.createElement('div');
    el.className = 'gb-dock-popup';
    el.style.zIndex = String(Z_INDEX);
    el.innerHTML = `
      <div class="gb-dock-popup-header">
        <span class="gb-dock-popup-title"></span>
        <button type="button" class="gb-dock-popup-close" data-e2e-id="dock-popup-close" aria-label="閉じる" title="閉じる">×</button>
      </div>
      <div class="gb-dock-popup-body"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="n"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="e"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="s"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="w"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="ne"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="se"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="sw"></div>
      <div class="gb-dock-popup-resize-handle" data-dir="nw"></div>
    `;
    el.querySelector('.gb-dock-popup-title').textContent = title || '';
    el.querySelector('.gb-dock-popup-close').addEventListener('click', (e) => {
      e.stopPropagation();
      closePopup();
    });
    // 内部でのドラッグでページ遷移等を起こさない
    el.addEventListener('dragover', (e) => { e.preventDefault(); });
    return el;
  }

  function _findPaneElement(paneId) {
    if (!paneId) return null;
    const escapedId = (typeof CSS !== 'undefined' && typeof CSS.escape === 'function')
      ? CSS.escape(paneId)
      : String(paneId).replace(/["\\]/g, '\\$&');
    return document.querySelector(`.gb-pane[data-pane-id="${escapedId}"]`);
  }

  function _setPopupTargetState(panelsetNode, groupId, paneNode, tabIdx) {
    // ポップアップは一時表示なので panelsetNode.activeGroupId は変更しない。
    // ここで active group を永続変更すると、チャット復元や内部タブ操作から
    // revealPane() が走った時に折りたたみドックが展開されてしまう。
    if (paneNode && Number.isInteger(tabIdx) && paneNode.activeTabIndex !== tabIdx) {
      paneNode.activeTabIndex = tabIdx;
    }
  }

  function _syncPopupPaneDom(paneEl, paneNode) {
    if (!paneEl || !paneNode) return;
    const activeIndex = Number.isInteger(paneNode.activeTabIndex) ? paneNode.activeTabIndex : 0;
    paneEl.querySelectorAll('.gb-tab').forEach((el, idx) => {
      el.classList.toggle('active', idx === activeIndex);
    });
    if (typeof GBPaneBridge?.refreshPaneAfterTabSwitch === 'function') {
      GBPaneBridge.refreshPaneAfterTabSwitch(paneNode.id, { dockPopup: true });
    } else if (typeof GBPaneBridge?.mountAllPanes === 'function') {
      GBPaneBridge.mountAllPanes();
    }
    if (typeof replaceIcons === 'function') replaceIcons();
  }

  function _bindPopupTabActivation(popup, paneNode) {
    if (!popup || !paneNode) return;
    popup.addEventListener('click', (e) => {
      const tabEl = e.target?.closest?.('.gb-tab[data-tab-id]');
      if (!tabEl || !popup.contains(tabEl)) return;
      e.preventDefault();
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      const tabId = tabEl.dataset.tabId || '';
      const tabIdx = (paneNode.tabs || []).findIndex((t) => t?.id === tabId);
      if (tabIdx < 0) return;
      paneNode.activeTabIndex = tabIdx;
      const tab = paneNode.tabs[tabIdx];
      const titleEl = popup.querySelector('.gb-dock-popup-title');
      if (titleEl) titleEl.textContent = tab?.label || '';
      if (_state && _state.paneId === paneNode.id) {
        _state.tabId = tab?.id || '';
        _state.tabType = tab?.type || '';
        _state.tabIdx = tabIdx;
      }
      _syncPopupPaneDom(_state?.paneEl || _findPaneElement(paneNode.id), paneNode);
    }, true);
  }

  function _markPopupInternalInteraction() {
    _suppressOutsidePointerUntil = Date.now() + 1500;
  }

  function _markNativeControlInteraction() {
    _markPopupInternalInteraction();
  }

  function _isNativePopupControl(el) {
    return !!el?.closest?.('select');
  }

  function _isPopupOwnedFloatingElement(el) {
    if (!el?.closest) return false;
    try {
      return POPUP_OWNED_FLOATING_SELECTORS.some(selector => !!el.closest(selector));
    } catch {
      return false;
    }
  }

  function _bindNativeControlGuard(popup) {
    if (!popup) return;
    popup.addEventListener('pointerdown', (event) => {
      if (_isNativePopupControl(event.target)) _markNativeControlInteraction();
    }, true);
    popup.addEventListener('mousedown', (event) => {
      if (_isNativePopupControl(event.target)) _markNativeControlInteraction();
    }, true);
    popup.addEventListener('focusin', (event) => {
      if (_isNativePopupControl(event.target)) _markNativeControlInteraction();
    }, true);
    popup.addEventListener('change', (event) => {
      if (_isNativePopupControl(event.target)) _markNativeControlInteraction();
    }, true);
  }

  function _shouldKeepPopupForNativeControl() {
    if (!_popup) return false;
    if (Date.now() < _suppressOutsidePointerUntil) return true;
    const active = document.activeElement;
    return !!(active && _popup.contains(active) && _isNativePopupControl(active));
  }

  function _eventStartedInPopup(ev) {
    if (!_popup) return false;
    if (_popup.contains(ev.target)) return true;
    const path = typeof ev.composedPath === 'function' ? ev.composedPath() : [];
    if (Array.isArray(path) && path.includes(_popup)) return true;
    const x = Number(ev.clientX);
    const y = Number(ev.clientY);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
    const rect = _popup.getBoundingClientRect();
    return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
  }

  function activateTabType(tabType, path) {
    if (!_popup || !_state?.paneNode || !tabType) return false;
    const tabs = _state.paneNode.tabs || [];
    const targetPath = path == null ? '' : String(path);
    const idx = tabs.findIndex(tab => tab?.type === tabType && String(tab?.path || '') === targetPath);
    if (idx < 0) return false;
    _state.paneNode.activeTabIndex = idx;
    const tab = tabs[idx];
    const titleEl = _popup.querySelector('.gb-dock-popup-title');
    if (titleEl) titleEl.textContent = tab?.label || '';
    _state.tabId = tab?.id || '';
    _state.tabType = tab?.type || '';
    _state.tabIdx = idx;
    _syncPopupPaneDom(_state.paneEl || _findPaneElement(_state.paneNode.id), _state.paneNode);
    return true;
  }

  function _bindResize(popup, panelsetNode) {
    popup.querySelectorAll('.gb-dock-popup-resize-handle').forEach((h) => {
      h.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const dir = h.dataset.dir || 'se';
        const rect = popup.getBoundingClientRect();
        const z = _dockPopupZoom();
        _resizeState = {
          dir,
          startX: e.clientX,
          startY: e.clientY,
          startW: rect.width / z,
          startH: rect.height / z,
          startLeft: rect.left / z,
          startTop: rect.top / z,
          zoom: z,
          panelsetNode,
        };
        h.setPointerCapture?.(e.pointerId);
        const onMove = (ev) => _onResizeMove(ev, popup);
        const onUp = (ev) => {
          _onResizeEnd(ev, popup, panelsetNode);
          document.removeEventListener('pointermove', onMove);
          document.removeEventListener('pointerup', onUp);
        };
        document.addEventListener('pointermove', onMove);
        document.addEventListener('pointerup', onUp);
      });
    });
  }

  function _onResizeMove(e, popup) {
    if (!_resizeState) return;
    const { dir, startX, startY, startW, startH, startLeft, startTop } = _resizeState;
    const z = _resizeState.zoom || _dockPopupZoom();
    const dx = (e.clientX - startX) / z;
    const dy = (e.clientY - startY) / z;
    let newW = startW, newH = startH, newLeft = startLeft, newTop = startTop;
    if (dir.includes('e')) newW = Math.max(MIN_W, startW + dx);
    if (dir.includes('s')) newH = Math.max(MIN_H, startH + dy);
    if (dir.includes('w')) {
      const w = Math.max(MIN_W, startW - dx);
      newLeft = startLeft + (startW - w);
      newW = w;
    }
    if (dir.includes('n')) {
      const h = Math.max(MIN_H, startH - dy);
      newTop = startTop + (startH - h);
      newH = h;
    }
    _applyPopupRect(popup, { left: newLeft, top: newTop, w: newW, h: newH });
  }

  function _onResizeEnd(e, popup, panelsetNode) {
    if (!_resizeState) return;
    _resizeState = null;
    const rect = popup.getBoundingClientRect();
    const z = _dockPopupZoom();
    const clamped = _applyPopupRect(popup, {
      left: rect.left / z,
      top: rect.top / z,
      w: rect.width / z,
      h: rect.height / z,
    });
    // panelset.popupRect に保存
    if (panelsetNode) {
      panelsetNode.popupRect = { w: Math.round(clamped.w), h: Math.round(clamped.h) };
      if (typeof GBLayout?.saveLayout === 'function') GBLayout.saveLayout();
    }
  }

  function _reclampOnWindowResize(popup) {
    if (!popup) return;
    const rect = popup.getBoundingClientRect();
    const z = _dockPopupZoom();
    _applyPopupRect(popup, {
      left: rect.left / z,
      top: rect.top / z,
      w: rect.width / z,
      h: rect.height / z,
    });
  }

  function openPopup({ panelsetNode, groupId, paneNode, tab, tabIdx, anchorEl }) {
    if (!panelsetNode || !paneNode || !tab) return;
    // 既に同じ対象で開いている場合はトグル（閉じる）
    if (_popup && _state?.paneId === paneNode.id && _state?.tabId === tab.id) {
      closePopup();
      return;
    }
    // 別対象で開いていたら閉じる
    if (_popup) closePopup();

    _setPopupTargetState(panelsetNode, groupId, paneNode, tabIdx);

    // サイズ決定: panelset.popupRect → fallback
    const savedRect = panelsetNode.popupRect;
    const size = (savedRect && savedRect.w >= MIN_W && savedRect.h >= MIN_H)
      ? _clampPopupSize({ w: savedRect.w, h: savedRect.h })
      : _defaultRect(anchorEl, panelsetNode);

    // ポップアップ DOM 作成
    const popup = _buildPopupDom(tab.label || '');
    const body = popup.querySelector('.gb-dock-popup-body');

    // 対象 pane の DOM を移動（参照切断を避けるため元の位置情報を保持）
    let paneEl = _findPaneElement(paneNode.id);
    let originalParent = null, originalNextSibling = null;
    let synthetic = false;
    if (paneEl) {
      originalParent = paneEl.parentNode;
      originalNextSibling = paneEl.nextSibling;
      body.appendChild(paneEl);
    } else if (typeof GBLayout?.renderNode === 'function') {
      paneEl = GBLayout.renderNode(paneNode, 0);
      synthetic = true;
      body.appendChild(paneEl);
    } else {
      // pane DOM が見つからない場合のフォールバック（プレースホルダ表示）
      const placeholder = document.createElement('div');
      placeholder.className = 'gb-dock-popup-placeholder';
      placeholder.style.padding = '16px';
      placeholder.textContent = tab.label ? `パネル: ${tab.label}` : 'パネル';
      body.appendChild(placeholder);
    }

    document.body.appendChild(popup);
    _popup = popup;
    _state = {
      panelsetId: panelsetNode.id,
      groupId: groupId || '',
      paneId: paneNode.id,
      tabId: tab.id || '',
      tabType: tab.type || '',
      tabIdx,
      paneNode,
      paneEl,
      synthetic,
      originalParent,
      originalNextSibling,
    };
    _bindPopupTabActivation(popup, paneNode);
    _bindNativeControlGuard(popup);
    _syncPopupPaneDom(paneEl, paneNode);
    if (_popup !== popup) return;
    _positionPopup(popup, anchorEl, size);
    _bindResize(popup, panelsetNode);

    // 外クリックで閉じる
    _clickListener = (ev) => {
      if (!_popup) return;
      // ポップアップ内または同じアンカー内クリックは無視
      if (_eventStartedInPopup(ev)) return;
      if (_isPopupOwnedFloatingElement(ev.target)) {
        _markPopupInternalInteraction();
        return;
      }
      if (_shouldKeepPopupForNativeControl()) return;
      // ドックバー上のクリックは該当アイコンハンドラが処理するのでここでは無視
      if (ev.target?.closest?.('.gb-dock-bar')) return;
      closePopup();
    };
    // 次マイクロタスクで登録（open 直後の自己クリックを無視）
    setTimeout(() => { if (_clickListener) document.addEventListener('pointerdown', _clickListener, true); }, 0);

    // Escape
    _keyListener = (ev) => {
      if (ev.key === 'Escape' && _popup) closePopup();
    };
    document.addEventListener('keydown', _keyListener, true);

    // ウィンドウリサイズでクランプ
    _resizeWindowListener = () => _reclampOnWindowResize(_popup);
    window.addEventListener('resize', _resizeWindowListener);
  }

  function closePopup() {
    if (!_popup) return;
    const state = _state;
    // pane DOM を元に戻す
    if (state?.paneEl && state.originalParent && !state.synthetic) {
      if (state.originalNextSibling && state.originalNextSibling.parentNode === state.originalParent) {
        state.originalParent.insertBefore(state.paneEl, state.originalNextSibling);
      } else {
        state.originalParent.appendChild(state.paneEl);
      }
    } else if (state?.synthetic && state.paneId && typeof GBLayout?.paneMap === 'object') {
      if (typeof GBPaneBridge?.retractPaneContent === 'function') {
        GBPaneBridge.retractPaneContent(state.paneId);
      }
      delete GBLayout.paneMap[state.paneId];
    }
    _popup.remove();
    _popup = null;
    _state = null;
    if (_clickListener) {
      document.removeEventListener('pointerdown', _clickListener, true);
      _clickListener = null;
    }
    if (_keyListener) {
      document.removeEventListener('keydown', _keyListener, true);
      _keyListener = null;
    }
    if (_resizeWindowListener) {
      window.removeEventListener('resize', _resizeWindowListener);
      _resizeWindowListener = null;
    }
  }

  function getCurrentPopupPaneId() {
    return _state?.paneId || null;
  }

  function getCurrentPopupTarget() {
    if (!_state) return null;
    return {
      panelsetId: _state.panelsetId || '',
      groupId: _state.groupId || '',
      paneId: _state.paneId || '',
      tabId: _state.tabId || '',
      tabType: _state.tabType || '',
      tabIdx: _state.tabIdx,
    };
  }

  window.GBDockPopup = {
    open: openPopup,
    close: closePopup,
    isOpen,
    getCurrentPopupPaneId,
    getCurrentPopupTarget,
    activateTabType,
  };
})();

;

/* === gb-component.js === */
;
/* ==============================
   gb-component.js: ToolComponent基底クラス + コンポーネントレジストリ（v5.0）
   ============================== */

// === ToolComponent 基底クラス ===
class ToolComponent {
  constructor(paneId, tabId) {
    this.paneId = paneId;
    this.tabId = tabId;
    this.el = null;        // ルートDOM要素
    this.state = {};       // ツール固有の状態
    this._mounted = false;
    this._active = false;
    this._displayBeforeDeactivate = null;
  }

  // --- ライフサイクル ---

  /** DOM要素を生成して返す（サブクラスでオーバーライド） */
  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-tool-component';
    return this.el;
  }

  /** containerにDOM要素を追加 */
  mount(container) {
    if (!this.el) this.create();
    container.appendChild(this.el);
    this._mounted = true;
  }

  /** タブがアクティブになった時（描画更新等）*/
  activate() {
    this._active = true;
    if (this.el) {
      this.el.style.display = this._displayBeforeDeactivate == null ? '' : this._displayBeforeDeactivate;
      this._displayBeforeDeactivate = null;
    }
  }

  /** タブが非アクティブになった時（リソース解放等）*/
  deactivate() {
    this._active = false;
    if (this.el) {
      if (this.el.style.display !== 'none') this._displayBeforeDeactivate = this.el.style.display;
      this.el.style.display = 'none';
    }
  }

  /** containerからDOM要素を除去 */
  unmount() {
    if (this.el && this.el.parentNode) {
      this.el.parentNode.removeChild(this.el);
    }
    this._mounted = false;
  }

  /** イベントリスナー除去、メモリ解放 */
  destroy() {
    this.unmount();
    this.el = null;
    this.state = {};
    this._displayBeforeDeactivate = null;
  }

  // --- 状態管理 ---

  /** 永続化用の状態を返す */
  getState() {
    return { ...this.state };
  }

  /** 状態を復元する */
  restoreState(savedState) {
    if (savedState) this.state = { ...savedState };
  }

  // --- 詳細パネル連携 ---

  /** アクティブ時に詳細ペインに表示する内容を返す（HTMLまたはDOM要素） */
  getDetailContent() {
    return null;
  }

  // --- キーボードショートカット ---

  /** キーイベントハンドラ（trueを返すと伝搬停止）*/
  handleKeyDown(e) {
    return false;
  }
}

// === LegacyWrapperComponent ===
// 既存のDOM要素をペインコンテンツとしてラップするコンポーネント
// Phase B移行期に使用し、各ツールのコンポーネント化完了後に除去
class LegacyWrapperComponent extends ToolComponent {
  constructor(paneId, tabId, legacyEl) {
    super(paneId, tabId);
    this._legacyEl = legacyEl; // ラップ対象のDOM要素
    this._legacyDisplayBeforeDeactivate = null;
  }

  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-tool-legacy-wrapper';
    this.el.style.cssText = 'display:flex;flex-direction:column;flex:1;overflow:hidden;';
    if (this._legacyEl) {
      this.el.appendChild(this._legacyEl);
    }
    return this.el;
  }

  activate() {
    super.activate();
    if (this._legacyEl) {
      this._legacyEl.style.display = this._legacyDisplayBeforeDeactivate == null ? '' : this._legacyDisplayBeforeDeactivate;
      this._legacyDisplayBeforeDeactivate = null;
    }
  }

  deactivate() {
    super.deactivate();
    if (this._legacyEl) {
      if (this._legacyEl.style.display !== 'none') this._legacyDisplayBeforeDeactivate = this._legacyEl.style.display;
      this._legacyEl.style.display = 'none';
    }
  }

  destroy() {
    // レガシー要素は破棄しない（元の位置に戻す可能性）
    if (this._legacyEl && this._legacyEl.parentNode === this.el) {
      this.el.removeChild(this._legacyEl);
    }
    super.destroy();
  }
}

// === コンポーネントレジストリ ===
const TOOL_REGISTRY = {};

// レジストリにコンポーネントクラスを登録
function registerToolComponent(type, config) {
  TOOL_REGISTRY[type] = {
    cls: config.cls,
    icon: config.icon || 'page',
    label: config.label || type,
    multi: config.multi !== false, // デフォルトtrue
    // Audit-P2 H-7: 表示状態の固定（view_lock）が必要なツールか
    requiresViewLock: !!config.requiresViewLock,
  };
}

// ViewLock 判定用ヘルパー（gb-view-lock.js から呼び出せるようグローバル公開）
function getToolRequiresViewLock(type) {
  return !!(TOOL_REGISTRY[type] && TOOL_REGISTRY[type].requiresViewLock);
}

// タイプからコンポーネントインスタンスを生成
function createToolComponent(type, paneId, tabId, options) {
  const reg = TOOL_REGISTRY[type];
  if (reg && reg.cls) {
    return new reg.cls(paneId, tabId, options);
  }
  // レジストリに未登録の場合はレガシーラッパーを返す
  return null;
}

// === コンポーネントインスタンス管理 ===
const _componentInstances = {}; // tabId → ToolComponent instance

function getComponentInstance(tabId) {
  return _componentInstances[tabId] || null;
}

function setComponentInstance(tabId, instance) {
  _componentInstances[tabId] = instance;
}

function removeComponentInstance(tabId) {
  const inst = _componentInstances[tabId];
  if (inst) {
    inst.destroy();
    delete _componentInstances[tabId];
  }
}

// 全インスタンスを走査
function forEachComponent(fn) {
  for (const tabId in _componentInstances) {
    fn(_componentInstances[tabId], tabId);
  }
}

;

/* === gb-tool-components.js === */
;
/* ==============================
   gb-tool-components.js: 全ToolComponentアダプター（v5.0 Phase B）

   各コンポーネントは既存モジュールの関数を呼び出す薄いアダプター。
   Phase C以降で段階的に内部ロジックを移行する。
   ============================== */

function _paneStateRead(key, fallbackValue) {
  if (typeof GBPaneState !== 'undefined' && typeof GBPaneState.read === 'function') {
    return GBPaneState.read(null, key, fallbackValue);
  }
  return fallbackValue;
}

function _renderLegacyToolRedirect(container, toolType, label, hint) {
  const safeToolType = esc(String(toolType || 'tool'));
  const safeLabel = esc(String(label || ''));
  const safeHint = esc(String(hint || ''));
  container.innerHTML = `<div class="gb-empty-state gb-tool-legacy-redirect" data-gb-legacy-tool-type="${safeToolType}">
    <div class="gb-empty-message">${safeLabel}</div>
    <div class="gb-empty-hint">${safeHint}</div>
    <button type="button" class="gb-btn gb-btn-primary" data-action="focus-legacy-tool" data-e2e-id="${safeToolType}-legacy-tool-focus" aria-label="${safeLabel}の既存ペインを表示">既存ペインを表示</button>
  </div>`;
  container.querySelector('[data-action="focus-legacy-tool"]')?.addEventListener('click', () => {
    const existing = (typeof GBTabs !== 'undefined' && typeof GBTabs.findPaneWithTab === 'function')
      ? GBTabs.findPaneWithTab(toolType, '')
      : null;
    if (existing && typeof GBTabs.activateTab === 'function') {
      GBTabs.activateTab(existing.paneId, existing.tabId);
    } else if (typeof showStatus === 'function') {
      showStatus(`${label}の既存ペインが見つかりません`, true);
    }
  });
}

// === OutlinerComponent ===
class OutlinerComponent extends ToolComponent {
  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-tool-outliner';
    this.el.style.cssText = 'display:flex;flex-direction:column;flex:1;overflow:hidden;';
    _renderLegacyToolRedirect(this.el, 'outliner', 'フォルダツリー', '固定IDを持つ既存ツリーを複製せず、既存ペインを再利用します。');
    return this.el;
  }

  activate() {
    super.activate();
    if (typeof loadOutliner === 'function') loadOutliner();
  }

  getDetailContent() { return null; }
}

// === DatabaseComponent ===
class DatabaseComponent extends ToolComponent {
  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-tool-database';
    this.el.style.cssText = 'display:flex;flex-direction:column;flex:1;overflow:hidden;';
    return this.el;
  }

  activate() {
    super.activate();
    if (this.state.dbPath && typeof selectDatabase === 'function') {
      selectDatabase(this.state.dbPath);
    }
  }

  restoreState(s) {
    super.restoreState(s);
    if (s && s.dbPath) this.state.dbPath = s.dbPath;
  }

  getState() {
    return { dbPath: this.state.dbPath || _paneStateRead('dbPath', '') };
  }

  getDetailContent() {
    // アクティブエントリの情報を返す
    const entityPath = _paneStateRead('entityPath', '');
    if (entityPath) {
      return { type: 'entity', path: entityPath };
    }
    return null;
  }
}

