/* === gb-board-dirty.js === */
;
/* gb-board-dirty.js: differential board update scheduler */

const BD_DIRTY_FULL_RENDER_NODE_RATIO = 0.30;
const BD_DIRTY_FULL_DRAW_CONN_RATIO = 0.30;

let _bdDirtyUpdateTimer = 0;
let _bdDirtyUpdateRaf = 0;
let _bdDirtyState = bdCreateEmptyDirtyState();

// DOM 上に .bd-selected を付与済みのノード ID を記録し、差分で class を付け外しする。
// v0.5.318: querySelectorAll('.bd-node').forEach(...) で全ノード走査していた箇所の置換用。
const _bdAppliedSelection = new Set();

function _bdSelectionIdFromNodeElement(el) {
  const raw = el?.dataset?.nodeId || el?.id || '';
  return String(raw).replace(/^bdn-/, '');
}

function bdApplySelectionDomClass() {
  if (typeof bd === 'undefined' || !bd) return;
  const next = new Set([...(bd.selected instanceof Set ? bd.selected : new Set())].map(id => String(id)));
  document.querySelectorAll('.bd-node.bd-selected').forEach(el => {
    const id = _bdSelectionIdFromNodeElement(el);
    if (!next.has(id)) el.classList.remove('bd-selected');
  });
  // 1) DOM から外すべきもの（以前付与されていたが now 解除）
  _bdAppliedSelection.forEach(id => {
    if (next.has(id)) return;
    const el = document.getElementById(`bdn-${id}`);
    if (el) el.classList.remove('bd-selected');
  });
  // 2) DOM へ付けるべきもの（新規選択）
  next.forEach(id => {
    if (_bdAppliedSelection.has(id)) return;
    const el = document.getElementById(`bdn-${id}`);
    if (el) el.classList.add('bd-selected');
  });
  _bdAppliedSelection.clear();
  next.forEach(id => _bdAppliedSelection.add(id));
}

function bdCreateEmptyDirtyState() {
  return {
    dirtyNodeIds: new Set(),
    dirtyMovedNodeIds: new Set(),
    dirtyConnIds: new Set(),
    dirtyConnNodeIds: new Set(),
    dirtySelectionIds: new Set(),
    dirtyCommentNodeIds: new Set(),
    dirtySelection: false,
    dirtyFrames: false,
    dirtyMinimap: false,
    dirtyBoardUi: false,
    dirtyCommentsAll: false,
    dirtyDetailPanel: false,
    needsFullRender: false,
    fullRenderReason: '',
    reasons: new Set(),
  };
}

function bdMarkNodeDirty(nodeId, reason) {
  if (!nodeId) return;
  _bdDirtyState.dirtyNodeIds.add(nodeId);
  _bdDirtyState.dirtySelectionIds.add(nodeId);
  _bdDirtyState.dirtyCommentNodeIds.add(nodeId);
  _bdDirtyState.dirtyFrames = true;
  _bdDirtyState.dirtyMinimap = true;
  bdDirtyRememberReason(reason || 'node');
  bdMarkConnectionsDirtyByNodes([nodeId], reason || 'node');
  bdScheduleBoardUpdates();
}

function bdMarkNodeMoved(nodeId, reason) {
  if (!nodeId) return;
  _bdDirtyState.dirtyMovedNodeIds.add(nodeId);
  _bdDirtyState.dirtySelectionIds.add(nodeId);
  _bdDirtyState.dirtyFrames = true;
  _bdDirtyState.dirtyMinimap = true;
  bdDirtyRememberReason(reason || 'move');
  bdMarkConnectionsDirtyByNodes([nodeId], reason || 'move');
  bdScheduleBoardUpdates();
}

function bdMarkNodesMoved(nodeIds, reason) {
  [...(nodeIds || [])].filter(Boolean).forEach(id => bdMarkNodeMoved(id, reason));
}

function bdMarkConnectionDirty(connId, reason) {
  if (!connId) return;
  _bdDirtyState.dirtyConnIds.add(connId);
  _bdDirtyState.dirtyMinimap = true;
  bdDirtyRememberReason(reason || 'connection');
  bdScheduleBoardUpdates();
}

function bdMarkConnectionsDirtyByNodes(nodeIds, reason) {
  const ids = new Set([...(nodeIds || [])].filter(Boolean));
  if (!ids.size || typeof bd === 'undefined') return;
  if (typeof bdEnsureConnectionRuntime === 'function') bdEnsureConnectionRuntime(bd.connections);
  ids.forEach(id => _bdDirtyState.dirtyConnNodeIds.add(id));
  (bd.connections || []).forEach(conn => {
    if ((ids.has(conn.from) || ids.has(conn.to)) && conn.id) _bdDirtyState.dirtyConnIds.add(conn.id);
  });
  _bdDirtyState.dirtyMinimap = true;
  bdDirtyRememberReason(reason || 'connection-by-node');
  bdScheduleBoardUpdates();
}

function bdMarkSelectionDirty(nodeIds, reason) {
  _bdDirtyState.dirtySelection = true;
  [...(nodeIds || [])].filter(Boolean).forEach(id => _bdDirtyState.dirtySelectionIds.add(id));
  bdDirtyRememberReason(reason || 'selection');
  bdScheduleBoardUpdates();
}

function bdMarkBoardUiDirty(reason) {
  _bdDirtyState.dirtyBoardUi = true;
  bdDirtyRememberReason(reason || 'board-ui');
  bdScheduleBoardUpdates();
}

function bdMarkExtrasDirty(flags = {}, reason) {
  if (flags === true) {
    _bdDirtyState.dirtySelection = true;
    _bdDirtyState.dirtyFrames = true;
    _bdDirtyState.dirtyMinimap = true;
    _bdDirtyState.dirtyBoardUi = true;
    _bdDirtyState.dirtyCommentsAll = true;
  } else {
    if (flags.selection) _bdDirtyState.dirtySelection = true;
    if (flags.frames) _bdDirtyState.dirtyFrames = true;
    if (flags.minimap) _bdDirtyState.dirtyMinimap = true;
    if (flags.boardUi) _bdDirtyState.dirtyBoardUi = true;
    if (flags.detailPanel) _bdDirtyState.dirtyDetailPanel = true;
    if (flags.comments === true) _bdDirtyState.dirtyCommentsAll = true;
    else if (Array.isArray(flags.comments) || flags.comments instanceof Set) {
      [...flags.comments].filter(Boolean).forEach(id => _bdDirtyState.dirtyCommentNodeIds.add(id));
    }
  }
  bdDirtyRememberReason(reason || 'extras');
  bdScheduleBoardUpdates();
}

function bdRequestFullRender(reason) {
  _bdDirtyState.needsFullRender = true;
  _bdDirtyState.fullRenderReason = reason || _bdDirtyState.fullRenderReason || 'unspecified';
  bdDirtyRememberReason('full:' + (_bdDirtyState.fullRenderReason || 'unspecified'));
  bdScheduleBoardUpdates();
}

function bdDirtyRememberReason(reason) {
  if (reason) _bdDirtyState.reasons.add(String(reason));
}

function bdScheduleBoardUpdates(delayMs) {
  const delay = Number.isFinite(+delayMs) ? Math.max(0, +delayMs) : 0;
  clearTimeout(_bdDirtyUpdateTimer);
  if (_bdDirtyUpdateRaf) {
    cancelAnimationFrame(_bdDirtyUpdateRaf);
    _bdDirtyUpdateRaf = 0;
  }
  _bdDirtyUpdateTimer = setTimeout(() => {
    _bdDirtyUpdateTimer = 0;
    _bdDirtyUpdateRaf = requestAnimationFrame(() => {
      _bdDirtyUpdateRaf = 0;
      bdFlushBoardUpdates();
    });
  }, delay);
}

function bdFlushBoardUpdates() {
  if (typeof bdShouldDeferBoardExtras === 'function' && bdShouldDeferBoardExtras()) {
    bdScheduleBoardUpdates(16);
    return;
  }
  const state = _bdDirtyState;
  if (!bdDirtyHasWork(state)) return;
  _bdDirtyState = bdCreateEmptyDirtyState();
  const started = typeof bdPerfStart === 'function' ? bdPerfStart('bdFlushBoardUpdates') : 0;
  if (state.needsFullRender) {
    bdFlushDirtyFullRender(state, started);
    return;
  }
  if (bdDirtyShouldUseFullRender(state)) {
    state.fullRenderReason = state.fullRenderReason || 'dirty-node-threshold';
    bdFlushDirtyFullRender(state, started);
    return;
  }
  const rendered = bdFlushDirtyNodes(state);
  bdFlushDirtyMovedNodes(state, rendered);
  bdFlushDirtySelection(state, rendered);
  bdFlushDirtyConnections(state);
  bdFlushDirtyFrames(state);
  bdFlushDirtyComments(state);
  bdFlushDirtyMinimap(state);
  bdFlushDirtyBoardUi(state);
  if (typeof bdPerfEnd === 'function') {
    bdPerfEnd('bdFlushBoardUpdates', started, bdDirtyMeta(state));
  }
}

function bdDirtyHasWork(state) {
  return state.needsFullRender
    || state.dirtyNodeIds.size
    || state.dirtyMovedNodeIds.size
    || state.dirtyConnIds.size
    || state.dirtyConnNodeIds.size
    || state.dirtySelectionIds.size
    || state.dirtyCommentNodeIds.size
    || state.dirtySelection
    || state.dirtyFrames
    || state.dirtyMinimap
    || state.dirtyBoardUi
    || state.dirtyCommentsAll
    || state.dirtyDetailPanel;
}

function bdDirtyShouldUseFullRender(state) {
  const total = (typeof bd !== 'undefined' && bd?.nodes) ? bd.nodes.length : 0;
  if (!total) return false;
  return state.dirtyNodeIds.size > Math.max(40, Math.ceil(total * BD_DIRTY_FULL_RENDER_NODE_RATIO));
}

function bdFlushDirtyFullRender(state, started) {
  const reason = state.fullRenderReason || [...state.reasons][0] || 'dirty-fallback';
  if (typeof bdPerfEnd === 'function') bdPerfEnd('bdFlushBoardUpdates', started, 'full-render reason=' + reason);
  const renderStarted = typeof bdPerfStart === 'function' ? bdPerfStart('bdRequestFullRender:' + reason) : 0;
  if (typeof bdRender === 'function') bdRender();
  if (typeof bdPerfEnd === 'function') bdPerfEnd('bdRequestFullRender:' + reason, renderStarted);
}

function bdFlushDirtyNodes(state) {
  const rendered = new Set();
  if (!state.dirtyNodeIds.size) return rendered;
  const ctx = typeof bdCreateRenderContext === 'function' ? bdCreateRenderContext() : null;
  for (const nodeId of state.dirtyNodeIds) {
    const ok = typeof bdReplaceNodeElement === 'function'
      ? bdReplaceNodeElement(nodeId, { renderContext: ctx })
      : false;
    if (!ok) {
      state.needsFullRender = true;
      state.fullRenderReason = 'node-replace-fallback:' + nodeId;
      bdRequestFullRender(state.fullRenderReason);
      continue;
    }
    rendered.add(nodeId);
  }
  return rendered;
}

function bdFlushDirtyMovedNodes(state, rendered) {
  state.dirtyMovedNodeIds.forEach(nodeId => {
    if (rendered.has(nodeId)) return;
    if (typeof bdUpdateNodePosition === 'function') bdUpdateNodePosition(nodeId);
  });
}

function bdFlushDirtySelection(state, rendered) {
  const ids = new Set([...state.dirtySelectionIds, ...rendered]);
  if (state.dirtySelection && bd?.selected) bd.selected.forEach(id => ids.add(id));
  if (!ids.size && !state.dirtySelection) return;
  bdApplySelectionDomClass();
  if (typeof bdRemoveSelectionUiForMissingNodes === 'function') bdRemoveSelectionUiForMissingNodes();
  ids.forEach(id => {
    if (typeof bdSyncResizeHandleForNode === 'function') bdSyncResizeHandleForNode(id);
    else if (typeof bdSyncSelectionRectForNode === 'function') bdSyncSelectionRectForNode(id);
  });
  const layer = document.getElementById('bd-resize-layer');
  if (layer && typeof _bdSyncGroupAnchors === 'function') _bdSyncGroupAnchors(layer);
}

function bdFlushDirtyConnections(state) {
  const connCount = (typeof bd !== 'undefined' && bd?.connections) ? bd.connections.length : 0;
  const connIds = new Set(state.dirtyConnIds);
  if (connIds.size && connCount && connIds.size > Math.max(50, Math.ceil(connCount * BD_DIRTY_FULL_DRAW_CONN_RATIO))) {
    if (typeof bdDrawConns === 'function') bdDrawConns({ reason: 'dirty-conn-threshold' });
    return;
  }
  if (connIds.size && typeof bdDrawConns === 'function') {
    bdDrawConns({ connIds: [...connIds], reason: 'dirty' });
    return;
  }
  if (state.dirtyConnNodeIds.size && typeof bdDrawConns === 'function') {
    bdDrawConns({ nodeIds: [...state.dirtyConnNodeIds], reason: 'dirty-nodes' });
  }
}

function bdFlushDirtyFrames(state) {
  if (state.dirtyFrames && typeof bdDrawFrames === 'function') bdDrawFrames();
}

function bdFlushDirtyComments(state) {
  const container = document.getElementById('bd-nodes');
  if (typeof CommentBadges === 'undefined' || !bd?.path || !container) return;
  if (state.dirtyCommentsAll) {
    try { CommentBadges.refreshBoard(bd.path, container); } catch {}
    return;
  }
  if (!state.dirtyCommentNodeIds.size) return;
  try {
    CommentBadges.refreshBoard(bd.path, container, { cardIds: [...state.dirtyCommentNodeIds] });
  } catch {}
}

function bdFlushDirtyMinimap(dirtyState) {
  if (!dirtyState.dirtyMinimap || typeof bdUpdateMinimap !== 'function') return;
  const pane = document.getElementById('gb-preview-pane');
  if (!pane || (typeof state !== 'undefined' && state.view !== 'board')) return;
  if (typeof bdShouldRenderMinimapInPreviewPane === 'function' && !bdShouldRenderMinimapInPreviewPane(pane)) return;
  // ノード/接続/スタイル更新系の dirty はキャッシュも無効化 (bdTransform からの pure transform 呼び出しと区別する)
  if (typeof bdInvalidateMinimapCache === 'function') bdInvalidateMinimapCache();
  bdUpdateMinimap();
}

function bdFlushDirtyBoardUi(state) {
  if (!state.dirtyBoardUi && !state.dirtyDetailPanel) return;
  if (typeof bdSyncBoardUi === 'function') bdSyncBoardUi(false);
}

function bdDirtyMeta(state) {
  const reasons = [...state.reasons].slice(0, 5).join(',');
  return `nodes=${state.dirtyNodeIds.size} moved=${state.dirtyMovedNodeIds.size} conns=${state.dirtyConnIds.size} selection=${state.dirtySelectionIds.size} reasons=${reasons}`;
}

;

/* === gb-board-background.js === */
;
/* gb-board-background.js: board canvas background image/color controls */

const BD_BG_IMAGE_STYLE_KEY = '--bd-bg-image';
const BD_BG_IMAGE_FIT_STYLE_KEY = '--bd-bg-image-fit';
const BD_BG_IMAGE_SCALE_STYLE_KEY = '--bd-bg-image-scale';
const BD_DEFAULT_FONT_STYLE_KEY = '--bd-default-font-family';

function _bdNormalizeBackgroundFit(value) {
  const next = String(value || '').trim();
  // 'world' はボード要素と一緒にパン/ズーム/回転されるモード (bd-world 内に配置)
  return ['contain', 'cover', 'auto', 'repeat', 'world'].includes(next) ? next : 'contain';
}

function _bdNormalizeBackgroundScale(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return 1;
  return Math.max(0.05, Math.min(20, n));
}

function _bdEnsureFileStyle() {
  if (!bd._fileStyle || typeof bd._fileStyle !== 'object' || Array.isArray(bd._fileStyle)) {
    bd._fileStyle = {};
  }
  return bd._fileStyle;
}

function bdLoadBoardBackgroundFromStyle() {
  const style = bd._fileStyle && typeof bd._fileStyle === 'object' ? bd._fileStyle : {};
  if (Object.prototype.hasOwnProperty.call(style, '--bd-bg')) {
    bd._bgColor = String(style['--bd-bg'] || '').trim();
  }
  bd._bgImage = String(style[BD_BG_IMAGE_STYLE_KEY] || '').trim();
  bd._bgImageFit = bd._bgImage ? _bdNormalizeBackgroundFit(style[BD_BG_IMAGE_FIT_STYLE_KEY]) : '';
  bd._bgImageScale = bd._bgImage && Object.prototype.hasOwnProperty.call(style, BD_BG_IMAGE_SCALE_STYLE_KEY)
    ? _bdNormalizeBackgroundScale(style[BD_BG_IMAGE_SCALE_STYLE_KEY])
    : (bd._bgImage ? 1 : '');
}

function bdApplyBoardFontVariables(canvasEl, worldEl) {
  if (typeof bd === 'undefined') return;
  const style = bd._fileStyle && typeof bd._fileStyle === 'object' ? bd._fileStyle : {};
  const raw = style[BD_DEFAULT_FONT_STYLE_KEY];
  const fontFamily = typeof normalizeFontFamilyValue === 'function'
    ? normalizeFontFamilyValue(raw)
    : String(raw || '').trim();
  const canvas = canvasEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : null)
    || document.getElementById('bd-canvas');
  const world = worldEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('world') : null)
    || document.getElementById('bd-world');
  [canvas, world].forEach(el => {
    if (!el) return;
    if (fontFamily) el.style.setProperty(BD_DEFAULT_FONT_STYLE_KEY, fontFamily);
    else el.style.removeProperty(BD_DEFAULT_FONT_STYLE_KEY);
  });
}

function _bdBackgroundCssUrl(value) {
  const url = String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return url ? `url("${url}")` : '';
}

function _bdBackgroundDisplayUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return window.MeldexPwaFileUrl?.displayUrl?.(raw)
    || window.MeldexResourceUrl?.rewriteInternalUrl?.(raw)
    || raw;
}

function _bdResolveBackgroundDisplayUrl(value) {
  const raw = String(value || '').trim();
  if (!raw || !window.MeldexPwaFileUrl?.ensureDisplayUrl) return Promise.resolve(_bdBackgroundDisplayUrl(raw));
  return window.MeldexPwaFileUrl.ensureDisplayUrl(raw, { allowLargeBlob: true })
    .then(info => info?.url || _bdBackgroundDisplayUrl(raw))
    .catch(() => _bdBackgroundDisplayUrl(raw));
}

function _bdSetCanvasBackgroundImage(canvas, imageUrl) {
  if (!canvas) return;
  const raw = String(imageUrl || '').trim();
  if (!raw) {
    delete canvas.dataset.bdBgImageSource;
    canvas.style.backgroundImage = '';
    return;
  }
  canvas.dataset.bdBgImageSource = raw;
  canvas.style.backgroundImage = _bdBackgroundCssUrl(_bdBackgroundDisplayUrl(raw));
  _bdResolveBackgroundDisplayUrl(raw).then(url => {
    if (!canvas.isConnected || canvas.dataset.bdBgImageSource !== raw || !url) return;
    canvas.style.backgroundImage = _bdBackgroundCssUrl(url);
  });
}

function _bdBackgroundImageName() {
  const raw = String(bd._bgImage || '');
  if (!raw) return '';
  const match = raw.match(/[?&]path=([^&]+)/);
  let decoded = match ? match[1] : raw;
  try { decoded = decodeURIComponent(decoded); } catch {}
  return decoded.split(/[\\/]/).pop() || decoded;
}

function _bdCanvasCssVar(canvas, key) {
  const inline = canvas?.style?.getPropertyValue?.(key)?.trim?.() || '';
  if (inline) return inline;
  try {
    return getComputedStyle(canvas).getPropertyValue(key).trim();
  } catch {
    return '';
  }
}

function _bdBoardThemeCssVar(canvas, key) {
  return _bdCanvasCssVar(canvas, key)
    || (typeof getCssVar === 'function' ? (getCssVar(key) || '').trim() : '');
}

function _bdClearCanvasBackgroundFileStyleVars(canvasEl) {
  const canvas = canvasEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : null)
    || document.getElementById('bd-canvas');
  if (!canvas) return;
  [BD_BG_IMAGE_STYLE_KEY, BD_BG_IMAGE_FIT_STYLE_KEY, BD_BG_IMAGE_SCALE_STYLE_KEY].forEach(key => {
    canvas.style.removeProperty(key);
  });
}

function _bdRefreshBoardBackgroundThemeRuntime(canvasEl) {
  if (typeof MeldexThemeManager === 'undefined' || typeof MeldexThemeManager.applyBoardThemeRuntime !== 'function') {
    return false;
  }
  const canvas = canvasEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : null)
    || document.getElementById('bd-canvas');
  const world = (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('world') : null)
    || document.getElementById('bd-world');
  MeldexThemeManager.applyBoardThemeRuntime(bd, canvas, world);
  return true;
}

function _bdApplyWorldBackgroundImage(imageUrl, scale) {
  const world = (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('world') : null)
    || document.getElementById('bd-world');
  if (!world) return;
  let layer = world.querySelector(':scope > .bd-bg-world-image');
  if (!imageUrl) {
    if (layer) layer.remove();
    return;
  }
  if (!layer) {
    layer = document.createElement('div');
    layer.className = 'bd-bg-world-image';
    layer.style.cssText = 'position:absolute;left:0;top:0;transform-origin:0 0;pointer-events:none;z-index:-1;';
    // 画像の自然サイズで配置し、bd-world の transform(パン/ズーム/回転) に追従させる
    const img = document.createElement('img');
    img.draggable = false;
    img.style.cssText = 'display:block;user-select:none;pointer-events:none;';
    layer.appendChild(img);
    world.insertBefore(layer, world.firstChild);
  }
  layer.dataset.bdBgImageSource = imageUrl;
  const imgEl = layer.querySelector('img');
  const displayUrl = _bdBackgroundDisplayUrl(imageUrl);
  if (imgEl && imgEl.src !== displayUrl) imgEl.src = displayUrl;
  _bdResolveBackgroundDisplayUrl(imageUrl).then(url => {
    if (!layer.isConnected || layer.dataset.bdBgImageSource !== imageUrl || !imgEl || !url) return;
    if (imgEl.src !== url) imgEl.src = url;
  });
  const s = _bdNormalizeBackgroundScale(scale);
  layer.style.transform = `scale(${s})`;
}

function _bdRemoveWorldBackgroundImage() {
  const world = (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('world') : null)
    || document.getElementById('bd-world');
  if (!world) return;
  const layer = world.querySelector(':scope > .bd-bg-world-image');
  if (layer) layer.remove();
}

function bdApplyCanvasBackground(canvasEl, fallbackColor) {
  const canvas = canvasEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : null)
    || document.getElementById('bd-canvas');
  if (!canvas) return;

  const fileStyle = bd?._fileStyle && typeof bd._fileStyle === 'object' ? bd._fileStyle : {};
  const fileStyleBg = String(fileStyle['--bd-bg'] || '').trim();
  const resolvedFallback = fileStyleBg || ((fallbackColor === undefined || fallbackColor === null || fallbackColor === '')
    ? _bdBoardThemeBackgroundColor()
    : fallbackColor);
  const color = bd._bgColor || resolvedFallback || '';
  canvas.style.backgroundColor = color || 'var(--bg)';

  // ファイル固有値が未設定のときはボード専用テーマ値、なければ :root 値を参照
  const fileBgImage = String(bd._bgImage || fileStyle[BD_BG_IMAGE_STYLE_KEY] || '').trim();
  const hasFileBgImage = !!fileBgImage;
  const themeBgImage = hasFileBgImage ? '' : _bdBoardThemeCssVar(canvas, BD_BG_IMAGE_STYLE_KEY);
  const themeBgFit = hasFileBgImage ? '' : _bdBoardThemeCssVar(canvas, BD_BG_IMAGE_FIT_STYLE_KEY);
  const themeBgScale = hasFileBgImage ? '' : _bdBoardThemeCssVar(canvas, BD_BG_IMAGE_SCALE_STYLE_KEY);
  const rawImage = fileBgImage || themeBgImage;
  const image = rawImage;
  const fileFit = hasFileBgImage ? (bd._bgImageFit || fileStyle[BD_BG_IMAGE_FIT_STYLE_KEY]) : '';
  const fit = _bdNormalizeBackgroundFit(fileFit || themeBgFit);
  const fileScale = hasFileBgImage
    ? (bd._bgImageScale !== undefined && bd._bgImageScale !== null && bd._bgImageScale !== ''
      ? bd._bgImageScale
      : fileStyle[BD_BG_IMAGE_SCALE_STYLE_KEY])
    : '';
  const scale = _bdNormalizeBackgroundScale(
    hasFileBgImage ? fileScale : themeBgScale
  );
  if (image && fit === 'world') {
    // ボード要素と一緒にパン/ズーム/回転する: bd-canvas の background-image は使わず、
    // bd-world の子要素として img を配置する (transform が連動する)。
    _bdSetCanvasBackgroundImage(canvas, '');
    canvas.style.backgroundPosition = '';
    canvas.style.backgroundRepeat = '';
    canvas.style.backgroundSize = '';
    _bdApplyWorldBackgroundImage(image, scale);
  } else if (image) {
    _bdSetCanvasBackgroundImage(canvas, image);
    canvas.style.backgroundPosition = 'center center';
    canvas.style.backgroundRepeat = fit === 'repeat' ? 'repeat' : 'no-repeat';
    canvas.style.backgroundSize = fit === 'repeat' ? 'auto' : fit;
    _bdRemoveWorldBackgroundImage();
  } else {
    _bdSetCanvasBackgroundImage(canvas, '');
    canvas.style.backgroundPosition = '';
    canvas.style.backgroundRepeat = '';
    canvas.style.backgroundSize = '';
    _bdRemoveWorldBackgroundImage();
  }

  const swatch = document.getElementById('bd-bg-swatch');
  if (swatch && typeof setColorSwatchValue === 'function') setColorSwatchValue(swatch, color || '');
  document.querySelectorAll('[data-bd-action="bg-image"]').forEach(btn => {
    btn.classList.toggle('active', !!image);
    btn.title = image ? `背景画像: ${_bdBackgroundImageName()}` : '背景画像';
  });
}

function _bdBoardThemeBackgroundColor() {
  const fileStyleBg = bd?._fileStyle && typeof bd._fileStyle === 'object'
    ? String(bd._fileStyle['--bd-bg'] || '').trim()
    : '';
  if (fileStyleBg) return fileStyleBg;
  if (!String(bd?.themeId || '').trim()) {
    const documentBg = typeof getCssVar === 'function' ? (getCssVar('--bd-bg') || '').trim() : '';
    if (documentBg) return documentBg;
  }
  if (typeof MeldexThemeManager === 'undefined' || typeof MeldexThemeManager.getActiveBoardTheme !== 'function') {
    return '';
  }
  const themeDef = MeldexThemeManager.getActiveBoardTheme(bd);
  return themeDef?.ui?.cssVars?.['--bd-bg'] || themeDef?.board?.backgroundColor || '';
}

function bdApplyBoardFileStyleAndTheme(canvasEl, worldEl) {
  const canvas = canvasEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : null)
    || document.getElementById('bd-canvas');
  const world = worldEl
    || (typeof bdGetBoardElement === 'function' ? bdGetBoardElement('world') : null)
    || document.getElementById('bd-world');
  if (typeof applyFileStyleToPanel === 'function') {
    applyFileStyleToPanel(bd._fileStyle || {}, 'bd-canvas');
  }
  if (typeof MeldexThemeManager !== 'undefined' && typeof MeldexThemeManager.applyBoardThemeRuntime === 'function') {
    MeldexThemeManager.applyBoardThemeRuntime(bd, canvas, world);
  }
  if (typeof bdApplyBoardFontVariables === 'function') {
    bdApplyBoardFontVariables(canvas, world);
  }
  bdApplyCanvasBackground(canvas);
}

function _bdApplyCurrentBoardBackground() {
  bdApplyCanvasBackground(null, _bdBoardThemeBackgroundColor());
}

function bdPickBoardBackgroundColor(anchorEl) {
  if (typeof openColorPalette !== 'function') return;
  openColorPalette(anchorEl, bd._bgColor || '', color => {
    bdSetBoardBackgroundColor(color || '');
  });
}

function bdSetBoardBackgroundColor(color) {
  if (typeof bdPushUndo === 'function') bdPushUndo();
  bd._bgColor = color || '';
  const style = _bdEnsureFileStyle();
  if (bd._bgColor) style['--bd-bg'] = bd._bgColor;
  else delete style['--bd-bg'];
  _bdApplyCurrentBoardBackground();
  if (typeof bdDirty === 'function') bdDirty();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  if (typeof bdMarkExtrasDirty === 'function') {
    bdMarkExtrasDirty({ minimap: true, boardUi: true }, 'bg-color');
    if (typeof bdScheduleBoardUpdates === 'function') bdScheduleBoardUpdates();
  }
}

function _bdBoardUploadDir() {
  const path = String(bd.path || '');
  const idx = path.lastIndexOf('/');
  return idx >= 0 ? path.substring(0, idx) : '';
}

function _bdReadFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = event => resolve(event.target.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

function _bdIsImageFile(file) {
  if (!file) return false;
  if (String(file.type || '').startsWith('image/')) return true;
  return /\.(png|jpe?g|gif|webp|bmp|svg|avif|ico)$/i.test(file.name || '');
}

async function _bdUploadBoardBackgroundImage(data, file) {
  const res = await apiFetch('/upload-file?path=' + encodeURIComponent(_bdBoardUploadDir()), {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({ data, filename: file.name || 'background.png' }),
  });
  if (!res?.ok || !res.path) throw new Error('upload failed');
  return API_BASE + '/file-raw?path=' + encodeURIComponent(res.path);
}

async function bdSetBoardBackgroundImageFromFile(file) {
  if (!_bdIsImageFile(file)) {
    if (typeof showStatus === 'function') showStatus('画像ファイルを選択してください', true);
    return false;
  }
  if (!bd.path) {
    if (typeof showStatus === 'function') showStatus('ボードを保存してから背景画像を設定してください', true);
    return false;
  }
  try {
    const data = await _bdReadFileAsDataUrl(file);
    // 2026-08-01: proprietary-format-sidecar-cleanup-plan-2026-07-31.md §5.1 により、
    // 背景画像は既定で .mel-board 本体へ埋め込む（アップロードによる隣接ファイル作成はしない）。
    // サイズが大きい場合だけ、埋め込み/リンクをユーザーに確認する。
    const choice = typeof bdResolveImageEmbedChoice === 'function'
      ? await bdResolveImageEmbedChoice(file.size, file.name)
      : 'embed';
    const imageUrl = choice === 'link'
      ? await _bdUploadBoardBackgroundImage(data, file)
      : data;
    bdSetBoardBackgroundImage(imageUrl, bd._bgImageFit || 'contain');
    if (typeof showStatus === 'function') showStatus('背景画像を設定しました');
    return true;
  } catch (err) {
    if (typeof showStatus === 'function') showStatus('背景画像の設定に失敗しました', true);
    return false;
  }
}

function bdChooseBoardBackgroundImage() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.addEventListener('change', () => {
    const file = input.files && input.files[0];
    if (file) bdSetBoardBackgroundImageFromFile(file);
    input.remove();
  });
  input.style.display = 'none';
  document.body.appendChild(input);
  input.click();
}

function bdSetBoardBackgroundImage(url, fit, scale) {
  if (typeof bdPushUndo === 'function') bdPushUndo();
  bd._bgImage = String(url || '').trim();
  bd._bgImageFit = _bdNormalizeBackgroundFit(fit || bd._bgImageFit);
  bd._bgImageScale = _bdNormalizeBackgroundScale(scale !== undefined ? scale : bd._bgImageScale);
  const style = _bdEnsureFileStyle();
  if (bd._bgImage) {
    style[BD_BG_IMAGE_STYLE_KEY] = bd._bgImage;
    style[BD_BG_IMAGE_FIT_STYLE_KEY] = bd._bgImageFit;
    if (bd._bgImageFit === 'world' && bd._bgImageScale !== 1) {
      style[BD_BG_IMAGE_SCALE_STYLE_KEY] = String(bd._bgImageScale);
    } else {
      delete style[BD_BG_IMAGE_SCALE_STYLE_KEY];
    }
  } else {
    delete style[BD_BG_IMAGE_STYLE_KEY];
    delete style[BD_BG_IMAGE_FIT_STYLE_KEY];
    delete style[BD_BG_IMAGE_SCALE_STYLE_KEY];
    _bdClearCanvasBackgroundFileStyleVars();
  }
  const refreshedTheme = !bd._bgImage && _bdRefreshBoardBackgroundThemeRuntime();
  if (!refreshedTheme) _bdApplyCurrentBoardBackground();
  if (typeof bdDirty === 'function') bdDirty();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  if (typeof bdMarkExtrasDirty === 'function') {
    bdMarkExtrasDirty({ minimap: true, boardUi: true }, 'bg-image');
    if (typeof bdScheduleBoardUpdates === 'function') bdScheduleBoardUpdates();
  }
}

function bdSetBoardBackgroundImageFit(fit) {
  bdSetBoardBackgroundImage(bd._bgImage || '', fit, bd._bgImageScale);
}

function bdSetBoardBackgroundImageScale(scale) {
  bdSetBoardBackgroundImage(bd._bgImage || '', bd._bgImageFit || 'contain', scale);
}

function bdClearBoardBackgroundImage() {
  bdSetBoardBackgroundImage('', 'contain', 1);
}

function bdClearBoardBackground() {
  if (typeof bdPushUndo === 'function') bdPushUndo();
  bd._bgColor = '';
  bd._bgImage = '';
  bd._bgImageFit = 'contain';
  bd._bgImageScale = 1;
  const style = _bdEnsureFileStyle();
  delete style['--bd-bg'];
  delete style[BD_BG_IMAGE_STYLE_KEY];
  delete style[BD_BG_IMAGE_FIT_STYLE_KEY];
  delete style[BD_BG_IMAGE_SCALE_STYLE_KEY];
  _bdClearCanvasBackgroundFileStyleVars();
  if (!_bdRefreshBoardBackgroundThemeRuntime()) _bdApplyCurrentBoardBackground();
  if (typeof bdDirty === 'function') bdDirty();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  if (typeof bdMarkExtrasDirty === 'function') {
    bdMarkExtrasDirty({ minimap: true, boardUi: true }, 'bg-clear');
    if (typeof bdScheduleBoardUpdates === 'function') bdScheduleBoardUpdates();
  }
}

document.addEventListener('click', event => {
  const btn = event.target?.closest?.('[data-bd-action]');
  if (!btn || !btn.closest?.('.gb-canvas-root')) return;
  if (btn.dataset.bdAction === 'bg-image') {
    event.preventDefault();
    bdChooseBoardBackgroundImage();
  } else if (btn.dataset.bdAction === 'bg-clear') {
    event.preventDefault();
    bdClearBoardBackground();
  }
});

if (typeof bdRefreshBoardToolbar === 'function') {
  const _bdRefreshBoardToolbarBase = bdRefreshBoardToolbar;
  bdRefreshBoardToolbar = function bdRefreshBoardToolbarWithBackground(...args) {
    const result = _bdRefreshBoardToolbarBase.apply(this, args);
    if (typeof bdApplyCanvasBackground === 'function') _bdApplyCurrentBoardBackground();
    return result;
  };
}

;

/* === gb-board-style-manager.js === */
;
/* gb-board-style-manager.part01.js: split from gb-board-style-manager.js */
/* gb-board-style-manager.js: board style managers and filter popup */

// ============================================================
// グローバルスタイルデフォルト (全ボード共通)
// ============================================================
// 「デフォルトとして保存」を押すと、per-board の style._default に加えて
// localStorage にも記録し、新しいボードを開いたときに自動マージされる。
const BD_GLOBAL_CARD_STYLE_DEFAULTS_KEY = 'meldex-bd-global-card-style-defaults';
const BD_GLOBAL_LINE_STYLE_DEFAULTS_KEY = 'meldex-bd-global-line-style-defaults';
const BD_GLOBAL_DEPTH_STYLES_KEY        = 'meldex-bd-global-depth-styles';

function bdCaptureGlobalStyleDefaults() {
  const read = key => {
    try { return localStorage.getItem(key); }
    catch { return null; }
  };
  return {
    card: read(BD_GLOBAL_CARD_STYLE_DEFAULTS_KEY),
    line: read(BD_GLOBAL_LINE_STYLE_DEFAULTS_KEY),
    depth: read(BD_GLOBAL_DEPTH_STYLES_KEY),
  };
}

function bdRestoreGlobalStyleDefaults(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') return false;
  const pairs = [
    [BD_GLOBAL_CARD_STYLE_DEFAULTS_KEY, snapshot.card],
    [BD_GLOBAL_LINE_STYLE_DEFAULTS_KEY, snapshot.line],
    [BD_GLOBAL_DEPTH_STYLES_KEY, snapshot.depth],
  ];
  pairs.forEach(([key, value]) => {
    try {
      if (value === null || value === undefined) localStorage.removeItem(key);
      else localStorage.setItem(key, String(value));
    } catch {}
  });
  return true;
}

function _bdGlobalStyleDefaultsKey(kind) {
  return kind === 'card' ? BD_GLOBAL_CARD_STYLE_DEFAULTS_KEY
       : kind === 'line' ? BD_GLOBAL_LINE_STYLE_DEFAULTS_KEY
       : '';
}

// { styleId: styleSnapshot (without id/_default), ... }
function _bdReadGlobalStyleDefaults(kind) {
  const key = _bdGlobalStyleDefaultsKey(kind);
  if (!key) return {};
  try {
    const raw = JSON.parse(localStorage.getItem(key) || 'null');
    return raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  } catch {
    return {};
  }
}

function _bdWriteGlobalStyleDefaults(kind, map) {
  const key = _bdGlobalStyleDefaultsKey(kind);
  if (!key) return;
  try {
    if (map && Object.keys(map).length) localStorage.setItem(key, JSON.stringify(map));
    else localStorage.removeItem(key);
  } catch {}
}

function _bdSaveGlobalStyleDefault(kind, style) {
  if (!style || !style.id) return;
  const map = _bdReadGlobalStyleDefaults(kind);
  const snap = _bdCloneStyleForDefault(style);
  if (!snap) return;
  // 名前も保存して、新規ボードで ID 一致時に name を揃えられるようにする
  map[style.id] = { ...snap, name: style.name || '' };
  _bdWriteGlobalStyleDefaults(kind, map);
}

function _bdRemoveGlobalStyleDefault(kind, styleId) {
  if (!styleId) return;
  const map = _bdReadGlobalStyleDefaults(kind);
  if (Object.prototype.hasOwnProperty.call(map, styleId)) {
    delete map[styleId];
    _bdWriteGlobalStyleDefaults(kind, map);
  }
}

function _bdReadGlobalDepthStyles() {
  try {
    const raw = JSON.parse(localStorage.getItem(BD_GLOBAL_DEPTH_STYLES_KEY) || 'null');
    return Array.isArray(raw) ? raw : null;
  } catch {
    return null;
  }
}

function _bdSaveGlobalDepthStyles(styles) {
  try {
    if (Array.isArray(styles) && styles.length) {
      localStorage.setItem(BD_GLOBAL_DEPTH_STYLES_KEY, JSON.stringify(styles));
    } else {
      localStorage.removeItem(BD_GLOBAL_DEPTH_STYLES_KEY);
    }
  } catch {}
}

function _bdBoardStylePackExportPayload() {
  if (typeof bdEnsureBoardUiState === 'function') bdEnsureBoardUiState();
  if (typeof bdEnsureDepthStyles === 'function') bdEnsureDepthStyles();
  const cardStyles = typeof _bdDisplayedManagedStyles === 'function'
    ? _bdDisplayedManagedStyles('card')
    : (bd.cardStyles || []);
  const lineStyles = typeof _bdDisplayedManagedStyles === 'function'
    ? _bdDisplayedManagedStyles('line')
    : (bd.lineStyles || []);
  const depthStyles = typeof bdNormalizeDepthStyles === 'function'
    ? bdNormalizeDepthStyles(bd.depthStyles || [])
    : (bd.depthStyles || []);
  return {
    type: 'meldex-board-style-pack',
    version: 1,
    exportedAt: new Date().toISOString(),
    sourceBoard: bd.path || '',
    stylePresetVersion: typeof BD_STYLE_PRESET_VERSION !== 'undefined' ? BD_STYLE_PRESET_VERSION : 0,
    activeCardStyle: bd.activeCardStyle || '',
    activeLineStyle: bd.activeLineStyle || '',
    cardStyles: _bdClone(cardStyles || []),
    lineStyles: _bdClone(lineStyles || []),
    depthStyles: _bdClone(depthStyles || []),
  };
}

async function bdExportBoardStylePack() {
  if (typeof MeldexExportSave === 'undefined' || typeof MeldexExportSave.saveText !== 'function') {
    if (typeof showStatus === 'function') showStatus('保存ダイアログを初期化できませんでした', true);
    return false;
  }
  const payload = _bdBoardStylePackExportPayload();
  const rawName = typeof MeldexExportSave.guessNameFromPath === 'function'
    ? MeldexExportSave.guessNameFromPath(bd.path || '', 'board')
    : 'board';
  const stem = String(rawName || 'board').replace(/(?:\.board)?\.md$/i, '') || 'board';
  const safeStem = typeof MeldexExportSave.sanitizeTitle === 'function'
    ? MeldexExportSave.sanitizeTitle(stem, 'board')
    : stem.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_');
  return MeldexExportSave.saveText(JSON.stringify(payload, null, 2), {
    dialogTitle: 'ボードスタイルを書き出し',
    initialfile: `${safeStem}-board-styles.json`,
    extension: '.json',
    filetypes: [['JSON', '*.json'], ['すべてのファイル', '*.*']],
    okMessage: 'ボードスタイルを書き出しました',
    errorMessage: 'ボードスタイルの書き出しに失敗しました',
  });
}

// v0.5.320: pathType を 3 種 (curve/straight/orthogonal) に正規化するヘルパー。
// 旧 free-bezier → curve、旧 orthogonal-curve → orthogonal。
function _bdNormalizePathType(value, fallback) {
  if (value === 'free-bezier') return 'curve';
  if (value === 'orthogonal-curve') return 'orthogonal';
  if (value === 'orthogonal' || value === 'straight' || value === 'curve') return value;
  if (fallback === 'free-bezier') return 'curve';
  if (fallback === 'orthogonal-curve') return 'orthogonal';
  if (['orthogonal', 'straight', 'curve'].includes(fallback)) return fallback;
  return 'curve';
}

const BD_STYLE_FONTMAP_ID = 'bd-style-fontmap';
let _bdStyleFontMapRaf = 0;

function _bdFontFamilyOptions() {
  if (typeof getFontFamilyOptionItems === 'function') return getFontFamilyOptionItems();
  return [{ v: '', l: '共通フォント', style: 'font-family:inherit;' }];
}

window.addEventListener('meldex:font-catalog-updated', () => {
  document.querySelectorAll('select.bd-font-family-select').forEach(select => {
    select._gbFmtSetOptions?.(_bdFontFamilyOptions(), select._gbFmtSelectedValue ?? select.value);
  });
});

function _bdNormalizeFontFamily(value) {
  if (typeof normalizeFontFamilyValue === 'function') return normalizeFontFamilyValue(value);
  const raw = String(value == null ? '' : value).trim();
  if (!raw || ['inherit', 'initial', 'unset', 'revert', 'revert-layer'].includes(raw.toLowerCase())) return '';
  return raw;
}

function _bdCssAttr(value) {
  return String(value == null ? '' : value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function _bdAppendFontRule(rules, selector, value) {
  const fontFamily = _bdNormalizeFontFamily(value);
  if (!fontFamily) return;
  rules.push(`${selector}{--bd-style-font-family:${fontFamily};}`);
}

function bdUpdateStyleFontMap() {
  if (typeof document === 'undefined' || typeof bd === 'undefined') return;
  let styleEl = document.getElementById(BD_STYLE_FONTMAP_ID);
  if (!styleEl) {
    styleEl = document.createElement('style');
    styleEl.id = BD_STYLE_FONTMAP_ID;
    document.head.appendChild(styleEl);
  }
  const worldSelector = '[data-bd-role="world"]';
  const rules = [];
  (bd.cardStyles || []).forEach(style => {
    const id = style?.id || '';
    if (!id) return;
    _bdAppendFontRule(rules, `${worldSelector} [data-style-id="${_bdCssAttr(id)}"]`, style.fontFamily);
  });
  (bd.lineStyles || []).forEach(style => {
    const id = style?.id || '';
    if (!id) return;
    _bdAppendFontRule(rules, `${worldSelector} [data-line-style-id="${_bdCssAttr(id)}"]`, style.fontFamily);
  });
  (bd.depthStyles || []).forEach((style, index) => {
    _bdAppendFontRule(rules, `${worldSelector} [data-depth-style-index="${index}"]`, style?.fontFamily);
    _bdAppendFontRule(rules, `${worldSelector} [data-depth-line-style-index="${index}"]`, style?.line?.fontFamily);
  });
  styleEl.textContent = rules.join('\n');
}

function bdScheduleFontStyleMapUpdate() {
  if (typeof requestAnimationFrame !== 'function') {
    bdUpdateStyleFontMap();
    return;
  }
  if (_bdStyleFontMapRaf) cancelAnimationFrame(_bdStyleFontMapRaf);
  _bdStyleFontMapRaf = requestAnimationFrame(() => {
    _bdStyleFontMapRaf = 0;
    bdUpdateStyleFontMap();
  });
}

function _bdApplyStyleFieldChange(kind, style, field, value) {
  if (!style) return;
  const markNodeOverride = () => {
    if (typeof bd === 'undefined' || !Array.isArray(bd.nodes) || !bd.nodes.includes(style)) return;
    if (field === 'width') style._userW = true;
    else if (field === 'bgColor') style._userBgColor = true;
    else if (field === 'fontSize') style._userFontSize = true;
    else if (field === 'fontBold') style._userFontBold = true;
  };
  if (field === 'fontFamily') {
    style.fontFamily = _bdNormalizeFontFamily(value);
    return;
  }
  if (kind === 'card') {
    if (['borderWidth', 'borderRadius', 'fontSize', 'width', 'textStrokeWidth'].includes(field)) {
      const num = parseInt(value, 10) || 0;
      if (field === 'width') style[field] = Math.max(40, num);
      else if (field === 'fontSize') style[field] = Math.max(8, num);
      else if (field === 'textStrokeWidth') style[field] = Math.max(0, Math.min(12, num));
      else style[field] = Math.max(0, num);
      markNodeOverride();
      return;
    }
    if (['cloudBumpWidth', 'cloudBumpHeight', 'cloudSideWidth'].includes(field)) {
      const num = parseInt(value, 10) || 0;
      if (field === 'cloudBumpWidth') style[field] = Math.max(8, Math.min(200, num));
      else if (field === 'cloudBumpHeight') style[field] = Math.max(2, Math.min(100, num));
      else style[field] = Math.max(2, Math.min(100, num));
      return;
    }
    if (field === 'cloudOffset') {
      // UI は 0〜100 (%) で渡されるので 0〜1 に正規化
      const num = parseInt(value, 10);
      const pct = Number.isFinite(num) ? Math.max(0, Math.min(100, num)) : 50;
      style[field] = pct / 100;
      return;
    }
    if (field === 'cloudSubWidthRatio' || field === 'cloudSubHeightRatio') {
      // 0〜100 (%) の整数で保存。両方が > 0 のときだけ小山が現れる。
      const num = parseInt(value, 10);
      style[field] = Number.isFinite(num) ? Math.max(0, Math.min(100, num)) : 0;
      return;
    }
    if (field === 'shape') {
      // v0.5.251: 'rect' を空文字列 ('') に変換すると、bdToMd の `if (n.shape)` 真偽値
      // チェックで override が永続化されない (保存/再読込で消える)。'rect' をそのまま
      // 格納し、レンダリング側は「どの if 分岐にもマッチしない」デフォルト = rect 扱いする。
      style[field] = value;
      markNodeOverride();
      return;
    }
    style[field] = value;
    markNodeOverride();
    return;
  }
  if (field === 'width') {
    style.width = Math.max(0, parseInt(value, 10) || 0);
  } else if (field === 'pathType') {
    // v0.5.320: 3 種に統合。旧 free-bezier → curve、旧 orthogonal-curve → orthogonal。
    if (value === 'free-bezier') style.pathType = 'curve';
    else if (value === 'orthogonal-curve') style.pathType = 'orthogonal';
    else if (value === 'orthogonal') style.pathType = 'orthogonal';
    else if (value === 'straight') style.pathType = 'straight';
    else style.pathType = 'curve';
    delete style.straight;
  } else if (field === 'branchRatio') {
    const num = parseFloat(value);
    if (Number.isFinite(num)) style.branchRatio = Math.max(0.05, Math.min(0.95, num));
    else delete style.branchRatio;
  } else if (field === 'cornerRadius') {
    const num = parseFloat(value);
    if (Number.isFinite(num)) style.cornerRadius = Math.max(0, Math.min(40, num));
    else delete style.cornerRadius;
  } else if (field === 'straight') {
    style.pathType = value === true || value === 'true' ? 'straight' : 'curve';
    delete style.straight;
  } else if (field === 'textVisible' || field === 'textAlongPath' || field === 'textAutoFlip') {
    style[field] = !!value;
  } else if (field === 'textShadowWidth') {
    const num = parseFloat(value);
    style.textShadowWidth = Number.isFinite(num) ? Math.max(0, Math.min(10, num)) : 0;
  } else if (field === 'labelBorderWidth') {
    const num = parseFloat(value);
    style.labelBorderWidth = Number.isFinite(num) ? Math.max(0, Math.min(10, num)) : 0;
  } else {
    style[field] = value;
  }
}

function _bdStyleFieldNeedsFullRebuild(kind, field) {
  if (kind === 'card') return field === 'shape';
  if (kind === 'line') return field === 'pathType' || field === 'textAlongPath' || field === 'textVisible';
  return false;
}

// 共通ヘルパー: カードスタイルの色系フィールドをリセット（計画書 §4-2）
function _bdResetCardColors(style) {
  style.bgColor = '';
  style.textColor = '';
  style.textStrokeColor = '';
  style.borderColor = '';
}

// スタイルの「ユーザー定義デフォルト」用スナップショットを作る。
// id / name / _default 自身は除外し、値プロパティだけコピーする。
function _bdCloneStyleForDefault(style) {
  if (!style || typeof style !== 'object') return null;
  const snap = {};
  for (const key of Object.keys(style)) {
    if (key === 'id' || key === 'name' || key === '_default') continue;
    snap[key] = style[key];
  }
  return snap;
}

// スタイルを初期設定に戻す。
// 優先順位:
// 1. style._default (このボード内で「+」/「保存」で記録した値) があればそれに戻す
// 2. グローバルデフォルト (localStorage) に id 一致するエントリがあればそれに戻す
// 3. BD_DEFAULT_*_STYLES の id 一致する定義があればそれに戻す (ビルトインの初期値)
// 4. どれもない場合は色系のみリセット (カスタムスタイルへの救済措置)
function _bdResetStyleToDefault(kind, style) {
  if (!style) return;
  if (style._default && typeof style._default === 'object') {
    Object.keys(style).forEach(key => {
      if (key === 'id' || key === 'name' || key === '_default') return;
      delete style[key];
    });
    Object.keys(style._default).forEach(key => {
      if (key === 'id' || key === 'name' || key === '_default') return;
      style[key] = style._default[key];
    });
    return;
  }
  const globals = _bdReadGlobalStyleDefaults(kind);
  const globalDef = style.id && globals[style.id];
  if (globalDef && typeof globalDef === 'object') {
    Object.keys(style).forEach(key => {
      if (key === 'id' || key === 'name' || key === '_default') return;
      delete style[key];
    });
    Object.keys(globalDef).forEach(key => {
      if (key === 'id' || key === 'name' || key === '_default') return;
      style[key] = globalDef[key];
    });
    // 次回以降のリセットを早くするため per-board _default にも反映
    style._default = _bdCloneStyleForDefault(style);
    return;
  }
  const defaults = kind === 'card'
    ? (typeof bdDefaultCardStylesForBoard === 'function' ? bdDefaultCardStylesForBoard(typeof bd !== 'undefined' ? bd : undefined) : BD_DEFAULT_CARD_STYLES)
    : (typeof bdDefaultLineStylesForBoard === 'function' ? bdDefaultLineStylesForBoard(typeof bd !== 'undefined' ? bd : undefined) : BD_DEFAULT_LINE_STYLES);
  const def = (defaults || []).find(d => d && d.id === style.id);
  if (def) {
    Object.keys(style).forEach(key => {
      if (key === 'id') return;
      delete style[key];
    });
    Object.keys(def).forEach(key => {
      if (key === 'id') return;
      style[key] = def[key];
    });
    return;
  }
  if (kind === 'card') _bdResetCardColors(style);
  else {
    style.color = '';
    style.labelTextColor = '';
    style.labelBgColor = '';
    style.labelBorderColor = '';
  }
}

function _bdShapeOpts() {
  const shapes = (typeof BD_SHAPES !== 'undefined' ? BD_SHAPES : ['rect']);
  return shapes.map(s => ({
    v: s,
    l: (typeof BD_SHAPE_LABELS !== 'undefined' && BD_SHAPE_LABELS[s]) || s,
  }));
}

function _bdGetBoardCustomStyleId(kind) {
  return kind === 'card' ? 'card-custom' : 'line-custom';
}

// ノード/接続単位の自動 fork スタイル (card-custom / card-custom-<nodeId> / line-custom / line-custom-<connId>) を判定する。
// これらは詳細パネルの編集時に内部的に作られるフォークで、ユーザー向けスタイル管理ダイアログには出さない。
function _bdIsCustomStyleId(kind, id) {
  if (!id) return false;
  const prefix = kind === 'card' ? 'card-custom' : 'line-custom';
  return id === prefix || id.startsWith(prefix + '-');
}

// スタイル管理ダイアログの一覧に表示するスタイル群を取り出す（カスタム fork を除外）。
function _bdDisplayedManagedStyles(kind) {
  const styles = kind === 'card' ? bd.cardStyles : bd.lineStyles;
  return (styles || []).filter(style => style && !_bdIsCustomStyleId(kind, style.id));
}

// 既存スタイルと名前が衝突しないように連番サフィックスを付与する。
function _bdMakeUniqueStyleName(baseName, styles, excludeId) {
  const trimmed = String(baseName || '').trim() || 'スタイル';
  const names = new Set();
  (styles || []).forEach(style => {
    if (!style || style.id === excludeId) return;
    if (style.name) names.add(String(style.name));
  });
  if (!names.has(trimmed)) return trimmed;
  for (let i = 2; i < 10000; i++) {
    const candidate = `${trimmed} ${i}`;
    if (!names.has(candidate)) return candidate;
  }
  return trimmed;
}

// 指定スタイルがボード上で何個のカード/接続から参照されているか数える。
function _bdCountStyleUsage(kind, styleId) {
  if (!styleId || typeof bd === 'undefined') return 0;
  if (kind === 'card') return (bd.nodes || []).filter(node => node && node.cardStyle === styleId).length;
  return (bd.connections || []).filter(conn => conn && conn.styleRef === styleId).length;
}

// ボード詳細パネルでスタイル編集が始まった瞬間に、既存スタイルを保護するため
// 現在 active なスタイルを fork してカスタム化する。
// 既にカスタムが active ならそのまま返す。
// 注意: bdGetCardStyleById/bdGetLineStyleById は内部で bdEnsureBoardUiState を再呼び
// 出して bd.cardStyles 配列を新オブジェクトに置換するため、ここでは使わず
// 直接 find する（古い配列参照を持ち続けないため）。
function _bdEnsureBoardCustomStyle(kind) {
  bdEnsureBoardUiState();
  const customId = _bdGetBoardCustomStyleId(kind);
  const styles = kind === 'card' ? bd.cardStyles : bd.lineStyles;
  const activeRef = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
  if (bd[activeRef] === customId) {
    return styles.find(s => s.id === customId) || null;
  }
  const source = styles.find(s => s.id === bd[activeRef]) || styles[0];
  if (!source) return null;
  const next = _bdClone(source);
  next.id = customId;
  next.name = 'カスタム';
  const customIndex = styles.findIndex(s => s.id === customId);
  if (customIndex >= 0) styles.splice(customIndex, 1, next);
  else styles.push(next);
  bd[activeRef] = customId;
  return next;
}

async function _bdSaveBoardStyleAsNew(kind) {
  const activeRef = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
  // bdGetCardStyleById/bdGetLineStyleById が内部で bdEnsureBoardUiState を呼んで
  // bd.cardStyles/bd.lineStyles を新配列に差し替えるため、source 取得後に配列参照を固定してはいけない。
  // push 時点で bd.cardStyles / bd.lineStyles を直接参照する。
  const source = kind === 'card' ? bdGetCardStyleById(bd[activeRef]) : bdGetLineStyleById(bd[activeRef]);
  if (!source) return null;
  const baseName = source.name && source.name !== 'カスタム'
    ? `${source.name} 2`
    : (kind === 'card' ? '新しいカードスタイル' : '新しいラインスタイル');
  const input = await cfPrompt(kind === 'card' ? 'カードスタイル名' : 'ラインスタイル名', baseName);
  if (input == null) return null;
  const name = String(input).trim();
  if (!name) return null;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  const next = _bdClone(source);
  next.id = _bdNormalizeStyleId(`${kind}-style-${Date.now().toString(36)}`, `${kind}-style`);
  next.name = name;
  // 保存時点の値を「ユーザー定義デフォルト」として記録（リセットで戻る先）
  next._default = _bdCloneStyleForDefault(next);
  if (kind === 'card') bd.cardStyles.push(next);
  else bd.lineStyles.push(next);
  bd[activeRef] = next.id;
  bdDirty();
  bdRender();
  bdRefreshBoardToolbar();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  showStatus(`${kind === 'card' ? 'カードスタイル' : 'ラインスタイル'}「${name}」として保存しました`, false, { showSaveDialog: true });
  return next;
}

function _bdSaveCurrentBoardStyle(kind) {
  bdEnsureBoardUiState();
  const activeRef = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
  const style = kind === 'card' ? bdGetCardStyleById(bd[activeRef]) : bdGetLineStyleById(bd[activeRef]);
  if (!style) return;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  // 保存時も現在値を「ユーザー定義デフォルト」として更新（以降のリセットで戻る先）
  style._default = _bdCloneStyleForDefault(style);
  // 全ボード共通のグローバルデフォルトにも保存 (他のボードを開いたときも反映される)
  _bdSaveGlobalStyleDefault(kind, style);
  bdDirty();
  showStatus(`${kind === 'card' ? 'カードスタイル' : 'ラインスタイル'}「${style.name}」をデフォルトとして保存しました`, false, { showSaveDialog: true });
}

// ノード個別のカードスタイルをカスタム化する。
// ノード固有の override が設定されている場合は effective style を base にカスタムを作成し、
// そのノードに割り当て、override をクリアする。
function _bdEnsureNodeCardCustomStyle(node) {
  if (!node) return null;
  bdEnsureBoardUiState();
  const customId = 'card-custom-' + node.id;
  if (node.cardStyle === customId) {
    const existing = bd.cardStyles.find(s => s.id === customId);
    if (existing) return existing;
  }
  const eff = typeof bdGetNodeStyle === 'function' ? bdGetNodeStyle(node) : {};
  const next = {
    id: customId,
    name: 'カスタム',
    bgColor: eff.bgColor || '',
    textColor: eff.textColor || '',
    textStrokeColor: eff.textStrokeColor || '',
    borderColor: eff.borderColor || '',
    borderWidth: Number.isFinite(+eff.borderWidth) ? +eff.borderWidth : 0,
    borderRadius: Number.isFinite(+eff.borderRadius) ? +eff.borderRadius : 6,
    fontSize: Number.isFinite(+eff.fontSize) ? +eff.fontSize : 13,
    fontBold: !!eff.fontBold,
    fontItalic: !!eff.fontItalic,
    textStrokeWidth: Number.isFinite(+eff.textStrokeWidth) ? +eff.textStrokeWidth : 0,
    shape: eff.shape || '',
    width: Number.isFinite(+eff.width) ? +eff.width : 160,
  };
  const idx = bd.cardStyles.findIndex(s => s.id === customId);
  if (idx >= 0) bd.cardStyles.splice(idx, 1, next);
  else bd.cardStyles.push(next);
  if (typeof bdSetNodeCardStyleRef === 'function') bdSetNodeCardStyleRef(node, customId, { clearOverrides: true });
  else {
    if (typeof bdClearCardStyleOverrides === 'function') bdClearCardStyleOverrides(node);
    node.cardStyle = customId;
    node._userCardStyle = true;
  }
  return next;
}

function _bdEnsureConnectionLineCustomStyle(conn) {
  if (!conn) return null;
  bdEnsureBoardUiState();
  const customId = 'line-custom-' + conn.id;
  if (conn.styleRef === customId) {
    const existing = bd.lineStyles.find(s => s.id === customId);
    if (existing) return existing;
  }
  const eff = typeof bdGetConnectionStyle === 'function' ? bdGetConnectionStyle(conn) : {};
  const next = {
    id: customId,
    name: 'カスタム',
    color: eff.color || '',
    width: Number.isFinite(+eff.width) ? +eff.width : 0,
    style: eff.style === 'dashed' ? 'dashed' : '',
    arrow: ['end', 'start', 'both', ''].includes(eff.arrow) ? eff.arrow : 'end',
    pathType: _bdNormalizePathType(eff.pathType),
  };
  const idx = bd.lineStyles.findIndex(s => s.id === customId);
  if (idx >= 0) bd.lineStyles.splice(idx, 1, next);
  else bd.lineStyles.push(next);
  if (typeof bdClearConnectionStyleOverrides === 'function') bdClearConnectionStyleOverrides(conn);
  conn.styleRef = customId;
  return next;
}

function _bdCardStyleSnapshotFromNode(node, fallback) {
  const eff = typeof bdGetNodeStyle === 'function' ? bdGetNodeStyle(node) : {};
  return {
    ..._bdClone(fallback || {}),
    bgColor: eff.bgColor ?? fallback?.bgColor ?? '',
    textColor: eff.textColor ?? fallback?.textColor ?? '',
    textStrokeColor: eff.textStrokeColor ?? fallback?.textStrokeColor ?? '',
    borderColor: eff.borderColor ?? fallback?.borderColor ?? '',
    borderWidth: Number.isFinite(+eff.borderWidth) ? +eff.borderWidth : (Number.isFinite(+(fallback?.borderWidth)) ? +fallback.borderWidth : 0),
    borderRadius: Number.isFinite(+eff.borderRadius) ? +eff.borderRadius : (Number.isFinite(+(fallback?.borderRadius)) ? +fallback.borderRadius : 6),
    fontSize: Number.isFinite(+eff.fontSize) ? +eff.fontSize : (Number.isFinite(+(fallback?.fontSize)) ? +fallback.fontSize : 13),
    fontBold: !!eff.fontBold,
    fontItalic: !!eff.fontItalic,
    fontFamily: _bdNormalizeFontFamily(eff.fontFamily ?? fallback?.fontFamily ?? ''),
    textStrokeWidth: Number.isFinite(+eff.textStrokeWidth) ? +eff.textStrokeWidth : (Number.isFinite(+(fallback?.textStrokeWidth)) ? +fallback.textStrokeWidth : 0),
    shape: eff.shape ?? fallback?.shape ?? '',
    width: Number.isFinite(+eff.width) ? +eff.width : (Number.isFinite(+(fallback?.width)) ? +fallback.width : 160),
    // v0.5.251: 雲/トゲ/もやもや用パラメータも effective 値で反映
    cloudBumpWidth: Number.isFinite(+eff.cloudBumpWidth) ? +eff.cloudBumpWidth : (Number.isFinite(+(fallback?.cloudBumpWidth)) ? +fallback.cloudBumpWidth : 40),
    cloudBumpHeight: Number.isFinite(+eff.cloudBumpHeight) ? +eff.cloudBumpHeight : (Number.isFinite(+(fallback?.cloudBumpHeight)) ? +fallback.cloudBumpHeight : 16),
    cloudSideWidth: Number.isFinite(+eff.cloudSideWidth) ? +eff.cloudSideWidth : (Number.isFinite(+(fallback?.cloudSideWidth)) ? +fallback.cloudSideWidth : 12),
    cloudOffset: Number.isFinite(+eff.cloudOffset) ? +eff.cloudOffset : (Number.isFinite(+(fallback?.cloudOffset)) ? +fallback.cloudOffset : 0.5),
    cloudSubWidthRatio: Number.isFinite(+eff.cloudSubWidthRatio) ? +eff.cloudSubWidthRatio : (Number.isFinite(+(fallback?.cloudSubWidthRatio)) ? +fallback.cloudSubWidthRatio : 0),
    cloudSubHeightRatio: Number.isFinite(+eff.cloudSubHeightRatio) ? +eff.cloudSubHeightRatio : (Number.isFinite(+(fallback?.cloudSubHeightRatio)) ? +fallback.cloudSubHeightRatio : 0),
  };
}

function _bdLineStyleSnapshotFromConnection(conn, fallback) {
  const eff = typeof bdGetConnectionStyle === 'function' ? bdGetConnectionStyle(conn) : {};
  const hasOwn = key => conn && Object.prototype.hasOwnProperty.call(conn, key);
  const valueOrFallback = (key, defaultValue = '') => (
    hasOwn(key) ? conn[key] : (eff[key] ?? fallback?.[key] ?? defaultValue)
  );
  const arrow = ['end', 'start', 'both', ''].includes(eff.arrow) ? eff.arrow : (fallback?.arrow || 'end');
  const pathType = _bdNormalizePathType(eff.pathType, fallback?.pathType);
  return {
    ..._bdClone(fallback || {}),
    color: valueOrFallback('color'),
    width: Number.isFinite(+eff.width) ? +eff.width : (Number.isFinite(+(fallback?.width)) ? +fallback.width : 0),
    style: valueOrFallback('style') === 'dashed' ? 'dashed' : '',
    arrow,
    pathType,
    branchRatio: Number.isFinite(+eff.branchRatio) ? Math.max(0.05, Math.min(0.95, +eff.branchRatio)) : (Number.isFinite(+fallback?.branchRatio) ? Math.max(0.05, Math.min(0.95, +fallback.branchRatio)) : 0.3),
    cornerRadius: Number.isFinite(+eff.cornerRadius) ? Math.max(0, Math.min(40, +eff.cornerRadius)) : (Number.isFinite(+fallback?.cornerRadius) ? Math.max(0, Math.min(40, +fallback.cornerRadius)) : 0),
    labelTextColor: valueOrFallback('labelTextColor'),
    labelBgColor: valueOrFallback('labelBgColor'),
    labelBorderColor: valueOrFallback('labelBorderColor'),
    labelBorderWidth: Number.isFinite(+eff.labelBorderWidth) ? +eff.labelBorderWidth : (Number.isFinite(+fallback?.labelBorderWidth) ? +fallback.labelBorderWidth : 0),
    fontBold: eff.fontBold !== undefined ? !!eff.fontBold : !!fallback?.fontBold,
    fontItalic: eff.fontItalic !== undefined ? !!eff.fontItalic : !!fallback?.fontItalic,
    fontFamily: _bdNormalizeFontFamily(eff.fontFamily ?? fallback?.fontFamily ?? ''),
    textVisible: eff.textVisible !== undefined ? !!eff.textVisible : (fallback?.textVisible !== undefined ? !!fallback.textVisible : true),
    textAlongPath: eff.textAlongPath !== undefined ? !!eff.textAlongPath : !!fallback?.textAlongPath,
    textAutoFlip: eff.textAutoFlip !== undefined ? !!eff.textAutoFlip : (fallback?.textAutoFlip !== undefined ? !!fallback.textAutoFlip : true),
    textShadowWidth: Number.isFinite(+eff.textShadowWidth) ? +eff.textShadowWidth : (Number.isFinite(+fallback?.textShadowWidth) ? +fallback.textShadowWidth : 0),
    textShadowColor: valueOrFallback('textShadowColor'),
  };
}

async function _bdSaveNodeCardStyleAsNew(node) {
  if (!node) return null;
  bdEnsureBoardUiState();
  const base = bdGetCardStyleById(node.cardStyle || bd.activeCardStyle);
  const source = _bdCardStyleSnapshotFromNode(node, base);
  const baseName = source.name && source.name !== 'カスタム' ? `${source.name} 2` : '新しいカードスタイル';
  const input = await cfPrompt('カードスタイル名', baseName);
  if (input == null) return null;
  const name = String(input).trim();
  if (!name) return null;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  const next = _bdClone(source);
  next.id = _bdNormalizeStyleId(`card-style-${Date.now().toString(36)}`, 'card-style');
  next.name = name;
  // 保存時点の値を「ユーザー定義デフォルト」として記録（リセットで戻る先）
  next._default = _bdCloneStyleForDefault(next);
  bd.cardStyles.push(next);
  if (typeof bdSetNodeCardStyleRef === 'function') bdSetNodeCardStyleRef(node, next.id, { clearOverrides: true });
  else {
    node.cardStyle = next.id;
    if (typeof bdClearCardStyleOverrides === 'function') bdClearCardStyleOverrides(node);
    node._userCardStyle = true;
  }
  bdDirty();
  bdRender();
  bdRefreshBoardToolbar();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  showStatus(`カードスタイル「${name}」として保存しました`, false, { showSaveDialog: true });
  return next;
}

async function _bdSaveConnectionLineStyleAsNew(conn) {
  if (!conn) return null;
  bdEnsureBoardUiState();
  const base = bdGetLineStyleById(conn.styleRef || bd.activeLineStyle);
  const source = _bdLineStyleSnapshotFromConnection(conn, base);
  const baseName = source.name && source.name !== 'カスタム' ? `${source.name} 2` : '新しいラインスタイル';
  const input = await cfPrompt('ラインスタイル名', baseName);
  if (input == null) return null;
  const name = String(input).trim();
  if (!name) return null;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  const next = _bdClone(source);
  next.id = _bdNormalizeStyleId(`line-style-${Date.now().toString(36)}`, 'line-style');
  next.name = name;
  // 保存時点の値を「ユーザー定義デフォルト」として記録（リセットで戻る先）
  next._default = _bdCloneStyleForDefault(next);
  bd.lineStyles.push(next);
  conn.styleRef = next.id;
  if (typeof bdClearConnectionStyleOverrides === 'function') bdClearConnectionStyleOverrides(conn);
  bdDirty();
  bdRender();
  bdRefreshBoardToolbar();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  showStatus(`ラインスタイル「${name}」として保存しました`, false, { showSaveDialog: true });
  return next;
}

// v0.5.251: カードの個別オーバーライドを共通スタイルに伝播する。
// 詳細パネル編集で node に蓄積された overrides を style にコピーし、node 側は削除する。
// これで同じスタイルを参照する他のカードにも変更が反映される。
// `bdClearCardStyleOverrides` のキー一覧と同期すること (width は n.w が別管理なので除外)。
const _BD_CARD_OVERRIDE_KEYS = [
  'bgColor', 'textColor', 'borderColor', 'borderWidth', 'borderRadius',
  'fontSize', 'fontBold', 'fontItalic', 'textStrokeColor', 'textStrokeWidth',
  'shape',
  'cloudBumpWidth', 'cloudBumpHeight', 'cloudSideWidth', 'cloudOffset',
  'cloudSubBumpRatio', 'cloudSubWidthRatio', 'cloudSubHeightRatio',
];
function _bdSaveCurrentNodeCardStyle(node) {
  if (!node) return;
  bdEnsureBoardUiState();
  const style = bdGetCardStyleById(node.cardStyle || bd.activeCardStyle);
  if (!style) return;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  // node の overrides を style にコピー → node 側は削除
  let copied = 0;
  _BD_CARD_OVERRIDE_KEYS.forEach(key => {
    if (Object.prototype.hasOwnProperty.call(node, key)) {
      style[key] = node[key];
      delete node[key];
      copied += 1;
    }
  });
  // 保存時も現在値を「ユーザー定義デフォルト」として更新（以降のリセットで戻る先）
  style._default = _bdCloneStyleForDefault(style);
  _bdSaveGlobalStyleDefault('card', style);
  if (typeof bdRender === 'function') bdRender();
  bdDirty();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  showStatus(copied > 0
    ? `カードスタイル「${style.name}」をデフォルトとして保存しました (同じスタイルの他のカードにも反映)`
    : `カードスタイル「${style.name}」は既に保存済みです`, false, { showSaveDialog: true });
}

const _BD_LINE_OVERRIDE_KEYS = [
  'color', 'width', 'style', 'arrow', 'straight', 'pathType',
  'branchRatio', 'cornerRadius',
  'labelTextColor', 'labelBgColor', 'labelBorderColor', 'labelBorderWidth',
  'fontBold', 'fontItalic',
  'textVisible', 'textAlongPath', 'textAutoFlip', 'textShadowWidth', 'textShadowColor',
];
function _bdSaveCurrentConnectionLineStyle(conn) {
  if (!conn) return;
  bdEnsureBoardUiState();
  const style = bdGetLineStyleById(conn.styleRef || bd.activeLineStyle);
  if (!style) return;
  if (typeof bdPushUndo === 'function') bdPushUndo();
  // conn の overrides を style にコピー → conn 側は削除
  let copied = 0;
  _BD_LINE_OVERRIDE_KEYS.forEach(key => {
    if (Object.prototype.hasOwnProperty.call(conn, key)) {
      style[key] = conn[key];
      delete conn[key];
      copied += 1;
    }
  });
  style._default = _bdCloneStyleForDefault(style);
  _bdSaveGlobalStyleDefault('line', style);
  if (typeof bdDrawConns === 'function') bdDrawConns();
  bdDirty();
  if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  showStatus(copied > 0
    ? `ラインスタイル「${style.name}」をデフォルトとして保存しました (同じスタイルの他のラインにも反映)`
    : `ラインスタイル「${style.name}」は既に保存済みです`, false, { showSaveDialog: true });
}

/**
 * カード/ラインのスタイルフィールドを DOM として構築する。
 * 計画書 §4-2/§4-3 の横並び構造に対応（gb-fmt-popup-row）。
 *
 * @param {HTMLElement} container 配置先コンテナ（innerHTML はクリアされる）
 * @param {'card'|'line'} kind
 * @param {Object} style 対象のスタイルオブジェクト（直接更新される）
 * @param {() => void} onChange 変更後コールバック
 * @param {{beforeEdit?: () => Object|null}} [options] beforeEdit が返したスタイルがあれば、
 *        編集はそのスタイルに対して行う（ボード詳細パネルでカスタム化に使用）
 */
function _bdBuildStyleFields(container, kind, style, onChange, options) {
  if (!container || !style) return;
  container.innerHTML = '';
  const fmt = window.gbFmt;
  if (!fmt) { container.textContent = '書式UI未ロード'; return; }
  const emit = (field) => { try { onChange && onChange(field); } catch (_) {} };
  const editTarget = () => {
    if (options && typeof options.beforeEdit === 'function') {
      const next = options.beforeEdit();
      if (next) return next;
    }
    return style;
  };
  // v0.5.251: name は「スタイルそのもののメタデータ」なので、常に shared style に書き込む。
  // 詳細パネルでは editTarget が node/conn (個別 override) を返すため、name だけは別経路で共有スタイルを参照する。
  const nameEditTarget = () => {
    if (options && typeof options.nameEditTarget === 'function') {
      const next = options.nameEditTarget();
      if (next) return next;
    }
    return style;
  };
  const setField = (field, value) => {
    if (field === 'name') {
      const nameTarget = nameEditTarget();
      if (!nameTarget) return;
      const trimmed = String(value == null ? '' : value).trim();
      if (trimmed === nameTarget.name) return;
      if (!trimmed) { emit(); return; }
      if (typeof bdPushUndo === 'function') bdPushUndo();
      nameTarget.name = trimmed;
      emit(field);
      return;
    }
    // 複数ターゲット一括適用: editTargets() が配列を返したら、全ターゲットに同じ変更を適用する。
    // editTargets が指定されていれば (空配列でも) 単一編集にフォールバックしない。
    // undo は 1 回だけ積む（まとめて戻せるように）。
    if (options && typeof options.editTargets === 'function') {
      const multi = options.editTargets();
      if (Array.isArray(multi) && multi.length) {
        if (typeof bdPushUndo === 'function') bdPushUndo();
        multi.forEach(t => { if (t) _bdApplyStyleFieldChange(kind, t, field, value); });
        emit(field);
      }
      return;
    }
    const target = editTarget();
    if (!target) return;
    if (typeof bdPushUndo === 'function') bdPushUndo();
    _bdApplyStyleFieldChange(kind, target, field, value);
    emit(field);
  };

  // E2E 互換のため、各フィールドに data-bd-style-field="<fieldName>" を付与する。
  // [app/gb-e2e-actions-extra.js](app/gb-e2e-actions-extra.js) が modal.querySelector で参照する。
  const e2eScope = (options && options.e2eScope) || kind;
  const tag = (field) => (el) => {
    if (!el || !el.setAttribute) return el;
    const e2eId = `bd-style-${e2eScope}-${field}`;
    const nested = el.matches?.('input,select,textarea,button')
      ? [el]
      : [...el.querySelectorAll('input,select,textarea,button')];
    if (nested.length) {
      el.setAttribute('data-bd-style-field-container', field);
    } else {
      el.setAttribute('data-bd-style-field', field);
    }
    el.setAttribute('data-e2e-id', e2eId);
    if (!el.getAttribute('aria-label') && !el.textContent.trim()) {
      el.setAttribute('aria-label', el.getAttribute('title') || field);
    }
    nested.forEach((node, index) => {
      node.setAttribute('data-bd-style-field', field);
      node.setAttribute('data-e2e-id', index === 0 ? e2eId : `${e2eId}-${index + 1}`);
      if (!node.getAttribute('aria-label')) {
        node.setAttribute('aria-label', node.getAttribute('title') || el.getAttribute('title') || field);
      }
    });
    return el;
  };
  const showFontFamily = !(options && options.hideFontFamily);

  // --- 名前行（独立行）---
  // hideName が指定されている or 複数ターゲット編集 (editTargets) の場合は名前行を表示しない。
  const hideName = !!(options && (options.hideName || typeof options.editTargets === 'function'));
  if (!hideName) {
    const nameRow = document.createElement('div');
    nameRow.className = 'bd-style-name-row';
    const nameLbl = document.createElement('span');
    nameLbl.className = 'gb-fmt-label';
    nameLbl.textContent = 'スタイル名';
    const nameInp = document.createElement('input');
    nameInp.type = 'text';
    nameInp.value = style.name || '';
    nameInp.className = 'bd-style-name-input';
    nameInp.setAttribute('data-bd-style-field', 'name');
    nameInp.setAttribute('data-e2e-id', `bd-style-${e2eScope}-name`);
    nameInp.setAttribute('aria-label', 'スタイル名');
    nameInp.addEventListener('change', () => setField('name', nameInp.value));
    nameRow.append(nameLbl, nameInp);
    container.appendChild(nameRow);
  }

  if (kind === 'card') {
    // --- Row 1: 色 + 書式 + サイズ ---
    // 並び順: 背景色 → 枠線色 → 文字色 → 文字フチ色。
    // 文字色・文字フチ色スウォッチは背景を bgColor に揃え、実際の見え方をプレビュー。
    const row1 = fmt.makeRow({ wrap: true });
    row1.appendChild(tag('bgColor')(fmt.makeSwatchBg({ title: '背景色', color: style.bgColor || '', onPick: (c) => setField('bgColor', c) })));
    row1.appendChild(tag('borderColor')(fmt.makeSwatchBg({ title: '枠線色', color: style.borderColor || '', onPick: (c) => setField('borderColor', c) })));
    row1.appendChild(tag('textColor')(fmt.makeSwatchText({ title: '文字色', color: style.textColor || '', iconName: 'type', bgColor: style.bgColor || '', onPick: (c) => setField('textColor', c) })));
    row1.appendChild(tag('textStrokeColor')(fmt.makeSwatchText({ title: '文字フチ色', color: style.textStrokeColor || '', iconName: 'typeOutline', bgColor: style.bgColor || '', onPick: (c) => setField('textStrokeColor', c) })));
    row1.appendChild(tag('fontBold')(fmt.makeToggle({ html: '<b>B</b>', title: '太字', active: !!style.fontBold, onToggle: (on) => setField('fontBold', on) })));
    row1.appendChild(tag('fontItalic')(fmt.makeToggle({ html: '<i>I</i>', title: '斜体', active: !!style.fontItalic, onToggle: (on) => setField('fontItalic', on) })));
    const fontSizeInp = fmt.makeNumInput({ title: '文字サイズ', value: style.fontSize, min: 8, max: 72, onChange: (v) => setField('fontSize', v == null ? '' : v) });
    tag('fontSize')(fontSizeInp);
    row1.appendChild(fmt.makeGroup([fmt.makeLabel('文字'), fontSizeInp, fmt.makeLabel('px')]));
    if (showFontFamily) {
      const fontFamilySel = fmt.makeSelect({ opts: _bdFontFamilyOptions(), value: _bdNormalizeFontFamily(style.fontFamily), onChange: (v) => setField('fontFamily', v) });
      fontFamilySel.classList.add('bd-font-family-select');
      tag('fontFamily')(fontFamilySel);
      row1.appendChild(fmt.makeGroup([fmt.makeLabel('フォント'), fontFamilySel]));
    }
    container.appendChild(row1);

    // --- Row 2: カード固有 (フチ幅 / 枠線 / [標準幅] / 形状 / [角丸]) ---
    //   - 標準幅: 新規カード作成時の初期幅に使われる。選択済みの既存カードには無意味なので
    //     hideDefaultWidth=true のとき非表示 (既存カード選択時の詳細パネル用途)。
    //   - 角丸: 矩形 (rect) のとき以外は形状が独自に輪郭を決めるため無意味。rect のときだけ表示。
    const row2 = fmt.makeRow({ wrap: true });
    const tswInp = fmt.makeNumInput({ title: '文字フチ幅', value: style.textStrokeWidth || 0, min: 0, max: 12, onChange: (v) => setField('textStrokeWidth', v == null ? 0 : v) });
    tag('textStrokeWidth')(tswInp);
    row2.appendChild(fmt.makeGroup([fmt.makeLabel('フチ幅'), tswInp, fmt.makeLabel('px')]));
    const bwInp = fmt.makeNumInput({ title: '枠線太さ', value: style.borderWidth, min: 0, max: 20, onChange: (v) => setField('borderWidth', v == null ? 0 : v) });
    tag('borderWidth')(bwInp);
    row2.appendChild(fmt.makeGroup([fmt.makeLabel('枠線'), bwInp, fmt.makeLabel('px')]));
    if (!(options && options.hideDefaultWidth)) {
      const wInp = fmt.makeNumInput({ title: '標準幅', value: style.width || 160, min: 40, max: 600, onChange: (v) => setField('width', v == null ? 160 : v), width: 76 });
      tag('width')(wInp);
      row2.appendChild(fmt.makeGroup([fmt.makeLabel('標準幅'), wInp, fmt.makeLabel('px')]));
    }
    const shpSel = fmt.makeSelect({ opts: _bdShapeOpts(), value: style.shape || 'rect', onChange: (v) => setField('shape', v) });
    tag('shape')(shpSel);
    row2.appendChild(fmt.makeGroup([fmt.makeLabel('形状'), shpSel]));
    const isRectShape = !style.shape || style.shape === 'rect';
    if (isRectShape) {
      const brInp = fmt.makeNumInput({ title: '角丸', value: style.borderRadius, min: 0, max: 64, onChange: (v) => setField('borderRadius', v == null ? 0 : v) });
      tag('borderRadius')(brInp);
      row2.appendChild(fmt.makeGroup([fmt.makeLabel('角丸'), brInp, fmt.makeLabel('px')]));
    }
    container.appendChild(row2);

    // 選択色・カーソル色はカードスタイル単位ではなくボード全体の設定 (bd.selectionColor / bd.caretColor) に移行。
    // カードスタイル UI からは除外し、ボード詳細パネル (選択なし時) で設定する。

    // --- Row 3 (雲型・トゲ型用): 山の幅 / 山の高さ / ズラし量 / 小山サイズ ---
    //   「張り出し」(cloudSideWidth) は楕円ベースに変更した v0.5.190 以降実際の描画に使われていないため UI から除外。
    if (style.shape === 'cloud' || style.shape === 'thorn' || style.shape === 'thorn-curve' || style.shape === 'fluffy') {
      const row3 = fmt.makeRow({ wrap: true });
      const cbw = fmt.makeNumInput({ title: '山の幅', value: style.cloudBumpWidth ?? 40, min: 8, max: 200, onChange: (v) => setField('cloudBumpWidth', v == null ? 40 : v) });
      tag('cloudBumpWidth')(cbw);
      row3.appendChild(fmt.makeGroup([fmt.makeLabel('山の幅'), cbw, fmt.makeLabel('px')]));
      const cbh = fmt.makeNumInput({ title: '山の高さ', value: style.cloudBumpHeight ?? 16, min: 2, max: 100, onChange: (v) => setField('cloudBumpHeight', v == null ? 16 : v) });
      tag('cloudBumpHeight')(cbh);
      row3.appendChild(fmt.makeGroup([fmt.makeLabel('山の高さ'), cbh, fmt.makeLabel('px')]));
      // ズラし量は 0〜100 (%) の整数で UI 表示し、内部では 0〜1 に正規化
      const offsetPct = Math.round((style.cloudOffset ?? 0.5) * 100);
      const coOff = fmt.makeNumInput({ title: 'ズラし量 (%)', value: offsetPct, min: 0, max: 100, onChange: (v) => setField('cloudOffset', v == null ? 50 : v) });
      tag('cloudOffset')(coOff);
      row3.appendChild(fmt.makeGroup([fmt.makeLabel('ズラし量'), coOff, fmt.makeLabel('%')]));
      // 小山サイズ比率 — メイン山の幅・高さを別々の % で縮小して小山とする。両方 > 0 で小山が現れる。
      const subWPct = Math.max(0, Math.min(100, Math.round(+(style.cloudSubWidthRatio ?? 0))));
      const subWInp = fmt.makeNumInput({ title: '小山の幅 (メイン山に対する %)', value: subWPct, min: 0, max: 100, onChange: (v) => setField('cloudSubWidthRatio', v == null ? 0 : v) });
      tag('cloudSubWidthRatio')(subWInp);
      row3.appendChild(fmt.makeGroup([fmt.makeLabel('小山幅'), subWInp, fmt.makeLabel('%')]));
      const subHPct = Math.max(0, Math.min(100, Math.round(+(style.cloudSubHeightRatio ?? 0))));
      const subHInp = fmt.makeNumInput({ title: '小山の高さ (メイン山に対する %)', value: subHPct, min: 0, max: 100, onChange: (v) => setField('cloudSubHeightRatio', v == null ? 0 : v) });
      tag('cloudSubHeightRatio')(subHInp);
      row3.appendChild(fmt.makeGroup([fmt.makeLabel('小山高'), subHInp, fmt.makeLabel('%')]));
      container.appendChild(row3);
    }
    // リセットボタンは詳細パネルの style-row に移動 (2026-04-18)
    return;
  }

  // kind === 'line'
  // --- Row 1: 色 + 太さ + ライン種 + 矢印 ---
  const lrow1 = fmt.makeRow({ wrap: true });
  lrow1.appendChild(tag('color')(fmt.makeSwatchBg({ title: '色', color: style.color || '', onPick: (c) => setField('color', c) })));
  const lwInp = fmt.makeNumInput({ title: '太さ', value: style.width, min: 0, max: 20, onChange: (v) => setField('width', v == null ? 0 : v) });
  tag('width')(lwInp);
  lrow1.appendChild(fmt.makeGroup([fmt.makeLabel('太さ'), lwInp, fmt.makeLabel('px')]));
  const lstyleSel = fmt.makeSelect({
    opts: [{ v: '', l: '実線' }, { v: 'dashed', l: '破線' }],
    value: style.style === 'dashed' ? 'dashed' : '',
    onChange: (v) => setField('style', v),
  });
  tag('style')(lstyleSel);
  lrow1.appendChild(fmt.makeGroup([fmt.makeLabel('種類'), lstyleSel]));
  const larrowSel = fmt.makeSelect({
    opts: [{ v: '', l: 'なし' }, { v: 'end', l: '順方向' }, { v: 'start', l: '逆方向' }, { v: 'both', l: '双方向' }],
    value: style.arrow || '',
    onChange: (v) => setField('arrow', v),
  });
  tag('arrow')(larrowSel);
  lrow1.appendChild(fmt.makeGroup([fmt.makeLabel('矢印'), larrowSel]));
  container.appendChild(lrow1);

  // --- Row 2: 形状 ---
  const lrow2 = fmt.makeRow({ wrap: true });
  // v0.5.320: pathType は 3 種 (curve/straight/orthogonal) に統合。
  // 旧 free-bezier は curve、旧 orthogonal-curve は orthogonal として表示。
  let curPath = style.pathType || (style.straight ? 'straight' : 'curve');
  if (curPath === 'free-bezier') curPath = 'curve';
  else if (curPath === 'orthogonal-curve') curPath = 'orthogonal';
  const lpathSel = fmt.makeSelect({
    opts: [
      { v: 'curve', l: '曲線' },
      { v: 'straight', l: '直線' },
      { v: 'orthogonal', l: '直角線' },
    ],
    value: curPath,
    onChange: (v) => setField('pathType', v),
  });
  tag('pathType')(lpathSel);
  lrow2.appendChild(fmt.makeGroup([fmt.makeLabel('形状'), lpathSel]));
  // v0.5.320: 直角線のパラメータ (コーナー半径 / 分岐位置)。pathType='orthogonal' のときのみ活性化
  // makeNumInput は整数のみ扱うため、branchRatio は % (5-95) で保持し、保存時に /100 する
  if (curPath === 'orthogonal') {
    const cornerInput = fmt.makeNumInput({ title: 'コーナー半径 (px)', value: Number.isFinite(+style.cornerRadius) ? +style.cornerRadius : 0, min: 0, max: 40, onChange: (v) => setField('cornerRadius', v == null ? 0 : v) });
    tag('cornerRadius')(cornerInput);
    lrow2.appendChild(fmt.makeGroup([fmt.makeLabel('コーナー半径'), cornerInput, fmt.makeLabel('px')]));
    const branchPct = Math.round((Number.isFinite(+style.branchRatio) ? +style.branchRatio : 0.3) * 100);
    const branchInput = fmt.makeNumInput({ title: '分岐位置 (%)', value: branchPct, min: 5, max: 95, onChange: (v) => setField('branchRatio', v == null ? 0.3 : Math.max(0.05, Math.min(0.95, v / 100))) });
    tag('branchRatio')(branchInput);
    lrow2.appendChild(fmt.makeGroup([fmt.makeLabel('分岐位置'), branchInput, fmt.makeLabel('%')]));
  }
  container.appendChild(lrow2);
  // ライン選択色はラインスタイル単位ではなくボード全体の設定 (bd.selectionColor) に移行。

  // --- ラベル（テキスト）のスタイル ---
  const textVisible = style.textVisible !== undefined ? !!style.textVisible : true;
  const textAlongPath = style.textAlongPath !== undefined ? !!style.textAlongPath : false;
  const textAutoFlip = style.textAutoFlip !== undefined ? !!style.textAutoFlip : true;
  const textShadowWidth = Number.isFinite(+style.textShadowWidth) ? +style.textShadowWidth : 0;
  const labelBorderWidth = Number.isFinite(+style.labelBorderWidth) ? +style.labelBorderWidth : 0;

  // --- Row 2.5: テキスト表示オン/オフ (テキスト設定直前に配置) ---
  const lrowTextToggle = fmt.makeRow({ wrap: true });
  const textVisibleCb = tag('textVisible')(fmt.makeCheckbox({
    text: 'テキスト', title: 'テキスト表示', checked: textVisible, onChange: (on) => setField('textVisible', on),
  }));
  lrowTextToggle.appendChild(textVisibleCb);
  container.appendChild(lrowTextToggle);

  // --- Row 3: テキスト書式 (背景 / 枠線色 / 枠線太さ / 文字色 / 太字 / 斜体 / 縁取 / フォント) ---
  // 並び順: 背景色 → 枠線色 → 枠線太さ → 文字色 → 太字 → 斜体 → 縁取(太さ + 色) → フォント
  const lrow3 = fmt.makeRow({ wrap: true });
  lrow3.appendChild(fmt.makeLabel('テキスト'));
  const labelBgSw = tag('labelBgColor')(fmt.makeSwatchBg({ title: 'テキスト背景色', color: style.labelBgColor || '', onPick: (c) => setField('labelBgColor', c) }));
  const labelBorderSw = tag('labelBorderColor')(fmt.makeSwatchBg({ title: 'テキスト枠線色', color: style.labelBorderColor || '', onPick: (c) => setField('labelBorderColor', c) }));
  lrow3.appendChild(labelBgSw);
  lrow3.appendChild(labelBorderSw);
  const labelBorderWInp = fmt.makeNumInput({ title: 'テキスト枠線太さ', value: labelBorderWidth, min: 0, max: 10, onChange: (v) => setField('labelBorderWidth', v == null ? 0 : v) });
  tag('labelBorderWidth')(labelBorderWInp);
  const labelBorderWGroup = fmt.makeGroup([fmt.makeLabel('枠線'), labelBorderWInp, fmt.makeLabel('px')]);
  lrow3.appendChild(labelBorderWGroup);
  lrow3.appendChild(tag('labelTextColor')(fmt.makeSwatchText({ title: 'テキスト文字色', color: style.labelTextColor || '', iconName: 'type', bgColor: style.labelBgColor || '', onPick: (c) => setField('labelTextColor', c) })));
  // ラインテキストの太字 / 斜体
  lrow3.appendChild(tag('fontBold')(fmt.makeToggle({ html: '<b>B</b>', title: '太字', active: !!style.fontBold, onToggle: (on) => setField('fontBold', on) })));
  lrow3.appendChild(tag('fontItalic')(fmt.makeToggle({ html: '<i>I</i>', title: '斜体', active: !!style.fontItalic, onToggle: (on) => setField('fontItalic', on) })));
  // 縁取 (斜体の後ろ、テキスト色・沿線回転とは独立)
  const shadowInp = fmt.makeNumInput({ title: '縁取り太さ', value: textShadowWidth, min: 0, max: 5, onChange: (v) => setField('textShadowWidth', v == null ? 0 : v) });
  tag('textShadowWidth')(shadowInp);
  const shadowColorSw = fmt.makeSwatchBg({ title: 'テキスト縁取り色', color: style.textShadowColor || '', onPick: (c) => setField('textShadowColor', c) });
  tag('textShadowColor')(shadowColorSw);
  lrow3.appendChild(fmt.makeGroup([fmt.makeLabel('縁取'), shadowInp, fmt.makeLabel('px'), shadowColorSw]));
  if (showFontFamily) {
    const lineFontFamilySel = fmt.makeSelect({ opts: _bdFontFamilyOptions(), value: _bdNormalizeFontFamily(style.fontFamily), onChange: (v) => setField('fontFamily', v) });
    lineFontFamilySel.classList.add('bd-font-family-select');
    tag('fontFamily')(lineFontFamilySel);
    lrow3.appendChild(fmt.makeGroup([fmt.makeLabel('フォント'), lineFontFamilySel]));
  }
  container.appendChild(lrow3);
  // 沿線回転 ON のときは labelBgColor / labelBorderColor / labelBorderWidth を非活性化
  // (SVG textPath では背景 / 枠線を描画できない)
  if (textAlongPath) {
    [labelBgSw, labelBorderSw, labelBorderWInp].forEach(el => {
      if (!el) return;
      el.disabled = true;
      el.style.opacity = '0.4';
      el.style.cursor = 'not-allowed';
    });
    labelBgSw.title = 'テキスト背景色 (沿線回転 ON のときは使用されません)';
    labelBorderSw.title = 'テキスト枠線色 (沿線回転 ON のときは使用されません)';
    labelBorderWInp.title = 'テキスト枠線太さ (沿線回転 ON のときは使用されません)';
  }

  // --- Row 4: 沿線回転 / 自動反転 ---
  const lrow4 = fmt.makeRow({ wrap: true });
  const alongCb = tag('textAlongPath')(fmt.makeCheckbox({
    text: '沿線回転', title: '沿線回転', checked: textAlongPath, onChange: (on) => setField('textAlongPath', on),
  }));
  lrow4.appendChild(alongCb);
  const flipCb = tag('textAutoFlip')(fmt.makeCheckbox({
    text: '自動反転', title: '自動反転 (90〜270°で読みやすい向きへ)', checked: textAutoFlip, onChange: (on) => setField('textAutoFlip', on),
  }));
  if (!textAlongPath) flipCb.style.opacity = '0.4';
  lrow4.appendChild(flipCb);
  container.appendChild(lrow4);
  // textVisible=false の時、他のテキスト系項目全体の透明度を下げる (視覚的な非活性化)
  if (!textVisible) {
    [lrow3, lrow4].forEach(row => {
      [...row.children].forEach(el => { el.style.opacity = '0.4'; });
    });
  }

  // 「テキストをラインに合わせる」はボードツールバー（フィルタメニュー）の表示トグルへ移行
  // （D-4、計画書 §4-3-A）
  // リセットボタンは詳細パネルの style-row に移動 (2026-04-18)
}

function bdDepthStyleLabel(index, total) {
  const nextIndex = Math.max(0, index | 0);
  const count = Math.max(1, total | 0);
  if (nextIndex === count - 1) return `深さ${nextIndex}+`;
  return `深さ${nextIndex}`;
}

function bdDepthStyleDisplayName(style, index, total) {
  const custom = String(style?.name || '').trim();
  if (custom) return custom;
  return `階層 ${Math.max(0, index | 0) + 1}`;
}

function _bdDepthStyleTooltip(style, index, total) {
  const label = bdDepthStyleDisplayName(style, index, total) || bdDepthStyleLabel(index, total);
  const fontSize = Math.max(8, +style?.fontSize || 13);
  const width = Math.max(40, +style?.width || 160);
  return `${label}\n文字 ${fontSize}px / 幅 ${width}px`;
}

function _bdDepthStylePreviewHtml(style) {
  const cardHtml = _bdCardStylePreviewHtml({
    bgColor: style?.bgColor || '',
    textColor: style?.textColor || '',
    borderColor: style?.borderColor || '',
    borderWidth: Number.isFinite(+style?.borderWidth) ? +style.borderWidth : 0,
    borderRadius: Number.isFinite(+style?.borderRadius) ? +style.borderRadius : 8,
    fontBold: !!style?.fontBold,
    fontItalic: !!style?.fontItalic,
    fontFamily: style?.fontFamily || '',
    textStrokeColor: style?.textStrokeColor || '',
    textStrokeWidth: Number.isFinite(+style?.textStrokeWidth) ? +style.textStrokeWidth : 0,
    shape: style?.shape || '',
    cloudBumpWidth: Number.isFinite(+style?.cloudBumpWidth) ? +style.cloudBumpWidth : 40,
    cloudBumpHeight: Number.isFinite(+style?.cloudBumpHeight) ? +style.cloudBumpHeight : 16,
    cloudSideWidth: Number.isFinite(+style?.cloudSideWidth) ? +style.cloudSideWidth : 12,
    cloudOffset: Number.isFinite(+style?.cloudOffset) ? +style.cloudOffset : 0.5,
    cloudSubWidthRatio: Number.isFinite(+style?.cloudSubWidthRatio) ? +style.cloudSubWidthRatio : 0,
    cloudSubHeightRatio: Number.isFinite(+style?.cloudSubHeightRatio) ? +style.cloudSubHeightRatio : 0,
  }).replace('Aa', '深');
  // 階層間ラインのプレビューを横に並べる。style.line が空（未設定）でも既定の薄いラインは出す。
  const linePreviewStyle = {
    color: style?.line?.color || '',
    width: Number.isFinite(+style?.line?.width) && +style.line.width > 0 ? +style.line.width : 2,
    style: style?.line?.style || '',
    arrow: style?.line?.arrow || '',
    pathType: style?.line?.pathType || 'curve',
    fontFamily: style?.line?.fontFamily || '',
  };
  const lineHtml = _bdLineStylePreviewHtml(linePreviewStyle);
  return `<span class="bd-depth-preview-group"><span class="bd-depth-preview-swatch">${cardHtml}</span><span class="bd-depth-preview-swatch bd-depth-preview-line">${lineHtml}</span></span>`;
}

function _bdNextStyle(kind, styles) {
  const cardDefaults = typeof bdDefaultCardStylesForBoard === 'function'
    ? bdDefaultCardStylesForBoard(typeof bd !== 'undefined' ? bd : undefined)
    : BD_DEFAULT_CARD_STYLES;
  const lineDefaults = typeof bdDefaultLineStylesForBoard === 'function'
    ? bdDefaultLineStylesForBoard(typeof bd !== 'undefined' ? bd : undefined)
    : BD_DEFAULT_LINE_STYLES;
  const seed = kind === 'card' ? _bdClone(cardDefaults[0]) : _bdClone(lineDefaults[0]);
  const baseName = kind === 'card' ? '新しいカードスタイル' : '新しいラインスタイル';
  seed.name = _bdMakeUniqueStyleName(baseName, styles);
  seed.id = _bdNormalizeStyleId(`${kind}-style-${Date.now().toString(36)}`, `${kind}-style`);
  styles.push(seed);
  return seed;
}

function _bdApplyAllAutoStyles() {
  if (typeof bdApplyAutoStyle !== 'function') return;
  bd.nodes.filter(node => node._autoStyle).forEach(node => bdApplyAutoStyle(node.id));
}
/* gb-board-style-manager.part02.js: split from gb-board-style-manager.js */
// ============================================================
//  In-panel スタイル管理タブ & ドロップダウンポップアップ
// ============================================================

// ドロップダウンポップアップ (card/line 用)。ピッカー要素をアンカーにして
// 上または下にスタイル一覧 + アクションボタンを表示する。
let _bdStyleManagerPopup = null;
let _bdStyleManagerPopupAnchor = null;
let _bdStyleManagerPopupCloseHandler = null;
let _bdStyleManagerPopupDragId = null;
// 階層別スタイルタブで編集中の階層 index を保存する。
// bdRefreshSelectionDetails(true) → clearBoardDetailTabContent() でタブ DOM が
// 一旦空にされ、_bdEnsureBoardStyleManagerTabs() が再描画する際、selectedIndex を
// 渡さないと既定の 0 (階層1) に戻ってしまうため、UI 状態として保持する。
let _bdLastDepthEditIndex = 0;
// カードスタイル / ラインスタイルタブで編集中のスタイル id も同様に保存する。
// 何も選んでいない (= active) ときは null。selectedId 未指定時のフォールバックに使う。
let _bdLastCardEditId = null;
let _bdLastLineEditId = null;

function _bdSetStyleManagerPopupAnchorState(anchor, expanded) {
  if (!anchor?.setAttribute) return;
  anchor.setAttribute('aria-haspopup', 'dialog');
  anchor.setAttribute('aria-expanded', expanded ? 'true' : 'false');
}

function _bdCloseStyleManagerPopup(options) {
  const anchor = _bdStyleManagerPopupAnchor;
  _bdSetStyleManagerPopupAnchorState(anchor, false);
  _bdStyleManagerPopup?.remove();
  _bdStyleManagerPopup = null;
  _bdStyleManagerPopupAnchor = null;
  if (_bdStyleManagerPopupCloseHandler) {
    document.removeEventListener('pointerdown', _bdStyleManagerPopupCloseHandler);
    _bdStyleManagerPopupCloseHandler = null;
  }
  if (options?.restoreFocus) _bdFocusStyleManagerPopupAnchor(anchor);
}

function _bdConfigureStyleManagerPopup(popup, label, anchorEl) {
  if (!popup) return;
  popup.setAttribute('role', 'dialog');
  popup.setAttribute('aria-label', label);
  popup.setAttribute('aria-modal', 'false');
  popup.tabIndex = -1;
  _bdSetStyleManagerPopupAnchorState(anchorEl, true);
}

function _bdStyleManagerPopupItems(popup) {
  return [...(popup?.querySelectorAll?.('.bd-style-list-item') || [])]
    .filter(item => item.isConnected && item.offsetParent !== null);
}

function _bdMoveStyleManagerPopupFocus(popup, direction) {
  const items = _bdStyleManagerPopupItems(popup);
  if (!items.length) return;
  const currentIndex = items.indexOf(document.activeElement);
  const nextIndex = currentIndex < 0
    ? (direction > 0 ? 0 : items.length - 1)
    : (currentIndex + direction + items.length) % items.length;
  items[nextIndex].focus();
}

function _bdBindStyleManagerPopupKeys(popup, getAnchor) {
  if (!popup || popup.dataset.bdStyleManagerKeys === '1') return;
  popup.dataset.bdStyleManagerKeys = '1';
  popup.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      _bdCloseStyleManagerPopup({ restoreFocus: true });
      return;
    }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      const targetItem = event.target?.closest?.('.bd-style-list-item');
      if (targetItem || event.target === popup) {
        event.preventDefault();
        _bdMoveStyleManagerPopupFocus(popup, event.key === 'ArrowDown' ? 1 : -1);
      }
      return;
    }
    if ((event.key === 'Enter' || event.key === ' ') && event.target?.closest?.('.bd-style-list-item')) {
      event.preventDefault();
      event.target.closest('.bd-style-list-item')?.click();
    }
  });
  popup.addEventListener('focusout', () => {
    const anchor = typeof getAnchor === 'function' ? getAnchor() : _bdStyleManagerPopupAnchor;
    _bdSetStyleManagerPopupAnchorState(anchor, !!popup.isConnected);
  });
}

function _bdPrepareStyleManagerPopupControls(popup) {
  popup?.querySelectorAll?.('.bd-detail-style-action').forEach(button => {
    const label = button.getAttribute('aria-label') || button.getAttribute('title') || button.textContent.trim();
    if (label) button.setAttribute('aria-label', label);
  });
}

function _bdStyleManagerPopupCloseButtonHtml() {
  if (typeof meldexDropdownCloseButtonHtml === 'function') {
    return meldexDropdownCloseButtonHtml({ className: 'bd-detail-style-action bd-style-manager-popup-close', attr: 'data-bd-popup-close' });
  }
  const closeIcon = typeof lucide === 'function' ? lucide('x', 14) : 'x';
  return `<button type="button" class="bd-detail-style-action bd-style-manager-popup-close" data-bd-popup-close title="閉じる" aria-label="閉じる">${closeIcon}</button>`;
}

function _bdFocusStyleManagerPopupAnchor(resolveAnchor) {
  const focus = () => { const el = typeof resolveAnchor === 'function' ? resolveAnchor() : resolveAnchor; if (!el?.isConnected || typeof el.focus !== 'function') return; try { el.focus({ preventScroll: true }); } catch (_) { el.focus(); } };
  focus(); setTimeout(focus, 0); if (typeof requestAnimationFrame === 'function') requestAnimationFrame(focus);
}

function _bdClampStyleManagerPopupToViewport(popup) {
  if (!popup?.getBoundingClientRect) return;
  const margin = 4;
  const viewportWidth = document.documentElement.clientWidth || window.innerWidth || 0;
  const viewportHeight = document.documentElement.clientHeight || window.innerHeight || 0;
  if (!viewportWidth || !viewportHeight) return;

  let rect = popup.getBoundingClientRect();
  const maxVisibleHeight = Math.max(120, viewportHeight - margin * 2);
  for (let i = 0; i < 4 && rect.height > maxVisibleHeight + 1; i += 1) {
    const computedMax = parseFloat(getComputedStyle(popup).maxHeight || '');
    const currentLimit = Number.isFinite(computedMax) && computedMax > 0 ? computedMax : rect.height;
    const cssToVisualRatio = Number.isFinite(computedMax) && computedMax > 0
      ? computedMax / Math.max(1, rect.height)
      : 1;
    const nextLimit = Math.min(currentLimit, Math.max(120, maxVisibleHeight * cssToVisualRatio * 0.98));
    popup.style.maxHeight = nextLimit + 'px';
    popup.style.height = nextLimit + 'px';
    popup.style.overflowY = 'auto';
    rect = popup.getBoundingClientRect();
  }

  const maxVisibleWidth = Math.max(160, viewportWidth - margin * 2);
  for (let i = 0; i < 4 && rect.width > maxVisibleWidth + 1; i += 1) {
    const computedMax = parseFloat(getComputedStyle(popup).maxWidth || '');
    const currentLimit = Number.isFinite(computedMax) && computedMax > 0 ? computedMax : rect.width;
    const cssToVisualRatio = Number.isFinite(computedMax) && computedMax > 0
      ? computedMax / Math.max(1, rect.width)
      : 1;
    const nextLimit = Math.min(currentLimit, Math.max(160, maxVisibleWidth * cssToVisualRatio * 0.98));
    popup.style.maxWidth = nextLimit + 'px';
    popup.style.width = nextLimit + 'px';
    popup.style.overflowX = 'auto';
    rect = popup.getBoundingClientRect();
  }

  let left = rect.left;
  let top = rect.top;
  if (rect.right > viewportWidth - margin) left = Math.max(margin, viewportWidth - rect.width - margin);
  if (rect.bottom > viewportHeight - margin) top = Math.max(margin, viewportHeight - rect.height - margin);
  if (left < margin) left = margin;
  if (top < margin) top = margin;
  popup.style.left = left + 'px';
  popup.style.top = top + 'px';
}

function _bdPositionStyleManagerPopup(popup, anchorEl) {
  if (!popup || !anchorEl?.getBoundingClientRect) return;
  const rect = anchorEl.getBoundingClientRect();
  if (typeof positionPopup === 'function') {
    positionPopup(popup, rect, { prefer: 'below', gap: 4 });
    _bdClampStyleManagerPopupToViewport(popup);
    return;
  }
  const zoom = typeof _getZoom === 'function' ? _getZoom() : 1;
  popup.style.left = (rect.left / zoom) + 'px';
  popup.style.top = (rect.bottom / zoom + 4) + 'px';
  if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
  _bdClampStyleManagerPopupToViewport(popup);
}

// card / line 用のスタイル選択ポップアップ。
// - options.onSelect(styleId): 選択時にタブ側を再描画するコールバック
// - options.kind: 'card' | 'line'
// - options.currentId: 現在タブで表示されているスタイル ID
// - options.refreshAnchor(): 再描画後に最新のアンカー要素 (ピッカーボタン) を返す。
//   タブの full re-render で旧アンカーが DOM 切断されると getBoundingClientRect() が
//   全 0 を返してしまい、ポップアップが画面左上に飛ぶのを防ぐために使う。
function _bdOpenStyleManagerPopup(kind, anchorEl, options) {
  if (!anchorEl) return;
  if (_bdStyleManagerPopup) {
    const same = _bdStyleManagerPopupAnchor === anchorEl;
    _bdCloseStyleManagerPopup();
    if (same) return;
  }
  bdEnsureBoardUiState();
  const opts = options || {};
  let currentAnchor = anchorEl;
  const popup = document.createElement('div');
  popup.className = 'bd-style-manager-popup';
  document.body.appendChild(popup);
  _bdStyleManagerPopup = popup;
  _bdStyleManagerPopupAnchor = currentAnchor;
  _bdConfigureStyleManagerPopup(popup, `${kind === 'card' ? 'カード' : 'ライン'}スタイル管理`, currentAnchor);
  _bdBindStyleManagerPopupKeys(popup, () => typeof opts.refreshAnchor === 'function' ? (opts.refreshAnchor() || currentAnchor) : currentAnchor);

  const render = () => {
    const displayStyles = _bdDisplayedManagedStyles(kind);
    const activeRef = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
    const activeStyleId = bd[activeRef] || '';
    const currentId = opts.currentId || activeStyleId;
    const itemLabel = kind === 'card' ? 'カードスタイル' : 'ラインスタイル';
    const plusIcon = typeof lucide === 'function' ? lucide('plus', 14) : '+';
    const copyIcon = typeof lucide === 'function' ? lucide('copy', 14) : '複製';
    const saveIcon = typeof lucide === 'function' ? lucide('save', 14) : '保存';
    const resetIcon = typeof lucide === 'function' ? lucide('rotateCcw', 14) : '戻す';
    const trashIcon = typeof lucide === 'function' ? lucide('trash2', 14) : '削除';
    const previewFn = kind === 'card' ? _bdCardStylePreviewHtml : _bdLineStylePreviewHtml;

    popup.innerHTML = `
      <div class="bd-style-manager-popup-list" role="listbox" aria-label="${_bdEscAttr(itemLabel)}一覧">
        ${displayStyles.map(style => `
          <div class="bd-style-list-item bd-style-list-item--draggable ${style.id === currentId ? 'active' : ''} ${style.id === activeStyleId ? 'is-applied' : ''}"
               data-bd-style-id="${_bdEscAttr(style.id)}" data-bd-style-item="${_bdEscAttr(style.id)}"
               draggable="true" tabindex="0" role="option" aria-selected="${style.id === currentId ? 'true' : 'false'}" aria-label="${_bdEscAttr(style.name || itemLabel)}">
            <span class="bd-style-list-handle" title="ドラッグして並べ替え">⋮⋮</span>
            <span class="bd-style-list-preview">${previewFn(style)}</span>
            <span class="bd-style-list-name">${esc(style.name)}</span>
            ${style.id === activeStyleId ? '<span class="bd-style-applied-mark" title="現在使用中">適用中</span>' : ''}
          </div>
        `).join('')}
      </div>
      <div class="bd-style-manager-popup-actions">
        <button type="button" class="bd-detail-style-action" data-bd-popup-add title="新しい${esc(itemLabel)}を追加" aria-label="新しい${esc(itemLabel)}を追加">${plusIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-duplicate title="複製" aria-label="複製">${copyIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-save title="現在の設定をデフォルトとして保存" aria-label="現在の設定をデフォルトとして保存">${saveIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-reset title="デフォルトに戻す" aria-label="デフォルトに戻す">${resetIcon}</button>
        <button type="button" class="bd-detail-style-action bd-detail-style-action--danger" data-bd-popup-delete title="削除" aria-label="削除" ${displayStyles.length <= 1 ? 'disabled' : ''}>${trashIcon}</button>
        ${_bdStyleManagerPopupCloseButtonHtml()}
      </div>`;

    // 位置決定: アンカーの下に出す (ピッカーが上部にあるので drop-down 優先)。
    // タブが re-render されて旧 anchor が DOM 切断されている場合は refreshAnchor で再取得し、
    // それでも取れなければ最後に有効だった矩形にフォールバックする。
    if (typeof opts.refreshAnchor === 'function') {
      const next = opts.refreshAnchor();
      if (next) {
        currentAnchor = next;
        _bdStyleManagerPopupAnchor = next;
      }
    }
    _bdPositionStyleManagerPopup(popup, currentAnchor);
    _bdSetStyleManagerPopupAnchorState(currentAnchor, true);
    _bdPrepareStyleManagerPopupControls(popup);

    // リスト項目クリックでアクティブ選択変更
    popup.querySelectorAll('[data-bd-style-id]').forEach(item => {
      item.addEventListener('click', () => {
        const id = item.dataset.bdStyleId;
        opts.currentId = id;
        if (typeof opts.onSelect === 'function') opts.onSelect(id);
        render();
      });
    });
    popup.querySelector('[data-bd-popup-close]')?.addEventListener('click', () => {
      _bdCloseStyleManagerPopup({ restoreFocus: true });
    });

    // D&D
    popup.querySelectorAll('[data-bd-style-item]').forEach(item => {
      item.addEventListener('dragstart', event => {
        _bdStyleManagerPopupDragId = item.dataset.bdStyleItem || null;
        item.classList.add('dragging');
        try { event.dataTransfer?.setData('text/plain', _bdStyleManagerPopupDragId || ''); } catch (_) {}
        if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
      });
      item.addEventListener('dragend', () => {
        _bdStyleManagerPopupDragId = null;
        popup.querySelectorAll('[data-bd-style-item]').forEach(el => el.classList.remove('dragging', 'drag-over'));
      });
      item.addEventListener('dragover', event => {
        if (!_bdStyleManagerPopupDragId) return;
        event.preventDefault();
        if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        item.classList.add('drag-over');
      });
      item.addEventListener('dragleave', () => { item.classList.remove('drag-over'); });
      item.addEventListener('drop', event => {
        event.preventDefault();
        item.classList.remove('drag-over');
        const draggedId = _bdStyleManagerPopupDragId;
        const targetId = item.dataset.bdStyleItem || '';
        _bdStyleManagerPopupDragId = null;
        if (!draggedId || !targetId || draggedId === targetId) return;
        const arr = kind === 'card' ? bd.cardStyles : bd.lineStyles;
        const fromIdx = arr.findIndex(s => s.id === draggedId);
        const toIdx = arr.findIndex(s => s.id === targetId);
        if (fromIdx < 0 || toIdx < 0) return;
        bdPushUndo();
        const [moved] = arr.splice(fromIdx, 1);
        const finalIdx = fromIdx < toIdx ? toIdx - 1 : toIdx;
        arr.splice(finalIdx, 0, moved);
        bdDirty();
        bdRender();
        bdRefreshBoardToolbar();
        if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
        render();
        if (typeof opts.onListChange === 'function') opts.onListChange(draggedId);
      });
    });

    const liveArr = () => kind === 'card' ? bd.cardStyles : bd.lineStyles;
    const currentLive = () => liveArr().find(s => s.id === (opts.currentId || activeStyleId)) || liveArr()[0];

    popup.querySelector('[data-bd-popup-add]')?.addEventListener('click', () => {
      bdPushUndo();
      const next = _bdNextStyle(kind, liveArr());
      bdDirty();
      opts.currentId = next.id;
      bdRefreshBoardToolbar();
      if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
      if (typeof opts.onSelect === 'function') opts.onSelect(next.id);
      render();
    });

    popup.querySelector('[data-bd-popup-duplicate]')?.addEventListener('click', () => {
      const arr = liveArr();
      const live = currentLive(); if (!live) return;
      bdPushUndo();
      const next = _bdClone(live);
      next.id = _bdNormalizeStyleId(`${live.id}-copy-${Date.now().toString(36)}`, `${kind}-style-copy`);
      next.name = _bdMakeUniqueStyleName(`${live.name} コピー`, arr);
      arr.push(next);
      bdDirty();
      opts.currentId = next.id;
      bdRefreshBoardToolbar();
      if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
      if (typeof opts.onSelect === 'function') opts.onSelect(next.id);
      render();
    });

    popup.querySelector('[data-bd-popup-save]')?.addEventListener('click', () => {
      const live = currentLive(); if (!live) return;
      bdPushUndo();
      live._default = _bdCloneStyleForDefault(live);
      _bdSaveGlobalStyleDefault(kind, live);
      bdDirty();
      showStatus(`${kind === 'card' ? 'カード' : 'ライン'}スタイル「${live.name}」をデフォルトとして保存しました`, false, { showSaveDialog: true });
      render();
    });

    popup.querySelector('[data-bd-popup-reset]')?.addEventListener('click', () => {
      const live = currentLive(); if (!live) return;
      bdPushUndo();
      _bdResetStyleToDefault(kind, live);
      bdDirty();
      bdRender();
      bdRefreshBoardToolbar();
      if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
      if (typeof opts.onSelect === 'function') opts.onSelect(live.id);
      render();
      showStatus(`${kind === 'card' ? 'カード' : 'ライン'}スタイル「${live.name}」をデフォルトに戻しました`);
    });

    popup.querySelector('[data-bd-popup-delete]')?.addEventListener('click', async () => {
      if (liveArr().length <= 1) return;
      const live = currentLive(); if (!live) return;
      const activeRefKey = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
      const unitLabel = kind === 'card' ? 'カード' : 'ライン';
      const usage = _bdCountStyleUsage(kind, live.id);
      const usageMsg = usage > 0 ? `\n\nこのスタイルは ${usage} 個の${unitLabel}で使用中です。削除すると、それらは別のスタイルに切り替わります。` : '';
      const ok = typeof cfConfirm === 'function' ? await cfConfirm(`${kind === 'card' ? 'カード' : 'ライン'}スタイル「${live.name}」を削除しますか？${usageMsg}`) : true;
      if (!ok) return;
      const arr = liveArr();
      const liveIndex = arr.findIndex(style => style.id === live.id);
      if (liveIndex < 0) return;
      bdPushUndo();
      const removedId = arr[liveIndex].id;
      arr.splice(liveIndex, 1);
      _bdRemoveGlobalStyleDefault(kind, removedId);
      const remainingDisplay = _bdDisplayedManagedStyles(kind);
      const fallbackId = remainingDisplay[0]?.id || arr[0]?.id || '';
      if (bd[activeRefKey] === removedId) bd[activeRefKey] = fallbackId;
      if (kind === 'card') {
        (bd.nodes || []).forEach(node => { if (node && node.cardStyle === removedId) node.cardStyle = fallbackId; });
      } else {
        (bd.connections || []).forEach(conn => { if (conn && conn.styleRef === removedId) conn.styleRef = fallbackId; });
      }
      if (typeof _bdReplaceDeletedStyleRefsInDepthStyles === 'function') {
        _bdReplaceDeletedStyleRefsInDepthStyles(kind, removedId, fallbackId);
      }
      bdDirty();
      bdRender();
      bdRefreshBoardToolbar();
      if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
      opts.currentId = fallbackId;
      if (typeof opts.onSelect === 'function') opts.onSelect(fallbackId);
      render();
      showStatus(`${kind === 'card' ? 'カード' : 'ライン'}スタイル「${live.name}」を削除しました`);
    });
  };

  render();

  setTimeout(() => {
    _bdStyleManagerPopupCloseHandler = event => {
      if (!_bdStyleManagerPopup) return;
      const anchor = _bdStyleManagerPopupAnchor || currentAnchor;
      if (!_bdStyleManagerPopup.contains(event.target) && !(anchor && anchor.contains(event.target))) {
        _bdCloseStyleManagerPopup();
      }
    };
    document.addEventListener('pointerdown', _bdStyleManagerPopupCloseHandler);
  }, 0);
}

// 指定 kind のスタイル管理をオプションパネルのタブ内にレンダリングする。
// 上部: ピッカーボタン (クリックでドロップダウンポップアップが開く: list + actions)
// 下部: 選択中スタイルの編集フィールド (左カラムの大きなプレビュー枠は廃止)
// mode === 'diff' はフィールド入力途中の再描画用。container.innerHTML を作り直すと
// 入力中の <input> がガベコレされ、フォーカスと IME 変換候補が飛ぶので、
// メタ・ピッカー表示だけを差分更新する。
// style 追加/削除/複製/reset やピッカー経由の選択変更時は 'full' で呼び、全再構築する。
function _bdRenderStyleManagerInPanel(kind, container, selectedId, mode) {
  if (!container) return;
  bdEnsureBoardUiState();
  const activeRef = kind === 'card' ? 'activeCardStyle' : 'activeLineStyle';
  const displayStyles = _bdDisplayedManagedStyles(kind);
  if (!displayStyles.length) {
    container.innerHTML = `<div class="bd-detail-hint">表示できるスタイルがありません。</div>`;
    return;
  }
  // selectedId 未指定時は、最後に編集していた id → active style → 先頭の順で採用する。
  // bdRefreshSelectionDetails(true) によるタブ再描画で active style へ強制復帰しないようにする。
  const lastIdRef = kind === 'card' ? _bdLastCardEditId : _bdLastLineEditId;
  const effectiveId = selectedId || lastIdRef || bd[activeRef] || displayStyles[0].id;
  const selected = displayStyles.find(s => s.id === effectiveId) || displayStyles[0];
  if (kind === 'card') _bdLastCardEditId = selected.id;
  else _bdLastLineEditId = selected.id;
  const itemLabel = kind === 'card' ? 'カードスタイル' : 'ラインスタイル';
  const unitLabel = kind === 'card' ? 'カード' : 'ライン';
  const activeStyleId = bd[activeRef] || '';
  const isSelectedActive = selected.id === activeStyleId;
  const usageCount = _bdCountStyleUsage(kind, selected.id);
  const previewFn = kind === 'card' ? _bdCardStylePreviewHtml : _bdLineStylePreviewHtml;
  const metaText = `${selected.name} ・ ${usageCount > 0 ? `${usageCount} 個の${unitLabel}が使用中` : `使用中の${unitLabel}なし`}${isSelectedActive ? ' ・ 現在使用中' : ''}`;
  const pickerLabelText = `${selected.name}${isSelectedActive ? ' (適用中)' : ''}`;
  const exportIcon = typeof lucide === 'function' ? lucide('download', 14) : '書出';

  if (mode === 'diff' && container.querySelector('[data-bd-style-in-panel]')) {
    const metaEl = container.querySelector('.bd-style-editor-meta');
    if (metaEl) metaEl.textContent = metaText;
    const pickerPreview = container.querySelector('.bd-style-picker-preview');
    if (pickerPreview) pickerPreview.innerHTML = previewFn(selected);
    const pickerLabel = container.querySelector('.bd-style-picker-label');
    if (pickerLabel) pickerLabel.textContent = pickerLabelText;
    const pickerBtn = container.querySelector('[data-bd-style-panel-picker]');
    if (pickerBtn) pickerBtn.dataset.bdCurrentStyleId = selected.id;
    return;
  }

  // プレビュードロップダウン (ピッカー) は最上部、編集フィールドはその下に。
  // 上段の大きなプレビュー枠は削除し、設定項目を縦 1 カラムで詰めて表示する。
  container.innerHTML = `
    <div class="bd-detail-panel bd-style-in-panel" data-bd-style-in-panel="${_bdEscAttr(kind)}">
      <div class="bd-detail-section">
        <div class="bd-detail-section-title">${esc(itemLabel)}一覧を開く</div>
        <button type="button" class="bd-style-panel-picker" data-bd-style-panel-picker="${_bdEscAttr(kind)}" data-bd-current-style-id="${_bdEscAttr(selected.id)}" aria-label="${esc(itemLabel)}一覧を開く" aria-haspopup="dialog" aria-expanded="false">
          <span class="bd-style-picker-preview">${previewFn(selected)}</span>
          <span class="bd-style-picker-label">${esc(pickerLabelText)}</span>
          <span class="bd-style-picker-caret" aria-hidden="true">▾</span>
        </button>
        <button type="button" class="bd-detail-style-action" data-e2e-id="bd-style-panel-export-board-styles" data-bd-style-panel-export-board-styles title="ボードスタイルを書き出し" aria-label="ボードスタイルを書き出し">${exportIcon}</button>
      </div>
      <div class="bd-detail-section">
        <div class="bd-detail-section-title">${esc(itemLabel)}</div>
        <div class="bd-style-editor-fields bd-style-editor-fields--fmt" data-bd-panel-fields></div>
        <div class="bd-style-editor-meta">${esc(metaText)}</div>
      </div>
    </div>`;

  const fieldsEl = container.querySelector('[data-bd-panel-fields]');
  // beforeEdit: bdEnsureBoardUiState / bdNormalize*Styles は呼び出しごとに bd.cardStyles /
  // bd.lineStyles を新配列 + 新オブジェクトへ差し替えるため、closure で掴んだ OLD selected は
  // 1 回目の diff 再レンダー後に orphan になる。2 回目以降のフィールド編集で OLD を
  // mutate すると mutation が bd.*Styles へ伝播せず失われる。毎回 ID から live な参照を
  // 取り直すことで、fields を再構築しない diff モードでも mutation が正しく保存される。
  _bdBuildStyleFields(fieldsEl, kind, selected, (field) => {
    const needsFullRebuild = typeof _bdStyleFieldNeedsFullRebuild === 'function'
      && _bdStyleFieldNeedsFullRebuild(kind, field);
    bdDirty();
    if (field === 'fontFamily') {
      if (typeof bdScheduleFontStyleMapUpdate === 'function') bdScheduleFontStyleMapUpdate();
    } else {
      bdRender();
    }
    _bdRenderStyleManagerInPanel(kind, container, selected.id, needsFullRebuild ? undefined : 'diff');
    bdRefreshBoardToolbar();
    if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  }, {
    e2eScope: `${kind}-panel-${selected.id}`,
    beforeEdit: () => {
      const arr = kind === 'card' ? bd.cardStyles : bd.lineStyles;
      return (arr || []).find(s => s.id === selected.id) || (arr || [])[0] || null;
    },
  });

  const pickerBtn = container.querySelector('[data-bd-style-panel-picker]');
  container.querySelector('[data-bd-style-panel-export-board-styles]')?.addEventListener('click', () => {
    if (typeof bdExportBoardStylePack === 'function') bdExportBoardStylePack();
    else if (typeof showStatus === 'function') showStatus('ボードスタイル書き出し機能を初期化できませんでした', true);
  });
  pickerBtn?.addEventListener('click', () => {
    _bdOpenStyleManagerPopup(kind, pickerBtn, {
      currentId: selected.id,
      onSelect: (styleId) => {
        _bdRenderStyleManagerInPanel(kind, container, styleId);
      },
      onListChange: (styleId) => {
        _bdRenderStyleManagerInPanel(kind, container, styleId);
      },
      // タブ再描画でピッカーボタンが新規 DOM に置き換わるため、ポップアップ
      // 位置計算前に最新の DOM を取り直す。これがないと旧ボタンの矩形 (0,0,0,0)
      // が使われてポップアップが画面左上に飛ぶ。
      refreshAnchor: () => container.querySelector('[data-bd-style-panel-picker]'),
    });
  });
  if (typeof bindMeldexDropdownKeySwitch === 'function') {
    bindMeldexDropdownKeySwitch(pickerBtn, {
      getItems: () => _bdDisplayedManagedStyles(kind).map(style => ({ value: style.id, style })),
      getCurrentValue: () => pickerBtn.dataset.bdCurrentStyleId || selected.id,
      onSelect: item => _bdRenderStyleManagerInPanel(kind, container, item.value),
      getFreshTrigger: () => container.querySelector('[data-bd-style-panel-picker]'),
    });
  }
}

function _bdDepthPickerLabel(style, index, total) {
  const name = typeof bdDepthStyleDisplayName === 'function'
    ? bdDepthStyleDisplayName(style, index, total)
    : `階層 ${Math.max(0, index | 0) + 1}`;
  const defaultText = style?.defaultText ? ` (${style.defaultText})` : '';
  return `${name}${defaultText}`;
}

function _bdStyleRefOptions(kind) {
  const styles = typeof _bdDisplayedManagedStyles === 'function'
    ? _bdDisplayedManagedStyles(kind)
    : (kind === 'card' ? (bd.cardStyles || []) : (bd.lineStyles || []));
  const label = kind === 'card' ? '個別カード設定' : '個別ライン設定';
  return [
    { v: '', l: label },
    ...(styles || []).map(style => ({ v: style.id || '', l: style.name || style.id || 'スタイル' })),
  ];
}

function _bdApplyStyleRefToDepth(depth, kind, styleId) {
  if (!depth) return;
  const id = String(styleId || '');
  if (kind === 'card') {
    depth.cardStyleRef = id;
    if (!id) return;
    const source = (bd.cardStyles || []).find(style => style && style.id === id);
    const snap = typeof _bdCloneStyleForDefault === 'function'
      ? _bdCloneStyleForDefault(source)
      : (source ? { ...source } : null);
    if (!snap) return;
    Object.keys(snap).forEach(key => { depth[key] = snap[key]; });
    return;
  }
  depth.lineStyleRef = id;
  if (!depth.line || typeof depth.line !== 'object') depth.line = {};
  if (!id) return;
  const source = (bd.lineStyles || []).find(style => style && style.id === id);
  const snap = typeof _bdCloneStyleForDefault === 'function'
    ? _bdCloneStyleForDefault(source)
    : (source ? { ...source } : null);
  if (!snap) return;
  Object.keys(snap).forEach(key => { depth.line[key] = snap[key]; });
}

function _bdReplaceDeletedStyleRefsInDepthStyles(kind, removedId, fallbackId) {
  if (!removedId || typeof bd === 'undefined') return;
  const key = kind === 'card' ? 'cardStyleRef' : 'lineStyleRef';
  (bd.depthStyles || []).forEach(depth => {
    if (!depth || depth[key] !== removedId) return;
    _bdApplyStyleRefToDepth(depth, kind, fallbackId || '');
  });
}

function _bdAppendDepthStyleRefRow(container, kind, selected, liveDepth, onApply) {
  const fmt = window.gbFmt;
  if (!container || !fmt) return;
  const row = fmt.makeRow({ wrap: true });
  row.classList.add('bd-depth-style-ref-row');
  const label = fmt.makeLabel(kind === 'card' ? '元カードスタイル' : '元ラインスタイル');
  const value = kind === 'card' ? (selected.cardStyleRef || '') : (selected.lineStyleRef || '');
  const select = fmt.makeSelect({
    opts: _bdStyleRefOptions(kind),
    value,
    onChange: (nextId) => {
      const live = typeof liveDepth === 'function' ? liveDepth() : selected;
      if (!live) return;
      if (typeof bdPushUndo === 'function') bdPushUndo();
      _bdApplyStyleRefToDepth(live, kind, nextId);
      if (typeof onApply === 'function') onApply();
    },
  });
  select.setAttribute('data-bd-depth-style-ref', kind);
  select.setAttribute('data-e2e-id', `bd-depth-${kind}-style-ref`);
  row.appendChild(label);
  row.appendChild(select);
  container.appendChild(row);
}

// 階層別スタイル用の in-panel 版。mode は _bdRenderStyleManagerInPanel と同じ役割で
// 'diff' のときは入力中のフォーカスを壊さないよう差分更新のみ行う。
function _bdRenderDepthStyleInPanel(container, selectedIndex, mode) {
  if (!container) return;
  if (typeof bdEnsureDepthStyles === 'function') bdEnsureDepthStyles();
  const styles = bd.depthStyles || [];
  if (!styles.length) {
    bd.depthStyles = typeof bdNormalizeDepthStyles === 'function' ? bdNormalizeDepthStyles([]) : [];
  }
  const liveStyles = () => bd.depthStyles || [];
  // selectedIndex 未指定時は、最後に編集していた階層 index を採用する。
  // これがないと bdRefreshSelectionDetails(true) で発生するタブ再描画のたびに
  // 0 (階層1) に戻ってしまい、ライン色等の編集中に「階層1に戻された」ように見える。
  const fallbackIdx = Number.isFinite(+_bdLastDepthEditIndex) ? +_bdLastDepthEditIndex : 0;
  const rawIdx = Number.isFinite(+selectedIndex) ? +selectedIndex : fallbackIdx;
  const idx = Math.max(0, Math.min(rawIdx, liveStyles().length - 1));
  _bdLastDepthEditIndex = idx;
  const selected = liveStyles()[idx] || liveStyles()[0];
  const previewHtml = _bdDepthStylePreviewHtml(selected);
  const pickerLabelText = _bdDepthPickerLabel(selected, idx, liveStyles().length);

  if (mode === 'diff' && container.querySelector('[data-bd-style-in-panel="depth"]')) {
    const pickerPreview = container.querySelector('.bd-style-picker-preview');
    if (pickerPreview) pickerPreview.innerHTML = previewHtml;
    const pickerLabel = container.querySelector('.bd-style-picker-label');
    if (pickerLabel) pickerLabel.textContent = pickerLabelText;
    const pickerBtn = container.querySelector('[data-bd-depth-panel-picker]');
    if (pickerBtn) pickerBtn.dataset.bdDepthCurrentIndex = String(idx);
    const nameInput = container.querySelector('[data-bd-depth-name]');
    if (nameInput && document.activeElement !== nameInput) nameInput.value = selected?.name || '';
    const cardRef = container.querySelector('[data-bd-depth-style-ref="card"]');
    if (cardRef && document.activeElement !== cardRef) cardRef.value = selected?.cardStyleRef || '';
    const lineRef = container.querySelector('[data-bd-depth-style-ref="line"]');
    if (lineRef && document.activeElement !== lineRef) lineRef.value = selected?.lineStyleRef || '';
    return;
  }

  // プレビュードロップダウン (ピッカー) は最上部、編集フィールドはその下に。
  // 上段の大きなプレビュー枠は削除し、設定項目を縦 1 カラムで詰めて表示する。
  container.innerHTML = `
    <div class="bd-detail-panel bd-style-in-panel bd-depth-in-panel" data-bd-style-in-panel="depth">
      <div class="bd-detail-section">
        <div class="bd-detail-section-title">階層一覧を開く</div>
        <div class="bd-detail-style-row">
          <button type="button" class="bd-style-panel-picker" data-bd-depth-panel-picker="depth" data-bd-depth-current-index="${idx}" aria-label="階層一覧を開く" aria-haspopup="dialog" aria-expanded="false">
            <span class="bd-style-picker-preview">${previewHtml}</span>
            <span class="bd-style-picker-label">${esc(pickerLabelText)}</span>
            <span class="bd-style-picker-caret" aria-hidden="true">▾</span>
          </button>
          <button type="button" class="bd-detail-style-action" data-bd-depth-apply-theme title="テーマカラーを階層別スタイルに適用">${typeof lucide === 'function' ? lucide('palette', 14) : '色'}</button>
        </div>
      </div>
      <div class="bd-detail-section">
        <div class="bd-detail-section-title">階層別スタイル</div>
        <div class="bd-style-editor-fields bd-style-editor-fields--fmt bd-depth-fields" data-bd-depth-fields></div>
      </div>
    </div>`;

  const depthFieldsEl = container.querySelector('[data-bd-depth-fields]');
  const applyDepthStyles = (options = {}) => {
    if (typeof bdNormalizeDepthStyles === 'function') bd.depthStyles = bdNormalizeDepthStyles(bd.depthStyles);
    if (!options.fontOnly) _bdApplyAllAutoStyles();
    bdDirty();
    if (options.fontOnly) {
      if (typeof bdScheduleFontStyleMapUpdate === 'function') bdScheduleFontStyleMapUpdate();
    } else {
      bdRender();
    }
    bdRefreshBoardToolbar();
    if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  };
  if (depthFieldsEl && selected && window.gbFmt) {
    const depthEmit = (styleKind, field) => {
      const needsFullRebuild = typeof _bdStyleFieldNeedsFullRebuild === 'function'
        && _bdStyleFieldNeedsFullRebuild(styleKind, field);
      applyDepthStyles({ fontOnly: field === 'fontFamily' });
      _bdRenderDepthStyleInPanel(container, idx, needsFullRebuild ? undefined : 'diff');
    };
    // bdNormalizeDepthStyles が applyDepthStyles の度に bd.depthStyles[idx] を新オブジェクトに
    // 差し替えるため、closure の selected / selected.line は 1 回目の diff 再レンダー後に orphan
    // となる。fields を再構築しない diff モードでは、beforeEdit で毎回 idx から live な参照を
    // 取り直さないと 2 回目以降のフィールド編集 mutation が保存されない。
    const liveDepth = () => (bd.depthStyles || [])[idx] || null;
    const fmt = window.gbFmt;

    const nameRow = document.createElement('div');
    nameRow.className = 'bd-style-name-row bd-depth-style-name-row';
    const nameLbl = document.createElement('span');
    nameLbl.className = 'gb-fmt-label';
    nameLbl.textContent = '階層別スタイル名';
    const nameInp = document.createElement('input');
    nameInp.type = 'text';
    nameInp.value = selected.name || '';
    nameInp.placeholder = `階層 ${idx + 1}`;
    nameInp.className = 'bd-style-name-input';
    nameInp.setAttribute('data-bd-depth-name', 'true');
    nameInp.setAttribute('data-e2e-id', `bd-depth-panel-${idx}-name`);
    nameInp.setAttribute('aria-label', '階層別スタイル名');
    nameInp.addEventListener('change', () => {
      const live = liveDepth();
      if (!live) return;
      const nextName = String(nameInp.value || '').trim();
      if ((live.name || '') === nextName) return;
      if (typeof bdPushUndo === 'function') bdPushUndo();
      live.name = nextName;
      depthEmit('', undefined);
    });
    nameRow.append(nameLbl, nameInp);
    depthFieldsEl.appendChild(nameRow);

    // カードスタイル部
    const cardHeader = document.createElement('div');
    cardHeader.className = 'bd-detail-section-title';
    cardHeader.textContent = 'カードスタイル';
    depthFieldsEl.appendChild(cardHeader);
    _bdAppendDepthStyleRefRow(depthFieldsEl, 'card', selected, liveDepth, () => {
      applyDepthStyles();
      _bdRenderDepthStyleInPanel(container, idx);
    });
    const cardFieldsWrap = document.createElement('div');
    cardFieldsWrap.className = 'bd-depth-style-field-group';
    depthFieldsEl.appendChild(cardFieldsWrap);
    _bdBuildStyleFields(cardFieldsWrap, 'card', selected, field => depthEmit('card', field), {
      hideName: true,
      e2eScope: `depth-panel-${idx}-card`,
      beforeEdit: liveDepth,
    });

    // デフォルトテキスト
    const defRow = fmt.makeRow({ wrap: true });
    const defInput = document.createElement('input');
    defInput.type = 'text';
    defInput.value = selected.defaultText != null ? selected.defaultText : 'カード';
    defInput.placeholder = 'カード追加時に自動で入る文字';
    defInput.title = '新規カード追加時のテキスト';
    defInput.style.cssText = 'flex:1;min-width:160px;padding:3px 6px;background:var(--bg);color:var(--fg);border:1px solid var(--border);border-radius:3px;font-size:12px;';
    defInput.addEventListener('change', () => {
      if (typeof bdPushUndo === 'function') bdPushUndo();
      // 同じく orphan 回避のため、書き込み直前に live 参照を取り直す。
      const live = liveDepth();
      if (live) live.defaultText = defInput.value;
      depthEmit('', undefined);
    });
    defRow.appendChild(fmt.makeLabel('デフォルトテキスト'));
    defRow.appendChild(defInput);
    depthFieldsEl.appendChild(defRow);

    // ラインスタイル部
    const lineHeader = document.createElement('div');
    lineHeader.className = 'bd-detail-section-title';
    lineHeader.style.marginTop = '12px';
    lineHeader.textContent = 'ラインスタイル（この階層のカードから出るライン）';
    depthFieldsEl.appendChild(lineHeader);
    _bdAppendDepthStyleRefRow(depthFieldsEl, 'line', selected, liveDepth, () => {
      applyDepthStyles();
      _bdRenderDepthStyleInPanel(container, idx);
    });
    if (!selected.line || typeof selected.line !== 'object') {
      selected.line = { color: '', width: 2, style: '', arrow: 'end', pathType: 'curve' };
    }
    const lineFieldsWrap = document.createElement('div');
    lineFieldsWrap.className = 'bd-depth-style-field-group';
    depthFieldsEl.appendChild(lineFieldsWrap);
    _bdBuildStyleFields(lineFieldsWrap, 'line', selected.line, field => depthEmit('line', field), {
      hideName: true,
      e2eScope: `depth-panel-${idx}-line`,
      beforeEdit: () => {
        const live = liveDepth();
        if (!live) return null;
        if (!live.line || typeof live.line !== 'object') {
          live.line = { color: '', width: 2, style: '', arrow: 'end', pathType: 'curve' };
        }
        return live.line;
      },
    });
  }

  const pickerBtn = container.querySelector('[data-bd-depth-panel-picker]');
  pickerBtn?.addEventListener('click', () => {
    _bdOpenDepthStyleManagerPopup(pickerBtn, {
      currentIndex: idx,
      onSelect: (nextIdx) => {
        _bdLastDepthEditIndex = Math.max(0, Math.min(+nextIdx || 0, (bd.depthStyles || []).length - 1));
        _bdRenderDepthStyleInPanel(container, nextIdx);
      },
      // タブ再描画でピッカーボタンが新規 DOM に置き換わるため、ポップアップ
      // 位置計算前に最新の DOM を取り直す。これがないと旧ボタンの矩形 (0,0,0,0)
      // が使われてポップアップが画面左上に飛ぶ。
      refreshAnchor: () => container.querySelector('[data-bd-depth-panel-picker]'),
    });
  });
  container.querySelector('[data-bd-depth-apply-theme]')?.addEventListener('click', () => {
    if (typeof bdApplyThemeColorsToDepthStyles !== 'function') return;
    if (typeof bdPushUndo === 'function') bdPushUndo();
    bdApplyThemeColorsToDepthStyles({ applyLineColor: true });
    applyDepthStyles();
    _bdRenderDepthStyleInPanel(container, idx);
    if (typeof showStatus === 'function') showStatus('テーマカラーを階層別スタイルに適用しました');
  });
  if (typeof bindMeldexDropdownKeySwitch === 'function') {
    bindMeldexDropdownKeySwitch(pickerBtn, {
      getItems: () => (bd.depthStyles || []).map((style, index) => ({ value: String(index), style })),
      getCurrentValue: () => pickerBtn.dataset.bdDepthCurrentIndex || String(idx),
      onSelect: (_item, nextIndex) => _bdRenderDepthStyleInPanel(container, nextIndex),
      getFreshTrigger: () => container.querySelector('[data-bd-depth-panel-picker]'),
    });
  }
}

// 階層別スタイル用のポップアップ (list + add/save/reset/delete アクション)。
let _bdDepthStyleDragIndex = -1;
function _bdOpenDepthStyleManagerPopup(anchorEl, options) {
  if (!anchorEl) return;
  if (_bdStyleManagerPopup) {
    const same = _bdStyleManagerPopupAnchor === anchorEl;
    _bdCloseStyleManagerPopup();
    if (same) return;
  }
  if (typeof bdEnsureDepthStyles === 'function') bdEnsureDepthStyles();
  const opts = options || {};
  let currentAnchor = anchorEl;
  const popup = document.createElement('div');
  popup.className = 'bd-style-manager-popup bd-depth-manager-popup';
  document.body.appendChild(popup);
  _bdStyleManagerPopup = popup;
  _bdStyleManagerPopupAnchor = currentAnchor;
  _bdConfigureStyleManagerPopup(popup, '階層別スタイル管理', currentAnchor);
  _bdBindStyleManagerPopupKeys(popup, () => typeof opts.refreshAnchor === 'function' ? (opts.refreshAnchor() || currentAnchor) : currentAnchor);

  const applyDepthStyles = (renderCb) => {
    if (typeof bdNormalizeDepthStyles === 'function') bd.depthStyles = bdNormalizeDepthStyles(bd.depthStyles);
    _bdApplyAllAutoStyles();
    bdDirty();
    bdRender();
    bdRefreshBoardToolbar();
    if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
    if (typeof renderCb === 'function') renderCb();
  };

  const render = () => {
    const styles = bd.depthStyles || [];
    let currentIndex = Math.max(0, Math.min(Number.isFinite(+opts.currentIndex) ? +opts.currentIndex : 0, styles.length - 1));
    const plusIcon = typeof lucide === 'function' ? lucide('plus', 14) : '+';
    const saveIcon = typeof lucide === 'function' ? lucide('save', 14) : '保存';
    const resetIcon = typeof lucide === 'function' ? lucide('rotateCcw', 14) : '戻す';
    const trashIcon = typeof lucide === 'function' ? lucide('trash2', 14) : '削除';
    const paletteIcon = typeof lucide === 'function' ? lucide('palette', 14) : '色';

    popup.innerHTML = `
      <div class="bd-style-manager-popup-list" role="listbox" aria-label="階層別スタイル一覧">
        ${styles.map((style, i) => {
          const tooltip = _bdEscAttr(_bdDepthStyleTooltip(style, i, styles.length));
          return `<div class="bd-style-list-item bd-depth-style-item ${i === currentIndex ? 'active' : ''}" data-bd-depth-select="${i}" data-bd-depth-item="${i}" draggable="true" tabindex="0" role="option" aria-selected="${i === currentIndex ? 'true' : 'false'}" title="${tooltip}" aria-label="${tooltip}">
            <span class="bd-style-list-handle" title="ドラッグして並べ替え">⋮⋮</span>
            <span class="bd-style-list-preview">${_bdDepthStylePreviewHtml(style)}</span>
            <span class="bd-style-list-name">${esc(typeof bdDepthStyleDisplayName === 'function' ? bdDepthStyleDisplayName(style, i, styles.length) : `階層 ${i + 1}`)}</span>
          </div>`;
        }).join('')}
      </div>
      <div class="bd-style-manager-popup-actions">
        <button type="button" class="bd-detail-style-action" data-bd-popup-depth-add title="階層を追加" aria-label="階層を追加">${plusIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-depth-theme title="テーマカラーを階層別スタイルに適用" aria-label="テーマカラーを階層別スタイルに適用">${paletteIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-depth-save title="現在の階層別スタイル一式を全ボード共通のデフォルトとして保存" aria-label="現在の階層別スタイル一式を全ボード共通のデフォルトとして保存">${saveIcon}</button>
        <button type="button" class="bd-detail-style-action" data-bd-popup-depth-reset title="保存したデフォルトに戻す (未保存ならビルトイン初期値)" aria-label="保存したデフォルトに戻す">${resetIcon}</button>
        <button type="button" class="bd-detail-style-action bd-detail-style-action--danger" data-bd-popup-depth-delete title="削除" aria-label="削除" ${styles.length <= 1 ? 'disabled' : ''}>${trashIcon}</button>
        ${_bdStyleManagerPopupCloseButtonHtml()}
      </div>`;

    if (typeof opts.refreshAnchor === 'function') {
      const next = opts.refreshAnchor();
      if (next) {
        currentAnchor = next;
        _bdStyleManagerPopupAnchor = next;
      }
    }
    _bdPositionStyleManagerPopup(popup, currentAnchor);
    _bdSetStyleManagerPopupAnchorState(currentAnchor, true);
    _bdPrepareStyleManagerPopupControls(popup);

    popup.querySelectorAll('[data-bd-depth-select]').forEach(item => {
      item.addEventListener('click', () => {
        const i = parseInt(item.dataset.bdDepthSelect, 10) || 0;
        opts.currentIndex = i;
        if (typeof opts.onSelect === 'function') opts.onSelect(i);
        render();
      });
    });
    popup.querySelector('[data-bd-popup-close]')?.addEventListener('click', () => {
      _bdCloseStyleManagerPopup({ restoreFocus: true });
    });

    popup.querySelectorAll('[data-bd-depth-item]').forEach(item => {
      item.addEventListener('dragstart', () => {
        _bdDepthStyleDragIndex = parseInt(item.dataset.bdDepthItem, 10);
        item.classList.add('dragging');
      });
      item.addEventListener('dragend', () => {
        _bdDepthStyleDragIndex = -1;
        popup.querySelectorAll('[data-bd-depth-item]').forEach(el => el.classList.remove('dragging', 'drag-over'));
      });
      item.addEventListener('dragover', event => { event.preventDefault(); item.classList.add('drag-over'); });
      item.addEventListener('dragleave', () => item.classList.remove('drag-over'));
      item.addEventListener('drop', event => {
        event.preventDefault();
        item.classList.remove('drag-over');
        const targetIndex = parseInt(item.dataset.bdDepthItem, 10);
        if (!Number.isFinite(_bdDepthStyleDragIndex) || !Number.isFinite(targetIndex)) return;
        const arr = bd.depthStyles || [];
        if (_bdDepthStyleDragIndex === targetIndex || _bdDepthStyleDragIndex < 0 || targetIndex < 0) return;
        if (typeof bdPushUndo === 'function') bdPushUndo();
        const [moved] = arr.splice(_bdDepthStyleDragIndex, 1);
        const finalIndex = _bdDepthStyleDragIndex < targetIndex ? targetIndex - 1 : targetIndex;
        arr.splice(finalIndex, 0, moved);
        opts.currentIndex = finalIndex;
        if (typeof opts.onSelect === 'function') opts.onSelect(finalIndex);
        applyDepthStyles(render);
      });
    });

    popup.querySelector('[data-bd-popup-depth-add]')?.addEventListener('click', () => {
      const styles2 = bd.depthStyles || [];
      const last = styles2[styles2.length - 1] || { fontSize: 13, fontBold: false, width: 160, bgColor: '' };
      if (typeof bdPushUndo === 'function') bdPushUndo();
      const next = _bdClone(last);
      const baseName = (last && last.name) ? `${last.name} 2` : `階層 ${styles2.length + 1}`;
      next.name = typeof _bdMakeUniqueStyleName === 'function'
        ? _bdMakeUniqueStyleName(baseName, styles2)
        : baseName;
      bd.depthStyles.push(next);
      opts.currentIndex = bd.depthStyles.length - 1;
      if (typeof opts.onSelect === 'function') opts.onSelect(opts.currentIndex);
      applyDepthStyles(render);
    });

    popup.querySelector('[data-bd-popup-depth-theme]')?.addEventListener('click', () => {
      if (typeof bdApplyThemeColorsToDepthStyles !== 'function') return;
      if (typeof bdPushUndo === 'function') bdPushUndo();
      bdApplyThemeColorsToDepthStyles({ applyLineColor: true });
      opts.currentIndex = currentIndex;
      if (typeof opts.onSelect === 'function') opts.onSelect(currentIndex);
      applyDepthStyles(render);
      if (typeof showStatus === 'function') showStatus('テーマカラーを階層別スタイルに適用しました');
    });

    popup.querySelector('[data-bd-popup-depth-delete]')?.addEventListener('click', async () => {
      if ((bd.depthStyles || []).length <= 1) return;
      const deleteIndex = Math.max(0, Math.min(Number.isFinite(+opts.currentIndex) ? +opts.currentIndex : 0, bd.depthStyles.length - 1));
      const target = bd.depthStyles[deleteIndex] || {};
      const label = typeof bdDepthStyleDisplayName === 'function'
        ? bdDepthStyleDisplayName(target, deleteIndex, bd.depthStyles.length)
        : (target.name || `階層 ${deleteIndex + 1}`);
      const ok = typeof cfConfirm === 'function'
        ? await cfConfirm(`階層別スタイル「${label}」を削除しますか？`)
        : (typeof confirm === 'function' ? confirm(`階層別スタイル「${label}」を削除しますか？`) : true);
      if (!ok) return;
      if (typeof bdPushUndo === 'function') bdPushUndo();
      bd.depthStyles.splice(deleteIndex, 1);
      opts.currentIndex = Math.max(0, Math.min(deleteIndex, bd.depthStyles.length - 1));
      if (typeof opts.onSelect === 'function') opts.onSelect(opts.currentIndex);
      applyDepthStyles(render);
    });

    popup.querySelector('[data-bd-popup-depth-save]')?.addEventListener('click', () => {
      if (typeof bdPushUndo === 'function') bdPushUndo();
      const snapshot = typeof bdNormalizeDepthStyles === 'function'
        ? bdNormalizeDepthStyles(bd.depthStyles)
        : (bd.depthStyles || []).slice();
      _bdSaveGlobalDepthStyles(snapshot);
      showStatus('階層別スタイルをデフォルトとして保存しました', false, { showSaveDialog: true });
    });

    popup.querySelector('[data-bd-popup-depth-reset]')?.addEventListener('click', () => {
      if (typeof bdPushUndo === 'function') bdPushUndo();
      const global = _bdReadGlobalDepthStyles();
      const globalIsLegacy = typeof _bdIsLegacyDefaultDepthStyles === 'function' && _bdIsLegacyDefaultDepthStyles(global);
      if (Array.isArray(global) && global.length && !globalIsLegacy) {
        bd.depthStyles = typeof bdNormalizeDepthStyles === 'function' ? bdNormalizeDepthStyles(global) : global.slice();
        showStatus('保存したデフォルトに戻しました');
      } else {
        bd.depthStyles = typeof bdNormalizeDepthStyles === 'function' ? bdNormalizeDepthStyles([]) : [];
        showStatus('デフォルトは未保存のため、ビルトイン初期値に戻しました');
      }
      opts.currentIndex = 0;
      if (typeof opts.onSelect === 'function') opts.onSelect(0);
      applyDepthStyles(render);
    });
  };

  render();
  setTimeout(() => {
    _bdStyleManagerPopupCloseHandler = event => {
      if (!_bdStyleManagerPopup) return;
      const anchor = _bdStyleManagerPopupAnchor || currentAnchor;
      if (!_bdStyleManagerPopup.contains(event.target) && !(anchor && anchor.contains(event.target))) {
        _bdCloseStyleManagerPopup();
      }
    };
    document.addEventListener('pointerdown', _bdStyleManagerPopupCloseHandler);
  }, 0);
}

// 旧モーダルは廃止し、オプションパネルの階層別スタイルタブに切り替える (コミットC)。
// window._bdPendingDepthStyleIndex が明示的に指定されていればそのインデックスを初期選択として
// タブを再描画する。未指定の場合は現在の描画状態を尊重し、強制的にインデックス 0 へリセットしない。
function bdOpenDepthStyleManager() {
  if (typeof bdEnsureDepthStyles === 'function') bdEnsureDepthStyles();
  if (typeof _bdEnsureBoardStyleManagerTabs === 'function') _bdEnsureBoardStyleManagerTabs();
  if (typeof showBoardTabs === 'function') showBoardTabs({ depthStyle: true });
  const pendingIndex = Number.isInteger(window?._bdPendingDepthStyleIndex) ? window._bdPendingDepthStyleIndex : null;
  window._bdPendingDepthStyleIndex = null;
  const el = document.getElementById('detail-tab-board-depth-style');
  if (el && typeof _bdRenderDepthStyleInPanel === 'function') {
    if (pendingIndex !== null) {
      // 呼び出し側が明示的に index を指定 → その階層を初期選択にして再描画
      _bdRenderDepthStyleInPanel(el, pendingIndex);
    } else if (el.childElementCount === 0) {
      // 初回レンダー時のみインデックス 0 で描画。既に描画済みの場合は現在の選択を保つ。
      _bdRenderDepthStyleInPanel(el, 0);
    }
  }
  if (typeof switchDetailTab === 'function') switchDetailTab('board-depth-style');
}

// 旧モーダルは廃止し、オプションパネルのカードスタイルタブに切り替える (コミットC)。
// タブコンテンツは _bdEnsureBoardStyleManagerTabs() 経由で _bdRenderStyleManagerInPanel が描画する。
function bdOpenCardStyleManager() {
  bdEnsureBoardUiState();
  if (typeof _bdEnsureBoardStyleManagerTabs === 'function') _bdEnsureBoardStyleManagerTabs();
  if (typeof showBoardTabs === 'function') showBoardTabs({ cardStyle: true });
  if (typeof switchDetailTab === 'function') switchDetailTab('board-card-style');
}

function bdOpenLineStyleManager() {
  bdEnsureBoardUiState();
  if (typeof _bdEnsureBoardStyleManagerTabs === 'function') _bdEnsureBoardStyleManagerTabs();
  if (typeof showBoardTabs === 'function') showBoardTabs({ lineStyle: true });
  if (typeof switchDetailTab === 'function') switchDetailTab('board-line-style');
}

function bdOpenFilterMenu(anchor) {
  if (typeof bdEnsureBoardUiState === 'function') bdEnsureBoardUiState();
  bdCloseStylePicker();
  document.querySelectorAll('.gb-context-menu').forEach(menu => menu.remove());
  const menu = document.createElement('div');
  menu.className = 'gb-context-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'ボード表示フィルタ');
  menu.style.cssText = 'position:fixed;z-index:10000;';
  const rect = anchor.getBoundingClientRect();
  anchor.setAttribute('aria-haspopup', 'menu');
  anchor.setAttribute('aria-expanded', 'true');
  let closeHandler = null;
  const closeMenu = (restoreFocus = false) => {
    menu.remove();
    anchor.setAttribute('aria-expanded', 'false');
    if (closeHandler) {
      document.removeEventListener('pointerdown', closeHandler);
      closeHandler = null;
    }
    if (restoreFocus && typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchor);
  };
  const prepareToggleRow = (row, checked) => {
    row.className = 'gb-context-menu-item';
    row.tabIndex = 0;
    row.setAttribute('role', 'menuitemcheckbox');
    row.setAttribute('aria-checked', checked ? 'true' : 'false');
    row.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        row.click();
      } else if (event.key === 'Escape') {
        event.preventDefault();
        closeMenu(true);
      }
    });
  };
  menu.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      closeMenu(true);
    }
  });
  // 表示フィルタ: 既定 true / OFF で非表示
  const labels = {
    showConnections: 'ライン',
    showConnLabels: 'ラインテキスト',
    showStatus: 'ステータス',
    showProgress: '進捗バー',
    showMarkers: 'マーカー',
    showNotes: 'ノート印',
    showLinkBadges: 'リンク印',
    showMenuButtons: '... ボタン',
    showImageNames: '画像ファイル名',
  };
  Object.entries(labels).forEach(([key, label]) => {
    const row = document.createElement('div');
    const checked = bd.displayFilters[key] !== false;
    prepareToggleRow(row, checked);
    row.innerHTML = `${radioMark(checked)}${esc(label)}`;
    row.addEventListener('click', () => {
      bd.displayFilters[key] = !(bd.displayFilters[key] !== false);
      closeMenu(true);
      bdRender();
      bdDirty();
    });
    menu.appendChild(row);
  });
  // 表示モード: 既定 false / ON で有効（計画書 §4-3-A）
  const modes = [
    { key: '_showShadow', label: 'カード影' },
    { key: '_textRotateOnLine', label: 'ライン上テキスト回転' },
  ];
  modes.forEach(({ key, label }) => {
    const row = document.createElement('div');
    const checked = !!bd[key];
    prepareToggleRow(row, checked);
    row.innerHTML = `${radioMark(checked)}${esc(label)}`;
    row.addEventListener('click', () => {
      bd[key] = !bd[key];
      closeMenu(true);
      bdRender();
      bdDirty();
    });
    menu.appendChild(row);
  });
  const relationSep = document.createElement('div');
  relationSep.className = 'bd-cm-sep';
  menu.appendChild(relationSep);
  {
    const key = 'highlightParentChildGroups';
    const row = document.createElement('div');
    const checked = bd.displayFilters[key] === true;
    prepareToggleRow(row, checked);
    row.innerHTML = `${radioMark(checked)}${esc('親子関係ハイライト')}`;
    row.addEventListener('click', () => {
      bd.displayFilters[key] = bd.displayFilters[key] !== true;
      closeMenu(true);
      bdRender();
      bdDirty();
    });
    menu.appendChild(row);
  }
  document.body.appendChild(menu);
  if (typeof attachMeldexDropdownCloseButton === 'function') {
    attachMeldexDropdownCloseButton(menu, {
      trigger: anchor,
      close: () => closeMenu(false),
    });
  }
  if (typeof positionPopup === 'function') positionPopup(menu, rect);
  else {
    const z = typeof _getZoom === 'function' ? _getZoom() : 1;
    menu.style.left = (rect.left / z) + 'px';
    menu.style.top = (rect.bottom / z + 4) + 'px';
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);
  }
  setTimeout(() => {
    closeHandler = event => {
      if (!menu.contains(event.target)) {
        closeMenu(false);
      }
    };
    document.addEventListener('pointerdown', closeHandler);
  }, 0);
  requestAnimationFrame(() => {
    if (menu.isConnected) menu.querySelector('.gb-context-menu-item')?.focus?.();
  });
}

;

/* === gb-tool-canvas.js === */
;
/* ==============================
   gb-tool-canvas.js: CanvasComponent (v5.0 Phase C)
   canvas.html → JSモジュール変換
   依存: gb-canvas-engine.js, gb-canvas-features.js, gb-canvas-interact.js
   ============================== */

class CanvasComponent extends ToolComponent {
  constructor(paneId, tabId) {
    super(paneId, tabId);
    this._interactionCleanup = null;
    this._keyboardCleanup = null;
    this.idSuffix = _bdComponentIdSuffix(tabId || paneId);
    // multi:true の複数キャンバスタブでグローバル bd を共有しないための dump slot
    this._bdDump = null;
  }

  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-canvas-root';
    this.el.dataset.bdIdSuffix = this.idSuffix;
    this.el.innerHTML = typeof bdBuildBoardShellMarkup === 'function' ? bdBuildBoardShellMarkup(this.idSuffix) : '';
    if (typeof bdInitBoardShell === 'function') bdInitBoardShell(this.el);
    // 右クリック無効化
    this.el.querySelector('[data-bd-role="canvas"]')?.addEventListener('contextmenu', (e) => e.preventDefault());
    return this.el;
  }

  _ownTab() {
    const paneInfo = (typeof GBLayout !== 'undefined')
      ? GBLayout.findNode?.(GBLayout.root, this.paneId)
      : null;
    return paneInfo?.node?.tabs?.find?.(tab => tab.id === this.tabId)
      || paneInfo?.node?.tabs?.[paneInfo?.node?.activeTabIndex]
      || null;
  }

  _isOwnPaneActive() {
    if (typeof GBLayout === 'undefined') return true;
    if (this.paneId === GBLayout.activePane) return true;
    const surface = GBLayout.paneMap?.[this.paneId]?.surface;
    return surface === 'float' || surface === 'subpanel';
  }

  _trackBoardLoad(result) {
    Promise.resolve(result).then((ok) => {
      if (!this.el) return;
      if (ok === false) this.el.dataset.loadFailed = '1';
      else delete this.el.dataset.loadFailed;
    }).catch(() => {
      if (this.el) this.el.dataset.loadFailed = '1';
    });
  }

  activate() {
    super.activate();
    const isPaneActive = this._isOwnPaneActive();
    if (isPaneActive) _bdSetActiveBoardRootIds(this.el, this.idSuffix);
    // 保存された背景色を復元
    const ownTab = this._ownTab();
    if (ownTab?.type === 'board') {
      this.state.boardPath = ownTab.state?.boardPath || ownTab.path || this.state.boardPath || '';
      this.state.label = ownTab.state?.label || ownTab.label || this.state.label || '';
    }
    if (typeof state !== 'undefined' && isPaneActive) {
      state.view = 'board';
      const activePath = this.state.boardPath || this._bdDump?.bd?.path || ((typeof bd !== 'undefined' && bd.path) ? bd.path : '');
      if (activePath) state.currentBoardPath = activePath;
      if (activePath && typeof startAutoVersion === 'function') startAutoVersion(activePath, 'file');
      // フェーズ3-3: タブがアクティブになったタイミングで取り消し履歴のアクティブスコープを
      // このボードへ切り替える（dump からの復元時は bdLoadState() 側でも同様に切り替わる）。
      if (activePath && typeof historySetScope === 'function') {
        historySetScope(typeof _bdHistoryScope === 'function' ? _bdHistoryScope(activePath) : ('board:' + String(activePath).replace(/\\/g, '/')));
      }
      if (typeof updateUndoRedoButtonStates === 'function') updateUndoRedoButtonStates();
    }
    const canvas = this.el.querySelector('[data-bd-role="canvas"]');
    const world = this.el.querySelector('[data-bd-role="world"]') || document.getElementById('bd-world');
    if (typeof bdApplyBoardFileStyleAndTheme === 'function') {
      bdApplyBoardFileStyleAndTheme(canvas, world);
    } else if (typeof bdApplyCanvasBackground === 'function') {
      bdApplyCanvasBackground(canvas);
    }
    if (!isPaneActive) {
      // v0.5.338: ここで cleanup すると、pane-bridge の _mountAllPanes 経由で
      // activate() が呼ばれたタイミングで GBLayout.activePane がまだ更新前の場合
      // (= 本来アクティブなペインのはずが isPaneActive:false と判定される) に、
      // 正当な listener (特に dragover/drop) を剥がしてしまう不具合があった。
      // cleanup は必ず deactivate() / destroy() 側で実行されるため、ここでは何もしない。
      return;
    }
    // インタラクション初期化（マウス/キーボードハンドラ）
    if (typeof bdInitInteraction === 'function' && !this._interactionCleanup) {
      this._interactionCleanup = bdInitInteraction(this.el);
    }
    if (typeof bdInitKeyboard === 'function' && !this._keyboardCleanup) {
      this._keyboardCleanup = bdInitKeyboard(this.el);
    }
    // メモオーバーレイ初期化
    if (typeof initIframeMarkup === 'function') {
      const canvas = this.el.querySelector('[data-bd-role="canvas"]');
      if (canvas) initIframeMarkup(canvas);
    }
    // ボードを開く:
    //  - dump があれば restore（複数キャンバスタブ間の state 分離）
    //  - なければ通常の bdOpenBoard で読み込み
    if (this._bdDump) {
      if (typeof bdLoadState === 'function') bdLoadState(this._bdDump);
      this._bdDump = null;
    } else if (!this._activatingForReload && this.state.boardPath && bd.path !== this.state.boardPath) {
      this._trackBoardLoad(bdOpenBoard(this.state.label || '', this.state.boardPath));
    }
  }

  _syncDetailPanel() {
    // pane-bridge の _syncDetailForActivePane から呼ばれる。
    // これを実装しておくことで _clearDetailPaneShell() → switchDetailTab(null)
    // の強制タブリセットを回避し、ボードアクティブ時にユーザーが選んでいた
    // オプションタブ (file-style / board-card / board-line 等) を保持する。
    // 他ツールのタブを非表示にする（board以外のタブを隠す）
    if (typeof showNoteTabs === 'function') showNoteTabs(false);
    if (typeof showDbTabs === 'function') showDbTabs(false);
    if (typeof showCalendarDetailTabs === 'function') showCalendarDetailTabs(false);
    if (typeof showPublishDetailTab === 'function') showPublishDetailTab(false);
    if (typeof hideScriptnoteDetailTabs === 'function') hideScriptnoteDetailTabs();
    if (typeof bdRefreshSelectionDetails === 'function') bdRefreshSelectionDetails(true);
  }

  deactivate() {
    super.deactivate();
    // 未保存があれば保存
    if (bd.dirty && bd.path) {
      bdSave();
    }
    // bd の state を自分のインスタンスに dump（次 activate 時に restore する）
    if (typeof bdDumpState === 'function' && bd.path === (this.state.boardPath || bd.path)) {
      this._bdDump = bdDumpState();
    }
    // インタラクション/キーボードハンドラをクリーンアップ（documentレベルのリスナー除去）
    if (this._interactionCleanup) { this._interactionCleanup(); this._interactionCleanup = null; }
    if (this._keyboardCleanup) { this._keyboardCleanup(); this._keyboardCleanup = null; }
    _bdRestoreBoardRootIds(this.el, this.idSuffix);
  }

  destroy() {
    // イベントリスナーのクリーンアップ
    if (this._interactionCleanup) { this._interactionCleanup(); this._interactionCleanup = null; }
    if (this._keyboardCleanup) { this._keyboardCleanup(); this._keyboardCleanup = null; }
    // 未保存があれば保存
    if (bd.dirty && bd.path) {
      bdSave();
    }
    _bdRestoreBoardRootIds(this.el, this.idSuffix);
    super.destroy();
  }

  handleKeyDown(e) {
    // キャンバスがフォーカスされていない場合でも、アクティブコンポーネントならキーを処理
    if (bd.editing) return false; // 編集中はグローバルに委譲しない
    // Ctrl+S: 保存
    if (e.ctrlKey && e.key === 's') { e.preventDefault(); bdSave(); return true; }
    // Ctrl+Z: Undo
    if (e.ctrlKey && e.key === 'z') { e.preventDefault(); bdUndo(); return true; }
    // Ctrl+Y: Redo
    if (e.ctrlKey && e.key === 'y') { e.preventDefault(); bdRedo(); return true; }
    return false;
  }

  restoreState(s) {
    super.restoreState(s);
    if (s) {
      this.state.boardPath = s.boardPath || '';
      this.state.label = s.label || '';
    }
  }

  getState() {
    return {
      boardPath: this.state.boardPath || this._bdDump?.bd?.path || (this._active ? bd.path : ''),
      label: this.state.label || this._bdDump?.bd?.label || '',
    };
  }

  async reload() {
    const path = this.state.boardPath || this._bdDump?.bd?.path || (this._active ? bd.path : '');
    if (!path || typeof bdOpenBoard !== 'function') return false;
    if (!this._isOwnPaneActive() && typeof GBLayout !== 'undefined' && typeof GBLayout.setActivePane === 'function') {
      this._activatingForReload = true;
      try {
        GBLayout.setActivePane(this.paneId, { sync: true });
      } finally {
        this._activatingForReload = false;
      }
    }
    if (!this._isOwnPaneActive()) return false;
    if (this._isOwnPaneActive()) _bdSetActiveBoardRootIds(this.el, this.idSuffix);
    const opened = await bdOpenBoard(this.state.label || this._bdDump?.bd?.label || '', path);
    if (opened === false) {
      if (this.el) this.el.dataset.loadFailed = '1';
      return false;
    }
    if (this.el) delete this.el.dataset.loadFailed;
    this._bdDump = null;
    return true;
  }
}

const _BD_CANONICAL_IDS = {
  canvas: 'bd-canvas',
  world: 'bd-world',
  svg: 'bd-svg',
  nodes: 'bd-nodes',
  'resize-layer': 'bd-resize-layer',
};

function _bdComponentIdSuffix(value) {
  const raw = String(value || ('bd-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7)));
  return raw.replace(/[^A-Za-z0-9_-]/g, '_');
}

function _bdCanonicalScopedId(id, suffix) {
  const raw = String(id || '');
  const scopedSuffix = suffix ? '-' + suffix : '';
  if (scopedSuffix && raw.endsWith(scopedSuffix)) return raw.slice(0, -scopedSuffix.length);
  return raw;
}

function _bdSetScopedId(el, suffix, active) {
  if (!el || !el.id) return;
  const baseId = el.dataset.bdBaseId || _bdCanonicalScopedId(el.id, suffix);
  if (!baseId || (!baseId.startsWith('bd-') && !baseId.startsWith('bdn-'))) return;
  el.dataset.bdBaseId = baseId;
  el.id = active ? baseId : (suffix ? `${baseId}-${suffix}` : baseId);
}

function _bdSetBoardRootIds(root, suffix, active) {
  if (!root) return;
  root.querySelectorAll?.('[id]')?.forEach(el => _bdSetScopedId(el, suffix, active));
  Object.entries(_BD_CANONICAL_IDS).forEach(([role, baseId]) => {
    const el = root.querySelector?.(`[data-bd-role="${role}"]`);
    if (!el) return;
    el.id = active ? baseId : `${baseId}-${suffix}`;
    el.dataset.bdBaseId = baseId;
  });
}

function _bdRestoreBoardRootIds(root, suffix) {
  _bdSetBoardRootIds(root, suffix || root?.dataset?.bdIdSuffix || '', false);
}

function _bdSetActiveBoardRootIds(root, suffix) {
  document.querySelectorAll('.gb-canvas-root').forEach(otherRoot => {
    if (otherRoot === root) return;
    _bdRestoreBoardRootIds(otherRoot, otherRoot.dataset.bdIdSuffix || '');
  });
  _bdSetBoardRootIds(root, suffix || root?.dataset?.bdIdSuffix || '', true);
}

// コンポーネントレジストリ更新（gb-tool-components.jsの定義を上書き）
registerToolComponent('board', { cls: CanvasComponent, icon: 'presentation', label: 'ボード', multi: true, requiresViewLock: false });

;

/* === gb-export-save.js === */
;
/* gb-export-save.js: エクスポート保存ダイアログ共通 helper */

const MeldexExportSave = (() => {
  const RESERVED_WINDOWS_NAMES = new Set([
    'CON', 'PRN', 'AUX', 'NUL',
    'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
    'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9',
  ]);
  const LARGE_BLOB_PICKER_THRESHOLD = 8 * 1024 * 1024;

  function _sanitizeFileName(name, fallback = '無題', maxLen = 180) {
    let safe = String(name || fallback)
      .replace(/[<>:"/\\|?*\x00-\x1f]/g, '_')
      .replace(/\.\./g, '')
      .trim()
      .replace(/[. ]+$/g, '');
    if (!safe) safe = fallback;
    const match = safe.match(/(\.[^.]+)$/);
    const ext = match ? match[1] : '';
    let stem = ext ? safe.slice(0, -ext.length) : safe;
    if (RESERVED_WINDOWS_NAMES.has(stem.toUpperCase())) stem += '_';
    safe = stem + ext;
    if (safe.length > maxLen) {
      const keep = Math.max(1, maxLen - ext.length);
      safe = stem.slice(0, keep).replace(/[. ]+$/g, '') + ext;
    }
    return safe || fallback;
  }

  function sanitizeTitle(title, fallback = '無題') {
    return _sanitizeFileName(title, fallback, 80);
  }

  function guessNameFromPath(path, fallback = '無題') {
    const raw = String(path || '').replace(/\\/g, '/').split('/').pop() || '';
    return raw || fallback;
  }

  function splitFileName(fileName = '', fallbackTitle = '無題', fallbackExtension = '.bin') {
    const normalized = String(fileName || '').trim();
    if (!normalized) {
      return { initialfile: sanitizeTitle(fallbackTitle, fallbackTitle) + fallbackExtension, extension: fallbackExtension };
    }
    const safeName = _sanitizeFileName(normalized, sanitizeTitle(fallbackTitle, fallbackTitle), 180);
    const match = safeName.match(/(\.[^.]+)$/);
    return {
      initialfile: safeName,
      extension: match ? match[1] : fallbackExtension,
    };
  }

  function _parseContentDispositionFileName(headerValue = '') {
    const src = String(headerValue || '');
    if (!src) return '';
    const utf8Match = src.match(/filename\*\s*=\s*UTF-8''([^;]+)/i);
    if (utf8Match?.[1]) {
      try { return decodeURIComponent(utf8Match[1]); } catch {}
    }
    const quotedMatch = src.match(/filename\s*=\s*"([^"]+)"/i);
    if (quotedMatch?.[1]) return quotedMatch[1];
    const plainMatch = src.match(/filename\s*=\s*([^;]+)/i);
    return plainMatch?.[1]?.trim() || '';
  }

  function _notifyManualSaveSuccess(message) {
    const text = String(message || '保存しました');
    if (typeof showSaveDialog === 'function') {
      showSaveDialog(text);
      return;
    }
    if (typeof showStatus === 'function') showStatus(text, false, { showSaveDialog: true });
  }

  // 単独アプリ（ノート/シナリオ/シート/タイマー/ボード）判定。
  // これらのページだけが window.MeldexStandaloneFS または window.BoardStandaloneFS を
  // 定義するため、本体 Meldex.html では常に false になる（本体の挙動には影響しない）。
  function _isStandaloneContext() {
    return typeof window !== 'undefined' && !!(window.MeldexStandaloneFS || window.BoardStandaloneFS);
  }

  // 単独アプリには /api/save-file-dialog（サーバー側ネイティブダイアログ）が無いため、
  // ブラウザの通常ダウンロード（Blob URL + <a download>）でファイルを書き出す。
  // 保存先フォルダを選ばせられない点は本体の名前を付けて保存ダイアログに劣るが、
  // Windows単独exe・Cloud静的版・PWAのいずれでも共通に動作する。
  function _downloadBlobDirect(blob, filename) {
    try {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename || '無題';
      a.rel = 'noopener';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => { try { URL.revokeObjectURL(url); } catch {} }, 4000);
      return true;
    } catch {
      return false;
    }
  }

  async function _standaloneSaveText(content, options = {}) {
    const fallbackExtension = options.extension || '.txt';
    const { initialfile } = splitFileName(
      options.initialfile || options.filename || '',
      options.title || options.fallbackTitle || '無題',
      fallbackExtension
    );
    const blob = new Blob([options.bom ? '\uFEFF' + String(content || '') : String(content || '')], {
      type: options.mime || 'text/plain;charset=utf-8',
    });
    if (!_downloadBlobDirect(blob, initialfile)) {
      if (typeof showStatus === 'function') showStatus(options.errorMessage || '保存に失敗しました', true);
      return false;
    }
    _notifyManualSaveSuccess((options.okMessage || '保存しました') + '（ダウンロード: ' + initialfile + '）');
    return { ok: true, path: initialfile };
  }

  async function _standaloneSaveBlob(blob, options = {}) {
    const fallbackExtension = options.extension || '.bin';
    const { initialfile } = splitFileName(
      options.initialfile || options.filename || '',
      options.title || options.fallbackTitle || '無題',
      fallbackExtension
    );
    if (!_downloadBlobDirect(blob, initialfile)) {
      if (typeof showStatus === 'function') showStatus(options.errorMessage || '保存に失敗しました', true);
      return false;
    }
    _notifyManualSaveSuccess((options.okMessage || '保存しました') + '（ダウンロード: ' + initialfile + '）');
    return { ok: true, path: initialfile };
  }

  async function _showDialog(payload, messages = {}) {
    try {
      const res = await apiPost('/save-file-dialog', payload);
      if (res?.cancelled) {
        if (typeof showStatus === 'function') showStatus(messages.cancel || '保存をキャンセルしました');
        return false;
      }
      if (res?.ok) {
        _notifyManualSaveSuccess((messages.ok || '保存しました') + ': ' + res.path);
        return res;
      }
      if (typeof showStatus === 'function') showStatus(messages.error || '保存に失敗しました', true);
      return false;
    } catch (err) {
      if (typeof showStatus === 'function') showStatus(messages.error || (err?.message || '保存に失敗しました'), true);
      return false;
    }
  }

  async function saveText(content, options = {}) {
    if (_isStandaloneContext()) return _standaloneSaveText(content, options);
    const fallbackExtension = options.extension || '.txt';
    const { initialfile, extension } = splitFileName(
      options.initialfile || options.filename || '',
      options.title || options.fallbackTitle || '無題',
      fallbackExtension
    );
    return _showDialog({
      title: options.dialogTitle || '書き出して保存',
      initialfile,
      defaultextension: extension,
      filetypes: options.filetypes || [['すべてのファイル', '*.*']],
      content: options.bom ? '\uFEFF' + String(content || '') : String(content || ''),
      register_publish_path: !!options.registerPublishPath,
    }, {
      ok: options.okMessage || '保存しました',
      cancel: options.cancelMessage || '保存をキャンセルしました',
      error: options.errorMessage || '保存に失敗しました',
    });
  }

  async function saveTextDirect(path, content, options = {}) {
    try {
      const res = await apiPost('/save-file-direct', {
        path,
        content: options.bom ? '\uFEFF' + String(content || '') : String(content || ''),
        allow_register: !!options.allowRegister,
      });
      if (res?.ok) {
        _notifyManualSaveSuccess((options.okMessage || '上書き保存しました') + ': ' + res.path);
        return res;
      }
      return false;
    } catch (err) {
      if (typeof showStatus === 'function') showStatus(options.errorMessage || (err?.message || '保存に失敗しました'), true);
      return false;
    }
  }

  async function saveBlob(blob, options = {}) {
    const fallbackExtension = options.extension || '.bin';
    const { initialfile, extension } = splitFileName(
      options.initialfile || options.filename || '',
      options.title || options.fallbackTitle || '無題',
      fallbackExtension
    );
    if (_isStandaloneContext()) {
      // 単独アプリには /api/save-file-dialog が無い。File System Access API
      // (showSaveFilePicker) が使える環境ではファイル名/保存先を選べる方を優先し、
      // 使えない環境（一部のwebview等）は通常のダウンロードにフォールバックする。
      const pickerResult = await _saveBlobWithBrowserPicker(blob, initialfile, {
        ok: options.okMessage || '保存しました',
        cancel: options.cancelMessage || '保存をキャンセルしました',
        error: options.errorMessage || '保存に失敗しました',
      });
      if (pickerResult !== null) return pickerResult;
      return _standaloneSaveBlob(blob, options);
    }
    const pickerThreshold = options.browserPickerThreshold || LARGE_BLOB_PICKER_THRESHOLD;
    if (blob?.size > pickerThreshold) {
      const pickerResult = await _saveBlobWithBrowserPicker(blob, initialfile, {
        ok: options.okMessage || '保存しました',
        cancel: options.cancelMessage || '保存をキャンセルしました',
        error: options.errorMessage || '保存に失敗しました',
      });
      if (pickerResult !== null) return pickerResult;
    }
    let dataUrl = '';
    try {
      const reader = new FileReader();
      dataUrl = await new Promise((resolve, reject) => {
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(reader.error || new Error('ファイル内容を読み込めませんでした'));
        reader.readAsDataURL(blob);
      });
    } catch (err) {
      if (typeof showStatus === 'function') showStatus(options.errorMessage || (err?.message || '保存に失敗しました'), true);
      return false;
    }
    return _showDialog({
      title: options.dialogTitle || '書き出して保存',
      initialfile,
      defaultextension: extension,
      filetypes: options.filetypes || [['すべてのファイル', '*.*']],
      content_base64: String(dataUrl || '').split(',')[1] || '',
      binary: true,
    }, {
      ok: options.okMessage || '保存しました',
      cancel: options.cancelMessage || '保存をキャンセルしました',
      error: options.errorMessage || '保存に失敗しました',
    });
  }

  async function _saveBlobWithBrowserPicker(blob, initialfile, messages = {}) {
    if (typeof window === 'undefined' || typeof window.showSaveFilePicker !== 'function') return null;
    try {
      const handle = await window.showSaveFilePicker({ suggestedName: initialfile });
      const writable = await handle.createWritable();
      await blob.stream().pipeTo(writable);
      _notifyManualSaveSuccess(messages.ok || '保存しました');
      return true;
    } catch (err) {
      if (err?.name === 'AbortError') {
        if (typeof showStatus === 'function') showStatus(messages.cancel || '保存をキャンセルしました');
        return false;
      }
      return null;
    }
  }

  async function saveUrl(url, options = {}) {
    try {
      const headers = { ...(options.headers || {}) };
      try {
        if (options.auth !== false && typeof _authToken !== 'undefined' && _authToken && !headers.Authorization) {
          headers.Authorization = 'Bearer ' + _authToken;
        }
      } catch {}
      const res = await fetch(url, { credentials: 'same-origin', headers });
      if (!res.ok) {
        throw new Error(options.errorMessage || `保存元の取得に失敗しました (${res.status})`);
      }
      const headerName = _parseContentDispositionFileName(res.headers.get('content-disposition'));
      const fallbackName = options.filename
        || (sanitizeTitle(options.title || options.fallbackTitle || guessNameFromPath(options.path || '', '無題'), options.fallbackTitle || '無題')
          + (options.extension || '.bin'));
      const blob = await res.blob();
      return saveBlob(blob, {
        ...options,
        filename: headerName || fallbackName,
      });
    } catch (err) {
      if (typeof showStatus === 'function') showStatus(options.errorMessage || (err?.message || '保存に失敗しました'), true);
      return false;
    }
  }

  return {
    sanitizeTitle,
    guessNameFromPath,
    splitFileName,
    saveText,
    saveTextDirect,
    saveBlob,
    saveUrl,
  };

})();

if (typeof window !== 'undefined') {
  window.MeldexExportSave = MeldexExportSave;
}

;

/* === gb-public-runtime.js === */
;
/* 公開 HTML ランタイム生成
 *
 * 役割: 現在のビュー (page/database/csv/smart-db/calendar/entity) を
 *   現テーマを完全再現した静的 HTML としてエクスポートする。
 *   + 編集不可 (input を span 化 / contenteditable 除去)
 *   + 画像埋込 / フォント埋込 / CSS 変数取込
 *   + フォーム送信ランタイム (現在表示がフォームビューの場合のみ注入)
 *
 * 生成経路は MeldexExportHtml の共通ヘルパを再利用し、`buildHtml` と
 * DOM パイプライン (cloneAndClean / convertDataRuby / embedImages / embedFont)
 * を統一する。旧 payload-rebuild 方式 (固定ライトテーマ) は廃止。
 */

const MeldexPublicRuntime = (() => {
  function _jsonForScript(payload) {
    // `<` のみエスケープして `</script>` で DOM が閉じないようにする。
    // JSON は正しい文字列リテラルを含むので二重引用符はそのまま。
    return JSON.stringify(payload || {}).replace(/</g, '\\u003c');
  }

  // ==========================================================================
  // ランタイムスクリプト: 公開 HTML に注入されてクライアントで動作する。
  //   - フォーム送信 (form[data-publish-form] があれば有効化)
  //   - 現バージョンではタブ切替はサポートしない (単一ビュー公開)
  // ==========================================================================
  // ランタイムスクリプト: 公開 HTML 内でフォーム入力を収集し POST する。
  // - checkbox: チェック状態を 'true' / 'false' の文字列で明示送信 (未チェックも区別)
  // - image (file): 各ファイルを base64 data URL に読み込み、バックエンド契約の
  //   [{filename, type, data_url}, ...] 形式 JSON 文字列で送信
  // - その他: input.value をそのまま送信
  // 入力種別は _buildFormInputRow が付与する data-form-type で判別。
  const RUNTIME_SCRIPT = "(function(){\n"
    + "  function init() {\n"
    + "  var cfgEl = document.getElementById('meldex-publish-cfg');\n"
    + "  var cfg = {};\n"
    + "  try { cfg = JSON.parse(cfgEl && cfgEl.textContent || '{}'); } catch (e) {}\n"
    + "  var form = document.querySelector('form[data-publish-form]');\n"
    + "  if (!form) return;\n"
    + "  var msg = document.getElementById('meldex-publish-msg');\n"
    + "  function successMessage() { return cfg.success_message || cfg.successMessage || '送信しました'; }\n"
    + "  function pad2(value) { return String(value).padStart(2, '0'); }\n"
    + "  function templateEntityName(template) {\n"
    + "    var d = new Date();\n"
    + "    return String(template || 'フォーム送信 {yyyy}-{MM}-{dd} {HH}:{mm}')\n"
    + "      .replace(/\\{yyyy\\}/g, String(d.getFullYear()))\n"
    + "      .replace(/\\{MM\\}/g, pad2(d.getMonth() + 1))\n"
    + "      .replace(/\\{dd\\}/g, pad2(d.getDate()))\n"
    + "      .replace(/\\{HH\\}/g, pad2(d.getHours()))\n"
    + "      .replace(/\\{mm\\}/g, pad2(d.getMinutes()))\n"
    + "      .replace(/\\{ss\\}/g, pad2(d.getSeconds()));\n"
    + "  }\n"
    + "  function buildEntityName(fields) {\n"
    + "    var source = cfg.form_entity_name_source || cfg.formEntityNameSource || null;\n"
    + "    if (!source || typeof source !== 'object') return '';\n"
    + "    if (source.kind === 'property') {\n"
    + "      var prop = String(source.property || '');\n"
    + "      return prop ? String(fields[prop] || '').trim().slice(0, 80) : '';\n"
    + "    }\n"
    + "    if (source.kind === 'timestamp') return templateEntityName('フォーム送信 {yyyy}-{MM}-{dd} {HH}-{mm}-{ss}');\n"
    + "    if (source.kind === 'template') return templateEntityName(source.template || '');\n"
    + "    return '';\n"
    + "  }\n"
    + "  function postFeedbackToGoogle(payload) {\n"
    + "    var url = String(cfg.feedback_google_url || '').trim();\n"
    + "    if (!cfg.feedback_relay_enabled || !/^https:\\/\\/script\\.google\\.com\\/macros\\/s\\//.test(url)) return;\n"
    + "    try {\n"
    + "      fetch(url, {\n"
    + "        method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain;charset=utf-8' },\n"
    + "        body: JSON.stringify({ app: 'Meldex', kind: 'feedback', sheet: cfg.feedback_google_sheet || 'feedback', payload: payload, sentAt: new Date().toISOString() })\n"
    + "      });\n"
    + "    } catch (err) {}\n"
    + "  }\n"
    + "  function readFileAsDataUrl(file) {\n"
    + "    return new Promise(function (resolve, reject) {\n"
    + "      var r = new FileReader();\n"
    + "      r.onload = function () { resolve(String(r.result || '')); };\n"
    + "      r.onerror = function () { reject(r.error || new Error('read failed')); };\n"
    + "      r.readAsDataURL(file);\n"
    + "    });\n"
    + "  }\n"
    + "  async function collectFields() {\n"
    + "    var fields = {};\n"
    + "    // name 属性付きの入力要素を全部見る (checkbox / file も含めて明示的に処理)\n"
    + "    var els = form.querySelectorAll('input[name], textarea[name], select[name]');\n"
    + "    for (var i = 0; i < els.length; i += 1) {\n"
    + "      var el = els[i];\n"
    + "      var name = el.getAttribute('name');\n"
    + "      if (!name) continue;\n"
    + "      var type = (el.dataset && el.dataset.formType) || el.type || 'text';\n"
    + "      if (type === 'checkbox' || el.type === 'checkbox') {\n"
    + "        fields[name] = el.checked ? 'true' : 'false';\n"
    + "        continue;\n"
    + "      }\n"
    + "      if (type === 'image' || el.type === 'file') {\n"
    + "        var files = Array.from(el.files || []);\n"
    + "        var items = [];\n"
    + "        for (var j = 0; j < files.length; j += 1) {\n"
    + "          var f = files[j];\n"
    + "          try {\n"
    + "            var dataUrl = await readFileAsDataUrl(f);\n"
    + "            items.push({ filename: f.name, type: f.type || '', data_url: dataUrl });\n"
    + "          } catch (err) { throw new Error('画像を読み込めませんでした: ' + (f && f.name || '添付ファイル')); }\n"
    + "        }\n"
    + "        fields[name] = JSON.stringify(items);\n"
    + "        continue;\n"
    + "      }\n"
    + "      if (el.type === 'radio') {\n"
    + "        if (el.checked) fields[name] = el.value;\n"
    + "        else if (!(name in fields)) fields[name] = '';\n"
    + "        continue;\n"
    + "      }\n"
    + "      fields[name] = el.value != null ? String(el.value) : '';\n"
    + "    }\n"
    + "    return fields;\n"
    + "  }\n"
    + "  form.addEventListener('submit', async function (e) {\n"
    + "    e.preventDefault();\n"
    + "    if (!cfg.form_submit_enabled) { if (msg) msg.textContent = '現在受付停止中です'; return; }\n"
    + "    if (msg) msg.textContent = '送信中...';\n"
    + "    var fields = {};\n"
    + "    try { fields = await collectFields(); } catch (err) {\n"
    + "      if (msg) msg.textContent = '入力収集失敗: ' + (err && err.message || err);\n"
    + "      return;\n"
    + "    }\n"
    + "    var body = {\n"
    + "      db_path: cfg.db_path || '',\n"
    + "      token: cfg.form_submit_token || '',\n"
    + "      form_id: cfg.form_id || '',\n"
    + "      name: buildEntityName(fields),\n"
    + "      fields: fields\n"
    + "    };\n"
    + "    try {\n"
    + "      var res = await fetch(cfg.submit_url || '/api/public-form/submit', {\n"
    + "        method: 'POST', headers: { 'Content-Type': 'application/json' },\n"
    + "        body: JSON.stringify(body)\n"
    + "      });\n"
    + "      if (msg) msg.textContent = res.ok ? successMessage() : ('送信失敗 (' + res.status + ')');\n"
    + "      if (res.ok) {\n"
    + "        postFeedbackToGoogle({ dbPath: body.db_path, formId: body.form_id, fields: fields, source: 'public-form', userAgent: navigator.userAgent || '' });\n"
    + "        form.reset();\n"
    + "      }\n"
    + "    } catch (err) {\n"
    + "      if (msg) msg.textContent = '送信失敗: ' + (err && err.message || err);\n"
    + "    }\n"
    + "  });\n"
    + "  }\n"
    + "  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true }); else init();\n"
    + "})();";

  // ==========================================================================
  // ビュータイプごとの入力要素取得・CSS ファイル・追加 CSS を決定
  // ==========================================================================
  function _resolveViewDef(viewType) {
    if (viewType === 'page' || viewType === 'entity') {
      const el = viewType === 'entity'
        ? document.getElementById('entity-view')
        : document.getElementById('page-content');
      // ノート本文の組方向は公開HTMLにも反映する。スタイル本体は gb-export-html.js の
      // noteExportCss と共有して、書き出し・画像・公開で見た目がずれないようにする。
      const noteVertical = viewType === 'page'
        && !!(window.MeldexNoteWritingMode && window.MeldexNoteWritingMode.isVertical(el));
      const noteCss = (typeof MeldexExportHtml !== 'undefined' && MeldexExportHtml.noteExportCss)
        ? MeldexExportHtml.noteExportCss(noteVertical)
        : '#page-content, [id="page-content"] { padding: 16px 60px; line-height: 1.7; max-width: 900px; margin: 0 auto; }\n'
          + 'ruby { ruby-position: over; }\n'
          + 'rt { font-size: 0.55em; line-height: 1; color: inherit; opacity: 0.75; }\n';
      return {
        el,
        cssFiles: ['gb-tools.css', 'gb-ui.css'],
        extraCss:
          noteCss + '\n'
          + '#entity-view { padding: 16px 60px; line-height: 1.7; max-width: 900px; margin: 0 auto; box-sizing: border-box; }\n',
        notFound: 'ノートが開かれていません',
      };
    }
    if (viewType === 'database') {
      // 現在の DB ビューモードで分岐: フォームビューならフォームを、それ以外はテーブルを公開
      const dbPath = (typeof state !== 'undefined' && state.currentDbPath) || '';
      const viewMode = (typeof getCurrentViewMode === 'function' && dbPath) ? getCurrentViewMode(dbPath) : (state?.view || 'pivot');
      if (viewMode === 'form') {
        // 公開用フォームを新規構築 (_buildFormAnswerPanel で publicMode=true 指定)
        const props = state.pivotData?.properties || [];
        const propTypes = (typeof getPropertyTypes === 'function') ? getPropertyTypes(dbPath) || {} : {};
        const formCfg = (typeof getActiveFormConfig === 'function')
          ? getActiveFormConfig(dbPath, props, propTypes)
          : null;
        if (!formCfg) return { el: null, cssFiles: [], extraCss: '', notFound: 'フォーム設定を取得できません' };
        let formEl = null;
        if (typeof _buildFormAnswerPanel === 'function') {
          formEl = _buildFormAnswerPanel(dbPath, formCfg, propTypes, true);
        }
        if (!formEl) return { el: null, cssFiles: [], extraCss: '', notFound: 'フォームを構築できません' };
        // 送信ランタイム検出用マーカー
        formEl.setAttribute('data-publish-form', '1');
        // ランタイムスクリプトが何らかの理由で動作しない場合でも、
        // デフォルト submit によるページリロードを抑止する。
        // action="javascript:void(0)" は form のネイティブ送信を無害化。
        formEl.setAttribute('action', 'javascript:void(0)');
        // DOM に接続しないまま cloneAndClean に渡す
        // （_buildFormAnswerPanel は computed style に依存しないため DOM 接続不要）
        return {
          el: formEl,
          preserveFormControls: true,
          runtimeExtras: {
            form_id: formCfg?.id || '',
            success_message: formCfg?.successMessage || '送信しました',
            feedback_relay_enabled: !!formCfg?.betaFeedbackRelay,
            ...(formCfg?.entityNameProp ? { form_entity_name_source: { kind: 'property', property: formCfg.entityNameProp } } : {}),
          },
          cssFiles: ['gb-tools.css', 'gb-ui.css'],
          extraCss:
            'body { padding: 24px; }\n'
            + 'form[data-publish-form] { max-width: 680px; margin: 0 auto; }\n'
            // getStaticCss の `input,textarea,select { display:none !important; }` を
            // 高特異度セレクタで上書き (pointer-events/cursor も有効化)
            + 'form[data-publish-form] input,\n'
            + 'form[data-publish-form] textarea,\n'
            + 'form[data-publish-form] select {\n'
            + '  display: revert !important;\n'
            + '  pointer-events: auto !important;\n'
            + '  cursor: text !important;\n'
            + '}\n'
            + 'form[data-publish-form] input[type="checkbox"],\n'
            + 'form[data-publish-form] input[type="radio"] { cursor: pointer !important; }\n'
            + 'form[data-publish-form] button,\n'
            + 'form[data-publish-form] button[type="submit"] {\n'
            + '  display: revert !important;\n'
            + '  pointer-events: auto !important;\n'
            + '  cursor: pointer !important;\n'
            + '  opacity: 1 !important;\n'
            + '}\n',
          notFound: 'フォームを構築できません',
        };
      }
      return {
        el: document.getElementById('pivot-table'),
        cssFiles: ['gb-tools.css', 'gb-ui.css'],
        extraCss:
          'body { padding: 16px; }\n'
          + 'table { border-collapse: collapse; table-layout: fixed; width: 100%; }\n'
          + 'th, td { border: 1px solid var(--border, #333); padding: 4px 8px; }\n'
          + 'thead { position: static; }\n',
        notFound: 'シートが開かれていません',
        preTransform: _preTransformDatabaseTable,
      };
    }
    if (viewType === 'csv') {
      const container = document.getElementById('csv-table-container');
      return {
        el: container ? container.querySelector('table') : null,
        cssFiles: [],
        extraCss:
          'body { padding: 16px; }\n'
          + 'table { border-collapse: collapse; table-layout: auto; }\n'
          + 'th, td { border: 1px solid var(--border, #333); padding: 4px 8px; white-space: pre-wrap; }\n'
          + 'thead th { background: var(--bg2, #252525); position: static; }\n',
        notFound: 'CSV が開かれていません',
      };
    }
    if (viewType === 'smart-db') {
      const el = (typeof getSmartDbActiveView === 'function' && getSmartDbActiveView() === 'dashboard')
        ? document.getElementById('smart-db-dashboard-area')
        : document.getElementById('smart-db-table');
      return {
        el,
        cssFiles: ['gb-tools.css', 'gb-ui.css'],
        extraCss:
          'body { padding: 16px; }\n'
          + 'table { border-collapse: collapse; table-layout: auto; width: 100%; }\n'
          + 'th, td { border: 1px solid var(--border, #333); padding: 4px 8px; }\n',
        notFound: 'スマートシートが開かれていません',
      };
    }
    if (viewType === 'calendar') {
      const calRoot = document.querySelector('.gb-cal-root');
      return {
        el: calRoot,
        cssFiles: ['gb-tools.css', 'gb-ui.css'],
        extraCss: 'body { padding: 16px; }\n',
        notFound: 'カレンダーが開かれていません',
      };
    }
    return { el: null, cssFiles: [], extraCss: '', notFound: 'この種別は公開 HTML 未対応です' };
  }

  // DB テーブル: 列幅とステータスバッジ色を computed value でインライン化
  // (これがないとクローン側では getComputedStyle が効かない)
  function _preTransformDatabaseTable(originalEl, clone) {
    if (!originalEl || !clone) return;
    const origCells = originalEl.querySelectorAll('th, td');
    const cellWidths = Array.from(origCells).map(c => c.getBoundingClientRect().width);
    const cloneCells = clone.querySelectorAll('th, td');
    cellWidths.forEach((w, i) => {
      if (cloneCells[i]) {
        cloneCells[i].style.width = w + 'px';
        cloneCells[i].style.minWidth = w + 'px';
      }
    });
    const origBadges = originalEl.querySelectorAll('[class*="status-"]');
    const cloneBadges = clone.querySelectorAll('[class*="status-"]');
    origBadges.forEach((b, i) => {
      if (!cloneBadges[i]) return;
      const cs = getComputedStyle(b);
      cloneBadges[i].style.backgroundColor = cs.backgroundColor;
      cloneBadges[i].style.color = cs.color;
    });
  }

  // ==========================================================================
  // 公開 HTML 構築メイン: viewType + publish 設定から自己完結 HTML 文字列を返す
  // ==========================================================================
  async function buildPublishHtml(viewType, publishCfg) {
    publishCfg = publishCfg || {};
    if (typeof MeldexExportHtml === 'undefined') {
      showStatus('HTML 出力エンジンを読み込めませんでした', true);
      return null;
    }
    const def = _resolveViewDef(viewType);
    if (!def.el) {
      showStatus(def.notFound || '公開対象が見つかりません', true);
      return null;
    }
    try {
      // DOM クローン → クリーンアップ → ルビ変換 → preTransform → 画像埋込
      const clone = MeldexExportHtml.cloneAndClean(def.el, {
        preserveFormControls: !!def.preserveFormControls,
      });
      MeldexExportHtml.convertDataRuby(clone);
      if (typeof def.preTransform === 'function') def.preTransform(def.el, clone);
      await MeldexExportHtml.embedImages(clone);

    // CSS: ルート変数 + 追加 CSS ファイル + ビュー固有 CSS + 公開ランタイム CSS
    const varDecls = typeof MeldexExportHtml.collectCssVars === 'function'
      ? MeldexExportHtml.collectCssVars()
      : '';
    let cssText = ':root { ' + varDecls + ' }\n';
    cssText += 'html, body { margin: 0; padding: 0; background: var(--bg, #1e1e1e); color: var(--fg, #d4d4d4);'
      + ' font-family: var(--ui-font, "Noto Sans JP", "Hiragino Sans", "Yu Gothic UI", "Meiryo", sans-serif);'
      + ' font-size: var(--ui-font-size, 15px); }\n';
    for (const f of def.cssFiles) {
      cssText += await MeldexExportHtml.fetchCss(f) + '\n';
    }
    cssText += def.extraCss + '\n';
    // 公開ランタイム用の補助スタイル (メッセージ表示等)
    cssText += '#meldex-publish-msg { margin-top: 10px; color: var(--accent, #4a90d9); font-size: 13px; }\n';

    // フォント埋込 (publish 設定で制御)
    const fontCss = publishCfg.embed_font !== false
      ? await MeldexExportHtml.embedFont()
      : '';

    // ランタイム設定 (def.runtimeExtras があればマージ)
    const runtimeCfg = {
      db_path: publishCfg.db_path || (typeof state !== 'undefined' && state.currentDbPath) || '',
      form_submit_enabled: !!publishCfg.form_submit_enabled,
      form_submit_token: publishCfg.form_submit_token || '',
      form_id: publishCfg.form_id || '',
      success_message: publishCfg.success_message || publishCfg.successMessage || '',
      form_entity_name_source: publishCfg.form_entity_name_source || publishCfg.formEntityNameSource || null,
      feedback_relay_enabled: !!publishCfg.feedback_relay_enabled,
      feedback_google_url: publishCfg.feedback_google_url || (window.MeldexReleaseConfig?.betaFeedback?.googleWebAppUrl || ''),
      feedback_google_sheet: publishCfg.feedback_google_sheet || (window.MeldexReleaseConfig?.betaFeedback?.feedbackSheetName || 'feedback'),
      submit_url: publishCfg.submit_url
        || (publishCfg.server_public_url
          ? String(publishCfg.server_public_url).replace(/\/+$/, '') + '/api/public-form/submit'
          : ''),
      ...(def.runtimeExtras || {}),
    };
    const extraHeadHtml =
      '<script type="application/json" id="meldex-publish-cfg">'
      + _jsonForScript(runtimeCfg)
      + '</script>\n'
      + '<script>' + RUNTIME_SCRIPT + '</script>';

    // body: クローン済み HTML + メッセージ領域
    const bodyHtml = clone.outerHTML + '\n<div id="meldex-publish-msg"></div>';

    const title = publishCfg.title || (typeof _getViewTitle === 'function' ? _getViewTitle(viewType) : 'Meldex');
      return MeldexExportHtml.buildHtml(title, bodyHtml, cssText, fontCss, extraHeadHtml);
    } finally {
      // 画面外に一時配置したフォーム等の仮要素を破棄
      if (def.disposeEl && def.disposeEl.parentNode) {
        try { def.disposeEl.parentNode.removeChild(def.disposeEl); } catch {}
      }
    }
  }

  return {
    buildPublishHtml,
  };
})();

;

/* === gb-cloud-form-relay.js === */
;
/* 公開フォーム クラウド中継アダプタの共通入口 */

const MeldexCloudFormRelay = (() => {
  const adapters = new Map();

  function register(name, adapter) {
    if (!name || !adapter) return;
    adapters.set(name, adapter);
  }

  function get(name) {
    return adapters.get(name) || null;
  }

  async function submit(name, payload, options) {
    const adapter = get(name);
    if (!adapter || typeof adapter.submit !== 'function') {
      throw new Error('クラウド中継アダプタが未設定です: ' + name);
    }
    return adapter.submit(payload, options || {});
  }

  return { register, get, submit };
})();

;

/* === gb-scriptnote-rules.js === */
;
/* gb-scriptnote-rules.js: シナリオエディタ用 入力設定 UI */

function getScenarioNoteLayoutLabel() {
  const value = typeof getScenarioNoteLayoutMode === 'function' ? getScenarioNoteLayoutMode(doc) : '';
  if (value === 'drama') return 'ドラマ・映画シナリオ';
  if (value === 'afureko') return 'アフレコシナリオ';
  if (value === 'stage') return '舞台シナリオ';
  return 'マンガシナリオ';
}

function _rulesAttrValue(value) {
  return esc(value == null ? '' : String(value));
}

function _rulesNamedActionAttrs(action, kind, name, extra = {}) {
  let attrs = `data-rules-action="${_rulesAttrValue(action)}" data-rules-kind="${_rulesAttrValue(kind)}" data-rules-name="${_rulesAttrValue(name)}"`;
  Object.entries(extra).forEach(([key, value]) => {
    attrs += ` data-rules-${key}="${_rulesAttrValue(value)}"`;
  });
  return attrs;
}

function _rulesNamedChangeAttrs(change, kind, name, extra = {}) {
  let attrs = `data-rules-change="${_rulesAttrValue(change)}" data-rules-kind="${_rulesAttrValue(kind)}" data-rules-name="${_rulesAttrValue(name)}"`;
  Object.entries(extra).forEach(([key, value]) => {
    attrs += ` data-rules-${key}="${_rulesAttrValue(value)}"`;
  });
  return attrs;
}

function _rulesBindStructuredHandlers(el) {
  if (!el || el._rulesStructuredBound) return;
  el._rulesStructuredBound = true;

  el.addEventListener('keydown', (event) => {
    const target = event.target.closest('[data-rules-action][role="button"]');
    if (!target || !el.contains(target)) return;
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    target.click();
  });

  el.addEventListener('click', (event) => {
    const target = event.target.closest('[data-rules-action]');
    if (!target || !el.contains(target)) return;
    const action = target.dataset.rulesAction || '';
    const kind = target.dataset.rulesKind || '';
    const name = target.dataset.rulesName || '';
    switch (action) {
      case 'pick-color':
        if (typeof _rulesPickColor === 'function') _rulesPickColor(target.dataset.rulesColorType || '', name, target);
        return;
      case 'toggle-chara-global-font':
        if (typeof _rulesToggleCharaGlobalFont === 'function') _rulesToggleCharaGlobalFont(target.dataset.rulesFontKey || '');
        return;
      case 'toggle-named-font':
        if (typeof _rulesToggleNamedFont === 'function') _rulesToggleNamedFont(kind, name, target.dataset.rulesFontKey || '');
        return;
      case 'remove-chara':
        if (typeof _rulesRemoveChara === 'function') _rulesRemoveChara(name);
        return;
      case 'add-chara':
        if (typeof _rulesAddChara === 'function') _rulesAddChara();
        return;
      case 'open-character-db-import':
        if (typeof openScenarioCharacterDbImport === 'function') openScenarioCharacterDbImport();
        return;
      case 'add-checked-charas':
        if (typeof _rulesAddCheckedCharas === 'function') _rulesAddCheckedCharas();
        return;
      case 'add-custom-type':
        if (typeof _rulesAddCustomType === 'function') _rulesAddCustomType(kind);
        return;
      case 'clear-named-style':
        if (kind === 'special' && typeof _rulesClearSpecialChara === 'function') _rulesClearSpecialChara(name);
        else if (kind === 'rowtype' && typeof _rulesClearRowType === 'function') _rulesClearRowType(name);
        return;
      case 'delete-mode-type':
        if (typeof _rulesDeleteModeType === 'function') _rulesDeleteModeType(kind, name);
        return;
      default:
        return;
    }
  });

  el.addEventListener('dragstart', (event) => {
    const target = event.target.closest('[data-rules-drag-kind]');
    if (!target || !el.contains(target)) return;
    const kind = target.dataset.rulesDragKind || '';
    const index = Number(target.dataset.rulesIndex || '0');
    if (kind === 'chara' && typeof _rulesCharaDragStart === 'function') _rulesCharaDragStart(event, index);
    else if (typeof _rulesTypeDragStart === 'function') _rulesTypeDragStart(event, kind, index);
  });

  el.addEventListener('dragover', (event) => {
    const target = event.target.closest('[data-rules-drag-kind]');
    if (!target || !el.contains(target)) return;
    const kind = target.dataset.rulesDragKind || '';
    const index = Number(target.dataset.rulesIndex || '0');
    if (kind === 'chara' && typeof _rulesCharaDragOver === 'function') _rulesCharaDragOver(event, index);
    else if (typeof _rulesTypeDragOver === 'function') _rulesTypeDragOver(event, kind, index);
  });

  el.addEventListener('drop', (event) => {
    const target = event.target.closest('[data-rules-drag-kind]');
    if (!target || !el.contains(target)) return;
    const kind = target.dataset.rulesDragKind || '';
    const index = Number(target.dataset.rulesIndex || '0');
    if (kind === 'chara' && typeof _rulesCharaDrop === 'function') _rulesCharaDrop(event, index);
    else if (typeof _rulesTypeDrop === 'function') _rulesTypeDrop(event, kind, index);
  });

  el.addEventListener('dragend', (event) => {
    const target = event.target.closest('[data-rules-drag-kind]');
    if (!target || !el.contains(target)) return;
    const kind = target.dataset.rulesDragKind || '';
    if (kind === 'chara' && typeof _rulesCharaDragEnd === 'function') _rulesCharaDragEnd();
    else if (typeof _rulesTypeDragEnd === 'function') _rulesTypeDragEnd();
  });

  el.addEventListener('change', (event) => {
    const target = event.target.closest('[data-rules-change]');
    if (!target || !el.contains(target)) return;
    const change = target.dataset.rulesChange || '';
    const kind = target.dataset.rulesKind || '';
    const name = target.dataset.rulesName || '';
    switch (change) {
      case 'chara-auto-color-target':
        if (typeof _rulesSetCharaAutoColorTarget === 'function') _rulesSetCharaAutoColorTarget(target.value);
        return;
      case 'chara-global-font-size':
        if (typeof _rulesSetCharaGlobalFontSize === 'function') _rulesSetCharaGlobalFontSize(target.value);
        return;
      case 'rename-chara':
        if (typeof _rulesRenameChara === 'function') _rulesRenameChara(name, target.value);
        return;
      case 'named-font-size':
        if (typeof _rulesSetNamedFontSize === 'function') _rulesSetNamedFontSize(kind, name, target.value);
        return;
      case 'page-visual-style':
        if (typeof _rulesSetPageVisualStyle === 'function') _rulesSetPageVisualStyle(name, target.value);
        return;
      case 'page-display-prefix':
        if (typeof _rulesSetPageDisplayPrefix === 'function') _rulesSetPageDisplayPrefix(name, target.value);
        return;
      case 'page-separator-text':
        if (typeof _rulesSetPageSeparatorText === 'function') _rulesSetPageSeparatorText(name, target.value);
        return;
      case 'page-boundary-line':
        if (typeof _rulesSetPageBoundaryLine === 'function') _rulesSetPageBoundaryLine(name, !!target.checked);
        return;
      default:
        return;
    }
  });
}

function _rulesGetActiveScriptNoteEditor() {
  const comp = typeof getActiveScriptNoteComponent === 'function' ? getActiveScriptNoteComponent() : null;
  if (comp?._editor?.doc) return comp._editor;
  return typeof _sn2GetActiveEditor === 'function' ? _sn2GetActiveEditor() : null;
}

function renderScriptNoteRulesTab(targetEl = null) {
  const el = targetEl;
  if (!el) return;
  const activeEditor = _rulesGetActiveScriptNoteEditor();
  if (activeEditor?.doc && typeof activeEditor.renderDetailPanel === 'function') {
    activeEditor.renderDetailPanel(el);
    return;
  }
  const legacyDoc = typeof doc !== 'undefined' ? doc : null;
  if (!legacyDoc || !legacyDoc.settings) {
    el.innerHTML = '<div class="rules-fallback-message">シナリオファイルを開いてください</div>';
    return;
  }
  const globalObj = typeof globalThis !== 'undefined' ? globalThis : window;
  const missingLegacyDeps = [
    'ensureScenarioSettings',
    '_rulesGetCharaStyleDefaults',
    '_rulesGetCharaAutoColorTarget',
    '_rulesResolveCharaBgColor',
    '_rulesResolveCharaTextColor',
    '_rulesRenderPreview',
    '_rulesEnsureSpecialStyle',
    '_rulesEnsureRowTypeStyle',
    'ensurePageSettingBehavior',
    '_rulesSetCharaAutoColorTarget',
    '_rulesToggleCharaGlobalFont',
    '_rulesSetCharaGlobalFontSize',
    '_rulesPickColor',
    '_rulesRenameChara',
    '_rulesRemoveChara',
    '_rulesAddChara',
    'openScenarioCharacterDbImport',
    '_rulesAddCheckedCharas',
    '_rulesAddCustomType',
    '_rulesCharaDragStart',
    '_rulesCharaDragOver',
    '_rulesCharaDrop',
    '_rulesCharaDragEnd',
    '_rulesTypeDragStart',
    '_rulesTypeDragOver',
    '_rulesTypeDrop',
    '_rulesTypeDragEnd',
    '_rulesToggleNamedFont',
    '_rulesClearSpecialChara',
    '_rulesClearRowType',
    '_rulesDeleteModeType',
    '_rulesSetNamedFontSize',
    '_rulesSetPageVisualStyle',
    '_rulesSetPageDisplayPrefix',
    '_rulesSetPageSeparatorText',
    '_rulesSetPageBoundaryLine',
  ].filter((name) => typeof globalObj[name] !== 'function');
  if (missingLegacyDeps.length
      || typeof SPECIAL_CHARA === 'undefined'
      || typeof PAGE_SETTINGS === 'undefined'
      || typeof RULE_PAGE_VISUAL_STYLE_OPTIONS === 'undefined') {
    el.innerHTML = '<div class="rules-fallback-message">現行シナリオエディタのタイプ管理タブを使用してください</div>';
    return;
  }
  ensureScenarioSettings(doc);
  let html = '';

  html += '<div class="rules-section">';
  html += `<div class="rules-section-title">入力設定 ${fieldHelp('シナリオエディタで使う候補名と基本書式を設定します。ここではキャラ・特殊キャラ・行タイプだけを扱います。')}</div>`;
  html += `<div class="rules-type-row rules-type-row--top">
    <span class="rules-type-label rules-type-label--fixed">現在の書式 ${fieldHelp('表示方向・折返し・幅・行間・字間・フォントはシナリオエディタのツールバーで調整します。')}</span>
    <div class="rules-current-body">
      <div>シナリオ書式: <strong class="rules-current-name">${esc(getScenarioNoteLayoutLabel())}</strong></div>
    </div>
  </div>`;
  html += '</div>';

  html += '<div class="rules-section">';
  html += `<div class="rules-section-title">キャラ設定 ${fieldHelp('キャラ候補と基本書式です。シナリオエディタのキャラ選択候補へ反映されます。')}</div>`;
  const charaDefaults = _rulesGetCharaStyleDefaults();
  const globalAutoTarget = _rulesGetCharaAutoColorTarget();
  const globalBold = (charaDefaults.fontWeight || 'bold') === 'bold';
  const globalItalic = charaDefaults.fontStyle === 'italic';
  const globalFontSize = charaDefaults.fontSize || '';
  html += `<div class="rules-type-row rules-type-row--wrap rules-chara-global-row">
    <span class="rules-type-label rules-type-label--fixed">共通設定</span>
    <select class="rules-mini-select" ${_rulesNamedChangeAttrs('chara-auto-color-target', 'chara', 'global')} title="自動配色の適用先" aria-label="自動配色の適用先">
      <option value="bg"${globalAutoTarget==='bg' ? ' selected' : ''}>背景へ</option>
      <option value="text"${globalAutoTarget==='text' ? ' selected' : ''}>文字へ</option>
      <option value="none"${globalAutoTarget==='none' ? ' selected' : ''}>不使用</option>
    </select>
    <button type="button" class="rules-font-btn rules-font-btn--bold${globalBold?' active':''}" ${_rulesNamedActionAttrs('toggle-chara-global-font', 'chara', 'global', { 'font-key': 'fontWeight' })} title="太字" aria-label="キャラ共通 太字">B</button>
    <button type="button" class="rules-font-btn rules-font-btn--italic${globalItalic?' active':''}" ${_rulesNamedActionAttrs('toggle-chara-global-font', 'chara', 'global', { 'font-key': 'fontStyle' })} title="斜体" aria-label="キャラ共通 斜体">I</button>
    <input type="number" class="rules-font-size" value="${globalFontSize}" min="8" max="24" placeholder="${_rulesGetCharacterFontPlaceholder()}"
      ${_rulesNamedChangeAttrs('chara-global-font-size', 'chara', 'global')} title="フォントサイズ(px)" aria-label="キャラ共通 フォントサイズ">
  </div>`;
  if (!doc.characters.length) {
    html += '<div class="rules-empty-note">キャラなし</div>';
  } else {
    doc.characters.forEach((c, i) => {
      if (c.isDefault) return; // 役割空行用デフォルトタイプはこの一覧では非表示
      const bg = _rulesResolveCharaBgColor(c);
      const tc = _rulesResolveCharaTextColor(c);
      const tcDisplay = tc || (isLightTheme() ? '#333' : '#aaa');
      const bgClass = globalAutoTarget === 'bg' ? 'rules-swatch rules-swatch-auto' : 'rules-swatch';
      const textClass = globalAutoTarget === 'text' ? 'rules-swatch rules-swatch-text rules-swatch-auto' : 'rules-swatch rules-swatch-text';
      html += `<div class="rules-chara-row" draggable="true" data-rules-chara-idx="${i}" data-rules-drag-kind="chara" data-rules-index="${i}">
        <span class="rules-drag-handle">⠿</span>
        <div class="${bgClass}" style="background:${_rulesGetSwatchBackground(bg, 'var(--bg3)')};${bg === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
          ${_rulesNamedActionAttrs('pick-color', 'chara', i, { 'color-type': 'chara-bg' })} role="button" tabindex="0" title="背景色" aria-label="${_rulesAttrValue((c.name || 'キャラ') + ' 背景色')}"></div>
        <div class="${textClass}" style="background:${_rulesGetSwatchBackground(tcDisplay, 'var(--fg2)')};border:1px solid var(--border);${tcDisplay === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
          ${_rulesNamedActionAttrs('pick-color', 'chara', i, { 'color-type': 'chara-text' })} role="button" tabindex="0" title="文字色" aria-label="${_rulesAttrValue((c.name || 'キャラ') + ' 文字色')}"></div>
        ${_rulesRenderPreview(c.name || '見本', { bgColor: bg, textColor: tc, fontWeight: charaDefaults.fontWeight || 'bold', fontStyle: charaDefaults.fontStyle || 'normal', fontSize: charaDefaults.fontSize || null }, { bgTransform: bg, defaultTextColor: tcDisplay })}
        <input class="rules-chara-name" value="${esc(c.name)}" ${_rulesNamedChangeAttrs('rename-chara', 'chara', i)} aria-label="${_rulesAttrValue((c.name || 'キャラ') + ' 名前')}">
        <button type="button" class="rules-remove" ${_rulesNamedActionAttrs('remove-chara', 'chara', i)} aria-label="${_rulesAttrValue((c.name || 'キャラ') + 'を削除')}">${lucide('x', 12)}</button>
      </div>`;
    });
  }
  html += `<div class="rules-action-row">
    <input id="rules-new-chara" class="rules-input" placeholder="キャラ名..." aria-label="追加するキャラ名">
    <button type="button" class="rules-add-btn" ${_rulesNamedActionAttrs('add-chara', 'chara', 'new')}>追加</button>
    <button type="button" class="rules-secondary-btn" ${_rulesNamedActionAttrs('open-character-db-import', 'chara', 'db')} title="シートからキャラを読み込み">DB読込</button>
  </div>`;
  if (doc.characterDb && doc.characterDb.length > 0) {
    const avail = doc.characterDb.filter(name => !doc.characters.some(c => c.name === name));
    if (avail.length > 0) {
      html += '<div class="rules-db-caption">候補済みのDB名:</div><div class="rules-db-list">';
      avail.forEach(name => {
        html += `<label class="rules-db-label"><input type="checkbox" value="${esc(name)}" class="rules-db-check"><span>${esc(name)}</span></label>`;
      });
      html += `</div><button type="button" class="rules-secondary-btn rules-secondary-btn--stacked" ${_rulesNamedActionAttrs('add-checked-charas', 'chara', 'db')}>チェック分を追加</button>`;
    }
  }
  html += '</div>';

  html += '<div class="rules-section">';
  html += `<div class="rules-section-title">特殊キャラ設定 ${fieldHelp('ト書きやナレーションなど、シナリオ用の補助行候補です。')}</div>`;
  SPECIAL_CHARA.forEach((sc, i) => {
    const style = _rulesEnsureSpecialStyle(sc);
    const bgCol = style.bgColor || '';
    const textCol = style.textColor || '';
    const isBold = style.fontWeight === 'bold';
    const isItalic = style.fontStyle === 'italic';
    const fSize = style.fontSize || '';
    html += `<div class="rules-chara-row" draggable="true" data-rules-type-kind="special" data-rules-type-idx="${i}" data-rules-drag-kind="special" data-rules-index="${i}">
      <span class="rules-drag-handle">⠿</span>
      <div class="rules-swatch" style="background:${_rulesGetSwatchBackground(bgCol, 'var(--bg3)')};${bgCol === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
        ${_rulesNamedActionAttrs('pick-color', 'special', sc, { 'color-type': 'special-bg' })} role="button" tabindex="0" title="背景色" aria-label="${_rulesAttrValue(sc + ' 背景色')}"></div>
      <div class="rules-swatch rules-swatch-text" style="background:${_rulesGetSwatchBackground(textCol, 'var(--fg2)')};border:1px solid var(--border);${textCol === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
        ${_rulesNamedActionAttrs('pick-color', 'special', sc, { 'color-type': 'special-text' })} role="button" tabindex="0" title="文字色" aria-label="${_rulesAttrValue(sc + ' 文字色')}"></div>
      ${_rulesRenderPreview(sc || '見本', style)}
      <button type="button" class="rules-font-btn rules-font-btn--bold${isBold?' active':''}" ${_rulesNamedActionAttrs('toggle-named-font', 'special', sc, { 'font-key': 'fontWeight' })} title="太字" aria-label="${_rulesAttrValue(sc + ' 太字')}">B</button>
      <button type="button" class="rules-font-btn rules-font-btn--italic${isItalic?' active':''}" ${_rulesNamedActionAttrs('toggle-named-font', 'special', sc, { 'font-key': 'fontStyle' })} title="斜体" aria-label="${_rulesAttrValue(sc + ' 斜体')}">I</button>
      <input type="number" class="rules-font-size" value="${fSize}" min="8" max="24" placeholder="${_rulesGetNamedFontPlaceholder('special', sc)}"
        ${_rulesNamedChangeAttrs('named-font-size', 'special', sc)} title="フォントサイズ(px)" aria-label="${_rulesAttrValue(sc + ' フォントサイズ')}">
      <span class="rules-type-label">${esc(sc)}</span>
      ${(bgCol || textCol || style.fontWeight || style.fontStyle || style.fontSize) ? `<button type="button" class="rules-clear" ${_rulesNamedActionAttrs('clear-named-style', 'special', sc)} title="モード既定に戻す" aria-label="${_rulesAttrValue(sc + 'をモード既定に戻す')}">↻</button>` : ''}
      <button type="button" class="rules-remove" ${_rulesNamedActionAttrs('delete-mode-type', 'special', sc)} title="削除" aria-label="${_rulesAttrValue(sc + 'を削除')}">${lucide('x', 12)}</button>
    </div>`;
  });
  html += `<div class="rules-action-row">
    <input id="rules-new-specialchara" class="rules-input rules-input--compact" placeholder="特殊キャラ名..." aria-label="追加する特殊キャラ名">
    <button type="button" class="rules-secondary-btn" ${_rulesNamedActionAttrs('add-custom-type', 'special', 'new')}>追加</button>
  </div>`;
  html += '</div>';

  html += '<div class="rules-section">';
  html += `<div class="rules-section-title">行タイプ設定 ${fieldHelp('柱や区切りなど、シナリオの段落種別候補です。色と書式に加えて接頭辞や区切り線も設定できます。')}</div>`;
  PAGE_SETTINGS.forEach((ps, i) => {
    const style = _rulesEnsureRowTypeStyle(ps);
    const behavior = ensurePageSettingBehavior(ps);
    const bgCol = style.bgColor || '';
    const textCol = style.textColor || '';
    const isBold = style.fontWeight === 'bold';
    const isItalic = style.fontStyle === 'italic';
    const fSize = style.fontSize || '';
    html += `<div class="rules-page-block" draggable="true" data-rules-type-kind="page" data-rules-type-idx="${i}" data-rules-drag-kind="page" data-rules-index="${i}">
      <div class="rules-type-row rules-type-row--wrap">
        <span class="rules-drag-handle">⠿</span>
        <div class="rules-swatch" style="background:${_rulesGetSwatchBackground(bgCol, 'var(--bg3)')};${bgCol === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
          ${_rulesNamedActionAttrs('pick-color', 'rowtype', ps, { 'color-type': 'rowtype-bg' })} role="button" tabindex="0" title="背景色" aria-label="${_rulesAttrValue(ps + ' 背景色')}"></div>
        <div class="rules-swatch rules-swatch-text" style="background:${_rulesGetSwatchBackground(textCol, 'var(--fg2)')};border:1px solid var(--border);${textCol === 'transparent' ? 'background-size:8px 8px;background-position:0 0,4px 4px;' : ''}"
          ${_rulesNamedActionAttrs('pick-color', 'rowtype', ps, { 'color-type': 'rowtype-text' })} role="button" tabindex="0" title="文字色" aria-label="${_rulesAttrValue(ps + ' 文字色')}"></div>
        ${_rulesRenderPreview(ps || '見本', style)}
        <button type="button" class="rules-font-btn rules-font-btn--bold${isBold?' active':''}" ${_rulesNamedActionAttrs('toggle-named-font', 'rowtype', ps, { 'font-key': 'fontWeight' })} title="太字" aria-label="${_rulesAttrValue(ps + ' 太字')}">B</button>
        <button type="button" class="rules-font-btn rules-font-btn--italic${isItalic?' active':''}" ${_rulesNamedActionAttrs('toggle-named-font', 'rowtype', ps, { 'font-key': 'fontStyle' })} title="斜体" aria-label="${_rulesAttrValue(ps + ' 斜体')}">I</button>
        <input type="number" class="rules-font-size" value="${fSize}" min="8" max="24" placeholder="${_rulesGetNamedFontPlaceholder('rowtype', ps)}"
          ${_rulesNamedChangeAttrs('named-font-size', 'rowtype', ps)} title="フォントサイズ(px)" aria-label="${_rulesAttrValue(ps + ' フォントサイズ')}">
        <span class="rules-type-label">${esc(ps)}</span>
        ${(bgCol || textCol || style.fontWeight || style.fontStyle || style.fontSize) ? `<button type="button" class="rules-clear" ${_rulesNamedActionAttrs('clear-named-style', 'rowtype', ps)} title="モード既定に戻す" aria-label="${_rulesAttrValue(ps + 'をモード既定に戻す')}">↻</button>` : ''}
        <button type="button" class="rules-remove" ${_rulesNamedActionAttrs('delete-mode-type', 'page', ps)} title="削除" aria-label="${_rulesAttrValue(ps + 'を削除')}">${lucide('x', 12)}</button>
      </div>
      <div class="rules-type-row rules-type-row--wrap rules-page-options">
        <select class="rules-page-select" ${_rulesNamedChangeAttrs('page-visual-style', 'page', ps)} aria-label="${_rulesAttrValue(ps + ' 表示スタイル')}">
          ${RULE_PAGE_VISUAL_STYLE_OPTIONS.map(opt => `<option value="${opt.value}"${behavior.visualStyle===opt.value?' selected':''}>${opt.label}</option>`).join('')}
        </select>
        <label class="rules-page-label">接頭辞
          <input class="rules-page-input rules-page-input--prefix" value="${esc(behavior.displayPrefix || '')}" ${_rulesNamedChangeAttrs('page-display-prefix', 'page', ps)}>
        </label>
        <label class="rules-page-label">区切り文字
          <input class="rules-page-input rules-page-input--separator" value="${esc(behavior.separatorText || '')}" ${_rulesNamedChangeAttrs('page-separator-text', 'page', ps)}>
        </label>
        <label class="rules-page-label rules-page-label--checkbox"><input type="checkbox" ${behavior.showBoundaryLine?'checked':''} ${_rulesNamedChangeAttrs('page-boundary-line', 'page', ps)}><span>区切り線</span></label>
      </div>
    </div>`;
  });
  html += `<div class="rules-action-row">
    <input id="rules-new-pagetype" class="rules-input rules-input--compact" placeholder="行タイプ名..." aria-label="追加する行タイプ名">
    <button type="button" class="rules-secondary-btn" ${_rulesNamedActionAttrs('add-custom-type', 'page', 'new')}>追加</button>
  </div>`;
  html += '</div>';

  el.innerHTML = html;
  _rulesBindStructuredHandlers(el);
}

;

/* === gb-scriptnote-format.js === */
;
/* gb-scriptnote-format.js: シナリオエディタ専用フォーマット */

const SCRIPTNOTE_FILE_TYPE = 'meldex-scriptnote';
const SCRIPTNOTE_FILE_VERSION = 1;

function isScriptNoteFileDoc(value) {
  return !!(value && typeof value === 'object' && value.fileType === SCRIPTNOTE_FILE_TYPE);
}

function _scriptNoteNormalizeLayout(layout) {
  return ['manga', 'drama', 'afureko', 'stage'].includes(layout) ? layout : 'manga';
}

function convertScenarioDocToScriptNoteDoc(sourceDoc = {}, options = {}) {
  const src = typeof cloneSeData === 'function' ? cloneSeData(sourceDoc) : JSON.parse(JSON.stringify(sourceDoc || {}));
  const settings = typeof ensureScenarioSettings === 'function'
    ? ensureScenarioSettings(src)
    : (src.settings || {});
  const layoutMode = _scriptNoteNormalizeLayout(
    options.layoutMode
      || settings.noteLayoutMode
      || (typeof _guessScenarioNoteLayoutMode === 'function' ? _guessScenarioNoteLayoutMode(settings.modeName || '') : 'manga')
  );
  const rows = Array.isArray(src.rows) ? src.rows.map((row, idx) => ({
    id: row?.id || `sn-row-${idx + 1}`,
    role: typeof getScenarioCharacterDisplayValue === 'function'
      ? getScenarioCharacterDisplayValue(row || {})
      : String(row?.pageSetting || row?.character || ''),
    status: String(row?.status || ''),
    text: String(row?.text || ''),
    columns: row?.columns && typeof row.columns === 'object'
      ? JSON.parse(JSON.stringify(row.columns))
      : {},
  })) : [];
  const converted = {
    fileType: SCRIPTNOTE_FILE_TYPE,
    version: SCRIPTNOTE_FILE_VERSION,
    title: String(src.title || ''),
    layoutMode,
    editor: {
      viewMode: settings.viewMode || 'horizontal',
      wrapMode: settings.wrapMode ?? true,
      textWidth: settings.textWidth ?? 20,
      baseTextLineHeightH: settings.lineHeightH ?? settings.lineHeight ?? 1.5,
      baseTextLineHeightV: settings.lineHeightV ?? settings.lineHeight ?? 1.5,
      baseTextLetterSpacingH: settings.letterSpacingH ?? settings.letterSpacing ?? 0.02,
      baseTextLetterSpacingV: settings.letterSpacingV ?? settings.letterSpacing ?? 0.02,
      fontH: settings.fontH || '',
      fontV: settings.fontV || '',
      colors: settings.colors || null,
    },
    characters: Array.isArray(src.characters) ? src.characters : [],
    characterDb: Array.isArray(src.characterDb) ? src.characterDb : [],
    notes: Array.isArray(src.notes) ? src.notes : [],
    rows,
    source: {
      importedFrom: options.sourcePath || '',
      modeName: settings.modeName || '',
    }
  };
  return globalThis.GBScriptNoteRoleModel?.ensureDocument
    ? globalThis.GBScriptNoteRoleModel.ensureDocument(converted)
    : converted;
}

function convertScriptNoteDocToScenarioDoc(scriptDoc = {}, options = {}) {
  const baseDoc = typeof createEmptyDoc === 'function' ? createEmptyDoc() : { rows: [], notes: [], characters: [], characterDb: [], settings: {} };
  const nextDoc = { ...baseDoc };
  nextDoc.title = String(scriptDoc.title || '');
  nextDoc.rows = [];
  nextDoc.notes = Array.isArray(scriptDoc.notes) ? scriptDoc.notes.map(note => ({ ...note })) : [];
  const roleModel = globalThis.GBScriptNoteRoleModel;
  const legacyTypes = (Array.isArray(scriptDoc.scenarioTypes) ? scriptDoc.scenarioTypes : [])
    .map((type) => JSON.parse(JSON.stringify(type)));
  const legacyCharacters = (Array.isArray(scriptDoc.characters) ? scriptDoc.characters : [])
    .map((character) => ({
      ...(roleModel?.getEffectiveStyle?.(scriptDoc, { kind: 'character', id: character.id }) || {}),
      name: character.name,
    }));
  nextDoc.characters = [...legacyTypes, ...legacyCharacters];
  nextDoc.characterDb = Array.isArray(scriptDoc.characterDb) ? [...scriptDoc.characterDb] : [];
  nextDoc.settings = typeof ensureScenarioSettings === 'function' ? ensureScenarioSettings(nextDoc) : (nextDoc.settings || {});
  const editor = scriptDoc.editor || {};
  nextDoc.settings.viewMode = editor.viewMode || 'horizontal';
  nextDoc.settings.wrapMode = editor.wrapMode ?? true;
  nextDoc.settings.textWidth = editor.textWidth ?? 20;
  nextDoc.settings.plotWidth = nextDoc.settings.textWidth;
  const lineHeightH = editor.baseTextLineHeightH ?? editor.baseTextLineHeight ?? 1.5;
  const lineHeightV = editor.baseTextLineHeightV ?? editor.baseTextLineHeight ?? lineHeightH;
  const letterSpacingH = editor.baseTextLetterSpacingH ?? editor.baseTextLetterSpacing ?? 0.02;
  const letterSpacingV = editor.baseTextLetterSpacingV ?? editor.baseTextLetterSpacing ?? letterSpacingH;
  nextDoc.settings.lineHeightH = lineHeightH;
  nextDoc.settings.lineHeightV = lineHeightV;
  nextDoc.settings.letterSpacingH = letterSpacingH;
  nextDoc.settings.letterSpacingV = letterSpacingV;
  nextDoc.settings.lineHeight = nextDoc.settings.viewMode === 'vertical' ? lineHeightV : lineHeightH;
  nextDoc.settings.letterSpacing = nextDoc.settings.viewMode === 'vertical' ? letterSpacingV : letterSpacingH;
  nextDoc.settings.fontH = editor.fontH || '';
  nextDoc.settings.fontV = editor.fontV || '';
  nextDoc.settings.colors = editor.colors || null;
  nextDoc.settings.noteLayoutMode = _scriptNoteNormalizeLayout(scriptDoc.layoutMode);
  nextDoc.settings.editorSurface = 'note';
  if (scriptDoc?.source?.modeName) nextDoc.settings.modeName = scriptDoc.source.modeName;

  (Array.isArray(scriptDoc.rows) ? scriptDoc.rows : []).forEach((item, idx) => {
    const role = String(item?.role || '').trim();
    const row = typeof createRow === 'function' ? createRow('', '', String(item?.text || '')) : {
      id: item?.id || `row-${idx + 1}`,
      pageSetting: '',
      character: '',
      text: String(item?.text || '')
    };
    row.id = item?.id || row.id;
    if (item?.status) row.status = String(item.status);
    if (item?.columns && typeof item.columns === 'object') {
      row.columns = JSON.parse(JSON.stringify(item.columns));
    }
    if (typeof syncScenarioRowPageSettingFromCharacter === 'function') syncScenarioRowPageSettingFromCharacter(row, role);
    else if (row) row.character = role;
    nextDoc.rows.push(row);
  });

  return nextDoc;
}

function suggestScriptNotePath(path = '', title = '') {
  const base = String(path || '').trim();
  if (base) return base.replace(/\.(json|csv|xlsx|xls)$/i, '') + '.scriptnote.json';
  const safeTitle = String(title || '無題シナリオ').trim() || '無題シナリオ';
  return safeTitle + '.scriptnote.json';
}

function _sn2GetActiveSaveContext() {
  const comp = typeof getActiveScriptNoteComponent === 'function' ? getActiveScriptNoteComponent() : null;
  const editor = comp?._editor?.doc
    ? comp._editor
    : (typeof _sn2GetActiveEditor === 'function' ? _sn2GetActiveEditor() : null);
  if (!editor?.doc) return null;
  return { comp, editor };
}

function _sn2NormalizeScriptNoteFileName(name = '') {
  const raw = String(name || '').trim();
  const base = raw || '無題シナリオ';
  if (/\.scriptnote\.json$/i.test(base)) return base;
  if (/\.json$/i.test(base)) return base.replace(/\.json$/i, '.scriptnote.json');
  return base.replace(/\.[^./\\]+$/i, '') + '.scriptnote.json';
}

function _sn2JoinPath(folder = '', fileName = '') {
  const f = String(folder || '').replace(/[\\/]+$/g, '');
  const n = String(fileName || '').replace(/^[\\/]+/g, '');
  return f ? f + '/' + n : n;
}

function _sn2SetActiveScriptNotePath(ctx, targetPath) {
  const { comp, editor } = ctx || {};
  if (!editor || !targetPath) return;
  const oldPath = editor._path || '';
  if (editor._saveTimer) {
    clearTimeout(editor._saveTimer);
    editor._saveTimer = null;
  }
  if (oldPath && oldPath !== targetPath && typeof _sn2Editors !== 'undefined') delete _sn2Editors[oldPath];
  editor._path = targetPath;
  editor._dirty = false;
  if (typeof createScriptNoteRowIdSet === 'function') editor._lastSavedRowIds = createScriptNoteRowIdSet(editor.doc);
  if (typeof _sn2Editors !== 'undefined') {
    _sn2Editors[targetPath] = editor;
    if (editor._historyScopeId) _sn2Editors[editor._historyScopeId] = editor;
    editor._sn2RegisteredPath = targetPath;
    editor._sn2RegisteredScopeId = editor._historyScopeId || '';
  }
  const label = typeof getScriptNoteLabelFromPath === 'function'
    ? getScriptNoteLabelFromPath(targetPath, editor.doc?.title || '')
    : (targetPath.split('/').pop() || targetPath).replace(/\.scriptnote\.json$/i, '');
  if (comp?.state) {
    comp.state.scenarioPath = targetPath;
    comp.state.label = label;
  }
  if (typeof GBTabs !== 'undefined' && comp?.tabId) GBTabs.setTabLabel?.(comp.tabId, label);
  if (typeof historySetScope === 'function' && typeof editor._historyScope === 'function') historySetScope(editor._historyScope());
  if (typeof startAutoVersion === 'function') startAutoVersion(targetPath, 'file');
}

async function _sn2ScriptNoteFileExists(path) {
  if (!path || typeof apiFetch !== 'function') return false;
  try {
    await apiFetch('/file?path=' + encodeURIComponent(path), { silentError: true });
    return true;
  } catch (err) {
    if (err?.status === 404) return false;
    return true;
  }
}

async function _sn2ConfirmScriptNoteOverwrite(targetPath, sourcePath = '', options = {}) {
  const normalizePath = (value) => String(value || '').replace(/\\/g, '/');
  if (normalizePath(targetPath) === normalizePath(sourcePath)) return true;
  const exists = await _sn2ScriptNoteFileExists(targetPath);
  if (!exists) return true;
  if (options.forceOverwrite) return true;
  if (typeof cfConfirm !== 'function') {
    if (typeof showStatus === 'function') showStatus('同名のシナリオファイルが既にあります', true);
    return false;
  }
  return await cfConfirm('同名のシナリオファイルが既にあります。上書きしますか？', {
    danger: true,
    okLabel: '上書き',
    cancelLabel: 'キャンセル',
  });
}

async function _sn2FetchCssWithImports(url, seen = new Set()) {
  const resolved = new URL(url, window.location.href);
  const seenKey = resolved.href.replace(/[?#].*$/, '');
  if (seen.has(seenKey)) return '';
  seen.add(seenKey);
  const fetchUrl = new URL(resolved.href);
  fetchUrl.searchParams.set('_', String(Date.now()));
  const res = await fetch(fetchUrl.href, { cache: 'no-store' });
  if (!res.ok) return '';
  const css = await res.text();
  const importRe = /@import\s+(?:url\(\s*)?["']?([^"')\s;]+)["']?\s*\)?\s*;/g;
  let out = '';
  let last = 0;
  let match;
  while ((match = importRe.exec(css)) !== null) {
    out += css.slice(last, match.index);
    const importUrl = match[1] || '';
    if (/^(https?:|data:)/i.test(importUrl)) out += match[0];
    else out += await _sn2FetchCssWithImports(new URL(importUrl, resolved).href, seen);
    last = importRe.lastIndex;
  }
  out += css.slice(last);
  return out;
}

async function saveCurrentScriptNoteAs(path, options = {}) {
  const targetPath = String(path || '').trim();
  if (!targetPath) return false;
  const ctx = _sn2GetActiveSaveContext();
  if (!ctx) {
    if (typeof showStatus === 'function') showStatus('シナリオファイルが開かれていません', true);
    return false;
  }
  const { editor } = ctx;
  const sourcePath = editor._path || ctx.comp?.state?.scenarioPath || '';
  const clearPendingSave = () => {
    if (editor._saveTimer) {
      clearTimeout(editor._saveTimer);
      editor._saveTimer = null;
    }
  };
  clearPendingSave();
  if (typeof editor._syncAllFromDom === 'function') editor._syncAllFromDom();
  const exportDoc = typeof editor.collectDoc === 'function'
    ? editor.collectDoc()
    : (typeof serializeScriptNoteDoc === 'function' ? serializeScriptNoteDoc(editor.doc) : editor.doc);
  clearPendingSave();
  if (!(await _sn2ConfirmScriptNoteOverwrite(targetPath, sourcePath, options))) return false;
  const targetExists = await _sn2ScriptNoteFileExists(targetPath);
  await apiPut('/file?path=' + encodeURIComponent(targetPath), {
    content: JSON.stringify(exportDoc, null, 2),
    ...(targetExists ? { force_overwrite: true } : { create_only: true }),
  });
  _sn2SetActiveScriptNotePath(ctx, targetPath);
  return true;
}

function _sn2FormatIcon(name, size = 14) {
  return typeof lucide === 'function' ? lucide(name, size) : '';
}

function _sn2IsRenderedFocusTarget(el) {
  if (!el || !el.isConnected || typeof el.focus !== 'function') return false;
  const style = window.getComputedStyle ? window.getComputedStyle(el) : null;
  if (style && (style.display === 'none' || style.visibility === 'hidden')) return false;
  const rect = typeof el.getBoundingClientRect === 'function' ? el.getBoundingClientRect() : null;
  return !rect || (rect.width > 0 && rect.height > 0);
}

function _sn2RestoreFocus(el) {
  if (!_sn2IsRenderedFocusTarget(el)) return;
  try { el.focus({ preventScroll: true }); } catch { try { el.focus(); } catch {} }
}

async function promptSaveCurrentScriptNoteAs() {
  const ctx = _sn2GetActiveSaveContext();
  if (!ctx) {
    if (typeof showStatus === 'function') showStatus('シナリオファイルが開かれていません', true);
    return false;
  }
  const srcPath = ctx.editor._path || ctx.comp?.state?.scenarioPath || '';
  const defaultName = _sn2NormalizeScriptNoteFileName(srcPath ? srcPath.split('/').pop() : (ctx.editor.doc?.title || ''));
  const srcFolder = srcPath.includes('/') ? srcPath.substring(0, srcPath.lastIndexOf('/')) : '';
  const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  return new Promise(resolve => {
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.dataset.e2eId = 'save-scenario-format-modal-overlay';

    const dialog = document.createElement('div');
    dialog.className = 'modal sn2-save-as-modal';
    dialog.dataset.e2eId = 'save-scenario-format-modal';
    dialog.setAttribute('role', 'dialog');
    dialog.setAttribute('aria-modal', 'true');
    dialog.setAttribute('aria-labelledby', 'sn-save-title');

    const header = document.createElement('div');
    header.className = 'gb-modal-header';
    const title = document.createElement('h3');
    title.id = 'sn-save-title';
    title.className = 'gb-modal-title';
    title.textContent = 'シナリオ形式として保存';
    const closeButton = document.createElement('button');
    closeButton.type = 'button';
    closeButton.className = 'gb-modal-close gb-btn gb-btn-sm gb-btn-icon gb-btn-ghost';
    closeButton.setAttribute('aria-label', '閉じる');
    closeButton.innerHTML = _sn2FormatIcon('x', 14);
    header.append(title, closeButton);

    const body = document.createElement('div');
    body.className = 'gb-modal-body sn2-save-as-body';

    const nameField = document.createElement('div');
    nameField.className = 'field gb-field sn2-save-field';
    const nameLabel = document.createElement('label');
    nameLabel.className = 'gb-label';
    nameLabel.htmlFor = 'sn-save-name';
    nameLabel.textContent = 'ファイル名';
    const nameInput = document.createElement('input');
    nameInput.id = 'sn-save-name';
    nameInput.className = 'gb-input sn2-save-name-input';
    nameInput.type = 'text';
    nameInput.value = defaultName;
    nameInput.autocomplete = 'off';
    nameInput.setAttribute('aria-label', 'ファイル名');
    nameField.append(nameLabel, nameInput);

    const folderField = document.createElement('div');
    folderField.className = 'field gb-field sn2-save-field';
    const folderFieldLabel = document.createElement('label');
    folderFieldLabel.className = 'gb-label';
    folderFieldLabel.id = 'sn-save-folder-field-label';
    folderFieldLabel.textContent = '保存先フォルダ';
    const folderDisplay = document.createElement('button');
    folderDisplay.id = 'sn-save-folder-display';
    folderDisplay.type = 'button';
    folderDisplay.className = 'gb-btn gb-btn-sm gb-btn-quiet sn2-save-folder-display';
    folderDisplay.setAttribute('role', 'button');
    folderDisplay.setAttribute('tabindex', '0');
    folderDisplay.setAttribute('aria-haspopup', 'dialog');
    folderDisplay.setAttribute('aria-expanded', 'false');
    folderDisplay.setAttribute('aria-labelledby', 'sn-save-folder-field-label sn-save-folder-label');
    folderDisplay.setAttribute('aria-label', '保存先フォルダを選択');
    const folderLabel = document.createElement('span');
    folderLabel.id = 'sn-save-folder-label';
    folderLabel.className = 'sn2-save-folder-label';
    folderLabel.textContent = srcFolder || '(ルート)';
    const folderChevron = document.createElement('span');
    folderChevron.className = 'sn2-save-folder-chevron';
    folderChevron.setAttribute('aria-hidden', 'true');
    folderChevron.innerHTML = _sn2FormatIcon('chevronDown', 14);
    folderDisplay.append(folderLabel, folderChevron);
    const folderTree = document.createElement('div');
    folderTree.id = 'sn-save-folder-tree';
    folderTree.className = 'sn2-save-folder-tree';
    folderTree.setAttribute('role', 'tree');
    folderTree.hidden = true;
    folderField.append(folderFieldLabel, folderDisplay, folderTree);
    body.append(nameField, folderField);

    const footer = document.createElement('div');
    footer.className = 'gb-modal-footer sn2-save-as-actions';
    const cancelButton = document.createElement('button');
    cancelButton.type = 'button';
    cancelButton.id = 'sn-save-cancel';
    cancelButton.className = 'gb-btn gb-btn-sm gb-btn-quiet';
    cancelButton.textContent = 'キャンセル';
    const saveButton = document.createElement('button');
    saveButton.type = 'button';
    saveButton.id = 'sn-save-ok';
    saveButton.className = 'gb-btn gb-btn-sm gb-btn-primary';
    saveButton.textContent = '保存';
    footer.append(cancelButton, saveButton);
    dialog.append(header, body, footer);
    overlay.appendChild(dialog);
    document.body.appendChild(overlay);
    if (window.GBModalShell?.enhanceOverlay) window.GBModalShell.enhanceOverlay(overlay);
    let selectedFolder = srcFolder;
    let finished = false;
    let saving = false;
    const escCss = (value) => (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') ? CSS.escape(value) : String(value).replace(/"/g, '\\"');
    const setTreeOpen = (open) => {
      folderTree.hidden = !open;
      folderTree.classList.toggle('is-open', !!open);
      folderDisplay.setAttribute('aria-expanded', open ? 'true' : 'false');
    };
    const close = (result) => {
      if (finished) return;
      finished = true;
      overlay.remove();
      _sn2RestoreFocus(opener);
      resolve(result);
    };
    const selectFolder = (path, label) => {
      selectedFolder = path;
      folderLabel.textContent = label || path || '(ルート)';
      setTreeOpen(false);
    };
    const createRow = (name, path, depth, icon = 'folder', options = {}) => {
      const row = document.createElement('div');
      row.className = 'sn2-save-folder-row';
      row.dataset.snFolderPath = path;
      row.dataset.depth = String(depth);
      row.style.setProperty('--sn2-save-folder-depth', String(depth));
      row.setAttribute('role', 'treeitem');
      row.setAttribute('aria-level', String(depth + 1));
      row.setAttribute('aria-selected', path === selectedFolder ? 'true' : 'false');
      if (path === selectedFolder) {
        row.dataset.selected = '1';
        row.classList.add('is-selected');
      }
      if (options.onToggle) {
        const toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'gb-btn gb-btn-xs gb-btn-icon gb-btn-ghost sn2-save-folder-toggle';
        toggle.setAttribute('aria-label', `${name || '(ルート)'}を展開`);
        toggle.setAttribute('aria-expanded', 'false');
        toggle.innerHTML = _sn2FormatIcon('chevronRight', 14);
        toggle.addEventListener('click', async (event) => {
          event.stopPropagation();
          await options.onToggle(toggle, row);
        });
        row.appendChild(toggle);
      } else {
        const spacer = document.createElement('span');
        spacer.className = 'sn2-save-folder-toggle-spacer';
        spacer.setAttribute('aria-hidden', 'true');
        row.appendChild(spacer);
      }
      const selectButton = document.createElement('button');
      selectButton.type = 'button';
      selectButton.className = 'gb-btn gb-btn-sm gb-btn-ghost sn2-save-folder-select';
      selectButton.setAttribute('aria-label', `${name || '(ルート)'}を保存先にする`);
      const iconWrap = document.createElement('span');
      iconWrap.className = 'sn2-save-folder-icon';
      iconWrap.setAttribute('aria-hidden', 'true');
      iconWrap.innerHTML = typeof lucide === 'function' ? lucide(icon, 12) : '';
      const label = document.createElement('span');
      label.className = 'sn2-save-folder-name';
      label.textContent = name || '(ルート)';
      selectButton.append(iconWrap, label);
      row.appendChild(selectButton);
      selectButton.addEventListener('click', () => {
        folderTree.querySelectorAll('[data-sn-folder-path]').forEach(el => {
          delete el.dataset.selected;
          el.classList.remove('is-selected');
          el.setAttribute('aria-selected', 'false');
        });
        row.dataset.selected = '1';
        row.classList.add('is-selected');
        row.setAttribute('aria-selected', 'true');
        selectFolder(path, name || '(ルート)');
      });
      return row;
    };
    const expandFolder = async (parentPath, depth) => {
      const parentRow = folderTree.querySelector(`[data-sn-folder-path="${escCss(parentPath)}"]`);
      let insertAfter = parentRow || null;
      try {
        const data = await apiFetch('/browse?path=' + encodeURIComponent(parentPath) + '&folders_only=1&sort=name&order=asc');
        const folders = (Array.isArray(data) ? data : (data.items || [])).filter(i => i.type === 'folder');
        for (const f of folders) {
          if (folderTree.querySelector(`[data-sn-folder-path="${escCss(f.path)}"]`)) continue;
          const row = createRow(f.name, f.path, depth + 1, 'folder', {
            onToggle: async (toggle, rowEl) => {
              const expanded = toggle.dataset.expanded === '1';
              if (expanded) {
                const d = Number(rowEl.dataset.depth || 0);
                let next = rowEl.nextElementSibling;
                while (next && Number(next.dataset.depth || 0) > d) {
                  const rm = next;
                  next = next.nextElementSibling;
                  rm.remove();
                }
                toggle.dataset.expanded = '0';
                toggle.setAttribute('aria-expanded', 'false');
                toggle.innerHTML = _sn2FormatIcon('chevronRight', 14);
                return;
              }
              await expandFolder(f.path, depth + 1);
              toggle.dataset.expanded = '1';
              toggle.setAttribute('aria-expanded', 'true');
              toggle.innerHTML = _sn2FormatIcon('chevronDown', 14);
            },
          });
          if (insertAfter?.nextSibling) folderTree.insertBefore(row, insertAfter.nextSibling);
          else folderTree.appendChild(row);
          insertAfter = row;
        }
      } catch {
        if (!folderTree.children.length) {
          const error = document.createElement('div');
          error.className = 'sn2-save-folder-status is-error';
          error.setAttribute('role', 'status');
          error.textContent = 'フォルダ一覧の取得に失敗';
          folderTree.replaceChildren(error);
        }
      }
    };
    // フォルダツリー展開
    folderDisplay.addEventListener('click', async () => {
      if (window.GBFolderPicker?.pickFolder) {
        const selected = await window.GBFolderPicker.pickFolder({
          title: '保存先フォルダを選択',
          initialPath: selectedFolder,
        });
        if (selected?.path !== undefined) {
          selectFolder(selected.path, selected.label || selected.name || selected.path || '(ルート)');
        }
        return;
      }
      if (!folderTree.hidden) { setTreeOpen(false); return; }
      setTreeOpen(true);
      const loading = document.createElement('div');
      loading.className = 'sn2-save-folder-status';
      loading.setAttribute('role', 'status');
      loading.textContent = '読み込み中...';
      folderTree.replaceChildren(loading);
      folderTree.replaceChildren();
      folderTree.appendChild(createRow('(ルート)', '', 0, 'home'));
      await expandFolder('', 0);
    });
    folderDisplay.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      folderDisplay.click();
    });
    const doSave = async () => {
      if (saving) return;
      const name = _sn2NormalizeScriptNoteFileName(nameInput.value);
      if (!name) return;
      nameInput.value = name;
      const targetPath = _sn2JoinPath(selectedFolder, name);
      saving = true;
      saveButton.disabled = true;
      try {
        const saved = await saveCurrentScriptNoteAs(targetPath);
        if (!saved) return;
        if (typeof saveLastView === 'function') {
          const label = typeof getScriptNoteLabelFromPath === 'function'
            ? getScriptNoteLabelFromPath(targetPath)
            : targetPath.split('/').pop().replace(/\.scriptnote\.json$/i, '').replace(/\.\w+$/, '');
          saveLastView({ type: 'scriptnote', label, path: targetPath });
        }
        close(true);
        if (typeof showStatus === 'function') showStatus('シナリオ形式で保存しました', false, { showSaveDialog: true });
      } catch (err) {
        if (typeof showStatus === 'function') showStatus('保存に失敗: ' + (err?.message || err), true);
      } finally {
        saving = false;
        if (overlay.isConnected) saveButton.disabled = false;
      }
    };
    overlay.addEventListener('pointerdown', event => {
      if (event.target !== overlay) return;
      event.preventDefault();
      close(false);
    });
    overlay.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        event.preventDefault();
        close(false);
      }
    });
    saveButton.addEventListener('click', doSave);
    cancelButton.addEventListener('click', () => close(false));
    closeButton.addEventListener('click', () => close(false));
    nameInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doSave(); } });
    nameInput.focus(); nameInput.select();
  });
}

// シナリオエディタの現在ビュー（フィルタ・テーマ・縦/横/折返し設定すべて反映済み）を
// 操作不可の静的 HTML として保存する。embed-font: Regular の woff2 を data URI で
// 埋め込んで自己完結させる。
async function exportCurrentScriptNoteAsHtml() {
  if (typeof _sn2GetActiveEditor !== 'function') {
    if (typeof showStatus === 'function') showStatus('シナリオエディタが利用できません', true);
    return;
  }
  const editor = _sn2GetActiveEditor();
  if (!editor?.doc) {
    if (typeof showStatus === 'function') showStatus('シナリオファイルが開かれていません', true);
    return;
  }
  // 最新状態でレンダリング
  try { editor._syncAllFromDom?.(); } catch {}
  try { editor._render(); } catch {}
  // _render() は縦書きモードで requestAnimationFrame 内で行の style.height と
  // style.minWidth を設定する。クローン前に rAF を 2 回待ってこれらの JS 同期
  // 処理が完了してから DOM スナップショットを取る (これを待たないと行高さが
  // 未設定のままクローンされ、エクスポート HTML でテキストが潰れる)。
  await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  const scroll = editor.host?.querySelector('.sn2-scroll');
  if (!scroll) {
    if (typeof showStatus === 'function') showStatus('レンダリング結果が見つかりません', true);
    return;
  }

  // ステータス表示
  if (typeof showStatus === 'function') showStatus('HTML を生成中...');

  // クローンしてインタラクティブな属性を除去
  const clone = scroll.cloneNode(true);
  // フローティング UI / ドラッグハンドル系を除去
  clone.querySelectorAll('.sn2-row-bulk-bar, .sn2-handle-zone, .sn2-handle, .sn2-add-row, .sn2-add-col-btn').forEach(el => el.remove());
  // contenteditable / inputs / data-action を完全除去
  clone.querySelectorAll('[contenteditable]').forEach(el => {
    el.removeAttribute('contenteditable');
    el.setAttribute('data-readonly', '1');
  });
  clone.querySelectorAll('[data-action], [data-sn-action]').forEach(el => {
    el.removeAttribute('data-action');
    el.removeAttribute('data-sn-action');
  });
  clone.querySelectorAll('input, textarea, select, button').forEach(el => {
    if (el.tagName === 'BUTTON') {
      // タイプボタンは見た目だけ残してクリック不可に
      el.setAttribute('disabled', 'disabled');
      el.style.pointerEvents = 'none';
    } else {
      const span = document.createElement('span');
      span.className = el.className;
      span.textContent = el.value || el.textContent || '';
      el.replaceWith(span);
    }
  });
  clone.querySelectorAll('[tabindex]').forEach(el => el.removeAttribute('tabindex'));
  clone.querySelectorAll('[draggable]').forEach(el => el.removeAttribute('draggable'));

  // span[data-ruby] / .auto-link[data-ruby] を HTML 標準の <ruby><rt> に置換する。
  // 元の実装は ::after 擬似要素で描画していたが、iOS Safari や Gmail/Dropbox の
  // 内蔵ブラウザでは ::after ルビの位置計算が壊れて二重描画になるケースがあった。
  // ネイティブ ruby は全ブラウザで安定して縦書きルビが描画される。
  clone.querySelectorAll('[data-ruby]').forEach(el => {
    const rubyText = el.getAttribute('data-ruby');
    if (!rubyText) return;
    const baseText = el.textContent || '';
    const ruby = document.createElement('ruby');
    ruby.appendChild(document.createTextNode(baseText));
    const rt = document.createElement('rt');
    rt.textContent = rubyText;
    ruby.appendChild(rt);
    // auto-link も含め、クラス名は保持しない (ネイティブ ruby に任せる)
    el.replaceWith(ruby);
  });

  // CSS を取得（gb-fonts.css は woff2 埋め込みに置き換えるので除外）
  // cache-buster + no-store でブラウザ・中間キャッシュを完全回避する
  let editorCss = '';
  try {
    editorCss = await _sn2FetchCssWithImports('gb-scriptnote-editor.css');
  } catch {}

  // CSS 変数を :root から収集
  const rootStyle = getComputedStyle(document.documentElement);
  const varNames = [
    '--bg', '--bg2', '--bg3', '--bg4',
    '--fg', '--fg2', '--accent', '--accent2',
    '--border', '--selection',
    '--ui-header-fg', '--ui-header-bg',
    '--ui-header-font',
    '--ui-toolbar-fg', '--ui-toolbar-bg',
    '--ui-toolbar-font', '--ui-muted-font',
    '--ui-hover-fg', '--ui-hover-bg',
    '--ui-fg-strong',
    '--ui-selection-fg', '--ui-selection-bg',
    '--ui-range-fill-bg', '--ui-range-track-bg',
    '--ui-scrollbar-track-bg', '--ui-scrollbar-thumb-bg', '--ui-scrollbar-thumb-hover-bg',
    '--ui-font', '--ui-font-size',
  ];
  const varDecls = varNames
    .map(v => {
      const val = rootStyle.getPropertyValue(v).trim();
      return val ? `${v}: ${val};` : '';
    })
    .filter(Boolean)
    .join(' ');

  // Noto Sans JP Regular を data URI で埋め込み（自己完結 HTML 化）
  let fontFaceCss = '';
  try {
    const r = await fetch('fonts/NotoSansJP-Regular.woff2');
    if (r.ok) {
      const buf = await r.arrayBuffer();
      const bin = new Uint8Array(buf);
      let s = '';
      for (let i = 0; i < bin.length; i++) s += String.fromCharCode(bin[i]);
      const b64 = btoa(s);
      fontFaceCss = `@font-face { font-family: 'Noto Sans JP'; font-style: normal; font-weight: 400; src: url('data:font/woff2;base64,${b64}') format('woff2'); }`;
    }
  } catch {}

  const title = (editor.doc.title || 'シナリオ').toString();
  const safeTitle = title.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').slice(0, 80) || '無題';
  const escHtml = (s) => String(s).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

  const html = `<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="color-scheme" content="dark light">
<title>${escHtml(title)}</title>
<style>
${fontFaceCss}
:root { ${varDecls} }
html, body {
  margin: 0; padding: 0;
  background: var(--bg, #1e1e1e);
  color: var(--fg, #d4d4d4);
  font-family: var(--ui-font, 'Noto Sans JP', 'Hiragino Sans', 'Yu Gothic UI', 'Meiryo', sans-serif);
  font-size: var(--ui-font-size, 15px);
}
${editorCss}
/* 静的エクスポート用の上書き: 操作 UI を完全に隠す */
/* .sn2-scroll は通常 flex:1 で親に張り付くが、エクスポートではコンテンツに
   ぴったり合わせて body 直下に並べる。縦書き row-reverse でもはみ出さない
   よう幅を fit-content にしてブラウザのスクロールに任せる */
.sn2-scroll {
  flex: none !important;
  overflow: visible !important;
  height: auto !important;
  max-height: none !important;
  width: fit-content !important;
  max-width: none !important;
}
.sn2-row-bulk-bar, .sn2-handle, .sn2-handle-zone, .sn2-add-row, .sn2-add-col-btn,
.sn2-resizer, .sn2-col-resizer, .sn2-row-resizer { display: none !important; }
.sn2-row { cursor: default !important; }
*, *::before, *::after { user-select: text !important; -webkit-user-select: text !important; }
[disabled] { cursor: default !important; opacity: 1 !important; }

/* iOS Safari / Gmail/Dropbox 内蔵ブラウザ向けの互換 CSS */
/* ネイティブ ruby を iOS でも正しく縦書きにレンダリングさせる */
ruby {
  ruby-position: over;
}
.sn2-scroll.sn2-vertical ruby {
  ruby-position: inter-character;
}
rt {
  font-size: 0.55em;
  line-height: 1;
  color: inherit;
  opacity: 0.75;
}
/* iOS で縦書きのグリフが一部横になる対策。writing-mode を -webkit- プレフィックス
   でも指定し、text-combine-upright で数字・記号を縦中横にする */
.sn2-scroll.sn2-vertical .sn2-text,
.sn2-scroll.sn2-vertical .sn2-gutter,
.sn2-scroll.sn2-vertical .sn2-custom-text {
  -webkit-writing-mode: vertical-rl;
  -webkit-text-orientation: upright;
}
.sn2-scroll.sn2-vertical .sn2-role-btn {
  -webkit-writing-mode: vertical-rl;
  -webkit-text-orientation: mixed;
}
.sn2-tcy,
.sn2-tcy-wide {
  -webkit-text-combine: horizontal;
}
</style>
</head>
<body>
${clone.outerHTML}
</body>
</html>`;

  // OS ネイティブの「名前を付けて保存」ダイアログをサーバー側 (Meldex.py)
  // で開き、選択されたパスに直接書き込む。
  if (typeof MeldexExportSave !== 'undefined' && typeof MeldexExportSave.saveText === 'function') {
    await MeldexExportSave.saveText(html, {
      title: safeTitle,
      extension: '.html',
      dialogTitle: 'HTMLとして保存',
      filetypes: [['HTMLファイル', '*.html'], ['すべてのファイル', '*.*']],
      bom: true,
      okMessage: 'HTML として保存しました',
      errorMessage: 'HTML の保存に失敗しました',
    });
  }
}

// 行本文 (row.text) を Markdown 出力用のプレーンテキストへ変換する。
// row.text の内部表現はエスケープ付きプレーンテキストで、ルビは {ベース|ルビ}、
// 手動リンクは [ラベル](ml:target)、改行は \n で保持されている (HTML の <br> ではない)。
// ここではルビ記法 {ベース|ルビ} をそのまま出力し、手動リンクはラベルのみに落とし、
// エスケープ済みの生文字 (\{ \| \} \\ \[ \]) は素の文字へ戻す。
function _sn2ScriptNoteRowTextForMarkdown(rawText) {
  const raw = String(rawText || '');
  if (typeof _sn2CollectVisibleSegments !== 'function') {
    return typeof _sn2UnescapeScriptNotePlainText === 'function' ? _sn2UnescapeScriptNotePlainText(raw) : raw;
  }
  return _sn2CollectVisibleSegments(raw).map(segment => {
    if (segment.type === 'ruby') return `{${segment.plain}|${segment.ruby}}`;
    if (segment.type === 'manual-link') return segment.plain;
    return typeof _sn2UnescapeScriptNotePlainText === 'function' ? _sn2UnescapeScriptNotePlainText(segment.raw) : segment.raw;
  }).join('');
}

// シナリオの現在ビューを Markdown 形式のプレーンテキストとして保存する。
// 役名 (タイプ) を持つ行は `**[役名]** 本文` の形式にし、区切り (ページ送り) 行は
// セクション区切りの水平線 "---" に変換する。行内改行は Markdown のハードブレーク
// (行末2スペース+改行) にして、素の Markdown ビューアでも改行が保たれるようにする。
async function exportCurrentScriptNoteAsMarkdown() {
  if (typeof _sn2GetActiveEditor !== 'function') {
    if (typeof showStatus === 'function') showStatus('シナリオエディタが利用できません', true);
    return;
  }
  const editor = _sn2GetActiveEditor();
  if (!editor?.doc) {
    if (typeof showStatus === 'function') showStatus('シナリオファイルが開かれていません', true);
    return;
  }
  try { editor._syncAllFromDom?.(); } catch {}

  const doc = editor.doc;
  const { breakNames } = typeof editor._getRoleFlagSets === 'function'
    ? editor._getRoleFlagSets()
    : { breakNames: new Set() };

  const title = String(doc.title || '無題シナリオ').trim() || '無題シナリオ';
  const rows = Array.isArray(doc.rows) ? doc.rows : [];
  const blocks = [`# ${title}`];

  rows.forEach((row, idx) => {
    const role = String(row?.role || '').trim();
    const rawBody = _sn2ScriptNoteRowTextForMarkdown(row?.text || '');
    if (role && breakNames.has(role)) {
      // 区切り（ページ送り）行はセクション区切りの水平線に変換する
      if (idx > 0) blocks.push('---');
      const trimmed = rawBody.trim();
      if (trimmed) blocks.push(trimmed.split('\n').join('  \n'));
      return;
    }
    const lines = rawBody.split('\n');
    if (role) lines[0] = lines[0] ? `**[${role}]** ${lines[0]}` : `**[${role}]**`;
    blocks.push(lines.join('  \n'));
  });

  const markdown = blocks.join('\n\n') + '\n';
  const safeTitle = title.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').slice(0, 80) || '無題';

  if (typeof MeldexExportSave !== 'undefined' && typeof MeldexExportSave.saveText === 'function') {
    await MeldexExportSave.saveText(markdown, {
      title: safeTitle,
      extension: '.md',
      dialogTitle: 'Markdownとして保存',
      filetypes: [['Markdownファイル', '*.md'], ['すべてのファイル', '*.*']],
      bom: true,
      okMessage: 'Markdown として保存しました',
      errorMessage: 'Markdown の保存に失敗しました',
    });
  }
}

;

/* === gb-scriptnote-document.js === */
;
/* gb-scriptnote-document.js: シナリオ文書の正規化・旧データ移行・直列化 */

const SCRIPTNOTE_DEFAULT_LAYOUT_MODE = 'manga';
const SCRIPTNOTE_SCHEMA_VERSION = 3;
const SCRIPTNOTE_LEGACY_PAGE_BREAK_BY_MODE = {
  manga: ['めくり', '改ページ', '柱'],
  drama: ['シーン見出し', '場面転換', '柱'],
  afureko: ['シーン見出し', '場面転換', 'Aパート', 'Bパート', 'Cパート', '柱'],
  stage: ['第一幕', '第二幕', '第三幕', '場', '柱'],
};
const SCRIPTNOTE_LEGACY_SUMMARY_NAMES = ['プロット'];
const SCRIPTNOTE_DEFAULT_TYPE_BG = '#333333';

function _scriptNotePlainObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function _scriptNoteRoleModel() {
  return typeof globalThis !== 'undefined' ? globalThis.GBScriptNoteRoleModel : null;
}

function _scriptNoteLayoutOrDefault(layout) {
  if (typeof _scriptNoteNormalizeLayout === 'function') return _scriptNoteNormalizeLayout(layout);
  return ['manga', 'drama', 'afureko', 'stage'].includes(layout) ? layout : SCRIPTNOTE_DEFAULT_LAYOUT_MODE;
}

function _scriptNoteNormalizeRows(rows, now) {
  const normalized = Array.isArray(rows) ? rows.map((row, index) => {
    const item = _scriptNotePlainObject(row);
    return {
      ...item,
      id: item.id || `sn-${now}-${index}`,
      role: String(item.role || ''),
      ...(item.roleRef && typeof item.roleRef === 'object'
        ? { roleRef: { ...item.roleRef } }
        : (!item.role ? { roleRef: { kind: 'none', id: 'none' } } : {})),
      status: String(item.status || ''),
      text: String(item.text || ''),
      columns: _scriptNotePlainObject(item.columns),
    };
  }) : [];
  if (normalized.length) return normalized;
  return [{
    id: `sn-${now}-0`,
    role: '',
    roleRef: { kind: 'none', id: 'none' },
    status: '',
    text: '',
    columns: {},
  }];
}

function createScriptNoteDefaultType() {
  return {
    isTypeDefault: true,
    name: '',
    gutter2Style: { bgColor: SCRIPTNOTE_DEFAULT_TYPE_BG },
    roleStyle: { bgColor: SCRIPTNOTE_DEFAULT_TYPE_BG },
    textStyle: { bgColor: SCRIPTNOTE_DEFAULT_TYPE_BG },
  };
}

function createScriptNoteNoneType() {
  return {
    isRoleNone: true,
    name: '',
    gutterStyle: { bgColor: 'transparent' },
    gutter2Style: { bgColor: 'transparent' },
  };
}

function ensureScriptNoteNoneType(editor) {
  const target = _scriptNotePlainObject(editor);
  let current = _scriptNotePlainObject(target.noneType);
  if (current !== target.noneType) {
    current = createScriptNoteNoneType();
    target.noneType = current;
  }
  current.isRoleNone = true;
  current.name = '';
  ['gutterStyle', 'gutter2Style'].forEach((key) => {
    let style = _scriptNotePlainObject(current[key]);
    if (style !== current[key]) {
      style = {};
      current[key] = style;
    }
    if (!Object.prototype.hasOwnProperty.call(style, 'bgColor')) style.bgColor = 'transparent';
  });
  return current;
}

function ensureScriptNoteDefaultType(editor) {
  const target = _scriptNotePlainObject(editor);
  let current = _scriptNotePlainObject(target.defaultType);
  if (current !== target.defaultType) {
    current = createScriptNoteDefaultType();
    target.defaultType = current;
  }
  // 書式ポップアップはこのオブジェクトを参照したまま Undo スナップショットを
  // 作るため、正規化時に参照を差し替えず同じオブジェクトを更新する。
  current.isTypeDefault = true;
  current.name = '';
  let roleStyle = _scriptNotePlainObject(current.roleStyle);
  if (roleStyle !== current.roleStyle) {
    roleStyle = {};
    current.roleStyle = roleStyle;
  }
  let textStyle = _scriptNotePlainObject(current.textStyle);
  if (textStyle !== current.textStyle) {
    textStyle = {};
    current.textStyle = textStyle;
  }
  let gutter2Style = _scriptNotePlainObject(current.gutter2Style);
  if (gutter2Style !== current.gutter2Style) {
    gutter2Style = {};
    current.gutter2Style = gutter2Style;
  }
  if (!Object.prototype.hasOwnProperty.call(gutter2Style, 'bgColor')) gutter2Style.bgColor = SCRIPTNOTE_DEFAULT_TYPE_BG;
  if (!Object.prototype.hasOwnProperty.call(roleStyle, 'bgColor')) roleStyle.bgColor = SCRIPTNOTE_DEFAULT_TYPE_BG;
  if (!Object.prototype.hasOwnProperty.call(textStyle, 'bgColor')) textStyle.bgColor = SCRIPTNOTE_DEFAULT_TYPE_BG;
  return current;
}

function _scriptNoteStylesEqual(left, right) {
  const a = _scriptNotePlainObject(left);
  const b = _scriptNotePlainObject(right);
  const keys = Array.from(new Set([...Object.keys(a), ...Object.keys(b)])).sort();
  return keys.every(key => a[key] === b[key]);
}

function _scriptNoteMigrateUnifiedGutterStyles(doc) {
  if (!doc || typeof doc !== 'object') return;
  const editor = _scriptNotePlainObject(doc.editor);
  const characters = Array.isArray(doc.scenarioTypes) && doc.scenarioTypes.length ? doc.scenarioTypes
    : (Array.isArray(doc.characters) ? doc.characters : []);
  const countConfig = _scriptNotePlainObject(editor.countConfig);
  const columnStyles = _scriptNotePlainObject(editor.columnStyles);
  const columnAllRules = _scriptNotePlainObject(editor.columnAllRules);
  const hasScopedGutterStyles = Number(editor.gutterStyleScopeVersion || 0) >= 2;
  editor.columnStyles = columnStyles;
  const defs = [
    { id: '_gutter', legacy: 'gutterStyle', count: 'primaryStyle', fallback: null },
    { id: '_gutter2', legacy: 'gutter2Style', count: 'secondaryStyle', fallback: { bgColor: SCRIPTNOTE_DEFAULT_TYPE_BG } },
  ];
  defs.forEach(def => {
    const allRule = _scriptNotePlainObject(columnAllRules[def.id]);
    const current = _scriptNotePlainObject(columnStyles[def.id]);
    const countStyle = _scriptNotePlainObject(countConfig[def.count]);
    const legacyStyles = characters
      .map(chara => _scriptNotePlainObject(_scriptNotePlainObject(chara)[def.legacy]))
      .filter(style => Object.keys(style).length);
    const hasExplicitGlobalStyle = Object.keys(current).length || Object.keys(allRule).length || Object.keys(countStyle).length;
    const commonLegacyStyle = !hasScopedGutterStyles && !hasExplicitGlobalStyle && legacyStyles.length
      && legacyStyles.every(style => _scriptNoteStylesEqual(style, legacyStyles[0]))
      ? legacyStyles[0]
      : null;
    const merged = { ...(def.fallback || {}), ...(commonLegacyStyle || {}), ...allRule, ...current, ...countStyle };
    // 開いている書式ポップアップが保持する参照を壊さないよう、既存オブジェクトを
    // その場で更新する。これにより Undo 取得直後の変更も保存対象へ確実に入る。
    Object.keys(current).forEach(key => delete current[key]);
    Object.assign(current, merged);
    if (Object.keys(current).length) columnStyles[def.id] = current;
    // 直前の一元設定版は、互換用として全体設定を各タイプへ同値コピーしていた。
    // 未識別の旧データだけ同値コピーを除去し、異なる値はタイプ別上書きとして保持する。
    if (!hasScopedGutterStyles) {
      characters.forEach(chara => {
        const item = _scriptNotePlainObject(chara);
        const roleStyle = _scriptNotePlainObject(item[def.legacy]);
        const effectiveRoleStyle = { ...(def.fallback || {}), ...roleStyle };
        if (Object.keys(roleStyle).length && _scriptNoteStylesEqual(effectiveRoleStyle, current)) delete item[def.legacy];
      });
    }
    delete countConfig[def.count];
    delete columnAllRules[def.id];
  });
  editor.gutterStyleScopeVersion = 2;
  if (Object.keys(countConfig).length) editor.countConfig = countConfig;
  else delete editor.countConfig;
  if (Object.keys(columnAllRules).length) editor.columnAllRules = columnAllRules;
  else delete editor.columnAllRules;
  doc.editor = editor;
}

function createScriptNoteDoc(parsed = {}, options = {}) {
  const input = _scriptNotePlainObject(parsed);
  const roleModel = _scriptNoteRoleModel();
  const src = roleModel
    ? roleModel.normalizeDocument(input, options.roleModelOptions || {})
    : input;
  const now = Number.isFinite(options.now) ? options.now : Date.now();
  const editor = { wrapMode: true, statusEnabled: false, ..._scriptNotePlainObject(src.editor) };
  ensureScriptNoteDefaultType(editor);
  ensureScriptNoteNoneType(editor);
  if (editor.baseTextLineHeight != null && editor.baseTextLineHeight !== '') {
    if (editor.baseTextLineHeightH == null || editor.baseTextLineHeightH === '') editor.baseTextLineHeightH = editor.baseTextLineHeight;
    if (editor.baseTextLineHeightV == null || editor.baseTextLineHeightV === '') editor.baseTextLineHeightV = editor.baseTextLineHeight;
  }
  if (editor.baseTextLetterSpacing != null && editor.baseTextLetterSpacing !== '') {
    if (editor.baseTextLetterSpacingH == null || editor.baseTextLetterSpacingH === '') editor.baseTextLetterSpacingH = editor.baseTextLetterSpacing;
    if (editor.baseTextLetterSpacingV == null || editor.baseTextLetterSpacingV === '') editor.baseTextLetterSpacingV = editor.baseTextLetterSpacing;
  }
  const doc = {
    ...src,
    fileType: src.fileType || (typeof SCRIPTNOTE_FILE_TYPE !== 'undefined' ? SCRIPTNOTE_FILE_TYPE : 'meldex-scriptnote'),
    schema_version: Math.max(
      SCRIPTNOTE_SCHEMA_VERSION,
      Number.isFinite(Number(src.schema_version)) ? Number(src.schema_version) : 1,
    ),
    version: src.version || (typeof SCRIPTNOTE_FILE_VERSION !== 'undefined' ? SCRIPTNOTE_FILE_VERSION : 1),
    title: String(src.title || ''),
    layoutMode: _scriptNoteLayoutOrDefault(src.layoutMode),
    // wrapMode の既定値は true。ツールバー状態と保存形式を一致させる。
    editor,
    scenarioTypes: Array.isArray(src.scenarioTypes) ? src.scenarioTypes : [],
    characters: Array.isArray(src.characters) ? src.characters : [],
    characterDb: Array.isArray(src.characterDb) ? src.characterDb : [],
    notes: Array.isArray(src.notes) ? src.notes : [],
    rubyRules: Array.isArray(src.rubyRules) ? src.rubyRules : [],
    rows: _scriptNoteNormalizeRows(src.rows, now),
    source: _scriptNotePlainObject(src.source),
  };
  if (typeof MeldexRubyPresentation !== 'undefined') {
    MeldexRubyPresentation.ensureDocument(doc, { defaults: options.rubyPresentationDefaults });
  }
  return doc;
}

function applyLegacyScriptNoteDocMigrations(doc, options = {}) {
  if (!doc || typeof doc !== 'object') return doc;
  const legacyDetectKindByName = typeof options.legacyDetectKindByName === 'function'
    ? options.legacyDetectKindByName
    : (() => 'dialogue');
  const layoutMode = _scriptNoteLayoutOrDefault(doc.layoutMode);
  const legacyBreakNames = SCRIPTNOTE_LEGACY_PAGE_BREAK_BY_MODE[layoutMode] || SCRIPTNOTE_LEGACY_PAGE_BREAK_BY_MODE[SCRIPTNOTE_DEFAULT_LAYOUT_MODE];
  const characters = Array.isArray(doc.scenarioTypes) && doc.scenarioTypes.length ? doc.scenarioTypes
    : (Array.isArray(doc.characters) ? doc.characters : []);
  const editor = _scriptNotePlainObject(doc.editor);
  doc.editor = editor;
  ensureScriptNoteDefaultType(editor);
  ensureScriptNoteNoneType(editor);

  characters.forEach((chara) => {
    const item = _scriptNotePlainObject(chara);
    if (item.isDefault) return;
    if (item.isBreak === undefined) {
      if (item.kind === 'break') item.isBreak = true;
      else if (item.name && (legacyBreakNames.includes(item.name) || legacyDetectKindByName(item.name) === 'break')) item.isBreak = true;
    }
    if (item.isSummary === undefined) {
      if (item.kind === 'summary') item.isSummary = true;
      else if (item.name && (SCRIPTNOTE_LEGACY_SUMMARY_NAMES.includes(item.name) || legacyDetectKindByName(item.name) === 'summary')) item.isSummary = true;
    }
  });

  // 旧形式: kind ごとの autoColorConfig を列ごとの autoColorRule に寄せる。
  if (!editor.autoColorRule && editor.autoColorConfig && typeof editor.autoColorConfig === 'object') {
    const cfg = editor.autoColorConfig;
    const pickKind = ['dialogue', 'action', 'heading', 'summary', 'break'].find((kind) => cfg[kind]);
    if (pickKind) {
      const value = cfg[pickKind];
      if (typeof value === 'string') {
        editor.autoColorRule = { _gutter: value, _gutter2: value, _role: value, _text: value };
      } else if (value && typeof value === 'object' && !Array.isArray(value)) {
        editor.autoColorRule = { ...value };
      }
    }
  }

  // 旧形式: actionIndent をト書き系タイプの indent へ転写する。
  if (editor.actionIndent) {
    const oldIndent = editor.actionIndent;
    characters.forEach((chara) => {
      const item = _scriptNotePlainObject(chara);
      if (item.isDefault || item.indent !== undefined) return;
      if (item.kind === 'action' || legacyDetectKindByName(item.name) === 'action') item.indent = oldIndent;
    });
  }

  _scriptNoteMigrateUnifiedGutterStyles(doc);
  const roleModel = _scriptNoteRoleModel();
  if (roleModel) roleModel.ensureDocument(doc, options.roleModelOptions || {});

  return doc;
}

function _scriptNoteSerializedCharacters(doc) {
  const characters = Array.isArray(doc?.characters) ? doc.characters : [];
  return characters.map(chara => {
    const item = { ..._scriptNotePlainObject(chara) };
    if (item.gutterStyle) item.gutterStyle = { ..._scriptNotePlainObject(item.gutterStyle) };
    if (item.gutter2Style) item.gutter2Style = { ..._scriptNotePlainObject(item.gutter2Style) };
    return item;
  });
}

function _scriptNoteSerializedTypes(doc) {
  const types = Array.isArray(doc?.scenarioTypes) ? doc.scenarioTypes : [];
  return types.map(item => {
    const type = { ..._scriptNotePlainObject(item) };
    for (const key of ['gutterStyle', 'gutter2Style', 'roleStyle', 'textStyle', 'customStyles']) {
      if (type[key]) type[key] = { ..._scriptNotePlainObject(type[key]) };
    }
    return type;
  });
}

function serializeScriptNoteDoc(doc) {
  if (!doc || typeof doc !== 'object') return null;
  if (typeof MeldexRubyPresentation !== 'undefined') MeldexRubyPresentation.ensureDocument(doc);
  if (!doc.editor || typeof doc.editor !== 'object' || Array.isArray(doc.editor)) doc.editor = {};
  ensureScriptNoteDefaultType(doc.editor);
  ensureScriptNoteNoneType(doc.editor);
  _scriptNoteMigrateUnifiedGutterStyles(doc);
  const serialized = {
    ...doc,
    fileType: doc.fileType || (typeof SCRIPTNOTE_FILE_TYPE !== 'undefined' ? SCRIPTNOTE_FILE_TYPE : 'meldex-scriptnote'),
    schema_version: Math.max(
      SCRIPTNOTE_SCHEMA_VERSION,
      Number.isFinite(Number(doc.schema_version)) ? Number(doc.schema_version) : 1,
    ),
    version: doc.version || (typeof SCRIPTNOTE_FILE_VERSION !== 'undefined' ? SCRIPTNOTE_FILE_VERSION : 1),
    title: String(doc.title || ''),
    layoutMode: _scriptNoteLayoutOrDefault(doc.layoutMode),
    editor: { ..._scriptNotePlainObject(doc.editor) },
    // 全体既定は editor.columnStyles、タイプ別上書きは各タイプのスタイルへ分離して保存する。
    scenarioTypes: _scriptNoteSerializedTypes(doc),
    characters: _scriptNoteSerializedCharacters(doc),
    characterDb: Array.isArray(doc.characterDb) ? doc.characterDb : [],
    notes: Array.isArray(doc.notes) ? doc.notes : [],
    rubyRules: Array.isArray(doc.rubyRules) ? doc.rubyRules : [],
    ...(doc.rubyPresentation && typeof doc.rubyPresentation === 'object'
      ? { rubyPresentation: { ...doc.rubyPresentation } }
      : {}),
    rows: _scriptNoteNormalizeRows(doc.rows, Date.now()),
    source: _scriptNotePlainObject(doc.source),
  };
  const roleModel = _scriptNoteRoleModel();
  return roleModel ? roleModel.prepareForSave(serialized) : serialized;
}

function createScriptNoteRowIdSet(doc) {
  return new Set((Array.isArray(doc?.rows) ? doc.rows : [])
    .map((row) => row?.id)
    .filter(Boolean));
}

;

/* === gb-scriptnote-editor.js === */
;
/* gb-scriptnote-editor.js: 軽量シナリオエディタ v2
   シナリオエンジンに依存しない、Word方式の段落ベースエディタ */

/* ================================
   ルビマークアップのエスケープ
   ================================
   ルビ表記 {漢字|ルビ} と、ユーザーが入力した生の `{` `|` `}` を区別するために
   エスケープ機構を使う。保存時: 生の `\ { | }` を `\\ \{ \| \}` に置き換え。
   復元時: 逆変換する。古いデータ（エスケープなし）も引き続き解釈できるよう、
   正規表現は \{x\|y\} と {x|y} の両方のパターンを受け付ける。 */
function _sn2EscapeRubyText(s) {
  if (typeof s !== 'string') return '';
  return s.replace(/([\\{|}])/g, '\\$1');
}
function _sn2UnescapeRubyText(s) {
  if (typeof s !== 'string') return '';
  return s.replace(/\\([\\{|}])/g, '$1');
}
// ルビマークアップ用の正規表現パターン。内部文字として \{ \| \} \\ のエスケープを許容する
const _SN2_RUBY_PATTERN = '\\{((?:\\\\[\\\\{|}]|[^{|}\\\\])+)\\|((?:\\\\[\\\\{|}]|[^{|}\\\\])+)\\}';
const _SN2_MANUAL_LINK_PATTERN = '\\[((?:\\\\.|[^\\]])+)\\]\\(ml:([^)]+)\\)';
function _sn2NewRubyRegex() { return new RegExp(_SN2_RUBY_PATTERN, 'g'); }
function _sn2NewVisibleMarkupRegex() { return new RegExp(_SN2_RUBY_PATTERN + '|' + _SN2_MANUAL_LINK_PATTERN, 'g'); }
function _sn2EscapeScriptNotePlainText(s) {
  if (typeof s !== 'string') return '';
  return _sn2EscapeRubyText(s).replace(new RegExp(_SN2_MANUAL_LINK_PATTERN, 'g'), (matched) => {
    return matched.replace(/([\[\]])/g, '\\$1');
  });
}
function _sn2UnescapeScriptNotePlainText(s) {
  if (typeof s !== 'string') return '';
  return _sn2UnescapeRubyText(s.replace(/\\([\[\]])/g, '$1'));
}
function _sn2DecodeManualLinkLabel(label) {
  return _sn2UnescapeRubyText(String(label || '').replace(/\\([\[\]\\])/g, '$1'));
}
function _sn2BuildManualLinkMarkup(label, target) {
  const safeLabel = _sn2EscapeRubyText(String(label || '')).replace(/([\\\[\]])/g, '\\$1');
  const encodedTarget = encodeURIComponent(String(target || ''))
    .replace(/[()]/g, (ch) => '%' + ch.charCodeAt(0).toString(16).toUpperCase());
  return `[${safeLabel}](ml:${encodedTarget})`;
}
// 本文中のルビをプレーンテキストに変換（エスケープの逆変換も行う）
function _sn2StripRubyToPlain(s) {
  if (typeof s !== 'string') return '';
  return _sn2UnescapeScriptNotePlainText(
    s
      .replace(new RegExp(_SN2_MANUAL_LINK_PATTERN, 'g'), (_m, label) => _sn2DecodeManualLinkLabel(label))
      .replace(_sn2NewRubyRegex(), (_m, kanji) => kanji)
  );
}

function _sn2SplitEscapedPlainSegment(raw, visibleOffset) {
  if (visibleOffset <= 0) return ['', raw];
  let rawIndex = 0;
  let visibleIndex = 0;
  while (rawIndex < raw.length && visibleIndex < visibleOffset) {
    const ch = raw[rawIndex];
    const next = raw[rawIndex + 1];
    if (ch === '\\' && next && '\\{|}[]'.includes(next)) rawIndex += 2;
    else rawIndex += 1;
    visibleIndex += 1;
  }
  return [raw.slice(0, rawIndex), raw.slice(rawIndex)];
}

function _sn2BuildRubyMarkup(base, ruby) {
  if (!base) return '';
  if (!ruby) return _sn2EscapeScriptNotePlainText(base);
  return `{${_sn2EscapeRubyText(base)}|${_sn2EscapeRubyText(ruby)}}`;
}

function _sn2CollectVisibleSegments(raw) {
  const segments = [];
  const re = _sn2NewVisibleMarkupRegex();
  let last = 0;
  let match;
  while ((match = re.exec(raw)) !== null) {
    if (match.index > last) segments.push({ type: 'plain', raw: raw.slice(last, match.index) });
    if (match[1] != null) {
      segments.push({
        type: 'ruby',
        raw: match[0],
        plain: _sn2UnescapeRubyText(match[1]),
        ruby: _sn2UnescapeRubyText(match[2]),
      });
    } else {
      let target = match[4] || '';
      try { target = decodeURIComponent(target); } catch {}
      segments.push({
        type: 'manual-link',
        raw: match[0],
        plain: _sn2StripRubyToPlain(_sn2DecodeManualLinkLabel(match[3])),
        target,
      });
    }
    last = match.index + match[0].length;
  }
  if (last < raw.length) segments.push({ type: 'plain', raw: raw.slice(last) });
  return segments;
}

function _sn2SplitRawTextByVisibleOffset(rawText, visibleOffset) {
  const raw = String(rawText || '');
  let remaining = Math.max(0, Number(visibleOffset) || 0);
  let before = '';
  let after = '';
  let done = false;
  const segments = _sn2CollectVisibleSegments(raw);
  segments.forEach((segment) => {
    if (done) {
      after += segment.raw;
      return;
    }
    const plain = (segment.type === 'ruby' || segment.type === 'manual-link')
      ? segment.plain
      : _sn2UnescapeScriptNotePlainText(segment.raw);
    const len = plain.length;
    if (remaining <= 0) {
      after += segment.raw;
      done = true;
      return;
    }
    if (remaining >= len) {
      before += segment.raw;
      remaining -= len;
      return;
    }
    if (segment.type === 'ruby') {
      const baseBefore = plain.slice(0, remaining);
      const baseAfter = plain.slice(remaining);
      const ruby = segment.ruby || '';
      const rubySplit = plain.length ? Math.round((ruby.length * remaining) / plain.length) : 0;
      before += _sn2BuildRubyMarkup(baseBefore, ruby.slice(0, rubySplit));
      after += _sn2BuildRubyMarkup(baseAfter, ruby.slice(rubySplit));
    } else if (segment.type === 'manual-link') {
      const labelBefore = plain.slice(0, remaining);
      const labelAfter = plain.slice(remaining);
      before += labelBefore ? _sn2BuildManualLinkMarkup(labelBefore, segment.target) : '';
      after += labelAfter ? _sn2BuildManualLinkMarkup(labelAfter, segment.target) : '';
    } else {
      const [segBefore, segAfter] = _sn2SplitEscapedPlainSegment(segment.raw, remaining);
      before += segBefore;
      after += segAfter;
    }
    done = true;
  });
  return [before, after];
}

function _sn2ReplaceRawTextByVisibleRange(rawText, startOffset, endOffset, replacement) {
  const [prefixAndMatch, after] = _sn2SplitRawTextByVisibleOffset(rawText, endOffset);
  const [before] = _sn2SplitRawTextByVisibleOffset(prefixAndMatch, startOffset);
  return before + _sn2EscapeScriptNotePlainText(String(replacement || '')) + after;
}

class ScriptNoteEditor {
  constructor(hostEl) {
    this.host = hostEl;
    this.doc = null;
    this._path = '';
    // 工程2-C項目3: 読込時に受け取ったetag（保存コーディネーター経由のif_match_etag送信に使う）。
    this._lastSavedEtag = '';
    this._lastSavedTransportRevision = '';
    this._dirty = false;
    this._saveTimer = null;
    this._bound = false;
    this._roleMenu = null;
    this._roleMenuRow = null;
    this._roleMenuCloseHandler = null;
    this._calcCache = null;
    this._undoTimer = null;
    this._lastPushedSnap = '';
    this._pushUndoSuppressed = false;
    this._textInputUndoOpen = false;
    this._textInputUndoTimer = null;
    this._wrapResizeObserver = null;
    this._wrapResizeRaf = null;
    this._wrapResizeTimer = null;
    this._wrapResizeWindowHandler = null;
    this._wrapResizeInterval = null;
    this._wrapResizeLastSize = 0;
    this._gridCellSelection = new Set();
    this._gridCellAnchor = null;
  }

  // === ドキュメント操作 ===

  loadDoc(parsed, path = '', etag = '', conflictGeneration = null, identity = null) {
    const coordinator = window.MeldexDocumentSaveCoordinator;
    let documentKey = path;
    if (coordinator && path) {
      documentKey = coordinator.bindDocumentIdentity(path, identity || {}) || coordinator.documentKeyForPath(path);
    }
    if (coordinator && path && conflictGeneration != null) {
      const current = coordinator.getConflict?.(documentKey);
      if (!current || current.generation !== conflictGeneration) return false;
    }
    if (this._undoTimer) { clearTimeout(this._undoTimer); this._undoTimer = null; }
    if (this._saveTimer) { clearTimeout(this._saveTimer); this._saveTimer = null; }
    const previousRegisteredPath = this._sn2RegisteredPath || '';
    const previousRegisteredScopeId = this._sn2RegisteredScopeId || '';
    const _prevDocumentKey = (coordinator && this._path)
      ? coordinator.documentKeyForPath(this._path) : '';
    this._path = path;
    // 工程2-C項目3: 読込時のetagを保持する。競合の解決として再読込した場合だけ、
    // 読込開始時に捕捉した世代と一致する保留状態を描画完了後に解除する。
    this._lastSavedEtag = etag || '';
    this._lastSavedTransportRevision = coordinator
      ? coordinator.normalizeTransportRevision(
        coordinator.currentTransportName(),
        identity?.transport_revision || etag || '',
      )
      : (etag || '');
    if (coordinator && path) {
      if (documentKey !== _prevDocumentKey) coordinator.unregisterParticipant(_prevDocumentKey, this);
      coordinator.registerParticipant(documentKey, this);
    }
    this._dirty = false;
    this.doc = createScriptNoteDoc(parsed);
    // 削除検知用の行ID スナップショット
    this._lastSavedRowIds = createScriptNoteRowIdSet(this.doc);
    // rowsで使用中のタイプをcharactersに自動登録
    this._syncCharactersFromRows();
    // 役割が空の行に適用するデフォルトタイプを末尾に確保
    this._ensureDefaultChara();
    applyLegacyScriptNoteDocMigrations(this.doc, {
      legacyDetectKindByName: (name) => this._legacyDetectKindByName(name),
    });
    // 一元化移行の完了後にのみ補完される初期値（（なし）行の区切り背景=透明）を初回描画前に確定させる
    this._ensureDefaultChara();
    if (typeof this._ensureStatusConfig === 'function') this._ensureStatusConfig();
    this._calcCache = null;
    this._lastPushedSnap = '';
    // セル範囲選択の残留を防止（別ファイルへ切替後に古い選択が再度有効化されるのを防ぐ）
    this._gridCellSelection = new Set();
    this._gridCellAnchor = null;
    this._textCellSelection = new Set();
    this._textCellAnchorIdx = -1;
    // エディタレジストリに登録（マルチインスタンス対応）
    if (typeof _sn2Editors !== 'undefined') {
      if (previousRegisteredPath && previousRegisteredPath !== this._path && _sn2Editors[previousRegisteredPath] === this) {
        delete _sn2Editors[previousRegisteredPath];
      }
      if (previousRegisteredScopeId && previousRegisteredScopeId !== this._historyScopeId && _sn2Editors[previousRegisteredScopeId] === this) {
        delete _sn2Editors[previousRegisteredScopeId];
      }
      if (this._path) _sn2Editors[this._path] = this;
      if (this._historyScopeId) _sn2Editors[this._historyScopeId] = this;
      this._sn2RegisteredPath = this._path || '';
      this._sn2RegisteredScopeId = this._historyScopeId || '';
    }
    this._render();
    this._pushUndo('初期状態');
    if (coordinator && path && conflictGeneration != null) {
      const resolved = coordinator.resolveConflict(documentKey, conflictGeneration);
      if (resolved) window.MeldexConflictPendingBanner?.hide?.(documentKey);
    } else if (coordinator?.getConflict?.(documentKey)) {
      this._showConflictPending(documentKey, path);
    }
    return true;
  }

  collectDoc() {
    if (!this.doc) return null;
    this._syncAllFromDom();
    return serializeScriptNoteDoc(this.doc);
  }

  _showConflictPending(documentKey, path) {
    window.MeldexConflictPendingBanner?.show?.(documentKey, {
      label: '競合を保留中',
      e2eId: 'scriptnote-conflict-pending-banner',
      onConfirm: () => { this._reviewConflict(path, documentKey); },
    });
  }

  _restoreConflictReview(documentKey, record, path) {
    const coordinator = window.MeldexDocumentSaveCoordinator;
    if (coordinator && record) {
      const current = coordinator.getConflict?.(documentKey);
      if (!current || current.generation !== record.generation) return;
      coordinator.restoreConflict?.(documentKey, record);
    }
    this._showConflictPending(documentKey, path);
  }

  async _reviewConflict(path, documentKey) {
    const coordinator = window.MeldexDocumentSaveCoordinator;
    const record = coordinator?.requestConflictReview?.(documentKey) || null;
    if (coordinator && !record) return;
    const generation = record?.generation ?? null;
    window.MeldexConflictPendingBanner?.hide?.(documentKey);
    try {
      const keepLocal = typeof cfConfirm === 'function'
        ? await cfConfirm('このシナリオは他の場所で更新されています。今の編集内容で上書きしますか？（キャンセルすると最新版を読み込み、今の編集内容は失われます）')
        : false;
      if (this._path !== path) {
        this._restoreConflictReview(documentKey, record, path);
        return;
      }
      if (keepLocal) {
        const json = JSON.stringify(this.collectDoc(), null, 2);
        const result = await apiPut('/file?path=' + encodeURIComponent(path), {
          content: json,
          force_overwrite: true,
        });
        const resolved = coordinator?.resolveConflict?.(documentKey, generation);
        if (coordinator && !resolved) {
          throw new Error('シナリオの競合状態が更新されたため、上書き結果を確定できません');
        }
        if (this._path === path) {
          this._lastSavedEtag = result?.etag || this._lastSavedEtag;
          if (coordinator && (result?.transport_revision || result?.etag)) {
            this._lastSavedTransportRevision = coordinator.normalizeTransportRevision(
              coordinator.currentTransportName(),
              result.transport_revision || result.etag,
            );
            coordinator.bindDocumentIdentity(path, result);
          }
          this._lastSavedRowIds = createScriptNoteRowIdSet(this.doc);
          this._dirty = false;
        }
        if (resolved) window.MeldexConflictPendingBanner?.hide?.(documentKey);
        await window.MeldexDraftRecovery?.markSynced?.(path);
        if (typeof showStatus === 'function') showStatus('自分の編集でシナリオを上書き保存しました');
        return;
      }

      const localJson = JSON.stringify(this.collectDoc(), null, 2);
      await window.MeldexDraftRecovery?.saveDraft?.(path, localJson, this._lastSavedEtag || '');
      const component = typeof getActiveScriptNoteComponent === 'function'
        ? getActiveScriptNoteComponent()
        : null;
      if (component?._editor === this && typeof component._loadScenario === 'function') {
        const loaded = await component._loadScenario(path, {
          skipNavPush: true,
          skipRecent: true,
          skipAutoVersion: true,
          skipSaveLastView: true,
          conflictGeneration: generation,
        });
        if (!loaded) throw new Error('最新版の読み込みに失敗しました');
      } else {
        const data = await apiFetch('/file?path=' + encodeURIComponent(path));
        const parsed = JSON.parse(data.content || '{}');
        if (typeof _sn2ExpandDefaultFileStyle === 'function') _sn2ExpandDefaultFileStyle(parsed);
        if (typeof isScriptNoteFileDoc === 'function' && !isScriptNoteFileDoc(parsed)) {
          throw new Error('シナリオ形式ファイルではありません');
        }
        if (!this.loadDoc(parsed, path, data.etag || '', generation, data)) {
          throw new Error('競合状態が更新されたため、再読込を中止しました');
        }
      }
      const current = coordinator?.getConflict?.(documentKey);
      if (current?.generation === generation) throw new Error('競合の解除に失敗しました');
      if (typeof showStatus === 'function') showStatus('相手の変更を読み込みました');
    } catch (error) {
      this._restoreConflictReview(documentKey, record, path);
      if (typeof showStatus === 'function') showStatus('競合の解決に失敗しました: ' + error.message, true);
    }
  }

  async save() {
    if (!this._path || !this.doc) return true;
    const savePath = this._path;
    const json = JSON.stringify(this.collectDoc(), null, 2);
    const prevIds = this._lastSavedRowIds || new Set();
    const currIds = createScriptNoteRowIdSet(this.doc);
    const coordinator = window.MeldexDocumentSaveCoordinator;
    const documentKey = coordinator ? coordinator.documentKeyForPath(savePath) : savePath;
    const transportRevisionAtRequestTime = this._lastSavedTransportRevision || this._lastSavedEtag || '';
    const sendFn = (previousResult) => {
      const chainedRevision = previousResult?.transport_revision || previousResult?.etag || '';
      const revisionForWrite = chainedRevision && coordinator
        ? coordinator.normalizeTransportRevision(coordinator.currentTransportName(), chainedRevision)
        : transportRevisionAtRequestTime;
      return apiPut('/file?path=' + encodeURIComponent(savePath), {
        content: json,
        if_match_etag: revisionForWrite && coordinator
          ? coordinator.revisionTokenForWrite(revisionForWrite, coordinator.currentTransportName())
          : (chainedRevision || this._lastSavedEtag || ''),
        transport_revision: revisionForWrite || '',
        skip_if_missing: true,
      });
    };
    try {
      // 工程2-C項目3: 2秒自動保存・flush()・書式変換保存を同じ文書キューへ接続する
      // （coordinator未ロード時は従来通り直接送信するフォールバック）。
      const saveResult = coordinator
        ? await coordinator.requestSave(documentKey, this, savePath, json, sendFn, { reason: 'scriptnote-auto' })
        : await sendFn();
      if (saveResult?.conflictPending) {
        this._dirty = true;
        window.MeldexDraftRecovery?.queueDraft?.(savePath, json, this._lastSavedEtag || '');
        this._showConflictPending(documentKey, savePath);
        return false;
      }
      if (saveResult?.skipped || saveResult?.missing) {
        this._dirty = true;
        if (typeof showStatus === 'function') showStatus('保存先が見つかりません。名前を付けて保存してください', true);
        return false;
      }
      if (saveResult?.etag && this._path === savePath) this._lastSavedEtag = saveResult.etag;
      if (coordinator && this._path === savePath && (saveResult?.transport_revision || saveResult?.etag)) {
        this._lastSavedTransportRevision = coordinator.normalizeTransportRevision(
          coordinator.currentTransportName(),
          saveResult.transport_revision || saveResult.etag,
        );
        coordinator.bindDocumentIdentity(savePath, saveResult);
      }
      const unchanged = this._path === savePath && JSON.stringify(this.collectDoc(), null, 2) === json;
      if (this._path === savePath) {
        this._lastSavedRowIds = currIds;
        if (unchanged) this._dirty = false;
      }
      // 削除された行IDを抽出し、該当コメントを孤児化 (annotation_unification_plan.md §5.3)
      const removed = [...prevIds].filter(id => !currIds.has(id));
      if (removed.length > 0) {
        const path = savePath;
        Promise.all(removed.map(id =>
          apiPost('/annotations/orphan-by-target', {
            target_kind: 'scriptnote_line',
            target_file: path,
            item_id: id,
            cascade_container: true,
          }).catch(() => {})
        ));
      }
      // Audit-P1 H-3: 保存完了後にコメントバッジキャッシュを無効化し、
      // 行並び替え・行挿入・行削除の結果を即座に反映する（3 秒 TTL キャッシュで
      // 古いバッジが残るのを防ぐ）。
      if (typeof CommentBadges !== 'undefined' && this._path === savePath && this.host) {
        try {
          CommentBadges.invalidate(savePath);
          CommentBadges.refreshScriptnote(savePath, this.host);
        } catch (_) {}
      }
      return true;
    } catch (e) {
      if (coordinator && (e?.status === 409 || e?.meldexCode === 'etag_conflict')) {
        // 工程2-C項目3: 409を受けた文書をconflict-pendingへ遷移させ、以後の
        // 自動保存（2秒タイマー）をコーディネーター入口で止める（工程2-Aと同じ契約）。
        this._dirty = true;
        coordinator.reportConflict(documentKey, {
          path: savePath,
          localMd: json,
          localEtag: this._lastSavedTransportRevision || this._lastSavedEtag || '',
          serverDetail: (e && e.meldexDetail && typeof e.meldexDetail === 'object') ? e.meldexDetail : null,
        });
        window.MeldexDraftRecovery?.saveDraft?.(savePath, json, this._lastSavedEtag || '');
        this._showConflictPending(documentKey, savePath);
        showStatus('シナリオは上書きされていません。別の端末で更新されています。最新のシナリオを開き直してから編集内容を反映してください', true);
        return false;
      }
      if (typeof showStatus === 'function') showStatus('保存失敗: ' + e.message, true);
      return false;
    }
  }

  flush() {
    if (this._saveTimer) { clearTimeout(this._saveTimer); this._saveTimer = null; }
    this._syncAllFromDom();
    if (this._dirty) return this.save();
    return Promise.resolve(true);
  }

  // === モード別カウント定義 ===
  // 設定駆動方針: 区切り/プロットの判定はタイプのオプション設定 (chara.isBreak / chara.isSummary)
  // で行う。MODE_COUNT_DEFS は label のデフォルト値の供給だけに使う。

  static get MODE_COUNT_DEFS() {
    if (ScriptNoteEditor._modeCountDefsCache) return ScriptNoteEditor._modeCountDefsCache;
    return (ScriptNoteEditor._modeCountDefsCache = {
      manga:   { primaryLabel: 'p', secondaryLabel: 'コマ' },
      drama:   { primaryLabel: '頁', secondaryLabel: 'カット' },
      afureko: { primaryLabel: '頁', secondaryLabel: 'カット' },
      stage:   { primaryLabel: '頁', secondaryLabel: 'カット' },
    });
  }

  _getCountDef() {
    const mode = this.doc?.layoutMode || 'manga';
    const base = ScriptNoteEditor.MODE_COUNT_DEFS[mode] || ScriptNoteEditor.MODE_COUNT_DEFS.manga;
    const custom = this.doc?.editor?.countConfig || {};
    return {
      primaryLabel: custom.primaryLabel || base.primaryLabel,
      secondaryLabel: custom.secondaryLabel || base.secondaryLabel,
    };
  }

  // chara のオプション設定で区切り/プロットフラグが立っているタイプ名集合を返す
  _getRoleFlagSets() {
    const breakNames = new Set();
    const summaryNames = new Set();
    const roleModel = globalThis.GBScriptNoteRoleModel;
    const subjects = [
      ...(roleModel?.buildRoleChoices?.(this.doc) || []),
      ...(this.doc?.rows || []),
    ];
    subjects.forEach((subject) => {
      const effective = roleModel?.getEffectiveRole?.(this.doc, subject);
      const name = String(effective?.name || subject?.role || subject?.name || '');
      if (!name) return;
      const type = effective?.type || effective?.style || null;
      if (type?.isBreak || type?.kind === 'break') breakNames.add(name);
      if (type?.isSummary || type?.kind === 'summary') summaryNames.add(name);
    });
    return { breakNames, summaryNames };
  }

  // === ページ/コマ番号計算 ===

  _calcPagePanel() {
    if (this._calcCache && this._calcCache.length === this.doc.rows.length) return this._calcCache;
    const rows = this.doc.rows;
    const { breakNames, summaryNames } = this._getRoleFlagSets();
    const isBreakRow = (role) => !!role && breakNames.has(role);
    const isSummaryRow = (role) => !!role && summaryNames.has(role);
    const result = [];
    let page = 1, panel = 1;
    for (let i = 0; i < rows.length; i++) {
      const role = rows[i].role;
      const text = rows[i].text;
      const isPageBreak = isBreakRow(role);
      const isPageReset = isPageBreak;
      const isSummary = isSummaryRow(role);

      // ページ番号: 区切り行で+1
      if (i > 0 && isPageBreak) page++;

      // コマ番号: リセットまたはインクリメント
      if (isPageReset || isSummary) {
        panel = 1;
      } else if (i > 0) {
        const prevRole = rows[i - 1].role;
        if (isBreakRow(prevRole) || isSummaryRow(prevRole)) {
          panel = 1;
        } else if (!role && !text) {
          panel++;
        }
      }

      const showPage = isPageBreak || isSummary || (i === 0);
      const showPanel = !isPageBreak && !isSummary && (role || text);
      result.push({ page, panel, showPage, showPanel });
    }
    this._calcCache = result;
    return result;
  }

  _fmtCount(label, num, cfg) {
    const pad = cfg.pad ?? 2;
    const pos = cfg.pos || 'before';
    if (pad === 0) return label; // 0桁 → 単位テキストのみ
    const n = pad > 0 ? String(num).padStart(pad, '0') : String(num);
    if (pos === 'after') return n + label;
    if (pos === 'both') return (cfg.labelBefore ?? label) + n + (cfg.labelAfter ?? label);
    return label + n;
  }

  _formatGutter(calc) {
    if (!calc) return '';
    const def = this._getCountDef();
    const cc = this.doc?.editor?.countConfig || {};
    const parts = [];
    parts.push(this._fmtCount(def.primaryLabel, calc.page, {
      pad: cc.primaryPad ?? cc.padDigits ?? 2,
      pos: cc.primaryPos ?? cc.labelPosition ?? 'before',
      labelBefore: cc.primaryLabelBefore,
      labelAfter: cc.primaryLabelAfter,
    }));
    if (calc.showPanel) parts.push(this._fmtCount(def.secondaryLabel, calc.panel, {
      pad: cc.secondaryPad ?? cc.padDigits ?? 2,
      pos: cc.secondaryPos ?? cc.labelPosition ?? 'before',
      labelBefore: cc.secondaryLabelBefore,
      labelAfter: cc.secondaryLabelAfter,
    }));
    return parts.join(' ');
  }

  _formatGutterPrimary(calc) {
    if (!calc) return '';
    const def = this._getCountDef();
    const cc = this.doc?.editor?.countConfig || {};
    return this._fmtCount(def.primaryLabel, calc.page, {
      pad: cc.primaryPad ?? cc.padDigits ?? 2,
      pos: cc.primaryPos ?? cc.labelPosition ?? 'before',
      labelBefore: cc.primaryLabelBefore,
      labelAfter: cc.primaryLabelAfter,
    });
  }

  _formatGutterSecondary(calc) {
    if (!calc || !calc.showPanel) return '';
    const def = this._getCountDef();
    const cc = this.doc?.editor?.countConfig || {};
    return this._fmtCount(def.secondaryLabel, calc.panel, {
      pad: cc.secondaryPad ?? cc.padDigits ?? 2,
      pos: cc.secondaryPos ?? cc.labelPosition ?? 'before',
      labelBefore: cc.secondaryLabelBefore,
      labelAfter: cc.secondaryLabelAfter,
    });
  }

  // === キャラクタースタイル ===

  // autoColor/autoColorTarget対応: 実効的な背景色・文字色を解決
  _resolveCharaColors(chara, colId) {
    if (!chara) return { bgColor: '', textColor: '' };
    let bg = chara.bgColor || '';
    let fg = chara.textColor || '';
    if (chara.autoColor) {
      // 列ごとのターゲットを取得（オブジェクト形式: { _gutter: 'bg', _role: 'text' }、文字列形式: 'bg'）
      // autoColorが設定済みならデフォルトは'bg'（既存データとの互換性）、未設定時のデフォルトは'none'
      const act = chara.autoColorTarget || 'bg';
      const target = (typeof act === 'object' && colId) ? (act[colId] || 'none') : (typeof act === 'string' ? act : 'bg');
      if (target === 'both') {
        if (!bg) bg = typeof calcBgColor === 'function' ? calcBgColor(chara.autoColor) : chara.autoColor;
        if (!fg) fg = chara.autoColor;
      } else if (target === 'bg') {
        bg = bg || chara.autoColor;
      } else if (target === 'text') {
        fg = fg || chara.autoColor;
      }
    }
    return { bgColor: bg, textColor: fg };
  }

  _getCharaStyle(role) {
    if (!role) return null;
    const chara = globalThis.GBScriptNoteRoleModel?.getEffectiveStyle?.(this.doc, role)
      || this.doc.characters.find(c => !c.isDefault && c.name === role);
    if (!chara) return null;
    const { bgColor, textColor } = this._resolveCharaColors(chara, '_role');
    const rs = chara.roleStyle || {};
    const parts = [];
    if (rs.bgColor || bgColor) parts.push(`background:${rs.bgColor || bgColor}`);
    if (rs.textColor || textColor) parts.push(`color:${rs.textColor || textColor}`);
    if (rs.fontWeight === 'bold') parts.push('font-weight:bold');
    if (rs.fontStyle === 'italic') parts.push('font-style:italic');
    if (rs.fontSize) parts.push(`font-size:${rs.fontSize}px`);
    if (rs.fontFamily) parts.push(`font-family:${rs.fontFamily}`);
    if (rs.textStrokeColor) parts.push(`-webkit-text-stroke-color:${rs.textStrokeColor}`);
    if (rs.textStrokeWidth) parts.push(`-webkit-text-stroke-width:${rs.textStrokeWidth}px`);
    if (rs.leftAccent) parts.push(`box-shadow:inset 3px 0 0 ${rs.accentColor || chara.accentColor || rs.textColor || textColor || 'var(--accent)'}`);
    if (rs.underline) parts.push(`text-decoration:underline;text-decoration-color:${rs.accentColor || chara.accentColor || rs.textColor || textColor || 'var(--accent)'}`);
    return parts.length ? parts.join(';') : null;
  }

  _applyRowStyle(rowEl, role) {
    const textEl = rowEl.querySelector('.sn2-text');
    const roleBtn = rowEl.querySelector('.sn2-role-btn');
    const statusBtn = rowEl.querySelector('.sn2-status-btn');
    const gutterEl = rowEl.querySelector('.sn2-gutter:not(.sn2-gutter2)');
    const gutter2El = rowEl.querySelector('.sn2-gutter2');
    const rowId = rowEl.dataset.rowId;
    const rowData = this.doc?.rows?.find((item) => item.id === rowId) || null;
    const chara = globalThis.GBScriptNoteRoleModel?.getEffectiveStyle?.(this.doc, rowData || role)
      || (role
        ? this.doc.characters.find(c => !c.isDefault && c.name === role)
        : this.doc.characters.find(c => c.isDefault));
    // 列スタイル設定
    const colStyles = this.doc.editor?.columnStyles || {};
    // スタイル解決: タイプ別設定（具体的）が列全体設定（汎用的）を常に上書き
    const resolve = (colStyle, roleStyle) => {
      const pick = (rVal, cVal) => rVal || cVal || '';
      return {
        bgColor: pick(roleStyle?.bgColor, colStyle?.bgColor),
        textColor: pick(roleStyle?.textColor, colStyle?.textColor),
        fontWeight: pick(roleStyle?.fontWeight, colStyle?.fontWeight),
        fontStyle: pick(roleStyle?.fontStyle, colStyle?.fontStyle),
        fontSize: pick(roleStyle?.fontSize, colStyle?.fontSize),
        fontFamily: pick(roleStyle?.fontFamily, colStyle?.fontFamily),
        textStrokeColor: pick(roleStyle?.textStrokeColor, colStyle?.textStrokeColor),
        textStrokeWidth: pick(roleStyle?.textStrokeWidth, colStyle?.textStrokeWidth),
        leftAccent: roleStyle?.leftAccent || colStyle?.leftAccent || false,
        underline: roleStyle?.underline || colStyle?.underline || false,
        accentColor: pick(roleStyle?.accentColor, colStyle?.accentColor),
      };
    };
    const resolveScopedOverride = (colStyle, roleStyle) => {
      const read = (key, fallback = '') => (
        roleStyle && Object.prototype.hasOwnProperty.call(roleStyle, key)
          ? roleStyle[key]
          : (colStyle?.[key] ?? fallback)
      );
      return {
        bgColor: read('bgColor'),
        textColor: read('textColor'),
        fontWeight: read('fontWeight'),
        fontStyle: read('fontStyle'),
        fontSize: read('fontSize'),
        fontFamily: read('fontFamily'),
        textStrokeColor: read('textStrokeColor'),
        textStrokeWidth: read('textStrokeWidth'),
        leftAccent: !!read('leftAccent', false),
        underline: !!read('underline', false),
        accentColor: read('accentColor'),
      };
    };
    // 背景未設定時はページ背景色にフォールバック（行のhover/focusグレーが透けるのを防止）
    const pageBg = 'var(--sn2-page-bg, var(--content-bg, var(--bg)))';
    const baseTextColor = 'var(--sn2-base-text-color, var(--fg))';
    const setStyle = (el, s, keepAlign) => {
      const align = keepAlign ? el.style.textAlign : '';
      el.style.background = s.bgColor || pageBg;
      el.style.color = s.textColor || baseTextColor;
      el.style.fontWeight = s.fontWeight === 'bold' ? 'bold' : '';
      el.style.fontStyle = s.fontStyle === 'italic' ? 'italic' : '';
      el.style.fontSize = s.fontSize ? s.fontSize + 'px' : '';
      el.style.fontFamily = s.fontFamily || '';
      const accentColor = s.accentColor || s.textColor || 'var(--accent)';
      el.style.webkitTextStrokeColor = s.textStrokeColor || '';
      el.style.webkitTextStrokeWidth = s.textStrokeWidth ? s.textStrokeWidth + 'px' : '';
      el.style.paintOrder = (s.textStrokeColor || s.textStrokeWidth) ? 'stroke fill' : '';
      el.style.boxShadow = s.leftAccent ? `inset 3px 0 0 ${accentColor}` : '';
      el.style.textDecorationLine = s.underline ? 'underline' : '';
      el.style.textDecorationColor = s.underline ? accentColor : '';
      if (align) el.style.textAlign = align;
    };
    // ガターのスタイル適用ヘルパー
    const applyGutterStyle = (el, colStyleKey) => {
      if (!el) return;
      // 表示タブの全体設定を既定値とし、タイプのオプション設定を優先上書きする。
      const roleGutter = colStyleKey === '_gutter2' ? chara?.gutter2Style : chara?.gutterStyle;
      const r = resolveScopedOverride(colStyles[colStyleKey], roleGutter);
      const ccBg = el.dataset.ccBg || '';
      const ccColor = el.dataset.ccColor || '';
      const ccWeight = el.dataset.ccWeight || '';
      const ccSize = el.dataset.ccSize || '';
      const align = el.style.textAlign;
      el.style.background = ccBg || r.bgColor || pageBg;
      el.style.color = ccColor || r.textColor || baseTextColor;
      el.style.fontWeight = ccWeight || (r.fontWeight === 'bold' ? 'bold' : '');
      el.style.fontStyle = r.fontStyle === 'italic' ? 'italic' : '';
      el.style.fontSize = ccSize ? ccSize + 'px' : (r.fontSize ? r.fontSize + 'px' : '');
      el.style.fontFamily = r.fontFamily || '';
      const accentColor = r.accentColor || r.textColor || 'var(--accent)';
      el.style.webkitTextStrokeColor = r.textStrokeColor || '';
      el.style.webkitTextStrokeWidth = r.textStrokeWidth ? r.textStrokeWidth + 'px' : '';
      el.style.paintOrder = (r.textStrokeColor || r.textStrokeWidth) ? 'stroke fill' : '';
      el.style.boxShadow = r.leftAccent ? `inset 3px 0 0 ${accentColor}` : '';
      el.style.textDecorationLine = r.underline ? 'underline' : '';
      el.style.textDecorationColor = r.underline ? accentColor : '';
      if (align) el.style.textAlign = align;
    };
    // 配置・折返の適用: タイプ管理の列別スタイル（textAlign/textValign/textOverflow）を優先し、
    // 未設定（自動）なら列ヘッダーメニューの列設定（align/valign/overflow）へフォールバックする
    const stdColSettings = this.doc.editor?.standardColumnSettings || {};
    const customColDefs = this.doc.editor?.customColumns || [];
    const alignmentColSettings = (colId) => (
      colId.startsWith('_') ? (stdColSettings[colId] || {}) : (customColDefs.find(c => c.id === colId) || {})
    );
    const applyCellAlignment = (el, roleStyle, colId, opts = {}) => {
      if (!el) return;
      const colSet = alignmentColSettings(colId);
      const align = roleStyle?.textAlign || colSet.align || '';
      const valign = roleStyle?.textValign || colSet.valign || '';
      const overflow = roleStyle?.textOverflow || colSet.overflow || '';
      el.style.textAlign = align;
      if (opts.alignDataset) {
        if (align) el.dataset.align = align; else delete el.dataset.align;
      }
      if (valign) el.dataset.valign = valign; else delete el.dataset.valign;
      const overflowEl = 'overflowEl' in opts ? opts.overflowEl : el;
      if (overflowEl) {
        if (overflow) overflowEl.dataset.overflow = overflow; else delete overflowEl.dataset.overflow;
      }
    };
    // 行背景は設定しない（ハンドル列はCSS側でページ背景色を使う）
    rowEl.style.background = '';
    // ガター列（大区切り）
    applyGutterStyle(gutterEl, '_gutter');
    applyCellAlignment(gutterEl, chara?.gutterStyle, '_gutter');
    // ガター2列（小区切り）
    applyGutterStyle(gutter2El, '_gutter2');
    applyCellAlignment(gutter2El, chara?.gutter2Style, '_gutter2');
    // タイプ列
    if (roleBtn) {
      const ecRole = this._resolveCharaColors(chara, '_role');
      const rs = chara?.roleStyle || {};
      const roleRole = { bgColor: rs.bgColor || ecRole.bgColor, textColor: rs.textColor || ecRole.textColor, fontWeight: rs.fontWeight, fontStyle: rs.fontStyle, fontSize: rs.fontSize, fontFamily: rs.fontFamily, textStrokeColor: rs.textStrokeColor, textStrokeWidth: rs.textStrokeWidth, leftAccent: rs.leftAccent, underline: rs.underline, accentColor: rs.accentColor || chara?.accentColor };
      setStyle(roleBtn, resolve(colStyles._role, roleRole), true);
      applyCellAlignment(roleBtn, rs, '_role');
    }
    // テキスト列
    if (textEl) {
      const ecText = this._resolveCharaColors(chara, '_text');
      const ts = chara?.textStyle || {};
      const roleText = { bgColor: ts.bgColor || ecText.bgColor, textColor: ts.textColor || ecText.textColor, fontWeight: ts.fontWeight || chara?.fontWeight, fontStyle: ts.fontStyle || chara?.fontStyle, fontSize: ts.fontSize || chara?.fontSize, fontFamily: ts.fontFamily || chara?.fontFamily, textStrokeColor: ts.textStrokeColor || chara?.textStrokeColor, textStrokeWidth: ts.textStrokeWidth || chara?.textStrokeWidth, leftAccent: ts.leftAccent, underline: ts.underline, accentColor: ts.accentColor || chara?.accentColor };
      setStyle(textEl, resolve(colStyles._text, roleText), false);
      textEl.style.paddingLeft = '';
      textEl.style.paddingTop = '';
      if (chara?.indent) {
        const indVal = String(chara.indent).trim();
        const cssVal = /^\d+(\.\d+)?$/.test(indVal) ? indVal + 'em' : indVal;
        const isVert = this.doc.editor?.viewMode === 'vertical';
        if (isVert) textEl.style.paddingTop = cssVal;
        else textEl.style.paddingLeft = cssVal;
      }
      // textStyle を優先、chara レベルにフォールバック（?? で空文字は有効値として扱う）
      const effBefore = ts.textBefore ?? chara?.textBefore;
      if (effBefore) textEl.dataset.before = effBefore; else delete textEl.dataset.before;
      const effAfter = ts.textAfter ?? chara?.textAfter;
      if (effAfter) textEl.dataset.after = effAfter; else delete textEl.dataset.after;
      // タイプ固有の配置・折り返し（textStyle優先、なければcharaレベル。?? で空文字=明示リセットを尊重）
      // タイプ側が未設定（自動）の場合は列ヘッダーメニューの列設定を消さずにフォールバックする
      const textColSet = alignmentColSettings('_text');
      const effAlign = (ts.textAlign ?? chara?.textAlign) || textColSet.align;
      if (effAlign) textEl.dataset.align = effAlign; else delete textEl.dataset.align;
      const effValign = (ts.textValign ?? chara?.textValign) || textColSet.valign;
      if (effValign) textEl.dataset.valign = effValign; else delete textEl.dataset.valign;
      const effOverflow = (ts.textOverflow ?? chara?.textOverflow) || textColSet.overflow;
      if (effOverflow) textEl.dataset.overflow = effOverflow; else delete textEl.dataset.overflow;
      // テキスト位置オフセット（1列 = 隣接セルの設定幅）
      // 横書き: translateX、縦書き: translateY で描画位置だけをずらす（レイアウト・枠線位置は固定）
      if (chara?.textShiftDir && chara?.textShiftCols) {
        const isVert = this.doc.editor?.viewMode === 'vertical';
        const cols = Number(chara.textShiftCols) || 1;
        const hideCell = (el) => { el.style.visibility = 'hidden'; el.style.background = pageBg; el.style.borderColor = 'transparent'; };
        const cw = this.doc.editor?.columnWidths || {};
        const defaultWidths = { _gutter: 40, _gutter2: 48, _role: 88, _status: 92 };
        const getColW = (colId) => cw[colId] || defaultWidths[colId] || 80;
        let totalPx = 0;
        if (chara.textShiftDir === 'after') {
          const customCells = [...rowEl.querySelectorAll('.sn2-custom-cell')];
          for (let j = 0; j < cols && j < customCells.length; j++) {
            totalPx += getColW(customCells[j].dataset.colId);
            hideCell(customCells[j]);
          }
          // 後にずらす: 横書き=右、縦書き=下
          textEl.style.transform = isVert ? `translateY(${totalPx}px)` : `translateX(${totalPx}px)`;
        } else {
          const leftCells = [
            { el: statusBtn, id: '_status' },
            { el: roleBtn, id: '_role' },
            { el: gutter2El, id: '_gutter2' },
            { el: gutterEl, id: '_gutter' },
          ].filter(c => c.el);
          for (let j = 0; j < cols && j < leftCells.length; j++) {
            totalPx += getColW(leftCells[j].id);
            hideCell(leftCells[j].el);
          }
          if (isVert) {
            // 縦書き: 高さ拡張+translateY+負マージンで下端レイアウトを維持
            textEl.style.setProperty('height', `calc(100% + ${totalPx}px)`, 'important');
            textEl.style.marginBottom = -totalPx + 'px';
            textEl.style.transform = `translateY(-${totalPx}px)`;
          } else {
            // 横書き: 幅拡張+translateX+負マージンで右端レイアウトを維持
            textEl.style.width = `calc(var(--sn2-col-_text, 300px) + ${totalPx}px)`;
            textEl.style.marginRight = -totalPx + 'px';
            textEl.style.transform = `translateX(-${totalPx}px)`;
          }
        }
        textEl.style.marginLeft = '';
      } else {
        textEl.style.transform = '';
        textEl.style.width = '';
        textEl.style.height = '';
        textEl.style.marginLeft = '';
        textEl.style.marginRight = '';
        textEl.style.marginBottom = '';
        // シフト解除時に復元
        [...rowEl.querySelectorAll('.sn2-custom-cell')].forEach(cell => { cell.style.visibility = ''; cell.style.borderColor = ''; });
        if (roleBtn) { roleBtn.style.visibility = ''; roleBtn.style.borderColor = ''; }
        if (gutter2El) { gutter2El.style.visibility = ''; gutter2El.style.borderColor = ''; }
        if (gutterEl) { gutterEl.style.visibility = ''; gutterEl.style.borderColor = ''; }
      }
    }
    if (statusBtn && rowData && typeof this._renderRowStatusButton === 'function') {
      this._renderRowStatusButton(statusBtn, rowData);
    }
    // カスタム列（textShiftで非表示にされたセルはスキップ）
    rowEl.querySelectorAll('.sn2-custom-cell').forEach(cell => {
      if (cell.style.visibility === 'hidden') return;
      const colId = cell.dataset.colId;
      const cs = colStyles[colId] || {};
      const ecCustom = this._resolveCharaColors(chara, colId);
      const rs = chara?.customStyles?.[colId] || {};
      const roleCustom = {
        bgColor: rs.bgColor || ecCustom.bgColor,
        textColor: rs.textColor || ecCustom.textColor,
        fontWeight: rs.fontWeight,
        fontStyle: rs.fontStyle,
        fontSize: rs.fontSize,
        fontFamily: rs.fontFamily,
        textStrokeColor: rs.textStrokeColor,
        textStrokeWidth: rs.textStrokeWidth,
        leftAccent: rs.leftAccent,
        underline: rs.underline,
        accentColor: rs.accentColor,
      };
      const r = resolve(cs, roleCustom);
      cell.style.background = r.bgColor || '';
      cell.style.color = r.textColor || '';
      cell.style.fontWeight = r.fontWeight === 'bold' ? 'bold' : '';
      cell.style.fontStyle = r.fontStyle === 'italic' ? 'italic' : '';
      cell.style.fontSize = r.fontSize ? r.fontSize + 'px' : '';
      cell.style.fontFamily = r.fontFamily || '';
      const accentColor = r.accentColor || r.textColor || 'var(--accent)';
      cell.style.webkitTextStrokeColor = r.textStrokeColor || '';
      cell.style.webkitTextStrokeWidth = r.textStrokeWidth ? r.textStrokeWidth + 'px' : '';
      cell.style.paintOrder = (r.textStrokeColor || r.textStrokeWidth) ? 'stroke fill' : '';
      cell.style.boxShadow = r.leftAccent ? `inset 3px 0 0 ${accentColor}` : '';
      cell.style.textDecorationLine = r.underline ? 'underline' : '';
      cell.style.textDecorationColor = r.underline ? accentColor : '';
      applyCellAlignment(cell, rs, colId, { alignDataset: true, overflowEl: cell.querySelector('.sn2-custom-text') });
    });
  }

  // 列間枠線: どの列の右側に線を引くかのSetを返す
  _getColumnBorderSet() {
    const cb = this.doc.editor?.columnBorders;
    if (!cb) return new Set();
    // 新形式: 配列 ['_gutter', '_role', ...]
    if (Array.isArray(cb)) return new Set(cb);
    // 旧形式: 文字列を変換
    if (cb === 'gutter-role') return new Set(['_gutter']);
    if (cb === 'role-text') return new Set(['_role']);
    if (cb === 'all-cols') {
      const s = new Set(['_gutter', '_gutter2', '_role', '_text']);
      if (this.doc.editor?.statusEnabled) s.add('_status');
      (this.doc.editor?.customColumns || []).forEach(c => s.add(c.id));
      return s;
    }
    return new Set();
  }

  // === レンダリング ===

  _teardownWrapResizeObserver() {
    if (this._wrapResizeObserver) {
      this._wrapResizeObserver.disconnect();
      this._wrapResizeObserver = null;
    }
    if (this._wrapResizeWindowHandler) {
      window.removeEventListener('resize', this._wrapResizeWindowHandler);
      this._wrapResizeWindowHandler = null;
    }
    if (this._wrapResizeInterval != null) {
      clearInterval(this._wrapResizeInterval);
      this._wrapResizeInterval = null;
    }
    if (this._wrapResizeRaf != null) {
      cancelAnimationFrame(this._wrapResizeRaf);
      this._wrapResizeRaf = null;
    }
    if (this._wrapResizeTimer != null) {
      clearTimeout(this._wrapResizeTimer);
      this._wrapResizeTimer = null;
    }
    this._wrapResizeLastSize = 0;
  }

  _setupWrapResizeObserver(scroll, viewMode, wrapMode) {
    this._teardownWrapResizeObserver();
    if (!scroll || !wrapMode) return;
    const isVertical = viewMode === 'vertical';
    const readSize = () => {
      if (!scroll.isConnected) return 0;
      const rect = scroll.getBoundingClientRect();
      const size = isVertical ? rect.width : rect.height;
      return Number.isFinite(size) ? Math.round(size) : 0;
    };
    let lastSize = readSize();
    this._wrapResizeLastSize = lastSize;
    const scheduleRender = () => {
      if (this._wrapResizeTimer != null) return;
      this._wrapResizeTimer = setTimeout(() => {
        this._wrapResizeTimer = null;
        if (!this.host || !this.doc || !scroll.isConnected || !this.host.contains(scroll)) return;
        const state = this.doc.editor || {};
        const currentMode = state.viewMode || 'horizontal';
        if (!state.wrapMode || currentMode !== viewMode) return;
        this._render();
      }, 0);
    };
    const checkSize = () => {
      const nextSize = readSize();
      if (nextSize <= 0 || Math.abs(nextSize - lastSize) < 2) return;
      lastSize = nextSize;
      this._wrapResizeLastSize = nextSize;
      scheduleRender();
    };
    if (typeof ResizeObserver === 'function') {
      this._wrapResizeObserver = new ResizeObserver(checkSize);
      this._wrapResizeObserver.observe(scroll);
      if (this.host && this.host !== scroll) this._wrapResizeObserver.observe(this.host);
      const root = this.host?.closest?.('.gb-scriptnote-root');
      if (root && root !== this.host && root !== scroll) this._wrapResizeObserver.observe(root);
      requestAnimationFrame(checkSize);
    } else {
      this._wrapResizeWindowHandler = checkSize;
      window.addEventListener('resize', this._wrapResizeWindowHandler);
    }
    this._wrapResizeInterval = setInterval(checkSize, 180);
  }

  _getCustomColumns() {
    return Array.isArray(this.doc.editor?.customColumns) ? this.doc.editor.customColumns : [];
  }

  _render() {
    if (!this.host || !this.doc) return;
    this._teardownWrapResizeObserver();
    if (typeof this._sanitizeRowSelection === 'function') this._sanitizeRowSelection();
    // フロートバーを除去（document.body上にあるため host.innerHTML='' では消えない）
    document.querySelectorAll('.sn2-row-bulk-bar').forEach(el => el.remove());
    // スクロール位置を保存（DOM再構築で失われるため）
    const prevScroll = this.host.querySelector('.sn2-scroll');
    const savedScrollTop = prevScroll ? prevScroll.scrollTop : 0;
    const savedScrollLeft = prevScroll ? prevScroll.scrollLeft : 0;
    this._calcCache = null;
    const calc = this._calcPagePanel();
    const viewMode = this.doc.editor?.viewMode || 'horizontal';
    const statusEnabled = !!this.doc.editor?.statusEnabled;
    const wrapMode = !!this.doc.editor?.wrapMode;
    const customCols = this._getCustomColumns();
    const colWidths = this.doc.editor?.columnWidths || {};

    const scroll = document.createElement('div');
    scroll.className = 'sn2-scroll' + (viewMode === 'vertical' ? ' sn2-vertical' : '') + (wrapMode ? ' sn2-wrap' : '');
    if (this.doc.editor?.pageBreakSpacing === false) scroll.classList.add('sn2-no-page-break-spacing');
    // 余白
    const marginRaw = this.doc.editor?.margin || '';
    const marginVal = marginRaw ? (/^\d+$/.test(marginRaw) ? marginRaw + 'px' : marginRaw) : '';
    if (marginVal) scroll.style.setProperty('--sn2-margin', marginVal);
    // 段間隔（折り返しの段と段の間。未指定なら余白と同じ）
    const wrapGapRaw = String(this.doc.editor?.wrapGap ?? '').trim();
    const wrapGapVal = wrapGapRaw ? (/^\d+$/.test(wrapGapRaw) ? wrapGapRaw + 'px' : wrapGapRaw) : '';
    if (wrapGapVal) scroll.style.setProperty('--sn2-wrap-gap', wrapGapVal);
    const editor = document.createElement('div');
    editor.className = 'sn2-editor';
    // 縦書き時のテキスト行数制限
    if (viewMode === 'vertical') {
      const vLines = this.doc.editor?.textWidth || 20;
      editor.style.setProperty('--sn2-vtext-lines', String(vLines));
    }
    // 段組み幅: ヘッダーの幅を基準にする（レンダリング後に測定）
    if (wrapMode && viewMode !== 'vertical') {
      // 一旦仮の値で設定、レンダリング後にヘッダーの実幅で更新
      const estWidth = (colWidths._handle || 20) + (colWidths._gutter || 40) + (colWidths._gutter2 || 48)
        + (colWidths._role || 88) + (statusEnabled ? (colWidths._status || 92) : 0)
        + (colWidths._text || 300) + customCols.reduce((s, c) => s + (colWidths[c.id] || c.width || 80), 0);
      editor.style.setProperty('--sn2-column-width', estWidth + 'px');
    }
    editor.dataset.border = this.doc.editor?.borderMode || 'all';
    editor.style.setProperty('--sn2-border-color', this.doc.editor?.borderColor || 'var(--border)');
    { const bw = String(this.doc.editor?.borderWidth || '1px');
      editor.style.setProperty('--sn2-border-width', /^\d+(\.\d+)?$/.test(bw) ? bw + 'px' : bw);
    }
    if (this.doc.editor?.themeId && typeof MeldexThemeManager !== 'undefined' && typeof MeldexThemeManager.getThemeById === 'function') {
      const themeVars = MeldexThemeManager.getThemeById(this.doc.editor.themeId)?.ui?.cssVars || {};
      [this.host, scroll, editor].forEach(target => {
        if (!target) return;
        Object.entries(themeVars).forEach(([key, value]) => {
          if (typeof COMMON_THEME_SURFACE_STYLE_KEYS !== 'undefined' && COMMON_THEME_SURFACE_STYLE_KEYS.has(key)) return;
          if (key.startsWith('--')) target.style.setProperty(key, value);
        });
      });
    }
    // テーマ設定
    if (this.doc.editor?.hoverBgColor) editor.style.setProperty('--sn2-hover-bg', this.doc.editor.hoverBgColor);
    if (this.doc.editor?.dropIndicatorColor) editor.style.setProperty('--sn2-drop-color', this.doc.editor.dropIndicatorColor);
    if (this.doc.editor?.spreadBorderColor) editor.style.setProperty('--sn2-spread-border-color', this.doc.editor.spreadBorderColor);
    if (this.doc.editor?.caretColor) editor.style.setProperty('--sn2-caret-color', this.doc.editor.caretColor);
    if (this.doc.editor?.dragSelectColor) editor.style.setProperty('--sn2-drag-select-color', this.doc.editor.dragSelectColor);
    if (this.doc.editor?.selectionColor) scroll.style.setProperty('--sn2-selection-color', this.doc.editor.selectionColor);
    if (this.doc.editor?.selectionTextColor) scroll.style.setProperty('--sn2-selection-fg', this.doc.editor.selectionTextColor);
    if (this.doc.editor?.caretWidth) {
      const cw = String(this.doc.editor.caretWidth);
      editor.style.setProperty('--sn2-caret-width', /^\d+(\.\d+)?$/.test(cw) ? cw + 'px' : cw);
    }
    if (this.doc.editor?.spreadBorderWidth) {
      const sbw = String(this.doc.editor.spreadBorderWidth);
      editor.style.setProperty('--sn2-spread-border-width', /^\d+(\.\d+)?$/.test(sbw) ? sbw + 'px' : sbw);
    }
    if (this.doc.editor?.dropIndicatorWidth) {
      const dw = String(this.doc.editor.dropIndicatorWidth);
      editor.style.setProperty('--sn2-drop-width', /^\d+(\.\d+)?$/.test(dw) ? dw + 'px' : dw);
    }
    // 基本テキスト設定
    if (this.doc.editor?.baseTextColor) scroll.style.setProperty('--sn2-base-text-color', this.doc.editor.baseTextColor);
    if (this.doc.editor?.baseTextFontFamily) scroll.style.setProperty('--sn2-base-text-font-family', this.doc.editor.baseTextFontFamily);
    if (this.doc.editor?.baseTextBold) scroll.style.setProperty('--sn2-base-text-bold', this.doc.editor.baseTextBold);
    if (this.doc.editor?.baseTextItalic) scroll.style.setProperty('--sn2-base-text-italic', this.doc.editor.baseTextItalic);
    if (this.doc.editor?.baseTextFontSize) scroll.style.setProperty('--sn2-base-text-font-size', this.doc.editor.baseTextFontSize + 'px');
    const lineHeight = viewMode === 'vertical'
      ? (this.doc.editor?.baseTextLineHeightV ?? this.doc.editor?.baseTextLineHeightH ?? this.doc.editor?.baseTextLineHeight)
      : (this.doc.editor?.baseTextLineHeightH ?? this.doc.editor?.baseTextLineHeightV ?? this.doc.editor?.baseTextLineHeight);
    if (lineHeight != null && lineHeight !== '') {
      scroll.style.setProperty('--sn2-base-text-line-height', String(lineHeight));
    }
    const letterSpacing = viewMode === 'vertical'
      ? (this.doc.editor?.baseTextLetterSpacingV ?? this.doc.editor?.baseTextLetterSpacingH ?? this.doc.editor?.baseTextLetterSpacing)
      : (this.doc.editor?.baseTextLetterSpacingH ?? this.doc.editor?.baseTextLetterSpacingV ?? this.doc.editor?.baseTextLetterSpacing);
    if (letterSpacing != null && letterSpacing !== '') {
      const ls = String(letterSpacing);
      scroll.style.setProperty('--sn2-base-text-letter-spacing', /^-?\d+(\.\d+)?$/.test(ls) ? ls + 'em' : ls);
    }
    // ルビ設定（3つの設定入口で共有するRubyPresentationを一度だけ適用）
    if (typeof MeldexRubyPresentation !== 'undefined') MeldexRubyPresentation.applyToEditor(this, scroll);
    else {
      if (this.doc.editor?.rubyFontSize) scroll.style.setProperty('--sn2-ruby-size', this.doc.editor.rubyFontSize + 'em');
      if (this.doc.editor?.rubyOffset != null) scroll.style.setProperty('--sn2-ruby-offset', this.doc.editor.rubyOffset + 'px');
    }

    // ヘッダー生成
    const textWidth = colWidths._text || 0;
    const colLabels = this.doc.editor?.columnLabels || {};
    const countDef = this._getCountDef();
    const defaultLabels = { _gutter: countDef.primaryLabel, _gutter2: countDef.secondaryLabel, _role: 'タイプ', _status: '採用状況', _text: 'テキスト' };
    const visCols = { _handle: true, _gutter: true, _gutter2: true, _role: true, _status: statusEnabled, _text: true, ...(this.doc.editor?.visibleStandardColumns || {}) };
    if (!statusEnabled) visCols._status = false;
    const allStdCols = [
      { id: '_handle', label: '', width: colWidths._handle || 36 },
      { id: '_gutter', label: colLabels._gutter || defaultLabels._gutter, width: colWidths._gutter || 40 },
      { id: '_gutter2', label: colLabels._gutter2 || defaultLabels._gutter2, width: colWidths._gutter2 || 48 },
      { id: '_role', label: colLabels._role || defaultLabels._role, width: colWidths._role || 88 },
      { id: '_status', label: colLabels._status || defaultLabels._status, width: colWidths._status || 92 },
      { id: '_text', label: colLabels._text || defaultLabels._text, width: textWidth },
    ];
    const unsortedCols = [
      ...allStdCols.filter(c => visCols[c.id] !== false),
      ...customCols.map(c => ({ id: c.id, label: c.label || c.id, width: colWidths[c.id] || c.width || 80 })),
    ];
    // columnOrderで並べ替え（_handleは常に先頭）
    const colOrder = this.doc.editor?.columnOrder;
    const cols = colOrder ? (() => {
      const handleCol = unsortedCols.find(c => c.id === '_handle');
      const rest = unsortedCols.filter(c => c.id !== '_handle');
      rest.sort((a, b) => {
        const ai = colOrder.indexOf(a.id), bi = colOrder.indexOf(b.id);
        if (ai >= 0 && bi >= 0) return ai - bi;
        if (ai >= 0) return -1;
        if (bi >= 0) return 1;
        return 0;
      });
      return handleCol ? [handleCol, ...rest] : rest;
    })() : unsortedCols;
    const buildHeader = (withResizer = true, instanceKey = '') => {
      const h = document.createElement('div');
      h.className = 'sn2-header' + (viewMode === 'vertical' ? ' sn2-header-vertical' : '');
      const safeId = (value) => String(value || 'col').replace(/[^a-zA-Z0-9_-]/g, '-');
      const e2eSuffix = instanceKey ? `-${safeId(instanceKey)}` : '';
      const colLabel = (col) => String(col?.label || defaultLabels[col?.id] || '列').trim() || '列';
      cols.forEach((col, ci) => {
        // リサイザーをセルの前に配置（前のセルとの境界）
        if (withResizer && ci > 0 && cols[ci - 1].id !== '_handle') {
          const resizeCol = cols[ci - 1];
          const resizer = document.createElement('div');
          resizer.className = 'sn2-col-resizer';
          resizer.dataset.colId = resizeCol.id;
          resizer.dataset.e2eId = `sn2-col-resizer-${safeId(resizeCol.id)}${e2eSuffix}`;
          resizer.tabIndex = 0;
          resizer.setAttribute('role', 'separator');
          resizer.setAttribute('aria-orientation', viewMode === 'vertical' ? 'horizontal' : 'vertical');
          resizer.setAttribute('aria-label', `${colLabel(resizeCol)}列の幅を調整`);
          // ドラッグで前のセルのサイズを変える
          resizer.addEventListener('pointerdown', (e) => this._startColResize(e, resizeCol.id, resizer));
          resizer.addEventListener('keydown', (e) => this._handleColResizerKeydown?.(e, resizeCol.id));
          h.appendChild(resizer);
        }
        const cell = document.createElement('div');
        const isTextFlex = col.id === '_text' && !col.width;
        cell.className = 'sn2-header-cell' + (isTextFlex ? ' sn2-header-flex' : '');
        cell.textContent = col.label;
        cell.dataset.colId = col.id;
        cell.dataset.e2eId = `sn2-header-cell-${safeId(col.id)}${e2eSuffix}`;
        if (viewMode === 'vertical' && col.id !== '_handle') this._wrapTcy(cell);
        if (col.width) cell.style.width = viewMode === 'vertical' ? '' : `var(--sn2-col-${col.id}, ${col.width}px)`;
        // ヘッダーセルのD&D並べ替え（_handle以外）
        if (col.id !== '_handle') {
          cell.draggable = true;
          cell.addEventListener('dragstart', (ev) => {
            ev.dataTransfer.effectAllowed = 'move';
            ev.dataTransfer.setData('text/plain', col.id);
            cell.style.opacity = '0.4';
          });
          cell.addEventListener('dragend', () => { cell.style.opacity = ''; });
          cell.addEventListener('dragover', (ev) => { ev.preventDefault(); ev.dataTransfer.dropEffect = 'move'; cell.style.borderBottom = '2px solid var(--blue, #4a90d9)'; });
          cell.addEventListener('dragleave', () => { cell.style.borderBottom = ''; });
          cell.addEventListener('drop', (ev) => {
            ev.preventDefault();
            cell.style.borderBottom = '';
            const dragId = ev.dataTransfer.getData('text/plain');
            if (!dragId || dragId === col.id) return;
            const order = cols.filter(c => c.id !== '_handle').map(c => c.id);
            const fromIdx = order.indexOf(dragId);
            const toIdx = order.indexOf(col.id);
            if (fromIdx < 0 || toIdx < 0) return;
            order.splice(fromIdx, 1);
            order.splice(toIdx, 0, dragId);
            this._pushUndo('列順序変更');
            if (!this.doc.editor) this.doc.editor = {};
            this.doc.editor.columnOrder = order;
            this._render();
            this._markDirty();
          });
        }
        // ハンドル列ヘッダー: クリックで全選択/全解除メニュー
        if (col.id === '_handle') {
          cell.style.cursor = 'pointer';
          cell.tabIndex = 0;
          cell.setAttribute('role', 'button');
          cell.setAttribute('aria-label', '行選択メニュー');
          cell.setAttribute('aria-haspopup', 'menu');
          cell.setAttribute('aria-expanded', 'false');
          cell.dataset.e2eId = 'sn2-header-select-menu-trigger' + e2eSuffix;
          const openSelectMenu = (ev) => {
            ev.stopPropagation();
            document.querySelectorAll('.sn2-header-popup').forEach(el => el.remove());
            document.querySelectorAll('[data-e2e-id^="sn2-header-select-menu-trigger"][aria-expanded="true"]').forEach(el => {
              el.setAttribute('aria-expanded', 'false');
            });
            const popup = document.createElement('div');
            popup.id = `sn2-header-select-menu-${Date.now()}`;
            popup.className = 'sn2-header-popup sn2-header-select-popup';
            popup.dataset.e2eId = 'sn2-header-select-menu';
            popup.setAttribute('role', 'menu');
            popup.setAttribute('aria-label', '行選択メニュー');
            let closeHandler = null;
            let escapeHandler = null;
            const closePopup = (restoreFocus = false) => {
              popup.remove();
              cell.setAttribute('aria-expanded', 'false');
              if (closeHandler) {
                document.removeEventListener('pointerdown', closeHandler, true);
                closeHandler = null;
              }
              if (escapeHandler) {
                document.removeEventListener('keydown', escapeHandler, true);
                escapeHandler = null;
              }
              if (restoreFocus) cell.focus();
            };
            const mkBtn = (text, actionId, fn) => {
              const b = document.createElement('button');
              b.className = 'sn2-header-popup-item'; b.type = 'button'; b.textContent = text;
              b.dataset.e2eId = `sn2-header-select-menu-${actionId}`;
              b.setAttribute('role', 'menuitem');
              b.addEventListener('click', () => { closePopup(false); fn(); });
              return b;
            };
            popup.appendChild(mkBtn('全選択', 'select-all', () => this._selectAllRows()));
            popup.appendChild(mkBtn('全選択解除', 'clear', () => this._clearRowSelection()));
            popup.style.cssText = 'position:fixed;z-index:10000;';
            document.body.appendChild(popup);
            cell.setAttribute('aria-expanded', 'true');
            cell.setAttribute('aria-controls', popup.id);
            positionPopup(popup, cell.getBoundingClientRect());
            if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
            closeHandler = (e) => {
              if (!popup.contains(e.target) && e.target !== cell) closePopup(false);
            };
            escapeHandler = (e) => {
              if (e.key !== 'Escape') return;
              e.preventDefault();
              e.stopPropagation();
              closePopup(true);
            };
            document.addEventListener('keydown', escapeHandler, true);
            requestAnimationFrame(() => popup.querySelector('.sn2-header-popup-item')?.focus());
            setTimeout(() => {
              if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
            }, 0);
          };
          cell.addEventListener('click', openSelectMenu);
          cell.addEventListener('keydown', (ev) => {
            if (ev.key !== 'Enter' && ev.key !== ' ') return;
            ev.preventDefault();
            openSelectMenu(ev);
          });
        }
        // ヘッダーセルのイベント（_handle以外、段ヘッダーでもメニュー表示可）
        if (col.id !== '_handle') {
          let clickTimer = null;
          cell.tabIndex = 0;
          cell.setAttribute('role', 'button');
          cell.setAttribute('aria-haspopup', 'menu');
          cell.setAttribute('aria-expanded', 'false');
          cell.setAttribute('aria-label', `${colLabel(col)}列メニュー`);
          cell.addEventListener('click', (ev) => {
            ev.stopPropagation();
            if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; return; }
            clickTimer = setTimeout(() => { clickTimer = null; this._showHeaderMenu(cell, col.id); }, 250);
          });
          cell.addEventListener('keydown', (ev) => {
            if (ev.key !== 'Enter' && ev.key !== ' ') return;
            ev.preventDefault();
            if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; }
            this._showHeaderMenu(cell, col.id);
          });
          cell.addEventListener('dblclick', (ev) => {
            ev.stopPropagation();
            if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; }
            // メニューが開いていたら閉じる
            document.querySelectorAll('.sn2-header-popup, .sn2-header-sub-popup').forEach(el => el.remove());
            this._startHeaderLabelEdit(cell, col.id);
          });
          cell.style.cursor = 'pointer';
        }
        h.appendChild(cell);
      });
      // 最後のセル（テキスト or カスタム列）の下端/右端のリサイザー
      if (withResizer && cols.length > 0) {
        const lastCol = cols[cols.length - 1];
        const resizer = document.createElement('div');
        resizer.className = 'sn2-col-resizer';
        resizer.dataset.colId = lastCol.id;
        resizer.dataset.e2eId = `sn2-col-resizer-${safeId(lastCol.id)}${e2eSuffix}`;
        resizer.tabIndex = 0;
        resizer.setAttribute('role', 'separator');
        resizer.setAttribute('aria-orientation', viewMode === 'vertical' ? 'horizontal' : 'vertical');
        resizer.setAttribute('aria-label', `${colLabel(lastCol)}列の幅を調整`);
        resizer.addEventListener('pointerdown', (e) => this._startColResize(e, lastCol.id, resizer));
        resizer.addEventListener('keydown', (e) => this._handleColResizerKeydown?.(e, lastCol.id));
        h.appendChild(resizer);
      }
      // スペーサー（ヘッダーの残り領域をページ背景色に）
      const spacer = document.createElement('div');
      spacer.className = 'sn2-header-spacer';
      h.appendChild(spacer);
      return h;
    };
    const header = buildHeader(true);

    // CSS変数で列幅/高さを設定
    const setColVars = (el) => {
      cols.forEach(col => {
        if (col.width) {
          el.style.setProperty(`--sn2-col-${col.id}`, col.width + 'px');
          if (viewMode === 'vertical') el.style.setProperty(`--sn2-vcol-${col.id}`, col.width + 'px');
        }
      });
      if (textWidth > 0) el.style.setProperty('--sn2-text-flex', '0 0 auto');
    };
    setColVars(scroll);
    setColVars(editor);

    // 全行を生成（フィルタ適用）
    const mergeDisplay = !!this.doc.editor?.mergeDisplay;
    const sb = this.doc.editor?.spreadBorder;
    const allRowEls = [];
    const allRowCalcs = []; // 見開き区切り判定用
    let prevVisibleRow = null;
    let prevVisibleCalc = null;
    for (let i = 0; i < this.doc.rows.length; i++) {
      // フィルタで非表示
      if (!this._isRoleVisible(this.doc.rows[i].role, this.doc.rows[i].status || '')) continue;
      const prevRow = prevVisibleRow;
      const prevCalc = prevVisibleCalc;
      const rowEl = this._buildRowEl(this.doc.rows[i], i, calc[i], mergeDisplay, prevRow, prevCalc, customCols, cols);
      allRowEls.push(rowEl);
      allRowCalcs.push(calc[i]);
      prevVisibleRow = this.doc.rows[i];
      prevVisibleCalc = calc[i];
    }
    // 見開き区切り線: 次ページ先頭行の手前に区切り属性を付与
    if (sb?.enabled && allRowEls.length > 0) {
      const sbStart = sb.start ?? 1;
      const sbEvery = sb.every ?? 2;
      if (sbEvery > 0) {
        for (let j = 0; j < allRowEls.length - 1; j++) {
          const pg = allRowCalcs[j]?.page;
          const nextPg = allRowCalcs[j + 1]?.page;
          if (pg != null && nextPg != null && pg !== nextPg && (pg - sbStart) % sbEvery === 0 && pg >= sbStart) {
            allRowEls[j + 1].dataset.spreadBorder = 'true';
          }
        }
      }
    }

    if (!wrapMode) {
      // === 折り返しOFF ===
      // scroll直下にヘッダー（sticky）、その後にeditor
      scroll.appendChild(header);
      allRowEls.forEach(el => editor.appendChild(el));
      scroll.appendChild(editor);
    } else {
      // === 折り返しON: JSで段を手動分割 ===
      // 一旦仮レンダリングして行の高さ/幅を測定
      // 縦書き時は仮レンダリングでも縦書きレイアウトにする
      if (viewMode === 'vertical') {
        editor.style.display = 'flex';
        editor.style.flexDirection = 'row-reverse';
        editor.style.alignItems = 'flex-start';
        editor.style.width = 'max-content';
      }
      allRowEls.forEach(el => editor.appendChild(el));
      scroll.appendChild(editor);
      this.host.innerHTML = '';
      this.host.appendChild(scroll);

      // 段の最大サイズ = scrollの高さ（横書き）or 幅（縦書き）
      // CSS zoom 下で offsetHeight/clientHeight がブラウザ間で不整合な値を返す
      // 問題を避けるため、getBoundingClientRect + _getZoom() で CSS ピクセルに
      // 正規化してから packing 計算する。
      const zPack = typeof _getZoom === 'function' ? _getZoom() : 1;
      const measureWrapViewportSize = () => {
        const rect = scroll.getBoundingClientRect();
        const rectSize = (viewMode === 'vertical' ? rect.width : rect.height) / zPack;
        const clientSize = viewMode === 'vertical' ? scroll.clientWidth : scroll.clientHeight;
        if (Number.isFinite(clientSize) && clientSize > 0) return Math.min(rectSize, clientSize);
        return rectSize;
      };
      const wrapFitGuard = 2;
      const maxSize = measureWrapViewportSize();
      let verticalMeasureHeader = null;
      if (viewMode === 'vertical') {
        verticalMeasureHeader = buildHeader(false, 'measure');
        verticalMeasureHeader.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;left:0;top:0;';
        scroll.appendChild(verticalMeasureHeader);
        const headerHeight = verticalMeasureHeader.getBoundingClientRect().height / zPack;
        if (headerHeight > 0) {
          allRowEls.forEach(el => { el.style.height = headerHeight + 'px'; });
        }
      }
      // ヘッダーサイズ: 縦書きではヘッダーの幅（行と同じ方向で場所を取る）
      // 仮測定ではなく、固定値を使う（ヘッダーの実幅は行のレイアウト確定後でないと正確に測れない）
      const headerSize = viewMode === 'vertical' ? 40 : 28;
      const availSize = Math.max(maxSize - headerSize - wrapFitGuard, 100);

      const applyVerticalWrapSizing = () => {
        if (viewMode !== 'vertical') return;
        const zV = typeof _getZoom === 'function' ? _getZoom() : 1;
        editor.querySelectorAll('.sn2-column-group').forEach(group => {
          const h = group.querySelector('.sn2-header');
          if (!h) return;
          const hH = h.getBoundingClientRect().height / zV;
          group.querySelectorAll('.sn2-row').forEach(r => {
            r.style.height = hH + 'px';
            const txt = r.querySelector('.sn2-text');
            if (txt) {
              const rW = r.getBoundingClientRect().width / zV;
              const scrollW = txt.scrollWidth;
              if (scrollW > rW) {
                r.style.minWidth = Math.ceil(scrollW) + 'px';
              }
            }
          });
        });
      };
      const rebuildWrapColumns = (columnsToBuild) => {
        while (editor.firstChild) editor.removeChild(editor.firstChild);
        columnsToBuild.forEach((colRows, groupIndex) => {
          const group = document.createElement('div');
          group.className = 'sn2-column-group';
          group.appendChild(buildHeader(false, groupIndex === 0 ? '' : `wrap-${groupIndex + 1}`));
          colRows.forEach(el => group.appendChild(el));
          editor.appendChild(group);
        });
        setColVars(editor);
      };
      const packWrapColumns = (sizes, availableSize) => {
        const packed = [[]];
        let current = 0;
        for (let i = 0; i < allRowEls.length; i++) {
          const rowSize = Math.max(1, Math.ceil(sizes[i] || 1));
          if (current + rowSize > availableSize && packed[packed.length - 1].length > 0) {
            packed.push([]);
            current = 0;
          }
          packed[packed.length - 1].push(allRowEls[i]);
          current += rowSize;
        }
        return packed;
      };
      const wrapColumnSignature = (columnsToCheck) => columnsToCheck
        .map(colRows => colRows.map(row => row.dataset.rowId || '').join(','))
        .join('|');
      const currentWrapColumnSignature = () => wrapColumnSignature([...editor.querySelectorAll('.sn2-column-group')]
        .map(group => [...group.querySelectorAll(':scope > .sn2-row')]));
      const measureWrapMargins = (el) => {
        const style = getComputedStyle(el);
        const before = parseFloat(viewMode === 'vertical' ? style.marginRight : style.marginTop) || 0;
        const after = parseFloat(viewMode === 'vertical' ? style.marginLeft : style.marginBottom) || 0;
        return { before, after, total: before + after };
      };
      const measureWrapOuterSize = (el) => {
        const rect = el.getBoundingClientRect();
        const margins = measureWrapMargins(el);
        const bodySize = (viewMode === 'vertical' ? rect.width : rect.height) / zPack;
        return Math.ceil(Math.max(bodySize + margins.total, 1));
      };
      const repackVerticalWrapFromFinalWidths = () => {
        if (viewMode !== 'vertical') return false;
        scroll.scrollLeft = 0;
        applyVerticalWrapSizing();
        return true;
      };
      const measureWrapOverflowAmounts = () => {
        const zV = typeof _getZoom === 'function' ? _getZoom() : 1;
        const currentScrollRect = scroll.getBoundingClientRect();
        if (viewMode === 'vertical') {
          const visibleRight = Math.min(
            currentScrollRect.right,
            currentScrollRect.left + (((scroll.clientWidth || currentScrollRect.width / zV) * zV))
          );
          return [...editor.querySelectorAll('.sn2-column-group > .sn2-row')].map(row => {
            const rect = row.getBoundingClientRect();
            return Math.max(0, currentScrollRect.left - rect.left, rect.right - visibleRight);
          }).filter(amount => amount > 1);
        }
        const visibleBottom = Math.min(
          currentScrollRect.bottom,
          currentScrollRect.top + (((scroll.clientHeight || currentScrollRect.height / zV) * zV))
        );
        return [...editor.querySelectorAll('.sn2-column-group > .sn2-row')].map(row => {
          const rect = row.getBoundingClientRect();
          return Math.max(0, currentScrollRect.top - rect.top, rect.bottom - visibleBottom);
        }).filter(amount => amount > 1);
      };
      const repackWrapFromFinalSizes = (force = false) => {
        if (viewMode === 'vertical') repackVerticalWrapFromFinalWidths();
        const overflowAmounts = measureWrapOverflowAmounts();
        if (!force && !overflowAmounts.length) return false;
        const zV = typeof _getZoom === 'function' ? _getZoom() : 1;
        const firstHeader = editor.querySelector('.sn2-column-group .sn2-header');
        const measuredHeaderSize = firstHeader
          ? (viewMode === 'vertical' ? firstHeader.getBoundingClientRect().width : firstHeader.getBoundingClientRect().height) / zV
          : headerSize;
        const currentMaxSize = measureWrapViewportSize();
        const baseAvailSize = Math.max(currentMaxSize - Math.ceil(measuredHeaderSize) - wrapFitGuard, 100);
        const finalRowSizes = allRowEls.map(measureWrapOuterSize);
        const packedColumns = packWrapColumns(finalRowSizes, baseAvailSize);
        const needsRebuild = overflowAmounts.length || currentWrapColumnSignature() !== wrapColumnSignature(packedColumns);
        if (!needsRebuild) return false;
        rebuildWrapColumns(packedColumns);
        if (viewMode === 'vertical') repackVerticalWrapFromFinalWidths();
        const remainingOverflow = measureWrapOverflowAmounts();
        if (remainingOverflow.length) {
          const overflowGuard = Math.ceil(Math.max(...remainingOverflow) / zV) + wrapFitGuard;
          const adjustedAvailSize = Math.max(baseAvailSize - overflowGuard, 100);
          if (adjustedAvailSize < baseAvailSize) {
            rebuildWrapColumns(packWrapColumns(finalRowSizes, adjustedAvailSize));
            if (viewMode === 'vertical') repackVerticalWrapFromFinalWidths();
          }
        }
        return true;
      };
      const resetVerticalWrapHorizontalPosition = () => {
        if (viewMode !== 'vertical') return;
        scroll.scrollLeft = 0;
      };
      const settleWrapPacking = (forceFirstPass = false) => {
        for (let pass = 0; pass < 4; pass += 1) {
          if (!repackWrapFromFinalSizes(forceFirstPass && pass === 0)) break;
        }
        resetVerticalWrapHorizontalPosition();
      };

      // 各行のサイズを測定（CSS ピクセルに正規化）
      const measureWrapRowSize = (el) => {
        let size = measureWrapOuterSize(el);
        if (viewMode === 'vertical') {
          // 縦書きは最終行高を先に適用してから実効幅を測る。
          // 行高未確定の scrollWidth を使うと長文方向の値になり、段が2行程度で折れる。
          const margins = measureWrapMargins(el);
          size = Math.max(size, (el.scrollWidth || 0) + margins.total);
          const txt = el.querySelector('.sn2-text');
          if (txt) {
            const textBodyWidth = txt.scrollWidth || 0;
            const textOuterWidth = textBodyWidth + margins.total;
            if (textOuterWidth > size) {
              el.style.minWidth = Math.ceil(textBodyWidth) + 'px';
              size = Math.max(textOuterWidth, measureWrapOuterSize(el));
            }
          }
        }
        return Math.ceil(Math.max(size, 1));
      };
      const rowSizes = allRowEls.map(measureWrapRowSize);

      // 段に分割
      const columns = packWrapColumns(rowSizes, availSize);

      // editorを再構築: 各段 = column-group div（ヘッダー + 行）
      // 子要素をdetach（参照を保持したまま除去）
      rebuildWrapColumns(columns);
      if (verticalMeasureHeader) verticalMeasureHeader.remove();
      // 仮レンダリング用のスタイルをリセット
      editor.style.removeProperty('display');
      editor.style.removeProperty('flex-direction');
      editor.style.removeProperty('align-items');
      editor.style.removeProperty('width');
      settleWrapPacking(true);
      this._bind();
      this._adjustRubySpacing();
      settleWrapPacking(true);
      // 縦書き折り返し: 各段のヘッダー高さを測定し行に適用 + テキスト幅拡張
      if (viewMode === 'vertical') {
        requestAnimationFrame(() => {
          settleWrapPacking(true);
        });
      }
      this._setupPanSpacer(scroll, editor, viewMode);
      // スクロール位置を復元
      scroll.scrollTop = savedScrollTop;
      scroll.scrollLeft = viewMode === 'vertical' ? 0 : savedScrollLeft;
      if (viewMode === 'vertical') resetVerticalWrapHorizontalPosition();
      // 折り返し表示でも行コメントバッジを通常表示と同じタイミングで再描画する
      if (this._path && typeof CommentBadges !== 'undefined') {
        try { CommentBadges.refreshScriptnote(this._path, this.host); } catch {}
      }
      this._setupWrapResizeObserver(scroll, viewMode, wrapMode);
      return;
    }

    this.host.innerHTML = '';
    this.host.appendChild(scroll);
    this._bind();
    this._adjustRubySpacing();
    // 縦書き: ヘッダーの高さを測定し行に適用（ヘッダーと行の下端を揃える）
    // + テキストが折り返して幅が必要な行はmin-widthを拡張
    if (viewMode === 'vertical') {
      requestAnimationFrame(() => {
        const h = scroll.querySelector('.sn2-header');
        if (!h) return;
        const zV = typeof _getZoom === 'function' ? _getZoom() : 1;
        const hH = h.getBoundingClientRect().height / zV;
        scroll.querySelectorAll('.sn2-row').forEach(r => {
          r.style.height = hH + 'px';
          const txt = r.querySelector('.sn2-text');
          if (txt) {
            const rW = r.getBoundingClientRect().width / zV;
            const scrollW = txt.scrollWidth;
            if (scrollW > rW) {
              r.style.minWidth = scrollW + 'px';
            }
          }
        });
      });
    }
    this._setupPanSpacer(scroll, editor, viewMode);
    // スクロール位置を復元
    scroll.scrollTop = savedScrollTop;
    scroll.scrollLeft = savedScrollLeft;
    // Phase 2e-ii: 行コメントバッジを描画
    if (this._path && typeof CommentBadges !== 'undefined') {
      try { CommentBadges.refreshScriptnote(this._path, this.host); } catch {}
    }
  }

  // 右ドラッグパン用の余白スペーサーを設置する。
  // editor の content box には一切影響しないよう、絶対配置で
  // editor の右下から +60vw, +60vh の位置に1pxの不可視要素を置く。
  // これによりスクロール領域だけが拡張される。
  // 縦書き行リバースモードでは editor の最終flex子として水平
  // スペーサーも追加し、視覚的な左方向にもパン可能にする。
  _setupPanSpacer(scroll, editor, viewMode) {
    if (!scroll || !editor) return;
    // 既存のスペーサーをすべて除去（再描画時の蓄積防止）
    scroll.querySelectorAll('.sn2-pan-spacer').forEach(el => el.remove());
    editor.querySelectorAll(':scope > .sn2-pan-spacer-inline').forEach(el => el.remove());
    // 縦書き row-reverse モード: 視覚的左方向の余白用の inline スペーサー
    const wrapMode = !!this.doc.editor?.wrapMode;
    if (viewMode === 'vertical' && !wrapMode) {
      const inline = document.createElement('div');
      inline.className = 'sn2-pan-spacer-inline';
      inline.style.cssText = 'flex-shrink:0;width:60vw;height:1px;pointer-events:none;background:transparent;';
      editor.appendChild(inline);
    }
    // 横書き折り返しモード: 表の右側にさらにパン余白を追加
    if (wrapMode && viewMode !== 'vertical') {
      const inline = document.createElement('div');
      inline.className = 'sn2-pan-spacer-inline';
      inline.style.cssText = 'flex-shrink:0;width:60vw;height:1px;pointer-events:none;background:transparent;';
      editor.appendChild(inline);
    }
    // 全モード共通: editor の右下に絶対配置スペーサー
    const absSpacer = document.createElement('div');
    absSpacer.className = 'sn2-pan-spacer';
    scroll.appendChild(absSpacer);
    // レイアウト確定後に位置を計算
    const place = () => {
      if (!editor.isConnected || !absSpacer.isConnected) return;
      const wPx = Math.round(window.innerWidth * 0.6);
      const hPx = Math.round(window.innerHeight * 0.6);
      const right = editor.offsetLeft + editor.offsetWidth;
      const bottom = editor.offsetTop + editor.offsetHeight;
      absSpacer.style.left = (right + wPx) + 'px';
      absSpacer.style.top = (bottom + hPx) + 'px';
    };
    requestAnimationFrame(() => {
      place();
      // 折り返しモードや縦書きモードでは2フレーム目に再計算（高さ調整後の位置を反映）
      requestAnimationFrame(place);
    });
  }

  _buildRowEl(row, idx, calc, mergeDisplay = false, prevRow = null, prevCalc = null, customCols = null, visibleCols = null) {
    if (!customCols) customCols = this._getCustomColumns();
    const el = document.createElement('div');
    el.className = 'sn2-row';
    el.dataset.rowId = row.id;
    // 枠線設定（タイプごとのオプション設定で制御）
    const effectiveRole = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(this.doc, row);
    const chara = effectiveRole?.style
      || (row.role
        ? this.doc.characters.find(c => !c.isDefault && c.name === row.role)
        : this.doc.characters.find(c => c.isDefault));
    // dataset.kind: 'blank' (空ロール), 'break' (区切り), 'summary' (プロット), 'action', 'heading', 'dialogue'
    let kind = 'dialogue';
    if (!row.role) kind = 'blank';
    else if (effectiveRole?.type?.isSummary || chara?.isSummary) kind = 'summary';
    else if (effectiveRole?.type?.isBreak || chara?.isBreak) kind = 'break';
    else {
      const resolvedKind = effectiveRole?.type?.kind || chara?.kind;
      if (['dialogue', 'action', 'heading'].includes(resolvedKind)) kind = resolvedKind;
    }
    el.dataset.kind = kind;
    const showOutline = !!chara?.outline;
    if (showOutline) {
      el.dataset.outline = 'true';
      // タイプ固有の枠線色・太さをCSS変数で設定
      if (chara?.outlineColor) el.style.setProperty('--sn2-outline-color', chara.outlineColor);
      if (chara?.outlineWidth) el.style.setProperty('--sn2-outline-width', chara.outlineWidth + 'px');
    }
    // まとめ表示: 前行と同じガター値やタイプ値なら非表示フラグ
    const mergeGutter = mergeDisplay && prevRow && calc && idx > 0;
    const mergeRole = mergeDisplay && prevRow && prevRow.role === row.role && row.role;
    const visCols = { _handle: true, _gutter: true, _gutter2: true, _role: true, _status: !!this.doc.editor?.statusEnabled, _text: true, ...(this.doc.editor?.visibleStandardColumns || {}) };
    if (!this.doc.editor?.statusEnabled) visCols._status = false;

    // 列間枠線: どの列の右側に枠線を表示するかを判定
    const colBorderSet = this._getColumnBorderSet();
    const appendCell = (colId, cell) => {
      if (!cell) return;
      cell.dataset.colId = colId;
      const gridKey = `${row.id}\u001f${colId}`;
      if (this._gridCellSelection?.has(gridKey)) cell.classList.add('sn2-grid-cell-selected');
      el.appendChild(cell);
    };

    // チェックボックス + ドラッグハンドル（ハンドルdiv内にチェックボックスを配置）
    if (visCols._handle !== false) {
      const rowId = row.id;
      const handle = document.createElement('div');
      handle.className = 'sn2-handle';
      // 注意: HTML5 draggable は使わない (ドラッグ中 wheel がブロックされるため)。
      // pointer events ベースの自前ドラッグ (_bind 内) で移動を実装する。
      // シナリオ上ではツールチップを出さない（title属性は付けない）
      handle.addEventListener('click', (ev) => {
        if (this._suppressRowCheckClick) {
          ev.preventDefault();
          ev.stopPropagation();
          return;
        }
        ev.stopPropagation();
        this._toggleRowSelection(rowId, idx, ev.shiftKey, ev.ctrlKey || ev.metaKey);
      });
      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.className = 'sn2-row-check';
      cb.dataset.e2eId = `sn-row-${rowId}-select`;
      cb.checked = this._rowSelection?.has(rowId) || false;
      cb.setAttribute('aria-label', `行を選択: ${idx + 1}`);
      cb.addEventListener('click', (ev) => {
        if (this._suppressRowCheckClick) {
          ev.preventDefault();
          ev.stopPropagation();
          return;
        }
        ev.stopPropagation();
        this._toggleRowSelection(rowId, idx, ev.shiftKey, ev.ctrlKey || ev.metaKey);
      });
      handle.appendChild(cb);
      const gripText = document.createElement('span');
      gripText.textContent = '⠿';
      gripText.style.cssText = 'pointer-events:none;';
      handle.appendChild(gripText);
      appendCell('_handle', handle);
    }

    // ガター（大区切り：ページ番号等）
    const gutter = visCols._gutter !== false ? document.createElement('div') : null;
    if (gutter) gutter.className = 'sn2-gutter';
    // ガター2（小区切り：コマ番号等）
    const gutter2 = visCols._gutter2 !== false ? document.createElement('div') : null;
    if (gutter2) gutter2.className = 'sn2-gutter sn2-gutter2';
    // 配置設定を取得するヘルパー
    const stdSettings = this.doc.editor?.standardColumnSettings || {};
    const getColSettings = (colId) => {
      if (colId.startsWith('_')) return stdSettings[colId] || {};
      const cd = customCols.find(c => c.id === colId);
      return cd || {};
    };
    const cc = this.doc.editor?.countConfig || {};
    if (gutter) {
      if (calc) {
        const gutterText = this._formatGutterPrimary(calc);
        const prevGutterText = (mergeGutter && prevCalc) ? this._formatGutterPrimary(prevCalc) : '';
        const showGutterText = !(mergeGutter && gutterText === prevGutterText);
        gutter.textContent = showGutterText ? gutterText : '';
        // countConfigスタイルはdata属性に保存し、_applyRowStyleで参照する
        if (showGutterText && cc.primaryStyle) {
          const gs = cc.primaryStyle;
          if (gs.bgColor) gutter.dataset.ccBg = gs.bgColor;
          if (gs.textColor) gutter.dataset.ccColor = gs.textColor;
          if (gs.fontWeight) gutter.dataset.ccWeight = gs.fontWeight;
          if (gs.fontSize) gutter.dataset.ccSize = gs.fontSize;
        }
      }
      const gutterSt = getColSettings('_gutter');
      if (gutterSt.align) gutter.style.textAlign = gutterSt.align;
      if (gutterSt.valign) gutter.dataset.valign = gutterSt.valign;
      if (colBorderSet.has('_gutter')) gutter.dataset.colBorderRight = '';
      appendCell('_gutter', gutter);
    }
    if (gutter2) {
      if (calc) {
        const gutter2Text = this._formatGutterSecondary(calc);
        const prevGutter2Text = (mergeGutter && prevCalc) ? this._formatGutterSecondary(prevCalc) : '';
        const showGutter2Text = !(mergeGutter && gutter2Text === prevGutter2Text);
        gutter2.textContent = showGutter2Text ? gutter2Text : '';
        if (showGutter2Text && cc.secondaryStyle) {
          const gs = cc.secondaryStyle;
          if (gs.bgColor) gutter2.dataset.ccBg = gs.bgColor;
          if (gs.textColor) gutter2.dataset.ccColor = gs.textColor;
          if (gs.fontWeight) gutter2.dataset.ccWeight = gs.fontWeight;
          if (gs.fontSize) gutter2.dataset.ccSize = gs.fontSize;
        }
      }
      const gutter2St = getColSettings('_gutter2');
      if (gutter2St.align) gutter2.style.textAlign = gutter2St.align;
      if (gutter2St.valign) gutter2.dataset.valign = gutter2St.valign;
      if (colBorderSet.has('_gutter2')) gutter2.dataset.colBorderRight = '';
      appendCell('_gutter2', gutter2);
    }

    // タイプボタン
    let roleBtn = null;
    if (visCols._role !== false) {
      roleBtn = document.createElement('button');
      roleBtn.className = 'sn2-role-btn';
      roleBtn.type = 'button';
      roleBtn.textContent = mergeRole ? '' : (row.role || '');
      roleBtn.setAttribute('aria-label', `タイプ: ${row.role || '未設定'}`);
      roleBtn.tabIndex = 0;
      roleBtn.dataset.rowId = row.id;
      roleBtn.dataset.e2eId = `sn-row-${row.id}-role`;
      const roleSt = getColSettings('_role');
      if (roleSt.align) roleBtn.style.textAlign = roleSt.align;
      if (roleSt.valign) roleBtn.dataset.valign = roleSt.valign;
      if (colBorderSet.has('_role')) roleBtn.dataset.colBorderRight = '';
      appendCell('_role', roleBtn);
    }

    let statusBtn = null;
    if (visCols._status !== false && this.doc.editor?.statusEnabled) {
      statusBtn = document.createElement('button');
      statusBtn.className = 'sn2-status-btn';
      statusBtn.type = 'button';
      statusBtn.dataset.rowId = row.id;
      statusBtn.dataset.e2eId = `sn-row-${row.id}-status`;
      const statusSt = getColSettings('_status');
      if (statusSt.align) statusBtn.style.justifyContent = statusSt.align === 'right' ? 'flex-end' : statusSt.align === 'center' ? 'center' : 'flex-start';
      if (statusSt.valign) statusBtn.dataset.valign = statusSt.valign;
      if (colBorderSet.has('_status')) statusBtn.dataset.colBorderRight = '';
      if (typeof this._renderRowStatusButton === 'function') this._renderRowStatusButton(statusBtn, row);
      statusBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        this._showRowStatusMenu?.(statusBtn, row, el);
      });
      appendCell('_status', statusBtn);
    }

    // テキスト
    let textDiv = null;
    if (visCols._text !== false) {
      textDiv = document.createElement('div');
      textDiv.className = 'sn2-text';
      textDiv.contentEditable = 'true';
      textDiv.dataset.rowId = row.id;
      textDiv.dataset.e2eId = `sn-row-${row.id}-text`;
      // 再描画をまたいでテキストセル範囲選択の表示を復元する
      if (this._textCellSelection?.has(row.id)) textDiv.classList.add('sn2-text-cell-selected');
      // ルビマークアップ {漢字|ルビ} をDOMに復元。エスケープ（\{ \| \} \\）を逆変換する
      const rowText = row.text || '';
      const manualLinkFrag = rowText && rowText.includes('](ml:') && typeof this._buildManualLinkFragment === 'function'
        ? this._buildManualLinkFragment(rowText)
        : null;
      if (manualLinkFrag) {
        textDiv.appendChild(manualLinkFrag);
      } else if (rowText && rowText.includes('{') && rowText.includes('|')) {
        const frag = document.createDocumentFragment();
        let last = 0;
        const re = _sn2NewRubyRegex();
        let m;
        while ((m = re.exec(rowText)) !== null) {
          if (m.index > last) frag.appendChild(document.createTextNode(_sn2UnescapeScriptNotePlainText(rowText.slice(last, m.index))));
          const span = document.createElement('span');
          span.dataset.ruby = _sn2UnescapeRubyText(m[2]);
          span.textContent = _sn2UnescapeRubyText(m[1]);
          frag.appendChild(span);
          last = m.index + m[0].length;
        }
        if (last < rowText.length) frag.appendChild(document.createTextNode(_sn2UnescapeScriptNotePlainText(rowText.slice(last))));
        textDiv.appendChild(frag);
      } else {
        textDiv.textContent = _sn2UnescapeScriptNotePlainText(rowText);
      }
      // 自動リンク（linkDict ルビ含む）→ シナリオ固有ルビの順で適用
      this._applyAutoLinks(textDiv);
      this._applyAutoRuby(textDiv);
      // D&D: フォルダツリー等からのドロップでリンク名テキストを挿入
      this._setupTextCellDrop(textDiv);
    }
    if (textDiv) {
      const textSt = getColSettings('_text');
      if (textSt.align) textDiv.dataset.align = textSt.align;
      if (textSt.valign) textDiv.dataset.valign = textSt.valign;
      if (textSt.overflow) textDiv.dataset.overflow = textSt.overflow;
      if (colBorderSet.has('_text')) textDiv.dataset.colBorderRight = '';
      appendCell('_text', textDiv);
    }

    // カスタム列
    if (!row.columns) row.columns = {};
    customCols.forEach(col => {
      const cell = document.createElement('div');
      cell.className = 'sn2-custom-cell';
      cell.dataset.colId = col.id;
      const isVMode = this.doc.editor?.viewMode === 'vertical';
      if (isVMode) {
        cell.style.height = `var(--sn2-vcol-${col.id}, ${col.width || 80}px)`;
      } else {
        cell.style.width = `var(--sn2-col-${col.id}, ${col.width || 80}px)`;
      }
      // 配置設定
      if (col.align) cell.dataset.align = col.align;
      if (col.valign) cell.dataset.valign = col.valign;
      const val = row.columns[col.id] ?? '';
      const colControlLabel = `${col.label || col.id || '列'}列`;
      if (col.type === 'number') {
        const inp = document.createElement('input');
        inp.type = 'number';
        inp.className = 'sn2-custom-input';
        inp.dataset.e2eId = `sn-row-${row.id}-custom-${col.id}`;
        inp.setAttribute('aria-label', colControlLabel);
        inp.value = val;
        inp.addEventListener('change', () => {
          this._pushUndo('列値変更');
          const rawValue = inp.value;
          const numericValue = Number(rawValue);
          row.columns[col.id] = rawValue === '' ? '' : (Number.isFinite(numericValue) ? numericValue : '');
          this._markDirty({ skipUndo: true });
        });
        cell.appendChild(inp);
        // 単位表示
        if (col.unit) {
          const unitSpan = document.createElement('span');
          unitSpan.className = 'sn2-custom-unit';
          unitSpan.textContent = col.unit;
          cell.appendChild(unitSpan);
        }
      } else if (col.type === 'select' && Array.isArray(col.options)) {
        const sel = document.createElement('select');
        sel.className = 'sn2-custom-select';
        sel.dataset.e2eId = `sn-row-${row.id}-custom-${col.id}`;
        sel.setAttribute('aria-label', colControlLabel);
        col.options.forEach(opt => { const o = document.createElement('option'); o.value = opt; o.textContent = opt; sel.appendChild(o); });
        sel.value = val;
        sel.addEventListener('change', () => { this._pushUndo('列値変更'); row.columns[col.id] = sel.value; this._markDirty({ skipUndo: true }); });
        cell.appendChild(sel);
      } else {
        const inp = document.createElement('div');
        inp.className = 'sn2-custom-text';
        inp.contentEditable = 'true';
        inp.dataset.e2eId = `sn-row-${row.id}-custom-${col.id}`;
        inp.setAttribute('aria-label', colControlLabel);
        inp.textContent = val;
        this._applyAutoLinks(inp);
        this._applyAutoRuby(inp);
        if (col.overflow) inp.dataset.overflow = col.overflow;
        inp.addEventListener('input', () => {
          if (typeof this._scheduleAutoDecorate === 'function') this._scheduleAutoDecorate(inp);
        });
        inp.addEventListener('focusout', () => { this._pushUndo('列値変更'); row.columns[col.id] = inp.textContent || ''; this._markDirty({ skipUndo: true }); });
        cell.appendChild(inp);
      }
      if (colBorderSet.has(col.id)) cell.dataset.colBorderRight = '';
      appendCell(col.id, cell);
    });

    if (Array.isArray(visibleCols) && visibleCols.length) {
      visibleCols.map(col => col.id).forEach(colId => {
        const cell = Array.from(el.children).find(child => child.dataset?.colId === colId);
        if (cell) el.appendChild(cell);
      });
    }

    // 右端スペーサー（テキスト列が固定幅の場合、行の残り部分をページ背景色に）
    const spacer = document.createElement('div');
    spacer.className = 'sn2-row-spacer';
    el.appendChild(spacer);

    // キャラスタイル適用
    this._applyRowStyle(el, row.role);

    // 縦書き: 連続半角英数字を縦中横(tcy)で横組みブロック化
    if (this.doc.editor?.viewMode === 'vertical') {
      el.querySelectorAll('.sn2-gutter').forEach(c => this._wrapTcy(c, 'sn2-tcy-wide'));
      el.querySelectorAll('.sn2-role-btn, .sn2-custom-text').forEach(c => this._wrapTcy(c));
      if (textDiv) this._wrapTcy(textDiv);
    }

    return el;
  }

  // 連続半角英数字/記号をsn2-tcyスパンで囲む（縦中横）
  // テキストセル内のカーソル位置を「改行を含まない連続テキストの文字オフセット」
  // として取得する。DOM を書き換えても復元できるよう、span ラップや改行非依存
  // な安定座標にする。<br> は改行 1 文字としてカウントする。
  _getTextOffset(textEl) {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount) return -1;
    const range = sel.getRangeAt(0);
    if (!textEl.contains(range.startContainer) && range.startContainer !== textEl) return -1;
    let offset = 0;
    let found = false;
    if (range.startContainer === textEl) {
      for (let i = 0; i < range.startOffset && i < textEl.childNodes.length; i++) {
        offset += this._textLenWithBr(textEl.childNodes[i]);
      }
      return offset;
    }
    const walk = (node) => {
      if (found) return;
      if (node === range.startContainer) {
        if (node.nodeType === 3) {
          offset += range.startOffset;
        } else {
          // element ノードがコンテナの場合: その要素の最初の startOffset 個分の
          // 子要素のテキスト長を加算
          for (let i = 0; i < range.startOffset && i < node.childNodes.length; i++) {
            offset += this._textLenWithBr(node.childNodes[i]);
          }
        }
        found = true;
        return;
      }
      if (node.nodeType === 3) {
        offset += node.textContent.length;
        return;
      }
      if (node.nodeType === 1) {
        if (node.tagName === 'BR') { offset += 1; return; }
        for (const c of node.childNodes) {
          walk(c);
          if (found) return;
        }
      }
    };
    for (const c of textEl.childNodes) { walk(c); if (found) break; }
    return found ? offset : -1;
  }

  _textLenWithBr(node) {
    if (node.nodeType === 3) return node.textContent.length;
    if (node.nodeType === 1) {
      if (node.tagName === 'BR') return 1;
      let len = 0;
      for (const c of node.childNodes) len += this._textLenWithBr(c);
      return len;
    }
    return 0;
  }

  // _getTextOffset で取得したオフセットを使ってカーソルを復元する
  _setTextOffset(textEl, offset) {
    if (offset < 0) return;
    let remaining = offset;
    let placed = false;
    const walk = (node) => {
      if (placed) return;
      if (node.nodeType === 3) {
        if (remaining <= node.textContent.length) {
          const range = document.createRange();
          range.setStart(node, remaining);
          range.collapse(true);
          const sel = window.getSelection();
          sel.removeAllRanges();
          sel.addRange(range);
          placed = true;
          return;
        }
        remaining -= node.textContent.length;
        return;
      }
      if (node.nodeType === 1) {
        if (node.tagName === 'BR') {
          if (remaining === 0) {
            // BR の直前
            const range = document.createRange();
            range.setStartBefore(node);
            range.collapse(true);
            const sel = window.getSelection();
            sel.removeAllRanges();
            sel.addRange(range);
            placed = true;
            return;
          }
          remaining -= 1;
          return;
        }
        for (const c of node.childNodes) {
          walk(c);
          if (placed) return;
        }
      }
    };
    for (const c of textEl.childNodes) { walk(c); if (placed) break; }
    if (!placed) {
      // 末尾にフォールバック
      this._focusText(textEl, 'end');
    }
  }

  _rangeWithinElement(range, el) {
    if (!range || !el) return false;
    return (range.startContainer === el || el.contains(range.startContainer))
      && (range.endContainer === el || el.contains(range.endContainer));
  }

  // デバウンス付きで自動ルビ/自動リンク/縦中横を再適用する。
  // 選択範囲がある場合はスキップ (ユーザー操作を邪魔しないため)。
  _scheduleAutoDecorate(textEl, delay = 200) {
    if (!textEl) return;
    if (!this._autoDecorateTimers) this._autoDecorateTimers = new WeakMap();
    const prev = this._autoDecorateTimers.get(textEl);
    if (prev) clearTimeout(prev);
    const run = () => {
      this._autoDecorateTimers.delete(textEl);
      if (this._imeComposing) return;
      const sel = window.getSelection();
      // 非 collapsed 選択中はスキップ (選択範囲が壊れる)
      if (sel && sel.rangeCount && !sel.isCollapsed) return;
      // textEl がまだ DOM に接続されている必要がある
      if (!textEl.isConnected) return;
      const offset = this._getTextOffset(textEl);
      // 既存装飾を剥がして text node を結合してから再適用する
      textEl.querySelectorAll('[data-auto-ruby], [data-auto-link], .sn2-tcy, .sn2-tcy-wide').forEach(span => {
        // data-ruby などユーザー定義のルビ span は剥がさない
        if (span.dataset && span.dataset.ruby && !span.dataset.autoRuby) return;
        if (span.classList.contains('auto-link') && !span.dataset?.autoLink) return;
        span.replaceWith(document.createTextNode(span.textContent));
      });
      textEl.normalize();
      this._applyAutoLinks(textEl);
      this._applyAutoRuby(textEl);
      if (this.doc?.editor?.viewMode === 'vertical') {
        this._wrapTcy(textEl);
      }
      if (offset >= 0) this._setTextOffset(textEl, offset);
      // カスタムキャレットも更新
      if (this._caretSelChangeHandler) this._caretSelChangeHandler();
    };
    if (delay > 0) {
      this._autoDecorateTimers.set(textEl, setTimeout(run, delay));
    } else {
      run();
    }
  }

  _wrapTcy(el, tcyCls = 'sn2-tcy') {
    const walk = (node) => {
      if (node.nodeType !== 3) return; // テキストノードのみ
      const text = node.textContent;
      // 連続する半角英数字・記号（スペース除く）を検出
      const re = /[a-zA-Z0-9!?.,;:'"()&%$#@+\-*/=<>[\]{}]+/g;
      let m, parts = [], last = 0;
      while ((m = re.exec(text)) !== null) {
        if (m.index > last) parts.push({ text: text.slice(last, m.index), tcy: false });
        parts.push({ text: m[0], tcy: true });
        last = m.index + m[0].length;
      }
      if (!parts.length) return;
      if (last < text.length) parts.push({ text: text.slice(last), tcy: false });
      const frag = document.createDocumentFragment();
      parts.forEach(p => {
        if (p.tcy) {
          const span = document.createElement('span');
          span.className = tcyCls;
          span.textContent = p.text;
          frag.appendChild(span);
        } else {
          frag.appendChild(document.createTextNode(p.text));
        }
      });
      node.parentNode.replaceChild(frag, node);
    };
    // 直接の子テキストノードのみ処理（span[data-ruby]等の中は触らない）
    [...el.childNodes].forEach(walk);
  }

  // === 行タイプ判定 ===

  // 設定駆動方針: タイプ名による暗黙判定は撤廃。空ロールのみ 'blank'、それ以外は 'dialogue'
  _detectKind(role) {
    if (!role) return 'blank';
    const r = String(role).trim();
    if (!r) return 'blank';
    return 'dialogue';
  }

  // 旧データ移行用: タイプ名から旧 kind を推測する（loadDoc 内の一回だけ使用）
  _legacyDetectKindByName(name) {
    if (!name) return 'blank';
    const r = String(name).trim();
    if (!r) return 'blank';
    const breaks = ['めくり', '改ページ', '白紙', '見開き', '巻頭カラー', 'トビラ絵', '場面転換', '暗転', '幕間'];
    if (breaks.includes(r)) return 'break';
    if (r === 'プロット') return 'summary';
    if (typeof PAGE_SETTINGS !== 'undefined' && Array.isArray(PAGE_SETTINGS) && PAGE_SETTINGS.includes(r)) return 'heading';
    const headings = ['柱', 'シーン', '○', 'シーン見出し', '第一幕', '第二幕', '第三幕', '場'];
    if (headings.some(h => r.startsWith(h)) || /^\d+\s*[.．]/.test(r)) return 'heading';
    if (typeof SPECIAL_CHARA !== 'undefined' && Array.isArray(SPECIAL_CHARA) && SPECIAL_CHARA.includes(r)) return 'action';
    const actions = ['ト書き', 'ト', '動作', '説明', 'N', 'ナレーション', 'ナレ', 'SE', 'ME', 'M',
                     'コマ外注釈', '擬音', 'モノローグ', '心の声', 'BGM', 'テロップ', '（間）',
                     '地の文', '独白', '傍白', '歌', '群衆'];
    if (actions.includes(r)) return 'action';
    return 'dialogue';
  }

  // === イベント ===

  _bind() {
    if (this._bound) return;
    this._bound = true;
    const host = this.host;

    // === ホイール/矩形選択/行コピー/右ドラッグパン → gb-scriptnote-interactions.js に移動 ===
    this._bindInteractionEvents(host);

    // === セルナビゲーション: クリックは「アクティブ化」のみ（即編集しない） ===
    // キャプチャフェーズで先に処理する。実際のmousedown→クリックの間にブラウザが
    // contentEditableへキャレットを置くが、この click ハンドラで contentEditable を
    // false に戻すため、同一フレーム内で「編集開始」の見た目には遷移しない。
    host.addEventListener('click', (e) => {
      const textEl = e.target.closest?.('.sn2-text, .sn2-custom-text');
      if (textEl && host.contains(textEl)) {
        const rowEl = textEl.closest('.sn2-row');
        if (!rowEl) return;
        const rowId = rowEl.dataset.rowId;
        const colId = textEl.dataset.colId || (textEl.closest('.sn2-custom-cell')?.dataset.colId) || '_text';
        if (this._cellEditMode && this._activeCellRowId === rowId && this._activeCellColId === colId) return;
        this._setActiveCell(rowId, colId, false);
        return;
      }
      const nativeCtrl = e.target.closest?.('.sn2-custom-input, .sn2-custom-select');
      if (nativeCtrl) {
        const customCell = nativeCtrl.closest('.sn2-custom-cell');
        const rowEl = nativeCtrl.closest('.sn2-row');
        if (!customCell || !rowEl || !host.contains(customCell)) return;
        const rowId = rowEl.dataset.rowId;
        const colId = customCell.dataset.colId;
        if (this._activeCellRowId === rowId && this._activeCellColId === colId) return;
        if (this._activeCellRowId) this._clearActiveCell?.();
        this._activeCellRowId = rowId;
        this._activeCellColId = colId;
        this._cellEditMode = true;
        customCell.classList.add('sn2-cell-active');
        nativeCtrl.focus();
      }
    }, true);

    host.addEventListener('dblclick', (e) => {
      const textEl = e.target.closest?.('.sn2-text, .sn2-custom-text');
      if (!textEl || !host.contains(textEl)) return;
      const rowEl = textEl.closest('.sn2-row');
      if (!rowEl) return;
      const rowId = rowEl.dataset.rowId;
      const colId = textEl.dataset.colId || (textEl.closest('.sn2-custom-cell')?.dataset.colId) || '_text';
      this._setActiveCell(rowId, colId, true);
    });

    // カスタムキャレット（太い線）
    let caretEl = null;
    // ブラウザの range.getClientRects() が 0 サイズを返すケース
    // (空セル / 改行直後 / DOM ミューテーション直後) の補完計算
    const computeFallbackRect = (range, textEl) => {
      const startContainer = range.startContainer;
      const startOffset = range.startOffset;
      const isVert = this.doc.editor?.viewMode === 'vertical';
      // TCY (tate-chu-yoko) 内のキャレットは縦書きモードでも横書きと同じ縦線にする
      let isInsideTcy = false;
      if (isVert && startContainer) {
        const el = startContainer.nodeType === 3 ? startContainer.parentElement : startContainer;
        isInsideTcy = !!(el?.closest?.('.sn2-tcy') || el?.closest?.('.sn2-tcy-wide'));
      }
      const effectiveVert = isVert && !isInsideTcy;
      const cs = getComputedStyle(textEl);
      // getComputedStyle は CSS ピクセル (ズーム未適用) を返すが、
      // getBoundingClientRect は CSS zoom 適用後の描画座標を返すため、
      // 加減算時は必ず _getZoom() を掛けて同じ座標系に揃える。
      const zFb = typeof _getZoom === 'function' ? _getZoom() : 1;
      const lineH = ((parseFloat(cs.lineHeight) || (parseFloat(cs.fontSize) * 1.6) || 16)) * zFb;
      const padTop = (parseFloat(cs.paddingTop) || 0) * zFb;
      const padLeft = (parseFloat(cs.paddingLeft) || 0) * zFb;
      const padRight = (parseFloat(cs.paddingRight) || 0) * zFb;
      const tr = textEl.getBoundingClientRect();
      // 横書きカーソル(縦線)を rect の右側に置くヘルパー
      const caretAfter = (r) => effectiveVert
        ? { left: r.left, top: r.bottom, right: r.right, bottom: r.bottom + 2, width: r.width, height: 2 }
        : { left: r.right, top: r.top, right: r.right + 2, bottom: r.bottom, width: 2, height: r.height };
      // 横書きカーソル(縦線)を rect の左側に置くヘルパー
      const caretBefore = (r) => effectiveVert
        ? { left: r.left, top: r.top, right: r.right, bottom: r.top + 2, width: r.width, height: 2 }
        : { left: r.left, top: r.top, right: r.left + 2, bottom: r.bottom, width: 2, height: r.height };
      // 1 文字分の rect を取得するヘルパー
      const charRect = (textNode, from, to) => {
        try {
          const r2 = document.createRange();
          r2.setStart(textNode, from);
          r2.setEnd(textNode, to);
          const r2rect = r2.getClientRects()[0] || r2.getBoundingClientRect();
          if (r2rect && (r2rect.width || r2rect.height)) return r2rect;
        } catch (e) {}
        return null;
      };
      // === Case A: startContainer がテキストノード ===
      if (startContainer.nodeType === 3) {
        // オフセット > 0: 1 文字戻した rect の右側にカーソル
        if (startOffset > 0) {
          const r = charRect(startContainer, startOffset - 1, startOffset);
          if (r) return caretAfter(r);
        }
        // オフセット 0: 先頭文字がある場合は左側にカーソル
        if (startContainer.length > 0) {
          const r = charRect(startContainer, 0, 1);
          if (r) return caretBefore(r);
        }
        // 空テキストノードの場合、prev/next をたどる
      }
      // === Case B: 直前の子要素を特定 ===
      let prev = null;
      if (startContainer.nodeType === 1 && startOffset > 0) {
        prev = startContainer.childNodes[startOffset - 1];
      } else if (startContainer.nodeType === 3) {
        prev = startContainer.previousSibling;
      }
      // prev がテキストノードなら最後の文字の右側にカーソル
      if (prev && prev.nodeType === 3 && prev.length > 0) {
        const r = charRect(prev, prev.length - 1, prev.length);
        if (r) return caretAfter(r);
      }
      // prev が BR なら次の行の先頭にカーソル
      if (prev && prev.nodeType === 1 && prev.tagName === 'BR') {
        const prr = prev.getBoundingClientRect();
        if (effectiveVert) {
          const x = prr.left - lineH;
          const y = tr.top + padTop;
          return { left: x, top: y, right: x + lineH, bottom: y + 16, width: lineH, height: 16 };
        }
        const x = tr.left + padLeft;
        const y = prr.bottom;
        return { left: x, top: y, right: x + 2, bottom: y + lineH, width: 2, height: lineH };
      }
      // それ以外（空セル等）: textEl の左上(横書き) / 右上(縦書き)
      if (effectiveVert) {
        const x = tr.right - padRight - lineH;
        const y = tr.top + padTop;
        return { left: x, top: y, right: x + lineH, bottom: y + 16, width: lineH, height: 16 };
      }
      const x = tr.left + padLeft;
      const y = tr.top + padTop;
      return { left: x, top: y, right: x + 2, bottom: y + lineH, width: 2, height: lineH };
    };

    const updateCaret = () => {
      const sel = window.getSelection();
      if (!sel?.isCollapsed || !sel.rangeCount) { if (caretEl) caretEl.style.display = 'none'; return; }
      const textEl = sel.anchorNode?.nodeType === 3
        ? sel.anchorNode.parentElement?.closest?.('.sn2-text')
        : sel.anchorNode?.closest?.('.sn2-text');
      if (!textEl || !host.contains(textEl)) { if (caretEl) caretEl.style.display = 'none'; return; }
      // 重要: caretEl は contenteditable な textEl の中ではなく、親の .sn2-row に置く。
      // textEl の子にすると caretEl が editable content として扱われ、入力文字が
      // caretEl に紛れ込んだり位置がずれたりする。
      const row = textEl.closest('.sn2-row');
      if (!row) { if (caretEl) caretEl.style.display = 'none'; return; }
      const range = sel.getRangeAt(0);
      let rect = range.getClientRects()[0] || range.getBoundingClientRect();
      // rect が 0 サイズなら推定で補完してカーソルを必ず表示する
      if (!rect || (!rect.height && !rect.width)) {
        rect = computeFallbackRect(range, textEl);
      }
      if (!rect) { if (caretEl) caretEl.style.display = 'none'; return; }
      const rowRect = row.getBoundingClientRect();
      const z = typeof _getZoom === 'function' ? _getZoom() : 1;
      if (!caretEl) {
        caretEl = document.createElement('div');
        caretEl.className = 'sn2-custom-caret';
      }
      if (caretEl.parentElement !== row) row.appendChild(caretEl);
      const isVert = this.doc.editor?.viewMode === 'vertical';
      // TCY (tate-chu-yoko) 内のキャレットは縦書きモードでも横書きと同じ縦線にする
      let isInsideTcy = false;
      if (isVert && sel.anchorNode) {
        const el = sel.anchorNode.nodeType === 3 ? sel.anchorNode.parentElement : sel.anchorNode;
        isInsideTcy = !!(el?.closest?.('.sn2-tcy') || el?.closest?.('.sn2-tcy-wide'));
      }
      const dx = (rect.left - rowRect.left) / z;
      const dy = (rect.top - rowRect.top) / z;
      if (isVert && !isInsideTcy) {
        // 縦書き: キャレットは横線
        caretEl.style.left = dx + 'px';
        caretEl.style.top = dy + 'px';
        caretEl.style.width = (rect.width || 16) / z + 'px';
        caretEl.style.height = '';
      } else {
        // 横書き or 縦中横内: キャレットは縦線
        caretEl.style.left = dx + 'px';
        caretEl.style.top = dy + 'px';
        caretEl.style.height = (rect.height || 16) / z + 'px';
        caretEl.style.width = '';
      }
      caretEl.style.display = '';
      caretEl.style.animation = 'none';
      caretEl.offsetHeight; // reflow — 点滅リセット
      caretEl.style.animation = '';
    };
    // 前回のリスナーを解除（タブ開閉によるリーク防止）
    if (this._caretSelChangeHandler) document.removeEventListener('selectionchange', this._caretSelChangeHandler);
    this._caretSelChangeHandler = updateCaret;
    document.addEventListener('selectionchange', updateCaret);
    // focusout 時は同期で隠さず、次フレームで本当に host 外に出たかを再確認する
    // (セル間のフォーカス移動中に瞬間的に隠れる現象の回避)
    host.addEventListener('focusout', () => {
      setTimeout(() => {
        const ae = document.activeElement;
        if (!host.contains(ae) && caretEl) caretEl.style.display = 'none';
      }, 0);
    });

    // IME 変換中は DOM を書き換えない (変換が切れるため)
    this._imeComposing = false;
    host.addEventListener('compositionstart', (e) => {
      this._imeComposing = true;
      const text = e.target.closest?.('.sn2-text');
      if (text && typeof this._beginTextInputUndo === 'function') this._beginTextInputUndo('編集');
    });
    host.addEventListener('compositionend', (e) => {
      this._imeComposing = false;
      // 変換確定後にデバウンスなしで 1 度再適用
      const text = e.target.closest?.('.sn2-text');
      if (text) {
        this._scheduleTextCellLiveResize?.(text);
        this._scheduleAutoDecorate(text, 0);
      }
    });

    host.addEventListener('beforeinput', (e) => {
      const text = e.target.closest?.('.sn2-text');
      if (!text || e.isComposing) return;
      if (e.inputType === 'historyUndo' || e.inputType === 'historyRedo') return;
      if (typeof this._beginTextInputUndo === 'function') this._beginTextInputUndo('編集');
    });

    // ルビを振った文字列の直前・直後で打った文字がルビへ取り込まれないようにする
    // （ノートと共通の gb-ruby-boundary.js）。取り消しの記録は上の beforeinput が
    // 先に済ませているので、ここでは重ねて積まない。既定動作を止める分だけ
    // input を明示的に発火させて、保存予約（下の input ハンドラ）へつなぐ。
    if (window.MeldexRubyBoundary) {
      window.MeldexRubyBoundary.attach(host, {
        pushUndo: () => {},
        dispatchInput: (el) => el.dispatchEvent(new Event('input', { bubbles: true })),
      });
    }

    host.addEventListener('input', (e) => {
      const text = e.target.closest?.('.sn2-text');
      if (!text) return;
      this._dirty = true;
      this._scheduleSave();
      // 編集のたびに自動ルビ/自動リンク/縦中横を再適用 (デバウンス)
      // IME 変換中はスキップ (compositionend 側で拾う)
      this._scheduleTextCellLiveResize?.(text);
      if (!this._imeComposing) this._scheduleAutoDecorate(text);
      // カーソルが見えるようスクロール追従（改行時にのみ重い処理を実行）
      if (e.inputType === 'insertParagraph' || e.inputType === 'insertLineBreak') {
        requestAnimationFrame(() => {
          const sel = window.getSelection();
          if (!sel?.rangeCount || !sel.isCollapsed) return;
          const r = sel.getRangeAt(0);
          const marker = document.createElement('span');
          marker.style.cssText = 'display:inline;';
          r.insertNode(marker);
          marker.scrollIntoView({ block: 'nearest', behavior: 'instant' });
          const markerParent = marker.parentNode;
          const markerIndex = markerParent ? Array.prototype.indexOf.call(markerParent.childNodes, marker) : -1;
          marker.remove();
          // マーカー除去後にselectionを復元
          if (markerParent && markerIndex >= 0) {
            const restoreRange = document.createRange();
            restoreRange.setStart(markerParent, Math.min(markerIndex, markerParent.childNodes.length));
            restoreRange.collapse(true);
            sel.removeAllRanges();
            sel.addRange(restoreRange);
          }
        });
      } else {
        // settleWrapPacking は別メソッドのローカル const のため、ここからは参照できない。
        // ファイル分割前は同じスコープに居たが、現状のコード構造では到達不可能。
        // ReferenceError を防ぐため typeof で存在チェックしてから呼ぶ。
        // （未到達時は折り返し再パックが走らないが、次のフル再レンダリングで反映される）
        requestAnimationFrame(() => {
          if (typeof settleWrapPacking === 'function') settleWrapPacking();
        });
      }
    });

    host.addEventListener('keydown', (e) => {
      if (e.isComposing) return;

      // アクティブセル（クリックで強調表示のみ・未編集）に対する矢印/Tab/Enter/Escapeは
      // ここでナビゲーションとして処理する。編集中のセルや無関係のターゲットには影響しない。
      if (typeof this._isActiveNonEditingTarget === 'function' && this._isActiveNonEditingTarget(e.target)) {
        if (this._handleNavigationKeydown(e)) return;
      }

      // ネイティブコントロール（数値入力・選択肢）が編集中のとき、Escape/Tab/Enterでセル編集を抜ける
      if (this._cellEditMode && this._activeCellRowId) {
        const nativeCtrl = e.target.closest?.('.sn2-custom-input, .sn2-custom-select');
        if (nativeCtrl) {
          if (e.key === 'Escape' || (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey)) {
            e.preventDefault(); e.stopPropagation();
            nativeCtrl.blur();
            const wrapperEl = this._getCellElement(this._activeCellRowId, this._activeCellColId);
            this._cellEditMode = false;
            if (wrapperEl) { wrapperEl.classList.add('sn2-cell-active'); wrapperEl.tabIndex = 0; wrapperEl.focus(); }
            return;
          }
          if (e.key === 'Tab') {
            e.preventDefault(); e.stopPropagation();
            nativeCtrl.blur();
            this._cellEditMode = false;
            // Tab はその行のタイプ選択メニューを開く（Shift+Tab は従来どおり前のセルへ移動）
            if (!e.shiftKey) {
              const roleBtn = nativeCtrl.closest('.sn2-row')?.querySelector('.sn2-role-btn');
              if (roleBtn) { this._showRoleMenu(roleBtn); return; }
            }
            this._navigateCell(e.shiftKey ? 'prev-col' : 'next-col');
            return;
          }
        }
      }

      const roleKeyTarget = e.target.closest?.('.sn2-role-btn');
      if (roleKeyTarget && typeof this._handleRoleCellKeydown === 'function' && this._handleRoleCellKeydown(roleKeyTarget, e)) return;

      // Tab: カスタム列テキストセル編集中もその行のタイプ選択メニューを開く
      // （メインテキストセルの Tab は part03 のテキストセル keydown で処理される）
      if (e.key === 'Tab' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey) {
        const customText = e.target.closest?.('.sn2-custom-text');
        const roleBtn = customText?.closest('.sn2-row')?.querySelector('.sn2-role-btn');
        if (roleBtn) { e.preventDefault(); this._showRoleMenu(roleBtn); return; }
      }

      // Ctrl+Z / Ctrl+Y (undo/redo) — テキスト内外どちらでも動作
      const lk = e.key.toLowerCase();
      if ((e.ctrlKey || e.metaKey) && lk === 'z' && !e.shiftKey) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.undo', e)) return;
        e.preventDefault(); this.undo(); return;
      }
      if ((e.ctrlKey || e.metaKey) && (lk === 'y' || (lk === 'z' && e.shiftKey))) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.redo', e)) return;
        e.preventDefault(); this.redo(); return;
      }
      // Ctrl+R: ルビ入力
      if ((e.ctrlKey || e.metaKey) && lk === 'r') {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.ruby', e)) return;
        e.preventDefault(); this._insertRuby(); return;
      }
      if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && (lk === 'f' || lk === 'h')) {
        const shortcutId = lk === 'h' ? 'scenario.replace' : 'scenario.search';
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById(shortcutId, e)) return;
        e.preventDefault();
        const searchBtn = this.host?.closest?.('.gb-se-root')?.querySelector?.('[data-sn-action="search"]') || null;
        this._showSearchReplacePopup?.(searchBtn);
        return;
      }
      // Ctrl+D: 行選択・セル範囲選択を解除
      if ((e.ctrlKey || e.metaKey) && lk === 'd' && !e.shiftKey && !e.altKey) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.deselectAll', e)) return;
        e.preventDefault();
        if (this._rowSelection?.size) this._clearRowSelection();
        if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
        if (this._textCellSelection?.size) this._clearTextCellSelection?.();
        this._lastSelectedIdx = -1;
        const dsel = window.getSelection();
        if (dsel?.rangeCount && !dsel.isCollapsed) dsel.collapseToStart();
        return;
      }
      // Alt+下: テキスト選択時にルビ設定を開く
      if (e.altKey && e.key === 'ArrowDown' && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
        const sel = window.getSelection();
        if (sel && !sel.isCollapsed && sel.rangeCount) {
          const textEl = sel.anchorNode?.parentElement?.closest?.('.sn2-text');
          if (textEl) { e.preventDefault(); this._insertRuby(); return; }
        }
      }

      // PageUp/PageDown: 折り返しOFF時にスクロール
      if ((e.key === 'PageUp' || e.key === 'PageDown') && !this.doc.editor?.wrapMode) {
        const sc = host.querySelector('.sn2-scroll');
        if (sc) {
          e.preventDefault();
          const isV = this.doc.editor?.viewMode === 'vertical';
          const activeText = e.target.closest?.('.sn2-text');
          const caretOffset = activeText ? this._getTextOffset(activeText) : -1;
          const scRect = sc.getBoundingClientRect();
          const textRect = activeText?.getBoundingClientRect?.() || null;
          const probeX = textRect
            ? Math.min(scRect.right - 8, Math.max(scRect.left + 8, textRect.left + Math.min(24, textRect.width || 24)))
            : scRect.left + Math.min(scRect.width / 2, 48);
          const probeY = textRect
            ? Math.min(scRect.bottom - 8, Math.max(scRect.top + 8, textRect.top + Math.min(18, textRect.height || 18)))
            : scRect.top + Math.min(scRect.height / 2, 48);
          const amount = (isV ? sc.clientWidth : sc.clientHeight) * 0.8;
          if (isV) sc.scrollLeft += e.key === 'PageUp' ? amount : -amount;
          else sc.scrollTop += e.key === 'PageUp' ? -amount : amount;
          if (activeText) {
            requestAnimationFrame(() => {
              let nextText = document.elementFromPoint(probeX, probeY)?.closest?.('.sn2-text') || null;
              if (!nextText || !sc.contains(nextText)) {
                nextText = [...sc.querySelectorAll('.sn2-text')].find((el) => {
                  const rect = el.getBoundingClientRect();
                  return rect.bottom > scRect.top && rect.top < scRect.bottom && rect.right > scRect.left && rect.left < scRect.right;
                }) || null;
              }
              if (nextText) {
                nextText.focus();
                if (caretOffset >= 0) this._setTextOffset(nextText, Math.min(caretOffset, this._textLenWithBr(nextText)));
              }
            });
          }
        }
        return;
      }

      // Ctrl+上下: 行入れ替え（縦書き時はCtrl+右/左）
      const isVert = this.doc.editor?.viewMode === 'vertical';
      const swapPrevKey = isVert ? 'ArrowRight' : 'ArrowUp';
      const swapNextKey = isVert ? 'ArrowLeft' : 'ArrowDown';
      if ((e.ctrlKey || e.metaKey) && (e.key === swapPrevKey || e.key === swapNextKey)) {
        const shortcutId = e.key === swapPrevKey ? 'scenario.moveUp' : 'scenario.moveDown';
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById(shortcutId, e)) return;
        const text = e.target.closest?.('.sn2-text');
        if (!text) return;
        e.preventDefault();
        const row = text.closest('.sn2-row');
        if (!row) return;
        const rowId = row.dataset.rowId;
        const idx = this.doc.rows.findIndex(r => r.id === rowId);
        if (idx < 0) return;
        const dir = e.key === swapPrevKey ? -1 : 1;
        // フィルタで非表示の行をスキップ
        let targetIdx = idx + dir;
        while (targetIdx >= 0 && targetIdx < this.doc.rows.length) {
          const targetRow = this.doc.rows[targetIdx];
          if (this._isRoleVisible(targetRow.role, targetRow.status || '')) break;
          targetIdx += dir;
        }
        if (targetIdx < 0 || targetIdx >= this.doc.rows.length) return;
        this._pushUndo('行入れ替え');
        // スワップ前にtargetのIDを保存
        const targetRowId = this.doc.rows[targetIdx].id;
        const tmp = this.doc.rows[idx];
        this.doc.rows[idx] = this.doc.rows[targetIdx];
        this.doc.rows[targetIdx] = tmp;
        this._calcCache = null;
        // DOM操作のみで行を入れ替え（_render()を避けて軽量化）
        const targetRow = this.host?.querySelector(`.sn2-row[data-row-id="${targetRowId}"]`);
        if (row && targetRow && !this._filterRoles) {
          // フィルタなし: DOM操作のみで軽量入れ替え
          if (dir === -1) row.parentNode.insertBefore(row, targetRow);
          else row.parentNode.insertBefore(row, targetRow.nextSibling);
          // ガター更新
          this._updateGuttersFrom(Math.min(idx, targetIdx));
          // ハイライトアニメーション
          row.classList.add('sn2-swap-highlight');
          setTimeout(() => row.classList.remove('sn2-swap-highlight'), 400);
        } else {
          // フィルタ有効時はDOM行数とデータ行数がずれるので全体再描画
          this._render();
        }
        this._markDirty({ skipUndo: true });
        // 移動先の行にフォーカス（_render()後はDOMが再構築されるためIDで検索）
        requestAnimationFrame(() => {
          const curRow = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
          const newText = curRow?.querySelector('.sn2-text');
          if (!newText) return;
          // フォーカスが既にnewText内にあれば再フォーカスしない（カーソル位置を保つ）
          const csel = window.getSelection();
          const inText = csel?.anchorNode && newText.contains(csel.anchorNode);
          if (!inText) this._focusText(newText, 'start');
          // DOM移動直後はlayoutが確定していないことがあるため、
          // 二重rAFで確実に layout 後にカスタムキャレットを再描画する
          if (this._caretSelChangeHandler) this._caretSelChangeHandler();
          requestAnimationFrame(() => {
            if (this._caretSelChangeHandler) this._caretSelChangeHandler();
          });
        });
        return;
      }

      // 矩形セル範囲選択中の Delete/Backspace: 行削除ではなく選択セルの内容をクリアする
      if ((e.key === 'Delete' || e.key === 'Backspace')
          && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey
          && this._gridCellSelection?.size
          && typeof this._clearSelectedGridCells === 'function') {
        e.preventDefault();
        this._clearSelectedGridCells();
        return;
      }

      // テキスト列だけの従来範囲選択も同じく内容をクリアする
      if ((e.key === 'Delete' || e.key === 'Backspace')
          && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey
          && this._textCellSelection?.size
          && typeof this._clearSelectedTextCells === 'function') {
        e.preventDefault();
        this._clearSelectedTextCells();
        return;
      }

      const text = e.target.closest?.('.sn2-text');
      if (!text) return;
      // アクティブセルのみ（非編集中）の場合、旧来のテキスト編集キー処理
      // （Enter分割・Backspace/Delete行結合・Shift+Delete行削除等）は行わない。
      // 矢印/Tab/Enter/Escapeはホストのkeydownルーティングでナビゲーションが処理済み。
      if (typeof this._isActiveNonEditingTarget === 'function' && this._isActiveNonEditingTarget(text)) return;
      const isVertical = this.doc.editor?.viewMode === 'vertical';

      if (e.key === 'Enter' && !e.shiftKey && !(e.ctrlKey || e.metaKey)) {
        if (this._cellEditMode && typeof this._exitEditMode === 'function') {
          e.preventDefault();
          this._exitEditMode();
          return;
        }
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.addRow', e)) return;
        e.preventDefault();
        const splitOffset = this._getTextOffset(text);
        this._pushUndo('行追加');
        this._splitRow(text, { keepRole: false, visibleOffset: splitOffset });
        return;
      }
      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.addRowSameType', e)) return;
        e.preventDefault();
        const splitOffset = this._getTextOffset(text);
        this._pushUndo('同タイプ行追加');
        this._splitRow(text, { keepRole: true, visibleOffset: splitOffset });
        return;
      }
      // Shift+Enter: 明示的に<br>を挿入して改行（ブラウザデフォルトに任せない）
      if (e.key === 'Enter' && e.shiftKey) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.newline', e)) return;
        e.preventDefault();
        const sel = window.getSelection();
        if (!sel?.rangeCount) return;
        const range = sel.getRangeAt(0);
        if (!this._rangeWithinElement(range, text)) return;
        this._pushUndo('セル内改行');
        // 旧実装は dataset.before / dataset.after が設定されていると先頭・末尾での Shift+Enter を弾いていたが、
        // これらの affix は CSS の ::before / ::after 疑似要素なので <br> を挿入しても視覚順序は変わらない (常に affix の内側で改行される)。
        // ユーザー要望によりこの早期 return を撤廃し、末尾を含むあらゆる位置で改行を許可する。
        range.deleteContents();
        const br = document.createElement('br');
        range.insertNode(br);
        // <br>の後にカーソルを移動
        range.setStartAfter(br);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
        // <br>が末尾なら trailing <br> を追加して空行を可視化（番兵）
        // カーソルは挿入brの直後＝trailing brの直前を指すため、新しい空行に表示される
        // insertNode がテキスト末尾で分割した場合に残る空テキストノードはスキップして判定
        let needsTrailingBr = true;
        for (let n = br.nextSibling; n; n = n.nextSibling) {
          if (n.nodeType === 3 && !n.textContent) continue; // 空テキストノードは無視
          if (n.nodeType === 1 && n.tagName === 'BR') { needsTrailingBr = false; break; } // 既存の番兵
          needsTrailingBr = false; // 何か可視コンテンツあり
          break;
        }
        if (needsTrailingBr) {
          text.appendChild(document.createElement('br'));
        }
        // 高さ自動調整のためリフロートリガー
        text.style.height = 'auto';
        this._syncRowFromDom(text, { skipUndo: true });
        this._scheduleTextCellLiveResize?.(text);
        // スクロール追従とカスタムキャレット再描画
        requestAnimationFrame(() => {
          const r2 = sel.getRangeAt(0);
          if (!this._rangeWithinElement(r2, text)) return;
          const marker = document.createElement('span');
          r2.insertNode(marker);
          marker.scrollIntoView({ block: 'nearest', behavior: 'instant' });
          const markerParent = marker.parentNode;
          const markerIndex = markerParent ? Array.prototype.indexOf.call(markerParent.childNodes, marker) : -1;
          marker.remove();
          if (markerParent && markerIndex >= 0) {
            const restoreRange = document.createRange();
            restoreRange.setStart(markerParent, Math.min(markerIndex, markerParent.childNodes.length));
            restoreRange.collapse(true);
            sel.removeAllRanges();
            sel.addRange(restoreRange);
          } else {
            sel.collapseToEnd();
          }
          // 末尾改行直後の空行は range.getClientRects() が 0 になりがちなので
          // 二重 rAF で layout 後に確実にカスタムキャレットを更新する
          if (this._caretSelChangeHandler) this._caretSelChangeHandler();
          requestAnimationFrame(() => {
            if (this._caretSelChangeHandler) this._caretSelChangeHandler();
          });
        });
        return;
      }

      // Tab: タイプ↔テキスト切り替え
      if (e.key === 'Tab') {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.tab', e)) return;
        e.preventDefault();
        const row = text.closest('.sn2-row');
        if (!row) return;
        const roleBtn = row.querySelector('.sn2-role-btn');
        if (roleBtn) this._showRoleMenu(roleBtn);
        return;
      }

      const roleFocusKey = isVertical ? 'ArrowUp' : 'ArrowLeft';
      if (e.altKey && !e.shiftKey && !e.ctrlKey && !e.metaKey && e.key === roleFocusKey) {
        e.preventDefault();
        const row = text.closest('.sn2-row');
        const roleBtn = row?.querySelector('.sn2-role-btn');
        const rowId = row?.dataset.rowId || '';
        const idx = this.doc.rows.findIndex(r => r.id === rowId);
        if (roleBtn && idx >= 0) {
          this._selectRoleCell?.(rowId, idx);
          roleBtn.focus();
          roleBtn.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
        }
        return;
      }

      // 行間移動: 横書き=ArrowUp/Down、縦書き=ArrowLeft/Right
      // 非Shift: 2段階移動 (1) セル内で先頭/末尾へ移動 → (2) 既に境界なら隣のセルへ
      // Shift押下時: セル境界に達したら行選択を拡張、それ以外はブラウザのデフォルト
      const prevKey = isVertical ? 'ArrowRight' : 'ArrowUp';
      const nextKey = isVertical ? 'ArrowLeft' : 'ArrowDown';
      if (e.key === prevKey || e.key === nextKey) {
        const isPrev = e.key === prevKey;
        // Alt+矢印: 5 行スキップしてフォーカス移動 (フィルタ非表示はスキップ)
        if (e.altKey && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
          e.preventDefault();
          const curRow = text.closest('.sn2-row');
          const curRowId = curRow?.dataset.rowId;
          const curIdx = this.doc.rows.findIndex(r => r.id === curRowId);
          if (curIdx < 0) return;
          const dir = isPrev ? -1 : 1;
          let remaining = 5;
          let nextIdx = curIdx;
          while (remaining > 0) {
            let probe = nextIdx + dir;
            while (probe >= 0 && probe < this.doc.rows.length) {
              const rr = this.doc.rows[probe];
              if (this._isRoleVisible(rr.role || '', rr.status || '')) break;
              probe += dir;
            }
            if (probe < 0 || probe >= this.doc.rows.length) break;
            nextIdx = probe;
            remaining--;
          }
          if (nextIdx === curIdx) return;
          const nextRowEl = this.host?.querySelector(`.sn2-row[data-row-id="${this.doc.rows[nextIdx].id}"]`);
          const nextText = nextRowEl?.querySelector('.sn2-text');
          if (nextText) {
            this._focusText(nextText, isPrev ? 'end' : 'start');
            nextText.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
          }
          return;
        }
        if (e.shiftKey) {
          // Shift+矢印: セル境界に達したらテキストセル範囲選択を拡張、それ以外はブラウザのデフォルトに任せる
          const sel = window.getSelection();
          if (!sel?.rangeCount) return;
          // focusが属するセルを起点にする（複数セル選択時はfocusが別セルにいる）
          const focusText = sel.focusNode?.nodeType === 1
            ? sel.focusNode.closest?.('.sn2-text') || text
            : sel.focusNode?.parentElement?.closest?.('.sn2-text') || text;
          if (!this._isAtBoundary(focusText, isPrev, true)) return;
          e.preventDefault();
          const curRow = focusText.closest('.sn2-row');
          if (!curRow) return;
          const curRowId = curRow.dataset.rowId;
          const curIdx = this.doc.rows.findIndex(r => r.id === curRowId);
          if (curIdx < 0) return;
          if (!this._textCellSelection) this._textCellSelection = new Set();
          // アンカー検証: _textCellAnchorIdx が現在の選択に含まれていなければ curRow を新アンカーにする
          const anchorRow = (this._textCellAnchorIdx >= 0) ? this.doc.rows[this._textCellAnchorIdx] : null;
          let anchorIdx;
          if (anchorRow && this._textCellSelection.has(anchorRow.id)) {
            anchorIdx = this._textCellAnchorIdx;
          } else {
            this._textCellAnchorIdx = curIdx;
            anchorIdx = curIdx;
          }
          // 次の行を探す（フィルタ非表示はスキップ）
          const dir = isPrev ? -1 : 1;
          let nextIdx = curIdx + dir;
          while (nextIdx >= 0 && nextIdx < this.doc.rows.length) {
            const rr = this.doc.rows[nextIdx];
            if (this._isRoleVisible(rr.role || '', rr.status || '')) break;
            nextIdx += dir;
          }
          if (nextIdx < 0 || nextIdx >= this.doc.rows.length) return;
          // アンカー〜nextIdx の連続範囲で選択を再構築（排他制御とUI更新は _setTextCellRange 側で行う）
          if (typeof this._setTextCellRange === 'function') this._setTextCellRange(anchorIdx, nextIdx);
          // 次の行のテキストにフォーカス移動（境界端に置く）
          const nextRowEl = this.host?.querySelector(`.sn2-row[data-row-id="${this.doc.rows[nextIdx].id}"]`);
          const nextText = nextRowEl?.querySelector('.sn2-text');
          if (nextText) {
            this._focusText(nextText, isPrev ? 'end' : 'start');
            nextText.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
          }
          return;
        }
        // 非Shift: 視覚的境界行 + 絶対先頭/末尾の判定で 3 段階に分岐
        // (1) 境界行でない (複数行セルの中間行): ブラウザのデフォルト (1 行移動)
        // (2) 境界行 + 絶対先頭/末尾でない: セルの先頭/末尾へジャンプ
        // (3) 境界行 + 絶対先頭/末尾: 隣のセルへ移動
        if (!this._isAtBoundary(text, isPrev)) {
          // 境界行でない: ブラウザに任せる (preventDefault しない)
          return;
        }
        // 境界行内: 絶対先頭/末尾チェック
        // _focusText が range を (textNode, 0) に設定するため、container が
        // element の場合と text node の場合で compareBoundaryPoints が
        // equal を返さない。ここでは (text, 0) から現在位置まで (または
        // 現在位置から text の末端まで) の実テキスト長で判定する。
        const csel = window.getSelection();
        if (!csel?.rangeCount) return;
        const crange = csel.getRangeAt(0);
        let atAbsoluteEdge;
        try {
          const logicalLen = typeof this._logicalTextLenWithBr === 'function'
            ? this._logicalTextLenWithBr(text)
            : this._textLenWithBr(text);
          const caretOffset = this._getTextOffset(text);
          if (caretOffset >= 0) {
            atAbsoluteEdge = isPrev ? caretOffset <= 0 : caretOffset >= logicalLen;
          } else if (isPrev) {
            const ref = document.createRange();
            ref.setStart(text, 0);
            ref.setEnd(crange.startContainer, crange.startOffset);
            atAbsoluteEdge = ref.toString().length === 0;
          } else {
            const ref = document.createRange();
            ref.selectNodeContents(text);
            ref.setStart(crange.endContainer, crange.endOffset);
            atAbsoluteEdge = ref.toString().length === 0;
          }
        } catch (err) { atAbsoluteEdge = false; }
        e.preventDefault();
        if (!atAbsoluteEdge) {
          // 境界行内だが先頭/末尾でない: セルの絶対先頭/末尾へジャンプ
          this._focusText(text, isPrev ? 'start' : 'end');
          return;
        }
        // 既に絶対先頭/末尾: 隣のセルへ移動
        const row = text.closest('.sn2-row');
        let next = isPrev ? row?.previousElementSibling : row?.nextElementSibling;
        // nextがヘッダーや存在しない場合、段を跨いで移動
        if (!next || !next.classList.contains('sn2-row')) {
          next = this._findAdjacentRow(row, isPrev);
        }
        if (!next) return;
        const nextText = next.querySelector('.sn2-text');
        if (nextText) this._focusText(nextText, isPrev ? 'end' : 'start');
        return;
      }

      // PageUp/PageDown: 前後の段に移動（折り返しモード時）
      // 縦書き: PageUp=右の段、PageDown=左の段
      if (e.key === 'PageUp' || e.key === 'PageDown') {
        const isPrev = e.key === 'PageUp';
        const colGroup = text.closest('.sn2-column-group');
        if (!colGroup) return; // 折り返しOFFでは段なし
        e.preventDefault();
        const adjGroup = isPrev ? colGroup.previousElementSibling : colGroup.nextElementSibling;
        if (!adjGroup || !adjGroup.classList.contains('sn2-column-group')) return;
        const caretOffset = this._getTextOffset(text);
        const currentRows = [...colGroup.querySelectorAll('.sn2-row')];
        const currentRow = text.closest('.sn2-row');
        const currentIndex = Math.max(0, currentRows.indexOf(currentRow));
        const rows = adjGroup.querySelectorAll('.sn2-row');
        const target = rows[Math.min(currentIndex, Math.max(0, rows.length - 1))];
        const targetText = target?.querySelector('.sn2-text');
        if (targetText) {
          targetText.focus();
          if (caretOffset >= 0) this._setTextOffset(targetText, Math.min(caretOffset, this._textLenWithBr(targetText)));
          else this._focusText(targetText, isPrev ? 'end' : 'start');
          targetText.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
        }
        return;
      }

      if (e.key === 'Backspace') {
        const sel = window.getSelection();
        if (!sel || !sel.isCollapsed) return;
        if ((sel.anchorNode === text && sel.anchorOffset === 0) ||
            (sel.anchorNode === text.firstChild && sel.anchorOffset === 0) ||
            (!text.textContent && !text.firstChild)) {
          e.preventDefault();
          this._pushUndo('行結合');
          this._mergeWithPrev(text);
          return;
        }
      }

      if (e.key === 'Delete' && !e.shiftKey) {
        const sel = window.getSelection();
        if (!sel || !sel.isCollapsed) return;
        // sel.anchorNode は null / 空テキストノードの末尾など NPE を起こしうるので null チェックを先に入れる
        const anchor = sel.anchorNode;
        const atEnd = (!text.textContent)
          || (!anchor)
          || (anchor === text && sel.anchorOffset >= text.childNodes.length)
          || (anchor.nodeType === 3 && sel.anchorOffset >= (anchor.length || 0) && !anchor.nextSibling);
        if (atEnd) {
          e.preventDefault();
          // セル末尾の改行 (\n / <br>) があればまずそれを削除する。
          // これがないと、text-after ("」" 等) が改行の後ろに描画されて
          // ユーザーから「Delete が効かない」ように見える。
          if (this._hasTrailingLineBreak(text)) {
            this._pushUndo('改行削除');
            this._removeTrailingLineBreak(text);
            this._syncRowFromDom(text);
            this._focusText(text, 'end');
            return;
          }
          this._pushUndo('行結合');
          this._mergeWithNext(text);
          return;
        }
      }

      // Shift+Delete: 現在行を削除
      if (e.key === 'Delete' && e.shiftKey) {
        if (typeof runMeldexShortcutById === 'function' && runMeldexShortcutById('scenario.deleteRow', e)) return;
        e.preventDefault();
        const row = text.closest('.sn2-row');
        if (!row) return;
        const rowId = row.dataset.rowId;
        const idx = this.doc.rows.findIndex(r => r.id === rowId);
        if (idx < 0) return;
        // 最後の1行は削除しない
        if (this.doc.rows.length <= 1) return;
        this._pushUndo('行削除');
        this.doc.rows.splice(idx, 1);
        this._calcCache = null;
        // 隣の行にフォーカス
        const focusIdx = Math.min(idx, this.doc.rows.length - 1);
        const focusId = this.doc.rows[focusIdx].id;
        this._render();
        this._markDirty({ skipUndo: true });
        const focusDeletedNeighbor = () => {
          const nextEl = this.host?.querySelector(`.sn2-row[data-row-id="${focusId}"] .sn2-text`);
          if (nextEl) {
            this._focusText(nextEl, 'start');
            document.dispatchEvent(new Event('selectionchange'));
            if (this._caretSelChangeHandler) this._caretSelChangeHandler();
          }
        };
        focusDeletedNeighbor();
        requestAnimationFrame(focusDeletedNeighbor);
        return;
      }
    });

    // Ctrl+Shift+V: keydownでフラグを立て、pasteハンドラでセル内ペーストに切り替える
    this._pasteInCellFlag = false;
    host.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key.toLowerCase() === 'v') {
        this._pasteInCellFlag = true;
        // pasteイベントが発火しなかった場合のフォールバックリセット
        setTimeout(() => { this._pasteInCellFlag = false; }, 200);
      }
    }, true); // captureフェーズで先に処理

    // pasteハンドラ: 改行で行を分割（空白行はタイプなし空行として追加）
    // Ctrl+Shift+V: セル内改行として貼り付け（行分割しない）
    host.addEventListener('paste', (e) => {
      const pasteInCell = !!this._pasteInCellFlag;
      this._pasteInCellFlag = false;
      const plain = (e.clipboardData?.getData('text/plain') || '').replace(/\r\n?/g, '\n');
      if (!plain) return;
      if (typeof this._handleGridCellPaste === 'function'
          && this._handleGridCellPaste(e, plain, pasteInCell)) return;
      const textEl = e.target.closest?.('.sn2-text');
      if (!textEl) return;
      e.preventDefault();
      const activeSel = window.getSelection();
      const activeRange = activeSel?.rangeCount ? activeSel.getRangeAt(0) : null;
      if (activeRange && !this._rangeWithinElement(activeRange, textEl)) return;
      // Ctrl+Shift+V（フラグ）または単一行: セル内にそのまま挿入
      const lines = plain.split('\n');
      if (pasteInCell || lines.length <= 1) {
        const sel = activeSel || window.getSelection();
        if (!sel?.rangeCount) return;
        const range = activeRange || sel.getRangeAt(0);
        this._pushUndo(pasteInCell ? 'セル内貼り付け' : '貼り付け');
        range.deleteContents();
        range.insertNode(document.createTextNode(plain));
        range.collapse(false);
        sel.removeAllRanges();
        sel.addRange(range);
        this._syncRowFromDom(textEl, { skipUndo: true });
        this._scheduleTextCellLiveResize?.(textEl);
        return;
      }
      // 複数行: 現在行にカーソル前後のテキストを分割し、残りの行を新規追加
      this._pushUndo('複数行ペースト');
      const pasteSel = activeSel || window.getSelection();
      if (activeRange && pasteSel && !pasteSel.isCollapsed) {
        activeRange.deleteContents();
        activeRange.collapse(false);
        pasteSel.removeAllRanges();
        pasteSel.addRange(activeRange);
      }
      this._syncRowFromDom(textEl, { skipUndo: true });
      const pasteCaretOffset = this._getTextOffset(textEl);
      const rowId = textEl.dataset.rowId;
      const idx = this.doc.rows.findIndex(r => r.id === rowId);
      if (idx < 0) return;
      const currentRow = this.doc.rows[idx];
      const sel = window.getSelection();
      let visibleOffset = _sn2StripRubyToPlain(currentRow.text).length;
      if (pasteCaretOffset >= 0) {
        visibleOffset = pasteCaretOffset;
      } else if (sel?.isCollapsed && sel.rangeCount) {
        const pos = this._getTextOffset(textEl);
        if (pos >= 0) visibleOffset = pos;
      }
      const [beforeText, afterText] = _sn2SplitRawTextByVisibleOffset(currentRow.text, visibleOffset);
      const escapedLines = lines.map(line => _sn2EscapeScriptNotePlainText(line));
      // 最初の行は現在行に追加
      currentRow.text = beforeText + escapedLines[0];
      let newStatus = currentRow.status || '';
      if (this._filterStatuses && this._filterStatuses.size === 1) {
        newStatus = [...this._filterStatuses][0];
      }
      // 中間行と最終行を新規行として挿入
      const newRows = [];
      for (let i = 1; i < lines.length; i++) {
        const isLast = i === lines.length - 1;
        const lineText = isLast ? escapedLines[i] + afterText : escapedLines[i];
        const newRow = {
          id: `sn-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          role: lineText ? currentRow.role : '', // 空白行はタイプなし
          status: newStatus,
          text: lineText,
          columns: {},
        };
        if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
          globalThis.GBScriptNoteRoleModel.assignRowRole(
            this.doc,
            newRow,
            lineText ? (currentRow.roleRef || currentRow.role) : ''
          );
        }
        newRows.push(newRow);
      }
      this.doc.rows.splice(idx + 1, 0, ...newRows);
      this._calcCache = null;
      this._render();
      this._markDirty({ skipUndo: true });
      // 最後に追加した行にフォーカス
      const focusLastPastedRow = () => {
        const lastRow = newRows[newRows.length - 1];
        const lastEl = this.host?.querySelector(`.sn2-row[data-row-id="${lastRow.id}"]`);
        const lastText = lastEl?.querySelector('.sn2-text');
        if (lastText) {
          this._focusText(lastText, 'end');
          document.dispatchEvent(new Event('selectionchange'));
          if (this._caretSelChangeHandler) this._caretSelChangeHandler();
        }
      };
      focusLastPastedRow();
      requestAnimationFrame(focusLastPastedRow);
    });

    host.addEventListener('click', (e) => {
      // 自動リンククリック
      const autoLink = e.target.closest?.('.auto-link');
      if (autoLink) {
        const isEditingLink = typeof this._isEditingAutoLinkTarget === 'function'
          ? this._isEditingAutoLinkTarget(autoLink)
          : false;
        if (!isEditingLink && typeof onAutoLinkClick === 'function') {
          e.preventDefault();
          onAutoLinkClick(autoLink, e);
        }
        return;
      }
      const roleBtn = e.target.closest?.('.sn2-role-btn');
      if (roleBtn) {
        e.preventDefault();
        e.stopPropagation();
        this._handleRoleCellClick?.(roleBtn, e);
        return;
      }
      // ハンドルクリック時はD&Dのみ（クリックは何もしない）
    });

    host.addEventListener('dblclick', (e) => {
      const roleBtn = e.target.closest?.('.sn2-role-btn');
      if (!roleBtn) return;
      e.preventDefault();
      e.stopPropagation();
      this._showRoleMenu(roleBtn);
    });

    // テキスト列の右クリックメニュー（＋長押しでも同メニュー）
    const _onScriptnoteRoleCtx = (e) => {
      const roleBtn = e.target.closest?.('.sn2-role-btn');
      if (!roleBtn) return;
      e.preventDefault();
      e.stopPropagation();
      this._showRoleCellContextMenu?.(roleBtn, e);
    };
    host.addEventListener('contextmenu', _onScriptnoteRoleCtx);

    // テキスト列の右クリックメニュー（＋長押しでも同メニュー）
    const _onScriptnoteTextCtx = (e) => {
      const textEl = e.target.closest?.('.sn2-text');
      if (!textEl) return;
      e.preventDefault();
      // 既存ポップアップを閉じる
      document.querySelectorAll('.sn2-context-menu, .sn2-header-popup').forEach(el => el.remove());
      const sel = window.getSelection();
      const hasSelection = sel && !sel.isCollapsed && sel.rangeCount > 0;
      // 選択範囲を保存（メニュー操作で選択が失われる対策）
      const savedRange = hasSelection ? sel.getRangeAt(0).cloneRange() : null;
      const savedText = hasSelection ? sel.toString().trim() : '';
      const commentAnchorEl = {
        getBoundingClientRect: () => {
          const x = Number.isFinite(e.clientX) && e.clientX > 0 ? e.clientX : textEl.getBoundingClientRect().left;
          const y = Number.isFinite(e.clientY) && e.clientY > 0 ? e.clientY : textEl.getBoundingClientRect().top;
          return { left: x, right: x, top: y, bottom: y, width: 0, height: 0 };
        },
      };
      const menu = document.createElement('div');
      menu.className = 'sn2-context-menu sn2-header-popup';
      menu.setAttribute('role', 'menu');
      const mkItem = (label, action, enabled = true, actionId = '') => {
        const btn = document.createElement('button');
        btn.className = 'sn2-header-popup-item';
        btn.type = 'button';
        btn.setAttribute('role', 'menuitem');
        if (actionId) {
          btn.dataset.sn2TextMenuAction = actionId;
          btn.dataset.e2eId = `sn2-text-menu-${actionId}`;
        }
        btn.textContent = label;
        btn.disabled = !enabled;
        if (!enabled) btn.setAttribute('aria-disabled', 'true');
        btn.addEventListener('click', () => {
          menu.remove();
          // 選択範囲を復元してからアクションを実行
          if (savedRange) { sel.removeAllRanges(); sel.addRange(savedRange); }
          action();
        });
        return btn;
      };
      menu.appendChild(mkItem('💬 コメントを追加', () => {
        if (typeof addCommentHere !== 'function') return;
        let override = null;
        try {
          if (typeof CommentBadges !== 'undefined' && typeof CommentBadges.detectCommentContext === 'function') {
            override = CommentBadges.detectCommentContext(textEl);
          }
        } catch (_) { override = null; }
        if (!override || override.targetKind === 'none') {
          const row = textEl.closest?.('.sn2-row[data-row-id]');
          const rowId = row?.dataset?.rowId || '';
          const filePath = this._path || this.doc?.source?.path || '';
          if (rowId && filePath) {
            override = {
              targetKind: 'scriptnote_line',
              filePath,
              targetRef: { file: filePath, lineId: rowId },
              snapshot: (textEl.textContent || '').trim().slice(0, 120),
            };
          }
        }
        addCommentHere(override || undefined, { anchorEl: commentAnchorEl });
      }, true, 'add-comment'));
      menu.appendChild(mkItem('コメント一覧を開く', () => {
        const filePath = this._path || this.doc?.source?.path || '';
        if (filePath && typeof CommentBadges !== 'undefined' && typeof CommentBadges.openPanelForFileComments === 'function') {
          CommentBadges.openPanelForFileComments(filePath);
        }
      }, true, 'open-comments'));
      menu.appendChild(mkItem('ルビ設定…', () => this._insertRuby(), hasSelection, 'ruby'));
      menu.appendChild(mkItem('リンクを挿入...', () => {
        if (typeof showLinkInsertModal === 'function') {
          showLinkInsertModal(savedRange, (result) => {
            if (!textEl.isConnected) return;
            if (typeof this._insertLinkResultIntoText === 'function') { this._insertLinkResultIntoText(textEl, savedRange, result); return; }
            const s = window.getSelection();
            if (result.type === 'file') {
              // savedRange を復元してファイル名を挿入
              if (savedRange) { s.removeAllRanges(); s.addRange(savedRange); }
              this._pushUndo('リンク挿入');
              document.execCommand('insertText', false, result.name);
              // linkDict に追加
              if (typeof linkDict !== 'undefined' && Array.isArray(linkDict)) {
                if (!linkDict.some(d => d.text === result.name && d.path === result.path)) {
                  linkDict.push({ text: result.name, path: result.path });
                }
              }
              this._syncRowFromDom(textEl, { skipUndo: true });
              this._applyAutoLinks(textEl);
            } else if (result.type === 'url') {
              if (savedRange) { s.removeAllRanges(); s.addRange(savedRange); }
              this._pushUndo('リンク挿入');
              document.execCommand('createLink', false, result.url);
              this._syncRowFromDom(textEl, { skipUndo: true });
            }
          });
        }
      }, true, 'insert-link'));
      menu.appendChild(mkItem('切り取り', () => document.execCommand('cut'), hasSelection, 'cut'));
      menu.appendChild(mkItem('コピー', () => document.execCommand('copy'), hasSelection, 'copy'));
      menu.appendChild(mkItem('貼り付け', async () => {
        try {
          const text = await navigator.clipboard.readText();
          const s = window.getSelection();
          if (s?.rangeCount && !this._rangeWithinElement(s.getRangeAt(0), textEl)) return;
          this._pushUndo('貼り付け');
          document.execCommand('insertText', false, text);
          this._syncRowFromDom(textEl, { skipUndo: true });
        } catch { document.execCommand('paste'); }
      }, true, 'paste'));
      menu.appendChild(mkItem('セル内に貼り付け', async () => {
        try {
          const clipText = await navigator.clipboard.readText();
          if (!clipText) return;
          const s = window.getSelection();
          if (!s?.rangeCount) return;
          const r = s.getRangeAt(0);
          if (!this._rangeWithinElement(r, textEl)) return;
          this._pushUndo('セル内貼り付け');
          r.deleteContents();
          r.insertNode(document.createTextNode(clipText));
          r.collapse(false);
          s.removeAllRanges();
          s.addRange(r);
          this._syncRowFromDom(textEl, { skipUndo: true });
        } catch { /* clipboard API unavailable */ }
      }, true, 'paste-in-cell'));
      menu.style.cssText = 'position:fixed;z-index:10000;min-width:140px;';
      const clickRect = { left: e.clientX, right: e.clientX, top: e.clientY, bottom: e.clientY };
      positionPopup(menu, clickRect);
      setTimeout(() => {
        const closeCtx = (ev) => {
          if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener('pointerdown', closeCtx); }
        };
        document.addEventListener('pointerdown', closeCtx);
      }, 0);
    };
    host.addEventListener('contextmenu', _onScriptnoteTextCtx);
    if (typeof addLongPressHandler === 'function') {
      addLongPressHandler(host, _onScriptnoteTextCtx);
    }

    host.addEventListener('focusout', (e) => {
      const text = e.target.closest?.('.sn2-text');
      if (!text) return;
      requestAnimationFrame(() => {
        if (!text.isConnected || !this.host?.contains(text)) return;
        this._syncRowFromDom(text, { skipUndo: true });
        if (typeof this._endTextInputUndo === 'function') this._endTextInputUndo();
      });
    });

    // === 行ドラッグ (pointer events 版) ===
    // HTML5 drag API は仕様上ドラッグ中に wheel イベントをターゲットに届けない
    // (Notion や他モダンエディタが独自実装する理由)。pointer events で自前実装
    // すれば wheel イベントは通常通り動作する。
    // - pointerdown on .sn2-handle: 待機状態。click が動くよう preventDefault は
    //   しない
    // - pointermove: 閾値を超えたらドラッグ開始。ゴースト表示 + 挿入インジ
    //   ケーター + 端オートスクロール
    // - pointerup: ドラッグ中なら drop 実行。ドラッグしていなければ click が
    //   通るので既存の行選択トグルが動く
    let pdragPending = false;
    let pdragActive = false;
    let pdragRowIds = [];
    let pdragStartX = 0, pdragStartY = 0;
    let pdragPointerId = 0;
    let pdragGhost = null;
    let pdragAutoScrollRaf = null;
    let pdragLastClientX = 0, pdragLastClientY = 0;
    const PDRAG_THRESHOLD = 4;

    const pdragAutoScrollStep = () => {
      if (!pdragActive) { pdragAutoScrollRaf = null; return; }
      // ポインタが領域の端を超えて外へ出てもスクロールを止めない:
      // 直下に .sn2-scroll が無ければ自エディタのスクロール領域へフォールバックする
      const clampedX = Math.max(0, Math.min(window.innerWidth - 1, pdragLastClientX));
      const clampedY = Math.max(0, Math.min(window.innerHeight - 1, pdragLastClientY));
      const under = document.elementFromPoint(clampedX, clampedY)?.closest?.('.sn2-scroll');
      const sc = (under && host.contains(under)) ? under : host.querySelector('.sn2-scroll');
      if (!sc) {
        pdragAutoScrollRaf = requestAnimationFrame(pdragAutoScrollStep);
        return;
      }
      const rect = sc.getBoundingClientRect();
      const edge = 80;
      const maxSpeed = 22;
      const speedFor = (dist) => maxSpeed * Math.min(1, Math.max(0, dist / edge));
      const isVertMode = this.doc.editor?.viewMode === 'vertical';
      const isWrap = !!this.doc.editor?.wrapMode;
      let sx = 0, sy = 0;
      if (pdragLastClientX < rect.left + edge) sx = -speedFor(rect.left + edge - pdragLastClientX);
      else if (pdragLastClientX > rect.right - edge) sx = speedFor(pdragLastClientX - (rect.right - edge));
      if (pdragLastClientY < rect.top + edge) sy = -speedFor(rect.top + edge - pdragLastClientY);
      else if (pdragLastClientY > rect.bottom - edge) sy = speedFor(pdragLastClientY - (rect.bottom - edge));
      if (isVertMode && isWrap) {
        if (sc.scrollLeft !== 0) sc.scrollLeft = 0;
        if (sy !== 0) sc.scrollBy({ top: sy });
      } else if (isVertMode || (isWrap && !isVertMode)) {
        if (sx !== 0) sc.scrollBy({ left: sx });
        else if (sy !== 0) sc.scrollBy({ top: sy });
      } else {
        if (sy !== 0) sc.scrollBy({ top: sy });
        else if (sx !== 0) sc.scrollBy({ left: sx });
      }
      pdragAutoScrollRaf = requestAnimationFrame(pdragAutoScrollStep);
    };

    const pdragCleanup = () => {
      pdragPending = false;
      pdragActive = false;
      pdragRowIds = [];
      if (pdragGhost) { pdragGhost.remove(); pdragGhost = null; }
      if (pdragAutoScrollRaf != null) { cancelAnimationFrame(pdragAutoScrollRaf); pdragAutoScrollRaf = null; }
      host.querySelectorAll('.sn2-row').forEach(r => r.classList.remove('sn2-dragging', 'sn2-drop-above', 'sn2-drop-below'));
      try { host.releasePointerCapture(pdragPointerId); } catch {}
    };

    host.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      const handle = e.target.closest?.('.sn2-handle');
      if (!handle) return;
      // チェックボックスクリックはドラッグ対象外
      if (e.target.closest?.('.sn2-row-check')) return;
      const row = handle.closest('.sn2-row');
      if (!row) return;
      pdragPending = true;
      pdragStartX = e.clientX;
      pdragStartY = e.clientY;
      pdragPointerId = e.pointerId;
      const startId = row.dataset.rowId;
      if (this._rowSelection?.size > 1 && this._rowSelection.has(startId)) {
        const sel = this._rowSelection;
        pdragRowIds = this.doc.rows.filter(r => sel.has(r.id)).map(r => r.id);
      } else {
        pdragRowIds = [startId];
      }
      // preventDefault はしない — click が通って _toggleRowSelection が動くように
    });

    host.addEventListener('pointermove', (e) => {
      if (pdragPending && !pdragActive) {
        if (e.pointerId !== pdragPointerId) return;
        const dx = e.clientX - pdragStartX;
        const dy = e.clientY - pdragStartY;
        if (Math.abs(dx) + Math.abs(dy) < PDRAG_THRESHOLD) return;
        // ドラッグ開始
        pdragActive = true;
        try { host.setPointerCapture(pdragPointerId); } catch {}
        const idSet = new Set(pdragRowIds);
        host.querySelectorAll('.sn2-row').forEach(r => {
          if (idSet.has(r.dataset.rowId)) r.classList.add('sn2-dragging');
        });
        // ゴースト表示
        pdragGhost = document.createElement('div');
        pdragGhost.className = 'sn2-pdrag-ghost';
        pdragGhost.textContent = pdragRowIds.length > 1 ? `${pdragRowIds.length} 行を移動` : '行を移動';
        pdragGhost.style.cssText = 'position:fixed;pointer-events:none;z-index:10000;background:var(--accent, #4a90d9);color:white;padding:4px 10px;border-radius:4px;font-size:12px;opacity:0.9;box-shadow:0 2px 8px rgba(0,0,0,0.3);';
        document.body.appendChild(pdragGhost);
      }
      if (!pdragActive) return;
      e.preventDefault();
      pdragLastClientX = e.clientX;
      pdragLastClientY = e.clientY;
      // ゴースト位置更新
      if (pdragGhost) {
        pdragGhost.style.left = (e.clientX + 12) + 'px';
        pdragGhost.style.top = (e.clientY + 12) + 'px';
      }
      // ドロップインジケーター更新
      host.querySelectorAll('.sn2-row').forEach(r => r.classList.remove('sn2-drop-above', 'sn2-drop-below'));
      const overEl = document.elementFromPoint(e.clientX, e.clientY);
      const overRow = overEl?.closest?.('.sn2-row');
      if (overRow && host.contains(overRow) && !pdragRowIds.includes(overRow.dataset.rowId)) {
        const rect = overRow.getBoundingClientRect();
        const isVertMode = this.doc.editor?.viewMode === 'vertical';
        if (isVertMode) {
          // 縦書き: 左右で判定 (画面右側 = 手前 = above)
          overRow.classList.add(e.clientX > rect.left + rect.width / 2 ? 'sn2-drop-above' : 'sn2-drop-below');
        } else {
          overRow.classList.add(e.clientY < rect.top + rect.height / 2 ? 'sn2-drop-above' : 'sn2-drop-below');
        }
      }
      // 端オートスクロールを起動 (初回のみ)
      if (pdragAutoScrollRaf == null) {
        pdragAutoScrollRaf = requestAnimationFrame(pdragAutoScrollStep);
      }
    });

    host.addEventListener('pointerup', (e) => {
      if (!pdragActive) {
        // ドラッグ未開始 (通常クリック): cleanup のみ
        pdragPending = false;
        pdragRowIds = [];
        return;
      }
      if (e.pointerId !== pdragPointerId) return;
      // ドロップ実行
      const overEl = document.elementFromPoint(e.clientX, e.clientY);
      const targetRow = overEl?.closest?.('.sn2-row');
      if (targetRow && host.contains(targetRow) && !pdragRowIds.includes(targetRow.dataset.rowId)) {
        const targetId = targetRow.dataset.rowId;
        const rect = targetRow.getBoundingClientRect();
        const isVertMode = this.doc.editor?.viewMode === 'vertical';
        const insertAfter = isVertMode
          ? e.clientX < rect.left + rect.width / 2
          : e.clientY >= rect.top + rect.height / 2;
        this._pushUndo(pdragRowIds.length > 1 ? '行移動（複数）' : '行移動');
        const draggedSet = new Set(pdragRowIds);
        const moved = pdragRowIds.map(id => this.doc.rows.find(r => r.id === id)).filter(Boolean);
        for (let i = this.doc.rows.length - 1; i >= 0; i--) {
          if (draggedSet.has(this.doc.rows[i].id)) this.doc.rows.splice(i, 1);
        }
        let insertAt = this.doc.rows.findIndex(r => r.id === targetId);
        if (insertAt < 0) insertAt = this.doc.rows.length;
        else if (insertAfter) insertAt++;
        this.doc.rows.splice(insertAt, 0, ...moved);
        this._calcCache = null;
        this._render();
        this._markDirty();
      }
      pdragCleanup();
      // ドラッグ完了後の click をキャンセル (行選択トグルが誤発火するのを防ぐ)
      const suppressClick = (ev) => { ev.stopPropagation(); ev.preventDefault(); document.removeEventListener('click', suppressClick, true); };
      document.addEventListener('click', suppressClick, true);
      // 保険: click が発火しなかった場合に備えて次フレームで解除
      setTimeout(() => document.removeEventListener('click', suppressClick, true), 50);
    });
    host.addEventListener('pointercancel', () => { if (pdragActive || pdragPending) pdragCleanup(); });
  }

  // 段を跨いで隣接する行を取得（折り返しモードでcolumn-groupを越える）
  _findAdjacentRow(currentRow, isPrev) {
    const colGroup = currentRow.closest('.sn2-column-group');
    if (!colGroup) return null;
    const adjGroup = isPrev ? colGroup.previousElementSibling : colGroup.nextElementSibling;
    if (!adjGroup || !adjGroup.classList.contains('sn2-column-group')) return null;
    const rows = adjGroup.querySelectorAll('.sn2-row');
    if (!rows.length) return null;
    return isPrev ? rows[rows.length - 1] : rows[0];
  }

  _isAtBoundary(textEl, isPrev, allowSelection) {
    const sel = window.getSelection();
    if (!sel || sel.rangeCount === 0) return false;
    if (!sel.isCollapsed && !allowSelection) return false;
    // テキスト先頭/末尾のプレーンテキスト判定（rectが取れない場合のフォールバック）
    // 選択中はfocusNode/focusOffsetで判定（anchorは選択の開始点なので移動先ではない）
    const useNode = allowSelection && !sel.isCollapsed ? sel.focusNode : sel.anchorNode;
    const useOff = allowSelection && !sel.isCollapsed ? sel.focusOffset : sel.anchorOffset;
    const isAtTextStart = () => {
      if (useNode === textEl && useOff === 0) return true;
      if (useNode === textEl.firstChild && useOff === 0) return true;
      let first = textEl.firstChild;
      while (first && first.nodeType === 1) first = first.firstChild;
      return first && useNode === first && useOff === 0;
    };
    const isAtTextEnd = () => {
      if (useNode === textEl && useOff >= textEl.childNodes.length) return true;
      if (useNode.nodeType === 3 && useOff >= useNode.length && !useNode.nextSibling) return true;
      let last = textEl.lastChild;
      while (last && last.nodeType === 1) last = last.lastChild;
      return last && useNode === last && useOff >= last.length;
    };
    const logicalOffset = this._getTextOffset(textEl);
    if (logicalOffset >= 0) {
      const logicalLen = typeof this._logicalTextLenWithBr === 'function'
        ? this._logicalTextLenWithBr(textEl)
        : this._textLenWithBr(textEl);
      if (isPrev && logicalOffset <= 0) return true;
      if (!isPrev && logicalOffset >= logicalLen) return true;
    }

    const range = sel.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    const elRect = textEl.getBoundingClientRect();
    const cs = getComputedStyle(textEl);
    const isVertical = this.doc.editor?.viewMode === 'vertical';

    if (isVertical) {
      if (elRect.width <= 0) return true;
      const padRight = parseFloat(cs.paddingRight) || 0;
      const padLeft = parseFloat(cs.paddingLeft) || 0;
      const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.6;
      const contentWidth = elRect.width - padRight - padLeft;
      if (contentWidth <= lh * 1.5) {
        if (allowSelection) return isPrev ? isAtTextStart() : isAtTextEnd();
        return true;
      }
      // rect が取れない場合はテキスト先頭/末尾で判定
      if (rect.width <= 0 && rect.height <= 0) return isPrev ? isAtTextStart() : isAtTextEnd();
      if (isPrev) return rect.right > elRect.right - padRight - lh;
      return rect.left < elRect.left + padLeft + lh;
    }
    // 横書き
    if (elRect.height <= 0) return true;
    const padTop = parseFloat(cs.paddingTop) || 0;
    const padBot = parseFloat(cs.paddingBottom) || 0;
    const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.6;
    const contentHeight = elRect.height - padTop - padBot;
    if (contentHeight <= lh * 1.5) {
      if (allowSelection) return isPrev ? isAtTextStart() : isAtTextEnd();
      return true;
    }
    // rect が取れない場合はテキスト先頭/末尾で判定
    if (rect.width <= 0 && rect.height <= 0) return isPrev ? isAtTextStart() : isAtTextEnd();
    if (isPrev) return rect.top < elRect.top + padTop + lh;
    return rect.bottom > elRect.bottom - padBot - lh;
  }

  _focusText(textEl, place = 'start') {
    textEl.focus();
    const sel = window.getSelection();
    if (!sel) return;
    const range = document.createRange();
    // Chromium の range.getClientRects() は (element, 0) のような要素基準の
    // 位置だとテキストノード基準と異なる rect を返すことがあり、CSS zoom 時に
    // カスタムキャレットの位置がずれる。テキストノードが存在する場合はそれを
    // 基準にして、ネイティブのキャレット測定と同じパスを踏ませる。
    const walker = document.createTreeWalker(textEl, NodeFilter.SHOW_TEXT);
    let targetNode = null;
    let targetOffset = 0;
    if (place === 'start') {
      targetNode = walker.nextNode();
      targetOffset = 0;
    } else {
      let last = null;
      let node;
      while ((node = walker.nextNode())) last = node;
      targetNode = last;
      targetOffset = last ? last.nodeValue.length : 0;
    }
    if (targetNode) {
      range.setStart(targetNode, targetOffset);
      range.collapse(true);
    } else {
      // 空セル: 従来通り要素を指定
      range.selectNodeContents(textEl);
      range.collapse(place === 'start');
    }
    sel.removeAllRanges();
    sel.addRange(range);
  }

  // === 行操作 ===

  _splitRow(textEl, opts) {
    const row = textEl.closest('.sn2-row');
    if (!row) return;
    const rowId = row.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    if (idx < 0) return;

    // ルビ対応: DOMを同期してからテキストを分割
    this._syncRowFromDom(textEl, { skipUndo: true });
    const fullText = this.doc.rows[idx].text;
    const sel = window.getSelection();
    let beforeText = fullText, afterText = '';
    const providedVisibleOffset = Number.isFinite(opts?.visibleOffset) ? opts.visibleOffset : -1;
    if (providedVisibleOffset >= 0 || (sel && sel.isCollapsed && sel.rangeCount > 0)) {
      const visibleOffset = providedVisibleOffset >= 0 ? providedVisibleOffset : this._getTextOffset(textEl);
      if (visibleOffset >= 0) {
        [beforeText, afterText] = _sn2SplitRawTextByVisibleOffset(fullText, visibleOffset);
      }
    }

    this.doc.rows[idx].text = beforeText;

    // タイプ決定: keepRole=trueなら同じタイプ、falseなら空（なし）
    // フィルタで1タイプだけ表示中ならそのタイプを使用
    let newRole = opts?.keepRole ? this.doc.rows[idx].role : '';
    if (this._filterRoles && this._filterRoles.size === 1) {
      newRole = [...this._filterRoles][0];
    }
    let newStatus = this.doc.rows[idx].status || '';
    if (this._filterStatuses && this._filterStatuses.size === 1) {
      newStatus = [...this._filterStatuses][0];
    }
    const newRow = { id: `sn-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, role: newRole, status: newStatus, text: afterText, columns: {} };
    if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
      const roleValue = opts?.keepRole && !this._filterRoles?.size
        ? (this.doc.rows[idx].roleRef || newRole)
        : newRole;
      globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, newRow, roleValue);
    }
    this.doc.rows.splice(idx + 1, 0, newRow);
    this._calcCache = null;
    // ルビ対応: 全体再描画で正しくDOMを構築
    this._render();
    this._markDirty({ skipUndo: true });
    // 新しい行にフォーカス。E2E/高速操作では rAF だけだと次操作が先行するため即時にも反映する。
    const focusNewRow = () => {
      const newRowEl = this.host?.querySelector(`.sn2-row[data-row-id="${newRow.id}"]`);
      const newText = newRowEl?.querySelector('.sn2-text');
      if (newText) {
        this._focusText(newText, 'start');
        document.dispatchEvent(new Event('selectionchange'));
        if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      }
    };
    focusNewRow();
    requestAnimationFrame(focusNewRow);
  }

  _mergeWithPrev(textEl) {
    const row = textEl.closest('.sn2-row');
    if (!row) return;
    let prev = row.previousElementSibling;
    // 折り返しモード: 段の最初の行なら前の段の最後の行を探す
    if (!prev || !prev.classList.contains('sn2-row')) prev = this._findAdjacentRow(row, true);
    if (!prev) return;
    const prevText = prev.querySelector('.sn2-text');
    if (!prevText) return;

    const rowId = row.dataset.rowId;
    const prevId = prev.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    const prevIdx = this.doc.rows.findIndex(r => r.id === prevId);
    if (idx < 0 || prevIdx < 0) return;

    // ルビ対応: DOM同期してからテキスト結合
    this._syncRowFromDom(prevText, { skipUndo: true });
    this._syncRowFromDom(textEl, { skipUndo: true });
    const cursorPos = this.doc.rows[prevIdx].text.length;
    this.doc.rows[prevIdx].text += this.doc.rows[idx].text;
    this.doc.rows.splice(idx, 1);
    this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });
    // 結合位置にカーソル
    const focusMergedRow = () => {
      const newPrevEl = this.host?.querySelector(`.sn2-row[data-row-id="${prevId}"]`);
      const newPrevText = newPrevEl?.querySelector('.sn2-text');
      if (newPrevText) this._focusTextAt(newPrevText, cursorPos);
    };
    focusMergedRow();
    requestAnimationFrame(focusMergedRow);
  }

  // セル末尾に改行 (\n / <br>) があるかを判定する (DOM 変更なし)
  _hasTrailingLineBreak(textEl) {
    if (!textEl) return false;
    let last = textEl.lastChild;
    while (last && last.nodeType === 3 && last.textContent === '') {
      last = last.previousSibling;
    }
    if (!last) return false;
    if (last.nodeType === 3 && last.textContent.endsWith('\n')) return true;
    if (last.nodeType === 1 && last.tagName === 'BR') return true;
    return false;
  }

  _isTerminalSentinelBrNode(node, root) {
    if (!node || node.nodeType !== 1 || node.tagName !== 'BR' || !root) return false;
    let next = node.nextSibling;
    while (next && next.nodeType === 3 && next.textContent === '') next = next.nextSibling;
    if (next) return false;
    let prev = node.previousSibling;
    while (prev && prev.nodeType === 3 && prev.textContent === '') prev = prev.previousSibling;
    return !!(prev && prev.nodeType === 1 && prev.tagName === 'BR' && root.contains(prev));
  }

  _logicalTextLenWithBr(textEl) {
    if (!textEl) return 0;
    const total = this._textLenWithBr(textEl);
    let last = textEl.lastChild;
    while (last && last.nodeType === 3 && last.textContent === '') last = last.previousSibling;
    return this._isTerminalSentinelBrNode(last, textEl) ? Math.max(0, total - 1) : total;
  }

  // セル末尾の末尾改行 (\n / <br>) を 1 段階ぶん削除する。
  // - 最後の text node の末尾が \n ならそれを削除
  // - 最後の子が <br> なら削除。直前も <br> (sentinel との組) なら両方削除して
  //   可視的な改行が 1 回で消えるようにする
  // 何か削除した場合は true を返す
  _removeTrailingLineBreak(textEl) {
    if (!textEl) return false;
    // 末尾の空 text node を掃除
    let last = textEl.lastChild;
    while (last && last.nodeType === 3 && last.textContent === '') {
      const prev = last.previousSibling;
      last.remove();
      last = prev;
    }
    if (!last) return false;
    // 末尾が \n で終わる text node
    if (last.nodeType === 3 && last.textContent.endsWith('\n')) {
      last.textContent = last.textContent.slice(0, -1);
      return true;
    }
    // 末尾が <br>
    if (last.nodeType === 1 && last.tagName === 'BR') {
      const prev = last.previousSibling;
      last.remove();
      // Shift+Enter は <br> (ユーザー改行) + <br> (sentinel) のペアを作るので、
      // 末尾 <br> の前も <br> ならペアとみなして両方削除する
      if (prev && prev.nodeType === 1 && prev.tagName === 'BR') {
        prev.remove();
      }
      return true;
    }
    return false;
  }

  _mergeWithNext(textEl) {
    const row = textEl.closest('.sn2-row');
    if (!row) return;
    let next = row.nextElementSibling;
    // 折り返しモード: 段の最後の行なら次の段の最初の行を探す
    if (!next || !next.classList.contains('sn2-row')) next = this._findAdjacentRow(row, false);
    if (!next) return;
    const nextText = next.querySelector('.sn2-text');
    if (!nextText) return;

    const rowId = row.dataset.rowId;
    const nextId = next.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    const nextIdx = this.doc.rows.findIndex(r => r.id === nextId);
    if (idx < 0 || nextIdx < 0) return;

    // ルビ対応: DOM同期してからテキスト結合
    this._syncRowFromDom(textEl, { skipUndo: true });
    this._syncRowFromDom(nextText, { skipUndo: true });
    const cursorPos = this.doc.rows[idx].text.length;
    this.doc.rows[idx].text += this.doc.rows[nextIdx].text;
    this.doc.rows.splice(nextIdx, 1);
    this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });
    const focusMergedRow = () => {
      const newRowEl = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
      const newText = newRowEl?.querySelector('.sn2-text');
      if (newText) this._focusTextAt(newText, cursorPos);
    };
    focusMergedRow();
    requestAnimationFrame(focusMergedRow);
  }

  _focusTextAt(textEl, offset) {
    textEl.focus();
    this._setTextOffset(textEl, offset);
    document.dispatchEvent(new Event('selectionchange'));
    if (this._caretSelChangeHandler) this._caretSelChangeHandler();
  }

  _updateGuttersFrom(startIdx) {
    const calc = this._calcPagePanel();
    const cc = this.doc.editor?.countConfig || {};
    const rows = this.host.querySelectorAll('.sn2-row');
    const isVert = this.doc.editor?.viewMode === 'vertical';
    const mergeDisplay = !!this.doc.editor?.mergeDisplay;
    const clearCc = (el) => { delete el.dataset.ccBg; delete el.dataset.ccColor; delete el.dataset.ccWeight; delete el.dataset.ccSize; };
    const setCc = (el, gs) => { if (gs.bgColor) el.dataset.ccBg = gs.bgColor; if (gs.textColor) el.dataset.ccColor = gs.textColor; if (gs.fontWeight) el.dataset.ccWeight = gs.fontWeight; if (gs.fontSize) el.dataset.ccSize = gs.fontSize; };
    let prevVisibleCalc = null;
    for (const rowEl of rows) {
      const rowId = rowEl.dataset.rowId;
      const docIdx = this.doc.rows.findIndex(r => r.id === rowId);
      if (docIdx < 0) continue;
      const rowCalc = calc[docIdx];
      if (!rowCalc) continue;
      const prevCalc = prevVisibleCalc;
      if (docIdx >= startIdx) {
        // 大区切り（primary）
        const gutter = rowEl.querySelector('.sn2-gutter:not(.sn2-gutter2)');
        if (gutter) {
          const gutterText = this._formatGutterPrimary(rowCalc);
          const prevGutterText = (mergeDisplay && prevCalc) ? this._formatGutterPrimary(prevCalc) : '';
          const showGutterText = !(mergeDisplay && gutterText === prevGutterText);
          gutter.textContent = showGutterText ? gutterText : '';
          // 縦書き: 半角英数字を縦中横に再ラップ (textContent 設定で tcy span が消えるため)
          if (isVert) this._wrapTcy(gutter, 'sn2-tcy-wide');
          clearCc(gutter);
          if (showGutterText && cc.primaryStyle) setCc(gutter, cc.primaryStyle);
        }
        // 小区切り（secondary）
        const gutter2 = rowEl.querySelector('.sn2-gutter2');
        if (gutter2) {
          const gutter2Text = this._formatGutterSecondary(rowCalc);
          const prevGutter2Text = (mergeDisplay && prevCalc) ? this._formatGutterSecondary(prevCalc) : '';
          const showGutter2Text = !(mergeDisplay && gutter2Text === prevGutter2Text);
          gutter2.textContent = showGutter2Text ? gutter2Text : '';
          if (isVert) this._wrapTcy(gutter2, 'sn2-tcy-wide');
          clearCc(gutter2);
          if (showGutter2Text && cc.secondaryStyle) setCc(gutter2, cc.secondaryStyle);
        }
        // スタイル再適用
        const row = this.doc.rows[docIdx];
        if (row) this._applyRowStyle(rowEl, row.role);
      }
      prevVisibleCalc = rowCalc;
    }
  }

  // === タイプ選択メニュー → gb-scriptnote-menu.js に移動 ===

  // === DOM同期 ===

  _beginTextInputUndo(label = '編集') {
    if (!this._textInputUndoOpen) {
      this._pushUndo(label);
      this._textInputUndoOpen = true;
    }
    if (this._textInputUndoTimer) clearTimeout(this._textInputUndoTimer);
    this._textInputUndoTimer = setTimeout(() => {
      this._textInputUndoTimer = null;
      this._textInputUndoOpen = false;
    }, 1000);
  }

  _endTextInputUndo() {
    if (this._textInputUndoTimer) {
      clearTimeout(this._textInputUndoTimer);
      this._textInputUndoTimer = null;
    }
    this._textInputUndoOpen = false;
  }

  _syncRowFromDom(textEl, options = {}) {
    const rowId = textEl.dataset.rowId;
    const row = this.doc.rows.find(r => r.id === rowId);
    if (!row) return;
    // ルビスパンを {漢字|ルビ} 形式に変換（自動ルビはスキップ）。
    // プレーンテキスト部分は `\` `{` `|` `}` をエスケープして保存する（復元時に逆変換される）。
    let text = '';
    const walk = (node) => {
      if (node.nodeType === 3) { text += _sn2EscapeScriptNotePlainText(node.textContent); return; }
      if (node.nodeType === 1) {
        if (node.dataset?.manualLink && node.dataset?.path && typeof this._formatManualLinkMarkup === 'function') {
          text += this._formatManualLinkMarkup(node.textContent, node.dataset.path);
          return;
        }
        // 自動ルビ・自動リンクはテキストのみ出力（マークアップを保存しない）
        if (node.dataset?.autoRuby || node.dataset?.autoLink) { text += _sn2EscapeScriptNotePlainText(node.textContent); return; }
        if (node.dataset?.ruby) {
          text += `{${_sn2EscapeRubyText(node.textContent)}|${_sn2EscapeRubyText(node.dataset.ruby)}}`;
          return;
        }
        if (node.tagName === 'BR') {
          if (!this._isTerminalSentinelBrNode(node, textEl)) text += '\n';
          return;
        }
        node.childNodes.forEach(walk);
      }
    };
    textEl.childNodes.forEach(walk);
    text = text.replace(/\u00A0/g, ' ');
    if (row.text !== text) {
      const wasEmpty = !row.text;
      const nowEmpty = !text;
      row.text = text;
      if (wasEmpty !== nowEmpty) this._calcCache = null;
      this._markDirty(options.skipUndo ? { skipUndo: true } : {});
    }
  }

  _syncAllFromDom() {
    if (!this.host) return;
    // sync-from-dom の最中に _markDirty → _pushUndo → _syncAllFromDom の再発火ループが
    // 起きないようガードフラグで抑制する
    this._inSyncingFromDom = true;
    try {
      this.host.querySelectorAll('.sn2-text').forEach(el => this._syncRowFromDom(el));
    } finally {
      this._inSyncingFromDom = false;
    }
  }

  // B-MANGA と同じJIS系配置・隣接衝突解決をCSS座標へ反映する。
  _adjustRubySpacing() {
    if (!this.host) return;
    const model = typeof MeldexRubyPresentation !== 'undefined' ? MeldexRubyPresentation : null;
    if (!model) return;
    model.refreshRubyNodes(this);
    const presentation = model.ensureDocument(this.doc);
    const isVertical = this.doc?.editor?.viewMode === 'vertical';
    const spans = this.host.querySelectorAll('.sn2-text [data-ruby]');
    if (!spans.length) return;
    const z = typeof _getZoom === 'function' ? _getZoom() : 1;
    const rows = new Map();
    const spanToInfo = new Map();
    spans.forEach((span, index) => {
      const rect = span.getBoundingClientRect();
      const parentStart = (isVertical ? rect.top : rect.left) / z;
      const parentEnd = (isVertical ? rect.bottom : rect.right) / z;
      const rubyText = span.dataset.rubyRendered || span.dataset.ruby;
      const baseEm = parseFloat(getComputedStyle(span).fontSize) || 16;
      const info = model.createRubyLayoutInfo({
        parentStart,
        parentEnd,
        baseEm,
        rubyText,
        presentation,
        style: span.dataset.rubyStyle,
      });
      info.span = span;
      info.groupId = span.dataset.rubyGroupId || `span-${index}`;
      const crossStart = (isVertical ? rect.left : rect.top) / z;
      const lineKey = Math.round(crossStart * 2) / 2;
      info._lineKey = lineKey;
      if (!rows.has(lineKey)) rows.set(lineKey, []);
      rows.get(lineKey).push(info);
      spanToInfo.set(span, info);
      const crossSize = (isVertical ? rect.width : rect.height) / z;
      span.style.setProperty('--sn2-ruby-base-edge', ((crossSize + baseEm) * 0.5) + 'px');
      span.style.marginLeft = '';
      span.style.marginTop = '';
    });
    this._appendAfterTextRubyBoundaries(rows, spanToInfo, isVertical, z);
    rows.forEach(infos => {
      model.resolveRubyOverlaps(infos).forEach(info => {
        if (!info.span) return;
        const layout = model.finalizeRubyLayout(info);
        if (!layout) return;
        const style = info.span.style;
        style.setProperty('--sn2-ruby-inline-start', layout.inlineStartPx + 'px');
        style.setProperty('--sn2-ruby-layout-extent', layout.extentPx + 'px');
        style.setProperty('--sn2-ruby-size-override', layout.fontSizePx + 'px');
        style.setProperty('--sn2-ruby-effective-letter-spacing', layout.letterSpacingPx + 'px');
        style.setProperty('--sn2-ruby-gap-px', layout.gapPx + 'px');
      });
    });
  }

  // 後の文字列（data-after）は::afterで描画され重なり解決の対象外だったため、
  // 最終文字のルビが閉じ括弧等に被る不具合があった。占有幅を「動かせない境界」
  // (span:null, minExtent===extent) として同じ行のresolveRubyOverlapsに参加させる。
  _appendAfterTextRubyBoundaries(rows, spanToInfo, isVertical, z) {
    this.host.querySelectorAll('.sn2-text[data-after]:not(:empty)').forEach(textEl => {
      const rubySpans = textEl.querySelectorAll('[data-ruby]');
      if (!rubySpans.length) return;
      const info = spanToInfo.get(rubySpans[rubySpans.length - 1]);
      if (!info || info._lineKey === undefined) return;
      const boundary = this._measureAfterTextRubyBoundary(textEl, isVertical, z);
      if (boundary) rows.get(info._lineKey)?.push(boundary);
    });
  }

  // data-after の実際の描画幅は::afterのため直接測れない。同じフォント文脈の
  // 子要素として一時的に不可視計測し、直後に取り除く（DOM変更は無し扱い）。
  _measureAfterTextRubyBoundary(textEl, isVertical, z) {
    const afterText = textEl.dataset.after || '';
    const lastChild = textEl.lastChild;
    if (!afterText || !lastChild) return null;
    // 末尾がルビ等のinline-block要素だと、その直後に collapse したRangeの矩形が
    // 0になるブラウザ実装があるため、要素なら要素自身の矩形を終端とする。
    let endRect;
    if (lastChild.nodeType === Node.TEXT_NODE) {
      const endRange = document.createRange();
      endRange.selectNodeContents(textEl);
      endRange.collapse(false);
      endRect = endRange.getBoundingClientRect();
    } else {
      endRect = lastChild.getBoundingClientRect();
    }
    const probe = document.createElement('span');
    probe.textContent = afterText;
    probe.style.cssText = 'position:absolute;visibility:hidden;white-space:nowrap;left:-9999px;top:-9999px;';
    textEl.appendChild(probe);
    const probeRect = probe.getBoundingClientRect();
    probe.remove();
    const afterSize = (isVertical ? probeRect.height : probeRect.width) / z;
    if (!(afterSize > 0)) return null;
    const parentStart = (isVertical ? endRect.bottom : endRect.right) / z;
    return {
      parentStart,
      parentEnd: parentStart + afterSize,
      parentSpan: afterSize,
      parentCenter: parentStart + afterSize / 2,
      baseEm: 0,
      rubyEm: 0,
      count: 0,
      text: '',
      style: '',
      align: 'start',
      extent: afterSize,
      minExtent: afterSize,
      effectiveLetterSpacing: 0,
      condense: 1,
      gapPx: 0,
      groupId: '__sn2-after-boundary__',
      span: null,
    };
  }

  // 自動ルビルールをテキスト要素に適用（表示のみ、data-auto-ruby属性で識別）
  _applyAutoRuby(textEl) {
    const rules = this.doc?.rubyRules;
    // 既存の自動ルビを除去（再適用時の二重表示を防止）
    textEl.querySelectorAll('[data-auto-ruby]').forEach(span => {
      span.replaceWith(document.createTextNode(span.textContent));
    });
    textEl.normalize();
    if (!rules || !rules.length) return;
    // 既にルビが付いているテキストを避けるため、テキストノードのみを対象にする
    const textNodes = [];
    const collectTextNodes = (node) => {
      if (node.nodeType === 3 && node.textContent) textNodes.push(node);
      else if (node.nodeType === 1 && !node.dataset?.ruby && !node.dataset?.autoRuby) {
        node.childNodes.forEach(collectTextNodes);
      }
    };
    collectTextNodes(textEl);
    for (const tNode of textNodes) {
      let content = tNode.textContent;
      let matched = false;
      const frag = document.createDocumentFragment();
      let lastIdx = 0;
      // 全ルールをテキスト内で検索（先に見つかった位置優先）
      while (lastIdx < content.length) {
        let earliest = null;
        for (const rule of rules) {
          if (!rule.text || !rule.ruby) continue;
          const pos = content.indexOf(rule.text, lastIdx);
          if (pos >= 0 && (!earliest || pos < earliest.pos || (pos === earliest.pos && rule.text.length > earliest.rule.text.length))) {
            earliest = { pos, rule };
          }
        }
        if (!earliest) break;
        matched = true;
        if (earliest.pos > lastIdx) frag.appendChild(document.createTextNode(content.slice(lastIdx, earliest.pos)));
        const span = document.createElement('span');
        span.dataset.ruby = earliest.rule.ruby;
        if (['group', 'mono', 'jukugo'].includes(earliest.rule.style)) {
          span.dataset.rubyStyle = earliest.rule.style;
          span.dataset.rubyStyleSource = 'rule';
        }
        span.dataset.autoRuby = 'true';
        span.textContent = earliest.rule.text;
        frag.appendChild(span);
        lastIdx = earliest.pos + earliest.rule.text.length;
      }
      if (matched) {
        if (lastIdx < content.length) frag.appendChild(document.createTextNode(content.slice(lastIdx)));
        tNode.parentNode.replaceChild(frag, tNode);
      }
    }
  }

  // D&D: テキストセルへのファイル/ノードドロップハンドラ
  _setupTextCellDrop(textDiv) {
    textDiv.addEventListener('dragover', (e) => {
      if (MeldexDnD.isPanelDnD(e.dataTransfer.types, e.ctrlKey)) return;
      if (!e.dataTransfer.types.includes('application/x-meldex-node') &&
          !e.dataTransfer.types.includes('application/x-annotation') &&
          !e.dataTransfer.types.includes('application/x-cal-event')) return;
      e.preventDefault();
      e.stopPropagation();
      MeldexDnD.showDropCaret(textDiv, e);
    });
    textDiv.addEventListener('dragleave', (e) => {
      if (!textDiv.contains(e.relatedTarget)) MeldexDnD.hideDropCaret(textDiv);
    });
    textDiv.addEventListener('drop', (e) => {
      if (MeldexDnD.isPanelDnD(e.dataTransfer.types, e.ctrlKey)) return;
      e.preventDefault();
      e.stopPropagation();
      MeldexDnD.hideDropCaret(textDiv);
      MeldexDnD.setCaretFromPoint(e);

      const nodeData = MeldexDnD.parseMeldexNode(e);
      if (nodeData) {
        if (typeof this._insertLinkResultIntoText === 'function') {
          this._insertLinkResultIntoText(textDiv, null, { type: 'file', name: nodeData.name, path: nodeData.path });
          return;
        }
        // ファイル名テキストを挿入し、linkDict に登録して自動リンク化
        const { name, path } = nodeData;
        this._pushUndo('リンク挿入');
        document.execCommand('insertText', false, name);
        if (typeof linkDict !== 'undefined' && Array.isArray(linkDict)) {
          if (!linkDict.some(d => d.text === name && d.path === path)) {
            linkDict.push({ text: name, path });
          }
        }
        this._syncRowFromDom(textDiv, { skipUndo: true });
        this._applyAutoLinks(textDiv);
        return;
      }

      const annData = e.dataTransfer.getData('application/x-annotation');
      if (annData) {
        try {
          const ann = JSON.parse(annData);
          this._pushUndo('注釈テキスト挿入');
          document.execCommand('insertText', false, ann.text || '[メモ]');
          this._syncRowFromDom(textDiv, { skipUndo: true });
        } catch {}
        return;
      }

      const calData = e.dataTransfer.getData('application/x-cal-event');
      if (calData) {
        const text = e.dataTransfer.getData('text/plain') || '[イベント]';
        this._pushUndo('イベントテキスト挿入');
        document.execCommand('insertText', false, text);
        this._syncRowFromDom(textDiv, { skipUndo: true });
        return;
      }
    });
  }

  // 自動リンク（linkDict）をテキスト要素に適用（表示のみ、data-auto-link属性で識別）
  _applyAutoLinks(textEl) {
    if (typeof MeldexAutoLink !== 'undefined') {
      MeldexAutoLink.applyToDom(textEl, this._path || this.doc?.source?.path || '');
    }
  }

  _markDirty(options = {}) {
    this._dirty = true;
    this._scheduleSave();
    // sync-from-dom の最中（= 既に _pushUndo 処理中のフラッシュ経路）では
    // デバウンス undo を仕込み直さない。再発火ループ防止。
    if (this._inSyncingFromDom) return;
    // テキスト入力のundoは500msデバウンス（skipUndo指定時はスキップ）
    if (!options.skipUndo) {
      if (this._undoTimer) clearTimeout(this._undoTimer);
      this._undoTimer = setTimeout(() => { this._undoTimer = null; this._pushUndo('編集'); }, 500);
    }
  }

  _scheduleSave() {
    if (typeof markAutoVersionDirty === 'function') markAutoVersionDirty();
    if (this._saveTimer) clearTimeout(this._saveTimer);
    this._saveTimer = setTimeout(() => { this._saveTimer = null; this.save(); }, 2000);
  }

  // === Undo/Redo → gb-scriptnote-history.js に移動 ===

  // === 行の複数選択 → gb-scriptnote-selection.js に移動 ===

  // === 詳細パネル → gb-scriptnote-detail.js に移動 ===
  // === 列リサイズ・カスタム列 → gb-scriptnote-columns.js に移動 ===

  // === フィルタ → gb-scriptnote-filter.js に移動 ===

  // === ルビ ===

  _insertRuby() {
    const context = this._rubySelectionContext();
    if (!context) return;
    // ルビ入力は文字列選択時の書式設定ポップアップへ統合済み。
    // 書式設定ポップアップが使えない環境（単独シナリオアプリ、Cloudモバイル編集UI等）だけ
    // 従来のルビ専用ポップアップを開く
    if (window.GBTextSelectionFormat?.openForSelection) {
      window.GBTextSelectionFormat.openForSelection({ focusRuby: true, force: true });
      if (document.querySelector('.gb-text-selection-fmt [data-e2e-id="sn2-ruby-input"]')) return;
    }
    this._openLegacyRubyPopup(context);
  }

  // ルビ挿入可能な選択状態なら { sel, range, text, textEl } を返す（単一テキストセル内の非空選択のみ）
  _rubySelectionContext() {
    const sel = window.getSelection();
    if (!sel || sel.isCollapsed || !sel.rangeCount) return null;
    const text = sel.toString().trim();
    if (!text) return null;
    const range = sel.getRangeAt(0);
    const textEl = range.startContainer.closest?.('.sn2-text') || range.startContainer.parentElement?.closest?.('.sn2-text');
    if (!textEl || !this._rangeWithinElement(range, textEl)) return null;
    return { sel, range, text, textEl };
  }

  // 選択範囲をルビスパンへ置き換えて保存・表示を更新する（レガシーポップアップと
  // 書式設定ポップアップ内ルビ入力の共通経路）。挿入できたら true
  _applyRubyToSelection(range, textEl, ruby, addRule) {
    if (!range || !textEl || !ruby) return false;
    const text = range.toString().trim();
    if (!text) return false;
    this._pushUndo('ルビ追加');
    // 選択範囲を削除してルビスパンを挿入（インラインstyleはCSSに任せる）
    range.deleteContents();
    const rubyNode = document.createElement('span');
    rubyNode.dataset.ruby = ruby;
    rubyNode.textContent = text;
    range.insertNode(rubyNode);
    // insertNodeが作る空テキストノードを除去して改行を防止
    textEl.normalize();
    const sel = window.getSelection();
    if (sel) {
      sel.removeAllRanges();
      const newRange = document.createRange();
      newRange.setStartAfter(rubyNode);
      newRange.collapse(true);
      sel.addRange(newRange);
    }
    // DOMからrow.textに同期（ルビマークアップ {漢字|ルビ} をrow.textに保存）
    this._syncRowFromDom(textEl, { skipUndo: true });
    // 自動ルビルールにも追加
    if (addRule) {
      if (!this.doc.rubyRules) this.doc.rubyRules = [];
      const exists = this.doc.rubyRules.some(r => r.text === text && r.ruby === ruby);
      if (!exists) this.doc.rubyRules.push({ text, ruby, auto: true });
    }
    this._markDirty({ skipUndo: true });
    if (typeof MeldexRubyPresentation !== 'undefined') MeldexRubyPresentation.refreshRubyNodes(this);
    this._adjustRubySpacing();
    return true;
  }

  _openLegacyRubyPopup(context) {
    const { range, text, textEl } = context;
    if (typeof this._closeRubyPopup === 'function') this._closeRubyPopup({ restoreFocus: false });
    // ルビ入力ポップアップ
    const popup = document.createElement('div');
    popup.className = 'sn2-header-popup sn2-ruby-popup';
    popup.dataset.e2eId = 'sn2-ruby-popup';
    popup.setAttribute('role', 'dialog');
    popup.setAttribute('aria-modal', 'false');
    popup.setAttribute('aria-labelledby', 'sn2-ruby-label');

    const title = document.createElement('div');
    title.id = 'sn2-ruby-label';
    title.className = 'sn2-ruby-popup-title';
    title.dataset.e2eId = 'sn2-ruby-label';
    title.textContent = `「${text.slice(0, 20)}」にルビを追加`;

    const mainRow = document.createElement('div');
    mainRow.className = 'sn2-ruby-popup-main';
    const input = document.createElement('input');
    input.type = 'text';
    input.id = 'sn2-ruby-input';
    input.className = 'gb-input-sm sn2-ruby-popup-input';
    input.dataset.e2eId = 'sn2-ruby-input';
    input.placeholder = 'ルビを入力...';
    input.setAttribute('aria-label', '選択文字のルビ');
    // 開くと同時に自動フォーカスされるため、フォーカス由来のツールチップは出さない
    input.setAttribute('data-gb-tooltip-disabled', 'true');
    const okButton = document.createElement('button');
    okButton.type = 'button';
    okButton.id = 'sn2-ruby-ok';
    okButton.className = 'gb-btn gb-btn-sm gb-btn-primary primary sn2-ruby-popup-ok';
    okButton.dataset.e2eId = 'sn2-ruby-ok';
    okButton.textContent = '追加';
    mainRow.append(input, okButton);

    const optionRow = document.createElement('div');
    optionRow.className = 'sn2-ruby-popup-options';
    const addRuleLabel = document.createElement('label');
    addRuleLabel.className = 'gb-check sn2-ruby-popup-check';
    addRuleLabel.dataset.e2eId = 'sn2-ruby-add-rule-label';
    const addRuleInput = document.createElement('input');
    addRuleInput.type = 'checkbox';
    addRuleInput.id = 'sn2-ruby-add-rule';
    addRuleInput.className = 'gb-checkbox';
    addRuleInput.dataset.e2eId = 'sn2-ruby-add-rule';
    const addRuleText = document.createElement('span');
    addRuleText.textContent = '自動ルビルールにも追加';
    addRuleLabel.append(addRuleInput, addRuleText);
    const autoButton = document.createElement('button');
    autoButton.type = 'button';
    autoButton.id = 'sn2-ruby-auto';
    autoButton.className = 'gb-btn gb-btn-sm gb-btn-quiet sn2-ruby-popup-auto';
    autoButton.dataset.e2eId = 'sn2-ruby-auto';
    autoButton.textContent = '読み取得';
    // 選択時書式ポップアップのルビ行と同じ並び（読み取得 → ルール追加）に揃える
    optionRow.append(autoButton, addRuleLabel);
    popup.append(title, mainRow, optionRow);
    const rr = range.getBoundingClientRect();
    popup.style.cssText += 'position:fixed;z-index:10000;min-width:240px;';
    positionPopup(popup, rr);
    input.focus();
    let closeHandler = null;
    let keyHandler = null;
    const restoreFocus = () => {
      if (!textEl?.isConnected) return;
      // 遅延実行の間に別のポップアップ等がフォーカスを取った場合は奪い返さない
      const ae = document.activeElement;
      if (ae && ae !== document.body && ae !== textEl && !textEl.contains(ae)) return;
      try { textEl.focus({ preventScroll: true }); }
      catch { textEl.focus(); }
    };
    const closeRubyPopup = (options = {}) => {
      popup.remove();
      if (closeHandler) document.removeEventListener('pointerdown', closeHandler);
      if (keyHandler) document.removeEventListener('keydown', keyHandler);
      if (this._rubyPopup === popup) {
        this._rubyPopup = null;
        this._closeRubyPopup = null;
      }
      if (options.restoreFocus !== false) {
        restoreFocus();
        requestAnimationFrame(restoreFocus);
      }
    };
    this._rubyPopup = popup;
    this._closeRubyPopup = closeRubyPopup;
    const apply = (ruby) => {
      if (!ruby) { closeRubyPopup(); return; }
      this._applyRubyToSelection(range, textEl, ruby, addRuleInput.checked);
      closeRubyPopup();
    };
    okButton.addEventListener('click', () => apply(input.value.trim()));
    input.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        ev.stopPropagation();
        apply(input.value.trim());
      }
      if (ev.key === 'Escape') {
        ev.preventDefault();
        ev.stopPropagation();
        closeRubyPopup();
      }
    });
    autoButton.addEventListener('click', async () => {
      try {
        const res = await apiFetch('/ruby?text=' + encodeURIComponent(text));
        if (res?.ruby) input.value = res.ruby;
        else if (typeof showStatus === 'function') showStatus('この語の読みは設定に登録されていません', true);
      } catch (err) {
        if (typeof showStatus === 'function') showStatus('自動ルビエラー: ' + err.message, true);
      }
    });
    closeHandler = (ev) => { if (!popup.contains(ev.target)) closeRubyPopup(); };
    keyHandler = (ev) => {
      // Tab / Shift+Tab はポップアップ内の項目切り替え（選択時書式ポップアップと同じ挙動）
      if (ev.key === 'Tab') {
        ev.preventDefault();
        ev.stopPropagation();
        if (typeof gbCyclePopupFocus === 'function') gbCyclePopupFocus(popup, ev.shiftKey);
        return;
      }
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closeRubyPopup();
    };
    document.addEventListener('keydown', keyHandler);
    setTimeout(() => document.addEventListener('pointerdown', closeHandler), 0);
  }

  // === 破棄 ===

  destroy() {
    this._closeRoleMenu();
    if (typeof this._closeRubyPopup === 'function') this._closeRubyPopup({ restoreFocus: false });
    if (this._saveTimer) { clearTimeout(this._saveTimer); this._saveTimer = null; }
    if (this._undoTimer) { clearTimeout(this._undoTimer); this._undoTimer = null; }
    if (this._textInputUndoTimer) { clearTimeout(this._textInputUndoTimer); this._textInputUndoTimer = null; }
    if (typeof this._teardownWrapResizeObserver === 'function') this._teardownWrapResizeObserver();
    if (typeof this._stopRowBulkBarGuard === 'function') this._stopRowBulkBarGuard();
    // エディタレジストリから除去
    if (typeof _sn2Editors !== 'undefined') {
      const registeredPath = this._sn2RegisteredPath || this._path;
      const registeredScopeId = this._sn2RegisteredScopeId || this._historyScopeId;
      if (registeredPath && _sn2Editors[registeredPath] === this) delete _sn2Editors[registeredPath];
      if (registeredScopeId && _sn2Editors[registeredScopeId] === this) delete _sn2Editors[registeredScopeId];
    }
    if (this._caretSelChangeHandler) { document.removeEventListener('selectionchange', this._caretSelChangeHandler); this._caretSelChangeHandler = null; }
    if (this._copyHandler) { document.removeEventListener('copy', this._copyHandler); this._copyHandler = null; }
    if (typeof this._dragSelectionDocCleanup === 'function') {
      this._dragSelectionDocCleanup();
      this._dragSelectionDocCleanup = null;
    }
    // document.body上のフロートバー・一時UIを除去
    document.querySelectorAll('.sn2-row-bulk-bar, .gb-fmt-popup--bulk-edit, .sn2-drag-select-rect').forEach(el => el.remove());
    // セル範囲選択の表示クラスを除去（セル要素自体は残す。他インスタンスに影響しないようhost配下に限定）
    this.host?.querySelectorAll('.sn2-text-cell-selected, .sn2-grid-cell-selected').forEach(el => {
      el.classList.remove('sn2-text-cell-selected', 'sn2-grid-cell-selected');
    });
    if (this.host) this.host.innerHTML = '';
    this._bound = false;
  }
}

// Clip Studio / SEP 連携は gb-scriptnote-clipstudio.js に分離

;

/* === gb-scriptnote-history.js === */
;
/* gb-scriptnote-history.js: シナリオの Undo/Redo とスナップショット復元 */

function _sn2FindRowFromNode(node) {
  if (!node) return null;
  const el = node.nodeType === 3 ? node.parentElement : node;
  return el?.closest?.('.sn2-row') || null;
}

function _sn2CaptureSnapshotFocus(editor) {
  let focusRowId = null;
  let focusRowIdx = -1;
  try {
    const sel = window.getSelection();
    const activeElement = document.activeElement;
    const activeRow = _sn2FindRowFromNode(activeElement)
      || _sn2FindRowFromNode(sel?.anchorNode)
      || _sn2FindRowFromNode(sel?.focusNode);
    if (activeRow && editor.host?.contains(activeRow)) {
      focusRowId = activeRow.dataset.rowId || null;
      if (focusRowId) focusRowIdx = editor.doc.rows.findIndex((row) => row.id === focusRowId);
    }
  } catch {}
  return { focusRowId, focusRowIdx };
}

function _sn2FindRestoreTarget(editor, focusState) {
  if (!editor.host) return null;
  const { focusRowId, focusRowIdx } = focusState || {};
  if (focusRowId) {
    const byId = editor.host.querySelector(`.sn2-row[data-row-id="${focusRowId}"] .sn2-text`);
    if (byId) return byId;
  }
  if (focusRowIdx >= 0 && Array.isArray(editor.doc.rows) && editor.doc.rows.length) {
    const tryIdx = (index) => {
      if (index < 0 || index >= editor.doc.rows.length) return null;
      const rowId = editor.doc.rows[index]?.id;
      if (!rowId) return null;
      return editor.host.querySelector(`.sn2-row[data-row-id="${rowId}"] .sn2-text`);
    };
    return tryIdx(focusRowIdx - 1)
      || tryIdx(focusRowIdx)
      || tryIdx(Math.min(focusRowIdx, editor.doc.rows.length - 1))
      || tryIdx(editor.doc.rows.length - 1);
  }
  return editor.host.querySelector('.sn2-row .sn2-text');
}

let _sn2HistoryScopeSeq = 0;
function _sn2NewHistoryScopeId() {
  _sn2HistoryScopeSeq += 1;
  return 'sn-' + Date.now().toString(36) + '-' + _sn2HistoryScopeSeq.toString(36) + '-' + Math.random().toString(36).slice(2, 7);
}

Object.assign(ScriptNoteEditor.prototype, {

  _takeSnapshot() {
    return JSON.stringify(serializeScriptNoteDoc(this.doc));
  },

  _historyScope() {
    if (!this._historyScopeId) {
      this._historyScopeId = _sn2NewHistoryScopeId();
      this._historyScopePath = this._path || '';
    }
    return 'scriptnote:' + this._historyScopeId;
  },

  _pushUndo(label = '') {
    if (this._pushUndoSuppressed) return;
    if (this._undoTimer) {
      clearTimeout(this._undoTimer);
      this._undoTimer = null;
    }
    this._syncAllFromDom();
    const snap = this._takeSnapshot();
    if (this._lastPushedSnap === snap) return;
    this._lastPushedSnap = snap;
    const scope = this._historyScope();
    if (typeof historyPush === 'function') {
      historyPush(label, () => { this._applySnapshot(snap); }, null, scope);
    }
  },

  undo() {
    const scope = this._historyScope();
    if (typeof historyUndo === 'function') historyUndo(scope);
  },

  redo() {
    const scope = this._historyScope();
    if (typeof historyRedo === 'function') historyRedo(scope);
  },

  _applySnapshot(snap) {
    if (!this.doc || !this.host) return;
    const focusState = _sn2CaptureSnapshotFocus(this);
    this._pushUndoSuppressed = true;
    try {
      // 書式ポップアップはタイプオブジェクトを捕捉するため、配列を復元する前に閉じる。
      // 復元後も残すと、切断済みオブジェクトへの変更が保存されずに消える。
      if (typeof closeAllPalettePopups === 'function') closeAllPalettePopups();
      if (typeof closeAllFormatPopups === 'function') closeAllFormatPopups();
      const data = createScriptNoteDoc(JSON.parse(snap));
      this.doc.fileType = data.fileType;
      this.doc.version = data.version;
      this.doc.title = data.title;
      this.doc.layoutMode = data.layoutMode;
      this.doc.editor = data.editor;
      this.doc.scenarioTypes = data.scenarioTypes;
      this.doc.characters = data.characters;
      this.doc.characterDb = data.characterDb;
      this.doc.notes = data.notes;
      this.doc.rubyRules = data.rubyRules || [];
      this.doc.rubyPresentation = data.rubyPresentation;
      this.doc.rows = data.rows;
      this.doc.source = data.source;
      this._ensureDefaultChara();
      this._lastPushedSnap = snap;
      this._calcCache = null;
      this._render();
      if (this._rowSelection instanceof Set) {
        const rowIds = createScriptNoteRowIdSet(this.doc);
        for (const rowId of [...this._rowSelection]) {
          if (!rowIds.has(rowId)) this._rowSelection.delete(rowId);
        }
      }
      if (typeof this._updateRowSelectionUI === 'function') this._updateRowSelectionUI();
      this._dirty = true;
      this._scheduleSave();
      this._refreshDetailPanel();
    } finally {
      this._pushUndoSuppressed = false;
    }
    requestAnimationFrame(() => {
      if (!this.host) return;
      const restoreText = _sn2FindRestoreTarget(this, focusState);
      if (restoreText) {
        this._focusText(restoreText, 'end');
        restoreText.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
      }
      if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      requestAnimationFrame(() => {
        if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      });
    });
  },

  _refreshDetailPanel() {
    const container = document.getElementById('detail-tab-sn2-main');
    if (!container) return;
    const panel = container.querySelector('.sn2-detail-wrap');
    if (!panel || panel.style.display === 'none') return;
    const activeTab = this._detailActiveTab || 'roles';
    if (activeTab === 'style') {
      if (typeof renderFileStyleTab === 'function') renderFileStyleTab('scriptnote');
    } else if (activeTab === 'ruby' && typeof this.renderRubyPanel === 'function') {
      this.renderRubyPanel(panel);
    } else if (activeTab === 'theme' && typeof this.renderThemePanel === 'function') {
      this.renderThemePanel(panel);
    } else if (activeTab === 'rowset' && typeof this.renderRowsetPanel === 'function') {
      this.renderRowsetPanel(panel);
    } else {
      this.renderDetailPanel(panel);
    }
  },

});

(function _sn2PatchHistoryScopePerEditor() {
  if (typeof ScriptNoteEditor === 'undefined') return;
  const proto = ScriptNoteEditor?.prototype;
  if (!proto || typeof proto.loadDoc !== 'function' || proto.loadDoc.__sn2HistoryScopePatched) return;
  const originalLoadDoc = proto.loadDoc;
  proto.loadDoc = function(parsed, path = '') {
    const nextPath = String(path || '');
    if (!this._historyScopeId || (this._historyScopePath && nextPath && this._historyScopePath !== nextPath)) {
      this._historyScopeId = _sn2NewHistoryScopeId();
    }
    this._historyScopePath = nextPath;
    return originalLoadDoc.apply(this, arguments);
  };
  proto.loadDoc.__sn2HistoryScopePatched = true;
})();

;

/* === gb-scriptnote-interactions.js === */
;
/* gb-scriptnote-interactions.js: シナリオの入力インタラクション */

function _sn2GetDragRectStyles(customColor) {
  if (customColor) {
    let bgStyle = customColor;
    if (!customColor.includes('rgba') && !customColor.includes('hsla')) {
      bgStyle = `color-mix(in srgb, ${customColor} 20%, transparent)`;
    }
    return { bgStyle, bdStyle: customColor };
  }
  return {
    bgStyle: 'rgba(74,144,217,0.15)',
    bdStyle: 'var(--accent, #4a90d9)',
  };
}

Object.assign(ScriptNoteEditor.prototype, {

  runShortcutAction(id, e) {
    if (e?.isComposing) return false;
    const ae = document.activeElement;
    if (ae && ['INPUT', 'TEXTAREA', 'SELECT'].includes(ae.tagName)) return false;
    switch (id) {
      case 'scenario.undo':
        if (typeof this.undo !== 'function') return false;
        this.undo();
        return true;
      case 'scenario.redo':
        if (typeof this.redo !== 'function') return false;
        this.redo();
        return true;
      case 'scenario.ruby':
        if (typeof this._insertRuby !== 'function') return false;
        this._insertRuby();
        return true;
      case 'scenario.search':
      case 'scenario.replace':
        return this._runSearchShortcut();
      case 'scenario.deselectAll':
        return this._runDeselectAllShortcut();
      case 'scenario.selectAll': {
        // セル内で Ctrl+A: 全行選択ではなくそのセルの内容全体を選択する
        const cell = ae?.closest?.('.sn2-text[contenteditable], .sn2-custom-text[contenteditable]');
        if (cell && this.host?.contains(cell)) {
          // 過去のセル範囲選択が残っていると、この後のDeleteで無関係なセルまで消えるため先に解除する
          this._clearGridCellSelection?.();
          this._clearTextCellSelection?.();
          const sel = window.getSelection();
          if (sel) {
            const range = document.createRange();
            range.selectNodeContents(cell);
            sel.removeAllRanges();
            sel.addRange(range);
            return true;
          }
        }
        if (typeof this._selectAllRows !== 'function') return false;
        this._selectAllRows();
        return true;
      }
      case 'scenario.moveUp':
        return this._runMoveRowShortcut(-1);
      case 'scenario.moveDown':
        return this._runMoveRowShortcut(1);
      case 'scenario.addRow':
        return this._runAddRowShortcut(false, e);
      case 'scenario.addRowSameType':
        return this._runAddRowShortcut(true, e);
      case 'scenario.newline':
        return this._runNewlineShortcut(e);
      case 'scenario.tab':
        return this._runTabShortcut(e);
      case 'scenario.deleteRow':
        return this._runDeleteRowShortcut(e);
      case 'scenario.escape':
        return this._runEscapeShortcut();
      case 'scenario.copy':
        document.execCommand('copy');
        return true;
      case 'scenario.cut':
        document.execCommand('cut');
        return true;
      case 'scenario.paste':
        return false;
      case 'scenario.pasteInCell':
        this._pasteInCellFlag = true;
        setTimeout(() => { this._pasteInCellFlag = false; }, 200);
        return false;
      default:
        return false;
    }
  },

  _shortcutTextTarget(e) {
    const target = e?.target || document.activeElement;
    return target?.closest?.('.sn2-text') || document.activeElement?.closest?.('.sn2-text') || null;
  },

  _runSearchShortcut() {
    const searchBtn = this.host?.closest?.('.gb-se-root')?.querySelector?.('[data-sn-action="search"]') || null;
    if (typeof this._showSearchReplacePopup !== 'function') return false;
    this._showSearchReplacePopup(searchBtn);
    return true;
  },

  _runDeselectAllShortcut() {
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection();
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    this._lastSelectedIdx = -1;
    const sel = window.getSelection();
    if (sel?.rangeCount && !sel.isCollapsed) sel.collapseToStart();
    return true;
  },

  _runMoveRowShortcut(dir) {
    const text = this._shortcutTextTarget();
    if (!text) return false;
    const row = text.closest('.sn2-row');
    if (!row) return false;
    const rowId = row.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    if (idx < 0) return false;
    let targetIdx = idx + dir;
    while (targetIdx >= 0 && targetIdx < this.doc.rows.length) {
      const targetRow = this.doc.rows[targetIdx];
      if (this._isRoleVisible(targetRow.role, targetRow.status || '')) break;
      targetIdx += dir;
    }
    if (targetIdx < 0 || targetIdx >= this.doc.rows.length) return false;
    this._pushUndo('行入れ替え');
    const targetRowId = this.doc.rows[targetIdx].id;
    const tmp = this.doc.rows[idx];
    this.doc.rows[idx] = this.doc.rows[targetIdx];
    this.doc.rows[targetIdx] = tmp;
    this._calcCache = null;
    const targetRow = this.host?.querySelector(`.sn2-row[data-row-id="${targetRowId}"]`);
    if (row && targetRow && !this._filterRoles) {
      if (dir === -1) row.parentNode.insertBefore(row, targetRow);
      else row.parentNode.insertBefore(row, targetRow.nextSibling);
      this._updateGuttersFrom(Math.min(idx, targetIdx));
      row.classList.add('sn2-swap-highlight');
      setTimeout(() => row.classList.remove('sn2-swap-highlight'), 400);
    } else {
      this._render();
    }
    this._markDirty({ skipUndo: true });
    requestAnimationFrame(() => {
      const curRow = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
      const newText = curRow?.querySelector('.sn2-text');
      if (!newText) return;
      const sel = window.getSelection();
      const inText = sel?.anchorNode && newText.contains(sel.anchorNode);
      if (!inText) this._focusText(newText, 'start');
      if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      requestAnimationFrame(() => {
        if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      });
    });
    return true;
  },

  _runAddRowShortcut(keepRole, e) {
    const text = this._shortcutTextTarget(e);
    if (!text) return false;
    const splitOffset = this._getTextOffset(text);
    this._pushUndo(keepRole ? '同タイプ行追加' : '行追加');
    this._splitRow(text, { keepRole, visibleOffset: splitOffset });
    return true;
  },

  _runNewlineShortcut(e) {
    const text = this._shortcutTextTarget(e);
    if (!text) return false;
    const sel = window.getSelection();
    if (!sel?.rangeCount) return false;
    const range = sel.getRangeAt(0);
    if (!this._rangeWithinElement(range, text)) return false;
    this._pushUndo('セル内改行');
    range.deleteContents();
    const br = document.createElement('br');
    range.insertNode(br);
    range.setStartAfter(br);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    let needsTrailingBr = true;
    for (let n = br.nextSibling; n; n = n.nextSibling) {
      if (n.nodeType === 3 && !n.textContent) continue;
      if (n.nodeType === 1 && n.tagName === 'BR') { needsTrailingBr = false; break; }
      needsTrailingBr = false;
      break;
    }
    if (needsTrailingBr) text.appendChild(document.createElement('br'));
    text.style.height = 'auto';
    this._syncRowFromDom(text, { skipUndo: true });
    requestAnimationFrame(() => {
      if (!sel.rangeCount) return;
      const r2 = sel.getRangeAt(0);
      if (!this._rangeWithinElement(r2, text)) return;
      const marker = document.createElement('span');
      r2.insertNode(marker);
      marker.scrollIntoView({ block: 'nearest', behavior: 'instant' });
      const markerParent = marker.parentNode;
      const markerIndex = markerParent ? Array.prototype.indexOf.call(markerParent.childNodes, marker) : -1;
      marker.remove();
      if (markerParent && markerIndex >= 0) {
        const restoreRange = document.createRange();
        restoreRange.setStart(markerParent, Math.min(markerIndex, markerParent.childNodes.length));
        restoreRange.collapse(true);
        sel.removeAllRanges();
        sel.addRange(restoreRange);
      } else {
        sel.collapseToEnd();
      }
      if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      requestAnimationFrame(() => {
        if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      });
    });
    return true;
  },

  _runTabShortcut(e) {
    const text = this._shortcutTextTarget(e);
    if (!text) return false;
    const row = text.closest('.sn2-row');
    if (!row) return false;
    const roleBtn = row.querySelector('.sn2-role-btn');
    if (roleBtn) this._showRoleMenu(roleBtn);
    return true;
  },

  _runDeleteRowShortcut(e) {
    const text = this._shortcutTextTarget(e);
    if (!text) return false;
    const row = text.closest('.sn2-row');
    if (!row) return false;
    const rowId = row.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    if (idx < 0 || this.doc.rows.length <= 1) return false;
    this._pushUndo('行削除');
    this.doc.rows.splice(idx, 1);
    this._calcCache = null;
    const focusIdx = Math.min(idx, this.doc.rows.length - 1);
    const focusId = this.doc.rows[focusIdx].id;
    this._render();
    this._markDirty({ skipUndo: true });
    const focusDeletedNeighbor = () => {
      const nextEl = this.host?.querySelector(`.sn2-row[data-row-id="${focusId}"] .sn2-text`);
      if (nextEl) {
        this._focusText(nextEl, 'start');
        document.dispatchEvent(new Event('selectionchange'));
        if (this._caretSelChangeHandler) this._caretSelChangeHandler();
      }
    };
    focusDeletedNeighbor();
    requestAnimationFrame(focusDeletedNeighbor);
    return true;
  },

  _runEscapeShortcut() {
    // セルナビゲーションで編集中の場合、まず編集モードを抜けるだけに留める
    // （アクティブ状態は保持。もう一度Escapeでアクティブ解除まで進む）
    if (this._cellEditMode && typeof this._exitEditMode === 'function') {
      this._exitEditMode();
      return true;
    }
    if (typeof this._closeRubyPopup === 'function') this._closeRubyPopup();
    document.querySelectorAll('.sn2-header-popup, .sn2-header-sub-popup, .gb-fmt-popup--bulk-edit').forEach(el => el.remove());
    if (typeof this._closeRoleMenu === 'function') this._closeRoleMenu();
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection();
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    return true;
  },

  _bindInteractionEvents(host) {
    if (typeof this._initCellNavigation === 'function') this._initCellNavigation();
    this._bindWheelScroll(host);
    this._bindDragSelection(host);
    this._bindRowSelectionCopy();
    if (typeof this._bindRowCheckDragToggle === 'function') this._bindRowCheckDragToggle(host);
    if (typeof this._bindRoleCellSelection === 'function') this._bindRoleCellSelection(host);
    this._bindRightDragPan(host);
  },

  _bindWheelScroll(host) {
    host.addEventListener('wheel', (e) => {
      const sc = e.target.closest?.('.sn2-scroll');
      if (!sc) return;
      const isVerticalMode = this.doc.editor?.viewMode === 'vertical';
      const isWrap = !!this.doc.editor?.wrapMode;
      if (!e.deltaY || e.deltaX) return;
      const stored = parseFloat(localStorage.getItem('meldex-wheel-speed'));
      let mul;
      if (!isNaN(stored) && stored > 0) {
        mul = stored;
      } else {
        const viewSize = sc.clientWidth;
        if (e.deltaMode === 2) {
          mul = viewSize * 0.8;
        } else if (e.deltaMode === 1) {
          mul = viewSize * 0.08;
        } else {
          mul = viewSize * 0.25 / 100;
        }
      }
      if (isWrap && !isVerticalMode) {
        e.preventDefault();
        sc.scrollBy({ left: e.deltaY * mul, behavior: 'smooth' });
      } else if (!isWrap && isVerticalMode) {
        e.preventDefault();
        sc.scrollBy({ left: -e.deltaY * mul, behavior: 'smooth' });
      }
    }, { passive: false });
  },

  _bindDragSelection(host) {
    let dragSelecting = false;
    let dragPending = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragPointerId = 0;
    let dragBaseSet = null;
    let dragAnchorCell = null;
    let dragScrollEl = null;
    let dragLastX = 0;
    let dragLastY = 0;
    let dragAutoScrollRaf = 0;
    let dragRect = null;
    let textDragCell = null;
    let textDragStartX = 0;
    let textDragStartY = 0;
    let textDragPointerId = 0;
    const DRAG_THRESHOLD = 4;
    const EDGE_THRESHOLD = 52;
    const EDGE_MAX_SPEED = 24;

    const selectableCell = (element) => {
      const cell = element?.closest?.('[data-col-id]');
      const row = cell?.closest?.('.sn2-row[data-row-id]');
      const colId = cell?.dataset?.colId || '';
      if (!cell || !row || !host.contains(row) || !colId || colId === '_handle') return null;
      return { element: cell, rowId: row.dataset.rowId || '', colId };
    };
    const visibleScrollRect = () => {
      const rect = dragScrollEl?.getBoundingClientRect?.();
      if (!rect) return null;
      return {
        left: Math.max(0, rect.left),
        top: Math.max(0, rect.top),
        right: Math.min(window.innerWidth, rect.right),
        bottom: Math.min(window.innerHeight, rect.bottom),
      };
    };
    const cellFromPoint = (x, y, clampToScroll = false) => {
      let pointX = x;
      let pointY = y;
      if (clampToScroll && dragScrollEl) {
        const rect = visibleScrollRect() || dragScrollEl.getBoundingClientRect();
        pointX = Math.max(rect.left + 2, Math.min(rect.right - 2, pointX));
        pointY = Math.max(rect.top + 2, Math.min(rect.bottom - 2, pointY));
      }
      return selectableCell(document.elementFromPoint(pointX, pointY));
    };
    const nearestCellFromPoint = (x, y) => {
      const scrollEl = dragScrollEl || host.querySelector('.sn2-scroll');
      const rawRect = scrollEl?.getBoundingClientRect?.();
      if (!rawRect) return null;
      const viewRect = {
        left: Math.max(0, rawRect.left),
        top: Math.max(0, rawRect.top),
        right: Math.min(window.innerWidth, rawRect.right),
        bottom: Math.min(window.innerHeight, rawRect.bottom),
      };
      const pointX = Math.max(viewRect.left + 2, Math.min(viewRect.right - 2, x));
      const pointY = Math.max(viewRect.top + 2, Math.min(viewRect.bottom - 2, y));
      let nearest = null;
      let nearestDistance = Number.POSITIVE_INFINITY;
      host.querySelectorAll('.sn2-row[data-row-id] > [data-col-id]').forEach(cell => {
        const candidate = selectableCell(cell);
        if (!candidate) return;
        const rect = cell.getBoundingClientRect();
        if (rect.right <= viewRect.left || rect.left >= viewRect.right
            || rect.bottom <= viewRect.top || rect.top >= viewRect.bottom) return;
        const dx = pointX < rect.left ? rect.left - pointX : pointX > rect.right ? pointX - rect.right : 0;
        const dy = pointY < rect.top ? rect.top - pointY : pointY > rect.bottom ? pointY - rect.bottom : 0;
        const distance = dx * dx + dy * dy;
        if (distance < nearestDistance) {
          nearest = candidate;
          nearestDistance = distance;
        }
      });
      return nearest;
    };

    const updateDragRect = (x, y) => {
      if (!dragRect) {
        dragRect = document.createElement('div');
        dragRect.className = 'sn2-drag-select-rect';
        document.body.appendChild(dragRect);
      }
      const z = typeof _getZoom === 'function' ? _getZoom() : 1;
      const left = Math.min(dragStartX, x) / z;
      const top = Math.min(dragStartY, y) / z;
      const w = Math.abs(x - dragStartX) / z;
      const h = Math.abs(y - dragStartY) / z;
      const customColor = this.doc.editor?.dragSelectColor || '';
      const { bgStyle, bdStyle } = _sn2GetDragRectStyles(customColor);
      dragRect.style.cssText = `position:fixed;left:${left}px;top:${top}px;width:${w}px;height:${h}px;z-index:9999;background:${bgStyle};border:1px solid ${bdStyle};border-radius:2px;pointer-events:none;`;
    };
    const removeDragRect = () => {
      if (dragRect) {
        dragRect.remove();
        dragRect = null;
      }
    };
    const updateGridRangeAtPoint = (x, y) => {
      if (!dragSelecting || !dragAnchorCell) return false;
      const over = cellFromPoint(x, y, true) || nearestCellFromPoint(x, y);
      if (!over) return false;
      return !!this._setGridCellRange?.(
        dragAnchorCell.rowId,
        dragAnchorCell.colId,
        over.rowId,
        over.colId,
        dragBaseSet,
      );
    };
    const edgeVelocity = (position, start, end) => {
      if (position < start + EDGE_THRESHOLD) {
        const ratio = Math.min(1, Math.max(0, (start + EDGE_THRESHOLD - position) / EDGE_THRESHOLD));
        return -Math.max(2, Math.round(EDGE_MAX_SPEED * ratio));
      }
      if (position > end - EDGE_THRESHOLD) {
        const ratio = Math.min(1, Math.max(0, (position - (end - EDGE_THRESHOLD)) / EDGE_THRESHOLD));
        return Math.max(2, Math.round(EDGE_MAX_SPEED * ratio));
      }
      return 0;
    };
    const stopAutoScroll = () => {
      if (dragAutoScrollRaf) cancelAnimationFrame(dragAutoScrollRaf);
      dragAutoScrollRaf = 0;
    };
    const performAutoScrollStep = () => {
      if (!dragSelecting || !dragScrollEl?.isConnected) return false;
      const rect = visibleScrollRect() || dragScrollEl.getBoundingClientRect();
      const deltaX = dragScrollEl.scrollWidth > dragScrollEl.clientWidth
        ? edgeVelocity(dragLastX, rect.left, rect.right)
        : 0;
      const deltaY = dragScrollEl.scrollHeight > dragScrollEl.clientHeight
        ? edgeVelocity(dragLastY, rect.top, rect.bottom)
        : 0;
      const beforeLeft = dragScrollEl.scrollLeft;
      const beforeTop = dragScrollEl.scrollTop;
      if (deltaX) dragScrollEl.scrollLeft += deltaX;
      if (deltaY) dragScrollEl.scrollTop += deltaY;
      if (dragScrollEl.scrollLeft !== beforeLeft || dragScrollEl.scrollTop !== beforeTop) {
        updateGridRangeAtPoint(dragLastX, dragLastY);
        return true;
      }
      return false;
    };
    const runAutoScroll = () => {
      dragAutoScrollRaf = 0;
      if (!dragSelecting || !dragScrollEl?.isConnected) return;
      performAutoScrollStep();
      dragAutoScrollRaf = requestAnimationFrame(runAutoScroll);
    };
    const startAutoScroll = () => {
      if (!dragAutoScrollRaf) dragAutoScrollRaf = requestAnimationFrame(runAutoScroll);
    };
    const beginGridDrag = (anchor, pointerEvent, startX, startY, pointerId) => {
      if (!anchor?.rowId || !anchor?.colId) return false;
      dragPending = false;
      dragSelecting = true;
      dragAnchorCell = anchor;
      dragStartX = startX;
      dragStartY = startY;
      dragPointerId = pointerId;
      dragScrollEl = anchor.element?.closest?.('.sn2-scroll') || host.querySelector('.sn2-scroll');
      this._beginGridCellDragSelection?.(anchor.rowId, anchor.colId, dragBaseSet);
      this._setGridCellRange?.(anchor.rowId, anchor.colId, anchor.rowId, anchor.colId, dragBaseSet);
      this._gridDragSelectionActive = true;
      try { window.getSelection()?.removeAllRanges(); } catch {}
      try { host.setPointerCapture(dragPointerId); } catch {}
      pointerEvent?.preventDefault?.();
      startAutoScroll();
      return true;
    };
    const finishDrag = (options = {}) => {
      const hadSelection = dragSelecting;
      stopAutoScroll();
      this._gridDragSelectionActive = false;
      textDragCell = null;
      dragPending = false;
      dragSelecting = false;
      removeDragRect();
      try { if (dragPointerId) host.releasePointerCapture(dragPointerId); } catch {}
      dragPointerId = 0;
      dragScrollEl = null;
      dragAnchorCell = null;
      dragBaseSet = null;
      if (hadSelection) {
        this._updateGridCellSelectionUI?.();
        if (options.focus !== false) this._focusGridCellSelectionHost?.();
      }
    };
    if (this._dragSelectionDocCleanup) this._dragSelectionDocCleanup();
    const onDocumentPointerUp = () => finishDrag();
    const onDocumentPointerCancel = () => finishDrag({ focus: false });
    document.addEventListener('pointerup', onDocumentPointerUp);
    document.addEventListener('pointercancel', onDocumentPointerCancel);
    this._dragSelectionDocCleanup = () => {
      finishDrag({ focus: false });
      document.removeEventListener('pointerup', onDocumentPointerUp);
      document.removeEventListener('pointercancel', onDocumentPointerCancel);
    };

    host.addEventListener('pointerdown', (e) => {
      if (e.button !== 0) return;
      const target = e.target;
      const textLike = target.closest('.sn2-text[contenteditable], .sn2-custom-text[contenteditable]');
      if (textLike) {
        textDragCell = selectableCell(textLike);
        textDragStartX = e.clientX;
        textDragStartY = e.clientY;
        textDragPointerId = e.pointerId;
        dragBaseSet = (e.ctrlKey || e.metaKey || e.shiftKey) ? new Set(this._gridCellSelection || []) : new Set();
        dragLastX = e.clientX;
        dragLastY = e.clientY;
        return;
      }
      if (target.closest('.sn2-role-btn')
          || target.closest('.sn2-status-btn')
          || target.closest('.sn2-header')
          || target.closest('.sn2-handle')
          || target.tagName === 'INPUT'
          || target.tagName === 'SELECT'
          || target.tagName === 'BUTTON') return;
      if (!target.closest('.sn2-row')
          && !target.closest('.sn2-scroll')
          && !target.closest('.sn2-editor')
          && !target.closest('.sn2-column-group')) return;
      dragPending = true;
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      dragPointerId = e.pointerId;
      dragLastX = e.clientX;
      dragLastY = e.clientY;
      dragAnchorCell = selectableCell(target) || nearestCellFromPoint(e.clientX, e.clientY);
      dragBaseSet = (e.ctrlKey || e.metaKey || e.shiftKey) ? new Set(this._gridCellSelection || []) : new Set();
    });

    host.addEventListener('pointermove', (e) => {
      dragLastX = e.clientX;
      dragLastY = e.clientY;
      if (textDragCell && !dragSelecting && !dragPending) {
        const over = cellFromPoint(e.clientX, e.clientY);
        const movedToOtherCell = over && (over.rowId !== textDragCell.rowId || over.colId !== textDragCell.colId);
        if (movedToOtherCell) {
          const anchor = textDragCell;
          textDragCell = null;
          beginGridDrag(anchor, e, textDragStartX, textDragStartY, textDragPointerId);
          updateGridRangeAtPoint(e.clientX, e.clientY);
        }
      }
      if (dragPending && !dragSelecting) {
        const dx = e.clientX - dragStartX;
        const dy = e.clientY - dragStartY;
        if (Math.abs(dx) + Math.abs(dy) < DRAG_THRESHOLD) return;
        const anchor = dragAnchorCell || cellFromPoint(dragStartX, dragStartY) || nearestCellFromPoint(dragStartX, dragStartY);
        if (!beginGridDrag(anchor, e, dragStartX, dragStartY, dragPointerId)) return;
      }
      if (!dragSelecting) return;
      updateDragRect(e.clientX, e.clientY);
      updateGridRangeAtPoint(e.clientX, e.clientY);
      // rAFが間引かれる環境でも端へ入った瞬間には必ず1段階スクロールする。
      performAutoScrollStep();
    });

    host.addEventListener('pointerup', (e) => {
      const wasTextCellClick = !!textDragCell;
      textDragCell = null;
      if (dragPending && !dragSelecting) {
        dragPending = false;
        // ドラッグでない単クリック: すべての選択系を解除
        if (this._rowSelection?.size) {
          this._rowSelection.clear();
          this._updateRowSelectionUI();
        }
        if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
        if (this._textCellSelection?.size) this._clearTextCellSelection?.();
        if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
        if (this._activeCellRowId) this._clearActiveCell?.();
        return;
      }
      // テキストセル上のドラッグでない単クリック: テキストセル範囲選択を解除
      if (wasTextCellClick && !dragSelecting) {
        if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
        if (this._textCellSelection?.size) this._clearTextCellSelection?.();
      }
      if (dragSelecting) finishDrag();
    });

    host.addEventListener('lostpointercapture', () => {
      textDragCell = null;
      if (dragSelecting || dragPending) finishDrag();
    });

    host.addEventListener('wheel', (e) => {
      if (!dragSelecting || !dragScrollEl?.isConnected) return;
      dragLastX = e.clientX || dragLastX;
      dragLastY = e.clientY || dragLastY;
      if (!e.defaultPrevented) {
        e.preventDefault();
        dragScrollEl.scrollLeft += e.deltaX;
        dragScrollEl.scrollTop += e.deltaY;
      }
      requestAnimationFrame(() => updateGridRangeAtPoint(dragLastX, dragLastY));
    }, { passive: false });
  },

  _bindRowSelectionCopy() {
    this._copyHandler = (e) => {
      if (!this._rowSelection || this._rowSelection.size === 0) {
        // 行選択が無い場合は矩形セル範囲→従来テキストセル範囲の順にコピーを試す
        if (typeof this._handleGridCellSelectionCopy === 'function'
            && this._handleGridCellSelectionCopy(e)) return;
        if (typeof this._handleTextCellSelectionCopy === 'function') this._handleTextCellSelectionCopy(e);
        return;
      }
      if (!this.host || !this.host.isConnected) return;
      if (typeof this._sanitizeRowSelection === 'function') this._sanitizeRowSelection();
      if (!this._rowSelection || this._rowSelection.size === 0) return;
      const sel = window.getSelection();
      if (sel && sel.rangeCount && !sel.isCollapsed) {
        const anchor = sel.anchorNode;
        const anchorEl = anchor?.nodeType === 1 ? anchor : anchor?.parentElement;
        const anchorHost = anchor?.nodeType === 1 ? anchor : anchor?.parentNode;
        const isInsideText = anchorEl?.closest?.('.sn2-text');
        if (isInsideText && this.host.contains(anchorHost)) return;
      }
      const selectedIds = typeof this._getVisibleSelectedIds === 'function'
        ? this._getVisibleSelectedIds()
        : new Set(this._rowSelection || []);
      const selected = this.doc.rows.filter((row) => selectedIds.has(row.id));
      if (!selected.length) return;
      const lines = selected.map((row) => _sn2StripRubyToPlain(row.text || ''));
      e.clipboardData?.setData('text/plain', lines.join('\n'));
      e.preventDefault();
    };
    document.addEventListener('copy', this._copyHandler);
  },

  _bindRightDragPan(host) {
    let panActive = false;
    let panStartX = 0;
    let panStartY = 0;
    let panOrigSL = 0;
    let panOrigST = 0;
    let panSc = null;
    let panPid = 0;
    let panMoved = false;

    host.addEventListener('pointerdown', (e) => {
      if (e.button !== 2) return;
      const target = e.target;
      if (target.closest('.sn2-text[contenteditable]')
          || target.tagName === 'INPUT'
          || target.tagName === 'BUTTON'
          || target.tagName === 'SELECT'
          || target.tagName === 'TEXTAREA') return;
      const sc = target.closest?.('.sn2-scroll');
      if (!sc) return;
      panActive = true;
      panMoved = false;
      panSc = sc;
      panStartX = e.clientX;
      panStartY = e.clientY;
      panOrigSL = sc.scrollLeft;
      panOrigST = sc.scrollTop;
      panPid = e.pointerId;
      try { host.setPointerCapture(panPid); } catch {}
      sc.classList.add('sn2-panning');
      e.preventDefault();
    });

    host.addEventListener('pointermove', (e) => {
      if (!panActive || !panSc) return;
      const dx = e.clientX - panStartX;
      const dy = e.clientY - panStartY;
      if (!panMoved && Math.abs(dx) + Math.abs(dy) > 3) panMoved = true;
      if (panSc.classList.contains('sn2-vertical') && panSc.classList.contains('sn2-wrap')) {
        panSc.scrollLeft = 0;
      } else {
        panSc.scrollLeft = panOrigSL - dx;
      }
      panSc.scrollTop = panOrigST - dy;
    });

    const endPan = () => {
      if (!panActive) return;
      panActive = false;
      if (panSc) panSc.classList.remove('sn2-panning');
      try { host.releasePointerCapture(panPid); } catch {}
      panSc = null;
    };

    host.addEventListener('pointerup', (e) => {
      if (e.button === 2) endPan();
    });
    host.addEventListener('lostpointercapture', endPan);
    host.addEventListener('contextmenu', (e) => {
      const target = e.target;
      if (target.closest('.sn2-text[contenteditable]') || target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return;
      if (target.closest?.('.sn2-scroll')) e.preventDefault();
    });
  },

});

;

/* === gb-scriptnote-selection.js === */
;
/* gb-scriptnote-selection.js: シナリオの複数行選択と一括操作 */

Object.assign(ScriptNoteEditor.prototype, {

  _isRowSelectionTarget(row) {
    return !!(row && this._isRoleVisible(row.role || '', row.status || ''));
  },

  _sanitizeRowSelection() {
    if (!this._rowSelection || !this.doc?.rows) return;
    const visibleIds = new Set(this.doc.rows.filter(row => this._isRowSelectionTarget(row)).map(row => row.id));
    for (const rowId of [...this._rowSelection]) {
      if (!visibleIds.has(rowId)) this._rowSelection.delete(rowId);
    }
  },

  _getVisibleSelectedIds() {
    this._sanitizeRowSelection();
    return new Set(this._rowSelection || []);
  },

  _isRowSelectionOwnerActive() {
    if (!this.host?.isConnected || !this.doc?.rows) return false;
    if (this.host.getClientRects && !this.host.getClientRects().length) return false;
    const activeComp = typeof getActiveScriptNoteComponent === 'function' ? getActiveScriptNoteComponent() : null;
    if (activeComp?._editor) return activeComp._editor === this;
    return true;
  },

  _guardRowBulkAction() {
    if (this._isRowSelectionOwnerActive()) return true;
    if (this._rowSelection) this._rowSelection.clear();
    if (this._gridCellSelection) this._gridCellSelection.clear();
    if (this._textCellSelection) this._textCellSelection.clear();
    if (this._rowBulkBar?.isConnected) this._rowBulkBar.remove();
    this._rowBulkBar = null;
    return false;
  },

  _startRowBulkBarGuard() {
    if (this._rowBulkBarGuardTimer) return;
    this._rowBulkBarGuardTimer = setInterval(() => {
      if (!this._rowBulkBar?.isConnected || !this._rowSelection?.size) {
        this._stopRowBulkBarGuard();
        return;
      }
      if (!this._isRowSelectionOwnerActive()) this._clearRowSelection();
    }, 250);
  },

  _stopRowBulkBarGuard() {
    if (!this._rowBulkBarGuardTimer) return;
    clearInterval(this._rowBulkBarGuardTimer);
    this._rowBulkBarGuardTimer = null;
  },

  _clampRowBulkBarToViewport(bar) {
    if (!bar?.isConnected) return;
    const z = (typeof _getZoom === 'function' ? _getZoom() : 1) || 1;
    const margin = 8 / z;
    const vw = window.innerWidth / z;
    const vh = window.innerHeight / z;
    const parentRect = bar.offsetParent?.getBoundingClientRect?.() || { left: 0, top: 0 };
    const rect = bar.getBoundingClientRect();
    const box = {
      left: rect.left / z,
      top: rect.top / z,
      width: rect.width / z,
      height: rect.height / z,
    };
    const maxHeight = Math.max(120 / z, vh - margin * 2);
    if (box.height > maxHeight) {
      bar.style.maxHeight = `${maxHeight}px`;
      bar.style.overflowY = 'auto';
    }
    const nextRect = bar.getBoundingClientRect();
    const next = {
      left: nextRect.left / z,
      top: nextRect.top / z,
      width: nextRect.width / z,
      height: nextRect.height / z,
    };
    const clampedLeft = Math.max(margin, Math.min(next.left, vw - next.width - margin));
    const clampedTop = Math.max(margin, Math.min(next.top, vh - next.height - margin));
    if (Math.abs(clampedLeft - next.left) > 0.5 || Math.abs(clampedTop - next.top) > 0.5) {
      bar.style.left = `${clampedLeft - (parentRect.left / z)}px`;
      bar.style.top = `${clampedTop - (parentRect.top / z)}px`;
      bar.style.right = '';
      bar.style.bottom = 'auto';
      bar.style.transform = 'none';
    }
  },

  _toggleRowSelection(rowId, idx, shiftKey, ctrlKey) {
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
    if (this._activeCellRowId) this._clearActiveCell?.();
    if (!this._rowSelection) this._rowSelection = new Set();
    if (shiftKey && this._lastSelectedIdx >= 0) {
      const from = Math.min(this._lastSelectedIdx, idx);
      const to = Math.max(this._lastSelectedIdx, idx);
      for (let i = from; i <= to; i++) {
        const row = this.doc.rows[i];
        if (!row) continue;
        if (!this._isRoleVisible(row.role || '', row.status || '')) continue;
        this._rowSelection.add(row.id);
      }
    } else if (ctrlKey) {
      if (this._rowSelection.has(rowId)) this._rowSelection.delete(rowId);
      else this._rowSelection.add(rowId);
    } else {
      if (this._rowSelection.has(rowId)) this._rowSelection.delete(rowId);
      else this._rowSelection.add(rowId);
    }
    this._lastSelectedIdx = idx;
    this._updateRowSelectionUI();
  },

  _clearRowSelection() {
    if (this._rowSelection) this._rowSelection.clear();
    this._lastSelectedIdx = -1;
    this._updateRowSelectionUI();
  },

  _invertRowSelection() {
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (!this._rowSelection) this._rowSelection = new Set();
    this._sanitizeRowSelection();
    this.doc.rows.forEach((row) => {
      if (!this._isRowSelectionTarget(row)) return;
      if (this._rowSelection.has(row.id)) this._rowSelection.delete(row.id);
      else this._rowSelection.add(row.id);
    });
    this._updateRowSelectionUI();
  },

  _selectAllRows() {
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (!this._rowSelection) this._rowSelection = new Set();
    this._rowSelection.clear();
    this.doc.rows.forEach((row) => {
      if (!this._isRowSelectionTarget(row)) return;
      this._rowSelection.add(row.id);
    });
    this._updateRowSelectionUI();
  },

  _bulkDuplicateRows() {
    if (!this._guardRowBulkAction()) return;
    const selectedIds = this._getVisibleSelectedIds();
    if (!selectedIds.size) return;
    this._pushUndo('一括複製');
    const newRows = [];
    this.doc.rows.forEach((row) => {
      newRows.push(row);
      if (selectedIds.has(row.id)) {
        const nextId = (globalThis.crypto?.randomUUID?.() || ('sn-row-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2)));
        newRows.push({ ...row, id: nextId, columns: { ...(row.columns || {}) } });
      }
    });
    this.doc.rows = newRows;
    this._clearRowSelection();
    this._render();
    this._markDirty();
  },

  _updateRowSelectionUI() {
    this._sanitizeRowSelection();
    const editor = this.host?.querySelector('.sn2-editor');
    if (!editor) return;
    editor.querySelectorAll('.sn2-row').forEach((el) => {
      const rowId = el.dataset.rowId;
      const selected = this._rowSelection?.has(rowId) || false;
      el.classList.toggle('sn2-row-selected', selected);
      const checkbox = el.querySelector('.sn2-row-check');
      if (checkbox) checkbox.checked = selected;
    });
    this._updateRowBulkBar();
  },

  _updateRowBulkBar() {
    let bar = this._rowBulkBar && this._rowBulkBar.isConnected ? this._rowBulkBar : null;
    const count = this._rowSelection?.size || 0;
    if (count >= 1 && !this._isRowSelectionOwnerActive()) {
      if (bar) bar.remove();
      this._rowBulkBar = null;
      this._stopRowBulkBarGuard();
      return;
    }
    if (count < 1) {
      if (bar) bar.remove();
      this._rowBulkBar = null;
      this._stopRowBulkBarGuard();
      return;
    }
    if (!bar) {
      bar = document.createElement('div');
      bar.className = 'sn2-row-bulk-bar gb-selection-float-bar';
      bar.setAttribute('role', 'toolbar');
      bar.setAttribute('aria-label', 'シナリオ行の一括操作');
      (this.host || document.body).appendChild(bar);
      this._rowBulkBar = bar;
    }
    if (window.GBSelectionFloatMenu) {
      window.GBSelectionFloatMenu.bindDrag(bar, { host: this.host || document.body });
      window.GBSelectionFloatMenu.resetPosition(bar, { host: this.host || document.body, anchor: this.host, zIndex: '1000' });
    } else {
      const hostRect = this.host?.getBoundingClientRect();
      const zoom = (typeof _getZoom === 'function' ? _getZoom() : 1) || 1;
      const left = hostRect ? (hostRect.left / zoom) : 0;
      const top = hostRect ? (hostRect.top / zoom) : 0;
      const offset = 8 / zoom;
      bar.style.cssText = `position:fixed;top:${top + offset}px;left:${left + offset}px;z-index:1000;background:var(--ui-popup-bg, var(--bg3));border:1px solid var(--border);border-left:3px solid var(--accent, #4a90d9);border-radius:6px;padding:6px 12px;display:flex;align-items:center;gap:6px;font-size:12px;box-shadow:0 2px 12px rgba(0,0,0,0.4);width:fit-content;`;
    }
    bar.innerHTML = '';
    if (window.GBSelectionFloatMenu) {
      bar.appendChild(window.GBSelectionFloatMenu.createDragHandle());
    }
    const label = document.createElement('span');
    label.className = 'gb-selection-float-count';
    label.textContent = `${count}行選択中`;
    bar.appendChild(label);
    const mkBtn = (id, text, title, onClick, options = {}) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = text;
      button.title = title;
      button.dataset.e2eId = id;
      button.setAttribute('aria-label', title);
      button.className = 'gb-selection-float-button' + (options.danger ? ' danger' : '');
      button.addEventListener('click', () => {
        if (!this._guardRowBulkAction()) return;
        window.GBSelectionFloatMenu?.pulseButton?.(button);
        onClick();
      });
      return button;
    };
    bar.appendChild(mkBtn('sn-row-bulk-role', 'タイプ変更', '選択行のタイプを一括変更', () => this._bulkChangeRole()));
    bar.appendChild(mkBtn('sn-row-bulk-duplicate', '複製', '選択行を複製', () => this._bulkDuplicateRows()));
    bar.appendChild(mkBtn('sn-row-bulk-delete', '削除', '選択行を一括削除', () => this._bulkDeleteRows(), { danger: true }));
    bar.appendChild(mkBtn('sn-row-bulk-invert', '選択反転', '選択状態を反転', () => this._invertRowSelection()));
    bar.appendChild(mkBtn('sn-row-bulk-clear', '選択解除', '選択を解除', () => this._clearRowSelection()));
    this._clampRowBulkBarToViewport(bar);
    this._startRowBulkBarGuard();
  },

  _bulkChangeRole() {
    if (!this._guardRowBulkAction()) return;
    const selectedIds = this._getVisibleSelectedIds();
    if (!selectedIds.size) return;
    const roles = (globalThis.GBScriptNoteRoleModel?.buildRoleChoices?.(this.doc) || [])
      .filter((choice) => choice && choice.kind !== 'none')
      .map((choice) => String(choice.name || choice.label || ''))
      .filter(Boolean);
    if (!roles.length) return;
    const popup = document.createElement('div');
    popup.className = 'sn2-header-popup sn2-bulk-role-popup';
    popup.setAttribute('role', 'menu');
    popup.setAttribute('aria-label', '選択行のタイプを一括変更');
    popup.style.cssText = 'position:fixed;z-index:10100;max-height:300px;overflow-y:auto;';
    const bar = this._rowBulkBar && this._rowBulkBar.isConnected ? this._rowBulkBar : null;
    const trigger = bar?.querySelector?.('[data-e2e-id="sn-row-bulk-role"]') || null;
    const close = (options = {}) => {
      popup.remove();
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeydown, true);
      if (options.restoreFocus) trigger?.focus?.();
    };
    const onPointerDown = (ev) => {
      if (!popup.contains(ev.target)) close({ restoreFocus: true });
    };
    const onKeydown = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      close({ restoreFocus: true });
    };
    roles.forEach((name, index) => {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'sn2-header-popup-item';
      item.setAttribute('role', 'menuitem');
      item.dataset.e2eId = `sn-row-bulk-role-option-${index + 1}`;
      item.dataset.sn2BulkRoleOption = name;
      item.textContent = name;
      item.addEventListener('click', () => {
        if (!this._guardRowBulkAction()) { close(); return; }
        close();
        this._pushUndo('一括タイプ変更');
        this.doc.rows.forEach((row) => {
          if (!selectedIds.has(row.id)) return;
          if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
            globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, row, name);
          } else {
            row.role = name;
          }
        });
        this._render();
        this._markDirty();
        this._clearRowSelection();
      });
      popup.appendChild(item);
    });
    document.body.appendChild(popup);
    if (bar && typeof positionPopup === 'function') positionPopup(popup, bar.getBoundingClientRect());
    else if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
    requestAnimationFrame(() => popup.querySelector('.sn2-header-popup-item')?.focus());
    setTimeout(() => {
      document.addEventListener('pointerdown', onPointerDown, true);
      document.addEventListener('keydown', onKeydown, true);
    }, 0);
  },

  _bulkDeleteRows() {
    if (!this._guardRowBulkAction()) return;
    const selectedIds = this._getVisibleSelectedIds();
    if (!selectedIds.size) return;
    if ((this.doc?.rows?.length || 0) - selectedIds.size < 1) {
      const keepRow = this.doc.rows.find((row) => selectedIds.has(row.id));
      if (keepRow) selectedIds.delete(keepRow.id);
      if (typeof showStatus === 'function') showStatus('最後の1行は削除できません', true);
    }
    if (!selectedIds.size) {
      this._clearRowSelection();
      return;
    }
    if (typeof showConfirmDialog === 'function') {
      showConfirmDialog(`${selectedIds.size}行を削除しますか？`, () => {
        this._pushUndo('一括行削除');
        this.doc.rows = this.doc.rows.filter((row) => !selectedIds.has(row.id));
        this._clearRowSelection();
        this._render();
        this._markDirty();
      });
    }
  },

  _setRowSelectionState(rowId, idx, selected) {
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
    if (this._activeCellRowId) this._clearActiveCell?.();
    if (!this._rowSelection) this._rowSelection = new Set();
    if (selected) this._rowSelection.add(rowId);
    else this._rowSelection.delete(rowId);
    this._lastSelectedIdx = idx;
    this._updateRowSelectionUI();
  },

  _bindRowCheckDragToggle(host) {
    let active = false;
    let mode = false;
    let pointerId = 0;
    const seen = new Set();
    const apply = (target) => {
      const cb = target?.closest?.('.sn2-row-check');
      const rowEl = cb?.closest?.('.sn2-row');
      const rowId = rowEl?.dataset.rowId || '';
      if (!rowId || seen.has(rowId)) return;
      const idx = this.doc.rows.findIndex(row => row.id === rowId);
      if (idx < 0) return;
      seen.add(rowId);
      this._setRowSelectionState(rowId, idx, mode);
    };
    host.addEventListener('pointerdown', (e) => {
      const cb = e.target.closest?.('.sn2-row-check');
      if (!cb || e.button !== 0) return;
      const rowId = cb.closest?.('.sn2-row')?.dataset.rowId || '';
      if (!rowId) return;
      e.preventDefault();
      e.stopPropagation();
      active = true;
      pointerId = e.pointerId;
      seen.clear();
      mode = !(this._rowSelection?.has(rowId));
      this._suppressRowCheckClick = true;
      try { host.setPointerCapture(pointerId); } catch {}
      apply(cb);
    });
    host.addEventListener('pointermove', (e) => {
      if (!active) return;
      apply(document.elementFromPoint(e.clientX, e.clientY));
    });
    const end = () => {
      if (!active) return;
      active = false;
      try { host.releasePointerCapture(pointerId); } catch {}
      setTimeout(() => { this._suppressRowCheckClick = false; }, 0);
    };
    host.addEventListener('pointerup', end);
    host.addEventListener('pointercancel', end);
    host.addEventListener('lostpointercapture', end);
  },

  _syncTextCellLiveSize(textEl) {
    if (!textEl?.isConnected) return;
    const rowEl = textEl.closest?.('.sn2-row');
    const scrollEl = textEl.closest?.('.sn2-scroll');
    if (!rowEl || !scrollEl) return;
    const z = (typeof _getZoom === 'function' ? _getZoom() : 1) || 1;
    const isVertical = scrollEl.classList.contains('sn2-vertical');
    if (isVertical) {
      const currentWidth = rowEl.getBoundingClientRect().width / z;
      const nextWidth = Math.max(24, Math.ceil(textEl.scrollWidth || currentWidth || 0));
      rowEl.style.minWidth = `${nextWidth}px`;
      return;
    }
    const currentHeight = rowEl.getBoundingClientRect().height / z;
    const nextHeight = Math.max(28, Math.ceil(textEl.scrollHeight || currentHeight || 0));
    rowEl.style.minHeight = `${nextHeight}px`;
    if (textEl.dataset.overflow && textEl.dataset.overflow !== 'wrap') {
      const currentTextWidth = textEl.getBoundingClientRect().width / z;
      const nextTextWidth = Math.max(60, Math.ceil(textEl.scrollWidth || currentTextWidth || 0));
      textEl.style.minWidth = `${nextTextWidth}px`;
    }
  },

  _scheduleTextCellLiveResize(textEl) {
    if (!textEl?.isConnected) return;
    if (this._textCellLiveResizeRaf) cancelAnimationFrame(this._textCellLiveResizeRaf);
    this._textCellLiveResizeRaf = requestAnimationFrame(() => {
      this._textCellLiveResizeRaf = 0;
      this._syncTextCellLiveSize(textEl);
    });
  },

  _sanitizeRoleCellSelection() {
    if (!this._roleCellSelection || !this.doc?.rows) return;
    const visible = new Set(this.doc.rows.filter(row => this._isRoleVisible(row.role || '', row.status || '')).map(row => row.id));
    for (const rowId of [...this._roleCellSelection]) {
      if (!visible.has(rowId)) this._roleCellSelection.delete(rowId);
    }
  },

  _roleCellRows(fallbackRowId = '') {
    this._sanitizeRoleCellSelection();
    const ids = new Set(this._roleCellSelection || []);
    if (!ids.size && fallbackRowId) ids.add(fallbackRowId);
    return this.doc.rows.filter(row => ids.has(row.id));
  },

  _roleButtonByRowId(rowId) {
    return [...(this.host?.querySelectorAll('.sn2-role-btn') || [])].find(btn => btn.dataset.rowId === rowId) || null;
  },

  _updateRoleCellSelectionUI() {
    this._sanitizeRoleCellSelection();
    this.host?.querySelectorAll('.sn2-role-btn').forEach((btn) => {
      const selected = !!this._roleCellSelection?.has(btn.dataset.rowId);
      btn.classList.toggle('sn2-role-cell-selected', selected);
      btn.setAttribute('aria-selected', selected ? 'true' : 'false');
    });
  },

  _clearRoleCellSelection() {
    if (this._roleCellSelection) this._roleCellSelection.clear();
    this._lastRoleCellIdx = -1;
    this._updateRoleCellSelectionUI();
  },

  _setRoleCellRange(fromIdx, toIdx, baseSet = null) {
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (!this._roleCellSelection) this._roleCellSelection = new Set();
    const next = new Set(baseSet || []);
    const from = Math.max(0, Math.min(fromIdx, toIdx));
    const to = Math.min(this.doc.rows.length - 1, Math.max(fromIdx, toIdx));
    for (let i = from; i <= to; i++) {
      const row = this.doc.rows[i];
      if (row && this._isRoleVisible(row.role || '', row.status || '')) next.add(row.id);
    }
    this._roleCellSelection = next;
    this._updateRoleCellSelectionUI();
  },

  _selectRoleCell(rowId, idx, options = {}) {
    if (!rowId || idx < 0) return;
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (!this._roleCellSelection) this._roleCellSelection = new Set();
    const ctrl = !!options.ctrl;
    if (options.shift && this._lastRoleCellIdx >= 0) {
      this._setRoleCellRange(this._lastRoleCellIdx, idx, ctrl ? this._roleCellSelection : null);
    } else if (ctrl) {
      if (this._roleCellSelection.has(rowId)) this._roleCellSelection.delete(rowId);
      else this._roleCellSelection.add(rowId);
      this._lastRoleCellIdx = idx;
      this._updateRoleCellSelectionUI();
    } else {
      this._roleCellSelection.clear();
      this._roleCellSelection.add(rowId);
      this._lastRoleCellIdx = idx;
      this._updateRoleCellSelectionUI();
    }
  },

  _handleRoleCellClick(roleBtn, e) {
    if (!roleBtn) return false;
    if (this._suppressRoleCellClick) { this._suppressRoleCellClick = false; return true; }
    if (this._activeCellRowId) this._clearActiveCell?.();
    const rowId = roleBtn.dataset.rowId || '';
    const idx = this.doc.rows.findIndex(row => row.id === rowId);
    this._selectRoleCell(rowId, idx, { shift: e?.shiftKey, ctrl: e?.ctrlKey || e?.metaKey });
    if (!e?.shiftKey && !(e?.ctrlKey || e?.metaKey)) {
      this._activeCellRowId = rowId;
      this._activeCellColId = '_role';
      this._cellEditMode = false;
    }
    roleBtn.focus();
    return true;
  },

  _nextVisibleRoleIndex(idx, dir) {
    let next = idx + dir;
    while (next >= 0 && next < this.doc.rows.length) {
      const row = this.doc.rows[next];
      if (this._isRoleVisible(row.role || '', row.status || '')) return next;
      next += dir;
    }
    return -1;
  },

  _writeRoleClipboard(text) {
    const value = String(text || '');
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(value).catch(() => this._writeRoleClipboardFallback(value));
      return;
    }
    this._writeRoleClipboardFallback(value);
  },

  _writeRoleClipboardFallback(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('aria-hidden', 'true');
    ta.tabIndex = -1;
    ta.style.cssText = 'position:fixed;left:-9999px;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try { document.execCommand('copy'); } catch {}
    ta.remove();
  },

  _copyRoleCellSelection(fallbackRowId = '') {
    const rows = this._roleCellRows(fallbackRowId);
    if (!rows.length) return false;
    this._writeRoleClipboard(rows.map(row => row.role || '').join('\n'));
    return true;
  },

  _applyRoleValuesToSelection(text, fallbackRowId = '', undoLabel = 'タイプ貼り付け') {
    const rows = this._roleCellRows(fallbackRowId);
    if (!rows.length) return false;
    const values = String(text || '').replace(/\r\n?/g, '\n').split('\n');
    this._pushUndo(undoLabel);
    let needsRender = false;
    rows.forEach((row, i) => {
      const idx = this.doc.rows.indexOf(row);
      const value = (values.length === 1 ? values[0] : (values[i] ?? values[values.length - 1] ?? '')).trim();
      const rowEl = this._roleButtonByRowId(row.id)?.closest?.('.sn2-row') || null;
      if (rowEl && typeof this._setRowRole === 'function') this._setRowRole(idx, rowEl, value);
      else {
        if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
          globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, row, value);
        } else {
          row.role = value;
        }
        needsRender = true;
      }
    });
    if (needsRender) this._render();
    this._markDirty({ skipUndo: true });
    this._updateRoleCellSelectionUI();
    return true;
  },

  async _pasteRoleCellSelectionFromClipboard(fallbackRowId = '') {
    try {
      const text = await navigator.clipboard?.readText?.();
      if (text == null) return false;
      return this._applyRoleValuesToSelection(text, fallbackRowId);
    } catch {
      if (typeof showStatus === 'function') showStatus('クリップボードを読み取れませんでした', true);
      return false;
    }
  },

  _clearSelectedRoleCells(fallbackRowId = '') {
    return this._applyRoleValuesToSelection('', fallbackRowId, 'タイプ削除');
  },

  _handleRoleCellKeydown(roleBtn, e) {
    const rowId = roleBtn?.dataset.rowId || '';
    const idx = this.doc.rows.findIndex(row => row.id === rowId);
    if (!rowId || idx < 0) return false;
    const key = e.key;
    const lk = String(key || '').toLowerCase();
    const mod = e.ctrlKey || e.metaKey;
    if (key === 'Enter' && !mod) {
      e.preventDefault(); e.stopPropagation();
      this._selectRoleCell(rowId, idx);
      this._showRoleMenu(roleBtn);
      return true;
    }
    if (mod && !e.shiftKey && (lk === 'c' || lk === 'x')) {
      e.preventDefault(); e.stopPropagation();
      this._copyRoleCellSelection(rowId);
      if (lk === 'x') this._clearSelectedRoleCells(rowId);
      return true;
    }
    if (mod && !e.shiftKey && lk === 'v') {
      e.preventDefault(); e.stopPropagation();
      this._pasteRoleCellSelectionFromClipboard(rowId);
      return true;
    }
    if ((key === 'Delete' || key === 'Backspace') && !mod) {
      e.preventDefault(); e.stopPropagation();
      this._clearSelectedRoleCells(rowId);
      return true;
    }
    const isVertical = this.doc.editor?.viewMode === 'vertical';
    const dir = key === (isVertical ? 'ArrowRight' : 'ArrowUp') ? -1 : key === (isVertical ? 'ArrowLeft' : 'ArrowDown') ? 1 : 0;
    if (dir) {
      const nextIdx = this._nextVisibleRoleIndex(idx, dir);
      if (nextIdx < 0) return false;
      e.preventDefault(); e.stopPropagation();
      const nextRow = this.doc.rows[nextIdx];
      this._selectRoleCell(nextRow.id, nextIdx, { shift: e.shiftKey, ctrl: mod });
      const nextBtn = this._roleButtonByRowId(nextRow.id);
      if (nextBtn) {
        nextBtn.focus();
        nextBtn.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
      }
      return true;
    }
    const crossCol = isVertical
      ? (key === 'ArrowUp' ? 'prev-col' : key === 'ArrowDown' ? 'next-col' : null)
      : (key === 'ArrowLeft' ? 'prev-col' : key === 'ArrowRight' ? 'next-col' : null);
    // Tab はその行のタイプ選択メニューを開く（Shift+Tab は従来どおり前のセルへ移動）
    if (key === 'Tab' && !e.shiftKey) {
      e.preventDefault(); e.stopPropagation();
      this._selectRoleCell(rowId, idx);
      this._showRoleMenu(roleBtn);
      return true;
    }
    if (crossCol || key === 'Tab') {
      e.preventDefault(); e.stopPropagation();
      this._activeCellRowId = rowId;
      this._activeCellColId = '_role';
      this._cellEditMode = false;
      if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
      this._navigateCell(key === 'Tab' ? (e.shiftKey ? 'prev-col' : 'next-col') : crossCol);
      return true;
    }
    if (key === 'Escape') {
      e.preventDefault(); e.stopPropagation();
      if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
      this._activeCellRowId = null;
      this._activeCellColId = null;
      this._cellEditMode = false;
      return true;
    }
    return false;
  },

  _bindRoleCellSelection(host) {
    let pending = false;
    let dragging = false;
    let startIdx = -1;
    let startX = 0;
    let startY = 0;
    let pointerId = 0;
    let baseSet = null;
    const threshold = 4;
    host.addEventListener('pointerdown', (e) => {
      const btn = e.target.closest?.('.sn2-role-btn');
      if (!btn || e.button !== 0) return;
      pending = true;
      dragging = false;
      startX = e.clientX;
      startY = e.clientY;
      pointerId = e.pointerId;
      startIdx = this.doc.rows.findIndex(row => row.id === btn.dataset.rowId);
      baseSet = (e.ctrlKey || e.metaKey) ? new Set(this._roleCellSelection || []) : new Set();
    });
    host.addEventListener('pointermove', (e) => {
      if (!pending) return;
      if (!dragging && Math.abs(e.clientX - startX) + Math.abs(e.clientY - startY) < threshold) return;
      dragging = true;
      try { host.setPointerCapture(pointerId); } catch {}
      const over = document.elementFromPoint(e.clientX, e.clientY)?.closest?.('.sn2-role-btn');
      const overIdx = this.doc.rows.findIndex(row => row.id === over?.dataset.rowId);
      if (startIdx >= 0 && overIdx >= 0) this._setRoleCellRange(startIdx, overIdx, baseSet);
    });
    const end = () => {
      if (dragging) {
        this._suppressRoleCellClick = true;
        setTimeout(() => { this._suppressRoleCellClick = false; }, 0);
      }
      try { if (pointerId) host.releasePointerCapture(pointerId); } catch {}
      pending = false;
      dragging = false;
      pointerId = 0;
    };
    host.addEventListener('pointerup', end);
    host.addEventListener('pointercancel', end);
    host.addEventListener('lostpointercapture', end);
  },

  _showRoleCellContextMenu(roleBtn, e) {
    if (!roleBtn) return false;
    const rowId = roleBtn.dataset.rowId || '';
    const idx = this.doc.rows.findIndex(row => row.id === rowId);
    if (!this._roleCellSelection?.has(rowId)) this._selectRoleCell(rowId, idx);
    document.querySelectorAll('.sn2-role-cell-menu').forEach(el => el.remove());
    const menu = document.createElement('div');
    menu.className = 'sn2-role-cell-menu sn2-header-popup';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', 'タイプセル操作');
    const close = (options = {}) => {
      menu.remove();
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeydown, true);
      if (options.restoreFocus) roleBtn.focus?.();
    };
    const onPointerDown = (ev) => {
      if (!menu.contains(ev.target)) close({ restoreFocus: true });
    };
    const onKeydown = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      close({ restoreFocus: true });
    };
    const mk = (label, fn, actionId = '') => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'sn2-header-popup-item';
      btn.setAttribute('role', 'menuitem');
      if (actionId) {
        btn.dataset.sn2RoleCellMenuAction = actionId;
        btn.dataset.e2eId = `sn2-role-cell-menu-${actionId}`;
      }
      btn.textContent = label;
      btn.addEventListener('click', () => { close(); fn(); });
      return btn;
    };
    menu.appendChild(mk('コピー', () => this._copyRoleCellSelection(rowId), 'copy'));
    menu.appendChild(mk('貼り付け', () => this._pasteRoleCellSelectionFromClipboard(rowId), 'paste'));
    menu.appendChild(mk('削除', () => this._clearSelectedRoleCells(rowId), 'clear'));
    menu.style.cssText = 'position:fixed;z-index:10000;min-width:140px;';
    document.body.appendChild(menu);
    const rect = { left: e.clientX, right: e.clientX, top: e.clientY, bottom: e.clientY };
    if (typeof positionPopup === 'function') positionPopup(menu, rect);
    else if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);
    requestAnimationFrame(() => menu.querySelector('.sn2-header-popup-item')?.focus());
    setTimeout(() => {
      document.addEventListener('pointerdown', onPointerDown, true);
      document.addEventListener('keydown', onKeydown, true);
    }, 0);
    return true;
  },

});

;

/* === gb-scriptnote-navigation.js === */
;
/* gb-scriptnote-navigation.js: シナリオのExcel風セルナビゲーション
   クリックはセルを「アクティブ化」するだけ（強調表示のみ、編集はしない）。
   Enter またはダブルクリックで編集モードに入り、Escapeで編集モード→アクティブ→非アクティブの順に抜ける。
   矢印キー/Tabでセル間を移動する（縦書き時は論理方向を物理キーに読み替える）。
   既存のテキストセル範囲選択 (_textCellSelection) ・行選択 (_rowSelection) ・
   タイプセル選択 (_roleCellSelection) とは相互排他: アクティブセルへ移動すると
   これらの選択は解除される。 */

Object.assign(ScriptNoteEditor.prototype, {

  _initCellNavigation() {
    this._activeCellRowId = null;
    this._activeCellColId = null;
    this._cellEditMode = false;
  },

  // 表示順の列ID配列を返す（非表示列は除外）。_render() のヘッダー構築ロジック
  // (visibleStandardColumns / columnOrder) と同じ並び替えを行い、実際の見た目の
  // 左右（縦書きは上下）の並びとナビゲーション順序を一致させる。
  _getNavigableColumnOrder() {
    const customCols = this._getCustomColumns();
    const statusEnabled = !!this.doc.editor?.statusEnabled;
    const visCols = {
      _handle: true, _gutter: true, _gutter2: true, _role: true,
      _status: statusEnabled, _text: true,
      ...(this.doc.editor?.visibleStandardColumns || {}),
    };
    if (!statusEnabled) visCols._status = false;
    const allStdIds = ['_handle', '_gutter', '_gutter2', '_role', '_status', '_text'];
    const unsortedIds = [
      ...allStdIds.filter(id => visCols[id] !== false),
      ...customCols.filter(cc => cc.visible !== false).map(cc => cc.id),
    ];
    const colOrder = this.doc.editor?.columnOrder;
    if (!colOrder) return unsortedIds;
    // columnOrderで並べ替え（_handleは常に先頭。_render()のヘッダー構築と同じ規則）
    const hasHandle = unsortedIds.includes('_handle');
    const rest = unsortedIds.filter(id => id !== '_handle');
    rest.sort((a, b) => {
      const ai = colOrder.indexOf(a), bi = colOrder.indexOf(b);
      if (ai >= 0 && bi >= 0) return ai - bi;
      if (ai >= 0) return -1;
      if (bi >= 0) return 1;
      return 0;
    });
    return hasHandle ? ['_handle', ...rest] : rest;
  },

  // rowId・colId からセルのDOM要素を取得する。標準列・カスタム列とも _buildRowEl() の
  // appendCell() が dataset.colId を一貫して設定しているため data-col-id 属性で引く
  // （.sn2-gutter は .sn2-gutter2 にも付いているクラスなのでクラス名だけでは曖昧になる）。
  // カスタム列のテキスト型は、実際に編集可能な内側の .sn2-custom-text を返す
  // （ラッパーの .sn2-custom-cell ではない）。number/select型はラッパーをそのまま返す。
  _getCellElement(rowId, colId) {
    if (!rowId || !colId) return null;
    const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
    if (!rowEl) return null;
    const cell = rowEl.querySelector(`[data-col-id="${colId}"]`);
    if (!cell) return null;
    if (cell.classList.contains('sn2-custom-cell')) {
      return cell.querySelector('.sn2-custom-text') || cell;
    }
    return cell;
  },

  // el（イベントターゲット）が「現在アクティブだが非編集」セルそのもの（またはその内部）かどうかを判定する。
  // ホストのkeydownルーティングと、既存テキストセルkeydownハンドラの抑制判定の両方から使う共通ヘルパー。
  _isActiveNonEditingTarget(el) {
    if (!el || this._cellEditMode || !this._activeCellRowId) return false;
    const activeCellEl = this._getCellElement(this._activeCellRowId, this._activeCellColId);
    if (!activeCellEl) return false;
    return el === activeCellEl || (typeof activeCellEl.contains === 'function' && activeCellEl.contains(el));
  },

  // rowId・colId のセルをアクティブにする。enterEdit=true ならそのまま編集モードへ入る
  // （テキスト系）か、タイプメニューを開く（_role）。それ以外は強調表示のみでフォーカスする。
  _setActiveCell(rowId, colId, enterEdit) {
    if (!rowId || !colId) return;
    // 既存のアクティブセル強調をすべて解除（テキスト系セルはcontentEditableも復元する）
    this.host?.querySelectorAll('.sn2-cell-active').forEach(el => {
      el.classList.remove('sn2-cell-active');
      if (el.classList.contains('sn2-text') || el.classList.contains('sn2-custom-text')) {
        el.contentEditable = 'true';
      }
    });
    // 他の選択系（矩形セル・テキストセル・行・タイプセル選択）とは相互排他
    if (this._gridCellSelection?.size) this._clearGridCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (this._rowSelection?.size) this._clearRowSelection?.();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();

    // 別セルへ切り替える場合は、編集中だったセルの内容をモデルへ同期してから抜ける
    if (this._cellEditMode && (this._activeCellRowId !== rowId || this._activeCellColId !== colId)) {
      this._exitEditMode();
    }

    // 旧セルに残るブラウザ選択範囲をクリアしてカスタムキャレットの残留を防ぐ
    const sel = window.getSelection();
    if (sel?.rangeCount) sel.removeAllRanges();

    this._activeCellRowId = rowId;
    this._activeCellColId = colId;

    const cellEl = this._getCellElement(rowId, colId);
    if (!cellEl) return;
    const isTextLike = cellEl.classList.contains('sn2-text') || cellEl.classList.contains('sn2-custom-text');

    if (enterEdit && isTextLike) {
      this._enterEditMode(cellEl);
      return;
    }
    if (enterEdit && colId === '_role') {
      // タイプセルの「編集」＝タイプ変更メニューを開く（既存の役割選択・メニュー機構をそのまま使う）
      this._cellEditMode = false;
      if (typeof this._showRoleMenu === 'function') this._showRoleMenu(cellEl, { fromNav: true });
      return;
    }
    // それ以外: アクティブ化のみ（編集はしない）
    this._cellEditMode = false;
    cellEl.classList.add('sn2-cell-active');
    if (isTextLike) cellEl.contentEditable = 'false';
    cellEl.tabIndex = 0;
    cellEl.focus();
  },

  _enterEditMode(cellEl) {
    if (!cellEl) cellEl = this._getCellElement(this._activeCellRowId, this._activeCellColId);
    if (!cellEl) return;
    this._cellEditMode = true;
    cellEl.classList.remove('sn2-cell-active');
    if (cellEl.classList.contains('sn2-text') || cellEl.classList.contains('sn2-custom-text')) {
      cellEl.contentEditable = 'true';
      cellEl.focus();
      // カーソルを先頭に置く
      const sel = window.getSelection();
      if (sel) {
        const range = document.createRange();
        range.selectNodeContents(cellEl);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
      }
    }
  },

  // 編集モードを抜ける。標準テキスト列は _syncRowFromDom()、カスタムテキスト列は
  // 既存のfocusoutハンドラと同じ代入経路でモデルへ反映してから、
  // 「アクティブだが非編集」の見た目・状態に戻す。
  _exitEditMode() {
    const cellEl = this._getCellElement(this._activeCellRowId, this._activeCellColId);
    if (!cellEl) { this._cellEditMode = false; return; }
    this._cellEditMode = false;
    const isStdText = cellEl.classList.contains('sn2-text');
    const isCustomText = cellEl.classList.contains('sn2-custom-text');
    if (isStdText) {
      try { this._syncRowFromDom(cellEl, { skipUndo: true }); } catch {}
      if (typeof this._endTextInputUndo === 'function') this._endTextInputUndo();
    } else if (isCustomText) {
      const rowEl = cellEl.closest('.sn2-row');
      const row = rowEl ? this.doc.rows.find(r => r.id === rowEl.dataset.rowId) : null;
      const colId = cellEl.closest('.sn2-custom-cell')?.dataset.colId;
      if (row && colId) {
        if (!row.columns) row.columns = {};
        row.columns[colId] = cellEl.textContent || '';
        this._markDirty({ skipUndo: true });
      }
    }
    if (isStdText || isCustomText) cellEl.contentEditable = 'false';
    // 編集モードのブラウザ選択範囲をクリアしてカスタムキャレットの残留を防ぐ
    const sel = window.getSelection();
    if (sel?.rangeCount) sel.removeAllRanges();
    cellEl.classList.add('sn2-cell-active');
    cellEl.tabIndex = 0;
    cellEl.focus();
    if (this._caretSelChangeHandler) this._caretSelChangeHandler();
  },

  // アクティブセルを完全に解除する（編集中なら先に抜けてから解除）
  _clearActiveCell() {
    if (this._cellEditMode) this._exitEditMode();
    this.host?.querySelectorAll('.sn2-cell-active').forEach(el => {
      el.classList.remove('sn2-cell-active');
      // 非アクティブに戻すテキスト系セルは、直接クリックでの即編集に戻す
      if (el.classList.contains('sn2-text') || el.classList.contains('sn2-custom-text')) {
        el.contentEditable = 'true';
      }
    });
    this._activeCellRowId = null;
    this._activeCellColId = null;
    this._cellEditMode = false;
  },

  _navigateCell(direction) {
    if (!this._activeCellRowId || !this._activeCellColId) return;
    const cols = this._getNavigableColumnOrder();
    const colIdx = cols.indexOf(this._activeCellColId);
    if (colIdx < 0) return;

    if (direction === 'prev-col' || direction === 'next-col') {
      const step = direction === 'prev-col' ? -1 : 1;
      const newColIdx = this._findFirstVisibleCol(this._activeCellRowId, cols, colIdx + step, step);

      if (newColIdx < 0) {
        // 折り返しモード時は段を跨いで同位置の行へ移動
        const crossRowId = this._findCrossDanRow(this._activeCellRowId, step > 0);
        if (crossRowId) {
          const startIdx = step > 0 ? 0 : cols.length - 1;
          const targetColIdx = this._findFirstVisibleCol(crossRowId, cols, startIdx, step);
          if (targetColIdx >= 0) this._setActiveCell(crossRowId, cols[targetColIdx], false);
          return;
        }
        // 段がない場合はデータ行順で折り返す
        const fallbackRowId = this._findNextVisibleRowId(this._activeCellRowId, step);
        if (fallbackRowId) {
          const startIdx = step > 0 ? 0 : cols.length - 1;
          const targetColIdx = this._findFirstVisibleCol(fallbackRowId, cols, startIdx, step);
          if (targetColIdx >= 0) this._setActiveCell(fallbackRowId, cols[targetColIdx], false);
        }
        return;
      }
      this._setActiveCell(this._activeCellRowId, cols[newColIdx], false);
    } else {
      // prev-row / next-row
      const dir = direction === 'prev-row' ? -1 : 1;
      const nextRowId = this._findNextVisibleRowId(this._activeCellRowId, dir);
      if (!nextRowId) return;
      let targetCol = this._activeCellColId;
      if (this._isCellHiddenByShift(nextRowId, targetCol)) {
        const idx = cols.indexOf(targetCol);
        for (let d = 1; d < cols.length; d++) {
          if (idx + d < cols.length && !this._isCellHiddenByShift(nextRowId, cols[idx + d])) { targetCol = cols[idx + d]; break; }
          if (idx - d >= 0 && !this._isCellHiddenByShift(nextRowId, cols[idx - d])) { targetCol = cols[idx - d]; break; }
        }
      }
      this._setActiveCell(nextRowId, targetCol, false);
    }
  },

  _findNextVisibleRowId(currentRowId, dir) {
    const rows = this.doc.rows;
    let idx = rows.findIndex(r => r.id === currentRowId);
    if (idx < 0) return null;
    for (;;) {
      idx += dir;
      if (idx < 0 || idx >= rows.length) return null;
      const row = rows[idx];
      if (typeof this._isRoleVisible === 'function' && !this._isRoleVisible(row.role || '', row.status || '')) continue;
      return row.id;
    }
  },

  _isCellHiddenByShift(rowId, colId) {
    const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
    if (!rowEl) return false;
    const cell = rowEl.querySelector(`[data-col-id="${colId}"]`);
    return cell ? cell.style.visibility === 'hidden' : false;
  },

  _findCrossDanRow(rowId, isForward) {
    const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${rowId}"]`);
    if (!rowEl) return null;
    const colGroup = rowEl.closest('.sn2-column-group');
    if (!colGroup) return null;
    const groupRows = [...colGroup.querySelectorAll(':scope > .sn2-row')];
    const rowIndex = groupRows.indexOf(rowEl);
    if (rowIndex < 0) return null;
    const adjGroup = isForward ? colGroup.nextElementSibling : colGroup.previousElementSibling;
    if (!adjGroup || !adjGroup.classList.contains('sn2-column-group')) return null;
    const adjRows = [...adjGroup.querySelectorAll(':scope > .sn2-row')];
    if (!adjRows.length) return null;
    return adjRows[Math.min(rowIndex, adjRows.length - 1)]?.dataset?.rowId || null;
  },

  _findFirstVisibleCol(rowId, cols, startIdx, step) {
    for (let i = startIdx; i >= 0 && i < cols.length; i += step) {
      if (!this._isCellHiddenByShift(rowId, cols[i])) return i;
    }
    return -1;
  },

  // 非編集時（アクティブセルのみ存在する状態）のキー操作を処理する。
  // 呼び出し側（ホストのkeydownルーティング）が _isActiveNonEditingTarget() で
  // 対象を確認してから呼ぶ想定だが、単体で呼ばれても安全なように自前でも確認する。
  _handleNavigationKeydown(e) {
    if (this._cellEditMode || !this._activeCellRowId) return false;
    const isVert = this.doc.editor?.viewMode === 'vertical';

    if (e.key === 'Escape') {
      e.preventDefault();
      if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
      this._clearActiveCell();
      return true;
    }

    if (e.key === 'Tab') {
      e.preventDefault();
      // Tab はその行のタイプ選択メニューを開く（Shift+Tab は従来どおり前のセルへ移動）
      if (!e.shiftKey) {
        const roleBtn = this.host?.querySelector(`.sn2-row[data-row-id="${this._activeCellRowId}"] .sn2-role-btn`);
        if (roleBtn && typeof this._showRoleMenu === 'function') {
          this._showRoleMenu(roleBtn, { fromNav: true });
          return true;
        }
      }
      this._navigateCell(e.shiftKey ? 'prev-col' : 'next-col');
      return true;
    }

    if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault(); e.stopPropagation();
      const colId = this._activeCellColId;
      const cellEl = this._getCellElement(this._activeCellRowId, colId);
      if (cellEl?.classList.contains('sn2-text') || cellEl?.classList.contains('sn2-custom-text')) {
        this._enterEditMode(cellEl);
      } else if (colId === '_role') {
        this._setActiveCell(this._activeCellRowId, colId, true);
      } else if (cellEl?.classList.contains('sn2-custom-cell')) {
        const nativeCtrl = cellEl.querySelector('.sn2-custom-input, .sn2-custom-select');
        if (nativeCtrl) {
          this._cellEditMode = true;
          cellEl.classList.remove('sn2-cell-active');
          nativeCtrl.focus();
        }
      }
      return true;
    }

    if (e.key === 'Enter' && e.shiftKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault(); e.stopPropagation();
      this._insertEmptyRowBelow();
      return true;
    }

    // 矢印キーは修飾キーなし（プレーン）のときだけセル移動として扱う。
    // Ctrl+上下（行入れ替え）・Alt+矢印（タイプセル移動／5行スキップ）など、
    // 編集中に使う既存ショートカットを非編集時に奪わないための保護。
    if (!e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey) {
      let logicalDir = null;
      if (e.key === 'ArrowLeft') logicalDir = isVert ? 'next-row' : 'prev-col';
      else if (e.key === 'ArrowRight') logicalDir = isVert ? 'prev-row' : 'next-col';
      else if (e.key === 'ArrowUp') logicalDir = isVert ? 'prev-col' : 'prev-row';
      else if (e.key === 'ArrowDown') logicalDir = isVert ? 'next-col' : 'next-row';
      if (logicalDir) {
        e.preventDefault();
        this._navigateCell(logicalDir);
        return true;
      }
    }

    return false;
  },

  _insertEmptyRowBelow() {
    if (!this._activeCellRowId) return;
    const idx = this.doc.rows.findIndex(r => r.id === this._activeCellRowId);
    if (idx < 0) return;
    this._pushUndo('行追加');
    let newRole = '';
    if (this._filterRoles && this._filterRoles.size === 1) newRole = [...this._filterRoles][0];
    let newStatus = this.doc.rows[idx].status || '';
    if (this._filterStatuses && this._filterStatuses.size === 1) newStatus = [...this._filterStatuses][0];
    const newRow = { id: `sn-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, role: newRole, status: newStatus, text: '', columns: {} };
    if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
      globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, newRow, newRole);
    }
    this.doc.rows.splice(idx + 1, 0, newRow);
    this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });
    this._setActiveCell(newRow.id, this._activeCellColId || '_text', false);
  },

});

;

/* === gb-scriptnote-text-selection.js === */
;
/* gb-scriptnote-text-selection.js: シナリオのセル範囲選択と表形式クリップボード
   矩形ドラッグは行ID×列IDのセル範囲として保持し、TSV/HTML tableで表計算ソフトと
   双方向コピー＆ペーストする。従来のテキスト列・タイプ列だけの範囲選択も維持する。 */

const _SN2_GRID_CELL_KEY_SEPARATOR = '\u001f';

function _sn2GridCellKey(rowId, colId) {
  return String(rowId || '') + _SN2_GRID_CELL_KEY_SEPARATOR + String(colId || '');
}

function _sn2GridCellParts(key) {
  const raw = String(key || '');
  const index = raw.indexOf(_SN2_GRID_CELL_KEY_SEPARATOR);
  return index < 0 ? ['', ''] : [raw.slice(0, index), raw.slice(index + 1)];
}

function _sn2QuoteTsvCell(value) {
  const text = String(value == null ? '' : value);
  return /[\t\n\r"]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}

function _sn2EscapeClipboardHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/\n/g, '<br>');
}

function _sn2ParseClipboardTable(rawText) {
  const text = String(rawText || '').replace(/\r\n?/g, '\n');
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      if (quoted && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (quoted) {
        quoted = false;
      } else if (!cell) {
        quoted = true;
      } else {
        cell += ch;
      }
      continue;
    }
    if (!quoted && ch === '\t') {
      row.push(cell);
      cell = '';
      continue;
    }
    if (!quoted && ch === '\n') {
      row.push(cell);
      rows.push(row);
      row = [];
      cell = '';
      continue;
    }
    cell += ch;
  }
  row.push(cell);
  rows.push(row);
  if (text.endsWith('\n') && rows.length > 1 && rows[rows.length - 1].length === 1 && rows[rows.length - 1][0] === '') rows.pop();
  return rows;
}

Object.assign(ScriptNoteEditor.prototype, {

  _gridVisibleRowIds() {
    return (this.doc?.rows || [])
      .filter(row => this._isRoleVisible(row.role || '', row.status || ''))
      .map(row => row.id);
  },

  _gridSelectableColumnIds() {
    const firstRow = this.host?.querySelector('.sn2-row[data-row-id]');
    const domIds = firstRow
      ? [...firstRow.children].map(cell => cell.dataset?.colId || '').filter(colId => colId && colId !== '_handle')
      : [];
    if (domIds.length) return domIds;
    const statusEnabled = !!this.doc?.editor?.statusEnabled;
    const visible = {
      _gutter: true,
      _gutter2: true,
      _role: true,
      _status: statusEnabled,
      _text: true,
      ...(this.doc?.editor?.visibleStandardColumns || {}),
    };
    if (!statusEnabled) visible._status = false;
    const ids = ['_gutter', '_gutter2', '_role', '_status', '_text']
      .filter(colId => visible[colId] !== false)
      .concat((this.doc?.editor?.customColumns || []).filter(col => col?.id && col.visible !== false).map(col => col.id));
    const order = Array.isArray(this.doc?.editor?.columnOrder) ? this.doc.editor.columnOrder : [];
    return ids.sort((left, right) => {
      const li = order.indexOf(left);
      const ri = order.indexOf(right);
      if (li >= 0 && ri >= 0) return li - ri;
      if (li >= 0) return -1;
      if (ri >= 0) return 1;
      return 0;
    });
  },

  _sanitizeGridCellSelection() {
    if (!this._gridCellSelection) return;
    const rows = new Set(this._gridVisibleRowIds());
    const cols = new Set(this._gridSelectableColumnIds());
    for (const key of [...this._gridCellSelection]) {
      const [rowId, colId] = _sn2GridCellParts(key);
      if (!rows.has(rowId) || !cols.has(colId)) this._gridCellSelection.delete(key);
    }
  },

  _updateGridCellSelectionUI() {
    this._sanitizeGridCellSelection();
    this.host?.querySelectorAll('.sn2-row[data-row-id] > [data-col-id]').forEach(cell => {
      const rowId = cell.parentElement?.dataset?.rowId || '';
      const colId = cell.dataset.colId || '';
      cell.classList.toggle('sn2-grid-cell-selected', !!this._gridCellSelection?.has(_sn2GridCellKey(rowId, colId)));
    });
  },

  _clearGridCellSelection() {
    if (this._gridCellSelection) this._gridCellSelection.clear();
    this._gridCellAnchor = null;
    this._updateGridCellSelectionUI();
  },

  _beginGridCellDragSelection(rowId, colId, baseSet = null) {
    if (this._rowSelection?.size) this._clearRowSelection?.();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection?.();
    if (this._textCellSelection?.size) this._clearTextCellSelection?.();
    if (this._activeCellRowId) this._clearActiveCell?.();
    this._gridCellSelection = new Set(baseSet || []);
    this._gridCellAnchor = { rowId, colId };
  },

  _setGridCellRange(anchorRowId, anchorColId, targetRowId, targetColId, baseSet = null) {
    const rowIds = this._gridVisibleRowIds();
    const colIds = this._gridSelectableColumnIds();
    const rowStart = rowIds.indexOf(anchorRowId);
    const rowEnd = rowIds.indexOf(targetRowId);
    const colStart = colIds.indexOf(anchorColId);
    const colEnd = colIds.indexOf(targetColId);
    if (rowStart < 0 || rowEnd < 0 || colStart < 0 || colEnd < 0) return false;
    const next = new Set(baseSet || []);
    const firstRow = Math.min(rowStart, rowEnd);
    const lastRow = Math.max(rowStart, rowEnd);
    const firstCol = Math.min(colStart, colEnd);
    const lastCol = Math.max(colStart, colEnd);
    for (let rowIndex = firstRow; rowIndex <= lastRow; rowIndex++) {
      for (let colIndex = firstCol; colIndex <= lastCol; colIndex++) {
        next.add(_sn2GridCellKey(rowIds[rowIndex], colIds[colIndex]));
      }
    }
    this._gridCellSelection = next;
    this._gridCellAnchor = { rowId: anchorRowId, colId: anchorColId };
    this._updateGridCellSelectionUI();
    return true;
  },

  _gridCellSelectionBounds() {
    this._sanitizeGridCellSelection();
    if (!this._gridCellSelection?.size) return null;
    const rowIds = this._gridVisibleRowIds();
    const colIds = this._gridSelectableColumnIds();
    let firstRow = rowIds.length;
    let lastRow = -1;
    let firstCol = colIds.length;
    let lastCol = -1;
    this._gridCellSelection.forEach(key => {
      const [rowId, colId] = _sn2GridCellParts(key);
      const rowIndex = rowIds.indexOf(rowId);
      const colIndex = colIds.indexOf(colId);
      if (rowIndex < 0 || colIndex < 0) return;
      firstRow = Math.min(firstRow, rowIndex);
      lastRow = Math.max(lastRow, rowIndex);
      firstCol = Math.min(firstCol, colIndex);
      lastCol = Math.max(lastCol, colIndex);
    });
    if (lastRow < firstRow || lastCol < firstCol) return null;
    return { rowIds, colIds, firstRow, lastRow, firstCol, lastCol };
  },

  _gridCellValue(rowId, colId) {
    const row = this.doc?.rows?.find(item => item.id === rowId);
    if (!row) return '';
    if (colId === '_role') return row.role || '';
    if (colId === '_status') return row.status || '';
    if (colId === '_text') return typeof _sn2StripRubyToPlain === 'function' ? _sn2StripRubyToPlain(row.text || '') : (row.text || '');
    if (colId === '_gutter' || colId === '_gutter2') {
      const rowEl = [...(this.host?.querySelectorAll('.sn2-row[data-row-id]') || [])].find(el => el.dataset.rowId === rowId);
      return rowEl?.querySelector(`[data-col-id="${colId}"]`)?.textContent || '';
    }
    return row.columns?.[colId] ?? '';
  },

  _gridSelectionMatrix() {
    const bounds = this._gridCellSelectionBounds();
    if (!bounds) return null;
    const matrix = [];
    for (let rowIndex = bounds.firstRow; rowIndex <= bounds.lastRow; rowIndex++) {
      const values = [];
      for (let colIndex = bounds.firstCol; colIndex <= bounds.lastCol; colIndex++) {
        const rowId = bounds.rowIds[rowIndex];
        const colId = bounds.colIds[colIndex];
        values.push(this._gridCellSelection.has(_sn2GridCellKey(rowId, colId)) ? this._gridCellValue(rowId, colId) : '');
      }
      matrix.push(values);
    }
    return { bounds, matrix };
  },

  _handleGridCellSelectionCopy(e) {
    if (!this._gridCellSelection?.size || !this.host?.isConnected) return false;
    if (typeof this._isRowSelectionOwnerActive === 'function' && !this._isRowSelectionOwnerActive()) return false;
    const nativeSelection = window.getSelection();
    if (nativeSelection?.rangeCount && !nativeSelection.isCollapsed) return false;
    const table = this._gridSelectionMatrix();
    if (!table?.matrix?.length) return false;
    const tsv = table.matrix.map(row => row.map(_sn2QuoteTsvCell).join('\t')).join('\n');
    const html = '<table><tbody>' + table.matrix.map(row => '<tr>' + row.map(value => `<td>${_sn2EscapeClipboardHtml(value)}</td>`).join('') + '</tr>').join('') + '</tbody></table>';
    e.clipboardData?.setData('text/plain', tsv);
    e.clipboardData?.setData('text/html', html);
    e.preventDefault();
    return true;
  },

  _gridPasteStart(target) {
    const bounds = this._gridCellSelectionBounds();
    if (bounds) return { rowId: bounds.rowIds[bounds.firstRow], colId: bounds.colIds[bounds.firstCol] };
    const cell = target?.closest?.('[data-col-id]');
    const rowId = cell?.closest?.('.sn2-row[data-row-id]')?.dataset?.rowId || this._activeCellRowId || '';
    const colId = cell?.dataset?.colId || this._activeCellColId || '';
    return rowId && colId && colId !== '_handle' ? { rowId, colId } : null;
  },

  _setGridPastedValue(row, colId, value) {
    const text = String(value == null ? '' : value);
    if (colId === '_gutter' || colId === '_gutter2') return false;
    if (colId === '_role') {
      if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
        globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, row, text.trim());
      } else {
        row.role = text.trim();
      }
      return true;
    }
    if (colId === '_status') {
      row.status = text.trim();
      return true;
    }
    if (colId === '_text') {
      row.text = typeof _sn2EscapeScriptNotePlainText === 'function' ? _sn2EscapeScriptNotePlainText(text) : text;
      return true;
    }
    if (!row.columns || typeof row.columns !== 'object') row.columns = {};
    const column = (this.doc?.editor?.customColumns || []).find(item => item?.id === colId);
    if (column?.type === 'number') {
      const numberValue = Number(text);
      row.columns[colId] = text === '' ? '' : (Number.isFinite(numberValue) ? numberValue : '');
    } else {
      row.columns[colId] = text;
    }
    return true;
  },

  _createGridPasteRow(templateRow = null) {
    const row = {
      id: globalThis.crypto?.randomUUID?.() || `sn-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      role: templateRow?.role || '',
      ...(templateRow?.roleRef ? { roleRef: { ...templateRow.roleRef } } : {}),
      status: templateRow?.status || '',
      text: '',
      columns: {},
    };
    if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
      globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, row, row.roleRef || row.role);
    }
    return row;
  },

  _handleGridCellPaste(e, plainText, pasteInCell = false) {
    if (pasteInCell) return false;
    const hasGridSelection = !!this._gridCellSelection?.size;
    const targetCell = e.target?.closest?.('[data-col-id]');
    const hasTableShape = String(plainText || '').includes('\t');
    if (!hasGridSelection && !hasTableShape && !targetCell?.classList?.contains('sn2-custom-cell')) return false;
    const start = this._gridPasteStart(e.target);
    if (!start) return false;
    const matrix = _sn2ParseClipboardTable(plainText);
    if (!matrix.length || !matrix.some(row => row.length)) return false;
    const colIds = this._gridSelectableColumnIds();
    const startColIndex = colIds.indexOf(start.colId);
    const visibleRowIds = this._gridVisibleRowIds();
    const startVisibleRowIndex = visibleRowIds.indexOf(start.rowId);
    if (startColIndex < 0 || startVisibleRowIndex < 0) return false;
    const hasWritableCell = matrix.some(values => values.some((value, colOffset) => {
      const colId = colIds[startColIndex + colOffset];
      return !!colId && colId !== '_gutter' && colId !== '_gutter2';
    }));
    if (!hasWritableCell) return false;
    e.preventDefault();
    this._pushUndo('表を貼り付け');
    const templateRow = this.doc.rows.find(row => row.id === start.rowId) || null;
    const selectedKeys = new Set();
    let changed = false;
    let mappedColumns = 0;
    matrix.forEach((values, rowOffset) => {
      const targetVisibleIndex = startVisibleRowIndex + rowOffset;
      while (targetVisibleIndex >= visibleRowIds.length) {
        const newRow = this._createGridPasteRow(templateRow);
        this.doc.rows.push(newRow);
        visibleRowIds.push(newRow.id);
      }
      const row = this.doc.rows.find(item => item.id === visibleRowIds[targetVisibleIndex]);
      if (!row) return;
      values.forEach((value, colOffset) => {
        const colId = colIds[startColIndex + colOffset];
        if (!colId) return;
        selectedKeys.add(_sn2GridCellKey(row.id, colId));
        if (this._setGridPastedValue(row, colId, value)) changed = true;
        mappedColumns = Math.max(mappedColumns, colOffset + 1);
      });
    });
    if (changed) {
      this._syncCharactersFromRows?.();
      this._calcCache = null;
      this._gridCellSelection = selectedKeys;
      this._gridCellAnchor = { rowId: start.rowId, colId: start.colId };
      this._render();
      this._markDirty({ skipUndo: true });
      this._updateGridCellSelectionUI();
      this._focusGridCellSelectionHost();
      if (typeof showStatus === 'function') showStatus(`表を貼り付けました: ${matrix.length}行 × ${mappedColumns}列`);
    }
    return true;
  },

  _clearSelectedGridCells() {
    this._sanitizeGridCellSelection();
    if (!this._gridCellSelection?.size) return false;
    const targets = [];
    this._gridCellSelection.forEach(key => {
      const [rowId, colId] = _sn2GridCellParts(key);
      const row = this.doc?.rows?.find(item => item.id === rowId);
      if (row && colId !== '_gutter' && colId !== '_gutter2') targets.push([row, colId]);
    });
    if (!targets.length) return false;
    this._pushUndo('セル内容を削除');
    targets.forEach(([row, colId]) => this._setGridPastedValue(row, colId, ''));
    this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });
    this._updateGridCellSelectionUI();
    this._focusGridCellSelectionHost();
    return true;
  },

  _focusGridCellSelectionHost() {
    const host = this.host;
    if (!host?.isConnected || !this._gridCellSelection?.size) return;
    if (!host.hasAttribute('tabindex')) host.setAttribute('tabindex', '-1');
    try { host.focus({ preventScroll: true }); } catch { host.focus(); }
  },

  _sanitizeTextCellSelection() {
    if (!this._textCellSelection || !this.doc?.rows) return;
    const visible = new Set(this.doc.rows.filter(row => this._isRoleVisible(row.role || '', row.status || '')).map(row => row.id));
    for (const rowId of [...this._textCellSelection]) {
      if (!visible.has(rowId)) this._textCellSelection.delete(rowId);
    }
  },

  _updateTextCellSelectionUI() {
    this._sanitizeTextCellSelection();
    this.host?.querySelectorAll('.sn2-text').forEach((el) => {
      const selected = !!this._textCellSelection?.has(el.dataset.rowId);
      el.classList.toggle('sn2-text-cell-selected', selected);
    });
  },

  _clearTextCellSelection() {
    if (this._textCellSelection) this._textCellSelection.clear();
    this._textCellAnchorIdx = -1;
    this._updateTextCellSelectionUI();
  },

  // ドラッグ選択開始時の初期化。排他: 行選択・タイプセル選択とは同時に成立させない
  _beginTextCellDragSelection(anchorRowId = '') {
    if (this._gridCellSelection?.size) this._clearGridCellSelection();
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection();
    if (!this._textCellSelection) this._textCellSelection = new Set();
    const anchorIdx = anchorRowId ? this.doc.rows.findIndex(row => row.id === anchorRowId) : -1;
    if (anchorIdx >= 0) this._textCellAnchorIdx = anchorIdx;
  },

  // アンカー〜現在行の連続範囲で選択を再構築（フィルタ非表示行はスキップ）
  _setTextCellRange(fromIdx, toIdx, baseSet = null) {
    if (this._gridCellSelection?.size) this._clearGridCellSelection();
    if (this._rowSelection?.size) this._clearRowSelection();
    if (this._roleCellSelection?.size) this._clearRoleCellSelection();
    if (!this._textCellSelection) this._textCellSelection = new Set();
    const next = new Set(baseSet || []);
    const from = Math.max(0, Math.min(fromIdx, toIdx));
    const to = Math.min(this.doc.rows.length - 1, Math.max(fromIdx, toIdx));
    for (let i = from; i <= to; i++) {
      const row = this.doc.rows[i];
      if (row && this._isRoleVisible(row.role || '', row.status || '')) next.add(row.id);
    }
    this._textCellSelection = next;
    this._updateTextCellSelectionUI();
  },

  // 選択行のテキストセル内容をクリアする（行削除ではない。undoで復元可能）
  _clearSelectedTextCells() {
    this._sanitizeTextCellSelection();
    const ids = new Set(this._textCellSelection || []);
    if (!ids.size) return false;
    this._pushUndo('セル内容を削除');
    let emptied = false;
    this.doc.rows.forEach((row) => {
      if (!ids.has(row.id) || !row.text) return;
      row.text = '';
      emptied = true;
    });
    if (emptied) this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });
    this._updateTextCellSelectionUI();
    this._focusTextCellSelectionHost();
    return true;
  },

  _copyTextCellSelectionText() {
    this._sanitizeTextCellSelection();
    const ids = new Set(this._textCellSelection || []);
    if (!ids.size) return null;
    const rows = this.doc.rows.filter(row => ids.has(row.id));
    if (!rows.length) return null;
    return rows.map(row => (typeof _sn2StripRubyToPlain === 'function' ? _sn2StripRubyToPlain(row.text || '') : (row.text || ''))).join('\n');
  },

  // document copy イベントの受け口（行選択が無いときのみ interactions 側から呼ばれる）
  _handleTextCellSelectionCopy(e) {
    if (!this._textCellSelection?.size) return false;
    if (!this.host?.isConnected) return false;
    if (typeof this._isRowSelectionOwnerActive === 'function' && !this._isRowSelectionOwnerActive()) return false;
    const sel = window.getSelection();
    if (sel && sel.rangeCount && !sel.isCollapsed) return false; // ネイティブ選択を優先
    const text = this._copyTextCellSelectionText();
    if (text == null) return false;
    e.clipboardData?.setData('text/plain', text);
    e.preventDefault();
    return true;
  },

  // ドラッグ終了後などに host が Delete/Backspace を受けられるようフォーカスを保証する
  _focusTextCellSelectionHost() {
    const host = this.host;
    if (!host?.isConnected || !this._textCellSelection?.size) return;
    const ae = document.activeElement;
    if (ae && host.contains(ae)) return;
    if (!host.hasAttribute('tabindex')) host.setAttribute('tabindex', '-1');
    try { host.focus({ preventScroll: true }); } catch { host.focus(); }
  },

});

;

/* === gb-scriptnote-filter.js === */
;
/* gb-scriptnote-filter.js: シナリオのタイプ/採用状況フィルタ UI */

Object.assign(ScriptNoteEditor.prototype, {

  _isRoleVisible(roleOrRow, statusValue = '') {
    const row = roleOrRow && typeof roleOrRow === 'object' ? roleOrRow : null;
    const role = row ? String(row.role || '') : String(roleOrRow || '');
    const status = row ? String(row.status || '') : String(statusValue || '');
    const effective = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(this.doc, row || role);
    const roleKeys = new Set([role, effective?.name, effective?.type?.name].filter((value) => value != null));
    if (this._hideRoles && [...roleKeys].some((key) => this._hideRoles.has(key))) return false;
    if (this._filterRoles && ![...roleKeys].some((key) => this._filterRoles.has(key))) return false;
    if (this.doc?.editor?.statusEnabled) {
      if (this._hideStatuses && this._hideStatuses.has(status)) return false;
      if (this._filterStatuses && !this._filterStatuses.has(status)) return false;
    }
    return true;
  },

  _showFilterMenu(anchorBtn, positionAnchor = null) {
    document.querySelectorAll('.sn2-filter-popup').forEach((el) => el.remove());
    const anchorForPosition = positionAnchor || anchorBtn;
    const roles = new Set();
    this.doc.rows.forEach((row) => {
      if (row.role) roles.add(row.role);
      const typeName = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(this.doc, row)?.type?.name;
      if (typeName) roles.add(typeName);
    });
    const statusEnabled = !!this.doc.editor?.statusEnabled;
    const statusItems = statusEnabled
      ? [{ label: '（未設定）', key: '', color: '' }, ...this._getStatusList().map((item) => ({ label: item.name, key: item.name, color: item.color }))]
      : [];

    const popup = document.createElement('div');
    popup.className = 'sn2-filter-popup sn2-header-popup';

    const hasAnyFilter = () => !!this._filterRoles
      || !!(this._hideRoles && this._hideRoles.size)
      || !!this._filterStatuses
      || !!(this._hideStatuses && this._hideStatuses.size);

    const updateFilterActive = () => {
      anchorBtn?.classList?.toggle('active', hasAnyFilter());
    };

    const setPresetSelection = (value) => {
      const filterPreset = this.host?.closest?.('.gb-scriptnote-root')?.querySelector('#sn-filter-preset') || document.getElementById('sn-filter-preset');
      if (filterPreset) {
        if (value === '__custom__' && !filterPreset.querySelector('option[value="__custom__"]')) {
          const opt = document.createElement('option');
          opt.value = '__custom__';
          opt.textContent = 'カスタム';
          filterPreset.insertBefore(opt, filterPreset.options[1] || null);
        }
        filterPreset.value = value;
      }
      const comp = (typeof getActiveScriptNoteComponent === 'function') ? getActiveScriptNoteComponent() : null;
      if (comp?._editor === this) comp._activeFilterPreset = value;
      this._activeFilterPreset = value;
    };

    const markCustomFilter = () => setPresetSelection('__custom__');

    let closeHandler;
    let keyHandler;
    const close = () => {
      popup.remove();
      if (closeHandler) document.removeEventListener('pointerdown', closeHandler);
      if (keyHandler) document.removeEventListener('keydown', keyHandler);
    };
    closeHandler = (ev) => {
      if (!popup.contains(ev.target) && ev.target !== anchorBtn && ev.target !== anchorForPosition) close();
    };
    keyHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      close();
      if (typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchorForPosition);
    };

    const allLbl = document.createElement('label');
    allLbl.className = 'sn2-filter-all-row';
    const allCb = document.createElement('input');
    allCb.type = 'checkbox';
    allCb.checked = !hasAnyFilter();
    allCb.addEventListener('change', () => {
      this._filterRoles = null;
      this._hideRoles = null;
      this._filterStatuses = null;
      this._hideStatuses = null;
      this._render();
      updateFilterActive();
      setPresetSelection('__all__');
      allCb.checked = !hasAnyFilter();
    });
    allLbl.appendChild(allCb);
    allLbl.appendChild(document.createTextNode('すべて表示'));
    popup.appendChild(allLbl);

    const sep = document.createElement('div');
    sep.className = 'sn2-header-popup-sep';
    popup.appendChild(sep);

    const appendSection = (title, items, visibleProp, hiddenProp) => {
      if (!items.length) return;
      const titleEl = document.createElement('div');
      titleEl.className = 'sn2-header-popup-label';
      titleEl.textContent = title;
      popup.appendChild(titleEl);

      const headerRow = document.createElement('div');
      headerRow.className = 'sn2-filter-grid-header';
      const showHead = document.createElement('div');
      showHead.textContent = '表示';
      const hideHead = document.createElement('div');
      hideHead.textContent = '非表示';
      const typeHead = document.createElement('div');
      typeHead.className = 'sn2-filter-grid-label';
      typeHead.textContent = title;
      headerRow.appendChild(showHead);
      headerRow.appendChild(hideHead);
      headerRow.appendChild(typeHead);
      popup.appendChild(headerRow);

      const visibleSet = this[visibleProp] || new Set(items.map((item) => item.key));
      items.forEach((item) => {
        const row = document.createElement('div');
        row.className = 'sn2-filter-row';

        const showCb = document.createElement('input');
        showCb.type = 'checkbox';
        showCb.className = 'sn2-filter-checkbox';
        showCb.checked = visibleSet.has(item.key);
        showCb.addEventListener('click', (ev) => {
          if (ev.altKey) {
            ev.preventDefault();
            this[visibleProp] = new Set([item.key]);
            this[hiddenProp] = null;
            popup.querySelectorAll(`input[data-filter-prop="${visibleProp}"]`).forEach((other) => {
              other.checked = other.dataset.filterKey === item.key;
            });
            popup.querySelectorAll(`input[data-filter-hidden-prop="${hiddenProp}"]`).forEach((other) => {
              other.checked = false;
            });
            allCb.checked = false;
            markCustomFilter();
            this._render();
            updateFilterActive();
          }
        });
        showCb.dataset.filterProp = visibleProp;
        showCb.dataset.filterKey = item.key;
        showCb.addEventListener('change', (ev) => {
          if (!this[visibleProp]) this[visibleProp] = new Set(items.map((entry) => entry.key));
          if (ev.target.checked) {
            this[visibleProp].add(item.key);
            if (this[hiddenProp]) {
              this[hiddenProp].delete(item.key);
              if (!this[hiddenProp].size) this[hiddenProp] = null;
            }
            hideCb.checked = false;
          } else {
            this[visibleProp].delete(item.key);
          }
          this._render();
          updateFilterActive();
          allCb.checked = false;
          markCustomFilter();
        });

        const hideCb = document.createElement('input');
        hideCb.type = 'checkbox';
        hideCb.className = 'sn2-filter-checkbox';
        hideCb.checked = !!(this[hiddenProp] && this[hiddenProp].has(item.key));
        hideCb.title = 'チェックすると常に非表示';
        hideCb.dataset.filterHiddenProp = hiddenProp;
        hideCb.dataset.filterKey = item.key;
        hideCb.addEventListener('change', (ev) => {
          if (!this[hiddenProp]) this[hiddenProp] = new Set();
          if (ev.target.checked) {
            this[hiddenProp].add(item.key);
            if (this[visibleProp]) this[visibleProp].delete(item.key);
            showCb.checked = false;
          } else {
            this[hiddenProp].delete(item.key);
          }
          if (!this[hiddenProp].size) this[hiddenProp] = null;
          this._render();
          updateFilterActive();
          allCb.checked = false;
          markCustomFilter();
        });

        const labelEl = document.createElement('span');
        labelEl.className = 'sn2-filter-item-label';
        if (item.color) {
          const dot = document.createElement('span');
          dot.className = 'sn2-status-dot';
          dot.style.background = item.color;
          labelEl.appendChild(dot);
        }
        const text = document.createElement('span');
        text.textContent = item.label;
        labelEl.appendChild(text);

        const showCell = document.createElement('label');
        showCell.className = 'sn2-filter-checkbox-cell';
        showCell.title = `表示: ${item.label}`;
        showCell.appendChild(showCb);

        const hideCell = document.createElement('label');
        hideCell.className = 'sn2-filter-checkbox-cell';
        hideCell.title = `非表示: ${item.label}`;
        hideCell.appendChild(hideCb);

        row.appendChild(showCell);
        row.appendChild(hideCell);
        row.appendChild(labelEl);
        popup.appendChild(row);
      });
    };

    const charaOrder = (globalThis.GBScriptNoteRoleModel?.buildRoleChoices?.(this.doc) || [])
      .map((choice) => choice?.name)
      .filter(Boolean);
    const sortedRoles = Array.from(roles).sort((a, b) => {
      const ai = charaOrder.indexOf(a);
      const bi = charaOrder.indexOf(b);
      if (ai >= 0 && bi >= 0) return ai - bi;
      if (ai >= 0) return -1;
      if (bi >= 0) return 1;
      return a.localeCompare(b);
    }).map((role) => ({ label: role, key: role, color: '' }));

    appendSection('タイプ', [...sortedRoles, { label: '（タイプなし）', key: '', color: '' }], '_filterRoles', '_hideRoles');
    if (statusEnabled) {
      const sep2 = document.createElement('div');
      sep2.className = 'sn2-header-popup-sep';
      popup.appendChild(sep2);
      appendSection('採用状況', statusItems, '_filterStatuses', '_hideStatuses');
    }
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorForPosition,
        close,
      });
    }

    popup.style.cssText = 'position:fixed;z-index:10000;min-width:240px;max-height:420px;overflow-y:auto;';
    positionPopup(popup, anchorForPosition.getBoundingClientRect());
    setTimeout(() => {
      document.addEventListener('pointerdown', closeHandler);
      document.addEventListener('keydown', keyHandler);
    }, 0);
  },

});

;

/* === gb-scriptnote-status.js === */
;
/* gb-scriptnote-status.js: シナリオ行ステータス */

const SCRIPTNOTE_DEFAULT_STATUS_LIST = [
  { name: '案', color: '#ce9178' },
  { name: '採用', color: '#6fa8dc' },
  { name: 'ボツ', color: '#969696' },
  { name: '掲載済み', color: '#6a9955' },
];

function _sn2CloneStatusList(list) {
  return (Array.isArray(list) ? list : []).map((item) => ({
    name: String(item?.name || ''),
    color: String(item?.color || ''),
  }));
}

function _sn2NormalizeStatusList(list) {
  const fallback = _sn2CloneStatusList(SCRIPTNOTE_DEFAULT_STATUS_LIST);
  const src = Array.isArray(list) && list.length ? list : fallback;
  const next = [];
  const seen = new Set();
  src.forEach((item, idx) => {
    const name = String(item?.name || '').trim() || `状態${idx + 1}`;
    if (seen.has(name)) return;
    seen.add(name);
    const color = String(item?.color || fallback[idx % fallback.length]?.color || '#6fa8dc');
    next.push({ name, color });
  });
  return next.length ? next : fallback;
}

Object.assign(ScriptNoteEditor.prototype, {

  _syncFilterButtonState() {
    const root = this.host?.closest?.('.gb-se-root');
    const btn = root?.querySelector?.('#btn-filter');
    const sel = root?.querySelector?.('#sn-filter-preset');
    const statusEnabled = !!this.doc?.editor?.statusEnabled;
    const hasAny = !!this._filterRoles
      || !!(this._hideRoles && this._hideRoles.size)
      || (statusEnabled && !!this._filterStatuses)
      || (statusEnabled && !!(this._hideStatuses && this._hideStatuses.size));
    if (btn) btn.classList.toggle('active', hasAny);
    if (sel && !hasAny) sel.value = '__all__';
  },

  _ensureStatusConfig() {
    if (!this.doc) return [];
    if (!this.doc.editor) this.doc.editor = {};
    if (this.doc.editor.statusEnabled !== true) this.doc.editor.statusEnabled = false;
    this.doc.editor.statusList = _sn2NormalizeStatusList(this.doc.editor.statusList);
    return this.doc.editor.statusList;
  },

  _getStatusList() {
    return this._ensureStatusConfig();
  },

  _clearInvalidStatuses(names = null) {
    if (!this.doc?.rows) return;
    const validNames = new Set(this._getStatusList().map((item) => item.name));
    const removeNames = names
      ? new Set((Array.isArray(names) ? names : [names]).map((item) => String(item || '').trim()).filter(Boolean))
      : null;
    this.doc.rows.forEach((row) => {
      const status = String(row?.status || '').trim();
      if (!status) return;
      if ((removeNames && removeNames.has(status)) || (!removeNames && !validNames.has(status))) delete row.status;
    });
    if (this._filterStatuses?.size) {
      this._filterStatuses.forEach((status) => {
        if (!validNames.has(status)) this._filterStatuses.delete(status);
      });
      if (!this._filterStatuses.size) this._filterStatuses = null;
    }
    if (this._hideStatuses?.size) {
      this._hideStatuses.forEach((status) => {
        if (!validNames.has(status)) this._hideStatuses.delete(status);
      });
      if (!this._hideStatuses.size) this._hideStatuses = null;
    }
    this._syncFilterButtonState?.();
  },

  _getStatusColor(statusName) {
    const found = this._getStatusList().find((item) => item.name === statusName);
    return found?.color || '#6fa8dc';
  },

  _renderRowStatusButton(button, row) {
    if (!button || !row) return;
    const status = String(row.status || '').trim();
    const labelText = status || '未設定';
    button.innerHTML = '';
    button.classList.toggle('is-empty', !status);
    button.dataset.status = status;
    const dot = document.createElement('span');
    dot.className = 'sn2-status-dot';
    if (status) dot.style.background = this._getStatusColor(status);
    const label = document.createElement('span');
    label.className = 'sn2-status-label';
    label.textContent = labelText;
    button.appendChild(dot);
    button.appendChild(label);
    button.setAttribute('aria-label', `採用状況: ${labelText}`);
  },

  _showRowStatusMenu(anchorBtn, row, rowEl = null) {
    if (!anchorBtn || !row || !this.doc?.editor?.statusEnabled) return;
    document.querySelectorAll('.sn2-status-popup').forEach((el) => el.remove());
    const popup = document.createElement('div');
    popup.className = 'sn2-status-popup sn2-header-popup';
    popup.style.cssText = 'position:fixed;z-index:10000;min-width:160px;';
    const items = [
      { label: '未設定', value: '', color: '' },
      ...this._getStatusList().map(item => ({ label: item.name, value: item.name, color: item.color })),
    ];
    let closeHandler = null;
    let escapeHandler = null;
    const closePopup = (restoreFocus = false) => {
      popup.remove();
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (escapeHandler) {
        document.removeEventListener('keydown', escapeHandler, true);
        escapeHandler = null;
      }
      if (restoreFocus && typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchorBtn);
    };
    const applyStatus = (statusValue) => {
      const prevStatus = String(row.status || '');
      const wasVisible = this._isRoleVisible(row.role || '', prevStatus);
      const nextStatus = String(statusValue || '').trim();
      if (prevStatus === nextStatus) return;
      this._pushUndo('採用状況変更');
      if (nextStatus) row.status = nextStatus;
      else delete row.status;
      const isVisible = this._isRoleVisible(row.role || '', row.status || '');
      if (!rowEl || wasVisible !== isVisible) this._render();
      else this._renderRowStatusButton(anchorBtn, row);
      this._markDirty({ skipUndo: true });
    };

    const mkItem = (label, statusValue, color = '') => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'sn2-header-popup-item';
      btn.style.cssText = 'display:flex;align-items:center;gap:8px;width:100%;text-align:left;';
      if ((row.status || '') === statusValue) btn.classList.add('active');
      const dot = document.createElement('span');
      dot.className = 'sn2-status-dot';
      if (color) dot.style.background = color;
      const text = document.createElement('span');
      text.textContent = label;
      btn.appendChild(dot);
      btn.appendChild(text);
      btn.addEventListener('click', () => {
        closePopup(true);
        applyStatus(statusValue);
      });
      return btn;
    };

    popup.appendChild(mkItem(items[0].label, items[0].value, items[0].color));
    const sep = document.createElement('div');
    sep.className = 'sn2-header-popup-sep';
    popup.appendChild(sep);
    items.slice(1).forEach((item) => {
      popup.appendChild(mkItem(item.label, item.value, item.color));
    });
    document.body.appendChild(popup);
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorBtn,
        close: () => closePopup(true),
      });
    }
    positionPopup(popup, anchorBtn.getBoundingClientRect());
    escapeHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closePopup(true);
    };
    document.addEventListener('keydown', escapeHandler, true);
    if (typeof bindMeldexDropdownKeySwitch === 'function') {
      bindMeldexDropdownKeySwitch(anchorBtn, {
        getItems: () => items.map(item => ({ value: item.value, item })),
        getCurrentValue: () => row.status || '',
        onSelect: item => {
          closePopup(false);
          applyStatus(item.value);
        },
        getFreshTrigger: () => anchorBtn.isConnected ? anchorBtn : null,
      });
    }
    closeHandler = (ev) => {
      if (!popup.contains(ev.target) && ev.target !== anchorBtn) {
        closePopup(false);
      }
    };
    setTimeout(() => {
      if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

});

;

/* === gb-scriptnote-search.js === */
;
/* gb-scriptnote-search.js: シナリオ本文の検索置換 */

Object.assign(ScriptNoteEditor.prototype, {

  _closeSearchReplacePopup() {
    if (this._searchPopup?.isConnected) this._searchPopup.remove();
    if (this._searchPopupCloseHandler) {
      document.removeEventListener('pointerdown', this._searchPopupCloseHandler, true);
      this._searchPopupCloseHandler = null;
    }
    if (this._searchPopupKeyHandler) {
      document.removeEventListener('keydown', this._searchPopupKeyHandler, true);
      this._searchPopupKeyHandler = null;
    }
    this._updateSearchPopupUi = null;
    this._searchPopup = null;
  },

  _collectSearchMatches(query) {
    const needle = String(query || '');
    if (!needle) return [];
    const matches = [];
    (Array.isArray(this.doc?.rows) ? this.doc.rows : []).forEach((row, rowIndex) => {
      if (!this._isRoleVisible(row.role || '', row.status || '')) return;
      const plain = _sn2StripRubyToPlain(row.text || '');
      let start = 0;
      while (start <= plain.length) {
        const hit = plain.indexOf(needle, start);
        if (hit < 0) break;
        matches.push({ rowId: row.id, rowIndex, start: hit, end: hit + needle.length });
        start = hit + Math.max(needle.length, 1);
      }
    });
    return matches;
  },

  _syncSearchSourceFromDom() {
    if (typeof this._syncAllFromDom === 'function') this._syncAllFromDom();
  },

  _findVisibleTextBoundary(textEl, targetOffset) {
    let remaining = Math.max(0, Number(targetOffset) || 0);
    let found = null;
    const setElementBoundary = (node, after = false) => {
      const parent = node.parentNode || textEl;
      const index = Array.prototype.indexOf.call(parent.childNodes, node);
      found = { container: parent, offset: Math.max(0, index + (after ? 1 : 0)) };
    };
    const walk = (node) => {
      if (found) return;
      if (node.nodeType === 3) {
        const len = node.textContent.length;
        if (remaining <= len) {
          found = { container: node, offset: remaining };
          return;
        }
        remaining -= len;
        return;
      }
      if (node.nodeType === 1) {
        if (node.tagName === 'BR') {
          if (remaining === 0) { setElementBoundary(node, false); return; }
          if (remaining === 1) { setElementBoundary(node, true); return; }
          remaining -= 1;
          return;
        }
        node.childNodes.forEach(walk);
      }
    };
    textEl.childNodes.forEach(walk);
    return found || { container: textEl, offset: textEl.childNodes.length };
  },

  _selectVisibleTextRange(textEl, startOffset, endOffset) {
    if (!textEl) return;
    textEl.focus();
    const start = this._findVisibleTextBoundary(textEl, startOffset);
    const end = this._findVisibleTextBoundary(textEl, endOffset);
    const range = document.createRange();
    range.setStart(start.container, start.offset);
    range.setEnd(end.container, end.offset);
    const sel = window.getSelection();
    if (!sel) return;
    sel.removeAllRanges();
    sel.addRange(range);
  },

  _findSearchMatchIndex(matches, preferred = null) {
    if (!matches.length) return -1;
    if (!preferred) return 0;
    const prefRow = preferred.rowIndex ?? -1;
    const prefStart = preferred.start ?? -1;
    const idx = matches.findIndex((item) => item.rowIndex > prefRow || (item.rowIndex === prefRow && item.start >= prefStart));
    return idx >= 0 ? idx : 0;
  },

  _activateSearchMatch(match) {
    if (!match) return;
    const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${match.rowId}"]`);
    const textEl = rowEl?.querySelector('.sn2-text');
    if (!textEl) return;
    textEl.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'auto' });
    this._selectVisibleTextRange(textEl, match.start, match.end);
  },

  _refreshSearchState(preferred = null) {
    if (!this._searchState) this._searchState = { query: '', replace: '', matches: [], index: -1 };
    this._syncSearchSourceFromDom();
    this._searchState.matches = this._collectSearchMatches(this._searchState.query);
    this._searchState.index = this._findSearchMatchIndex(this._searchState.matches, preferred);
    return this._searchState;
  },

  _jumpSearchMatch(step) {
    const previous = this._searchState?.matches?.[this._searchState.index] || null;
    const state = this._refreshSearchState(previous);
    if (!state.matches.length) return;
    const len = state.matches.length;
    state.index = ((state.index >= 0 ? state.index : 0) + step + len) % len;
    this._activateSearchMatch(state.matches[state.index]);
    this._updateSearchPopupUi?.();
  },

  _replaceSearchMatch(match, replacement) {
    const row = this.doc?.rows?.find((item) => item.id === match?.rowId);
    if (!row) return false;
    row.text = _sn2ReplaceRawTextByVisibleRange(row.text || '', match.start, match.end, replacement);
    return true;
  },

  _replaceCurrentSearchMatch() {
    const previous = this._searchState?.matches?.[this._searchState.index] || null;
    const state = this._refreshSearchState(previous);
    const match = state.matches?.[state.index];
    if (!match) return;
    this._pushUndo('検索置換');
    if (!this._replaceSearchMatch(match, state.replace || '')) return;
    this._render();
    this._markDirty({ skipUndo: true });
    this._refreshSearchState({ rowIndex: match.rowIndex, start: match.start + (state.replace || '').length });
    this._updateSearchPopupUi?.();
    if (this._searchState.matches.length) this._activateSearchMatch(this._searchState.matches[this._searchState.index]);
  },

  _replaceAllSearchMatches() {
    const state = this._refreshSearchState();
    if (!state.query || !state.matches.length) return;
    this._pushUndo('検索一括置換');
    let replaced = 0;
    (Array.isArray(this.doc?.rows) ? this.doc.rows : []).forEach((row) => {
      if (!this._isRoleVisible(row.role || '', row.status || '')) return;
      let plain = _sn2StripRubyToPlain(row.text || '');
      let pos = plain.indexOf(state.query);
      let seekFrom = 0;
      while (pos >= 0) {
        row.text = _sn2ReplaceRawTextByVisibleRange(row.text || '', pos, pos + state.query.length, state.replace || '');
        replaced += 1;
        plain = _sn2StripRubyToPlain(row.text || '');
        seekFrom = pos + (state.replace || '').length;
        pos = plain.indexOf(state.query, seekFrom);
      }
    });
    this._render();
    this._markDirty({ skipUndo: true });
    this._refreshSearchState();
    this._updateSearchPopupUi?.();
    if (typeof showStatus === 'function') showStatus(`${replaced} 件を置換しました`);
  },

  _showSearchReplacePopup(anchorBtn = null) {
    if (!this.doc) return;
    this._closeSearchReplacePopup();
    if (!this._searchState) this._searchState = { query: '', replace: '', matches: [], index: -1 };
    const popup = document.createElement('div');
    popup.className = 'sn2-search-popup sn2-header-popup';
    popup.style.cssText = 'position:fixed;z-index:10000;min-width:320px;max-width:min(420px, calc(100vw - 24px));padding:10px;';
    popup.innerHTML = `
      <div style="display:grid;grid-template-columns:1fr auto auto;gap:6px;align-items:center;">
        <input type="text" class="sn2-search-input" placeholder="検索">
        <button type="button" class="sn2-header-popup-item" data-sn-search-prev>↑</button>
        <button type="button" class="sn2-header-popup-item" data-sn-search-next>↓</button>
      </div>
      <div style="display:grid;grid-template-columns:1fr auto auto;gap:6px;align-items:center;margin-top:6px;">
        <input type="text" class="sn2-replace-input" placeholder="置換">
        <button type="button" class="sn2-header-popup-item" data-sn-search-replace>置換</button>
        <button type="button" class="sn2-header-popup-item" data-sn-search-replace-all>全置換</button>
      </div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;">
        <span class="sn2-search-count" style="font-size:11px;color:var(--fg2);">0 / 0</span>
        <button type="button" class="sn2-header-popup-item" data-sn-search-close>閉じる</button>
      </div>`;
    const queryInput = popup.querySelector('.sn2-search-input');
    const replaceInput = popup.querySelector('.sn2-replace-input');
    const countEl = popup.querySelector('.sn2-search-count');
    const btnPrev = popup.querySelector('[data-sn-search-prev]');
    const btnNext = popup.querySelector('[data-sn-search-next]');
    const btnReplace = popup.querySelector('[data-sn-search-replace]');
    const btnReplaceAll = popup.querySelector('[data-sn-search-replace-all]');

    queryInput.value = this._searchState.query || '';
    replaceInput.value = this._searchState.replace || '';

    this._updateSearchPopupUi = () => {
      const state = this._searchState || { matches: [], index: -1 };
      const total = state.matches?.length || 0;
      const current = total ? state.index + 1 : 0;
      countEl.textContent = `${current} / ${total}`;
      const disabled = !total;
      btnPrev.disabled = disabled;
      btnNext.disabled = disabled;
      btnReplace.disabled = disabled;
      btnReplaceAll.disabled = disabled;
    };

    const syncState = (preferred = null, focusCurrent = true) => {
      this._searchState.query = queryInput.value;
      this._searchState.replace = replaceInput.value;
      this._refreshSearchState(preferred);
      this._updateSearchPopupUi();
      if (focusCurrent && this._searchState.matches.length) {
        this._activateSearchMatch(this._searchState.matches[this._searchState.index]);
      }
    };
    const commitQuery = (focusCurrent = true) => {
      const currentQuery = queryInput.value;
      if (this._searchState.query !== currentQuery || !Array.isArray(this._searchState.matches)) {
        syncState(null, focusCurrent);
        return true;
      }
      if (!this._searchState.matches.length) {
        syncState(null, focusCurrent);
        return true;
      }
      return false;
    };

    let queryComposing = false;
    queryInput.addEventListener('compositionstart', () => { queryComposing = true; });
    queryInput.addEventListener('compositionend', () => {
      queryComposing = false;
      syncState(null, true);
    });
    replaceInput.addEventListener('input', () => {
      this._searchState.replace = replaceInput.value;
    });
    queryInput.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') {
        if (queryComposing || ev.isComposing || ev.keyCode === 229) return;
        ev.preventDefault();
        if (!commitQuery(true)) this._jumpSearchMatch(ev.shiftKey ? -1 : 1);
      }
      if (ev.key === 'Escape') this._closeSearchReplacePopup();
    });
    replaceInput.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        commitQuery(false);
        this._replaceCurrentSearchMatch();
      }
      if (ev.key === 'Escape') this._closeSearchReplacePopup();
    });
    btnPrev.addEventListener('click', () => { if (!commitQuery(true)) this._jumpSearchMatch(-1); });
    btnNext.addEventListener('click', () => { if (!commitQuery(true)) this._jumpSearchMatch(1); });
    btnReplace.addEventListener('click', () => { commitQuery(false); this._replaceCurrentSearchMatch(); });
    btnReplaceAll.addEventListener('click', () => { commitQuery(false); this._replaceAllSearchMatches(); });
    popup.querySelector('[data-sn-search-close]').addEventListener('click', () => this._closeSearchReplacePopup());

    document.body.appendChild(popup);
    this._searchPopup = popup;
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorBtn,
        close: () => this._closeSearchReplacePopup(),
      });
    }
    if (anchorBtn) positionPopup(popup, anchorBtn.getBoundingClientRect());
    else {
      const hostRect = this.host?.getBoundingClientRect?.();
      const anchorRect = hostRect
        ? { left: hostRect.right, right: hostRect.right, top: hostRect.top, bottom: hostRect.top }
        : { left: window.innerWidth - 16, right: window.innerWidth - 16, top: 16, bottom: 16 };
      positionPopup(popup, anchorRect);
    }
    this._searchPopupKeyHandler = (ev) => {
      if (ev.key !== 'Escape' || !this._searchPopup?.isConnected) return;
      ev.preventDefault();
      ev.stopPropagation();
      this._closeSearchReplacePopup();
    };
    document.addEventListener('keydown', this._searchPopupKeyHandler, true);
    this._searchPopupCloseHandler = (ev) => {
      if (!popup.contains(ev.target) && ev.target !== anchorBtn) this._closeSearchReplacePopup();
    };
    setTimeout(() => {
      if (popup.isConnected) document.addEventListener('pointerdown', this._searchPopupCloseHandler, true);
    }, 0);
    syncState(null, !!queryInput.value);
    queryInput.focus();
    queryInput.select();
  },

});

;

/* === gb-scriptnote-clipstudio.js === */
;
/* ==============================
   gb-scriptnote-clipstudio.js: Clip Studio / SEP 連携

   gb-scriptnote-editor.js から WebSocket 接続とコピー送信まわりを分離。
   ============================== */

let _sn2SepWs = null;
let _sn2SepConnected = false;
let _sn2SepConnecting = false;
let _sn2SepRefCount = 0;
let _sn2SepReconnectTimer = null;
let _sn2SepToken = '';
let _sn2SepTokenPromise = null;

function _sn2SepAcquire() {
  _sn2SepRefCount++;
  if (_sn2SepRefCount === 1) _sn2SepConnect();
}

function _sn2SepRelease() {
  _sn2SepRefCount = Math.max(0, _sn2SepRefCount - 1);
  if (_sn2SepRefCount === 0) {
    if (_sn2SepReconnectTimer) { clearTimeout(_sn2SepReconnectTimer); _sn2SepReconnectTimer = null; }
    try { _sn2SepWs?.close(); } catch {}
    _sn2SepWs = null;
    _sn2SepConnected = false;
    _sn2SepConnecting = false;
  }
}

async function _sn2FetchSepToken() {
  if (_sn2SepToken) return _sn2SepToken;
  if (_sn2SepTokenPromise) return _sn2SepTokenPromise;
  _sn2SepTokenPromise = fetch((typeof API_BASE !== 'undefined' ? API_BASE : '') + '/sep-token', { cache: 'no-store' })
    .then(async res => {
      if (!res.ok) throw new Error('SEP token unavailable');
      const data = await res.json();
      const token = String(data?.token || '').trim();
      if (!token) throw new Error('SEP token missing');
      _sn2SepToken = token;
      return token;
    })
    .finally(() => { _sn2SepTokenPromise = null; });
  return _sn2SepTokenPromise;
}

function _sn2SepUrl(token) {
  const wsPort = new URLSearchParams(location.search).get('port') || location.port || '8001';
  const host = location.hostname || 'localhost';
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  return protocol + '//' + host + ':' + wsPort + '/ws/sep?token=' + encodeURIComponent(token);
}

function _sn2SepConnect() {
  if (_sn2SepWs && (_sn2SepWs.readyState === WebSocket.OPEN || _sn2SepWs.readyState === WebSocket.CONNECTING)) return;
  if (_sn2SepRefCount === 0) return;
  if (_sn2SepConnecting) return;
  _sn2SepConnecting = true;
  try {
    _sn2FetchSepToken().then(token => {
      if (_sn2SepRefCount === 0) { _sn2SepConnecting = false; return; }
      _sn2SepWs = new WebSocket(_sn2SepUrl(token));
      _sn2SepWs.onopen = () => { _sn2SepConnected = true; _sn2SepConnecting = false; };
      _sn2SepWs.onclose = () => {
        _sn2SepConnected = false;
        _sn2SepConnecting = false;
        if (_sn2SepRefCount > 0) {
          if (_sn2SepReconnectTimer) clearTimeout(_sn2SepReconnectTimer);
          _sn2SepReconnectTimer = setTimeout(() => { _sn2SepReconnectTimer = null; _sn2SepConnect(); }, 3000);
        }
      };
      _sn2SepWs.onerror = () => { _sn2SepConnected = false; _sn2SepConnecting = false; };
      _sn2SepWs.onmessage = (e) => {
        try {
          const msg = JSON.parse(e.data);
          const w = document.getElementById('sb-warn') || document.getElementById('sb-msg');
          const colorMap = { countdown: 'var(--orange)', progress: 'var(--accent2)', done: 'var(--green)', status: 'var(--fg2)', error: 'var(--red)' };
          if (w) {
            if (msg.type === 'countdown') w.textContent = `CLIP STUDIO PAINTへ送信: ${msg.seconds}秒後にペースト開始...`;
            else w.textContent = msg.message || '';
            if (w.id === 'sb-warn') w.style.display = w.textContent ? '' : 'none';
            w.style.color = colorMap[msg.type] || '';
            // 接続済み/進行中/完了などの通常状態は失敗ではないため、
            // 「エラー: 」表示（#sb-warn[data-status-kind="error"] / #sb-msg[data-status-kind="error"]、
            // gb-accessibility.css）を誤って出さないよう、実際の失敗時のみ error 扱いにする。
            if (msg.type === 'error') {
              w.dataset.statusKind = 'error';
              if (w.id === 'sb-msg') w.setAttribute('aria-label', 'エラー: ' + w.textContent);
            } else {
              delete w.dataset.statusKind;
              if (w.id === 'sb-msg') w.removeAttribute('aria-label');
            }
            if (msg.type === 'done') setTimeout(() => {
              w.textContent = '';
              w.style.color = '';
              delete w.dataset.statusKind;
              if (w.id === 'sb-msg') w.removeAttribute('aria-label');
              if (w.id === 'sb-warn') w.style.display = 'none';
            }, 3000);
          }
          _sn2UpdateRunningDialog(msg);
        } catch {}
      };
    }).catch(() => {
      _sn2SepConnected = false;
      _sn2SepConnecting = false;
    });
  } catch { _sn2SepConnected = false; _sn2SepConnecting = false; }
}

function _sn2GetActiveEditor() {
  if (typeof GBLayout !== 'undefined' && typeof getComponentInstance === 'function') {
    const paneId = GBLayout.activePane;
    if (paneId) {
      const pane = GBLayout.findNode(GBLayout.root, paneId);
      if (pane?.node) {
        const tab = pane.node.tabs?.[pane.node.activeTabIndex];
        if (tab) {
          const comp = getComponentInstance(tab.id);
          if (comp?._editor?.doc) return comp._editor;
        }
      }
    }
  }
  return null;
}

const _sn2Editors = {};

function _sn2EditorByScope(scope) {
  if (scope) {
    if (!scope.startsWith('scriptnote:')) return _sn2GetActiveEditor();
    const key = scope.slice('scriptnote:'.length);
    if (key && _sn2Editors[key]?.doc) return _sn2Editors[key];
    if (key) {
      const byScopeId = Object.values(_sn2Editors)
        .find(editor => editor?.doc && editor._historyScopeId === key);
      if (byScopeId) return byScopeId;
    }
    return null;
  }
  return _sn2GetActiveEditor();
}

function _captureScriptnoteState(scope) {
  const editor = _sn2EditorByScope(scope);
  if (!editor?.doc) return null;
  editor._syncAllFromDom();
  return editor._takeSnapshot();
}

function _restoreScriptnoteState(snapshot, scope) {
  if (!snapshot) return;
  const editor = _sn2EditorByScope(scope);
  if (!editor?.doc) return;
  editor._applySnapshot(snapshot);
}

async function _sn2ConfirmIncludeAffix() {
  return await cfConfirm('テキストの前後設定（「」（）等）を含めますか？');
}

function _sn2RowsForClipStudio(editor) {
  const rows = Array.isArray(editor?.doc?.rows) ? editor.doc.rows : [];
  let selectedIds = null;
  if (typeof editor?._getVisibleSelectedIds === 'function') {
    selectedIds = editor._getVisibleSelectedIds();
  } else if (editor?._rowSelection instanceof Set) {
    selectedIds = editor._rowSelection;
  }
  if (selectedIds?.size) {
    const selectedRows = rows.filter(row => selectedIds.has(row.id));
    if (selectedRows.length) return selectedRows;
  }
  return rows;
}

function sn2CopyForClipStudio() {
  const editor = _sn2GetActiveEditor();
  if (!editor?.doc) {
    if (typeof showStatus === 'function') showStatus('シナリオが開かれていません', true);
    return;
  }
  if (typeof editor._syncAllFromDom === 'function') editor._syncAllFromDom();

  _sn2SepConnect();

  if (_sn2SepConnected && _sn2SepWs && _sn2SepWs.readyState === WebSocket.OPEN) {
    _sn2ShowSepDialog(editor);
    return;
  }

  _sn2ConfirmIncludeAffix().then((includeAffixCb) => {
    const doc = editor.doc;
    const calc = editor._calcPagePanel();
    const rows = _sn2RowsForClipStudio(editor);
    let out = '';
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      const rowIndex = doc.rows.indexOf(r);
      const nextIndex = i < rows.length - 1 ? doc.rows.indexOf(rows[i + 1]) : -1;
      const effectiveRole = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(doc, r);
      const charaR = effectiveRole?.type || effectiveRole?.style
        || (r.role ? doc.characters?.find(c => !c.isDefault && c.name === r.role) : null);
      if (charaR?.isBreak || charaR?.kind === 'break') { out += '←\r\n'; continue; }
      let plainText = _sn2StripRubyToPlain(r.text || '');
      if (includeAffixCb && plainText) {
        const affix = _sn2GetTextAffix(editor, r);
        plainText = (affix.before || '') + plainText + (affix.after || '');
      }
      if (plainText) out += plainText + '\r\n';
      if (nextIndex >= 0 && calc[rowIndex] && calc[nextIndex] && calc[nextIndex].page !== calc[rowIndex].page) {
        out += '\r\n';
      }
    }
    const onCopied = () => {
      if (typeof showStatus === 'function') showStatus('CLIP STUDIO PAINT用テキストをコピーしました');
    };
    const fallbackCopy = () => {
      const ta = document.createElement('textarea');
      ta.className = 'sn2-clipstudio-copy-buffer';
      ta.setAttribute('aria-hidden', 'true');
      ta.tabIndex = -1;
      ta.readOnly = true;
      ta.value = out;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch {}
      ta.remove();
      onCopied();
    };
    const clipboard = (typeof navigator !== 'undefined') ? navigator.clipboard : null;
    if (clipboard?.writeText) clipboard.writeText(out).then(onCopied).catch(fallbackCopy);
    else fallbackCopy();
  });
}

function _sn2ShowSepDialog(editor) {
  const doc = editor.doc;
  const selectedRows = _sn2RowsForClipStudio(editor);
  const hasSelection = selectedRows.length > 0 && selectedRows.length < doc.rows.length;
  const allChecked = hasSelection ? '' : ' checked';
  const selectedOption = hasSelection
    ? `<label class="sn2-sep-choice"><input type="radio" name="sn2-sep-range" value="selected" checked> 選択範囲（${selectedRows.length}行）</label>`
    : '';
  const o = document.createElement('div');
  o.className = 'modal-overlay';
  o.dataset.sn2Dialog = 'clipstudio-send';
  o.innerHTML = `<div class="modal sn2-sep-modal" role="dialog" aria-modal="true" aria-labelledby="sn2-sep-title"><h3 id="sn2-sep-title">CLIP STUDIO PAINTへ送信 ${fieldHelp('「送信」を押した後、カウントダウン中にCLIP STUDIO PAINTのストーリーエディタをクリックしてください')}</h3>
    <div class="field"><label>送信範囲</label><div class="sn2-sep-range-row">
      <label class="sn2-sep-choice"><input type="radio" name="sn2-sep-range" value="all"${allChecked}> 全行（${doc.rows.length}行）</label>${selectedOption}</div></div>
    <div class="field"><label class="sn2-sep-choice"><input type="checkbox" id="sn2-sep-include-affix"> テキストの前後設定（「」（）等）を含める</label></div>
    <div class="field"><label class="sn2-sep-choice"><input type="checkbox" id="sn2-sep-include-summary"> プロット行も出力する</label></div>
    <div class="field"><label class="sn2-sep-choice"><input type="checkbox" id="sn2-sep-include-break-text"> 区切り行のテキストも出力する</label></div>
    <div class="field"><label class="sn2-sep-choice"><input type="checkbox" id="sn2-sep-skip-blank"> 空白行を出力しない</label></div>
    <div id="sn2-sep-countdown-slot"></div>
    <div id="sn2-sep-break-wait-slot"></div>
    <div id="sn2-sep-status" class="sn2-sep-status"></div>
    <div class="btn-row"><button type="button" class="cancel-btn" data-sn2-role="cancel">キャンセル</button>
    <button type="button" class="sn2-sep-stop-btn" data-sn2-role="stop">中断</button>
    <button type="button" class="primary ok-btn" data-sn2-role="send">送信</button></div></div>`;
  document.body.appendChild(o);
  const slot = o.querySelector('#sn2-sep-countdown-slot');
  if (slot && window.GBUI && typeof window.GBUI.buildNumInput === 'function') {
    const control = window.GBUI.buildNumInput({
      label: 'カウントダウン',
      value: 5,
      unit: '秒',
      min: 1,
      max: 60,
      attrs: { id: 'sn2-sep-countdown' }
    });
    control?.classList?.add('sn2-sep-field');
    slot.replaceWith(control);
  } else if (slot) {
    slot.outerHTML = '<div class="field sn2-sep-field"><label for="sn2-sep-countdown">カウントダウン（秒）</label><input id="sn2-sep-countdown" class="sn2-sep-number" type="number" min="1" max="60" value="5"></div>';
  }
  const breakWaitSlot = o.querySelector('#sn2-sep-break-wait-slot');
  if (breakWaitSlot && window.GBUI && typeof window.GBUI.buildNumInput === 'function') {
    const control = window.GBUI.buildNumInput({
      label: 'ページ送り後の待機',
      value: 1.0,
      unit: '秒',
      min: 0,
      max: 10,
      step: 0.1,
      attrs: { id: 'sn2-sep-break-wait' }
    });
    control?.classList?.add('sn2-sep-field');
    breakWaitSlot.replaceWith(control);
  } else if (breakWaitSlot) {
    breakWaitSlot.outerHTML = '<div class="field sn2-sep-field"><label for="sn2-sep-break-wait">ページ送り後の待機（秒）</label><input id="sn2-sep-break-wait" class="sn2-sep-number" type="number" min="0" max="10" step="0.1" value="1.0"></div>';
  }
  o._sn2Editor = editor;
  o.querySelector('[data-sn2-role="cancel"]')?.addEventListener('click', () => { o.remove(); });
  o.querySelector('[data-sn2-role="stop"]')?.addEventListener('click', () => { _sn2StopSep(); });
  o.querySelector('[data-sn2-role="send"]')?.addEventListener('click', () => { _sn2StartSep(); });
  window.GBModalShell?.enhanceOverlay?.(o);
}

function _sn2GetTextAffix(editor, roleOrRow) {
  const role = typeof roleOrRow === 'object' ? String(roleOrRow?.role || '') : String(roleOrRow || '');
  const chara = globalThis.GBScriptNoteRoleModel?.getEffectiveStyle?.(editor.doc, roleOrRow)
    || (role
      ? editor.doc.characters?.find(c => !c.isDefault && c.name === role)
      : editor.doc.characters?.find(c => c.isDefault));
  const ts = chara?.textStyle || {};
  const before = ts.textBefore ?? chara?.textBefore ?? '';
  const after = ts.textAfter ?? chara?.textAfter ?? '';
  return { before, after };
}

function _sn2StartSep() {
  const overlay = document.querySelector('.modal-overlay[data-sn2-dialog="clipstudio-send"]') || document.querySelector('.modal-overlay');
  const editor = overlay?._sn2Editor || _sn2GetActiveEditor();
  if (!editor?.doc) return;
  if (typeof editor._syncAllFromDom === 'function') editor._syncAllFromDom();
  const countdown = parseInt(document.getElementById('sn2-sep-countdown')?.value) || 5;
  const breakWaitRaw = parseFloat(document.getElementById('sn2-sep-break-wait')?.value);
  const breakWait = Number.isFinite(breakWaitRaw) ? Math.max(0, Math.min(10, Math.round(breakWaitRaw * 10) / 10)) : 1.0;
  const includeAffix = !!document.getElementById('sn2-sep-include-affix')?.checked;
  const includeSummary = !!document.getElementById('sn2-sep-include-summary')?.checked;
  const includeBreakText = !!document.getElementById('sn2-sep-include-break-text')?.checked;
  const skipBlank = !!document.getElementById('sn2-sep-skip-blank')?.checked;
  const doc = editor.doc;
  const range = document.querySelector('input[name="sn2-sep-range"]:checked')?.value || 'all';
  const sourceRows = range === 'selected' ? _sn2RowsForClipStudio(editor) : doc.rows;
  // 「見開き」ONの区切り行が連続したとき、偶数回目はページ送りをスルーしてコマ送り扱いにする。
  // 連続は「区切り行だけを抽出した並び」で数え、他の行を挟んでも継続する。
  // 見開きOFFの区切り行が現れたら連続カウントをリセット。
  let spreadRun = 0;
  const rows = [];
  for (const r of sourceRows) {
    const role = r.role || '';
    const effectiveRole = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(doc, r);
    const roleType = effectiveRole?.type || effectiveRole?.style || null;
    const isBreak = !!role && !!(roleType?.isBreak || roleType?.kind === 'break');
    const isSummary = !!role && !!(roleType?.isSummary || roleType?.kind === 'summary');
    const isSpread = !!role && !!roleType?.isSpread;
    if (isSummary && !includeSummary) continue;
    let plainText = _sn2StripRubyToPlain(r.text || '');
    if (includeAffix && plainText) {
      const affix = _sn2GetTextAffix(editor, r);
      plainText = (affix.before || '') + plainText + (affix.after || '');
    }
    // 「空白行を出力しない」: 区切り/プロットではなく、キャラ名も本文も空の行を除外
    if (skipBlank && !isBreak && !isSummary && !role && !plainText) continue;
    let kind = 'normal';
    if (isBreak) {
      if (isSpread) {
        spreadRun++;
        // 連続2,4,6…回目（偶数回目）はページ送りをスルーしてコマ送りへ。
        // 「区切り行のテキストも出力する」ON かつ本文ありならテキストも出力する
        if (spreadRun % 2 === 0) {
          const breakText = (includeBreakText && plainText) ? plainText : '';
          rows.push({ kind: 'normal', character: '', text: breakText });
          continue;
        }
      } else {
        spreadRun = 0;
      }
      kind = 'pageBreak';
    } else if (isSummary) {
      kind = 'summary';
    }
    // 区切り行のテキストは「区切り行のテキストも出力する」ON のときだけ送信
    const outText = isBreak ? (includeBreakText ? plainText : '') : plainText;
    rows.push({
      kind,
      character: isBreak ? '' : role,
      text: outText,
    });
  }
  // 全ページ出力（range==='all'）のとき、先頭ページの区切り行ではページ送りしない
  if (range === 'all') {
    if (rows[0]?.kind === 'pageBreak') {
      const first = rows[0];
      if (includeBreakText && first.text) {
        // テキストがあれば通常行扱いで先頭ページ先頭にペースト
        first.kind = 'normal';
        first.character = '';
      } else {
        // テキストがない or オプションOFF → 先頭の区切り行ごと除去
        rows.shift();
      }
    }
  }
  if (!_sn2SepWs || _sn2SepWs.readyState !== WebSocket.OPEN) {
    if (typeof showStatus === 'function') showStatus('CLIP STUDIO PAINT連携が切断されています。再接続してから送信してください', true);
    _sn2SepConnect();
    return;
  }
  try {
    _sn2SepWs.send(JSON.stringify({ command: 'paste', rows, countdown, breakWait }));
    _sn2EnterRunningMode(overlay);
  } catch {
    if (typeof showStatus === 'function') showStatus('CLIP STUDIO PAINT連携への送信に失敗しました', true);
  }
}

// 送信中は元のダイアログを閉じ、画面全体を覆う警告オーバーレイに切り替える
function _sn2EnterRunningMode(dialogOverlay) {
  try { dialogOverlay?.remove(); } catch {}
  // 既に警告オーバーレイが出ていれば再利用
  let ov = document.getElementById('sn2-sep-running-overlay');
  if (ov) return ov;
  ov = document.createElement('div');
  ov.id = 'sn2-sep-running-overlay';
  ov.className = 'sn2-sep-running-overlay';
  ov.setAttribute('role', 'dialog');
  ov.setAttribute('aria-modal', 'true');
  ov.setAttribute('aria-labelledby', 'sn2-sep-running-title');
  const box = document.createElement('div');
  box.className = 'sn2-sep-running-box';
  const title = document.createElement('div');
  title.id = 'sn2-sep-running-title';
  title.className = 'sn2-sep-running-title';
  title.textContent = 'CLIP STUDIO PAINTへ送信中';
  box.appendChild(title);
  const warn = document.createElement('div');
  warn.className = 'sn2-sep-running-warning';
  warn.textContent = 'ペーストが完了するまで、マウス・キーボード・他ウィンドウ等、一切の操作をしないでください。';
  box.appendChild(warn);
  const status = document.createElement('div');
  status.id = 'sn2-sep-running-status';
  status.className = 'sn2-sep-running-status';
  status.textContent = '送信準備中...';
  box.appendChild(status);
  const btnRow = document.createElement('div');
  btnRow.className = 'sn2-sep-running-actions';
  const stopBtn = document.createElement('button');
  stopBtn.type = 'button';
  stopBtn.className = 'sn2-sep-running-stop';
  stopBtn.textContent = '中断';
  stopBtn.addEventListener('click', () => { _sn2StopSep(); });
  btnRow.appendChild(stopBtn);
  box.appendChild(btnRow);
  ov.appendChild(box);
  document.body.appendChild(ov);
  return ov;
}

function _sn2UpdateRunningDialog(msg) {
  const ov = document.getElementById('sn2-sep-running-overlay');
  if (!ov) return;
  const statusEl = ov.querySelector('#sn2-sep-running-status');
  if (statusEl && msg) {
    if (msg.type === 'countdown') statusEl.textContent = `${msg.seconds}秒後にペースト開始...`;
    else if (msg.type === 'progress') statusEl.textContent = msg.message || `ペースト中... ${msg.current}/${msg.total}`;
    else if (msg.type === 'status') statusEl.textContent = msg.message || '';
    else if (msg.type === 'done') statusEl.textContent = msg.message || 'ペースト完了';
    else if (msg.type === 'error') statusEl.textContent = `エラー: ${msg.message || ''}`;
  }
  const isAborted = msg && msg.type === 'status' && typeof msg.message === 'string' && /中断されました/.test(msg.message);
  if (msg && (msg.type === 'done' || msg.type === 'error' || isAborted)) {
    setTimeout(() => { ov.remove(); }, 1500);
  }
}

function _sn2StopSep() {
  if (_sn2SepWs && _sn2SepWs.readyState === WebSocket.OPEN) {
    _sn2SepWs.send(JSON.stringify({ command: 'stop' }));
  }
  const running = document.getElementById('sn2-sep-running-overlay');
  if (running) {
    const statusEl = running.querySelector('#sn2-sep-running-status');
    if (statusEl) statusEl.textContent = '中断要求を送信しました...';
    return;
  }
  // 送信前のキャンセル: 送信ダイアログを閉じる
  document.querySelector('.modal-overlay[data-sn2-dialog="clipstudio-send"]')?.remove();
}

;

/* === gb-scriptnote-bmanga.js === */
;
/* B-MANGA scenario export: contract building, confirmation dialog, local relay. */
(function () {
  'use strict';

  const CONTRACT = 'meldex-bmanga-scenario';
  const VERSION = 1;
  const VERSION_V2 = 2;
  const DEFAULT_PORT = 47817;
  const RUBY_PRIORITY = Object.freeze({
    manual: 400,
    'shared-link-dictionary': 300,
    'document-rule': 200,
    'local-auto-dictionary': 100,
  });
  const DEFAULT_RUBY_PRESENTATION = Object.freeze({
    writingMode: 'horizontal',
    sizePercent: 50,
    gapEm: 0,
    letterSpacingEm: 0,
    lineHeight: 1.8,
    align: 'center',
    smallKana: 'keep',
    fontPreset: 'inherit',
    defaultStyle: 'group',
  });

  function isAvailable() {
    const host = String(location.hostname || '').toLowerCase();
    const localHost = host === '127.0.0.1' || host === 'localhost';
    return localHost && document.body?.dataset?.cloudMode !== 'dropbox';
  }

  function _visibleLength(value) { return Array.from(String(value || '')).length; }

  function _segments(raw) {
    if (typeof _sn2CollectVisibleSegments === 'function') return _sn2CollectVisibleSegments(String(raw || ''));
    return [{ type: 'plain', raw: String(raw || '') }];
  }

  function _plain(raw) {
    if (typeof _sn2UnescapeScriptNotePlainText === 'function') return _sn2UnescapeScriptNotePlainText(raw);
    return String(raw || '').replace(/\\([\\{|}\[\]])/g, '$1');
  }

  function _manualLinkLabelRaw(raw) {
    const match = String(raw || '').match(/^\[((?:\\.|[^\]])+)\]\(ml:/);
    return match ? match[1] : '';
  }

  function _rubyStyle(value, fallback = 'group') {
    const safeFallback = ['group', 'mono', 'jukugo'].includes(fallback) ? fallback : 'group';
    return ['group', 'mono', 'jukugo'].includes(value) ? value : safeFallback;
  }

  function _logicalFontPreset(value) {
    const preset = String(value || '').trim();
    if (!preset || preset.includes('/') || preset.includes('\\') || /^[A-Za-z]:/.test(preset)) return 'inherit';
    return preset.slice(0, 128);
  }

  function _finiteNumber(value, fallback, minimum = null) {
    const number = Number(value);
    if (!Number.isFinite(number) || (minimum != null && number < minimum)) return fallback;
    return number;
  }

  function _legacyTransferGapEm(stored, fallbackWritingMode = 'horizontal') {
    const compatibility = (stored?.compatibility && typeof stored.compatibility === 'object')
      ? stored.compatibility : {};
    if (compatibility.useLegacyGap !== true) {
      return _finiteNumber(stored?.gapEm, DEFAULT_RUBY_PRESENTATION.gapEm);
    }
    const explicit = Number(compatibility.legacyGapEm);
    if (compatibility.legacyGapEm !== undefined && compatibility.legacyGapEm !== null
      && String(compatibility.legacyGapEm).trim() !== '' && Number.isFinite(explicit)) {
      return Math.max(-2, Math.min(4, explicit));
    }
    const baseEm = _finiteNumber(compatibility.legacyBaseEmPx, 14, 0.001);
    const writingMode = ['horizontal', 'vertical'].includes(stored?.writingMode)
      ? stored.writingMode : fallbackWritingMode;
    const defaultCrossSize = writingMode === 'vertical' ? 18 : 14;
    const crossSize = _finiteNumber(compatibility.legacyCrossSizePx, defaultCrossSize, 0.001);
    const offset = _finiteNumber(compatibility.legacyOffsetPx, 3.5);
    return Math.max(-2, Math.min(4, ((crossSize - baseEm) * 0.5 - offset) / baseEm));
  }

  function normalizeRubyPresentation(doc) {
    const stored = (doc?.rubyPresentation && typeof doc.rubyPresentation === 'object')
      ? doc.rubyPresentation
      : ((doc?.editor?.rubyPresentation && typeof doc.editor.rubyPresentation === 'object')
        ? doc.editor.rubyPresentation
        : {});
    const viewMode = doc?.editor?.viewMode === 'vertical' ? 'vertical' : 'horizontal';
    const sharedModel = window.MeldexRubyPresentation;
    if (typeof sharedModel?.normalize === 'function') {
      const fallback = { ...sharedModel.DEFAULTS, writingMode: viewMode };
      const normalized = typeof sharedModel.toTransferPresentation === 'function'
        ? sharedModel.toTransferPresentation(stored, fallback)
        : sharedModel.normalize(stored, fallback);
      return {
        writingMode: normalized.writingMode,
        sizePercent: normalized.sizePercent,
        gapEm: normalized.gapEm,
        letterSpacingEm: normalized.letterSpacingEm,
        lineHeight: normalized.lineHeight,
        align: normalized.align,
        smallKana: normalized.smallKana,
        fontPreset: _logicalFontPreset(normalized.fontPreset),
        defaultStyle: _rubyStyle(normalized.defaultStyle),
      };
    }
    return {
      writingMode: ['horizontal', 'vertical'].includes(stored.writingMode) ? stored.writingMode : viewMode,
      sizePercent: stored?.compatibility?.useLegacySize === true
        ? _finiteNumber(stored.compatibility.legacySizeEm, 0.55, 0.05) * 100
        : _finiteNumber(stored.sizePercent, DEFAULT_RUBY_PRESENTATION.sizePercent, 5),
      gapEm: _legacyTransferGapEm(stored, viewMode),
      letterSpacingEm: _finiteNumber(stored.letterSpacingEm, DEFAULT_RUBY_PRESENTATION.letterSpacingEm),
      lineHeight: _finiteNumber(stored.lineHeight, DEFAULT_RUBY_PRESENTATION.lineHeight, 0.1),
      align: ['center', 'start'].includes(stored.align) ? stored.align : DEFAULT_RUBY_PRESENTATION.align,
      smallKana: ['keep', 'fullsize'].includes(stored.smallKana) ? stored.smallKana : DEFAULT_RUBY_PRESENTATION.smallKana,
      fontPreset: _logicalFontPreset(stored.fontPreset),
      defaultStyle: _rubyStyle(stored.defaultStyle, DEFAULT_RUBY_PRESENTATION.defaultStyle),
    };
  }

  function _normalizedRubyRule(rule, index, origin, defaultStyle = 'group') {
    const text = String(rule?.text || '');
    const rubyText = String(rule?.rubyText ?? rule?.ruby ?? '');
    if (!text || !rubyText) return null;
    const normalized = {
      text,
      chars: Array.from(text),
      rubyText,
      style: _rubyStyle(rule?.style, defaultStyle),
      origin,
      priority: RUBY_PRIORITY[origin],
      index,
    };
    if (Array.isArray(rule?.segments)) normalized.segments = rule.segments.map(item => ({ ...item }));
    return normalized;
  }

  function _applyRubyRuleSource(body, rules, used, found, origin, defaultStyle = 'group') {
    const chars = Array.from(body);
    const normalized = (Array.isArray(rules) ? rules : [])
      .map((rule, index) => _normalizedRubyRule(rule, index, origin, defaultStyle))
      .filter(Boolean);
    for (let pos = 0; pos < chars.length; pos++) {
      const candidates = normalized
        .filter(rule => rule.chars.every((ch, offset) => chars[pos + offset] === ch))
        .sort((a, b) => b.chars.length - a.chars.length || a.index - b.index);
      const match = candidates.find(rule => rule.chars.every((_ch, offset) => !used[pos + offset]));
      if (!match) continue;
      match.chars.forEach((_ch, offset) => { used[pos + offset] = true; });
      const span = {
        start: pos,
        length: match.chars.length,
        rubyText: match.rubyText,
        style: match.style,
        origin: match.origin,
        priority: match.priority,
      };
      if (match.segments) span.segments = match.segments;
      found.push(span);
      pos += match.chars.length - 1;
    }
  }

  function resolveRubySpans(raw, sources = {}) {
    let body = '';
    const rubies = [];
    const protectedRanges = [];
    const defaultStyle = _rubyStyle(sources.defaultStyle);
    _segments(raw).forEach(segment => {
      const start = _visibleLength(body);
      if (segment.type === 'ruby') {
        const base = String(segment.plain || '');
        const rubyText = String(segment.ruby || '');
        body += base;
        const span = {
          start,
          length: _visibleLength(base),
          rubyText,
          style: _rubyStyle(segment.style, defaultStyle),
          origin: 'manual',
          priority: RUBY_PRIORITY.manual,
        };
        if (Array.isArray(segment.segments)) span.segments = segment.segments.map(item => ({ ...item }));
        if (span.length && rubyText) rubies.push(span);
      } else if (segment.type === 'manual-link') {
        const labelRaw = _manualLinkLabelRaw(segment.raw);
        const nested = labelRaw
          ? resolveRubySpans(labelRaw, { defaultStyle })
          : { body: String(segment.plain || ''), rubies: [] };
        body += nested.body;
        nested.rubies.forEach(item => rubies.push({ ...item, start: start + item.start }));
        protectedRanges.push({ start, length: _visibleLength(nested.body) });
      } else {
        body += _plain(segment.raw);
      }
    });
    const used = new Array(_visibleLength(body)).fill(false);
    rubies.concat(protectedRanges).forEach(item => {
      for (let i = item.start; i < item.start + item.length; i++) used[i] = true;
    });
    _applyRubyRuleSource(body, sources.sharedLinkEntries, used, rubies, 'shared-link-dictionary', defaultStyle);
    _applyRubyRuleSource(body, sources.documentRules, used, rubies, 'document-rule', defaultStyle);
    _applyRubyRuleSource(body, sources.localDictionary, used, rubies, 'local-auto-dictionary', defaultStyle);
    rubies.sort((a, b) => a.start - b.start || b.priority - a.priority || b.length - a.length);
    return { body, rubies };
  }

  function resolveVisibleBody(raw, rubyRules) {
    let body = '';
    const rubies = [];
    const protectedRanges = [];
    _segments(raw).forEach(segment => {
      const start = _visibleLength(body);
      if (segment.type === 'ruby') {
        const base = String(segment.plain || '');
        body += base;
        rubies.push({ start, length: _visibleLength(base), rubyText: String(segment.ruby || ''), style: 'group' });
      } else if (segment.type === 'manual-link') {
        const labelRaw = _manualLinkLabelRaw(segment.raw);
        const nested = labelRaw ? resolveVisibleBody(labelRaw, []) : { body: String(segment.plain || ''), rubies: [] };
        const label = nested.body;
        body += label;
        nested.rubies.forEach(item => rubies.push({ ...item, start: start + item.start }));
        protectedRanges.push({ start, length: _visibleLength(label) });
      } else {
        body += _plain(segment.raw);
      }
    });
    _automaticRubies(body, rubyRules, rubies.concat(protectedRanges)).forEach(item => rubies.push(item));
    rubies.sort((a, b) => a.start - b.start || b.length - a.length || a.style.localeCompare(b.style));
    return { body, rubies };
  }

  function _automaticRubies(body, rubyRules, occupied) {
    const chars = Array.from(body);
    const used = new Array(chars.length).fill(false);
    occupied.forEach(item => {
      for (let i = item.start; i < item.start + item.length; i++) used[i] = true;
    });
    const rules = (Array.isArray(rubyRules) ? rubyRules : [])
      .filter(rule => rule && String(rule.text || '') && String(rule.ruby || ''))
      .map((rule, index) => ({ text: String(rule.text), ruby: String(rule.ruby), index, chars: Array.from(String(rule.text)) }));
    const found = [];
    for (let pos = 0; pos < chars.length; pos++) {
      const candidates = rules.filter(rule => rule.chars.every((ch, offset) => chars[pos + offset] === ch));
      candidates.sort((a, b) => b.chars.length - a.chars.length || a.index - b.index);
      const match = candidates.find(rule => rule.chars.every((_ch, offset) => !used[pos + offset]));
      if (!match) continue;
      match.chars.forEach((_ch, offset) => { used[pos + offset] = true; });
      found.push({ start: pos, length: match.chars.length, rubyText: match.ruby, style: 'group' });
      pos += match.chars.length - 1;
    }
    return found;
  }

  // クリスタ送信（gb-scriptnote-clipstudio.js の _sn2GetTextAffix）と同じ解決規則。
  // editor ではなく doc のみから引けるようにした純粋関数版。
  function _getTextAffix(doc, roleOrRow) {
    const role = typeof roleOrRow === 'object' ? String(roleOrRow?.role || '') : String(roleOrRow || '');
    const chara = globalThis.GBScriptNoteRoleModel?.getEffectiveStyle?.(doc, roleOrRow)
      || (role
        ? (doc?.characters || []).find(c => c && !c.isDefault && c.name === role)
        : (doc?.characters || []).find(c => c && c.isDefault));
    const ts = chara?.textStyle || {};
    const before = ts.textBefore ?? chara?.textBefore ?? '';
    const after = ts.textAfter ?? chara?.textAfter ?? '';
    return { before: String(before || ''), after: String(after || '') };
  }

  function _getEffectiveRoleType(doc, row) {
    const effective = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(doc, row);
    if (effective) return effective.type || effective.style || null;
    const role = String(row?.role || '');
    return role
      ? (doc?.characters || []).find(item => item && !item.isDefault && item.name === role) || null
      : (doc?.characters || []).find(item => item && item.isDefault) || null;
  }

  function _sharedLinkEntries() {
    const entries = window.MeldexAutoLink?.getDict?.();
    return (Array.isArray(entries) ? entries : []).filter(item => item && String(item.ruby || ''));
  }

  function _supportsV2(capabilities) {
    return capabilities?.contract === CONTRACT
      && Array.isArray(capabilities?.versions)
      && capabilities.versions.includes(VERSION_V2)
      && capabilities?.features?.presentationRuby === true
      && capabilities?.features?.rubySpanOrigins === true
      && capabilities?.features?.rubySegments === true;
  }

  function _rowPresentation(row, doc) {
    const override = (row?.rubyPresentation && typeof row.rubyPresentation === 'object')
      ? row.rubyPresentation
      : ((row?.presentation?.ruby && typeof row.presentation.ruby === 'object') ? row.presentation.ruby : null);
    if (!override) return null;
    return normalizeRubyPresentation({
      rubyPresentation: { ...normalizeRubyPresentation(doc), ...override },
      editor: doc?.editor,
    });
  }

  // doc/documentId のみに依存する純粋関数。Node からの直接evalテストのため editor に依存しない。
  function buildPayload(doc, documentId, options) {
    const opts = Object.assign({
      selectedRowIds: null,
      includeAffix: false,
      includeSummary: false,
      includeBreakText: false,
      skipBlank: false,
      contractVersion: VERSION,
      sharedLinkEntries: null,
      localDictionary: null,
    }, options || {});
    const contractVersion = Number(opts.contractVersion) === VERSION_V2 ? VERSION_V2 : VERSION;
    const id = String(documentId || doc?.source?.documentId || '').trim();
    if (!id) throw new Error('先にシナリオを保存してください');
    const allRows = Array.isArray(doc?.rows) ? doc.rows : [];
    let sourceRows = allRows;
    if (Array.isArray(opts.selectedRowIds)) {
      const idSet = new Set(opts.selectedRowIds);
      sourceRows = allRows.filter(row => idSet.has(row?.id));
    }
    const pages = [{ pageIndex: 0, rows: [] }];
    sourceRows.forEach((row, index) => {
      const role = String(row?.role || '');
      const roleType = _getEffectiveRoleType(doc, row);
      const isBreak = !!role && !!(roleType?.isBreak || roleType?.kind === 'break');
      const isSummary = !!role && !!(roleType?.isSummary || roleType?.kind === 'summary');
      if (isSummary && !opts.includeSummary) return;
      if (isBreak && index > 0) pages.push({ pageIndex: pages.length, rows: [] });
      const resolved = contractVersion === VERSION_V2
        ? resolveRubySpans(String(row?.text || ''), {
          sharedLinkEntries: Array.isArray(opts.sharedLinkEntries) ? opts.sharedLinkEntries : _sharedLinkEntries(),
          documentRules: doc?.rubyRules,
          localDictionary: opts.localDictionary,
          defaultStyle: window.MeldexRubyPresentation?.ensureDocument?.(doc)?.defaultStyle
            || doc?.rubyPresentation?.defaultStyle,
        })
        : resolveVisibleBody(String(row?.text || ''), doc?.rubyRules);
      let body = resolved.body;
      let rubies = resolved.rubies;
      if (opts.includeAffix && body) {
        const affix = _getTextAffix(doc, row);
        const shift = _visibleLength(affix.before);
        if (shift) rubies = rubies.map(item => ({ ...item, start: item.start + shift }));
        body = affix.before + body + affix.after;
      }
      const rowId = String(row?.id || `row-${index}`);
      const rowPayload = { rowId, type: isBreak ? '' : role, body, rubies };
      const rowRubyPresentation = contractVersion === VERSION_V2 ? _rowPresentation(row, doc) : null;
      if (rowRubyPresentation) rowPayload.presentation = { ruby: rowRubyPresentation };
      if (isBreak) {
        // 区切り行は「区切り行のテキストも出力する」ONかつ本文ありのときだけ、新しいページの先頭に type:'' で出力する。
        if (opts.includeBreakText && body) {
          pages[pages.length - 1].rows.push(rowPayload);
        }
        return;
      }
      // 「空白行を出力しない」: 区切り/プロットではなく、役名も本文も空の行だけを除外する。
      if (opts.skipBlank && !isSummary && !role && !body) return;
      pages[pages.length - 1].rows.push(rowPayload);
    });
    const payload = {
      contract: CONTRACT,
      version: contractVersion,
      source: { documentId: id, title: String(doc?.title || '') },
      pages,
    };
    if (contractVersion === VERSION_V2) {
      payload.indexUnit = 'unicode-code-point';
      payload.normalization = 'none';
      payload.presentation = { ruby: normalizeRubyPresentation(doc) };
    }
    return payload;
  }

  function _activeEditor() {
    if (typeof _sn2GetActiveEditor === 'function') return _sn2GetActiveEditor();
    return window.getActiveScriptNoteComponent?.()?._editor || null;
  }

  function _documentId(editor) {
    return String(editor?._path || editor?.doc?.source?.documentId || window.state?.currentPagePath || '');
  }

  // クリスタ送信（_sn2RowsForClipStudio）と同じ方法で選択行を取得し、id配列を返す。
  // 「選択範囲」に意味のある部分選択（1行以上、全行未満）がなければ null を返す。
  function _selectedRowIds(editor) {
    const rows = Array.isArray(editor?.doc?.rows) ? editor.doc.rows : [];
    let selectedIds = null;
    if (typeof editor?._getVisibleSelectedIds === 'function') {
      selectedIds = editor._getVisibleSelectedIds();
    } else if (editor?._rowSelection instanceof Set) {
      selectedIds = editor._rowSelection;
    }
    if (!selectedIds?.size) return null;
    const ids = rows.filter(row => selectedIds.has(row.id)).map(row => row.id);
    if (!ids.length || ids.length >= rows.length) return null;
    return ids;
  }

  function _field(label, input) {
    const wrap = document.createElement('label');
    wrap.style.cssText = 'display:grid;grid-template-columns:150px 1fr;gap:10px;align-items:center;margin:10px 0;';
    const text = document.createElement('span');
    text.textContent = label;
    wrap.append(text, input);
    return wrap;
  }

  function _checkboxField(e2eId, text) {
    const field = document.createElement('div');
    field.className = 'field';
    const label = document.createElement('label');
    label.className = 'sn2-sep-choice';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.dataset.e2eId = e2eId;
    const span = document.createElement('span');
    span.textContent = text;
    label.append(input, span);
    field.appendChild(label);
    return { field, input };
  }

  function _openDialog(doc, documentId, selectedRowIds) {
    return new Promise(resolve => {
      const overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      overlay.dataset.sn2Dialog = 'bmanga-send';
      const modal = document.createElement('div');
      modal.className = 'modal';
      modal.setAttribute('role', 'dialog');
      modal.setAttribute('aria-modal', 'true');
      modal.setAttribute('aria-label', 'B-MANGAへ送信');
      modal.style.cssText = 'width:min(520px,calc(100vw - 32px));max-height:calc(100vh - 32px);overflow:auto;padding:20px;box-sizing:border-box;';
      const title = document.createElement('h2');
      title.textContent = 'B-MANGAへ送信';

      const totalCount = Array.isArray(doc?.rows) ? doc.rows.length : 0;
      const hasSelection = Array.isArray(selectedRowIds) && selectedRowIds.length > 0;
      const selectedCount = hasSelection ? selectedRowIds.length : 0;

      const rangeField = document.createElement('div');
      rangeField.className = 'field';
      const rangeLabel = document.createElement('label');
      rangeLabel.textContent = '送信範囲';
      const rangeRow = document.createElement('div');
      rangeRow.className = 'sn2-sep-range-row';

      const allChoice = document.createElement('label');
      allChoice.className = 'sn2-sep-choice';
      const allRadio = document.createElement('input');
      allRadio.type = 'radio'; allRadio.name = 'bmanga-send-range'; allRadio.value = 'all';
      allRadio.dataset.e2eId = 'bmanga-send-range-all';
      allRadio.checked = !hasSelection;
      const allLabelText = document.createElement('span');
      allLabelText.textContent = `全行（${totalCount}行）`;
      allChoice.append(allRadio, allLabelText);
      rangeRow.appendChild(allChoice);

      let selectedRadio = null;
      if (hasSelection) {
        const selectedChoice = document.createElement('label');
        selectedChoice.className = 'sn2-sep-choice';
        selectedRadio = document.createElement('input');
        selectedRadio.type = 'radio'; selectedRadio.name = 'bmanga-send-range'; selectedRadio.value = 'selected';
        selectedRadio.dataset.e2eId = 'bmanga-send-range-selected';
        selectedRadio.checked = true;
        const selectedLabelText = document.createElement('span');
        selectedLabelText.textContent = `選択範囲（${selectedCount}行）`;
        selectedChoice.append(selectedRadio, selectedLabelText);
        rangeRow.appendChild(selectedChoice);
      }
      rangeField.append(rangeLabel, rangeRow);

      const affix = _checkboxField('bmanga-send-include-affix', 'テキストの前後設定（「」（）等）を含める');
      const summaryField = _checkboxField('bmanga-send-include-summary', 'プロット行も出力する');
      const breakTextField = _checkboxField('bmanga-send-include-break-text', '区切り行のテキストも出力する');
      const skipBlankField = _checkboxField('bmanga-send-skip-blank', '空白行を出力しない');

      const countSummary = document.createElement('p');

      const currentOptions = () => ({
        selectedRowIds: (selectedRadio?.checked) ? selectedRowIds : null,
        includeAffix: affix.input.checked,
        includeSummary: summaryField.input.checked,
        includeBreakText: breakTextField.input.checked,
        skipBlank: skipBlankField.input.checked,
      });
      const refreshSummary = () => {
        let payload;
        try { payload = buildPayload(doc, documentId, currentOptions()); }
        catch { countSummary.textContent = ''; return; }
        const rowCount = payload.pages.reduce((total, page) => total + page.rows.length, 0);
        countSummary.textContent = `${payload.pages.length}ページ、本文${rowCount}件を送信します。`;
      };
      [allRadio, selectedRadio, affix.input, summaryField.input, breakTextField.input, skipBlankField.input]
        .filter(Boolean)
        .forEach(input => input.addEventListener('change', refreshSummary));
      refreshSummary();

      const port = document.createElement('input');
      port.type = 'number'; port.min = '1024'; port.max = '65535'; port.value = String(DEFAULT_PORT);
      port.dataset.e2eId = 'bmanga-send-port';
      const token = document.createElement('input');
      token.type = 'password'; token.autocomplete = 'off'; token.spellcheck = false;
      token.placeholder = 'B-MANGAに表示された接続トークン'; token.dataset.e2eId = 'bmanga-send-token';
      const buttons = document.createElement('div');
      buttons.style.cssText = 'display:flex;justify-content:flex-end;gap:8px;margin-top:18px;';
      const cancel = document.createElement('button'); cancel.type = 'button'; cancel.textContent = 'キャンセル';
      const send = document.createElement('button'); send.type = 'button'; send.textContent = '送信'; send.className = 'primary';
      send.dataset.e2eId = 'bmanga-send-confirm';
      const close = value => { token.value = ''; overlay.remove(); resolve(value); };
      cancel.addEventListener('click', () => close(null));
      send.addEventListener('click', () => {
        let payload;
        const options = currentOptions();
        try { payload = buildPayload(doc, documentId, options); }
        catch (error) { showStatus?.(error.message || String(error), true); return; }
        close({ port: Number(port.value), token: token.value, payload, options });
      });
      overlay.addEventListener('click', event => { if (event.target === overlay) close(null); });
      buttons.append(cancel, send);
      modal.append(
        title,
        rangeField,
        affix.field,
        summaryField.field,
        breakTextField.field,
        skipBlankField.field,
        countSummary,
        _field('B-MANGAのポート', port),
        _field('接続トークン', token),
        buttons,
      );
      overlay.appendChild(modal); document.body.appendChild(overlay);
      // 配置は .modal-overlay の flex 中央寄せに任せる（クリスタ送信ダイアログと同方式）。
      // positionPopup で手動配置すると中央寄せから外れ、縦に長いダイアログが画面外へはみ出す。
      window.GBModalShell?.enhanceOverlay?.(overlay);
      token.focus();
    });
  }

  async function sendActiveScenario() {
    if (!isAvailable()) return;
    const editor = _activeEditor();
    if (!editor?.doc) return showStatus?.('シナリオが開かれていません', true);
    editor._syncAllFromDom?.();
    const documentId = _documentId(editor);
    try { buildPayload(editor.doc, documentId, {}); }
    catch (error) { return showStatus?.(error.message || String(error), true); }
    const selectedRowIds = _selectedRowIds(editor);
    const result = await _openDialog(editor.doc, documentId, selectedRowIds);
    if (!result) return;
    showLoading?.('B-MANGAへ送信しています...');
    try {
      let sendVersion = VERSION;
      try {
        const capabilityResponse = await fetch('/api/bmanga/scenario/capabilities', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ port: result.port, token: result.token }),
        });
        const capabilities = await capabilityResponse.json().catch(() => ({}));
        if (capabilityResponse.ok && _supportsV2(capabilities)) sendVersion = VERSION_V2;
      } catch {
        // 能力確認に失敗しても、公開済みv1の送信経路は止めない。
      }
      result.payload = buildPayload(editor.doc, documentId, {
        ...(result.options || {}),
        contractVersion: sendVersion,
        sharedLinkEntries: _sharedLinkEntries(),
      });
      const response = await fetch('/api/bmanga/scenario/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ port: result.port, token: result.token, payload: result.payload }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(data.detail || data.error || '送信に失敗しました');
      const compatibilityNotice = sendVersion === VERSION
        ? '。ルビの表示設定は送信されません'
        : '';
      showStatus?.(`B-MANGAへ${result.payload.pages.length}ページを送信しました${compatibilityNotice}`);
      return data;
    } catch (error) {
      showStatus?.(error.message || 'B-MANGAへの送信に失敗しました', true);
    } finally { hideLoading?.(); }
  }

  window.MeldexBManga = {
    isAvailable,
    resolveVisibleBody,
    resolveRubySpans,
    normalizeRubyPresentation,
    supportsV2: _supportsV2,
    buildPayload,
    sendActiveScenario,
  };
})();

;

/* === gb-scriptnote-role-management.js === */
;
/* gb-scriptnote-role-management.js: タイプ／キャラ分離管理UI */

Object.assign(ScriptNoteEditor.prototype, {
  _roleManagementAdapter() {
    const doc = this.doc;
    const model = globalThis.GBScriptNoteRoleModel || null;
    const needsNormalization = Number(doc?.schema_version) < 3
      || !Array.isArray(doc?.scenarioTypes)
      || !Array.isArray(doc?.characters);
    if (needsNormalization && model?.ensureDocument) model.ensureDocument(doc);
    doc.scenarioTypes = Array.isArray(doc.scenarioTypes) ? doc.scenarioTypes : [];
    doc.characters = Array.isArray(doc.characters) ? doc.characters : [];
    const invoke = (name, args, fallback) => {
      if (typeof model?.[name] === 'function') return model[name](...args);
      return fallback();
    };
    const uniqueId = (kind) => {
      const prefix = kind === 'type' ? 'type-' : 'char-';
      const used = new Set([...doc.scenarioTypes, ...doc.characters].map(item => String(item?.id || '')));
      let id;
      do {
        const seed = globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
        id = prefix + seed;
      } while (used.has(id));
      return id;
    };
    const uniqueName = (base, self = null) => {
      const wanted = String(base || '').trim() || '名称未設定';
      const used = new Set([...doc.scenarioTypes, ...doc.characters]
        .filter(item => item !== self).map(item => String(item?.name || '').trim()).filter(Boolean));
      if (!used.has(wanted)) return wanted;
      let index = 2;
      while (used.has(`${wanted} ${index}`)) index += 1;
      return `${wanted} ${index}`;
    };
    const checkedName = (name, self = null) => {
      const wanted = String(name || '').trim();
      if (!wanted) throw new Error('名前を入力してください');
      const duplicate = [...doc.scenarioTypes, ...doc.characters]
        .some(item => item !== self && String(item?.name || '').trim() === wanted);
      if (duplicate) throw new Error(`「${wanted}」はすでに使用されています`);
      return wanted;
    };
    const references = (kind, id) => {
      const value = invoke('countReferences', [doc, { kind, id }], () => null);
      if (Number.isFinite(Number(value))) return Number(value);
      if (value && Number.isFinite(Number(value.total))) return Number(value.total);
      if (value?.references && Number.isFinite(Number(value.references.total))) {
        return Number(value.references.total);
      }
      if (kind === 'type') {
        return doc.characters.filter(character => character?.typeId === id).length
          + (doc.rows || []).filter(row => row?.roleRef?.kind === 'type' && row.roleRef.id === id).length;
      }
      return (doc.rows || []).filter(row => row?.roleRef?.kind === 'character' && row.roleRef.id === id).length;
    };
    const canDelete = (kind, id, replacement = null) => {
      const value = invoke('canDeleteRole', [doc, { kind, id }, replacement], () => null);
      if (typeof value === 'boolean') return value;
      if (value && typeof value === 'object') {
        return value.allowed !== false && value.ok !== false && value.canDelete !== false;
      }
      return references(kind, id) === 0;
    };
    const touch = () => {
      this._calcCache = null;
      this._markDirty();
      this._render();
    };
    return {
      model,
      types: doc.scenarioTypes,
      characters: doc.characters.filter(character => !character?.isDefault && !character?.isTypeDefault),
      uniqueName,
      references,
      canDelete,
      touch,
      addType: () => {
        const defaults = JSON.parse(JSON.stringify(doc.editor?.defaultType || {}));
        const type = {
          ...defaults,
          id: uniqueId('type'),
          name: uniqueName('新しいタイプ'),
          roleStyle: { ...(defaults.roleStyle || {}) },
          textStyle: { ...(defaults.textStyle || {}) },
          gutterStyle: { ...(defaults.gutterStyle || {}) },
          gutter2Style: { ...(defaults.gutter2Style || {}) },
          customStyles: { ...(defaults.customStyles || {}) },
          kind: defaults.kind || 'dialogue',
          isBreak: !!defaults.isBreak,
          isSummary: !!defaults.isSummary,
        };
        delete type.isTypeDefault;
        delete type.isDefault;
        delete type.isRoleNone;
        doc.scenarioTypes.push(type);
        return type;
      },
      addCharacter: (name = '新しいキャラ', typeId = null) => {
        const characterName = uniqueName(name);
        const character = invoke(
          'ensureCharacterForName',
          [doc, characterName, { nameColor: '#cccccc' }],
          () => {
            const item = {
              id: uniqueId('character'),
              name: characterName,
              typeId: null,
              nameColor: '#cccccc',
            };
            doc.characters.push(item);
            return item;
          },
        );
        if (typeId) invoke(
          'setCharacterType',
          [doc, character.id, typeId],
          () => { character.typeId = typeId; return character; },
        );
        return character;
      },
      renameType: (type, name) => invoke(
        'renameType',
        [doc, type.id, String(name || '').trim()],
        () => { type.name = checkedName(name, type); return type; },
      ),
      renameCharacter: (character, name) => invoke(
        'renameCharacter',
        [doc, character.id, String(name || '').trim()],
        () => { character.name = checkedName(name, character); return character; },
      ),
      setCharacterType: (character, typeId) => invoke(
        'setCharacterType',
        [doc, character.id, typeId || null],
        () => {
          character.typeId = typeId || null;
          if (character.typeId) delete character.legacyAppearance;
          return character;
        },
      ),
      remove: (kind, ids, replacement = null) => {
        ids.forEach(id => invoke(
          'deleteRole',
          [doc, { kind, id }, replacement],
          () => {
            if (references(kind, id)) throw new Error('使用中の役割は置換先なしで削除できません');
            const target = kind === 'type' ? doc.scenarioTypes : doc.characters;
            const index = target.findIndex(item => item?.id === id);
            if (index >= 0) target.splice(index, 1);
          },
        ));
      },
      move: (kind, id, delta) => {
        const target = kind === 'type' ? doc.scenarioTypes : doc.characters;
        const index = target.findIndex(item => item?.id === id);
        const next = index + delta;
        if (index < 0 || next < 0 || next >= target.length) return false;
        const [item] = target.splice(index, 1);
        target.splice(next, 0, item);
        return true;
      },
      clone: (kind, source) => {
        const clone = JSON.parse(JSON.stringify(source));
        clone.id = uniqueId(kind);
        clone.name = uniqueName(`${source.name || (kind === 'type' ? 'タイプ' : 'キャラ')}（コピー）`);
        const target = kind === 'type' ? doc.scenarioTypes : doc.characters;
        const index = target.indexOf(source);
        target.splice(index < 0 ? target.length : index + 1, 0, clone);
        return clone;
      },
    };
  },

  _renderSeparatedRoleManagement(container) {
    const adapter = this._roleManagementAdapter();
    this._detailTypeSelection = this._detailTypeSelection || new Set();
    this._detailCharacterSelection = this._detailCharacterSelection || new Set();
    this._detailSelection = new Set();
    container.innerHTML = '';
    const root = document.createElement('div');
    root.className = 'sn2-detail sn2-role-management';
    root.dataset.e2eId = 'scriptnote-role-management';
    root.append(
      this._buildRoleManagementSection('type', adapter, container),
      this._buildRoleManagementSection('character', adapter, container),
    );
    container.appendChild(root);
  },

  _roleManagementButton(label, title, action, e2eId = '') {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'sn2-detail-add-btn';
    button.textContent = label;
    button.title = title;
    if (e2eId) button.dataset.e2eId = e2eId;
    button.addEventListener('click', action);
    return button;
  },

  _buildRoleManagementSection(kind, adapter, panelContainer) {
    const isType = kind === 'type';
    const items = isType ? adapter.types : adapter.characters;
    const selection = isType ? this._detailTypeSelection : this._detailCharacterSelection;
    const section = document.createElement('section');
    section.className = `sn2-role-manage-section sn2-role-manage-section--${isType ? 'types' : 'characters'}`;
    section.dataset.e2eId = `scriptnote-${kind}-management-section`;
    const header = document.createElement('header');
    header.className = 'sn2-role-manage-header';
    header.title = isType
      ? 'キャラと紐づいたタイプは、シナリオのタイプ列候補から自動的に外れます'
      : 'キャラは名前色と対応タイプを持ち、本文などの書式は対応タイプから取得します';
    const title = document.createElement('h2');
    title.className = 'sn2-role-manage-title';
    title.textContent = isType ? 'タイプ' : 'キャラ';
    title.title = header.title;
    const count = document.createElement('span');
    count.className = 'sn2-role-manage-count';
    const unset = isType ? 0 : items.filter(item => !item.typeId).length;
    count.textContent = isType ? `${items.length}件` : `${items.length}件・未設定${unset}件`;
    title.appendChild(count);
    header.appendChild(title);
    section.appendChild(header);
    const scroll = document.createElement('div');
    scroll.className = 'sn2-role-manage-scroll';
    scroll.dataset.e2eId = `scriptnote-${kind}-list`;
    scroll.tabIndex = 0;
    scroll.setAttribute('aria-label', `${isType ? 'タイプ' : 'キャラ'}一覧`);
    const table = document.createElement('table');
    table.className = `sn2-role-manage-table sn2-role-manage-table--${isType ? 'types' : 'characters'}`;
    const thead = document.createElement('thead');
    const headings = isType
      ? [['', '選択'], ['タイプ名', 'シナリオ上の機能と完全な書式を所有する名前'], ['書式', '書式プレビュー。クリックすると既存の完全な書式設定を開きます'], ['設定', 'タイプの機能・ガター・詳細設定']]
      : [['', '選択'], ['色', 'タイプ列に表示するキャラ名だけへ適用する名前色'], ['キャラ名', 'シナリオに表示するキャラ名'], ['対応タイプ', '選択したタイプの完全な書式を使用します'], ['設定', 'キャラ行の編集と並べ替え']];
    const headingRow = document.createElement('tr');
    headings.forEach(([label, tooltip]) => {
      const th = document.createElement('th');
      th.textContent = label;
      th.title = tooltip;
      headingRow.appendChild(th);
    });
    thead.appendChild(headingRow);
    table.appendChild(thead);
    const tbody = document.createElement('tbody');
    if (!items.length) {
      const row = document.createElement('tr');
      const cell = document.createElement('td');
      cell.colSpan = headings.length;
      cell.className = 'sn2-role-manage-empty';
      cell.textContent = isType ? 'タイプがありません' : 'キャラがありません';
      row.appendChild(cell);
      tbody.appendChild(row);
    } else {
      items.forEach((item, index) => {
        tbody.appendChild(isType
          ? this._buildScenarioTypeManagementRow(item, index, adapter, panelContainer)
          : this._buildScenarioCharacterManagementRow(item, index, adapter, panelContainer));
      });
    }
    table.appendChild(tbody);
    scroll.appendChild(table);
    section.appendChild(scroll);
    section.appendChild(this._buildRoleManagementToolbar(kind, adapter, panelContainer));
    return section;
  },

  _showTypeManagementSettingsMenu(anchor, type, panelContainer) {
    document.querySelectorAll('.sn2-type-settings-menu').forEach(element => element.remove());
    const menu = document.createElement('div');
    menu.className = 'gb-fmt-popup sn2-type-settings-menu';
    menu.setAttribute('role', 'menu');
    const styleTargets = [
      ['_role', 'タイプ列の書式', 'タイプ列に表示する名前の完全な書式を設定'],
      ['_text', '本文の書式', '本文列の完全な書式を設定'],
      ['_gutter', '大区切りの書式', '大区切り列の完全な書式を設定'],
      ['_gutter2', '小区切りの書式', '小区切り列の完全な書式を設定'],
    ];
    (this.doc.editor?.customColumns || []).forEach(column => {
      styleTargets.push([column.id, `${column.label || column.id}の書式`, 'カスタム列の完全な書式を設定']);
    });
    styleTargets.forEach(([columnId, label, title]) => {
      menu.appendChild(this._roleManagementButton(label, title, () => {
        menu.remove();
        this._showCellStylePopup(anchor, type, columnId, panelContainer);
      }, `scriptnote-type-style-${columnId.replace(/^_/, '')}`));
    });
    menu.appendChild(this._roleManagementButton('機能・詳細設定', 'タイプの機能、区切り、その他の詳細設定を開く', () => {
      menu.remove();
      this._showRoleOptionsPopup(anchor, type, panelContainer);
    }, 'scriptnote-type-function-settings'));
    document.body.appendChild(menu);
    if (typeof positionPopup === 'function') positionPopup(menu, anchor.getBoundingClientRect());
    else if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);
    const close = (event) => {
      if (event.key === 'Escape' || (!menu.contains(event.target) && event.target !== anchor)) {
        menu.remove();
        document.removeEventListener('pointerdown', close, true);
        document.removeEventListener('keydown', close, true);
      }
    };
    setTimeout(() => {
      document.addEventListener('pointerdown', close, true);
      document.addEventListener('keydown', close, true);
    }, 0);
  },

  _buildScenarioTypeManagementRow(type, index, adapter, panelContainer) {
    const row = document.createElement('tr');
    row.className = 'sn2-role-manage-row';
    row.dataset.roleId = type.id;
    row.dataset.e2eId = `scriptnote-type-row-${index}`;
    row.draggable = true;
    const selected = this._detailTypeSelection.has(type.id);
    row.classList.toggle('selected', selected);
    const selectCell = document.createElement('td');
    const check = document.createElement('input');
    check.type = 'checkbox';
    check.checked = selected;
    check.title = `${type.name || 'タイプ'}を選択`;
    check.dataset.e2eId = `scriptnote-type-select-${index}`;
    check.setAttribute('aria-label', check.title);
    check.addEventListener('change', () => {
      if (check.checked) this._detailTypeSelection.add(type.id);
      else this._detailTypeSelection.delete(type.id);
      row.classList.toggle('selected', check.checked);
    });
    selectCell.appendChild(check);
    const nameCell = document.createElement('td');
    const name = document.createElement('input');
    name.type = 'text';
    name.className = 'sn2-role-manage-name';
    name.value = type.name || '';
    name.title = 'タイプ名。キャラ名を含む他の役割名と重複できません';
    name.dataset.e2eId = `scriptnote-type-name-${index}`;
    name.setAttribute('aria-label', 'タイプ名');
    name.addEventListener('change', () => {
      const previous = type.name;
      try {
        this._pushUndo('タイプ名変更');
        adapter.renameType(type, name.value);
      } catch (error) {
        name.value = previous || '';
        if (typeof showStatus === 'function') showStatus(error?.message || String(error), true);
        return;
      }
      name.value = type.name || previous;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    });
    nameCell.appendChild(name);
    const previewCell = document.createElement('td');
    const preview = document.createElement('button');
    preview.type = 'button';
    preview.className = 'sn2-role-style-preview';
    preview.title = 'タイプ列の書式を設定';
    preview.dataset.e2eId = `scriptnote-type-style-preview-${index}`;
    preview.setAttribute('aria-label', `${type.name || 'タイプ'}の書式を設定`);
    const roleStyle = type.roleStyle || {};
    preview.textContent = `${roleStyle.textBefore || ''}${type.name || 'Aa'}${roleStyle.textAfter || ''}`;
    Object.assign(preview.style, {
      color: roleStyle.textColor || '',
      background: roleStyle.bgColor || '',
      fontWeight: roleStyle.fontWeight === 'bold' || roleStyle.bold ? 'bold' : '',
      fontStyle: roleStyle.fontStyle === 'italic' || roleStyle.italic ? 'italic' : '',
      fontFamily: roleStyle.fontFamily || '',
      fontSize: roleStyle.fontSize ? `${roleStyle.fontSize}px` : '',
    });
    preview.addEventListener('click', () => this._showCellStylePopup(preview, type, '_role', panelContainer));
    previewCell.appendChild(preview);
    const settingsCell = document.createElement('td');
    settingsCell.className = 'sn2-role-manage-actions';
    const options = this._roleManagementButton('設定', 'タイプの機能、ガター、カスタム列を設定', () => {
      this._showTypeManagementSettingsMenu(options, type, panelContainer);
    }, `scriptnote-type-settings-${index}`);
    const up = this._roleManagementButton('↑', 'タイプを1つ上へ移動', () => {
      this._pushUndo('タイプ並び替え');
      if (!adapter.move('type', type.id, -1)) return;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    }, `scriptnote-type-move-up-${index}`);
    const down = this._roleManagementButton('↓', 'タイプを1つ下へ移動', () => {
      this._pushUndo('タイプ並び替え');
      if (!adapter.move('type', type.id, 1)) return;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    }, `scriptnote-type-move-down-${index}`);
    up.disabled = index === 0;
    down.disabled = index === adapter.types.length - 1;
    settingsCell.append(options, up, down);
    row.append(selectCell, nameCell, previewCell, settingsCell);
    this._bindRoleManagementDrag(row, 'type', type.id, adapter, panelContainer);
    return row;
  },

  _buildScenarioCharacterManagementRow(character, index, adapter, panelContainer) {
    const row = document.createElement('tr');
    row.className = 'sn2-role-manage-row';
    row.dataset.roleId = character.id;
    row.dataset.e2eId = `scriptnote-character-row-${index}`;
    row.draggable = true;
    const selected = this._detailCharacterSelection.has(character.id);
    row.classList.toggle('selected', selected);
    const selectCell = document.createElement('td');
    const check = document.createElement('input');
    check.type = 'checkbox';
    check.checked = selected;
    check.title = `${character.name || 'キャラ'}を選択`;
    check.dataset.e2eId = `scriptnote-character-select-${index}`;
    check.setAttribute('aria-label', check.title);
    check.addEventListener('change', () => {
      if (check.checked) this._detailCharacterSelection.add(character.id);
      else this._detailCharacterSelection.delete(character.id);
      row.classList.toggle('selected', check.checked);
    });
    selectCell.appendChild(check);
    const colorCell = document.createElement('td');
    const color = document.createElement('input');
    color.type = 'color';
    color.className = 'sn2-role-name-color';
    color.value = /^#[0-9a-f]{6}$/i.test(String(character.nameColor || '')) ? character.nameColor : '#cccccc';
    color.title = 'タイプ列に表示するキャラ名の色';
    color.dataset.e2eId = `scriptnote-character-name-color-${index}`;
    color.setAttribute('aria-label', `${character.name || 'キャラ'}の名前色`);
    let colorUndoCaptured = false;
    color.addEventListener('input', () => {
      if (!colorUndoCaptured) {
        this._pushUndo('キャラ名前色変更');
        colorUndoCaptured = true;
      }
      character.nameColor = color.value;
      adapter.touch();
    });
    const resetColorUndoCapture = () => { colorUndoCaptured = false; };
    color.addEventListener('change', resetColorUndoCapture);
    color.addEventListener('blur', resetColorUndoCapture);
    colorCell.appendChild(color);
    const nameCell = document.createElement('td');
    const name = document.createElement('input');
    name.type = 'text';
    name.className = 'sn2-role-manage-name';
    name.value = character.name || '';
    name.title = 'キャラ名。タイプ名を含む他の役割名と重複できません';
    name.dataset.e2eId = `scriptnote-character-name-${index}`;
    name.setAttribute('aria-label', 'キャラ名');
    name.addEventListener('change', () => {
      const previous = character.name;
      try {
        this._pushUndo('キャラ名変更');
        adapter.renameCharacter(character, name.value);
      } catch (error) {
        name.value = previous || '';
        if (typeof showStatus === 'function') showStatus(error?.message || String(error), true);
        return;
      }
      name.value = character.name || previous;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    });
    nameCell.appendChild(name);
    const typeCell = document.createElement('td');
    const typeSelect = document.createElement('select');
    typeSelect.className = 'sn2-role-type-select';
    typeSelect.title = '対応タイプの見た目と機能を使用します。未設定では既定または旧表示を維持します';
    typeSelect.dataset.e2eId = `scriptnote-character-type-${index}`;
    typeSelect.setAttribute('aria-label', `${character.name || 'キャラ'}の対応タイプ`);
    const none = document.createElement('option');
    none.value = '';
    none.textContent = '（未設定）';
    typeSelect.appendChild(none);
    adapter.types.forEach(type => {
      const option = document.createElement('option');
      option.value = type.id;
      option.textContent = type.name || '名称未設定';
      option.selected = type.id === character.typeId;
      typeSelect.appendChild(option);
    });
    typeSelect.addEventListener('change', () => {
      this._pushUndo('キャラ対応タイプ変更');
      adapter.setCharacterType(character, typeSelect.value || null);
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    });
    typeCell.appendChild(typeSelect);
    if (!character.typeId) {
      const badge = document.createElement('span');
      badge.className = 'sn2-role-unset-badge';
      badge.textContent = '未設定';
      badge.title = character.legacyAppearance ? '旧ファイルの表示を維持しています' : '新規タイプの既定書式を使用します';
      typeCell.appendChild(badge);
    }
    const settingsCell = document.createElement('td');
    settingsCell.className = 'sn2-role-manage-actions';
    const edit = this._roleManagementButton('設定', 'この行で名前色、キャラ名、対応タイプを設定', () => {
      row.classList.add('is-editing');
      name.focus();
      name.select();
    }, `scriptnote-character-settings-${index}`);
    const up = this._roleManagementButton('↑', 'キャラを1つ上へ移動', () => {
      this._pushUndo('キャラ並び替え');
      if (!adapter.move('character', character.id, -1)) return;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    }, `scriptnote-character-move-up-${index}`);
    const down = this._roleManagementButton('↓', 'キャラを1つ下へ移動', () => {
      this._pushUndo('キャラ並び替え');
      if (!adapter.move('character', character.id, 1)) return;
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    }, `scriptnote-character-move-down-${index}`);
    up.disabled = index === 0;
    down.disabled = index === adapter.characters.length - 1;
    settingsCell.append(edit, up, down);
    row.append(selectCell, colorCell, nameCell, typeCell, settingsCell);
    this._bindRoleManagementDrag(row, 'character', character.id, adapter, panelContainer);
    return row;
  },

  _bindRoleManagementDrag(row, kind, id, adapter, panelContainer) {
    row.addEventListener('dragstart', event => {
      event.dataTransfer?.setData('text/plain', `${kind}:${id}`);
      row.classList.add('sn2-dragging');
    });
    row.addEventListener('dragend', () => row.classList.remove('sn2-dragging'));
    row.addEventListener('dragover', event => {
      event.preventDefault();
      row.classList.add('sn2-drop-above');
    });
    row.addEventListener('dragleave', () => row.classList.remove('sn2-drop-above'));
    row.addEventListener('drop', event => {
      event.preventDefault();
      row.classList.remove('sn2-drop-above');
      const [sourceKind, sourceId] = String(event.dataTransfer?.getData('text/plain') || '').split(':');
      if (sourceKind !== kind || !sourceId || sourceId === id) return;
      const target = kind === 'type' ? adapter.types : adapter.characters;
      const from = target.findIndex(item => item.id === sourceId);
      const to = target.findIndex(item => item.id === id);
      if (from < 0 || to < 0) return;
      this._pushUndo(kind === 'type' ? 'タイプ並び替え' : 'キャラ並び替え');
      const [moved] = target.splice(from, 1);
      target.splice(to, 0, moved);
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    });
  },

  _deleteManagedRoles(kind, selected, adapter, panelContainer, onDeleted = null) {
    if (!selected.length) return;
    const isType = kind === 'type';
    const selection = isType ? this._detailTypeSelection : this._detailCharacterSelection;
    const selectedIds = new Set(selected.map(item => item.id));
    const used = selected.filter(item => adapter.references(kind, item.id) > 0);
    const finish = (replacement = null, close = null) => {
      try {
        selected.forEach(item => {
          if (!adapter.canDelete(kind, item.id, replacement)) {
            throw new Error(`「${item.name || '名称未設定'}」の参照を置換できません`);
          }
        });
        this._pushUndo(isType ? 'タイプ削除' : 'キャラ削除');
        adapter.remove(kind, selected.map(item => item.id), replacement);
      } catch (error) {
        if (typeof showStatus === 'function') showStatus(error?.message || String(error), true);
        return;
      }
      selection.clear();
      close?.();
      onDeleted?.();
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    };
    if (!used.length) {
      const message = `${selected.length}件の${isType ? 'タイプ' : 'キャラ'}を削除しますか？`;
      if (typeof showConfirmDialog === 'function') showConfirmDialog(message, () => finish());
      return;
    }
    const candidates = (isType ? adapter.types : adapter.characters)
      .filter(item => !selectedIds.has(item.id));
    if (isType && !candidates.length) {
      if (typeof showStatus === 'function') {
        showStatus('使用中のタイプを削除するには、置換先となる別のタイプが必要です', true);
      }
      return;
    }
    if (!globalThis.GBUI?.createModal) {
      if (typeof showStatus === 'function') {
        showStatus(`使用中の${isType ? 'タイプ' : 'キャラ'}は、置換先を指定してから削除してください`, true);
      }
      return;
    }
    const body = document.createElement('div');
    body.className = 'sn2-role-delete-body';
    const explanation = document.createElement('p');
    explanation.textContent = isType
      ? '使用中のタイプです。紐づくキャラと直接使用している行を、別のタイプへ一括置換してから削除します。'
      : '使用中のキャラです。使用行を別のキャラへ置換するか、役割を「（なし）」へ明示的に解除してから削除します。';
    body.appendChild(explanation);
    const impact = document.createElement('ul');
    used.forEach(item => {
      const line = document.createElement('li');
      line.textContent = `${item.name || '名称未設定'}: ${adapter.references(kind, item.id)}件`;
      impact.appendChild(line);
    });
    body.appendChild(impact);
    const label = document.createElement('label');
    label.className = 'sn2-role-delete-field';
    const caption = document.createElement('span');
    caption.textContent = isType ? '置換先タイプ' : '参照の処理';
    const select = document.createElement('select');
    select.dataset.e2eId = `scriptnote-${kind}-delete-replacement`;
    if (!isType) {
      const clear = document.createElement('option');
      clear.value = 'none:none';
      clear.textContent = '参照を「（なし）」に解除';
      select.appendChild(clear);
    }
    candidates.forEach(item => {
      const option = document.createElement('option');
      option.value = `${kind}:${item.id}`;
      option.textContent = `${isType ? '置換: ' : '別のキャラへ置換: '}${item.name || '名称未設定'}`;
      select.appendChild(option);
    });
    label.append(caption, select);
    body.appendChild(label);
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'gb-btn gb-btn-secondary';
    cancel.textContent = 'キャンセル';
    const confirm = document.createElement('button');
    confirm.type = 'button';
    confirm.className = 'gb-btn gb-btn-danger';
    confirm.textContent = '置換して削除';
    confirm.dataset.e2eId = `scriptnote-${kind}-delete-confirm`;
    const modal = globalThis.GBUI.createModal({
      title: `${isType ? 'タイプ' : 'キャラ'}の参照を置換して削除`,
      body,
      footer: [cancel, confirm],
      minWidth: 380,
      extraClass: 'sn2-role-delete-modal',
    });
    cancel.addEventListener('click', () => modal.close());
    confirm.addEventListener('click', () => {
      const [replacementKind, replacementId] = select.value.split(':');
      finish({ kind: replacementKind, id: replacementId }, modal.close);
    });
    document.body.appendChild(modal.overlay);
    select.focus();
  },

  _buildRoleManagementToolbar(kind, adapter, panelContainer) {
    const isType = kind === 'type';
    const selection = isType ? this._detailTypeSelection : this._detailCharacterSelection;
    const items = isType ? adapter.types : adapter.characters;
    const toolbar = document.createElement('div');
    toolbar.className = 'sn2-detail-toolbar sn2-role-manage-toolbar';
    const rerender = () => {
      adapter.touch();
      this.renderDetailPanel(panelContainer);
    };
    toolbar.appendChild(this._roleManagementButton('＋追加', isType ? '新規タイプを追加' : '新規キャラを追加', () => {
      this._pushUndo(isType ? 'タイプ追加' : 'キャラ追加');
      const created = isType ? adapter.addType() : adapter.addCharacter();
      selection.clear();
      selection.add(created.id);
      rerender();
    }, `scriptnote-${kind}-add`));
    toolbar.appendChild(this._roleManagementButton('複製', '選択中を複製', () => {
      const selected = items.filter(item => selection.has(item.id));
      if (!selected.length) return;
      this._pushUndo(isType ? 'タイプ複製' : 'キャラ複製');
      selection.clear();
      selected.forEach(item => selection.add(adapter.clone(kind, item).id));
      rerender();
    }, `scriptnote-${kind}-duplicate`));
    toolbar.appendChild(this._roleManagementButton('削除', '選択中を削除', () => {
      const selected = items.filter(item => selection.has(item.id));
      this._deleteManagedRoles(kind, selected, adapter, panelContainer);
    }, `scriptnote-${kind}-delete`));
    toolbar.appendChild(this._roleManagementButton('全選択', `すべての${isType ? 'タイプ' : 'キャラ'}を選択`, () => {
      items.forEach(item => selection.add(item.id));
      this.renderDetailPanel(panelContainer);
    }, `scriptnote-${kind}-select-all`));
    if (!isType) {
      const spacer = document.createElement('span');
      spacer.className = 'sn2-detail-toolbar-spacer';
      toolbar.appendChild(spacer);
      const bulk = document.createElement('select');
      bulk.className = 'sn2-role-bulk-type';
      bulk.dataset.e2eId = 'scriptnote-character-bulk-type-select';
      bulk.title = '選択したキャラへ一括設定する対応タイプ';
      bulk.setAttribute('aria-label', '一括設定する対応タイプ');
      const none = document.createElement('option');
      none.value = '';
      none.textContent = '対応タイプ: 未設定';
      bulk.appendChild(none);
      adapter.types.forEach(type => {
        const option = document.createElement('option');
        option.value = type.id;
        option.textContent = `対応タイプ: ${type.name}`;
        bulk.appendChild(option);
      });
      toolbar.appendChild(bulk);
      toolbar.appendChild(this._roleManagementButton('一括設定', '選択したキャラの対応タイプをまとめて変更', () => {
        const selected = adapter.characters.filter(character => selection.has(character.id));
        if (!selected.length) return;
        this._pushUndo('キャラ対応タイプ一括変更');
        selected.forEach(character => adapter.setCharacterType(character, bulk.value || null));
        rerender();
      }, 'scriptnote-character-bulk-type'));
      toolbar.appendChild(this._roleManagementButton('DB読込', 'DBからキャラを読み込む', () => {
        this._showDbImportModal(panelContainer);
      }, 'scriptnote-character-import-db'));
    }
    return toolbar;
  },

});

;

/* === gb-scriptnote-detail.js === */
;
/* gb-scriptnote-detail.js: 台本エディタ v2 — 詳細パネル（タイプ管理）
   ScriptNoteEditor.prototype を拡張する */

Object.assign(ScriptNoteEditor.prototype, {

  renderDetailPanel(container) {
    if (!container || !this.doc) return;
    return this._renderSeparatedRoleManagement(container);
  },

  _renderLegacyDetailPanel(container) {
    if (!container || !this.doc) return;
    this._ensureDefaultChara();
    this._detailSelection = this._detailSelection || new Set();
    container.innerHTML = '';
    const wrap = document.createElement('div');
    wrap.className = 'sn2-detail';
    const e = typeof esc === 'function' ? esc : (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

    const mkBtn = (label, title, onClick, e2eId = '') => {
      const b = document.createElement('button');
      b.className = 'sn2-detail-add-btn';
      b.type = 'button';
      b.textContent = label;
      b.title = title;
      if (e2eId) b.dataset.e2eId = e2eId;
      b.addEventListener('click', onClick);
      return b;
    };

    // ツールバー（タイトルバーなし、適用・DB読込を右寄せ）
    const toolbar = document.createElement('div');
    toolbar.className = 'sn2-detail-toolbar';
    toolbar.appendChild(mkBtn('＋追加', '新規タイプ追加', () => {
      this._pushUndo('タイプ追加');
      const name = this._uniqueRoleName ? this._uniqueRoleName('新しいキャラ') : '新しいキャラ';
      const newChara = this._createCharaFromTypeDefault(name);
      // デフォルトタイプの直前に挿入（末尾固定の不変条件を維持）
      const defIdx = this.doc.characters.findIndex(c => c.isDefault);
      if (defIdx >= 0) this.doc.characters.splice(defIdx, 0, newChara);
      else this.doc.characters.push(newChara);
      this._detailSelection.clear();
      this._markDirty();
      this.renderDetailPanel(container);
    }, 'scriptnote-detail-add-type'));
    toolbar.appendChild(mkBtn('複製', '選択中を複製', () => {
      if (!this._detailSelection.size) return;
      // デフォルトタイプは複製対象外
      const sorted = Array.from(this._detailSelection)
        .filter(i => !this.doc.characters[i]?.isDefault)
        .sort((a, b) => a - b);
      if (!sorted.length) return;
      this._pushUndo('タイプ複製');
      let offset = 0;
      sorted.forEach(i => {
        const src = this.doc.characters[i + offset];
        if (src) {
          const dup = this._cloneChara(src);
          dup.name = this._uniqueRoleName ? this._uniqueRoleName((src.name || 'タイプ') + '（コピー）', src) : src.name + '（コピー）';
          this.doc.characters.splice(i + offset + 1, 0, dup);
          offset++;
        }
      });
      this._detailSelection.clear();
      this._markDirty();
      this.renderDetailPanel(container);
    }, 'scriptnote-detail-duplicate-selected'));
    toolbar.appendChild(mkBtn('削除', '選択中を削除', () => {
      if (!this._detailSelection.size) return;
      // デフォルトタイプは削除対象外
      const targetIdxs = Array.from(this._detailSelection).filter(i => !this.doc.characters[i]?.isDefault);
      if (!targetIdxs.length) return;
      const names = targetIdxs.map(i => this.doc.characters[i]?.name).filter(Boolean);
      showConfirmDialog(`${targetIdxs.length}件のタイプを削除しますか？\n${names.join(', ')}`, () => {
        this._pushUndo('タイプ削除');
        this._clearRolesInRows(names);
        targetIdxs.sort((a, b) => b - a).forEach(i => this.doc.characters.splice(i, 1));
        this._detailSelection.clear();
        this._calcCache = null;
        this._render();
        this._markDirty();
        this.renderDetailPanel(container);
      });
    }, 'scriptnote-detail-delete-selected'));
    // 全選択ボタン
    const selectAllBtn = mkBtn('全選択', 'すべてのタイプを選択', () => {
      // （なし）行（isDefault）は選択対象外
      this.doc.characters.forEach((c, i) => { if (!c?.isDefault) this._detailSelection.add(i); });
      container.querySelectorAll('.sn2-detail-item').forEach(el => {
        if (el.dataset.idx === 'type-default') return;
        if (el.dataset.kind === 'blank') return;
        el.classList.add('selected');
        const cb = el.querySelector('.sn2-detail-check');
        if (cb) cb.checked = true;
      });
      this._updateBulkBar(toolbar);
    }, 'scriptnote-detail-select-all');
    toolbar.appendChild(selectAllBtn);
    // 全解除ボタン
    const deselectBtn = mkBtn('全解除', '選択をすべて解除', () => {
      this._detailSelection.clear();
      this._detailLastClickIdx = -1;
      container.querySelectorAll('.sn2-detail-item').forEach(el => {
        el.classList.remove('selected');
        const cb = el.querySelector('.sn2-detail-check');
        if (cb) cb.checked = false;
      });
      this._updateBulkBar(toolbar);
    }, 'scriptnote-detail-deselect-all');
    deselectBtn.className += ' sn2-detail-bulk-btn';
    toolbar.appendChild(deselectBtn);
    // 一括操作（複数選択時のみ表示）— 背景色・文字色ボタン削除、一括設定のみ残す
    const bulkSep = document.createElement('span');
    bulkSep.className = 'sn2-detail-bulk-sep';
    bulkSep.textContent = '|';
    toolbar.appendChild(bulkSep);
    const bulkCount = document.createElement('span');
    bulkCount.className = 'sn2-detail-bulk-count';
    bulkCount.textContent = '';
    toolbar.appendChild(bulkCount);
    const bulkAllBtn = mkBtn('一括設定…', '全プロパティ一括変更', () => this._showBulkEditPopup(container), 'scriptnote-detail-bulk-settings');
    bulkAllBtn.className += ' sn2-detail-bulk-btn';
    toolbar.appendChild(bulkAllBtn);
    // 右寄せスペーサー + DB読込
    const spacer = document.createElement('span');
    spacer.className = 'sn2-detail-toolbar-spacer';
    toolbar.appendChild(spacer);
    toolbar.appendChild(mkBtn('DB読込', 'DBからキャラ読み込み', () => this._showDbImportModal(container), 'scriptnote-detail-import-db'));
    this._detailBulkBar = toolbar;

    // キャラクターリスト（列×タイプ表形式）
    const list = document.createElement('div');
    list.className = 'sn2-detail-list';
    this._detailLastClickIdx = -1;
    // 列定義（標準列 + カスタム列）
    const detailCols = [
      { id: '_role', label: 'タイプ' },
      { id: '_text', label: 'テキスト' },
    ];
    (this.doc.editor?.customColumns || []).forEach(col => {
      detailCols.push({ id: col.id, label: col.label || col.id });
    });
    // テーブル構築
    const table = document.createElement('table');
    table.className = 'sn2-detail-table';
    // colgroup で列幅を明示指定
    const colgroup = document.createElement('colgroup');
    const addCol = (w) => { const c = document.createElement('col'); c.style.width = w; colgroup.appendChild(c); };
    addCol('36px'); // チェック+ハンドル
    detailCols.forEach(col => {
      if (col.id === '_role') addCol('100px');
      else if (col.id === '_text') addCol('90px');
      else addCol('54px');
    });
    addCol('80px'); // オプション
    table.appendChild(colgroup);
    // ヘッダー行
    const thead = document.createElement('thead');
    const hRow = document.createElement('tr');
    const thCtrl = document.createElement('th');
    thCtrl.className = 'sn2-detail-th-ctrl';
    hRow.appendChild(thCtrl);
    detailCols.forEach(col => {
      const th = document.createElement('th');
      th.className = 'sn2-detail-th-col';
      th.textContent = col.label;
      th.title = `${col.label}列のスタイルを一括設定`;
      th.addEventListener('click', () => this._showColBulkPopup(th, col.id, container));
      hRow.appendChild(th);
    });
    const thInfo = document.createElement('th');
    thInfo.className = 'sn2-detail-th-info';
    thInfo.textContent = 'オプション';
    hRow.appendChild(thInfo);
    thead.appendChild(hRow);
    table.appendChild(thead);
    const tbody = document.createElement('tbody');
    const typeDefault = this._ensureTypeDefaultChara();
    this.doc.characters.forEach((chara, i) => {
      if (chara?.isDefault && typeDefault) {
        tbody.appendChild(this._buildDetailItem(typeDefault, 'type-default', container, detailCols));
      }
      tbody.appendChild(this._buildDetailItem(chara, i, container, detailCols));
    });
    table.appendChild(tbody);
    list.appendChild(table);
    // ツールバー（＋追加等のボタンバー）をリスト内のテーブル直後に配置（スクロールに追従）
    list.appendChild(toolbar);
    wrap.appendChild(list);

    container.appendChild(wrap);
    this._setupDetailDragDrop(list, container);
    this._updateBulkBar(toolbar);
  },

  _buildDetailItem(chara, idx, panelContainer, detailCols) {
    const isDefaultRow = !!chara.isDefault;
    const isTypeDefaultRow = !!chara.isTypeDefault;
    const isMetaRow = isDefaultRow || isTypeDefaultRow;
    const item = document.createElement('tr');
    item.className = 'sn2-detail-item' + (this._detailSelection?.has(idx) ? ' selected' : '') + (isMetaRow ? ' sn2-detail-default' : '');
    item.dataset.idx = idx;
    item.dataset.kind = isTypeDefaultRow
      ? 'type-default'
      : isDefaultRow ? 'blank'
      : (chara.isSummary ? 'summary' : (chara.isBreak ? 'break' : (['dialogue', 'action', 'heading'].includes(chara.kind) ? chara.kind : 'dialogue')));
    item.draggable = !isMetaRow;

    // チェックボックス + ドラッグハンドル セル（横並び）— デフォルト行はチェックボックスのみ（ハンドルなし）
    const ctrlTd = document.createElement('td');
    ctrlTd.className = 'sn2-detail-td-ctrl';
    const check = document.createElement('input');
    check.type = 'checkbox';
    check.className = 'sn2-detail-check';
    check.dataset.e2eId = 'scriptnote-detail-row-check-' + idx;
    check.dataset.sn2DetailIndex = String(idx);
    // （デフォルト）行・（なし）行は選択対象外（複製・削除できない特殊行のため）
    check.disabled = isMetaRow;
    const checkLabel = isTypeDefaultRow
      ? '新規タイプの既定設定'
      : isDefaultRow ? 'タイプなし（選択対象外）'
      : '行を選択: ' + (chara.name || chara.label || chara.role || String(idx + 1));
    check.setAttribute('aria-label', checkLabel);
    check.title = checkLabel;
    check.checked = this._detailSelection?.has(idx) || false;
    check.addEventListener('click', (ev) => {
      ev.stopPropagation();
      if (isMetaRow) return;
      if (ev.shiftKey && this._detailLastClickIdx >= 0) {
        const from = Math.min(this._detailLastClickIdx, idx);
        const to = Math.max(this._detailLastClickIdx, idx);
        const adding = check.checked;
        for (let i = from; i <= to; i++) {
          if (adding) this._detailSelection.add(i); else this._detailSelection.delete(i);
        }
      } else {
        if (check.checked) this._detailSelection.add(idx); else this._detailSelection.delete(idx);
      }
      this._detailLastClickIdx = idx;
      item.closest('.sn2-detail-list')?.querySelectorAll('.sn2-detail-item').forEach(el => {
        const i = Number(el.dataset.idx);
        const sel = this._detailSelection.has(i);
        el.classList.toggle('selected', sel);
        const cb = el.querySelector('.sn2-detail-check');
        if (cb) cb.checked = sel;
      });
      if (this._detailBulkBar) this._updateBulkBar(this._detailBulkBar);
    });
    ctrlTd.appendChild(check);
    if (!isMetaRow) {
      const handle = document.createElement('span');
      handle.className = 'sn2-detail-handle-inline';
      handle.textContent = '⠿';
      ctrlTd.appendChild(handle);
    }
    item.appendChild(ctrlTd);

    // 各列のプレビューセル
    const previewCells = [];
    const CELL_LABELS = {
      _gutter: this._detailCellPreviewLabel('_gutter'),
      _gutter2: this._detailCellPreviewLabel('_gutter2'),
      _role: null,
      _text: this._detailCellPreviewLabel('_text'),
    };
    const _pageBg = 'var(--sn2-page-bg, var(--content-bg, var(--bg)))';
    // 動的スタイルを一括適用するヘルパー (背景・文字・太字・斜体・サイズ)
    const applyDynStyle = (el, props) => { Object.assign(el.style, props); };
    (detailCols || []).forEach(col => {
      const td = document.createElement('td');
      td.className = 'sn2-detail-td-cell';
      const ec = this._resolveCharaColors(chara, col.id);
      const cs = this._getColStyle(chara, col.id);
      const isText = col.id === '_text';
      // 色: 列別スタイル → resolveCharaColors(autoColor対応) → ページ背景色
      const rawBg = cs.bgColor || ec.bgColor || '';
      const bgIsTransparent = !rawBg || rawBg === 'transparent' || rawBg === 'rgba(0,0,0,0)';
      const bgDisplay = bgIsTransparent ? _pageBg : rawBg;
      const fgDisplay = cs.textColor || ec.textColor || 'var(--fg)';
      // フォント: _text列は旧データ互換のcharaフォールバックを使う。_role列はタイプ列専用設定のみ使う。
      const isRole = col.id === '_role';
      const fwActive = (isText ? (cs.fontWeight || chara.fontWeight) : cs.fontWeight) === 'bold';
      const fstActive = (isText ? (cs.fontStyle || chara.fontStyle) : cs.fontStyle) === 'italic';
      const effFz = isText ? (cs.fontSize || chara.fontSize) : cs.fontSize;
      const effFont = isText ? (cs.fontFamily || chara.fontFamily) : cs.fontFamily;
      const effStrokeColor = isText ? (cs.textStrokeColor || chara.textStrokeColor) : cs.textStrokeColor;
      const effStrokeWidth = isText ? (cs.textStrokeWidth || chara.textStrokeWidth) : cs.textStrokeWidth;
      const effAccentColor = cs.accentColor || chara.accentColor || fgDisplay || 'var(--accent)';
      const dynStyle = {
        background: bgDisplay,
        color: fgDisplay,
        fontWeight: fwActive ? 'bold' : '',
        fontStyle: fstActive ? 'italic' : '',
        fontSize: effFz ? effFz + 'px' : '',
        fontFamily: effFont || '',
        webkitTextStrokeColor: effStrokeColor || '',
        webkitTextStrokeWidth: effStrokeWidth ? effStrokeWidth + 'px' : '',
        paintOrder: (effStrokeColor || effStrokeWidth) ? 'stroke fill' : '',
        boxShadow: cs.leftAccent ? `inset 3px 0 0 ${effAccentColor}` : '',
        textDecorationLine: cs.underline ? 'underline' : '',
        textDecorationColor: cs.underline ? effAccentColor : '',
      };

      if (col.id === '_role') {
        // タイプ列: インライン入力 + ホバー時「…」ボタン（デフォルト行は固定ラベル）
        if (isMetaRow) {
          const labelDiv = document.createElement('div');
          labelDiv.className = 'sn2-detail-cell-label';
          labelDiv.textContent = isTypeDefaultRow ? '（デフォルト）' : '（なし）';
          labelDiv.title = isTypeDefaultRow
            ? '新しく追加するタイプに適用される初期設定'
            : 'タイプが空欄の行に適用される設定';
          applyDynStyle(labelDiv, dynStyle);
          td.appendChild(labelDiv);
          const fmtBtn = document.createElement('button');
          fmtBtn.type = 'button'; fmtBtn.textContent = '…'; fmtBtn.title = '書式設定';
          fmtBtn.className = 'sn2-detail-cell-fmt-btn';
          fmtBtn.addEventListener('click', (e) => { e.stopPropagation(); this._showCellStylePopup(td, chara, col.id, panelContainer); });
          td.appendChild(fmtBtn);
          td.addEventListener('click', () => this._showCellStylePopup(td, chara, col.id, panelContainer));
          previewCells.push({ td, el: labelDiv, colId: col.id, isInput: false, isDefaultLabel: true });
        } else {
          const nameInput = document.createElement('input');
          nameInput.type = 'text';
          nameInput.value = chara.name || '';
          nameInput.placeholder = 'タイプ名';
          nameInput.className = 'sn2-detail-cell-input';
          nameInput.dataset.e2eId = 'scriptnote-detail-role-name-input-' + idx;
          nameInput.dataset.sn2DetailIndex = String(idx);
          applyDynStyle(nameInput, dynStyle);
          nameInput.addEventListener('change', () => {
            const oldName = chara.name;
            const newName = this._uniqueRoleName ? this._uniqueRoleName(nameInput.value, chara) : (nameInput.value.trim() || oldName || 'タイプ');
            nameInput.value = newName;
            if (newName === oldName) return;
            this._pushUndo('タイプ名変更');
            chara.name = newName;
            this._renameRoleInRows(oldName, chara.name);
            this._markDirty();
            const focusIdx = nameInput.dataset.sn2DetailIndex;
            this.renderDetailPanel(panelContainer);
            const restored = panelContainer.querySelector(`input[type="text"][data-sn2-detail-index="${focusIdx}"]`);
            if (restored) { restored.focus(); restored.setSelectionRange(restored.value.length, restored.value.length); }
          });
          nameInput.addEventListener('click', (e) => e.stopPropagation());
          nameInput.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
              e.preventDefault();
              const currentIdx = parseInt(nameInput.dataset.sn2DetailIndex, 10);
              const targetIdx = e.key === 'ArrowUp' ? currentIdx - 1 : currentIdx + 1;
              nameInput.dispatchEvent(new Event('change'));
              const target = panelContainer.querySelector(`input[type="text"][data-sn2-detail-index="${targetIdx}"]`);
              if (target) { target.focus(); target.select(); }
            }
          });
          td.appendChild(nameInput);
          // ホバー時に表示する「…」ボタン
          const fmtBtn = document.createElement('button');
          fmtBtn.type = 'button'; fmtBtn.textContent = '…'; fmtBtn.title = '書式設定';
          fmtBtn.className = 'sn2-detail-cell-fmt-btn';
          fmtBtn.addEventListener('click', (e) => { e.stopPropagation(); this._showCellStylePopup(td, chara, col.id, panelContainer); });
          td.appendChild(fmtBtn);
          previewCells.push({ td, el: nameInput, colId: col.id, isInput: true });
        }
      } else {
        const cellLabel = CELL_LABELS[col.id] !== undefined ? CELL_LABELS[col.id] : (col.label || col.id);
        // _text列: textStyle → charaフォールバック（エディタと一致）
        // _gutter/_gutter2: 列スタイルのみ（エディタではtextBefore/After/Align未使用）
        const ta = isText ? (cs.textAlign || chara.textAlign || 'center') : (cs.textAlign || 'center');
        const va = isText ? (cs.textValign || chara.textValign || '') : (cs.textValign || '');
        const tb = isText ? (cs.textBefore ?? chara.textBefore ?? '') : '';
        const taf = isText ? (cs.textAfter ?? chara.textAfter ?? '') : '';
        const toVal = isText ? (cs.textOverflow || chara.textOverflow || '') : (cs.textOverflow || '');
        const preview = document.createElement('div');
        preview.className = 'sn2-detail-cell-preview';
        const previewProps = { ...dynStyle };
        if (va) {
          previewProps.display = 'flex';
          previewProps.alignItems = va === 'top' ? 'flex-start' : va === 'bottom' ? 'flex-end' : 'center';
          previewProps.justifyContent = ta === 'left' ? 'flex-start' : ta === 'right' ? 'flex-end' : 'center';
        } else {
          previewProps.textAlign = ta;
          previewProps.lineHeight = '24px';
        }
        previewProps.whiteSpace = toVal === 'wrap' ? 'normal' : 'nowrap';
        applyDynStyle(preview, previewProps);
        preview.textContent = tb + (cellLabel || '') + taf;
        preview.title = `${chara.name || '見本'} - ${col.label}`;
        td.appendChild(preview);
        td.addEventListener('click', () => this._showCellStylePopup(td, chara, col.id, panelContainer));
        previewCells.push({ td, el: preview, colId: col.id, isInput: false });
      }
      item.appendChild(td);
    });

    // オプション設定セル —（なし）行にも表示（効果のない項目はポップアップ側で非表示）
    const infoTd = document.createElement('td');
    infoTd.className = 'sn2-detail-td-info';
    const optBtn = document.createElement('button');
    optBtn.className = 'gb-fmt-btn sn2-detail-opt-btn';
    optBtn.type = 'button';
    optBtn.textContent = 'オプション';
    optBtn.title = 'オプション設定';
    optBtn.dataset.e2eId = 'scriptnote-detail-role-options-' + idx;
    optBtn.dataset.sn2DetailIndex = String(idx);
    optBtn.addEventListener('click', () => this._showRoleOptionsPopup(optBtn, chara, panelContainer));
    const infoWrap = document.createElement('div');
    infoWrap.className = 'sn2-detail-opt-wrap';
    infoWrap.append(optBtn);
    infoTd.appendChild(infoWrap);
    item.appendChild(infoTd);

    // applyPreview参照を保持
    item._applyPreview = () => {
      previewCells.forEach(pc => {
        const ec = this._resolveCharaColors(chara, pc.colId);
        const cs = this._getColStyle(chara, pc.colId);
        const isText = pc.colId === '_text';
        const isRole = pc.colId === '_role';
        // 色: 列別 → resolveCharaColors → デフォルト
        const rawBg = cs.bgColor || ec.bgColor || '';
        const bgTrans = !rawBg || rawBg === 'transparent' || rawBg === 'rgba(0,0,0,0)';
        const bg = bgTrans ? _pageBg : rawBg;
        const fg = cs.textColor || ec.textColor || 'var(--fg)';
        // フォント: _text列は旧データ互換のcharaフォールバックを使う。_role列はタイプ列専用設定のみ使う。
        const fw = (isText ? (cs.fontWeight || chara.fontWeight) : cs.fontWeight) === 'bold' ? 'bold' : '';
        const fst = (isText ? (cs.fontStyle || chara.fontStyle) : cs.fontStyle) === 'italic' ? 'italic' : '';
        const fz = isText ? (cs.fontSize || chara.fontSize || '') : (cs.fontSize || '');
        const ff = isText ? (cs.fontFamily || chara.fontFamily || '') : (cs.fontFamily || '');
        const strokeColor = isText ? (cs.textStrokeColor || chara.textStrokeColor || '') : (cs.textStrokeColor || '');
        const strokeWidth = isText ? (cs.textStrokeWidth || chara.textStrokeWidth || '') : (cs.textStrokeWidth || '');
        const accentColor = cs.accentColor || chara.accentColor || fg || 'var(--accent)';
        const ta = isText ? (cs.textAlign || chara.textAlign || 'center') : (cs.textAlign || 'center');
        const va = isText ? (cs.textValign || chara.textValign || '') : (cs.textValign || '');
        const tb = isText ? (cs.textBefore ?? chara.textBefore ?? '') : '';
        const taf = isText ? (cs.textAfter ?? chara.textAfter ?? '') : '';
        const toVal = isText ? (cs.textOverflow || chara.textOverflow || '') : (cs.textOverflow || '');
        const nextProps = {
          background: bg, backgroundSize: '', backgroundPosition: '',
          color: fg,
          fontWeight: fw, fontStyle: fst,
          fontSize: fz ? fz + 'px' : '',
          fontFamily: ff || '',
          webkitTextStrokeColor: strokeColor || '',
          webkitTextStrokeWidth: strokeWidth ? strokeWidth + 'px' : '',
          paintOrder: (strokeColor || strokeWidth) ? 'stroke fill' : '',
          boxShadow: cs.leftAccent ? `inset 3px 0 0 ${accentColor}` : '',
          textDecorationLine: cs.underline ? 'underline' : '',
          textDecorationColor: cs.underline ? accentColor : '',
        };
        // テキスト前後・配置の反映（input以外）
        if (!pc.isInput) {
          if (va) {
            nextProps.display = 'flex';
            nextProps.alignItems = va === 'top' ? 'flex-start' : va === 'bottom' ? 'flex-end' : 'center';
            nextProps.justifyContent = ta === 'left' ? 'flex-start' : ta === 'right' ? 'flex-end' : 'center';
            nextProps.textAlign = '';
            nextProps.lineHeight = '';
          } else {
            nextProps.display = '';
            nextProps.alignItems = '';
            nextProps.justifyContent = '';
            nextProps.textAlign = ta;
            nextProps.lineHeight = '24px';
          }
          nextProps.whiteSpace = toVal === 'wrap' ? 'normal' : 'nowrap';
          if (!pc.isDefaultLabel) {
            const label = this._detailCellPreviewLabel(pc.colId) ?? (CELL_LABELS[pc.colId] !== undefined ? CELL_LABELS[pc.colId] : '');
            pc.el.textContent = tb + (label || '') + taf;
          }
        }
        Object.assign(pc.el.style, nextProps);
      });
    };

    return item;
  },

  _updateBulkBar(toolbar) {
    if (!toolbar) return;
    const count = this._detailSelection?.size || 0;
    const countEl = toolbar.querySelector('.sn2-detail-bulk-count');
    if (countEl) countEl.textContent = count > 0 ? `${count}件` : '';
    const hidden = count <= 0;
    const sep = toolbar.querySelector('.sn2-detail-bulk-sep');
    if (sep) sep.hidden = hidden;
    // 一括処理ボタンは複数選択時のみ表示
    toolbar.querySelectorAll('.sn2-detail-bulk-btn').forEach(btn => {
      btn.hidden = hidden;
    });
  },

  _detailMultiSelectionPositionAnchor(anchorEl, panelContainer) {
    if (!this._detailSelection || this._detailSelection.size <= 1) return null;
    const root = panelContainer || anchorEl?.closest?.('.sn2-detail') || document;
    const selectedRows = [...this._detailSelection]
      .map(idx => root.querySelector?.(`.sn2-detail-item[data-idx="${idx}"]`))
      .filter(Boolean);
    const rows = selectedRows.length
      ? selectedRows
      : Array.from(root.querySelectorAll?.('.sn2-detail-item.selected') || []);
    let bottomRect = null;
    rows.forEach((row) => {
      const rect = row.getBoundingClientRect?.();
      if (!rect || rect.width <= 0 || rect.height <= 0) return;
      if (!bottomRect || rect.bottom > bottomRect.bottom || (rect.bottom === bottomRect.bottom && rect.top > bottomRect.top)) {
        bottomRect = rect;
      }
    });
    if (!bottomRect) return null;
    const anchorRect = {
      left: bottomRect.left,
      right: bottomRect.right,
      top: bottomRect.bottom,
      bottom: bottomRect.bottom,
    };
    return { getBoundingClientRect: () => anchorRect };
  },

  _clearDetailAutoColorForManualColor(chara, prop) {
    if (!chara?.autoColor || (prop !== 'bgColor' && prop !== 'textColor')) return;
    const act = chara.autoColorTarget || 'bg';
    const targets = typeof act === 'object' ? Object.values(act) : [act];
    const hasBg = targets.some(v => v === 'bg' || v === 'both');
    const hasText = targets.some(v => v === 'text' || v === 'both');
    if (prop === 'bgColor' && hasBg) delete chara.autoColor;
    if (prop === 'textColor' && hasText) delete chara.autoColor;
  },

  _bulkColorChange(prop, panelContainer) {
    // 一括色変更のトリガー元ボタンを探す
    const toolbar = this._detailBulkBar;
    const anchor = toolbar?.querySelector(`.sn2-detail-bulk-btn`) || toolbar;
    if (typeof openColorPalette === 'function' && anchor) {
      openColorPalette(anchor, '#4a90d9', (color) => {
        this._pushUndo('一括色変更');
        this._detailSelection.forEach(idx => {
          const chara = this.doc.characters[idx];
          if (chara) {
            chara[prop] = color;
            this._clearDetailAutoColorForManualColor(chara, prop);
          }
        });
        this._refreshRowStyles();
        this._markDirty();
        this.renderDetailPanel(panelContainer);
      });
    } else {
      const input = document.createElement('input');
      input.type = 'color';
      input.value = '#4a90d9';
      input.className = 'sn2-hidden-color-input';
      document.body.appendChild(input);
      const cleanup = () => { if (input.parentNode) input.remove(); };
      input.addEventListener('input', () => {
        this._pushUndo('一括色変更');
        this._detailSelection.forEach(idx => {
          const chara = this.doc.characters[idx];
          if (chara) {
            chara[prop] = input.value;
            this._clearDetailAutoColorForManualColor(chara, prop);
          }
        });
        this._refreshRowStyles();
        this._markDirty();
      });
      input.addEventListener('change', () => { cleanup(); this.renderDetailPanel(panelContainer); });
      input.addEventListener('blur', () => setTimeout(cleanup, 100));
      input.click();
    }
  },

  _showBulkEditPopup(panelContainer) {
    if (!this._detailSelection?.size) return;
    const toolbar = this._detailBulkBar;
    const anchor = toolbar?.querySelector('.sn2-detail-bulk-btn:last-child') || toolbar;
    document.querySelectorAll('.gb-fmt-popup--bulk-edit').forEach(el => el.remove());
    const popup = document.createElement('div');
    popup.className = 'gb-fmt-popup gb-fmt-popup--bulk-edit';
    const e = typeof esc === 'function' ? esc : (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    popup.innerHTML = `
      <div class="sn2-bulk-title">一括設定（${this._detailSelection.size}件）</div>
      <div class="sn2-bulk-body">
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="bgColor"> 背景色</label>
          <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg" data-bulk-color="bgColor"></button>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="textColor"> 文字色</label>
          <button type="button" class="gb-fmt-swatch gb-fmt-swatch-fg" data-bulk-color="textColor">T</button>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="fontWeight"> 太字</label>
          <select class="sn2-bulk-sel" data-bulk-val="fontWeight">
            <option value="">通常</option><option value="bold">太字</option>
          </select>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="fontStyle"> 斜体</label>
          <select class="sn2-bulk-sel" data-bulk-val="fontStyle">
            <option value="">通常</option><option value="italic">斜体</option>
          </select>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="fontSize"> サイズ</label>
          <input type="number" class="sn2-bulk-input-num" data-bulk-val="fontSize" value="" placeholder="14" min="8" max="48">
          <span class="sn2-role-opts-unit">px</span>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="kind"> 種別</label>
          <select class="sn2-bulk-sel" data-bulk-val="kind">
            <option value="dialogue">台詞</option><option value="action">ト書き</option><option value="heading">見出し</option><option value="break">区切り</option><option value="summary">プロット</option>
          </select>
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="textBefore"> テキスト前</label>
          <input type="text" class="sn2-bulk-input-text" data-bulk-val="textBefore" value="" placeholder="例: 「">
        </div>
        <div class="sn2-bulk-row">
          <label><input type="checkbox" data-bulk-check="textAfter"> テキスト後</label>
          <input type="text" class="sn2-bulk-input-text" data-bulk-val="textAfter" value="" placeholder="例: 」">
        </div>
        <div class="sn2-bulk-section-divider">
          <div class="sn2-bulk-section-title">テキスト列書式</div>
          <div class="sn2-bulk-row">
            <label><input type="checkbox" data-bulk-check="ts_bgColor"> 背景</label>
            <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg" data-bulk-color="ts_bgColor"></button>
            <label><input type="checkbox" data-bulk-check="ts_textColor"> 文字</label>
            <button type="button" class="gb-fmt-swatch gb-fmt-swatch-fg" data-bulk-color="ts_textColor">T</button>
            <label><input type="checkbox" data-bulk-check="ts_fontSize"> サイズ</label>
            <input type="number" class="sn2-bulk-input-num sn2-bulk-input-num--sm" data-bulk-val="ts_fontSize" value="" placeholder="14" min="8" max="48">
          </div>
        </div>
        <div class="sn2-bulk-apply-row">
          <button type="button" class="sn2-detail-add-btn" data-bulk-apply>適用</button>
        </div>
        </div>`;
    let closeHandler = null;
    let keyHandler = null;
    const closePopup = (restoreFocus = false) => {
      popup.remove();
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (keyHandler) {
        document.removeEventListener('keydown', keyHandler, true);
        keyHandler = null;
      }
      if (restoreFocus && typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchor);
    };
    const bulkValues = {};
    const isEmptyBulkValue = (value) => value === '' || value === null || value === undefined
      || (typeof value === 'number' && !Number.isFinite(value));
    const setBulkValue = (target, prop, value) => {
      if (!target) return;
      if (isEmptyBulkValue(value)) delete target[prop];
      else target[prop] = value;
    };
    const cleanupTextStyle = (chara) => {
      if (chara?.textStyle && !Object.keys(chara.textStyle).length) delete chara.textStyle;
    };
    const mirrorToTextStyle = new Set(['bgColor', 'textColor', 'fontWeight', 'fontStyle', 'fontSize', 'textBefore', 'textAfter']);
    // カラーピッカー（直接openColorPaletteを使用。適用前なので_refreshRowStylesは呼ばない）
    popup.querySelectorAll('[data-bulk-color]').forEach(btn => {
      btn.addEventListener('click', () => {
        const prop = btn.dataset.bulkColor;
        const cb = popup.querySelector(`[data-bulk-check="${prop}"]`);
        if (cb) cb.checked = true;
        if (typeof openColorPalette === 'function') {
          openColorPalette(btn, bulkValues[prop] || '', (color) => {
            bulkValues[prop] = color;
            if (prop === 'bgColor' || prop === 'ts_bgColor') Object.assign(btn.style, { background: color });
            if (prop === 'textColor' || prop === 'ts_textColor') Object.assign(btn.style, { color: color });
          });
        }
      });
    });
    // 適用ボタン
    popup.querySelector('[data-bulk-apply]')?.addEventListener('click', () => {
      this._pushUndo('一括設定適用');
      popup.querySelectorAll('[data-bulk-check]').forEach(cb => {
        if (!cb.checked) return;
        const prop = cb.dataset.bulkCheck;
        const colorBtn = popup.querySelector(`[data-bulk-color="${prop}"]`);
        const valEl = popup.querySelector(`[data-bulk-val="${prop}"]`);
        let val;
        if (colorBtn) {
          val = bulkValues[prop] || '';
        } else if (valEl) {
          val = valEl.type === 'number' ? (valEl.value ? Number(valEl.value) : null) : valEl.value;
        }
        // ts_*プレフィックスのプロパティはtextStyleに書き込む
        const isTs = prop.startsWith('ts_');
        const realProp = isTs ? prop.slice(3) : prop;
        this._detailSelection.forEach(idx => {
          const chara = this.doc.characters[idx];
          if (!chara) return;
          // デフォルトタイプは kind 変更のみ対象外（常に 'none' 固定）
          if (chara.isDefault && realProp === 'kind') return;
          if (isTs) {
            if (!chara.textStyle && !isEmptyBulkValue(val)) chara.textStyle = {};
            if (chara.textStyle) {
              setBulkValue(chara.textStyle, realProp, val);
              cleanupTextStyle(chara);
            }
          } else if (realProp === 'kind') {
            chara.kind = val;
            chara.isBreak = val === 'break';
            chara.isSummary = val === 'summary';
            this._calcCache = null;
          } else {
            setBulkValue(chara, realProp, val);
            if (mirrorToTextStyle.has(realProp)) {
              if (!chara.textStyle && !isEmptyBulkValue(val)) chara.textStyle = {};
              if (chara.textStyle) {
                setBulkValue(chara.textStyle, realProp, val);
                cleanupTextStyle(chara);
              }
            }
          }
        });
      });
      this._refreshRowStyles();
      this._markDirty();
      this._render(); // kind変更等をDOMに反映
      this.renderDetailPanel(panelContainer);
      closePopup();
    });
    document.body.appendChild(popup);
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchor,
        close: () => closePopup(true),
      });
    }
    const positionAnchor = this._detailMultiSelectionPositionAnchor(anchor, panelContainer) || anchor;
    if (typeof positionPopup === 'function') positionPopup(popup, positionAnchor.getBoundingClientRect());
    else if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
    keyHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closePopup(true);
    };
    document.addEventListener('keydown', keyHandler, true);
    setTimeout(() => {
      closeHandler = (ev) => {
        if (!popup.contains(ev.target) && !ev.target.closest?.('.gb-fmt-popup') && !ev.target.closest?.('.gb-palette-popup')) {
          closePopup();
        }
      };
      if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

  // DB読み込みモーダル
  async _showDbImportModal(panelContainer) {
    let overlay = null;
    let closeModal = () => { if (overlay) overlay.remove(); };
    try {
      const roots = await apiFetch('/outliner-roots');
      if (!Array.isArray(roots) || !roots.length) { showStatus('フォルダツリーがありません', true); return; }
      overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      overlay.innerHTML = `<div class="modal sn2-db-import-modal">
        <h3>DBからキャラ読み込み</h3>
        <div class="modal-body sn2-db-import-body">
          <div id="sn2-db-tree" class="sn2-db-import-tree"></div>
        </div>
        <div id="sn2-db-selected" class="sn2-db-import-selected">選択: 0件</div>
        <div class="btn-row">
          <button type="button" class="btn" id="sn2-db-cancel">キャンセル</button>
          <button type="button" class="primary" id="sn2-db-ok">読み込み</button>
        </div>
      </div>`;
      document.body.appendChild(overlay);
      window.GBModalShell?.enhanceOverlay?.(overlay);
      let keyHandler = null;
      closeModal = () => {
        if (keyHandler) { document.removeEventListener('keydown', keyHandler, true); keyHandler = null; }
        if (overlay?.isConnected) overlay.remove();
      };
      keyHandler = (ev) => {
        if (ev.key !== 'Escape') return;
        ev.preventDefault();
        closeModal();
      };
      document.addEventListener('keydown', keyHandler, true);
      const treeHost = overlay.querySelector('#sn2-db-tree');
      const selectedNames = new Set();
      const isCharacterDbFolder = (item) => /キャラ|キャラクター|登場人物|人物|character|chara|cast/i.test(String(item?.name || item?.path || ''));
      const visited = new Set();
      const addPageGroup = (folder, pages) => {
        const groupEl = document.createElement('div');
        groupEl.className = 'sn2-db-import-group';
        const groupLabel = document.createElement('div');
        groupLabel.className = 'sn2-db-import-group-label';
        groupLabel.textContent = folder.name || folder.path;
        groupEl.appendChild(groupLabel);
        pages.forEach(p => {
          const label = document.createElement('label');
          label.className = 'sn2-db-import-item';
          const cb = document.createElement('input');
          cb.type = 'checkbox';
          cb.addEventListener('change', () => {
            if (cb.checked) selectedNames.add(p.name); else selectedNames.delete(p.name);
            overlay.querySelector('#sn2-db-selected').textContent = `選択: ${selectedNames.size}件`;
          });
          label.appendChild(cb);
          label.appendChild(document.createTextNode(p.name || p.path));
          groupEl.appendChild(label);
        });
        treeHost.appendChild(groupEl);
      };
      const scanFolder = async (folder, depth = 0) => {
        const path = String(folder?.path || '');
        if (!path || visited.has(path) || depth > 4) return;
        visited.add(path);
        const entries = await apiFetch('/browse?path=' + encodeURIComponent(path) + '&all_files=true').catch(() => []);
        if ((folder.type === 'database' || folder.type === 'folder') && isCharacterDbFolder(folder)) {
          const pages = (entries || []).filter(it => it.type === 'page' || it.type === 'entity');
          if (pages.length) addPageGroup(folder, pages);
        }
        const childFolders = (entries || []).filter(it => it.type === 'folder' || it.type === 'database');
        for (const child of childFolders) await scanFolder(child, depth + 1);
      };
      // DBツリーを構築: ルート配下を再帰走査し、キャラ/登場人物系のシートだけを候補にする
      for (const root of roots) {
        const items = await apiFetch('/browse?path=' + encodeURIComponent(root.path) + '&all_files=true').catch(() => []);
        const dbFolders = (items || []).filter(it => it.type === 'folder' || it.type === 'database');
        for (const folder of dbFolders) await scanFolder(folder, 0);
      }
      if (!treeHost.children.length) {
        const empty = document.createElement('div');
        empty.className = 'sn2-db-import-empty';
        empty.textContent = 'キャラ用のシートが見つかりませんでした';
        treeHost.appendChild(empty);
      }
      overlay.querySelector('#sn2-db-cancel').addEventListener('click', () => closeModal());
      overlay.querySelector('#sn2-db-ok').addEventListener('click', () => {
        const roleAdapter = this._roleManagementAdapter();
        this._pushUndo('DBインポート');
        selectedNames.forEach(name => {
          if (!roleAdapter.characters.some(character => character.name === name)) roleAdapter.addCharacter(name);
        });
        this._detailCharacterSelection?.clear();
        roleAdapter.touch();
        this.renderDetailPanel(panelContainer);
        closeModal();
      });
      overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(); });
    } catch (err) {
      closeModal();
      if (typeof showStatus === 'function') showStatus('DB読み込みエラー: ' + err.message, true);
    }
  },

  _showColorPicker(anchorEl, chara, prop, panelContainer) {
    const current = chara[prop] || '';
    // 透明背景のチェック柄
    const CHECKER = {
      backgroundImage: 'linear-gradient(45deg,#666 25%,transparent 25%,transparent 75%,#666 75%),linear-gradient(45deg,#666 25%,transparent 25%,transparent 75%,#666 75%)',
      backgroundSize: '6px 6px',
      backgroundPosition: '0 0,3px 3px',
    };
    if (typeof openColorPalette === 'function') {
      openColorPalette(anchorEl, current, (color) => {
        this._pushUndo('タイプ色変更');
        // 「透明」選択 = 色設定をクリア（他の設定にフォールバック）
        if (color === 'transparent') {
          delete chara[prop];
        } else {
          chara[prop] = color;
          // 手動で色を変更した場合はautoColorをクリア（手動設定を優先）
          this._clearDetailAutoColorForManualColor(chara, prop);
        }
        if (prop === 'bgColor') {
          if (chara[prop]) Object.assign(anchorEl.style, { background: chara[prop], backgroundSize: '', backgroundPosition: '' });
          else Object.assign(anchorEl.style, { background: '', ...CHECKER });
        }
        if (prop === 'textColor') {
          Object.assign(anchorEl.style, { color: chara[prop] || 'var(--fg)', textDecorationColor: chara[prop] || '' });
        }
        this._refreshRowStyles();
        this._markDirty();
        // 詳細パネルのプレビューも更新
        const item = anchorEl.closest('.sn2-detail-item');
        if (item?._applyPreview) item._applyPreview();
      });
    } else {
      // フォールバック: ネイティブカラーピッカー
      const input = document.createElement('input');
      input.type = 'color';
      input.value = current || '#4a90d9';
      input.className = 'sn2-hidden-color-input';
      document.body.appendChild(input);
      const cleanup = () => { if (input.parentNode) input.remove(); };
      input.addEventListener('input', () => {
        this._pushUndo('タイプ色変更');
        chara[prop] = input.value;
        this._clearDetailAutoColorForManualColor(chara, prop);
        if (prop === 'bgColor') Object.assign(anchorEl.style, { background: input.value });
        if (prop === 'textColor') Object.assign(anchorEl.style, { color: input.value });
        this._refreshRowStyles();
        this._markDirty();
      });
      input.addEventListener('change', cleanup);
      input.addEventListener('blur', () => setTimeout(cleanup, 100));
      input.click();
    }
  },

  // 列IDに対応するスタイルオブジェクトを取得/作成
  _getColStyle(chara, colId) {
    if (colId === '_text') { if (!chara.textStyle) chara.textStyle = {}; return chara.textStyle; }
    if (colId === '_gutter') { if (!chara.gutterStyle) chara.gutterStyle = {}; return chara.gutterStyle; }
    if (colId === '_gutter2') { if (!chara.gutter2Style) chara.gutter2Style = {}; return chara.gutter2Style; }
    if (colId === '_role') { if (!chara.roleStyle) chara.roleStyle = {}; return chara.roleStyle; }
    // カスタム列
    if (!chara.customStyles) chara.customStyles = {};
    if (!chara.customStyles[colId]) chara.customStyles[colId] = {};
    return chara.customStyles[colId];
  },

  _countConfigPrefixForColumn(colId) {
    if (colId === '_gutter') return 'primary';
    if (colId === '_gutter2') return 'secondary';
    return '';
  },

  _countConfigLabelForPrefix(prefix) {
    return prefix === 'primary' ? '大区切り' : '小区切り';
  },

  _countConfigDefaultLabel(prefix) {
    const def = this._getCountDef ? this._getCountDef() : {};
    return prefix === 'primary' ? (def.primaryLabel || 'p') : (def.secondaryLabel || 'コマ');
  },

  _countConfigFieldValues(prefix) {
    const cc = this.doc?.editor?.countConfig || {};
    const unit = cc[prefix + 'Label'] ?? this._countConfigDefaultLabel(prefix);
    const pad = Math.max(0, Math.min(5, Number(cc[prefix + 'Pad'] ?? cc.padDigits ?? 2) || 0));
    const pos = ['before', 'after', 'both'].includes(cc[prefix + 'Pos']) ? cc[prefix + 'Pos'] : (cc.labelPosition || 'before');
    const labelBeforeRaw = cc[prefix + 'LabelBefore'];
    const labelAfterRaw = cc[prefix + 'LabelAfter'];
    return {
      unit,
      pad,
      pos: ['before', 'after', 'both'].includes(pos) ? pos : 'before',
      labelBefore: labelBeforeRaw == null ? unit : labelBeforeRaw,
      labelAfter: labelAfterRaw == null ? unit : labelAfterRaw,
    };
  },

  _detailCellPreviewLabel(colId) {
    const prefix = this._countConfigPrefixForColumn(colId);
    if (prefix) {
      const values = this._countConfigFieldValues(prefix);
      return this._fmtCount(values.unit, 1, {
        pad: values.pad,
        pos: values.pos,
        labelBefore: values.labelBefore,
        labelAfter: values.labelAfter,
      });
    }
    if (colId === '_role') return null;
    if (colId === '_text') return 'テキスト列';
    return '';
  },

  _refreshDetailCountPreviews(panelContainer) {
    const root = panelContainer || document;
    root.querySelectorAll?.('.sn2-detail-item').forEach((item) => {
      if (item?._applyPreview) item._applyPreview();
    });
  },

  _applyCountConfigFormatSetting(key, value, panelContainer) {
    if (!key) return;
    if (!this.doc.editor) this.doc.editor = {};
    this._pushUndo('区切り表示設定変更');
    // undo スナップショット直列化では空の countConfig が整理されるため、取得直前に作る。
    if (!this.doc.editor.countConfig) this.doc.editor.countConfig = {};
    const cc = this.doc.editor.countConfig;
    if (key.endsWith('Pad')) {
      const parsed = Number(value);
      cc[key] = Math.max(0, Math.min(5, Number.isFinite(parsed) ? Math.round(parsed) : 0));
    } else if (key.endsWith('Pos')) {
      cc[key] = ['before', 'after', 'both'].includes(value) ? value : 'before';
      if (cc[key] === 'both') {
        const prefix = key.slice(0, -3);
        const unitVal = cc[prefix + 'Label'] ?? this._countConfigDefaultLabel(prefix);
        if (cc[prefix + 'LabelBefore'] == null) cc[prefix + 'LabelBefore'] = unitVal;
        if (cc[prefix + 'LabelAfter'] == null) cc[prefix + 'LabelAfter'] = unitVal;
      }
    } else {
      cc[key] = String(value == null ? '' : value).trim();
    }
    this._calcCache = null;
    this._updateGuttersFrom(0);
    this._render();
    this._markDirty();
    this._refreshDetailCountPreviews(panelContainer);
  },

  _buildCountConfigFormatControls(colId, panelContainer) {
    const prefix = this._countConfigPrefixForColumn(colId);
    if (!prefix || typeof gbFmt === 'undefined') return [];
    const label = this._countConfigLabelForPrefix(prefix);
    const values = this._countConfigFieldValues(prefix);
    const unitKey = prefix + 'Label';
    const padKey = prefix + 'Pad';
    const posKey = prefix + 'Pos';
    const beforeKey = prefix + 'LabelBefore';
    const afterKey = prefix + 'LabelAfter';
    const update = (key, value) => this._applyCountConfigFormatSetting(key, value, panelContainer);

    const unitInput = gbFmt.makeTextInput({
      value: values.unit,
      placeholder: this._countConfigDefaultLabel(prefix),
      title: label + 'の単位',
      width: 54,
      onChange: (v) => update(unitKey, v),
    });
    unitInput.dataset.e2eId = `scriptnote-format-${prefix}-label`;
    const padInput = gbFmt.makeNumInput({
      title: label + 'の桁',
      value: values.pad,
      min: 0,
      max: 5,
      width: 44,
      placeholder: '桁',
      allowEmpty: false,
      onChange: (v) => update(padKey, v),
    });
    padInput.dataset.e2eId = `scriptnote-format-${prefix}-pad`;
    const posSelect = gbFmt.makeSelect({
      value: values.pos,
      opts: [
        { v: 'before', l: '単位+数' },
        { v: 'after', l: '数+単位' },
        { v: 'both', l: '前+数+後' },
      ],
      onChange: (v) => {
        update(posKey, v);
        syncBothControls();
      },
    });
    posSelect.title = label + 'の表示位置';
    posSelect.dataset.e2eId = `scriptnote-format-${prefix}-position`;

    const beforeInput = gbFmt.makeTextInput({
      value: values.labelBefore,
      placeholder: '前',
      title: label + 'の前の単位',
      width: 36,
      onChange: (v) => update(beforeKey, v),
    });
    beforeInput.dataset.e2eId = `scriptnote-format-${prefix}-label-before`;
    const afterInput = gbFmt.makeTextInput({
      value: values.labelAfter,
      placeholder: '後',
      title: label + 'の後の単位',
      width: 36,
      onChange: (v) => update(afterKey, v),
    });
    afterInput.dataset.e2eId = `scriptnote-format-${prefix}-label-after`;
    const beforeGroup = gbFmt.makeGroup([gbFmt.makeLabel('前'), beforeInput]);
    const afterGroup = gbFmt.makeGroup([gbFmt.makeLabel('後'), afterInput]);
    const syncBothControls = () => {
      const hidden = posSelect.value !== 'both';
      beforeGroup.hidden = hidden;
      afterGroup.hidden = hidden;
      if (!hidden) {
        const latest = this._countConfigFieldValues(prefix);
        beforeInput.value = latest.labelBefore;
        afterInput.value = latest.labelAfter;
      }
    };
    syncBothControls();

    return [
      gbFmt.makeGroup([gbFmt.makeLabel(label, 'gb-fmt-label--group')]),
      gbFmt.makeGroup([gbFmt.makeLabel('単位'), unitInput]),
      gbFmt.makeGroup([gbFmt.makeLabel('桁'), padInput]),
      gbFmt.makeGroup([gbFmt.makeLabel('位置'), posSelect]),
      beforeGroup,
      afterGroup,
    ];
  },

  // セルスタイルポップアップ（列別スタイル編集）— openFormatPopup 経由
  _showCellStylePopup(anchorEl, chara, colId, panelContainer, options = {}) {
    if (typeof openFormatPopup !== 'function') return;
    const style = this._getColStyle(chara, colId);
    const isTextCol = colId === '_text';
    const isRoleCol = colId === '_role';
    const isTypeOverride = options.typeOverride === true;
    const inheritedStyle = options.inheritedStyle && typeof options.inheritedStyle === 'object'
      ? options.inheritedStyle
      : {};
    const scopedValue = (key, fallback = '') => {
      if (!isTypeOverride) return fallback;
      return Object.prototype.hasOwnProperty.call(style, key) ? style[key] : (inheritedStyle[key] ?? fallback);
    };
    const needsLegacySync = isTextCol;
    const fields = [
      'textColor', 'fontSize', 'fontFamily',
      'bold', 'italic', 'textStrokeColor', 'textStrokeWidth',
      'bgColor', 'leftAccent', 'underline', 'accentColor',
      ...(!isTypeOverride ? [...(isTextCol ? ['textBefore', 'textAfter'] : []), 'textAlign', 'textValign', 'textOverflow'] : []),
    ];
    const refreshItem = () => { const item = anchorEl.closest('.sn2-detail-item'); if (item?._applyPreview) item._applyPreview(); };
    const ec = this._resolveCharaColors(chara, colId) || {};
    const pick = (primary, fallback) => (primary != null && primary !== '' ? primary : fallback);
    const values = {
      // bgColor: 背景色は計画書 §2-2「未設定時はチェック柄表示」方針に従い fallback なし
      bgColor: isTypeOverride ? scopedValue('bgColor') : (style.bgColor || ''),
      // textColor: T アイコンの色はタイプ色（ec）で表示するため fallback あり
      textColor: isTypeOverride ? scopedValue('textColor') : (style.textColor || ec.textColor || ''),
      fontWeight: isTypeOverride ? scopedValue('fontWeight') : (needsLegacySync ? pick(style.fontWeight, chara.fontWeight || '') : (style.fontWeight || '')),
      fontStyle: isTypeOverride ? scopedValue('fontStyle') : (needsLegacySync ? pick(style.fontStyle, chara.fontStyle || '') : (style.fontStyle || '')),
      fontSize: isTypeOverride ? scopedValue('fontSize') : (needsLegacySync ? pick(style.fontSize, chara.fontSize || '') : (style.fontSize || '')),
      fontFamily: isTypeOverride ? scopedValue('fontFamily') : (needsLegacySync ? pick(style.fontFamily, chara.fontFamily || '') : (style.fontFamily || '')),
      textStrokeColor: isTypeOverride ? scopedValue('textStrokeColor') : (needsLegacySync ? pick(style.textStrokeColor, chara.textStrokeColor || '') : (style.textStrokeColor || '')),
      textStrokeWidth: isTypeOverride ? scopedValue('textStrokeWidth') : (needsLegacySync ? pick(style.textStrokeWidth, chara.textStrokeWidth || '') : (style.textStrokeWidth || '')),
      leftAccent: isTypeOverride ? !!scopedValue('leftAccent', false) : !!style.leftAccent,
      underline: isTypeOverride ? !!scopedValue('underline', false) : !!style.underline,
      accentColor: isTypeOverride ? scopedValue('accentColor') : (style.accentColor || chara.accentColor || ''),
      textBefore: isTextCol ? (style.textBefore ?? chara.textBefore ?? '') : (style.textBefore ?? ''),
      textAfter: isTextCol ? (style.textAfter ?? chara.textAfter ?? '') : (style.textAfter ?? ''),
      textAlign: isTextCol ? (style.textAlign || chara.textAlign || '') : (style.textAlign ?? ''),
      textValign: isTextCol ? (style.textValign || chara.textValign || '') : (style.textValign ?? ''),
      textOverflow: isTextCol ? (style.textOverflow || chara.textOverflow || '') : (style.textOverflow ?? ''),
    };
    const clearAutoColorFor = (prop) => {
      if (!isRoleCol || !chara.autoColor) return;
      const act = chara.autoColorTarget || 'none';
      const actValues = typeof act === 'object' ? Object.values(act) : [act];
      const hasBg = actValues.some((v) => v === 'bg' || v === 'both');
      const hasText = actValues.some((v) => v === 'text' || v === 'both');
      if (prop === 'bgColor' && hasBg) delete chara.autoColor;
      if (prop === 'textColor' && hasText) delete chara.autoColor;
    };
    const UNDO_LABELS = {
      bgColor: 'タイプ色変更', textColor: 'タイプ色変更',
      fontWeight: 'タイプ書式変更', fontStyle: 'タイプ書式変更',
      fontSize: 'タイプサイズ変更', fontFamily: 'タイプフォント変更',
      textStrokeColor: 'タイプ装飾変更', textStrokeWidth: 'タイプ装飾変更',
      leftAccent: 'タイプ装飾変更', underline: 'タイプ装飾変更', accentColor: 'タイプ装飾変更',
      textBefore: 'タイプ設定変更', textAfter: 'タイプ設定変更',
      textAlign: 'タイプ配置変更', textValign: 'タイプ配置変更', textOverflow: 'タイプ配置変更',
    };
    const liveValues = { ...values };
    const STYLE_COPY_PROPS = [
      'bgColor', 'textColor', 'fontWeight', 'fontStyle', 'fontSize', 'fontFamily',
      'textStrokeColor', 'textStrokeWidth', 'leftAccent', 'underline', 'accentColor',
      ...(!isTypeOverride ? [...(isTextCol ? ['textBefore', 'textAfter'] : []), 'textAlign', 'textValign', 'textOverflow'] : []),
    ];
    const handleChange = (prop, value) => {
        liveValues[prop] = value;
        this._pushUndo(UNDO_LABELS[prop] || 'タイプ書式変更');
        if (isTypeOverride) {
          if (prop === 'leftAccent' || prop === 'underline') style[prop] = !!value;
          else if (value === '' || value === null || value === undefined) style[prop] = null;
          else style[prop] = value;
          this._render();
          this._markDirty();
          return;
        }
        if (prop === 'bgColor' || prop === 'textColor') {
          if (value === '' || value == null) delete style[prop];
          else style[prop] = value;
          clearAutoColorFor(prop);
        } else if (prop === 'fontWeight' || prop === 'fontStyle') {
          if (!value) {
            delete style[prop];
            if (needsLegacySync) delete chara[prop];
          } else {
            style[prop] = value;
          }
        } else if (prop === 'fontSize') {
          if (value == null) {
            style.fontSize = null;
            if (needsLegacySync) chara.fontSize = null;
          } else {
            style.fontSize = value;
          }
        } else if (prop === 'fontFamily') {
          if (!value) {
            delete style.fontFamily;
            if (needsLegacySync) delete chara.fontFamily;
          } else {
            style.fontFamily = value;
          }
        } else if (prop === 'textStrokeWidth') {
          if (value == null) {
            delete style.textStrokeWidth;
            if (needsLegacySync) delete chara.textStrokeWidth;
          } else {
            style.textStrokeWidth = value;
          }
        } else if (prop === 'textStrokeColor' || prop === 'accentColor') {
          if (value === '' || value == null) delete style[prop];
          else style[prop] = value;
        } else if (prop === 'leftAccent' || prop === 'underline') {
          if (value) style[prop] = true;
          else delete style[prop];
        } else {
          style[prop] = value;
        }
        const needRender = (prop === 'textAlign' || prop === 'textValign' || prop === 'textOverflow');
        if (needRender) this._render();
        else this._refreshRowStyles();
        this._markDirty();
        refreshItem();
    };
    // 書式貼り付け: コピーした書式を1回のUndo単位でまとめて適用し、表示更新のため開き直す
    const applyCopiedStyle = (clip, props) => {
      const entries = (props || []).filter((p) => Object.prototype.hasOwnProperty.call(clip, p));
      if (!entries.length) return;
      this._pushUndo('書式貼り付け');
      const prevSuppressed = this._pushUndoSuppressed;
      this._pushUndoSuppressed = true;
      try {
        entries.forEach((p) => {
          let v = clip[p];
          if (v === '' && (p === 'fontSize' || p === 'textStrokeWidth')) v = null;
          handleChange(p, v);
        });
      } finally {
        this._pushUndoSuppressed = prevSuppressed;
      }
      this._showCellStylePopup(anchorEl, chara, colId, panelContainer, options);
    };
    openFormatPopup(anchorEl, {
      values,
      fields,
      verticalWriting: this.doc.editor?.viewMode === 'vertical',
      className: 'gb-fmt-popup--cell-style' + (isTypeOverride ? ' gb-fmt-popup--type-gutter-style' : ''),
      positionAnchor: this._detailMultiSelectionPositionAnchor(anchorEl, panelContainer),
      extraRow2: options.includeCountConfig === false ? [] : this._buildCountConfigFormatControls(colId, panelContainer),
      extraRow4: this._buildStyleCopyPasteControls(() => liveValues, applyCopiedStyle, STYLE_COPY_PROPS),
      onChange: handleChange,
      onReset: () => {
        this._pushUndo('書式リセット');
        ['bgColor','textColor','fontWeight','fontStyle','fontSize','fontFamily','textStrokeColor','textStrokeWidth','leftAccent','underline','accentColor','textBefore','textAfter','textAlign','textValign','textOverflow'].forEach((p) => delete style[p]);
        if (needsLegacySync) {
          ['fontWeight', 'fontStyle', 'fontSize', 'fontFamily', 'textStrokeColor', 'textStrokeWidth'].forEach((p) => { delete chara[p]; });
        }
        if (!chara.isDefault && isRoleCol) this._reapplyAutoColor(chara);
        this._refreshRowStyles();
        this._render();
        this._markDirty();
        refreshItem();
      },
    });
  },
  // 書式コピー/貼り付けボタン（セル書式・列一括ポップアップ共通）
  // getValues(): 現在表示中の書式値を返す / applyValues(clip, props): コピー値を適用する
  _buildStyleCopyPasteControls(getValues, applyValues, props) {
    const mk = (label, title, e2eId) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'gb-fmt-style-copy';
      b.textContent = label;
      b.title = title;
      b.dataset.e2eId = e2eId;
      return b;
    };
    const copyBtn = mk('コピー', '表示中の書式をコピー', 'scriptnote-style-copy');
    const pasteBtn = mk('貼り付け', 'コピーした書式を貼り付け', 'scriptnote-style-paste');
    const getClipboard = () => (typeof ScriptNoteEditor !== 'undefined' && ScriptNoteEditor._copiedCellStyle) || null;
    pasteBtn.disabled = !getClipboard();
    copyBtn.addEventListener('click', () => {
      const values = getValues() || {};
      const copied = {};
      (props || []).forEach((p) => { copied[p] = values[p] ?? ''; });
      ScriptNoteEditor._copiedCellStyle = copied;
      pasteBtn.disabled = false;
      if (typeof showStatus === 'function') showStatus('書式をコピーしました');
    });
    pasteBtn.addEventListener('click', () => {
      const clip = getClipboard();
      if (!clip) return;
      applyValues(clip, props || []);
    });
    return [copyBtn, pasteBtn];
  },

  // 列ヘッダー一括設定ポップアップ — openFormatPopup 経由
  _showColBulkPopup(anchorEl, colId, panelContainer) {
    if (typeof openFormatPopup !== 'function') return;
    if (!this.doc.editor) this.doc.editor = {};
    if (!this.doc.editor.columnAllRules) this.doc.editor.columnAllRules = {};
    let applyAll = !!this.doc.editor.columnAllRules[colId];
    const rule0 = this.doc.editor.columnAllRules[colId] || {};
    const getTargets = () => {
      if (applyAll) return this.doc.characters.map((_, i) => i);
      return this._detailSelection?.size ? [...this._detailSelection] : this.doc.characters.map((_, i) => i);
    };
    const applyChanges = (changes, opts = {}) => {
      this._pushUndo('タイプ一括変更');
      const targets = getTargets();
      targets.forEach((i) => {
        const c = this.doc.characters[i];
        if (!c) return;
        const s = this._getColStyle(c, colId);
        Object.entries(changes).forEach(([prop, val]) => {
          if (val === '' || val === null || val === undefined) delete s[prop];
          else s[prop] = val;
        });
      });
      if (applyAll) {
        // undo スナップショット直列化では空の columnAllRules が整理されるため、取得直前に作り直す
        if (!this.doc.editor.columnAllRules) this.doc.editor.columnAllRules = {};
        const rule = this.doc.editor.columnAllRules[colId] = this.doc.editor.columnAllRules[colId] || {};
        Object.entries(changes).forEach(([prop, val]) => {
          if (val === '' || val === null || val === undefined) delete rule[prop];
          else rule[prop] = val;
        });
      }
      if (opts.fullRender) this._render();
      else this._refreshRowStyles();
      this._markDirty();
      this.renderDetailPanel(panelContainer);
    };
    const FULL_RENDER_PROPS = new Set(['textBefore', 'textAfter', 'textAlign', 'textValign', 'textOverflow']);
    const popupValues = {
      bgColor: rule0.bgColor || '',
      textColor: rule0.textColor || '',
      fontWeight: rule0.fontWeight || '',
      fontStyle: rule0.fontStyle || '',
      fontSize: rule0.fontSize || '',
      fontFamily: rule0.fontFamily || '',
      textStrokeColor: rule0.textStrokeColor || '',
      textStrokeWidth: rule0.textStrokeWidth || '',
      leftAccent: !!rule0.leftAccent,
      underline: !!rule0.underline,
      accentColor: rule0.accentColor || '',
      textBefore: rule0.textBefore || '',
      textAfter: rule0.textAfter || '',
      textAlign: rule0.textAlign || '',
      textValign: rule0.textValign || '',
      textOverflow: rule0.textOverflow || '',
    };
    const STYLE_COPY_PROPS = Object.keys(popupValues);
    // 貼り付けで applyChanges → renderDetailPanel が走るとヘッダー要素が作り直されるため、
    // 開き直し用に現在のヘッダーセルを取り直す
    const freshHeaderAnchor = () => {
      const ids = ['_role', '_text', ...((this.doc.editor?.customColumns || []).map(c => c.id))];
      const i = ids.indexOf(colId);
      const ths = panelContainer?.querySelectorAll?.('.sn2-detail-th-col') || [];
      return (i >= 0 && ths[i]) ? ths[i] : anchorEl;
    };
    openFormatPopup(anchorEl, {
      values: popupValues,
      verticalWriting: this.doc.editor?.viewMode === 'vertical',
      className: 'gb-fmt-popup--colbulk',
      positionAnchor: this._detailMultiSelectionPositionAnchor?.(anchorEl, panelContainer),
      extraRow2: this._buildCountConfigFormatControls(colId, panelContainer),
      extraRow4: this._buildStyleCopyPasteControls(
        () => popupValues,
        (clip, props) => {
          const changes = {};
          props.forEach((p) => {
            if (!Object.prototype.hasOwnProperty.call(clip, p)) return;
            const v = clip[p];
            changes[p] = (v === false || v === null || v === undefined) ? '' : v;
          });
          if (!Object.keys(changes).length) return;
          applyChanges(changes, { fullRender: true });
          Object.assign(popupValues, changes);
          this._showColBulkPopup(freshHeaderAnchor(), colId, panelContainer);
        },
        STYLE_COPY_PROPS,
      ),
      bulk: {
        enabled: applyAll,
        label: '全行に適用（新規行にも反映）',
        onToggle: (v) => {
          this._pushUndo(v ? '全行適用ON' : '全行適用OFF');
          applyAll = v;
          // undo スナップショット直列化では空の columnAllRules が整理されるため、取得直前に作り直す
          if (!this.doc.editor.columnAllRules) this.doc.editor.columnAllRules = {};
          if (applyAll) {
            if (!this.doc.editor.columnAllRules[colId]) this.doc.editor.columnAllRules[colId] = {};
          } else {
            delete this.doc.editor.columnAllRules[colId];
          }
          this._markDirty();
        },
      },
      onChange: (prop, value) => {
        const change = {};
        change[prop] = value === null || value === undefined ? '' : value;
        popupValues[prop] = change[prop];
        applyChanges(change, FULL_RENDER_PROPS.has(prop) ? { fullRender: true } : {});
      },
      onReset: () => {
        this._pushUndo('一括書式リセット');
        const targets = getTargets();
        targets.forEach((i) => {
          const c = this.doc.characters[i];
          if (!c) return;
          const s = this._getColStyle(c, colId);
          ['bgColor','textColor','fontWeight','fontStyle','fontSize','fontFamily','textStrokeColor','textStrokeWidth','leftAccent','underline','accentColor','textBefore','textAfter','textAlign','textValign','textOverflow'].forEach((p) => delete s[p]);
          this._reapplyAutoColor(c);
        });
        if (applyAll && this.doc.editor.columnAllRules?.[colId]) {
          delete this.doc.editor.columnAllRules[colId];
        }
        this._refreshRowStyles();
        this._render();
        this._markDirty();
        this.renderDetailPanel(panelContainer);
      },
    });
  },

  _showRoleOptionsPopup(anchorEl, chara, panelContainer) {
    document.querySelectorAll('.gb-fmt-popup--role-opts').forEach(el => el.remove());
    document.querySelectorAll('.gb-fmt-popup:not(.gb-fmt-popup--role-opts)').forEach(el => el.remove());
    const popup = document.createElement('div');
    popup.className = 'gb-fmt-popup gb-fmt-popup--role-opts';
    let closeHandler = null;
    let keyHandler = null;
    const closePopup = (restoreFocus = false) => {
      popup.remove();
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (keyHandler) {
        document.removeEventListener('keydown', keyHandler, true);
        keyHandler = null;
      }
      if (restoreFocus && typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchorEl);
    };
    const e = typeof esc === 'function' ? esc : (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const roleAdapter = this._roleManagementAdapter?.();
    const isScenarioType = !!roleAdapter?.types?.includes(chara);
    const ts = chara.textStyle || {};
    const indentNum = parseFloat(chara.indent) || '';
    const textShiftColsValue = Number.isFinite(Number(chara.textShiftCols)) ? Math.max(1, Math.min(10, Number(chara.textShiftCols))) : '';
    const outlineWidthValue = Number.isFinite(Number(chara.outlineWidth)) ? Math.max(0.5, Math.min(10, Number(chara.outlineWidth))) : 1;
    // （なし）行: タイプ空欄行はページ採番の対象外のため、区切り/見開き/プロットは表示しない
    const isNoneType = !!chara.isDefault;
    const breakOptsHtml = isNoneType ? '' : `
        <div class="sn2-role-opts-row sn2-role-opts-row--top">
          <label class="sn2-role-opts-check-lbl">
            <input type="checkbox" data-opt-check="isBreak"${chara.isBreak ? ' checked' : ''}> 区切り
          </label>
          <span class="sn2-role-opts-hint">ページを切り替える</span>
        </div>
        <div class="sn2-role-opts-row">
          <label class="sn2-role-opts-check-lbl">
            <input type="checkbox" data-opt-check="isSpread"${chara.isSpread ? ' checked' : ''}> 見開き
          </label>
          ${fieldHelp('「区切り」ON時のみ有効。連続時の偶数回目はページ送りせずコマ送り扱いになります')}
        </div>
        <div class="sn2-role-opts-row">
          <label class="sn2-role-opts-check-lbl">
            <input type="checkbox" data-opt-check="isSummary"${chara.isSummary ? ' checked' : ''}> プロット
          </label>
          ${fieldHelp('コマ番号を非表示にしリセット')}
        </div>`;
    popup.innerHTML = `
      <div class="sn2-role-opts-title">オプション設定</div>
      <div class="sn2-role-opts-body">${breakOptsHtml}
        <div class="sn2-role-opts-row${isNoneType ? ' sn2-role-opts-row--top' : ''}">
          <span class="sn2-role-opts-field-label">インデント</span>
          <input type="number" class="sn2-role-opts-input-num" data-opt="indent" value="${indentNum}" placeholder="0" min="0" max="20" step="0.5">
          <span class="sn2-role-opts-unit">em</span>
        </div>
        <div class="sn2-role-opts-row">
          <span class="sn2-role-opts-field-label">テキスト表示位置</span>
          <select class="sn2-role-opts-sel" data-opt-sel="textShiftDir">
            <option value=""${!chara.textShiftDir ? ' selected' : ''}>なし</option>
            <option value="before"${chara.textShiftDir === 'before' ? ' selected' : ''}>前にズラす</option>
            <option value="after"${chara.textShiftDir === 'after' ? ' selected' : ''}>後にズラす</option>
          </select>
          <input type="number" class="sn2-role-opts-input-num sn2-role-opts-input-num--sm" data-opt="textShiftCols" value="${e(textShiftColsValue)}" placeholder="1" min="1" max="10">
          <span class="sn2-role-opts-unit">列</span>
        </div>
        <div class="sn2-role-opts-divider sn2-role-opts-gutter-settings">
          <div class="sn2-role-opts-row">
            <span class="sn2-role-opts-field-label">大区切り</span>
            <button type="button" class="sn2-detail-add-btn" data-role-gutter-style="_gutter" data-e2e-id="scriptnote-role-option-gutter-style">個別設定…</button>
            <span class="sn2-role-opts-hint">${Object.keys(chara.gutterStyle || {}).length ? '個別設定あり' : '表示タブの設定を使用'}</span>
          </div>
          <div class="sn2-role-opts-row">
            <span class="sn2-role-opts-field-label">小区切り</span>
            <button type="button" class="sn2-detail-add-btn" data-role-gutter-style="_gutter2" data-e2e-id="scriptnote-role-option-gutter2-style">個別設定…</button>
            <span class="sn2-role-opts-hint">${Object.keys(chara.gutter2Style || {}).length ? '個別設定あり' : '表示タブの設定を使用'}</span>
          </div>
        </div>
        <div class="sn2-role-opts-divider">
          <div class="sn2-role-opts-row sn2-role-opts-row--wrap">
            <label class="sn2-role-opts-check-lbl">
              <input type="checkbox" data-opt-check="outline"${chara.outline ? ' checked' : ''}> 見出し枠線
            </label>
            <span class="sn2-role-opts-sep">色</span>
            <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg gb-fmt-swatch--sm" data-outline-color="outlineColor"></button>
            <span class="sn2-role-opts-unit">太さ</span>
            <input type="number" class="sn2-role-opts-input-num sn2-role-opts-input-num--sm" data-opt="outlineWidth" value="${e(outlineWidthValue)}" placeholder="1" min="0.5" max="10" step="0.5">
            <span class="sn2-role-opts-unit">px</span>
          </div>
        </div>
        <div class="sn2-role-opts-divider-flex">
          <button type="button" class="sn2-detail-add-btn sn2-role-opts-flex1" data-role-duplicate>複製</button>
          <button type="button" class="sn2-detail-add-btn sn2-role-opts-flex1 sn2-role-opts-del" data-role-delete>削除</button>
        </div>
      </div>`;
    // outlineColor swatch 初期背景 (インライン指定)
    const outlineBtn = popup.querySelector('[data-outline-color]');
    if (outlineBtn) Object.assign(outlineBtn.style, { background: chara.outlineColor || 'var(--border)' });
    if (chara.isTypeDefault || chara.isDefault) {
      popup.querySelector('[data-role-duplicate]')?.setAttribute('disabled', '');
      popup.querySelector('[data-role-delete]')?.setAttribute('disabled', '');
    }
    popup.querySelectorAll('[data-role-gutter-style]').forEach(btn => {
      btn.addEventListener('click', () => {
        const colId = btn.dataset.roleGutterStyle;
        const inheritedStyle = this.doc.editor?.columnStyles?.[colId] || {};
        closePopup();
        this._showCellStylePopup(anchorEl, chara, colId, panelContainer, {
          includeCountConfig: false,
          inheritedStyle,
          typeOverride: true,
        });
      });
    });
    // 複製ボタン
    popup.querySelector('[data-role-duplicate]')?.addEventListener('click', () => {
      if (chara.isDefault || chara.isTypeDefault) {
        if (typeof showStatus === 'function') showStatus('この初期設定は複製できません', true);
        return;
      }
      this._pushUndo('タイプ複製');
      if (isScenarioType) {
        const duplicate = roleAdapter.clone('type', chara);
        this._detailTypeSelection?.clear();
        this._detailTypeSelection?.add(duplicate.id);
        roleAdapter.touch();
        closePopup();
        this.renderDetailPanel(panelContainer);
        return;
      }
      const dup = this._cloneChara(chara);
      dup.name = this._uniqueRoleName((chara.name || 'タイプ') + '（コピー）', chara);
      const idx = this.doc.characters.indexOf(chara);
      if (idx >= 0) this.doc.characters.splice(idx + 1, 0, dup);
      else this.doc.characters.push(dup);
      this._markDirty();
      closePopup();
      this.renderDetailPanel(panelContainer);
    });
    // 削除ボタン
    popup.querySelector('[data-role-delete]')?.addEventListener('click', () => {
      if (chara.isDefault || chara.isTypeDefault) {
        if (typeof showStatus === 'function') showStatus('この初期設定は削除できません', true);
        return;
      }
      const name = chara.name || '（名称未設定）';
      if (isScenarioType) {
        this._deleteManagedRoles('type', [chara], roleAdapter, panelContainer, closePopup);
        return;
      }
      showConfirmDialog(`タイプ「${name}」を削除しますか？`, () => {
        this._pushUndo('タイプ削除');
        this._clearRolesInRows([name]);
        const idx = this.doc.characters.indexOf(chara);
        if (idx >= 0) this.doc.characters.splice(idx, 1);
        this._detailSelection?.clear();
        this._calcCache = null;
        this._render();
        this._markDirty();
        closePopup();
        this.renderDetailPanel(panelContainer);
      });
    });
    popup.querySelectorAll('[data-opt]').forEach(inp => {
      inp.addEventListener('change', () => {
        this._pushUndo('オプション設定変更');
        const key = inp.dataset.opt;
        const val = inp.type === 'number' ? (inp.value ? Number(inp.value) : null) : inp.value;
        if (key === 'indent') {
          // インデントは em 単位の文字列で保存（空ならクリア）
          if (val) chara.indent = String(val) + 'em';
          else delete chara.indent;
          this._calcCache = null;
          this._render(); this._markDirty();
          return;
        }
        chara[key] = val;
        // 枠線関連プロパティはDOM再構築が必要
        if (key === 'outlineWidth') { this._render(); this._markDirty(); return; }
        this._refreshRowStyles(); this._markDirty();
        const item = anchorEl.closest('.sn2-detail-item');
        if (item?._applyPreview) item._applyPreview();
      });
    });
    // セレクト(配置・折り返し・位置ズラし方向)
    popup.querySelectorAll('[data-opt-sel]').forEach(sel => {
      sel.addEventListener('change', () => {
        this._pushUndo('オプション設定変更');
        chara[sel.dataset.optSel] = sel.value;
        this._render(); this._markDirty();
      });
    });
    // チェックボックス（区切り、プロット、枠線表示）
    popup.querySelectorAll('[data-opt-check]').forEach(cb => {
      cb.addEventListener('change', () => {
        this._pushUndo('オプション設定変更');
        const key = cb.dataset.optCheck;
        chara[key] = cb.checked;
        if (key === 'isBreak' && cb.checked) {
          chara.isSummary = false;
          const summaryCb = popup.querySelector('[data-opt-check="isSummary"]');
          if (summaryCb) summaryCb.checked = false;
        } else if (key === 'isBreak' && !cb.checked) {
          chara.isSpread = false;
          const spreadCb = popup.querySelector('[data-opt-check="isSpread"]');
          if (spreadCb) spreadCb.checked = false;
        } else if (key === 'isSummary' && cb.checked) {
          chara.isBreak = false;
          chara.isSpread = false;
          const breakCb = popup.querySelector('[data-opt-check="isBreak"]');
          const spreadCb = popup.querySelector('[data-opt-check="isSpread"]');
          if (breakCb) breakCb.checked = false;
          if (spreadCb) spreadCb.checked = false;
        } else if (key === 'isSpread' && cb.checked && !chara.isBreak) {
          chara.isSpread = false;
          cb.checked = false;
          if (typeof showStatus === 'function') showStatus('見開きは区切りタイプでのみ使えます', true);
        }
        // 区切り/プロットはページ採番に影響するのでキャッシュクリア
        if (key === 'isBreak' || key === 'isSummary') this._calcCache = null;
        this._render(); this._markDirty();
      });
    });
    // 枠線カラーピッカー
    popup.querySelectorAll('[data-outline-color]').forEach(btn => {
      btn.addEventListener('click', () => {
        if (typeof openColorPalette === 'function') {
          openColorPalette(btn, chara.outlineColor || '#888', (color) => {
            this._pushUndo('枠線色変更');
            if (color === 'transparent') { delete chara.outlineColor; } else { chara.outlineColor = color; }
            Object.assign(btn.style, { background: chara.outlineColor || 'var(--border)' });
            this._render(); this._markDirty();
          });
        }
      });
    });
    document.body.appendChild(popup);
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorEl,
        close: () => closePopup(true),
      });
    }
    if (typeof positionPopup === 'function') positionPopup(popup, anchorEl.getBoundingClientRect());
    else if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
    keyHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closePopup(true);
    };
    document.addEventListener('keydown', keyHandler, true);
    setTimeout(() => {
      closeHandler = (ev) => {
        if (!popup.contains(ev.target) && ev.target !== anchorEl && !ev.target.closest?.('.gb-fmt-popup') && !ev.target.closest?.('.gb-palette-popup')) {
          closePopup();
        }
      };
      if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

  // チャラのディープコピー（候補値共有を防ぐ）
  _cloneChara(src) {
    if (!src) return {};
    const out = { ...src };
    if (src.textStyle) out.textStyle = { ...src.textStyle };
    if (src.gutterStyle) out.gutterStyle = { ...src.gutterStyle };
    if (src.gutter2Style) out.gutter2Style = { ...src.gutter2Style };
    if (src.roleStyle) out.roleStyle = { ...src.roleStyle };
    if (src.customStyles) {
      out.customStyles = {};
      Object.entries(src.customStyles).forEach(([k, v]) => { out.customStyles[k] = { ...(v || {}) }; });
    }
    if (src.autoColorTarget && typeof src.autoColorTarget === 'object') out.autoColorTarget = { ...src.autoColorTarget };
    return out;
  },

  _uniqueRoleName(baseName, excludeChara = null) {
    const base = String(baseName || '').trim() || '新しいタイプ';
    const used = new Set((this.doc?.characters || [])
      .filter(c => c && c !== excludeChara && !c.isDefault)
      .map(c => String(c.name || '').trim())
      .filter(Boolean));
    if (!used.has(base)) return base;
    let index = 2;
    let candidate = `${base}（${index}）`;
    while (used.has(candidate)) {
      index++;
      candidate = `${base}（${index}）`;
    }
    return candidate;
  },

  // 列の「全行に適用」ルール (doc.editor.columnAllRules) をchara に適用する
  _applyColumnAllRules(chara) {
    if (!chara) return;
    const rules = this.doc.editor?.columnAllRules || {};
    Object.entries(rules).forEach(([colId, rule]) => {
      if (!rule || typeof rule !== 'object') return;
      const style = this._getColStyle(chara, colId);
      Object.entries(rule).forEach(([prop, val]) => {
        if (val === '' || val === null || val === undefined) delete style[prop];
        else style[prop] = val;
      });
    });
  },

  // リセット後に自動配色を再適用する
  _getAutoColorPaletteRow() {
    const raw = Number(this.doc?.editor?.autoColorPaletteRow);
    return Number.isFinite(raw) ? Math.max(1, Math.min(4, Math.round(raw))) : 3;
  },

  _getAutoColorPalette() {
    const row = this._getAutoColorPaletteRow();
    if (typeof getStandardPaletteSwatches === 'function') {
      const colors = getStandardPaletteSwatches(undefined, { themeSlots: true })
        .filter(swatch => swatch && swatch.row === row && swatch.color && swatch.color !== 'transparent')
        .map(swatch => swatch.color);
      if (colors.length) return colors;
    }
    const fallback = typeof PALETTE_COLORS !== 'undefined' ? PALETTE_COLORS : [];
    const ranges = { 1: [0, 7], 2: [7, 15], 3: [15, 23], 4: [23, 31] };
    const [start, end] = ranges[row] || ranges[3];
    const colors = fallback.slice(start, end).filter(Boolean);
    return colors.length ? colors : fallback.filter(Boolean);
  },

  _getAutoColorAppearanceTargets() {
    if (Number(this.doc?.schema_version) >= 3 || Array.isArray(this.doc?.scenarioTypes)) {
      const targets = [...(this.doc?.scenarioTypes || [])];
      (this.doc?.characters || []).forEach(character => {
        if (!character?.typeId && character?.legacyAppearance) targets.push(character.legacyAppearance);
      });
      return targets;
    }
    return (this.doc?.characters || []).filter(character => !character?.isDefault);
  },

  _resetAutoColorPaletteAssignments() {
    const targets = this._getAutoColorAppearanceTargets();
    targets.forEach(target => { delete target.autoColor; });
    targets.forEach(target => this._reapplyAutoColor(target));
  },

  _reapplyAutoColor(chara) {
    if (!chara) return;
    const acRule = this.doc.editor?.autoColorRule || {};
    const allNone = Object.values(acRule).every(v => !v || v === 'none');
    if (allNone) { delete chara.autoColor; return; }
    // autoColorが未設定なら再割り当て
    if (!chara.autoColor) {
      const colors = this._getAutoColorPalette();
      if (colors.length) {
        const existingCount = this._getAutoColorAppearanceTargets()
          .filter(item => item !== chara && (item.autoColor || item.bgColor)).length;
        chara.autoColor = colors[existingCount % colors.length];
      }
    }
    chara.autoColorTarget = { ...acRule };
  },

  _refreshRowStyles() {
    if (!this.host) return;
    this.host.querySelectorAll('.sn2-row').forEach(rowEl => {
      const rowId = rowEl.dataset.rowId;
      const row = this.doc.rows.find(r => r.id === rowId);
      if (row) this._applyRowStyle(rowEl, row.role);
    });
  },

  _renameRoleInRows(oldName, newName) {
    if (!oldName || oldName === newName) return;
    this.doc.rows.forEach(r => { if (r.role === oldName) r.role = newName; });
    this.host?.querySelectorAll('.sn2-row').forEach(rowEl => {
      const rowId = rowEl.dataset.rowId;
      const row = this.doc.rows.find(r => r.id === rowId);
      if (row) {
        const btn = rowEl.querySelector('.sn2-role-btn');
        if (btn) btn.textContent = row.role || '';
        this._applyRowStyle(rowEl, row.role);
      }
    });
  },

  _clearRolesInRows(roleNames) {
    const targets = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).filter(Boolean));
    if (!targets.size) return;
    this.doc.rows.forEach(row => {
      if (targets.has(row.role)) row.role = '';
    });
    this._calcCache = null;
    this.host?.querySelectorAll('.sn2-row').forEach(rowEl => {
      const rowId = rowEl.dataset.rowId;
      const row = this.doc.rows.find(r => r.id === rowId);
      if (!row) return;
      const btn = rowEl.querySelector('.sn2-role-btn');
      if (btn) btn.textContent = row.role || '';
      this._applyRowStyle(rowEl, row.role);
    });
  },

  _setupDetailDragDrop(listEl, panelContainer) {
    let dragIdx = -1;
    const clearDragState = () => {
      dragIdx = -1;
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => {
        el.classList.remove('sn2-dragging', 'sn2-drop-above', 'sn2-drop-below');
      });
    };
    listEl.addEventListener('dragstart', (e) => {
      const item = e.target.closest('.sn2-detail-item');
      if (!item) return;
      // デフォルト行はドラッグ不可
      if (item.classList.contains('sn2-detail-default')) { e.preventDefault(); return; }
      dragIdx = Number(item.dataset.idx);
      item.classList.add('sn2-dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    listEl.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      // 全アイテムのハイライトをクリアしてから、現在のアイテムだけハイライト
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => {
        el.classList.remove('sn2-drop-above', 'sn2-drop-below');
      });
      const item = e.target.closest('.sn2-detail-item');
      if (item) {
        const rect = item.getBoundingClientRect();
        const isTop = e.clientY < rect.top + rect.height / 2;
        item.classList.toggle('sn2-drop-above', isTop);
        item.classList.toggle('sn2-drop-below', !isTop);
      }
    });
    listEl.addEventListener('dragend', () => {
      clearDragState();
    });
    listEl.addEventListener('drop', (e) => {
      e.preventDefault();
      const item = e.target.closest('.sn2-detail-item');
      if (!item || dragIdx < 0) { clearDragState(); return; }
      // デフォルト行はドラッグ元・ドロップ先のいずれでも対象外（末尾固定）
      if (this.doc.characters[dragIdx]?.isDefault) { clearDragState(); return; }
      let dropIdx = Number(item.dataset.idx);
      const rect = item.getBoundingClientRect();
      if (e.clientY >= rect.top + rect.height / 2) dropIdx++;
      if (dropIdx === dragIdx || dropIdx === dragIdx + 1) { clearDragState(); return; }
      // デフォルト行の位置 (= 末尾) より後ろには挿入させない
      const defIdx = this.doc.characters.findIndex(c => c.isDefault);
      if (defIdx >= 0 && dropIdx > defIdx) dropIdx = defIdx;
      this._pushUndo('タイプ並び替え');
      const [moved] = this.doc.characters.splice(dragIdx, 1);
      const insertAt = dropIdx > dragIdx ? dropIdx - 1 : dropIdx;
      this.doc.characters.splice(insertAt, 0, moved);
      this._ensureDefaultChara();
      this._detailSelection.clear();
      this._markDirty();
      dragIdx = -1;
      this.renderDetailPanel(panelContainer);
    });
  },

  _showUnifiedGutterStylePopup(anchorEl, colId, panelContainer) {
    if (typeof openFormatPopup !== 'function') return;
    if (!this.doc.editor) this.doc.editor = {};
    if (!this.doc.editor.columnStyles) this.doc.editor.columnStyles = {};
    const style = this.doc.editor.columnStyles[colId] = { ...(this.doc.editor.columnStyles[colId] || {}) };
    const resetStyle = colId === '_gutter2' ? { bgColor: '#333333' } : {};
    const fields = [
      'textColor', 'fontSize', 'fontFamily', 'bold', 'italic',
      'textStrokeColor', 'textStrokeWidth', 'bgColor', 'leftAccent', 'underline', 'accentColor',
    ];
    const values = {
      bgColor: style.bgColor || '', textColor: style.textColor || '',
      fontWeight: style.fontWeight || '', fontStyle: style.fontStyle || '',
      fontSize: style.fontSize || '', fontFamily: style.fontFamily || '',
      textStrokeColor: style.textStrokeColor || '', textStrokeWidth: style.textStrokeWidth || '',
      leftAccent: !!style.leftAccent, underline: !!style.underline, accentColor: style.accentColor || '',
    };
    const refresh = () => {
      anchorEl.style.background = style.bgColor || 'var(--bg3)';
      this._render();
      this._markDirty();
    };
    openFormatPopup(anchorEl, {
      values,
      fields,
      className: 'gb-fmt-popup--unified-gutter',
      extraRow2: this._buildCountConfigFormatControls(colId, panelContainer),
      onChange: (prop, value) => {
        this._pushUndo('区切り一元設定変更');
        if (value === '' || value === null || value === undefined || value === false) delete style[prop];
        else style[prop] = value;
        refresh();
      },
      onReset: () => {
        this._pushUndo('区切り一元設定リセット');
        Object.keys(style).forEach(key => delete style[key]);
        Object.assign(style, resetStyle);
        refresh();
      },
    });
  },

  renderThemePanel(container) {
    if (!container || !this.doc) return;
    container.innerHTML = '';
    const wrap = document.createElement('div');
    wrap.className = 'sn2-detail';
    const e = typeof esc === 'function' ? esc : (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

    // scroll 要素への setProperty ヘルパー（margin 用）
    const setScrollVar = (name, val) => {
      const scrollEl = this.host?.querySelector('.sn2-scroll');
      if (!scrollEl) return;
      if (val) scrollEl.style.setProperty(name, val);
      else scrollEl.style.removeProperty(name);
    };

    // ヘッダー + テーマタブへの誘導バナー
    const header = document.createElement('div');
    header.className = 'sn2-detail-header';
    header.innerHTML = '<span class="sn2-detail-theme-header-strong">挙動</span>';
    wrap.appendChild(header);
    const migrBanner = document.createElement('div');
    migrBanner.className = 'sn2-detail-theme-banner';
    migrBanner.textContent = '※ 色・基本テキスト・ルビなどのスタイル項目はオプションパネルの「テーマ」タブに移行しました。このタブは挙動系（枠線モード・見開き区切り・自動配色・カウント設定など）専用です。';
    wrap.appendChild(migrBanner);

    // 設定セクション
    const borderMode = this.doc.editor?.borderMode || 'all';
    const borderColor = this.doc.editor?.borderColor || '';
    const borderWidth = this.doc.editor?.borderWidth || '';
    const parsedBorderWidth = parseFloat(borderWidth);
    const borderWidthValue = Number.isFinite(parsedBorderWidth) ? String(parsedBorderWidth) : '';
    const editorMargin = this.doc.editor?.margin || '';
    const editorWrapGap = String(this.doc.editor?.wrapGap ?? '');
    const mergeDisp = !!this.doc.editor?.mergeDisplay;
    const pageBreakSpacing = this.doc.editor?.pageBreakSpacing !== false;
    const rawWheelSpeed = parseFloat(localStorage.getItem('meldex-wheel-speed'));
    const wheelSpeed = Number.isFinite(rawWheelSpeed) && rawWheelSpeed > 0
      ? Math.max(0.5, Math.min(5, rawWheelSpeed))
      : 2.5;
    const selOpt = (val, cur) => val === cur ? ' selected' : '';
    const clampNumberText = (value, fallback, min, max) => {
      const num = Number(value);
      const next = Number.isFinite(num) ? num : fallback;
      return String(Math.max(min, Math.min(max, next)));
    };
    const settings = document.createElement('div');
    settings.className = 'sn2-detail-settings';
    const spreadBorderStartValue = clampNumberText(this.doc.editor?.spreadBorder?.start, 1, 1, 999);
    const spreadBorderEveryValue = clampNumberText(this.doc.editor?.spreadBorder?.every, 2, 1, 99);
    settings.innerHTML = `
      <div class="sn2-detail-settings-row">
        <label class="sn2-detail-settings-label">枠線</label>
        <select class="sn2-detail-settings-select" data-setting="borderMode" data-e2e-id="scriptnote-theme-border-mode">
          <option value="all"${selOpt('all', borderMode)}>すべて</option>
          <option value="horizontal"${selOpt('horizontal', borderMode)}>横線のみ</option>
          <option value="vertical"${selOpt('vertical', borderMode)}>縦線のみ</option>
          <option value="none"${selOpt('none', borderMode)}>非表示</option>
        </select>
        <label class="sn2-detail-settings-label">色</label>
        <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg gb-fmt-swatch--xs" data-setting-color="borderColor" data-e2e-id="scriptnote-theme-border-color" title="枠線の色" aria-label="枠線の色"></button>
        <label class="sn2-detail-settings-label">太さ</label>
        <input type="number" class="sn2-detail-settings-input sn2-detail-settings-input--w36" data-setting="borderWidth" data-e2e-id="scriptnote-theme-border-width" value="${e(borderWidthValue)}" placeholder="1" min="0" max="10" step="0.5">
        <span class="sn2-detail-settings-label sn2-detail-settings-label--ml0">px</span>
        <label class="sn2-detail-settings-label">余白</label>
        <input type="text" class="sn2-detail-settings-input sn2-detail-settings-input--w48" data-setting="margin" data-e2e-id="scriptnote-theme-margin" value="${e(editorMargin)}" placeholder="16px" title="余白（段間隔が未指定の時は折り返しの段間隔にもなる）">
        <label class="sn2-detail-settings-label">段間隔</label>
        <input type="text" class="sn2-detail-settings-input sn2-detail-settings-input--w48" data-setting="wrapGap" data-e2e-id="scriptnote-theme-wrap-gap" value="${e(editorWrapGap)}" placeholder="余白と同じ" title="折り返しで生じる段と段の間隔（未指定なら余白と同じ）">
      </div>
      <div class="sn2-detail-settings-row">
        <label class="sn2-detail-settings-label sn2-detail-settings-label--mr2">
          <input type="checkbox" data-setting="mergeDisplay" data-e2e-id="scriptnote-theme-merge-display"${mergeDisp ? ' checked' : ''}> まとめ表示
        </label>
        <label class="sn2-detail-settings-label sn2-detail-settings-label--mr2">
          <input type="checkbox" data-setting="pageBreakSpacing" data-e2e-id="scriptnote-theme-page-break-spacing" title="区切り行の前に1行分の余白を表示" aria-label="ページ間を空ける" ${pageBreakSpacing ? ' checked' : ''}> ページ間を空ける
        </label>
      </div>
      <div class="sn2-detail-settings-row sn2-detail-settings-row--nowrap">
        <label class="sn2-detail-settings-label">ホイール速度</label>
        <input type="range" class="gb-range sn2-detail-theme-range" min="0.5" max="5" step="0.1" value="${e(wheelSpeed.toFixed(1))}" data-sn2-wheel-speed data-e2e-id="scriptnote-theme-wheel-speed" title="ホイール速度" aria-label="ホイール速度">
        <span class="sn2-detail-settings-label sn2-detail-settings-label--ml0 sn2-detail-theme-range-value" data-sn2-wheel-speed-value>${e(wheelSpeed.toFixed(1))}倍</span>
      </div>
      <div class="sn2-detail-settings-row">
        <label class="sn2-detail-settings-label sn2-detail-settings-label--mr2">
          <input type="checkbox" data-setting="spreadBorderEnabled" data-e2e-id="scriptnote-theme-spread-border-enabled"${this.doc.editor?.spreadBorder?.enabled ? ' checked' : ''}> 見開き区切り
        </label>
        <label class="sn2-detail-settings-label">開始</label>
        <input type="number" class="sn2-detail-settings-input sn2-detail-settings-input--w36" data-setting="spreadBorderStart" data-e2e-id="scriptnote-theme-spread-border-start" value="${e(spreadBorderStartValue)}" min="1" max="999" title="区切り線を引く最初のページ番号">
        <label class="sn2-detail-settings-label">間隔</label>
        <input type="number" class="sn2-detail-settings-input sn2-detail-settings-input--w36" data-setting="spreadBorderEvery" data-e2e-id="scriptnote-theme-spread-border-every" value="${e(spreadBorderEveryValue)}" min="1" max="99" title="何ページごとに区切り線を引くか">
        <span class="sn2-detail-settings-label">p</span>
      </div>
      <div class="sn2-detail-settings-row">
        <label class="sn2-detail-settings-label">列間枠線</label>
        <div id="sn2-col-border-ui" class="sn2-detail-colborder-ui"></div>
      </div>
      <div class="sn2-detail-settings-row">
        <label class="sn2-detail-settings-label">大区切り</label>
        <button type="button" class="sn2-detail-add-btn" data-gutter-style="_gutter" data-e2e-id="scriptnote-theme-primary-style">書式設定…</button>
        <label class="sn2-detail-settings-label">小区切り</label>
        <button type="button" class="sn2-detail-add-btn" data-gutter-style="_gutter2" data-e2e-id="scriptnote-theme-secondary-style">書式設定…</button>
      </div>`;
    settings.querySelectorAll('[data-gutter-style]').forEach(button => {
      const colId = button.dataset.gutterStyle;
      const style = this.doc.editor?.columnStyles?.[colId] || {};
      button.style.background = style.bgColor || 'var(--bg3)';
      button.addEventListener('click', () => this._showUnifiedGutterStylePopup(button, colId, container));
    });
    // 枠線色スウォッチの初期背景色
    const borderSwBtn = settings.querySelector('[data-setting-color="borderColor"]');
    if (borderSwBtn) borderSwBtn.style.background = borderColor || 'var(--border)';
    const wheelSpeedInput = settings.querySelector('[data-sn2-wheel-speed]');
    const wheelSpeedValue = settings.querySelector('[data-sn2-wheel-speed-value]');
    if (wheelSpeedInput && wheelSpeedValue) {
      const updateWheelSpeed = (save) => {
        const raw = parseFloat(wheelSpeedInput.value);
        const next = Number.isFinite(raw) ? Math.max(0.5, Math.min(5, raw)) : 2.5;
        wheelSpeedInput.value = next.toFixed(1);
        wheelSpeedValue.textContent = next.toFixed(1) + '倍';
        if (save) localStorage.setItem('meldex-wheel-speed', String(next));
        globalThis.GBUI?.refreshRangeFill?.(wheelSpeedInput);
      };
      wheelSpeedInput.addEventListener('input', () => updateWheelSpeed(true));
      updateWheelSpeed(false);
    }
    // editor 要素への setProperty 用ヘルパー (settings セクション内で使用)
    const setEditorVar = (name, val) => {
      const editorEl = this.host?.querySelector('.sn2-editor');
      if (!editorEl) return;
      if (val) editorEl.style.setProperty(name, val);
      else editorEl.style.removeProperty(name);
    };

    // カラースウォッチのクリックハンドラ (borderColor のみ)
    settings.querySelectorAll('[data-setting-color]').forEach(btn => {
      btn.addEventListener('click', () => {
        const prop = btn.dataset.settingColor;
        const current = this.doc.editor?.[prop] || '';
        const applySetting = (color) => {
          this._pushUndo('枠線色変更');
          const isNone = color === 'transparent';
          if (isNone) { delete this.doc.editor[prop]; } else { this.doc.editor[prop] = color; }
          Object.assign(btn.style, { background: isNone ? 'var(--bg3)' : color });
          if (prop === 'borderColor') {
            setEditorVar('--sn2-border-color', isNone ? 'var(--border)' : color);
          }
          this._markDirty();
        };
        if (typeof openColorPalette === 'function') {
          openColorPalette(btn, current || '#888', applySetting);
        }
      });
    });
    settings.addEventListener('change', (ev) => {
      const el = ev.target;
      const key = el.dataset.setting;
      if (!key) return;
      this._pushUndo('テーマ設定変更');
      const editorEl = this.host?.querySelector('.sn2-editor');
      if (key === 'borderMode') {
        this.doc.editor.borderMode = el.value;
        if (editorEl) editorEl.dataset.border = el.value;
      } else if (key === 'borderWidth') {
        const bw = el.value.trim();
        this.doc.editor.borderWidth = bw ? bw + 'px' : '';
        setEditorVar('--sn2-border-width', bw ? bw + 'px' : '1px');
      } else if (key === 'margin') {
        const mv = el.value.trim();
        this.doc.editor.margin = mv;
        const mvCss = mv ? (/^\d+$/.test(mv) ? mv + 'px' : mv) : '';
        setScrollVar('--sn2-margin', mvCss);
        this._render();
      } else if (key === 'wrapGap') {
        const wv = el.value.trim();
        if (wv) this.doc.editor.wrapGap = wv;
        else delete this.doc.editor.wrapGap;
        const wvCss = wv ? (/^\d+$/.test(wv) ? wv + 'px' : wv) : '';
        setScrollVar('--sn2-wrap-gap', wvCss);
        this._render();
      } else if (key === 'mergeDisplay') {
        this.doc.editor.mergeDisplay = el.checked;
        this._render();
        // ツールバーのボタン状態も同期
        document.querySelectorAll('#btn-merge-display').forEach(btn => btn.classList.toggle('active', el.checked));
      } else if (key === 'pageBreakSpacing') {
        this.doc.editor.pageBreakSpacing = el.checked;
        this._render();
      } else if (key === 'spreadBorderEnabled') {
        if (!this.doc.editor.spreadBorder) this.doc.editor.spreadBorder = {};
        this.doc.editor.spreadBorder.enabled = el.checked;
        this._render();
      } else if (key === 'spreadBorderStart') {
        if (!this.doc.editor.spreadBorder) this.doc.editor.spreadBorder = {};
        this.doc.editor.spreadBorder.start = Math.max(1, parseInt(el.value) || 1);
        this._render();
      } else if (key === 'spreadBorderEvery') {
        if (!this.doc.editor.spreadBorder) this.doc.editor.spreadBorder = {};
        this.doc.editor.spreadBorder.every = Math.max(1, parseInt(el.value) || 2);
        this._render();
      } else {
        return;
      }
      this._markDirty();
    });
    wrap.appendChild(settings);
    const statusEnabled = !!this.doc.editor?.statusEnabled;
    const statusSection = document.createElement('div');
    statusSection.className = 'sn2-detail-settings sn2-detail-settings--spaced';
    const statusTitle = document.createElement('div');
    statusTitle.className = 'sn2-detail-ac-title';
    statusTitle.textContent = '採用状況';
    statusSection.appendChild(statusTitle);
    const statusBar = document.createElement('div');
    statusBar.className = 'sn2-detail-settings-row';
    const enabledLabel = document.createElement('label');
    enabledLabel.className = 'sn2-detail-settings-label sn2-detail-settings-label--mr2';
    enabledLabel.innerHTML = `<input type="checkbox" data-status-setting="enabled"${statusEnabled ? ' checked' : ''}> ステータス機能`;
    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'sn2-detail-add-btn';
    addBtn.textContent = '＋ステータス';
    addBtn.dataset.e2eId = 'scriptnote-theme-add-status';
    addBtn.title = '採用状況を追加';
    addBtn.setAttribute('aria-label', '採用状況を追加');
    addBtn.disabled = !statusEnabled;
    statusBar.appendChild(enabledLabel);
    statusBar.appendChild(addBtn);
    statusSection.appendChild(statusBar);
    const statusListWrap = document.createElement('div');
    statusListWrap.className = 'sn2-detail-status-list';
    (this._getStatusList ? this._getStatusList() : []).forEach((item, index) => {
      const row = document.createElement('div');
      row.className = 'sn2-detail-settings-row sn2-detail-settings-row--center';
      row.innerHTML = `
        <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg gb-fmt-swatch--xs" data-status-color="${index}" title="色"></button>
        <input type="text" class="sn2-detail-settings-input sn2-detail-settings-input--status-name" data-status-name="${index}" value="${typeof esc === 'function' ? esc(item.name) : item.name}" placeholder="名称"${statusEnabled ? '' : ' disabled'}>
        <button type="button" class="sn2-detail-add-btn" data-status-delete="${index}"${statusEnabled ? '' : ' disabled'}>削除</button>`;
      statusListWrap.appendChild(row);
      const sw = row.querySelector('[data-status-color]');
      if (sw) sw.style.background = item.color || 'var(--bg3)';
    });
    statusSection.appendChild(statusListWrap);
    addBtn.addEventListener('click', () => {
      this._pushUndo('採用状況設定変更');
      const list = this._getStatusList();
      const usedNames = new Set(list.map(item => String(item?.name || '').trim()).filter(Boolean));
      let nextIndex = list.length + 1;
      let nextName = `状態${nextIndex}`;
      while (usedNames.has(nextName)) {
        nextIndex++;
        nextName = `状態${nextIndex}`;
      }
      list.push({ name: nextName, color: SCRIPTNOTE_DEFAULT_STATUS_LIST[list.length % SCRIPTNOTE_DEFAULT_STATUS_LIST.length].color });
      this.doc.editor.statusList = list;
      this._markDirty();
      this.renderThemePanel(container);
    });
    statusSection.querySelector('[data-status-setting="enabled"]')?.addEventListener('change', (ev) => {
      this._pushUndo('採用状況設定変更');
      this.doc.editor.statusEnabled = ev.target.checked;
      if (!ev.target.checked) {
        this._filterStatuses = null;
        this._hideStatuses = null;
      }
      this._syncFilterButtonState?.();
      this._markDirty();
      this._render();
      this.renderThemePanel(container);
    });
    statusSection.querySelectorAll('[data-status-name]').forEach((input) => {
      input.addEventListener('change', () => {
        const idx = Number(input.dataset.statusName);
        const list = this._getStatusList();
        if (!list[idx]) return;
        this._pushUndo('採用状況設定変更');
        const oldName = list[idx].name;
        list[idx].name = input.value.trim() || list[idx].name || `状態${idx + 1}`;
        (this.doc.rows || []).forEach((row) => {
          if ((row.status || '') === oldName) row.status = list[idx].name;
        });
        this.doc.editor.statusList = _sn2NormalizeStatusList(list);
        this._clearInvalidStatuses?.();
        this._markDirty();
        this._render();
        this.renderThemePanel(container);
      });
    });
    statusSection.querySelectorAll('[data-status-delete]').forEach((button) => {
      button.addEventListener('click', () => {
        const idx = Number(button.dataset.statusDelete);
        const list = this._getStatusList();
        if (!list[idx] || list.length <= 1) return;
        const removeStatus = () => {
          this._pushUndo('採用状況設定変更');
          const removed = list.splice(idx, 1)[0];
          this.doc.editor.statusList = _sn2NormalizeStatusList(list);
          this._clearInvalidStatuses?.(removed?.name || '');
          this._markDirty();
          this._render();
          this.renderThemePanel(container);
        };
        const name = list[idx].name || `状態${idx + 1}`;
        if (typeof showConfirmDialog === 'function') showConfirmDialog(`採用状況「${name}」を削除しますか？`, removeStatus);
        else if (typeof window === 'undefined' || window.confirm(`採用状況「${name}」を削除しますか？`)) removeStatus();
      });
    });
    statusSection.querySelectorAll('[data-status-color]').forEach((button) => {
      button.addEventListener('click', () => {
        const idx = Number(button.dataset.statusColor);
        const list = this._getStatusList();
        if (!list[idx] || typeof openColorPalette !== 'function') return;
        openColorPalette(button, list[idx].color || '#6fa8dc', (color) => {
          this._pushUndo('採用状況設定変更');
          list[idx].color = color === 'transparent' ? '#6fa8dc' : color;
          this.doc.editor.statusList = _sn2NormalizeStatusList(list);
          button.style.background = list[idx].color;
          this._markDirty();
          this._render();
        });
      });
    });
    wrap.appendChild(statusSection);
    // 列間枠線UI: 列名の間にチェックボックスを配置
    const colBorderUI = settings.querySelector('#sn2-col-border-ui');
    if (colBorderUI) {
      const borderSet = this._getColumnBorderSet();
      const colLabels = this.doc.editor?.columnLabels || {};
      const countDef2 = this._getCountDef();
      const defaultLabels = { _gutter: countDef2.primaryLabel, _gutter2: countDef2.secondaryLabel, _role: 'タイプ', _status: '採用状況', _text: 'テキスト' };
      const visCols2 = { _handle: true, _gutter: true, _gutter2: true, _role: true, _status: statusEnabled, _text: true, ...(this.doc.editor?.visibleStandardColumns || {}) };
      if (!statusEnabled) visCols2._status = false;
      const allCols = [];
      if (visCols2._gutter !== false) allCols.push({ id: '_gutter', label: colLabels._gutter || defaultLabels._gutter });
      if (visCols2._gutter2 !== false) allCols.push({ id: '_gutter2', label: colLabels._gutter2 || defaultLabels._gutter2 });
      if (visCols2._role !== false) allCols.push({ id: '_role', label: colLabels._role || defaultLabels._role });
      if (visCols2._status !== false) allCols.push({ id: '_status', label: colLabels._status || defaultLabels._status });
      if (visCols2._text !== false) allCols.push({ id: '_text', label: colLabels._text || defaultLabels._text });
      (this.doc.editor?.customColumns || []).forEach(c => allCols.push({ id: c.id, label: c.label || c.id }));
      allCols.forEach((col, i) => {
        // 列名ラベル
        const lbl = document.createElement('span');
        lbl.className = 'sn2-detail-colborder-lbl';
        lbl.textContent = col.label;
        colBorderUI.appendChild(lbl);
        // 最後の列でなければチェックボックス
        if (i < allCols.length - 1) {
          const cb = document.createElement('input');
          cb.type = 'checkbox';
          cb.checked = borderSet.has(col.id);
          cb.title = col.label + ' | ' + allCols[i + 1].label + ' 間';
          cb.setAttribute('aria-label', cb.title);
          cb.dataset.e2eId = 'scriptnote-theme-column-border-' + String(col.id).replace(/[^a-zA-Z0-9_-]/g, '_');
          cb.dataset.columnBorderLeft = col.id;
          cb.dataset.columnBorderRight = allCols[i + 1].id;
          cb.className = 'sn2-detail-colborder-cb';
          const hit = document.createElement('label');
          hit.className = 'sn2-detail-colborder-hit';
          hit.title = cb.title;
          hit.setAttribute('aria-label', cb.title);
          cb.addEventListener('change', () => {
            this._pushUndo('列間枠線変更');
            const newSet = this._getColumnBorderSet();
            if (cb.checked) newSet.add(col.id); else newSet.delete(col.id);
            this.doc.editor.columnBorders = Array.from(newSet);
            this._markDirty();
            this._render();
          });
          hit.appendChild(cb);
          colBorderUI.appendChild(hit);
        }
      });
    }

    // 自動配色セクション（列ごとに 背景 / 文字 / 両方 / なし を切替）
    const acSection = document.createElement('div');
    acSection.className = 'sn2-detail-settings sn2-detail-theme-section--autocolor';
    const acTitle = document.createElement('div');
    acTitle.className = 'sn2-detail-ac-title';
    acTitle.textContent = '自動配色';
    acSection.appendChild(acTitle);
    const colDefs = [
      { id: '_gutter', label: '大区切り' },
      { id: '_gutter2', label: '小区切り' },
      { id: '_role', label: 'タイプ' },
      { id: '_text', label: 'テキスト' },
    ];
    // ヘッダー行
    const acHeader = document.createElement('div');
    acHeader.className = 'sn2-detail-settings-row';
    acHeader.innerHTML = colDefs.map(cd =>
      `<span class="sn2-detail-settings-label sn2-detail-ac-settings-label">${cd.label}</span>`
    ).join('');
    const acSelOpt = (val, cur) => val === cur ? ' selected' : '';
    const acRule = this.doc.editor?.autoColorRule || {};
    const acPaletteRow = typeof this._getAutoColorPaletteRow === 'function' ? this._getAutoColorPaletteRow() : 3;
    const acPaletteRowEl = document.createElement('div');
    acPaletteRowEl.className = 'sn2-detail-settings-row';
    acPaletteRowEl.innerHTML = `
      <label class="sn2-detail-settings-label">テーマカラー</label>
      <select class="sn2-detail-settings-select" data-ac-palette-row data-e2e-id="scriptnote-theme-auto-color-palette-row" title="自動配色で繰り返すテーマカラーの行">
        <option value="1"${acSelOpt(1, acPaletteRow)}>1行目</option>
        <option value="2"${acSelOpt(2, acPaletteRow)}>2行目</option>
        <option value="3"${acSelOpt(3, acPaletteRow)}>3行目</option>
        <option value="4"${acSelOpt(4, acPaletteRow)}>4行目</option>
      </select>`;
    acSection.appendChild(acPaletteRowEl);
    acSection.appendChild(acHeader);
    const acRow = document.createElement('div');
    acRow.className = 'sn2-detail-settings-row';
    acRow.innerHTML = colDefs.map(cd => {
      const cur = acRule[cd.id] || 'none';
      return `<select data-ac-col="${cd.id}" class="sn2-detail-settings-select sn2-detail-ac-select">
        <option value="bg"${acSelOpt('bg', cur)}>背景</option>
        <option value="text"${acSelOpt('text', cur)}>文字</option>
        <option value="both"${acSelOpt('both', cur)}>両方</option>
        <option value="none"${acSelOpt('none', cur)}>なし</option>
      </select>`;
    }).join('');
    acSection.appendChild(acRow);
    acSection.addEventListener('change', (ev) => {
      const paletteRowSel = ev.target.closest('[data-ac-palette-row]');
      if (paletteRowSel) {
        this._pushUndo('自動配色変更');
        const nextRow = Math.max(1, Math.min(4, parseInt(paletteRowSel.value, 10) || 3));
        if (!this.doc.editor) this.doc.editor = {};
        this.doc.editor.autoColorPaletteRow = nextRow;
        this._resetAutoColorPaletteAssignments();
        this._refreshRowStyles();
        this._markDirty();
        return;
      }
      const sel = ev.target.closest('[data-ac-col]');
      if (!sel) return;
      this._pushUndo('自動配色変更');
      if (!this.doc.editor.autoColorRule) this.doc.editor.autoColorRule = {};
      const colId = sel.dataset.acCol;
      this.doc.editor.autoColorRule[colId] = sel.value;
      const rule = {};
      colDefs.forEach(cd => { rule[cd.id] = this.doc.editor.autoColorRule[cd.id] || 'none'; });
      this.doc.editor.autoColorRule = { ...rule };
      // すべての非デフォルトタイプに同じターゲットを適用
      this._getAutoColorAppearanceTargets().forEach(appearance => {
        appearance.autoColorTarget = { ...rule };
        if (typeof this._reapplyAutoColor === 'function') this._reapplyAutoColor(appearance);
      });
      this._refreshRowStyles();
      this._markDirty();
    });
    wrap.appendChild(acSection);

    container.appendChild(wrap);
  },

});

;

/* === gb-scriptnote-menu.js === */
;
/* gb-scriptnote-menu.js: 台本エディタ v2 — タイプ選択メニュー
   ScriptNoteEditor.prototype を拡張する */

Object.assign(ScriptNoteEditor.prototype, {

  _showRoleMenu(roleBtn, opts) {
    this._closeRoleMenu();
    const sel = window.getSelection();
    this._roleMenuSavedRange = null;
    if (sel && sel.rangeCount) {
      const r = sel.getRangeAt(0);
      const textEl = r.startContainer?.nodeType === 3
        ? r.startContainer.parentElement?.closest?.('.sn2-text')
        : r.startContainer?.closest?.('.sn2-text');
      if (textEl && this.host?.contains(textEl)) {
        this._roleMenuSavedRange = r.cloneRange();
      }
    }
    const rowEl = roleBtn.closest('.sn2-row');
    if (!rowEl) return;
    const rowId = rowEl.dataset.rowId;
    const idx = this.doc.rows.findIndex(r => r.id === rowId);
    if (idx < 0) return;
    const currentRow = this.doc.rows[idx];
    const currentRole = currentRow.role;
    const currentResolved = globalThis.GBScriptNoteRoleModel?.resolveRole?.(this.doc, currentRow);

    const menu = document.createElement('div');
    menu.className = 'sn2-role-menu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', 'タイプを選択');
    menu.tabIndex = -1;

    const pageSettings = typeof PAGE_SETTINGS !== 'undefined' && Array.isArray(PAGE_SETTINGS)
      ? PAGE_SETTINGS : ['改ページ', 'めくり', '見開き', '白紙', 'トビラ絵', '大ゴマ', '未完'];
    const specialCharas = typeof SPECIAL_CHARA !== 'undefined' && Array.isArray(SPECIAL_CHARA)
      ? SPECIAL_CHARA : ['プロット', 'ト書き', 'ナレーション', '擬音', 'コマ外注釈'];
    const chars = this._getCharacterList();

    const select = (val) => {
      this._pushUndo('タイプ変更');
      this._setRowRole(idx, rowEl, val === '（なし）' ? '' : val);
      this._closeRoleMenu();
      if (opts?.fromNav) {
        const btn = rowEl.querySelector('.sn2-role-btn');
        if (btn && typeof this._setActiveCell === 'function') {
          this._setActiveCell(rowId, '_role', false);
        } else {
          this._restoreRangeAfterRoleMenu(rowEl);
        }
      } else {
        this._restoreRangeAfterRoleMenu(rowEl);
      }
    };

    const roleChoices = globalThis.GBScriptNoteRoleModel?.buildRoleChoices?.(this.doc)
      || this.doc.characters.filter((item) => !item.isDefault && item.name).map((item) => ({
        kind: 'character',
        id: item.id || item.name,
        name: item.name,
        label: item.name,
        ref: item.name,
      }));
    if (currentResolved?.kind === 'type'
      && !roleChoices.some((choice) => choice?.kind === 'type' && choice.id === currentResolved.id)) {
      const noneIndex = roleChoices.findIndex((choice) => choice?.kind === 'none');
      const retainedChoice = {
        kind: 'type',
        id: currentResolved.id,
        name: currentResolved.name,
        label: currentResolved.name,
        ref: { ...currentResolved.ref },
      };
      if (noneIndex >= 0) roleChoices.splice(noneIndex, 0, retainedChoice);
      else roleChoices.push(retainedChoice);
    }
    roleChoices.filter((choice) => choice?.kind !== 'none').forEach((choice) => {
      const choiceName = String(choice.name || choice.label || '');
      if (!choiceName) return;
      const btn = document.createElement('button');
      const isCurrent = currentResolved
        ? currentResolved.kind === choice.kind && currentResolved.id === choice.id
        : choiceName === currentRole;
      btn.className = 'sn2-role-item' + (isCurrent ? ' active' : '');
      btn.type = 'button';
      btn.setAttribute('role', 'menuitem');
      btn.textContent = choice.label || choiceName;
      const style = this._getCharaStyle(choiceName);
      if (style) btn.style.cssText = style;
      btn.addEventListener('click', () => select(choice.ref || choiceName));
      menu.appendChild(btn);
    });

    // 空欄タイプは管理画面の「（なし）」と同じ名称で、件数に関係なく常に選べる。
    // 既存のArrowDown順（最初の通常タイプ）を変えないよう、通常候補の末尾へ置く。
    const noneButton = document.createElement('button');
    noneButton.className = 'sn2-role-item' + (!currentRole ? ' active' : '');
    noneButton.type = 'button';
    noneButton.setAttribute('role', 'menuitem');
    noneButton.textContent = '（なし）';
    noneButton.addEventListener('click', () => select(''));
    menu.appendChild(noneButton);

    // 自由入力
    const inputWrap = document.createElement('div');
    inputWrap.className = 'sn2-role-group';
    const inputLabel = document.createElement('div');
    inputLabel.className = 'sn2-role-group-label';
    inputLabel.textContent = '自由入力';
    inputWrap.appendChild(inputLabel);
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'sn2-role-input';
    input.placeholder = 'キャラ名を入力';
    input.setAttribute('aria-label', 'タイプ名を入力');
    input.title = '';
    input.value = currentRole;
    inputWrap.appendChild(input);
    menu.appendChild(inputWrap);

    // 行本文へ手動リンクを設定する（タイプ選択とは独立したアクション）
    const linkButton = document.createElement('button');
    linkButton.className = 'sn2-role-link';
    linkButton.type = 'button';
    linkButton.setAttribute('role', 'menuitem');
    linkButton.textContent = 'リンクを設定';
    linkButton.addEventListener('click', () => {
      this._closeRoleMenu();
      this._insertLinkFromRoleMenu(rowEl);
    });
    menu.appendChild(linkButton);

    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(menu, {
        trigger: roleBtn,
        close: () => this._closeRoleMenu(),
      });
    }

    // キーボードナビゲーション（フラットリスト + 自由入力）
    const flatBtns = [...menu.querySelectorAll('.sn2-role-item')];
    let flatIdx = -1;
    const focusFlat = (i) => {
      if (i < 0 || i >= flatBtns.length) return;
      flatIdx = i;
      flatBtns[i].focus();
      flatBtns[i].scrollIntoView({ block: 'nearest' });
    };
    const menuKeyHandler = (e) => {
      if (!this._roleMenu) return;
      if (e.key === 'Escape') {
        e.preventDefault();
        this._closeRoleMenu();
        this._restoreRangeAfterRoleMenu(roleBtn.closest('.sn2-row'));
        return;
      }
      const inMenu = menu.contains(document.activeElement);
      if (!inMenu) return;
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const step = e.shiftKey ? 5 : 1;
        if (document.activeElement === input) {
          focusFlat(Math.min(flatBtns.length - 1, step - 1));
        } else if (flatIdx >= flatBtns.length - 1) {
          input.focus(); input.select(); flatIdx = -1;
        } else {
          focusFlat(Math.min(flatBtns.length - 1, flatIdx + step));
        }
        return;
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        const step = e.shiftKey ? 5 : 1;
        if (document.activeElement === input) {
          focusFlat(Math.max(0, flatBtns.length - step));
        } else if (flatIdx <= 0) {
          input.focus(); input.select(); flatIdx = -1;
        } else {
          focusFlat(Math.max(0, flatIdx - step));
        }
        return;
      }
      if (e.key === 'Enter') {
        e.preventDefault();
        if (document.activeElement === input) { select(input.value.trim()); return; }
        if (flatIdx >= 0 && flatBtns[flatIdx]) { flatBtns[flatIdx].click(); }
        return;
      }
      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (document.activeElement !== input) { e.preventDefault(); select('（なし）'); return; }
      }
      if (e.key === 'Tab') {
        e.preventDefault();
        if (document.activeElement === input) { focusFlat(0); }
        else { input.focus(); input.select(); flatIdx = -1; }
        return;
      }
      // 文字入力→入力欄にフォーカス移動
      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && document.activeElement !== input) {
        input.focus();
      }
    };
    document.addEventListener('keydown', menuKeyHandler);
    // _closeRoleMenuで解除するため保持
    this._roleMenuKeyHandler = menuKeyHandler;

    // 位置決め
    const rect = roleBtn.getBoundingClientRect();
    menu.style.cssText = 'position:fixed;z-index:10100;';
    document.body.appendChild(menu);
    positionPopup(menu, rect);
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);

    this._roleMenu = menu;
    this._roleMenuRow = rowId;
    this._roleMenuCloseHandler = null;
    setTimeout(() => {
      const close = (ev) => {
        if (!menu.contains(ev.target) && ev.target !== roleBtn) this._closeRoleMenu();
      };
      this._roleMenuCloseHandler = close;
      document.addEventListener('pointerdown', close, true);
    }, 0);
    input.focus();
    input.select();
  },

  _closeRoleMenu() {
    if (this._roleMenuCloseHandler) {
      document.removeEventListener('pointerdown', this._roleMenuCloseHandler, true);
      this._roleMenuCloseHandler = null;
    }
    if (this._roleMenuKeyHandler) {
      document.removeEventListener('keydown', this._roleMenuKeyHandler);
      this._roleMenuKeyHandler = null;
    }
    if (this._roleMenu) {
      this._roleMenu.remove();
      this._roleMenu = null;
      this._roleMenuRow = null;
    }
  },

  _restoreRangeAfterRoleMenu(rowEl) {
    const textEl = rowEl?.querySelector('.sn2-text');
    if (!textEl) return;
    textEl.focus();
    if (this._roleMenuSavedRange) {
      const sel = window.getSelection();
      if (sel) { sel.removeAllRanges(); sel.addRange(this._roleMenuSavedRange); }
      this._roleMenuSavedRange = null;
    }
  },

  _isEditingAutoLinkTarget(autoLinkEl) {
    const activeText = document.activeElement?.closest?.('.sn2-text');
    if (!activeText || !this.host?.contains(activeText)) return false;
    const linkText = autoLinkEl?.closest?.('.sn2-text');
    return !!(linkText && linkText === activeText);
  },

  _upsertAutoLinkEntry(text, path) {
    const label = String(text || '').trim();
    const target = String(path || '').trim();
    if (!label || !target) return;
    if (typeof linkDict !== 'undefined' && Array.isArray(linkDict)) {
      if (!linkDict.some(d => d.text === label && d.path === target)) {
        linkDict.push({ text: label, path: target });
      }
    }
  },

  _formatManualLinkMarkup(label, target) {
    return _sn2BuildManualLinkMarkup(label, target);
  },

  _decodeManualLinkLabel(label) {
    return _sn2DecodeManualLinkLabel(label);
  },

  _createManualLinkSpan(label, target) {
    const span = document.createElement('span');
    span.className = 'auto-link';
    span.dataset.path = target || '';
    span.dataset.manualLink = 'true';
    span.textContent = label || target || '';
    return span;
  },

  _appendScriptNoteInlineFragment(frag, rawText) {
    if (!frag || !rawText) return;
    if (rawText.includes('{') && rawText.includes('|') && typeof _sn2NewRubyRegex === 'function') {
      let last = 0;
      const re = _sn2NewRubyRegex();
      let m;
      while ((m = re.exec(rawText)) !== null) {
        if (m.index > last) frag.appendChild(document.createTextNode(_sn2UnescapeScriptNotePlainText(rawText.slice(last, m.index))));
        const span = document.createElement('span');
        span.dataset.ruby = _sn2UnescapeRubyText(m[2]);
        span.textContent = _sn2UnescapeRubyText(m[1]);
        frag.appendChild(span);
        last = m.index + m[0].length;
      }
      if (last < rawText.length) frag.appendChild(document.createTextNode(_sn2UnescapeScriptNotePlainText(rawText.slice(last))));
      return;
    }
    frag.appendChild(document.createTextNode(_sn2UnescapeScriptNotePlainText(rawText)));
  },

  _buildManualLinkFragment(rawText) {
    const frag = document.createDocumentFragment();
    const re = /\[((?:\\.|[^\]])+)\]\(ml:([^)]+)\)/g;
    let last = 0;
    let matched = false;
    let m;
    while ((m = re.exec(rawText || '')) !== null) {
      matched = true;
      if (m.index > last) this._appendScriptNoteInlineFragment(frag, rawText.slice(last, m.index));
      let target = '';
      try { target = decodeURIComponent(m[2]); } catch { target = m[2]; }
      frag.appendChild(this._createManualLinkSpan(this._decodeManualLinkLabel(m[1]), target));
      last = m.index + m[0].length;
    }
    if (!matched) return null;
    if (last < rawText.length) this._appendScriptNoteInlineFragment(frag, rawText.slice(last));
    return frag;
  },

  _restoreTextSelectionForLinkInsert(textEl, savedRange) {
    if (!textEl) return null;
    textEl.focus();
    const sel = window.getSelection();
    if (!sel) return null;
    if (savedRange) {
      try {
        sel.removeAllRanges();
        sel.addRange(savedRange);
        return sel;
      } catch {}
    }
    const inText = sel.rangeCount > 0
      && textEl.contains(sel.anchorNode)
      && textEl.contains(sel.focusNode);
    if (!inText) {
      const range = document.createRange();
      range.selectNodeContents(textEl);
      range.collapse(false);
      sel.removeAllRanges();
      sel.addRange(range);
    }
    return sel;
  },

  _insertLinkResultIntoText(textEl, savedRange, result) {
    if (!textEl || !result) return false;
    const sel = this._restoreTextSelectionForLinkInsert(textEl, savedRange);
    if (!sel) return false;
    const selectedLabel = (sel.toString() || '').trim();
    let label = '';
    let target = '';
    if (result.type === 'file') {
      label = selectedLabel || result.name || result.path || '';
      target = result.path || '';
    } else if (result.type === 'url') {
      label = selectedLabel || result.url || '';
      target = result.url || '';
    } else {
      return false;
    }
    if (!label || !target || !sel.rangeCount) return false;
    this._pushUndo('リンク挿入');
    const span = this._createManualLinkSpan(label, target);
    const range = sel.getRangeAt(0);
    range.deleteContents();
    range.insertNode(span);
    range.setStartAfter(span);
    range.collapse(true);
    sel.removeAllRanges();
    sel.addRange(range);
    this._upsertAutoLinkEntry(label, target);
    this._syncRowFromDom(textEl, { skipUndo: true });
    return true;
  },

  _insertLinkFromRoleMenu(rowEl) {
    const textEl = rowEl?.querySelector('.sn2-text');
    if (!textEl || typeof showLinkInsertModal !== 'function') return;
    showLinkInsertModal(null, (result) => {
      if (!textEl.isConnected) return;
      this._insertLinkResultIntoText(textEl, null, result);
    });
  },

  _setRowRole(idx, rowEl, newRole) {
    const targetRow = this.doc.rows[idx];
    if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
      globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, targetRow, newRole);
      newRole = targetRow.role;
    } else {
      targetRow.role = newRole;
    }
    // dataset.kind: オプション設定 isBreak/isSummary/kind を反映
    const effective = globalThis.GBScriptNoteRoleModel?.getEffectiveRole?.(this.doc, targetRow);
    const charaForKind = effective?.type || effective?.style || (newRole
      ? this.doc.characters.find(c => !c.isDefault && c.name === newRole)
      : null);
    let kind = 'dialogue';
    if (!newRole) kind = 'blank';
    else if (charaForKind?.isSummary) kind = 'summary';
    else if (charaForKind?.isBreak) kind = 'break';
    else if (['dialogue', 'action', 'heading'].includes(charaForKind?.kind)) kind = charaForKind.kind;
    rowEl.dataset.kind = kind;
    // 枠線設定（タイプ個別のoutline）— 役割空時はデフォルトタイプから引く
    const outlineChara = effective?.style || (newRole
      ? this.doc.characters.find(c => !c.isDefault && c.name === newRole)
      : this.doc.characters.find(c => c.isDefault));
    if (outlineChara?.outline) {
      rowEl.dataset.outline = 'true';
      if (outlineChara.outlineColor) rowEl.style.setProperty('--sn2-outline-color', outlineChara.outlineColor);
      if (outlineChara.outlineWidth) rowEl.style.setProperty('--sn2-outline-width', outlineChara.outlineWidth + 'px');
    } else {
      delete rowEl.dataset.outline;
      rowEl.style.removeProperty('--sn2-outline-color');
      rowEl.style.removeProperty('--sn2-outline-width');
    }
    const btn = rowEl.querySelector('.sn2-role-btn');
    if (btn) {
      btn.textContent = newRole || '';
      // 縦書き: 半角英数字を縦中横に再ラップ
      if (this.doc.editor?.viewMode === 'vertical') this._wrapTcy(btn);
    }
    // 旧形式のfallbackでは、未登録名を従来どおりキャラ候補へ追加する。
    if (!globalThis.GBScriptNoteRoleModel?.assignRowRole
      && newRole && !this.doc.characters.some(c => !c.isDefault && c.name === newRole)) {
      const newChara = this._createCharaFromTypeDefault(newRole);
      // デフォルトタイプの直前に挿入（末尾固定の不変条件を維持）
      const defIdx = this.doc.characters.findIndex(c => c.isDefault);
      if (defIdx >= 0) this.doc.characters.splice(defIdx, 0, newChara);
      else this.doc.characters.push(newChara);
    }
    // スタイル適用
    this._applyRowStyle(rowEl, newRole);
    // ページ/コマ番号更新
    this._calcCache = null;
    this._updateGuttersFrom(Math.max(0, idx));
    this._markDirty({ skipUndo: true }); // undoは呼び出し元で管理
  },

  _syncCharactersFromRows() {
    if (!this.doc) return;
    if (globalThis.GBScriptNoteRoleModel?.ensureDocument) {
      globalThis.GBScriptNoteRoleModel.ensureDocument(this.doc);
      return;
    }
    const registered = new Set(this.doc.characters.map(c => c.name));
    this.doc.rows.forEach(r => {
      if (r.role && !registered.has(r.role)) {
        const newChara = this._createCharaFromTypeDefault(r.role);
        this.doc.characters.push(newChara);
        registered.add(r.role);
      }
    });
  },

  _ensureTypeDefaultChara() {
    if (!this.doc) return null;
    if (!this.doc.editor) this.doc.editor = {};
    if (typeof ensureScriptNoteDefaultType === 'function') return ensureScriptNoteDefaultType(this.doc.editor);
    if (!this.doc.editor.defaultType) {
      this.doc.editor.defaultType = {
        isTypeDefault: true,
        name: '',
        roleStyle: { bgColor: '#333333' },
        textStyle: { bgColor: '#333333' },
      };
    }
    return this.doc.editor.defaultType;
  },

  _createCharaFromTypeDefault(name) {
    const source = this._ensureTypeDefaultChara() || {};
    let chara;
    try { chara = JSON.parse(JSON.stringify(source)); } catch { chara = { ...source }; }
    delete chara.isTypeDefault;
    delete chara.isDefault;
    chara.name = String(name || '').trim();
    // 「全行に適用（新規行にも反映）」の列ルールを新規タイプへ反映する
    // （2523156b でひな形方式へ移行した際に呼び出しが欠落していた）
    if (typeof this._applyColumnAllRules === 'function') this._applyColumnAllRules(chara);
    return chara;
  },

  // 役割が空の行に適用するデフォルトタイプ（isDefault: true）を末尾に常時 1 件保持する。
  // 複数あれば 1 件に統合し、末尾以外にあれば末尾へ移動する。
  _ensureDefaultChara() {
    if (!this.doc) return;
    if (globalThis.GBScriptNoteRoleModel?.ensureDocument) {
      globalThis.GBScriptNoteRoleModel.ensureDocument(this.doc);
      return;
    }
    this._ensureTypeDefaultChara();
    if (!Array.isArray(this.doc.characters)) this.doc.characters = [];
    const chars = this.doc.characters;
    let def = null;
    for (let i = chars.length - 1; i >= 0; i--) {
      if (chars[i] && chars[i].isDefault) {
        if (def) chars.splice(i, 1); // 重複は削除
        else def = chars[i];
      }
    }
    if (!def) {
      def = { isDefault: true, name: '' };
      chars.push(def);
    } else {
      // name は空文字に正規化（kind は使わない: 識別は isDefault フラグのみ）
      delete def.kind;
      def.name = '';
      // 末尾に移動
      const idx = chars.indexOf(def);
      if (idx !== chars.length - 1) {
        chars.splice(idx, 1);
        chars.push(def);
      }
    }
    // （なし）行の大区切り/小区切り背景の初期値は透明。
    // bgColor キーが存在する場合（null=解除含む）はユーザー設定として保持する。
    // 一元化移行前（gutterStyleScopeVersion<2）に補完すると、移行が補完値を
    // 全タイプ共通スタイルとして editor.columnStyles へ昇格させるため、移行後のみ補完する。
    if (Number(this.doc.editor?.gutterStyleScopeVersion || 0) >= 2) {
      ['gutterStyle', 'gutter2Style'].forEach((key) => {
        let style = def[key];
        if (!style || typeof style !== 'object' || Array.isArray(style)) {
          style = {};
          def[key] = style;
        }
        if (!Object.prototype.hasOwnProperty.call(style, 'bgColor')) style.bgColor = 'transparent';
      });
    }
  },

  // 自動配色: PALETTE_COLORSを循環して割り当て
  _assignAutoColor(chara) {
    if (chara.isDefault) return; // デフォルトタイプは自動配色対象外
    if (chara.autoColor || chara.bgColor) return; // 既に色が設定されている場合はスキップ
    const colors = typeof this._getAutoColorPalette === 'function'
      ? this._getAutoColorPalette()
      : (typeof PALETTE_COLORS !== 'undefined' ? PALETTE_COLORS : []);
    if (!colors.length) return;
    // editor.autoColorRule から列ごとの配色先を取得
    const acRule = this.doc.editor?.autoColorRule || {};
    const allNone = Object.values(acRule).every(v => !v || v === 'none');
    if (allNone) return;
    // 既存キャラの使用色数をカウントしてインデックスを決定
    const existingCount = this.doc.characters.filter(c => c.autoColor || c.bgColor).length;
    const idx = existingCount % colors.length;
    chara.autoColor = colors[idx];
    chara.autoColorTarget = { ...acRule };
  },

  _getCharacterList() {
    if (globalThis.GBScriptNoteRoleModel?.buildRoleChoices) {
      return globalThis.GBScriptNoteRoleModel.buildRoleChoices(this.doc)
        .filter((choice) => choice?.kind !== 'none')
        .map((choice) => String(choice.name || choice.label || ''))
        .filter(Boolean);
    }
    const set = new Set();
    this.doc.characters.forEach(c => { if (!c.isDefault && c.name) set.add(c.name); });
    return Array.from(set).sort();
  },

});

;

/* === gb-scriptnote-ruby.js === */
;
/* gb-scriptnote-ruby.js: 台本エディタ v2 — ルビタブ
   ScriptNoteEditor.prototype を拡張する */

function _snRubyIcon(name, size, fallback) {
  if (typeof lucide === 'function') return lucide(name, size || 14);
  return fallback || '';
}

function _snRubyConfirmDelete(message) {
  if (typeof cfConfirm === 'function') {
    return Promise.resolve(cfConfirm(message, { danger: true, okLabel: '解除' })).then(Boolean);
  }
  if (typeof showConfirmDialog === 'function') {
    return new Promise(resolve => showConfirmDialog(message, () => resolve(true), () => resolve(false)));
  }
  if (typeof confirm === 'function') return Promise.resolve(!!confirm(message));
  return Promise.resolve(false);
}

Object.assign(ScriptNoteEditor.prototype, {

  _refreshAutoRubyDisplay() {
    this.host?.querySelectorAll('.sn2-text').forEach((textEl) => {
      if (typeof this._applyAutoRuby === 'function') this._applyAutoRuby(textEl);
    });
    if (typeof this._adjustRubySpacing === 'function') this._adjustRubySpacing();
  },

  renderRubyPanel(container) {
    if (!container || !this.doc) return;
    container.innerHTML = '';
    const wrap = document.createElement('div');
    wrap.className = 'sn2-ruby-panel';

    // ヘッダー
    const header = document.createElement('div');
    header.className = 'sn2-detail-header';
    const title = document.createElement('span');
    title.className = 'sn2-ruby-title';
    title.textContent = 'ルビ';
    header.appendChild(title);
    const headerBtns = document.createElement('div');
    headerBtns.className = 'sn2-ruby-header-actions';
    const mkBtn = (label, title, onClick, e2eId, iconName = 'plus') => {
      const b = document.createElement('button');
      b.className = 'sn2-detail-add-btn gb-btn gb-btn-sm gb-btn-quiet sn2-ruby-add-rule';
      b.type = 'button';
      b.title = title;
      b.setAttribute('aria-label', title || label);
      if (e2eId) b.dataset.e2eId = e2eId;
      const icon = document.createElement('span');
      icon.className = 'sn2-ruby-btn-icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.innerHTML = _snRubyIcon(iconName, 13, label);
      const text = document.createElement('span');
      text.className = 'sn2-ruby-btn-label';
      text.textContent = label;
      b.append(icon, text);
      b.addEventListener('click', onClick);
      return b;
    };
    headerBtns.appendChild(mkBtn('追加', '自動ルビルール追加', () => {
      this._pushUndo('ルビルール追加');
      if (!this.doc.rubyRules) this.doc.rubyRules = [];
      this.doc.rubyRules.push({ text: '', ruby: '', auto: true });
      this._refreshAutoRubyDisplay();
      this._markDirty({ skipUndo: true });
      this.renderRubyPanel(container);
    }, 'scriptnote-ruby-add-rule'));
    headerBtns.appendChild(mkBtn('全解除', 'ファイル内ルビを全解除', async () => {
      const hasRuby = this.doc.rows.some(row => {
        const re = typeof _sn2NewRubyRegex === 'function' ? _sn2NewRubyRegex() : /\{([^|{}]+)\|([^|{}]+)\}/g;
        return re.test(String(row.text || ''));
      });
      if (!hasRuby) return;
      const ok = await _snRubyConfirmDelete('ファイル内の手動ルビをすべて解除しますか？');
      if (!ok) return;
      this._pushUndo('ルビ全解除');
      this.doc.rows.forEach(row => {
        const re = typeof _sn2NewRubyRegex === 'function' ? _sn2NewRubyRegex() : /\{([^|{}]+)\|([^|{}]+)\}/g;
        row.text = String(row.text || '').replace(re, (_matched, base) => base);
      });
      this._render();
      this._markDirty({ skipUndo: true });
      this.renderRubyPanel(container);
    }, 'scriptnote-ruby-clear-all', 'xCircle'));
    header.appendChild(headerBtns);
    wrap.appendChild(header);

    // ── 表示設定セクション（ルビ一覧の上に配置） ──
    const settingsLabel = document.createElement('div');
    settingsLabel.className = 'sn2-detail-settings-label sn2-ruby-section-label';
    settingsLabel.textContent = '表示設定';
    wrap.appendChild(settingsLabel);
    if (typeof MeldexRubySettingsUI !== 'undefined') {
      wrap.appendChild(MeldexRubySettingsUI.createEditorSettings(this, { scope: 'ruby-tab' }));
    }

    // ── ファイル内ルビ一覧（テーブル形式） ──
    // gb-scriptnote-editor.js の _sn2NewRubyRegex / _sn2UnescapeRubyText を利用
    const fileRubies = [];
    this.doc.rows.forEach((r, i) => {
      if (!r.text) return;
      const re = typeof _sn2NewRubyRegex === 'function'
        ? _sn2NewRubyRegex()
        : /\{([^|{}]+)\|([^|{}]+)\}/g;
      const unescape = typeof _sn2UnescapeRubyText === 'function' ? _sn2UnescapeRubyText : (s => s);
      let m;
      while ((m = re.exec(r.text)) !== null) {
        fileRubies.push({
          text: unescape(m[1]), ruby: unescape(m[2]), rowIdx: i, role: r.role,
          rawIndex: m.index, rawLength: m[0].length,
        });
      }
    });

    const autoRules = Array.isArray(this.doc.rubyRules) ? this.doc.rubyRules : [];

    if (fileRubies.length) {
      const secLabel = document.createElement('div');
      secLabel.className = 'sn2-detail-settings-label sn2-ruby-section-label';
      secLabel.textContent = `ファイル内ルビ（${fileRubies.length}件）`;
      wrap.appendChild(secLabel);
      const table = document.createElement('table');
      table.className = 'sn2-ruby-table';
      const thead = document.createElement('thead');
      const headRow = document.createElement('tr');
      ['対象', 'ルビ', '位置', '操作'].forEach((text, index) => {
        const th = document.createElement('th');
        th.textContent = text;
        if (index === 2) th.className = 'sn2-ruby-file-pos';
        headRow.appendChild(th);
      });
      thead.appendChild(headRow);
      table.appendChild(thead);
      const tbody = document.createElement('tbody');
      fileRubies.forEach((fr, idx) => {
        const tr = document.createElement('tr');
        tr.className = 'sn2-ruby-file-row';
        tr.tabIndex = 0;
        tr.setAttribute('role', 'button');
        tr.setAttribute('aria-label', `${fr.text} のルビ位置へ移動`);
        tr.dataset.e2eId = 'scriptnote-ruby-file-row-' + idx;
        const baseCell = document.createElement('td');
        baseCell.textContent = fr.text;
        const rubyCell = document.createElement('td');
        rubyCell.className = 'sn2-ruby-file-ruby';
        rubyCell.textContent = fr.ruby;
        const posCell = document.createElement('td');
        posCell.className = 'sn2-ruby-file-pos';
        posCell.textContent = fr.role || '行' + (fr.rowIdx + 1);
        const actionCell = document.createElement('td');
        actionCell.className = 'sn2-ruby-file-actions';
        const replaceRuby = nextRuby => {
          const row = this.doc.rows[fr.rowIdx];
          if (!row) return;
          const raw = String(row.text || '');
          const replacement = nextRuby
            ? (typeof _sn2BuildRubyMarkup === 'function' ? _sn2BuildRubyMarkup(fr.text, nextRuby) : `{${fr.text}|${nextRuby}}`)
            : (typeof _sn2EscapeScriptNotePlainText === 'function' ? _sn2EscapeScriptNotePlainText(fr.text) : fr.text);
          this._pushUndo(nextRuby ? 'ルビ編集' : 'ルビ解除');
          row.text = raw.slice(0, fr.rawIndex) + replacement + raw.slice(fr.rawIndex + fr.rawLength);
          this._render();
          this._markDirty({ skipUndo: true });
          this.renderRubyPanel(container);
        };
        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'gb-btn gb-btn-xs gb-btn-quiet';
        editBtn.textContent = '編集';
        editBtn.dataset.e2eId = 'scriptnote-ruby-file-edit-' + idx;
        editBtn.addEventListener('click', async event => {
          event.stopPropagation();
          if (typeof cfPrompt !== 'function') return;
          const next = await cfPrompt(`「${fr.text}」のルビ`, fr.ruby, { okLabel: '編集' });
          if (next == null || !String(next).trim() || String(next).trim() === fr.ruby) return;
          replaceRuby(String(next).trim());
        });
        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'gb-btn gb-btn-xs gb-btn-quiet';
        removeBtn.textContent = '解除';
        removeBtn.dataset.e2eId = 'scriptnote-ruby-file-remove-' + idx;
        removeBtn.addEventListener('click', async event => {
          event.stopPropagation();
          const ok = await _snRubyConfirmDelete(`「${fr.text}」のルビを解除しますか？`);
          if (ok) replaceRuby('');
        });
        actionCell.append(editBtn, removeBtn);
        tr.append(baseCell, rubyCell, posCell, actionCell);
        const jumpToRubyRow = () => {
          const row = this.doc.rows[fr.rowIdx];
          if (row) {
            const safeRowId = (typeof CSS !== 'undefined' && typeof CSS.escape === 'function')
              ? CSS.escape(row.id)
              : String(row.id).replace(/["\\]/g, '\\$&');
            const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${safeRowId}"]`);
            if (rowEl) {
              rowEl.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
              rowEl.classList.add('sn2-swap-highlight');
              setTimeout(() => rowEl.classList.remove('sn2-swap-highlight'), 600);
            }
          }
        };
        tr.addEventListener('click', jumpToRubyRow);
        tr.addEventListener('keydown', (ev) => {
          if (ev.key !== 'Enter' && ev.key !== ' ') return;
          ev.preventDefault();
          jumpToRubyRow();
        });
        tbody.appendChild(tr);
      });
      table.appendChild(tbody);
      const tableWrap = document.createElement('div');
      tableWrap.className = 'sn2-ruby-table-wrap';
      tableWrap.appendChild(table);
      wrap.appendChild(tableWrap);
    }

    // ── 自動ルビルール（テーブル形式） ──
    const autoLabel = document.createElement('div');
    autoLabel.className = 'sn2-detail-settings-label sn2-ruby-section-label sn2-ruby-section-label--ruled';
    autoLabel.textContent = `自動ルビルール（${autoRules.length}件）`;
    wrap.appendChild(autoLabel);

    const ruleList = document.createElement('div');
    ruleList.className = 'sn2-detail-list';
    autoRules.forEach((rule, i) => {
      const item = document.createElement('div');
      item.className = 'sn2-detail-item sn2-ruby-rule-item';
      item.draggable = true;
      item.dataset.idx = i;

      const handle = document.createElement('span');
      handle.className = 'sn2-detail-handle sn2-ruby-rule-handle';
      handle.setAttribute('aria-hidden', 'true');
      handle.textContent = '⠿';
      item.appendChild(handle);

      const textInp = document.createElement('input');
      textInp.type = 'text';
      textInp.value = rule.text || '';
      textInp.placeholder = '漢字';
      textInp.dataset.e2eId = 'scriptnote-ruby-rule-text-' + i;
      textInp.setAttribute('aria-label', '自動ルビ対象 ' + (i + 1));
      textInp.title = '自動ルビ対象';
      textInp.className = 'gb-input-sm sn2-ruby-rule-input';
      textInp.addEventListener('change', () => {
        this._pushUndo('ルビルール編集');
        rule.text = textInp.value.trim();
        this._refreshAutoRubyDisplay();
        this._markDirty({ skipUndo: true });
      });
      item.appendChild(textInp);

      const arrow = document.createElement('span');
      arrow.textContent = '→';
      arrow.className = 'sn2-ruby-rule-arrow';
      item.appendChild(arrow);

      const rubyInp = document.createElement('input');
      rubyInp.type = 'text';
      rubyInp.value = rule.ruby || '';
      rubyInp.placeholder = 'ルビ';
      rubyInp.dataset.e2eId = 'scriptnote-ruby-rule-ruby-' + i;
      rubyInp.setAttribute('aria-label', '自動ルビ ' + (i + 1));
      rubyInp.title = '自動ルビ';
      rubyInp.className = 'gb-input-sm sn2-ruby-rule-input';
      rubyInp.addEventListener('change', () => {
        this._pushUndo('ルビルール編集');
        rule.ruby = rubyInp.value.trim();
        this._refreshAutoRubyDisplay();
        this._markDirty({ skipUndo: true });
      });
      item.appendChild(rubyInp);

      // 解除ボタン（右端固定、改行しない）
      const delBtn = document.createElement('button');
      delBtn.className = 'gb-btn gb-btn-xs gb-btn-icon gb-btn-quiet sn2-ruby-delete-rule';
      delBtn.type = 'button';
      delBtn.title = '解除';
      delBtn.dataset.e2eId = 'scriptnote-ruby-rule-delete-' + i;
      delBtn.setAttribute('aria-label', '自動ルビルールを解除 ' + (i + 1));
      delBtn.innerHTML = _snRubyIcon('trash2', 13, '解除');
      delBtn.addEventListener('click', async () => {
        const ok = await _snRubyConfirmDelete(`ルビルール「${rule.text || '(空)'}→${rule.ruby || '(空)'}」を解除しますか？`);
        if (!ok) return;
        this._pushUndo('ルビルール解除');
        autoRules.splice(i, 1);
        this._refreshAutoRubyDisplay();
        this._markDirty({ skipUndo: true });
        this.renderRubyPanel(container);
      });
      item.appendChild(delBtn);

      ruleList.appendChild(item);
    });
    wrap.appendChild(ruleList);

    // D&D for auto rules
    this._setupRubyDragDrop(ruleList, container);

    container.appendChild(wrap);
  },

  _setupRubyDragDrop(listEl, panelContainer) {
    let dragIdx = -1;
    const clearDragState = () => {
      dragIdx = -1;
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => el.classList.remove('sn2-dragging', 'sn2-drop-above', 'sn2-drop-below'));
    };
    listEl.addEventListener('dragstart', (e) => {
      const item = e.target.closest('.sn2-detail-item');
      if (!item) return;
      dragIdx = Number(item.dataset.idx);
      item.classList.add('sn2-dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    listEl.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => el.classList.remove('sn2-drop-above', 'sn2-drop-below'));
      const item = e.target.closest('.sn2-detail-item');
      if (item) {
        const rect = item.getBoundingClientRect();
        item.classList.toggle('sn2-drop-above', e.clientY < rect.top + rect.height / 2);
        item.classList.toggle('sn2-drop-below', e.clientY >= rect.top + rect.height / 2);
      }
    });
    listEl.addEventListener('dragend', () => {
      clearDragState();
    });
    listEl.addEventListener('drop', (e) => {
      e.preventDefault();
      const item = e.target.closest('.sn2-detail-item');
      if (!item || dragIdx < 0) { clearDragState(); return; }
      const rules = this.doc.rubyRules || [];
      let dropIdx = Number(item.dataset.idx);
      const rect = item.getBoundingClientRect();
      if (e.clientY >= rect.top + rect.height / 2) dropIdx++;
      if (dropIdx === dragIdx || dropIdx === dragIdx + 1) { clearDragState(); return; }
      this._pushUndo('ルビルール並び替え');
      const [moved] = rules.splice(dragIdx, 1);
      rules.splice(dropIdx > dragIdx ? dropIdx - 1 : dropIdx, 0, moved);
      this._refreshAutoRubyDisplay();
      this._markDirty({ skipUndo: true });
      clearDragState();
      this.renderRubyPanel(panelContainer);
    });
  },

  _escHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  },

});

;

/* === gb-scriptnote-rowset.js === */
;
/* gb-scriptnote-rowset.js: 台本エディタ v2 — 行セットタブ
   ScriptNoteEditor.prototype を拡張する
   行の組み合わせを指定回数分、台本に追加する機能 */

const SN2_ROWSET_PRESETS_STORAGE_KEY = 'sn2-rowset-presets';
const SN2_ROWSET_STORAGE_HISTORY_SCOPE = 'settings:scriptnote';

function _snRowsetIcon(name, size, fallback) {
  if (typeof lucide === 'function') return lucide(name, size || 14);
  return fallback || '';
}

function _snRowsetIsRenderedFocusTarget(target) {
  if (!target?.isConnected || target.hidden || typeof target.focus !== 'function') return false;
  let node = target;
  while (node && node !== document.body) {
    if (node.hidden) return false;
    const style = window.getComputedStyle ? getComputedStyle(node) : null;
    if (style && (style.display === 'none' || style.visibility === 'hidden')) return false;
    node = node.parentElement;
  }
  const rect = typeof target.getBoundingClientRect === 'function' ? target.getBoundingClientRect() : null;
  return !rect || (rect.width > 0 && rect.height > 0);
}

function _snRowsetRestoreFocus(target) {
  if (!_snRowsetIsRenderedFocusTarget(target)) return;
  if (typeof focusMeldexDropdownTrigger === 'function') {
    focusMeldexDropdownTrigger(target);
    return;
  }
  try { target.focus({ preventScroll: true }); } catch { target.focus(); }
}

function _snRowsetConfirmDelete(message) {
  if (typeof cfConfirm === 'function') {
    return cfConfirm(message, { danger: true, okLabel: '削除' }).then(Boolean);
  }
  if (typeof showConfirmDialog === 'function') {
    return new Promise(resolve => showConfirmDialog(message, () => resolve(true), () => resolve(false)));
  }
  if (typeof confirm === 'function') return Promise.resolve(!!confirm(message));
  return Promise.resolve(false);
}

function _snRowsetCaptureStorageHistory() {
  if (typeof captureLocalStorageSettings !== 'function') return null;
  if (typeof isLocalStorageSettingsHistorySuppressed === 'function'
    && isLocalStorageSettingsHistorySuppressed()) return null;
  return captureLocalStorageSettings([SN2_ROWSET_PRESETS_STORAGE_KEY]);
}

function _snRowsetRefreshAfterHistory() {
  if (typeof forEachComponent !== 'function') return;
  forEachComponent(component => {
    if (!component?._editor || component._editor._detailActiveTab !== 'rowset') return;
    if (typeof component._syncDetailPanel === 'function') component._syncDetailPanel();
  });
}

function _snRowsetPushStorageHistory(label, beforeSnapshot, detail) {
  if (!beforeSnapshot || typeof historyPush !== 'function'
    || typeof captureLocalStorageSettings !== 'function'
    || typeof restoreLocalStorageSettings !== 'function'
    || typeof _normalizeLocalStorageSettingsSnapshots !== 'function') return false;
  const afterSnapshot = captureLocalStorageSettings([SN2_ROWSET_PRESETS_STORAGE_KEY]);
  const snapshots = _normalizeLocalStorageSettingsSnapshots(beforeSnapshot, afterSnapshot);
  let beforeKey = '';
  let afterKey = '';
  try {
    beforeKey = JSON.stringify(snapshots.before);
    afterKey = JSON.stringify(snapshots.after);
  } catch {}
  if (beforeKey && beforeKey === afterKey) return false;
  historyPush(
    label || 'シナリオ: 行セットプリセット変更',
    () => restoreLocalStorageSettings(snapshots.before, _snRowsetRefreshAfterHistory),
    () => restoreLocalStorageSettings(snapshots.after, _snRowsetRefreshAfterHistory),
    SN2_ROWSET_STORAGE_HISTORY_SCOPE,
    detail || '行セットプリセット'
  );
  return true;
}

Object.assign(ScriptNoteEditor.prototype, {

  _readRowsetPresets() {
    try {
      const parsed = JSON.parse(localStorage.getItem(SN2_ROWSET_PRESETS_STORAGE_KEY) || '{}');
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  },

  _writeRowsetPresets(presets, options = {}) {
    const beforeStorage = options.skipHistory ? null : _snRowsetCaptureStorageHistory();
    localStorage.setItem(SN2_ROWSET_PRESETS_STORAGE_KEY, JSON.stringify(presets && typeof presets === 'object' ? presets : {}));
    if (!options.skipHistory) {
      _snRowsetPushStorageHistory(
        options.label || 'シナリオ: 行セットプリセット変更',
        beforeStorage,
        options.detail || ''
      );
    }
  },

  renderRowsetPanel(container) {
    if (!container || !this.doc) return;
    container.innerHTML = '';
    const wrap = document.createElement('div');
    wrap.className = 'sn2-rowset-panel';

    // 現在の行セット状態（セッション中保持）
    if (!this._rowsetRows) this._rowsetRows = [];

    const roleChoices = globalThis.GBScriptNoteRoleModel?.buildRoleChoices?.(this.doc) || [];
    const charaNames = roleChoices
      .filter((choice) => choice && choice.kind !== 'none')
      .map((choice) => String(choice.name || choice.label || ''))
      .filter(Boolean);

    // ── ヘッダー ──
    const header = document.createElement('div');
    header.className = 'sn2-detail-header';
    const title = document.createElement('span');
    title.className = 'sn2-rowset-title';
    title.textContent = '行セット';
    header.appendChild(title);
    wrap.appendChild(header);

    // ── プリセット ──
    const presetRow = document.createElement('div');
    presetRow.className = 'sn2-rowset-preset-row';
    const presetSel = document.createElement('select');
    presetSel.className = 'gb-select gb-select-sm sn2-rowset-preset-select';
    presetSel.dataset.e2eId = 'scriptnote-rowset-preset-select';
    presetSel.title = '行セットプリセットを選択';
    presetSel.setAttribute('aria-label', '行セットプリセットを選択');
    this._refreshRowsetPresetOptions(presetSel);
    presetSel.addEventListener('change', () => {
      const val = presetSel.value;
      if (!val) return;
      const presets = this._readRowsetPresets();
      const preset = presets[val];
      if (preset) {
        this._rowsetRows = JSON.parse(JSON.stringify(preset));
        this.renderRowsetPanel(container);
      }
    });
    presetRow.appendChild(presetSel);
    // 保存ボタン
    const saveBtn = document.createElement('button');
    saveBtn.className = 'sn2-detail-add-btn gb-btn gb-btn-sm gb-btn-quiet sn2-rowset-save-preset';
    saveBtn.type = 'button';
    saveBtn.textContent = '保存';
    saveBtn.title = '現在の行セットをプリセットとして保存';
    saveBtn.dataset.e2eId = 'scriptnote-rowset-save-preset';
    saveBtn.setAttribute('aria-label', '現在の行セットをプリセットとして保存');
    saveBtn.addEventListener('click', () => {
      if (!this._rowsetRows.length) return;
      const focusReturnTarget = saveBtn;
      const dialogId = `sn2-rsp-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
      const titleId = dialogId + '-title';
      const inputId = dialogId + '-name';
      const overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      overlay.dataset.sn2Dialog = 'rowset-preset-save';
      const modal = document.createElement('div');
      modal.className = 'modal sn2-rowset-save-modal';
      modal.setAttribute('role', 'dialog');
      modal.setAttribute('aria-modal', 'true');
      modal.setAttribute('aria-labelledby', titleId);
      const heading = document.createElement('h3');
      heading.id = titleId;
      heading.textContent = '行セットプリセット保存';
      const body = document.createElement('div');
      body.className = 'modal-body sn2-rowset-save-body';
      const field = document.createElement('label');
      field.className = 'sn2-rowset-save-field';
      field.setAttribute('for', inputId);
      const labelText = document.createElement('span');
      labelText.className = 'gb-label';
      labelText.textContent = 'プリセット名';
      const input = document.createElement('input');
      input.type = 'text';
      input.id = inputId;
      input.className = 'gb-input sn2-rowset-save-input';
      input.placeholder = '台詞＋ト書き';
      input.dataset.e2eId = 'scriptnote-rowset-save-preset-name';
      input.setAttribute('aria-label', '行セットプリセット名');
      field.append(labelText, input);
      body.appendChild(field);
      const actions = document.createElement('div');
      actions.className = 'btn-row sn2-rowset-save-actions';
      const cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.className = 'gb-btn gb-btn-sm cancel-btn';
      cancelBtn.textContent = 'キャンセル';
      const okBtn = document.createElement('button');
      okBtn.type = 'button';
      okBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary ok-btn';
      okBtn.textContent = '保存';
      actions.append(cancelBtn, okBtn);
      modal.append(heading, body, actions);
      overlay.appendChild(modal);
      const close = () => {
        if (typeof window !== 'undefined') window.removeEventListener('keydown', keyHandler, true);
        document.removeEventListener('keydown', keyHandler, true);
        overlay.remove();
        _snRowsetRestoreFocus(focusReturnTarget);
        setTimeout(() => _snRowsetRestoreFocus(focusReturnTarget), 0);
        setTimeout(() => _snRowsetRestoreFocus(focusReturnTarget), 60);
        if (typeof requestAnimationFrame === 'function') {
          requestAnimationFrame(() => _snRowsetRestoreFocus(focusReturnTarget));
        }
      };
      const doSave = () => {
        const name = input.value.trim();
        if (!name) return;
        close();
        const presets = this._readRowsetPresets();
        presets[name] = JSON.parse(JSON.stringify(this._rowsetRows));
        this._writeRowsetPresets(presets, {
          label: 'シナリオ: 行セットプリセット保存',
          detail: name,
        });
        this._refreshRowsetPresetOptions(presetSel);
        if (typeof showStatus === 'function') showStatus(`行セットプリセット「${name}」を保存しました`);
      };
      function keyHandler(ev) {
        if (ev.key === 'Escape') {
          ev.preventDefault();
          ev.stopPropagation();
          ev.stopImmediatePropagation?.();
          close();
        }
      }
      okBtn.addEventListener('click', doSave);
      cancelBtn.addEventListener('click', close);
      input.addEventListener('keydown', ev => { if (ev.key === 'Enter') doSave(); });
      overlay.addEventListener('click', ev => { if (ev.target === overlay) close(); });
      if (typeof window !== 'undefined') window.addEventListener('keydown', keyHandler, true);
      document.addEventListener('keydown', keyHandler, true);
      document.body.appendChild(overlay);
      if (typeof window !== 'undefined' && window.GBModalShell?.enhanceOverlay) {
        window.GBModalShell.enhanceOverlay(overlay);
      }
      input.focus();
      input.select();
    });
    presetRow.appendChild(saveBtn);
    // 削除ボタン
    const delPresetBtn = document.createElement('button');
    delPresetBtn.className = 'sn2-detail-add-btn gb-btn gb-btn-sm gb-btn-danger sn2-rowset-delete-preset';
    delPresetBtn.type = 'button';
    delPresetBtn.textContent = '削除';
    delPresetBtn.title = '選択中のプリセットを削除';
    delPresetBtn.dataset.e2eId = 'scriptnote-rowset-delete-preset';
    delPresetBtn.setAttribute('aria-label', '選択中のプリセットを削除');
    delPresetBtn.addEventListener('click', async () => {
      const val = presetSel.value;
      if (!val) return;
      const presets = this._readRowsetPresets();
      if (!presets[val]) return;
      if (!await _snRowsetConfirmDelete(`プリセット「${val}」を削除しますか？`)) return;
      delete presets[val];
      this._writeRowsetPresets(presets, {
        label: 'シナリオ: 行セットプリセット削除',
        detail: val,
      });
      this._refreshRowsetPresetOptions(presetSel);
      if (typeof showStatus === 'function') showStatus(`プリセット「${val}」を削除しました`);
    });
    presetRow.appendChild(delPresetBtn);
    wrap.appendChild(presetRow);

    // ── 行リスト ──
    const listLabel = document.createElement('div');
    listLabel.className = 'sn2-rowset-list-label gb-section-desc';
    listLabel.textContent = '行の組み合わせ';
    wrap.appendChild(listLabel);

    const listWrap = document.createElement('div');
    listWrap.className = 'sn2-rowset-list-wrap';
    const list = document.createElement('div');
    list.className = 'sn2-rowset-list';

    this._rowsetRows.forEach((entry, i) => {
      const item = document.createElement('div');
      item.className = 'sn2-detail-item sn2-rowset-item';
      item.draggable = true;
      item.dataset.idx = i;

      // ドラッグハンドル
      const handle = document.createElement('span');
      handle.className = 'sn2-detail-handle sn2-rowset-handle';
      handle.innerHTML = _snRowsetIcon('gripVertical', 14, '↕');
      handle.setAttribute('aria-hidden', 'true');
      item.appendChild(handle);

      // タイプ選択
      const sel = document.createElement('select');
      sel.className = 'gb-select gb-select-sm sn2-rowset-role-select';
      sel.dataset.e2eId = 'scriptnote-rowset-role-' + i;
      sel.title = '行セット ' + (i + 1) + ' 行目のタイプ';
      sel.setAttribute('aria-label', sel.title);
      const emptyOpt = document.createElement('option');
      emptyOpt.value = '';
      emptyOpt.textContent = '（なし）';
      sel.appendChild(emptyOpt);
      if (entry.role && !charaNames.includes(entry.role)) {
        const retainedOpt = document.createElement('option');
        retainedOpt.value = entry.role;
        retainedOpt.textContent = entry.role;
        retainedOpt.selected = true;
        sel.appendChild(retainedOpt);
      }
      charaNames.forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        opt.textContent = name;
        if (name === entry.role) opt.selected = true;
        sel.appendChild(opt);
      });
      sel.addEventListener('change', () => { entry.role = sel.value; });
      item.appendChild(sel);

      // 削除ボタン
      const delBtn = document.createElement('button');
      delBtn.className = 'gb-btn gb-btn-xs gb-btn-icon gb-btn-quiet sn2-rowset-delete-row';
      delBtn.type = 'button';
      delBtn.innerHTML = _snRowsetIcon('x', 12, '×');
      delBtn.title = '行セット ' + (i + 1) + ' 行目を削除';
      delBtn.dataset.e2eId = 'scriptnote-rowset-delete-row-' + i;
      delBtn.setAttribute('aria-label', delBtn.title);
      delBtn.addEventListener('click', () => {
        this._rowsetRows.splice(i, 1);
        this.renderRowsetPanel(container);
      });
      item.appendChild(delBtn);

      list.appendChild(item);
    });

    // D&D
    this._setupRowsetDragDrop(list, container);

    listWrap.appendChild(list);
    wrap.appendChild(listWrap);

    // ── 追加ボタン ──
    const addBtn = document.createElement('button');
    addBtn.className = 'sn2-detail-add-btn gb-btn gb-btn-sm gb-btn-quiet sn2-rowset-add-row';
    addBtn.type = 'button';
    addBtn.innerHTML = _snRowsetIcon('plus', 14, '+') + ' 行を追加';
    addBtn.dataset.e2eId = 'scriptnote-rowset-add-row';
    addBtn.title = '行セットに行を追加';
    addBtn.setAttribute('aria-label', '行セットに行を追加');
    addBtn.addEventListener('click', () => {
      this._rowsetRows.push({ role: '' });
      this.renderRowsetPanel(container);
    });
    wrap.appendChild(addBtn);

    // ── 実行セクション ──
    const execRow = document.createElement('div');
    execRow.className = 'sn2-rowset-exec-row';
    const repeatLabel = document.createElement('span');
    repeatLabel.className = 'gb-section-desc sn2-rowset-repeat-label';
    repeatLabel.textContent = '回数';
    execRow.appendChild(repeatLabel);
    const repeatInput = document.createElement('input');
    repeatInput.type = 'number';
    repeatInput.min = '1';
    repeatInput.max = '100';
    repeatInput.value = this._rowsetRepeat || '1';
    repeatInput.dataset.e2eId = 'scriptnote-rowset-repeat';
    repeatInput.title = '行セットの追加回数';
    repeatInput.setAttribute('aria-label', '行セットの追加回数');
    repeatInput.className = 'gb-input-sm sn2-rowset-repeat-input';
    repeatInput.addEventListener('change', () => { this._rowsetRepeat = parseInt(repeatInput.value) || 1; });
    execRow.appendChild(repeatInput);
    const execBtn = document.createElement('button');
    execBtn.className = 'sn2-detail-add-btn gb-btn gb-btn-sm gb-btn-primary sn2-rowset-insert';
    execBtn.type = 'button';
    execBtn.textContent = 'シナリオに追加';
    execBtn.dataset.e2eId = 'scriptnote-rowset-insert';
    execBtn.title = '行セットをシナリオに追加';
    execBtn.setAttribute('aria-label', '行セットをシナリオに追加');
    execBtn.addEventListener('click', () => this._execRowsetInsert(container));
    execRow.appendChild(execBtn);
    wrap.appendChild(execRow);

    container.appendChild(wrap);
  },

  _execRowsetInsert(panelContainer) {
    if (!this._rowsetRows.length || !this.doc) return;
    const repeat = Math.max(1, Math.min(100, this._rowsetRepeat || 1));

    // カーソル位置を特定
    let insertIdx = this.doc.rows.length - 1;
    const sel = window.getSelection();
    if (sel?.rangeCount) {
      const textEl = sel.focusNode?.nodeType === 1
        ? sel.focusNode.closest?.('.sn2-text')
        : sel.focusNode?.parentElement?.closest?.('.sn2-text');
      if (textEl) {
        const rowEl = textEl.closest('.sn2-row');
        if (rowEl) {
          const rowId = rowEl.dataset.rowId;
          const idx = this.doc.rows.findIndex(r => r.id === rowId);
          if (idx >= 0) insertIdx = idx;
        }
      }
    }

    this._pushUndo('行セット追加');
    const newRows = [];
    let newStatus = '';
    if (this._filterStatuses && this._filterStatuses.size === 1) {
      newStatus = [...this._filterStatuses][0];
    }
    for (let r = 0; r < repeat; r++) {
      this._rowsetRows.forEach(entry => {
        newRows.push({
          id: `sn-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          role: entry.role || '',
          status: newStatus,
          text: '',
          columns: {},
        });
      });
    }
    if (globalThis.GBScriptNoteRoleModel?.assignRowRole) {
      newRows.forEach((row) => globalThis.GBScriptNoteRoleModel.assignRowRole(this.doc, row, row.role));
    }
    this.doc.rows.splice(insertIdx + 1, 0, ...newRows);
    this._calcCache = null;
    this._render();
    this._markDirty({ skipUndo: true });

    // 最初の追加行にフォーカス
    if (newRows.length) {
      requestAnimationFrame(() => {
        const rowEl = this.host?.querySelector(`.sn2-row[data-row-id="${newRows[0].id}"]`);
        const textEl = rowEl?.querySelector('.sn2-text');
        if (textEl) this._focusText(textEl, 'start');
      });
    }
    if (typeof showStatus === 'function') showStatus(`${newRows.length}行を追加しました`);
  },

  _refreshRowsetPresetOptions(sel) {
    const presets = this._readRowsetPresets();
    const prevVal = sel.value;
    while (sel.options.length) sel.remove(0);
    const emptyOpt = document.createElement('option');
    emptyOpt.value = '';
    emptyOpt.textContent = '（プリセット選択）';
    sel.appendChild(emptyOpt);
    Object.keys(presets).forEach(name => {
      const opt = document.createElement('option');
      opt.value = name;
      opt.textContent = name;
      sel.appendChild(opt);
    });
    if (prevVal && [...sel.options].some(o => o.value === prevVal)) sel.value = prevVal;
  },

  _setupRowsetDragDrop(listEl, panelContainer) {
    let dragIdx = -1;
    const clearDragState = () => {
      dragIdx = -1;
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => el.classList.remove('sn2-dragging', 'sn2-drop-above', 'sn2-drop-below'));
    };
    listEl.addEventListener('dragstart', (e) => {
      const item = e.target.closest('.sn2-detail-item');
      if (!item) return;
      dragIdx = Number(item.dataset.idx);
      item.classList.add('sn2-dragging');
      e.dataTransfer.effectAllowed = 'move';
    });
    listEl.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      listEl.querySelectorAll('.sn2-detail-item').forEach(el => el.classList.remove('sn2-drop-above', 'sn2-drop-below'));
      const item = e.target.closest('.sn2-detail-item');
      if (item) {
        const rect = item.getBoundingClientRect();
        item.classList.toggle('sn2-drop-above', e.clientY < rect.top + rect.height / 2);
        item.classList.toggle('sn2-drop-below', e.clientY >= rect.top + rect.height / 2);
      }
    });
    listEl.addEventListener('dragend', () => {
      clearDragState();
    });
    listEl.addEventListener('drop', (e) => {
      e.preventDefault();
      const item = e.target.closest('.sn2-detail-item');
      if (!item || dragIdx < 0) { clearDragState(); return; }
      let dropIdx = Number(item.dataset.idx);
      const rect = item.getBoundingClientRect();
      if (e.clientY >= rect.top + rect.height / 2) dropIdx++;
      if (dropIdx === dragIdx || dropIdx === dragIdx + 1) { clearDragState(); return; }
      const [moved] = this._rowsetRows.splice(dragIdx, 1);
      this._rowsetRows.splice(dropIdx > dragIdx ? dropIdx - 1 : dropIdx, 0, moved);
      clearDragState();
      this.renderRowsetPanel(panelContainer);
    });
  },

});

;

/* === gb-scriptnote-columns.js === */
;
/* gb-scriptnote-columns.js: 台本エディタ v2 — 列管理（リサイズ、カスタム列追加/編集/削除、ヘッダーメニュー）
   ScriptNoteEditor.prototype を拡張する */

Object.assign(ScriptNoteEditor.prototype, {

  _bindColumnModalOverlay(overlay, focusSelector) {
    if (!overlay) return () => {};
    if (typeof window !== 'undefined' && window.GBModalShell?.enhanceOverlay) {
      window.GBModalShell.enhanceOverlay(overlay);
    }
    let closed = false;
    function close() {
      if (closed) return;
      closed = true;
      document.removeEventListener('keydown', keyHandler, true);
      overlay.remove();
    }
    function keyHandler(ev) {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      close();
    }
    overlay.addEventListener('click', (ev) => {
      if (ev.target === overlay) close();
    });
    document.addEventListener('keydown', keyHandler, true);
    requestAnimationFrame(() => {
      if (!overlay.isConnected) return;
      const target = focusSelector ? overlay.querySelector(focusSelector) : null;
      target?.focus?.();
      target?.select?.();
    });
    return close;
  },

  _startColResize(e, colId, resizerEl) {
    e.preventDefault();
    this._pushUndo('列幅変更');
    const isVertical = this.doc.editor?.viewMode === 'vertical';
    const startPos = isVertical ? e.clientY : e.clientX;
    const editor = this.host?.querySelector('.sn2-editor');
    if (!editor) return;
    if (!this.doc.editor.columnWidths) this.doc.editor.columnWidths = {};
    const headerCell = this.host?.querySelector(`.sn2-header-cell[data-col-id="${colId}"]`);
    let currentSize = this.doc.editor.columnWidths[colId];
    if (!currentSize) {
      currentSize = headerCell
        ? (isVertical ? headerCell.getBoundingClientRect().height : headerCell.getBoundingClientRect().width)
        : 80;
    }
    currentSize = Math.round(currentSize);
    const scrollEl = this.host?.querySelector('.sn2-scroll');
    const vcolVar = `--sn2-vcol-${colId}`;
    const colVar = `--sn2-col-${colId}`;
    const onMove = (ev) => {
      const delta = (isVertical ? ev.clientY : ev.clientX) - startPos;
      const newSize = Math.max(30, currentSize + delta);
      this.doc.editor.columnWidths[colId] = newSize;
      if (isVertical) {
        editor.style.setProperty(vcolVar, newSize + 'px');
        if (scrollEl) scrollEl.style.setProperty(vcolVar, newSize + 'px');
        if (headerCell) headerCell.style.height = newSize + 'px';
      } else {
        editor.style.setProperty(colVar, newSize + 'px');
        if (scrollEl) scrollEl.style.setProperty(colVar, newSize + 'px');
        if (colId === '_text') {
          editor.style.setProperty('--sn2-text-flex', '0 0 auto');
          if (scrollEl) scrollEl.style.setProperty('--sn2-text-flex', '0 0 auto');
        }
        if (headerCell) { headerCell.style.width = newSize + 'px'; headerCell.classList.remove('sn2-header-flex'); }
      }
    };
    const onUp = () => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      // 縦書き: ヘッダーの高さ変更に合わせて全行の高さを再同期
      if (isVertical) {
        const header = scrollEl?.querySelector('.sn2-header');
        if (header) {
          const hH = header.offsetHeight;
          scrollEl.querySelectorAll('.sn2-row').forEach(r => { r.style.height = hH + 'px'; });
        }
      }
      this._markDirty();
    };
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
  },

  _currentColSize(colId) {
    const isVertical = this.doc.editor?.viewMode === 'vertical';
    const headerCell = this.host?.querySelector(`.sn2-header-cell[data-col-id="${colId}"]`);
    const stored = Number(this.doc.editor?.columnWidths?.[colId]);
    if (Number.isFinite(stored) && stored > 0) return Math.round(stored);
    if (headerCell) {
      const rect = headerCell.getBoundingClientRect();
      return Math.round(isVertical ? rect.height : rect.width);
    }
    return 80;
  },

  _applyColSize(colId, size) {
    if (!this.doc.editor.columnWidths) this.doc.editor.columnWidths = {};
    const newSize = Math.max(30, Math.round(Number(size) || 30));
    const isVertical = this.doc.editor?.viewMode === 'vertical';
    const editor = this.host?.querySelector('.sn2-editor');
    const scrollEl = this.host?.querySelector('.sn2-scroll');
    const headerCell = this.host?.querySelector(`.sn2-header-cell[data-col-id="${colId}"]`);
    this.doc.editor.columnWidths[colId] = newSize;
    if (isVertical) {
      const vcolVar = `--sn2-vcol-${colId}`;
      editor?.style.setProperty(vcolVar, newSize + 'px');
      scrollEl?.style.setProperty(vcolVar, newSize + 'px');
      if (headerCell) headerCell.style.height = newSize + 'px';
      const header = scrollEl?.querySelector('.sn2-header');
      if (header) {
        const headerHeight = header.offsetHeight;
        scrollEl.querySelectorAll('.sn2-row').forEach(rowEl => { rowEl.style.height = headerHeight + 'px'; });
      }
      return;
    }
    const colVar = `--sn2-col-${colId}`;
    editor?.style.setProperty(colVar, newSize + 'px');
    scrollEl?.style.setProperty(colVar, newSize + 'px');
    if (colId === '_text') {
      editor?.style.setProperty('--sn2-text-flex', '0 0 auto');
      scrollEl?.style.setProperty('--sn2-text-flex', '0 0 auto');
    }
    if (headerCell) {
      headerCell.style.width = newSize + 'px';
      headerCell.classList.remove('sn2-header-flex');
    }
  },

  _handleColResizerKeydown(e, colId) {
    const isVertical = this.doc.editor?.viewMode === 'vertical';
    const positiveKey = isVertical ? 'ArrowDown' : 'ArrowRight';
    const negativeKey = isVertical ? 'ArrowUp' : 'ArrowLeft';
    if (e.key !== positiveKey && e.key !== negativeKey) return;
    e.preventDefault();
    e.stopPropagation();
    const step = e.shiftKey ? 1 : 10;
    const delta = e.key === positiveKey ? step : -step;
    this._pushUndo('列幅変更');
    this._applyColSize(colId, this._currentColSize(colId) + delta);
    this._markDirty();
  },

  // === ヘッダーダブルクリックで列名編集 ===

  _startHeaderLabelEdit(cell, colId) {
    const isStandard = colId.startsWith('_');
    const customCols = this._getCustomColumns();
    const colDef = isStandard ? null : customCols.find(c => c.id === colId);
    const currentLabel = cell.textContent.replace('…', '').trim();
    const input = document.createElement('input');
    input.type = 'text';
    input.value = currentLabel;
    input.setAttribute('aria-label', `${currentLabel || '列'}列名`);
    input.title = `${currentLabel || '列'}列名`;
    input.style.cssText = 'width:100%;padding:2px 4px;border:1px solid var(--blue,#4a90d9);border-radius:2px;background:var(--bg);color:var(--fg);font-size:11px;font-weight:600;outline:none;box-sizing:border-box;';
    cell.textContent = '';
    cell.appendChild(input);
    input.focus();
    input.select();
    let finished = false;
    const commit = () => {
      if (finished) return;
      finished = true;
      const newLabel = input.value.trim() || currentLabel;
      if (newLabel === currentLabel) {
        this._render();
        return;
      }
      this._pushUndo('列名変更');
      if (isStandard) {
        if (!this.doc.editor.columnLabels) this.doc.editor.columnLabels = {};
        this.doc.editor.columnLabels[colId] = newLabel;
      } else if (colDef) {
        colDef.label = newLabel;
      }
      this._markDirty();
      this._render();
    };
    input.addEventListener('blur', commit);
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); input.blur(); }
      if (e.key === 'Escape') {
        e.preventDefault();
        if (finished) return;
        finished = true;
        input.value = currentLabel;
        this._render();
      }
    });
  },

  // === ヘッダーメニュー（セルクリックで表示） ===

  _showHeaderMenu(cell, colId) {
    // 既存メニュー・サブメニューを閉じる
    document.querySelectorAll('.sn2-header-popup, .sn2-header-sub-popup').forEach(el => el.remove());
    document.querySelectorAll('.sn2-header-cell[aria-expanded="true"]').forEach(el => {
      el.setAttribute('aria-expanded', 'false');
    });
    const isStandard = colId.startsWith('_');
    const customCols = this._getCustomColumns();
    const colDef = isStandard ? null : customCols.find(c => c.id === colId);

    // 現在の設定を取得
    const getSettings = () => {
      if (isStandard) {
        if (!this.doc.editor.standardColumnSettings) this.doc.editor.standardColumnSettings = {};
        if (!this.doc.editor.standardColumnSettings[colId]) this.doc.editor.standardColumnSettings[colId] = {};
        return this.doc.editor.standardColumnSettings[colId];
      }
      return colDef || {};
    };
    const settings = getSettings();

    const popup = document.createElement('div');
    popup.className = 'sn2-header-popup';
    popup.id = `sn2-header-popup-${String(colId || 'col').replace(/[^a-zA-Z0-9_-]/g, '-')}`;
    popup.setAttribute('role', 'menu');
    popup.setAttribute('aria-label', `${(cell.textContent || '列').trim() || '列'}列メニュー`);

    const mkSep = () => { const el = document.createElement('div'); el.className = 'sn2-header-popup-sep'; return el; };
    const mkItem = (text, active, onClick) => {
      const btn = document.createElement('button');
      btn.className = 'sn2-header-popup-item' + (active ? ' active' : '');
      btn.type = 'button';
      btn.textContent = text;
      btn.setAttribute('role', 'menuitem');
      btn.addEventListener('click', onClick);
      return btn;
    };
    // サブメニュー付きアイテム
    let openSub = null;
    const closeSub = () => {
      if (openSub) {
        openSub._triggerBtn?.setAttribute('aria-expanded', 'false');
        openSub.remove();
        openSub = null;
      }
    };
    const mkSubItem = (text, currentLabel, buildSub) => {
      const btn = document.createElement('button');
      btn.className = 'sn2-header-popup-item sn2-header-popup-sub-trigger';
      btn.type = 'button';
      btn.setAttribute('role', 'menuitem');
      btn.setAttribute('aria-haspopup', 'menu');
      btn.setAttribute('aria-expanded', 'false');
      btn.innerHTML = `<span>${text}: <b>${currentLabel}</b></span><span class="sn2-header-popup-arrow">${lucide('chevronRight', 10)}</span>`;
      btn.addEventListener('click', () => {
        if (openSub?._triggerBtn === btn) { closeSub(); return; }
        closeSub();
        const sub = document.createElement('div');
        sub.className = 'sn2-header-sub-popup sn2-header-popup';
        sub._triggerBtn = btn;
        sub.setAttribute('role', 'menu');
        sub.setAttribute('aria-label', `${text}メニュー`);
        buildSub(sub);
        const bRect = btn.getBoundingClientRect();
        sub.style.cssText = 'position:fixed;z-index:10001;';
        document.body.appendChild(sub);
        btn.setAttribute('aria-expanded', 'true');
        positionPopup(sub, bRect, { prefer: 'right' });
        openSub = sub;
      });
      return btn;
    };

    // 配置（現在値+サブメニュー）
    // 縦書き（vertical-rl）では align は上下方向（left=上）、valign は左右方向（top=右）に
    // 対応するため、保存値はそのままにラベルだけを縦書き向けへ切り替える
    const isVerticalWriting = this.doc.editor?.viewMode === 'vertical';
    const alignLabels = isVerticalWriting
      ? { left: '上寄せ', center: '中央', right: '下寄せ' }
      : { left: '左寄せ', center: '中央', right: '右寄せ' };
    popup.appendChild(mkSubItem(isVerticalWriting ? '垂直' : '水平', alignLabels[settings.align] || alignLabels.left, (sub) => {
      ['left', 'center', 'right'].forEach((val) => {
        sub.appendChild(mkItem(alignLabels[val], settings.align === val, () => {
          this._pushUndo('列配置変更'); settings.align = val; this._markDirty(); this._render(); closePopup();
        }));
      });
    }));

    const valignLabels = isVerticalWriting
      ? { top: '右寄せ', middle: '中央', bottom: '左寄せ' }
      : { top: '上寄せ', middle: '中央', bottom: '下寄せ' };
    popup.appendChild(mkSubItem(isVerticalWriting ? '水平' : '垂直', valignLabels[settings.valign] || valignLabels.top, (sub) => {
      ['top', 'middle', 'bottom'].forEach((val) => {
        sub.appendChild(mkItem(valignLabels[val], settings.valign === val, () => {
          this._pushUndo('列配置変更'); settings.valign = val; this._markDirty(); this._render(); closePopup();
        }));
      });
    }));

    // テキスト折り返し（現在値+サブメニュー）
    const overflowLabels = { wrap: '折り返し', overflow: 'はみ出し', clip: '切り詰め' };
    popup.appendChild(mkSubItem('テキスト', overflowLabels[settings.overflow] || '折り返し', (sub) => {
      [['折り返し', 'wrap'], ['はみ出し', 'overflow'], ['切り詰め', 'clip']].forEach(([label, val]) => {
        sub.appendChild(mkItem(label, settings.overflow === val, () => {
          this._pushUndo('列配置変更'); settings.overflow = val; this._markDirty(); this._render(); closePopup();
        }));
      });
    }));

    popup.appendChild(mkSep());

    // 列スタイル（背景色・テキスト色・書式・フォントサイズ）
    popup.appendChild(mkItem('列スタイル設定…', false, () => {
      closePopup();
      this._showColumnStylePopup(cell, colId);
    }));

    popup.appendChild(mkSep());

    // 列操作
    popup.appendChild(mkItem('列を追加（右に）', false, () => { closePopup(); this._addColumnAt(colId); }));
    if (!isStandard) {
      popup.appendChild(mkItem('列を複製', false, () => { closePopup(); this._duplicateColumn(colId); }));
    }
    if (colId !== '_handle') {
      popup.appendChild(mkItem('列を削除', false, () => { closePopup(); this._deleteColumn(colId); }));
    }

    // 列固有メニュー
    if (colDef?.type === 'select') {
      popup.appendChild(mkSep());
      popup.appendChild(mkItem('選択肢を編集…', false, () => { closePopup(); this._editDropdownOptions(colId); }));
    }
    if (colDef?.type === 'number') {
      popup.appendChild(mkSep());
      popup.appendChild(mkItem('単位を設定…', false, () => { closePopup(); this._showUnitPopup(cell, colId); }));
    }

    // 非表示の標準列を復元
    const visCols = this.doc.editor?.visibleStandardColumns;
    if (visCols) {
      const hiddenLabels = { _gutter: '大区切り', _gutter2: '小区切り', _role: 'タイプ', _status: '採用状況', _text: 'テキスト' };
      const hiddenCols = Object.entries(hiddenLabels).filter(([id]) => (id !== '_status' || this.doc.editor?.statusEnabled) && visCols[id] === false);
      if (hiddenCols.length) {
        popup.appendChild(mkSep());
        hiddenCols.forEach(([id, label]) => {
          popup.appendChild(mkItem(`${label}列を表示`, false, () => {
            this._pushUndo('列表示変更'); visCols[id] = true; this._markDirty(); this._render(); closePopup();
          }));
        });
      }
    }

    let closeHandler = null;
    let escapeHandler = null;
    const closePopup = (options = {}) => {
      closeSub();
      popup.remove();
      cell.setAttribute('aria-expanded', 'false');
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (escapeHandler) {
        document.removeEventListener('keydown', escapeHandler, true);
        escapeHandler = null;
      }
      if (options.restoreFocus) cell.focus();
    };

    // 位置決め
    document.body.appendChild(popup);
    cell.setAttribute('aria-expanded', 'true');
    cell.setAttribute('aria-controls', popup.id);
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: cell,
        close: closePopup,
      });
    }
    popup.style.cssText = 'position:fixed;z-index:10000;';
    positionPopup(popup, cell.getBoundingClientRect());
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);

    closeHandler = (ev) => {
      if (!popup.contains(ev.target) && !openSub?.contains(ev.target) && !ev.target.closest?.('.gb-fmt-popup') && !ev.target.closest?.('.gb-palette-popup')) closePopup();
    };
    escapeHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closePopup({ restoreFocus: true });
    };
    document.addEventListener('keydown', escapeHandler, true);
    requestAnimationFrame(() => popup.querySelector('.sn2-header-popup-item')?.focus());
    setTimeout(() => {
      if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

  // === 列スタイル設定ポップアップ ===

  _showColumnStylePopup(anchorEl, colId) {
    document.querySelectorAll('.gb-fmt-popup--col-style').forEach(el => el.remove());
    if (!this.doc.editor.columnStyles) this.doc.editor.columnStyles = {};
    if (!this.doc.editor.columnStyles[colId]) this.doc.editor.columnStyles[colId] = {};
    const cs = this.doc.editor.columnStyles[colId];
    const safeColor = (value, fallback) => {
      const raw = String(value || '').trim();
      if (!raw) return fallback;
      if (raw === 'transparent') return raw;
      if (/^#[0-9a-f]{3,8}$/i.test(raw)) return raw;
      if (/^rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*(?:0|1|0?\.\d+))?\s*\)$/i.test(raw)) return raw;
      if (/^var\(--[-_a-zA-Z0-9]+\)$/.test(raw)) return raw;
      return fallback;
    };
    const fontSize = Number.isFinite(Number(cs.fontSize)) ? Math.max(8, Math.min(48, Number(cs.fontSize))) : '';
    const bgColor = safeColor(cs.bgColor, 'transparent');
    const textColor = safeColor(cs.textColor, 'var(--fg)');
    const popup = document.createElement('div');
    popup.className = 'gb-fmt-popup gb-fmt-popup--col-style';
    popup.innerHTML = `
      <div class="sn2-col-style-title">列スタイル</div>
      <div class="sn2-col-style-row">
        <button type="button" class="gb-fmt-swatch gb-fmt-swatch-bg" data-csp="bgColor" style="background:${bgColor};" title="背景色"></button>
        <button type="button" class="gb-fmt-swatch gb-fmt-swatch-fg" data-csp="textColor" style="color:${textColor};" title="テキスト色">T</button>
        <button type="button" class="gb-fmt-btn${cs.fontWeight === 'bold' ? ' active' : ''}" data-csp-toggle-fmt="fontWeight" title="太字"><b>B</b></button>
        <button type="button" class="gb-fmt-btn${cs.fontStyle === 'italic' ? ' active' : ''}" data-csp-toggle-fmt="fontStyle" title="斜体"><i>I</i></button>
        <input type="number" class="gb-fmt-num gb-fmt-num--w54" data-csp-num="fontSize" value="${fontSize}" placeholder="px" min="8" max="48">
        <button type="button" class="gb-fmt-btn sn2-col-style-reset" data-csp-reset title="リセット">${lucide('rotateCcw', 12)}</button>
      </div>
      <div class="sn2-col-style-note">※ タイプ管理の設定が優先されます</div>`;
    let closeHandler = null;
    let escapeHandler = null;
    const closePopup = () => {
      popup.remove();
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (escapeHandler) {
        document.removeEventListener('keydown', escapeHandler, true);
        escapeHandler = null;
      }
    };
    const refresh = () => { this._refreshRowStyles(); this._markDirty(); };
    // カラーピッカー
    popup.querySelectorAll('[data-csp]').forEach(btn => {
      btn.addEventListener('click', () => {
        if (typeof openColorPalette === 'function') {
          openColorPalette(btn, cs[btn.dataset.csp] || '#888', (color) => {
            this._pushUndo('列スタイル変更');
            if (color === 'transparent') { delete cs[btn.dataset.csp]; } else { cs[btn.dataset.csp] = color; }
            if (btn.dataset.csp === 'bgColor') btn.style.background = cs.bgColor || 'transparent';
            if (btn.dataset.csp === 'textColor') btn.style.color = cs.textColor || 'var(--fg)';
            refresh();
          });
        }
      });
    });
    // B / I トグル
    popup.querySelectorAll('[data-csp-toggle-fmt]').forEach(btn => {
      btn.addEventListener('click', () => {
        this._pushUndo('列スタイル変更');
        const prop = btn.dataset.cspToggleFmt;
        const activeVal = prop === 'fontWeight' ? 'bold' : 'italic';
        cs[prop] = cs[prop] === activeVal ? '' : activeVal;
        btn.classList.toggle('active', cs[prop] === activeVal);
        refresh();
      });
    });
    // サイズ
    popup.querySelectorAll('[data-csp-num]').forEach(inp => {
      inp.addEventListener('change', () => { this._pushUndo('列スタイル変更'); cs[inp.dataset.cspNum] = inp.value ? Number(inp.value) : ''; refresh(); });
    });
    // リセット
    popup.querySelector('[data-csp-reset]')?.addEventListener('click', () => {
      this._pushUndo('列スタイル変更');
      Object.keys(cs).forEach(k => delete cs[k]);
      popup.querySelector('[data-csp="bgColor"]').style.background = 'transparent';
      popup.querySelector('[data-csp="textColor"]').style.color = 'var(--fg)';
      popup.querySelectorAll('[data-csp-toggle-fmt]').forEach(b => b.classList.remove('active'));
      const sizeInp = popup.querySelector('[data-csp-num="fontSize"]'); if (sizeInp) sizeInp.value = '';
      refresh();
    });
    // (タイプ優先は常時有効 — トグル廃止)

    popup.style.cssText = 'position:fixed;z-index:10001;min-width:220px;';
    document.body.appendChild(popup);
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorEl,
        close: closePopup,
      });
    }
    positionPopup(popup, anchorEl.getBoundingClientRect());
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
    escapeHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      closePopup();
    };
    document.addEventListener('keydown', escapeHandler, true);
    setTimeout(() => {
      if (!popup.isConnected) return;
      closeHandler = (ev) => {
        if (!popup.contains(ev.target) && !ev.target.closest?.('.gb-palette-popup') && !ev.target.closest?.('.sn2-header-popup') && !ev.target.closest?.('.gb-fmt-popup')) {
          closePopup();
        }
      };
      document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

  // === 列追加（指定列の右に） ===

  _addColumnAt(afterColId) {
    if (!this.doc) return;
    if (!this.doc.editor.customColumns) this.doc.editor.customColumns = [];
    const id = 'col-' + Date.now();
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal sn2-column-modal" style="min-width:480px;max-width:640px;">
      <h3>列を追加</h3>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:8px;min-height:300px;">
        <div class="field"><label>列名</label><input type="text" id="sn2-col-name" value="新しい列" style="width:100%;padding:4px 6px;"></div>
        <div class="field"><label>タイプ</label>
          <select id="sn2-col-type" style="width:100%;padding:4px 6px;">
            <option value="text">テキスト</option>
            <option value="number">数値</option>
            <option value="select">ドロップダウン</option>
          </select>
        </div>
        <div class="field" id="sn2-col-options-wrap" style="display:none;">
          <label>選択肢（改行区切り）</label>
          <textarea id="sn2-col-options" rows="8" style="width:100%;padding:4px 6px;"></textarea>
        </div>
        <div class="field"><label>幅(px)</label><input type="number" id="sn2-col-width" value="80" min="20" max="400" style="width:80px;padding:4px 6px;"></div>
      </div>
      <div class="btn-row">
        <button class="btn" id="sn2-col-cancel">キャンセル</button>
        <button class="primary" id="sn2-col-ok">追加</button>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    const closeOverlay = this._bindColumnModalOverlay(overlay, '#sn2-col-name');
    const typeSel = overlay.querySelector('#sn2-col-type');
    const optWrap = overlay.querySelector('#sn2-col-options-wrap');
    typeSel.addEventListener('change', () => { optWrap.style.display = typeSel.value === 'select' ? '' : 'none'; });
    overlay.querySelector('#sn2-col-cancel').addEventListener('click', closeOverlay);
    overlay.querySelector('#sn2-col-ok').addEventListener('click', () => {
      const label = overlay.querySelector('#sn2-col-name').value.trim() || '列';
      const type = typeSel.value;
      const rawWidth = Number(overlay.querySelector('#sn2-col-width').value);
      const width = Math.max(20, Math.min(400, Number.isFinite(rawWidth) ? rawWidth : 80));
      const options = type === 'select'
        ? overlay.querySelector('#sn2-col-options').value.split('\n').map(s => s.trim()).filter(Boolean)
        : undefined;
      this._pushUndo('列追加');
      const newCol = { id, label, type, width, options };
      // afterColIdの位置を探して、その直後に挿入
      const afterIdx = this.doc.editor.customColumns.findIndex(c => c.id === afterColId);
      if (afterIdx >= 0) {
        this.doc.editor.customColumns.splice(afterIdx + 1, 0, newCol);
      } else {
        this.doc.editor.customColumns.push(newCol);
      }
      const statusEnabled = !!this.doc.editor?.statusEnabled;
      const visCols = { _gutter: true, _gutter2: true, _role: true, _status: statusEnabled, _text: true, ...(this.doc.editor?.visibleStandardColumns || {}) };
      if (!statusEnabled) visCols._status = false;
      const stdOrder = ['_gutter', '_gutter2', '_role', '_status', '_text'].filter(col => visCols[col] !== false);
      const customOrder = this.doc.editor.customColumns.filter(c => c.id !== id).map(c => c.id);
      let order = Array.isArray(this.doc.editor.columnOrder)
        ? this.doc.editor.columnOrder.filter(col => col !== '_handle' && col !== id)
        : [...stdOrder, ...customOrder];
      [...stdOrder, ...customOrder].forEach(col => { if (!order.includes(col)) order.push(col); });
      order = order.filter(col => stdOrder.includes(col) || customOrder.includes(col));
      const insertIdx = order.indexOf(afterColId);
      order.splice(insertIdx >= 0 ? insertIdx + 1 : 0, 0, id);
      this.doc.editor.columnOrder = order;
      this._render();
      this._markDirty();
      closeOverlay();
    });
  },

  // === 列を複製 ===

  _duplicateColumn(colId) {
    const customCols = this._getCustomColumns();
    const idx = customCols.findIndex(c => c.id === colId);
    if (idx < 0) return;
    const src = customCols[idx];
    const newId = 'col-' + Date.now();
    this._pushUndo('列複製');
    const dup = { ...src, id: newId, label: src.label + '（コピー）', options: src.options ? [...src.options] : undefined };
    customCols.splice(idx + 1, 0, dup);
    if (Array.isArray(this.doc.editor?.columnOrder)) {
      const order = this.doc.editor.columnOrder.filter(id => id !== newId && id !== '_handle');
      const orderIdx = order.indexOf(colId);
      order.splice(orderIdx >= 0 ? orderIdx + 1 : order.length, 0, newId);
      this.doc.editor.columnOrder = order;
    }
    // データも複製
    this.doc.rows.forEach(r => {
      if (r.columns && r.columns[colId] !== undefined) {
        r.columns[newId] = r.columns[colId];
      }
    });
    this._render();
    this._markDirty();
  },

  // === 列を削除 ===

  _deleteColumn(colId) {
    const colLabel = colId === '_gutter' ? '大区切り' : colId === '_gutter2' ? '小区切り' : colId === '_role' ? 'タイプ' : colId === '_status' ? '採用状況' : colId === '_text' ? 'テキスト'
      : (this._getCustomColumns().find(c => c.id === colId)?.label || colId);
    showConfirmDialog(`「${colLabel}」列を削除しますか？`, () => {
    this._pushUndo('列削除');
    const isStandard = colId.startsWith('_');
    if (isStandard) {
      // 標準列: visibleStandardColumnsで非表示にする
      if (!this.doc.editor.visibleStandardColumns) {
        this.doc.editor.visibleStandardColumns = { _handle: true, _gutter: true, _gutter2: true, _role: true, _status: !!this.doc.editor?.statusEnabled, _text: true };
      }
      // 最後の標準列（_handle除く）は削除不可
      const vis = this.doc.editor.visibleStandardColumns;
      const visibleCount = ['_gutter', '_gutter2', '_role', '_status', '_text']
        .filter(id => (id !== '_status' || this.doc.editor?.statusEnabled) && vis[id] !== false).length;
      if (visibleCount <= 1 && vis[colId] !== false) {
        if (typeof showStatus === 'function') showStatus('最後の標準列は削除できません', true);
        return;
      }
      vis[colId] = false;
    } else {
      // カスタム列: 配列から除去、各行のデータも除去
      const customCols = this._getCustomColumns();
      const idx = customCols.findIndex(c => c.id === colId);
      if (idx >= 0) customCols.splice(idx, 1);
      this.doc.rows.forEach(r => { if (r.columns) delete r.columns[colId]; });
    }
    this._render();
    this._markDirty();
    }); // showConfirmDialog
  },

  // === ドロップダウン列の選択肢編集 ===

  _editDropdownOptions(colId) {
    const customCols = this._getCustomColumns();
    const colDef = customCols.find(c => c.id === colId);
    if (!colDef || colDef.type !== 'select') return;
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal sn2-column-modal sn2-column-options-modal" style="min-width:400px;max-width:500px;">
      <h3>${esc(colDef.label)} — 選択肢を編集</h3>
      <div class="modal-body" style="min-height:200px;">
        <label>選択肢（改行区切り）</label>
        <textarea id="sn2-opt-edit" rows="10" style="width:100%;padding:6px;font-size:13px;"></textarea>
      </div>
      <div class="btn-row">
        <button class="btn" id="sn2-opt-cancel">キャンセル</button>
        <button class="primary" id="sn2-opt-ok">保存</button>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    const closeOverlay = this._bindColumnModalOverlay(overlay, '#sn2-opt-edit');
    const textarea = overlay.querySelector('#sn2-opt-edit');
    textarea.value = (colDef.options || []).join('\n');
    textarea.focus();
    overlay.querySelector('#sn2-opt-cancel').addEventListener('click', closeOverlay);
    overlay.querySelector('#sn2-opt-ok').addEventListener('click', () => {
      this._pushUndo('選択肢編集');
      const nextOptions = textarea.value.split('\n').map(s => s.trim()).filter(Boolean);
      const allowed = new Set(nextOptions);
      let cleared = 0;
      (this.doc.rows || []).forEach(row => {
        const val = row.columns?.[colId];
        if (val !== undefined && val !== '' && !allowed.has(String(val))) {
          row.columns[colId] = '';
          cleared++;
        }
      });
      colDef.options = nextOptions;
      this._render();
      this._markDirty();
      if (cleared && typeof showStatus === 'function') showStatus(`削除された選択肢を使っていた${cleared}件の値を空にしました`);
      closeOverlay();
    });
  },

  // === 数値列の単位設定 ===

  _showUnitPopup(anchorEl, colId) {
    const customCols = this._getCustomColumns();
    const colDef = customCols.find(c => c.id === colId);
    if (!colDef || colDef.type !== 'number') return;
    document.querySelectorAll('.sn2-header-popup').forEach(el => el.remove());
    const popup = document.createElement('div');
    popup.className = 'sn2-header-popup';
    popup.style.padding = '8px 12px';
    popup.innerHTML = `
      <div style="font-size:12px;font-weight:600;margin-bottom:6px;">単位を設定</div>
      <div style="display:flex;align-items:center;gap:6px;">
        <input type="text" id="sn2-unit-input" value="${esc(colDef.unit || '')}" placeholder="例: px, 円, kg"
          style="flex:1;padding:4px 6px;border:1px solid var(--border);border-radius:3px;background:var(--bg);color:var(--fg);font-size:12px;outline:none;">
        <button type="button" class="primary" id="sn2-unit-ok" style="padding:4px 12px;font-size:12px;">OK</button>
      </div>`;
    popup.style.cssText += 'position:fixed;z-index:10000;min-width:200px;';
    document.body.appendChild(popup);
    let closeHandler = null;
    let escapeHandler = null;
    const close = () => {
      popup.remove();
      if (closeHandler) {
        document.removeEventListener('pointerdown', closeHandler, true);
        closeHandler = null;
      }
      if (escapeHandler) {
        document.removeEventListener('keydown', escapeHandler, true);
        escapeHandler = null;
      }
    };
    if (typeof attachMeldexDropdownCloseButton === 'function') {
      attachMeldexDropdownCloseButton(popup, {
        trigger: anchorEl,
        close,
      });
    }
    positionPopup(popup, anchorEl.getBoundingClientRect());
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(popup);
    const input = popup.querySelector('#sn2-unit-input');
    input.focus();
    input.select();
    const save = () => {
      this._pushUndo('単位設定');
      colDef.unit = input.value.trim();
      this._render();
      this._markDirty();
      close();
    };
    popup.querySelector('#sn2-unit-ok').addEventListener('click', save);
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') save();
      if (e.key === 'Escape') close();
    });
    escapeHandler = (ev) => {
      if (ev.key !== 'Escape') return;
      ev.preventDefault();
      ev.stopPropagation();
      close();
    };
    document.addEventListener('keydown', escapeHandler, true);
    closeHandler = (ev) => { if (!popup.contains(ev.target)) close(); };
    setTimeout(() => {
      if (popup.isConnected) document.addEventListener('pointerdown', closeHandler, true);
    }, 0);
  },

  // === カスタム列追加（末尾に追加、既存メソッド） ===

  _addCustomColumn() {
    if (!this.doc) return;
    if (!this.doc.editor.customColumns) this.doc.editor.customColumns = [];
    const id = 'col-' + Date.now();
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal sn2-column-modal" style="min-width:480px;max-width:640px;">
      <h3>列を追加</h3>
      <div class="modal-body" style="display:flex;flex-direction:column;gap:8px;min-height:300px;">
        <div class="field"><label>列名</label><input type="text" id="sn2-col-name" value="新しい列" style="width:100%;padding:4px 6px;"></div>
        <div class="field"><label>タイプ</label>
          <select id="sn2-col-type" style="width:100%;padding:4px 6px;">
            <option value="text">テキスト</option>
            <option value="number">数値</option>
            <option value="select">ドロップダウン</option>
          </select>
        </div>
        <div class="field" id="sn2-col-options-wrap" style="display:none;">
          <label>選択肢（改行区切り）</label>
          <textarea id="sn2-col-options" rows="8" style="width:100%;padding:4px 6px;"></textarea>
        </div>
        <div class="field"><label>幅(px)</label><input type="number" id="sn2-col-width" value="80" min="20" max="400" style="width:80px;padding:4px 6px;"></div>
      </div>
      <div class="btn-row">
        <button class="btn" id="sn2-col-cancel">キャンセル</button>
        <button class="primary" id="sn2-col-ok">追加</button>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    const closeOverlay = this._bindColumnModalOverlay(overlay, '#sn2-col-name');
    const typeSel = overlay.querySelector('#sn2-col-type');
    const optWrap = overlay.querySelector('#sn2-col-options-wrap');
    typeSel.addEventListener('change', () => { optWrap.style.display = typeSel.value === 'select' ? '' : 'none'; });
    overlay.querySelector('#sn2-col-cancel').addEventListener('click', closeOverlay);
    overlay.querySelector('#sn2-col-ok').addEventListener('click', () => {
      const label = overlay.querySelector('#sn2-col-name').value.trim() || '列';
      const type = typeSel.value;
      const rawWidth = Number(overlay.querySelector('#sn2-col-width').value);
      const width = Math.max(20, Math.min(400, Number.isFinite(rawWidth) ? rawWidth : 80));
      const options = type === 'select'
        ? overlay.querySelector('#sn2-col-options').value.split('\n').map(s => s.trim()).filter(Boolean)
        : undefined;
      this._pushUndo('列追加');
      this.doc.editor.customColumns.push({ id, label, type, width, options });
      this._render();
      this._markDirty();
      closeOverlay();
    });
  },

});

;

/* === gb-entity-detail-surface.js === */
;
/* Shared editable entity detail surface for main, right-sidebar, and float panels. */
(function () {
  'use strict';

  let instanceSeq = 0;

  function parentDir(path) {
    return String(path || '').replace(/\\/g, '/').replace(/\/[^/]+$/, '');
  }

  function entityName(data, path) {
    return data?.entity || String(path || '').split(/[\\/]/).pop()?.replace(/\.md$/i, '') || '';
  }

  function xPostId(data) {
    const direct = String(data?.post_id || '').trim();
    if (direct) return direct;
    const values = data?.properties?.['ポストID'];
    for (const item of Array.isArray(values) ? values : []) {
      const value = String(item?.value ?? item ?? '').trim();
      if (value) return value;
    }
    return '';
  }

  function icon(name, size = 14) {
    return typeof lucide === 'function' ? lucide(name, size) : '';
  }

  function button(label, iconName, action, e2eId = '') {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'entity-create-action-btn meldex-entity-detail-action';
    el.dataset.e2eId = e2eId || ('entity-detail-action-' + iconName);
    el.setAttribute('aria-label', label);
    el.title = label;
    const iconBox = document.createElement('span');
    iconBox.className = 'entity-create-action-icon';
    iconBox.setAttribute('aria-hidden', 'true');
    iconBox.innerHTML = icon(iconName, 14);
    el.appendChild(iconBox);
    const text = document.createElement('span');
    text.className = 'entity-create-action-label';
    text.textContent = label;
    el.appendChild(text);
    el.addEventListener('click', action);
    return el;
  }

  function openChat(path) {
    if (typeof window.openEntityChatForPath === 'function') return window.openEntityChatForPath(path);
    if (typeof window.openEntityAiChat === 'function') return window.openEntityAiChat(path);
    if (typeof openFileChat === 'function') return openFileChat(path);
    if (typeof showStatus === 'function') showStatus('チャットを開けません', true);
  }

  function stripIds(root) {
    root.querySelectorAll('[id]').forEach(el => el.removeAttribute('id'));
  }

  function applyReadOnly(root, readOnly, reason) {
    root.dataset.readOnly = readOnly ? '1' : '0';
    root.setAttribute('aria-readonly', readOnly ? 'true' : 'false');
    root.querySelectorAll('[contenteditable]').forEach(el => el.setAttribute('contenteditable', readOnly ? 'false' : 'true'));
    root.querySelectorAll('input, textarea, select').forEach(el => {
      if ('readOnly' in el) el.readOnly = readOnly;
      if (el.tagName === 'SELECT') el.disabled = readOnly;
    });
    root.querySelectorAll('button').forEach(el => {
      if (el.dataset.allowReadonly === '1') return;
      el.disabled = readOnly;
      if (readOnly) el.setAttribute('aria-disabled', 'true');
    });
    let notice = root.querySelector('.meldex-entity-detail-readonly');
    if (!readOnly) {
      notice?.remove();
      return;
    }
    if (!notice) {
      notice = document.createElement('div');
      notice.className = 'meldex-entity-detail-readonly';
      notice.setAttribute('role', 'status');
      root.prepend(notice);
    }
    notice.textContent = reason || '読み取り専用です';
  }

  async function resolveReadOnly(path, explicit) {
    if (explicit === true || document.body?.dataset?.cloudReadonly === '1') {
      return { readOnly: true, reason: '閲覧専用のため編集できません' };
    }
    try {
      const result = await apiFetch('/file-lock/check?path=' + encodeURIComponent(path), { silentError: true });
      if (result?.locked) {
        return {
          readOnly: true,
          reason: '編集ロック中' + (result.entry?.lock_reason ? '（' + result.entry.lock_reason + '）' : '') + 'です',
        };
      }
    } catch {}
    return { readOnly: !!explicit, reason: '' };
  }

  function formatButton(label, iconName, command, value) {
    const el = document.createElement('button');
    el.type = 'button';
    el.className = 'tb-icon-btn';
    el.dataset.e2eId = 'entity-detail-format-' + command;
    el.title = label;
    el.setAttribute('aria-label', label);
    el.innerHTML = icon(iconName, 15) || label;
    el.addEventListener('mousedown', event => event.preventDefault());
    el.addEventListener('click', () => document.execCommand(command, false, value || null));
    return el;
  }

  function buildToolbar(editor) {
    const toolbar = document.createElement('div');
    toolbar.className = 'gb-toolbar meldex-entity-detail-toolbar';
    [
      ['太字', 'bold', 'bold'],
      ['斜体', 'italic', 'italic'],
      ['下線', 'underline', 'underline'],
      ['箇条書き', 'list', 'insertUnorderedList'],
      ['番号付きリスト', 'listOrdered', 'insertOrderedList'],
    ].forEach(([label, iconName, command]) => toolbar.appendChild(formatButton(label, iconName, command)));
    const link = formatButton('リンク', 'link', 'createLink');
    link.addEventListener('click', event => {
      event.stopImmediatePropagation();
      const selection = window.getSelection?.();
      const range = selection?.rangeCount ? selection.getRangeAt(0).cloneRange() : null;
      if (typeof showLinkInsertModal === 'function') {
        showLinkInsertModal(range);
      }
    }, true);
    toolbar.appendChild(link);
    toolbar.addEventListener('pointerdown', () => editor.focus(), true);
    return toolbar;
  }

  function mount(rootOrOptions, path, surface, readOnly) {
    const options = rootOrOptions?.nodeType
      ? { root: rootOrOptions, path, surface, readOnly }
      : (rootOrOptions || {});
    const root = options.root;
    if (!root || !options.path) {
      return { ready: Promise.resolve(false), flush: async () => false, dispose: async () => false };
    }
    const previousDispose = root._meldexEntityDetailController?.dispose?.();
    const id = 'entity-detail-' + (++instanceSeq);
    const state = {
      id,
      root,
      path: options.path,
      surface: options.surface || 'main',
      disposed: false,
      dirty: false,
      changeSeq: 0,
      timer: 0,
      saving: null,
      editor: null,
      data: options.data || null,
    };

    async function save() {
      if (state.disposed || !state.editor || state.root.dataset.readOnly === '1') return false;
      clearTimeout(state.timer);
      state.timer = 0;
      if (!state.dirty) return true;
      const savingSeq = state.changeSeq;
      const markdown = typeof htmlToMd === 'function' ? htmlToMd(state.editor.innerHTML) : state.editor.textContent;
      state.saving = Promise.resolve(_saveEntityFreeText(
        state.editor,
        state.path,
        markdown,
        { reason: 'entity-detail-surface' },
      ))
        .then(saved => {
          if (saved && state.changeSeq === savingSeq) state.dirty = false;
          return !!saved;
        })
        .finally(() => { state.saving = null; });
      return state.saving;
    }

    async function flush() {
      clearTimeout(state.timer);
      state.timer = 0;
      if (state.saving) await state.saving.catch(() => {});
      return save();
    }

    async function dispose() {
      if (state.disposed) return true;
      await flush().catch(() => {});
      state.disposed = true;
      clearTimeout(state.timer);
      if (root._meldexEntityDetailController === controller) delete root._meldexEntityDetailController;
      return true;
    }

    async function render() {
      root.dataset.meldexEntityDetail = id;
      root.dataset.surface = state.surface;
      root.dataset.path = state.path;
      root.replaceChildren();
      const loading = document.createElement('div');
      loading.className = 'meldex-entity-detail-loading';
      loading.textContent = 'エントリを読み込み中...';
      root.appendChild(loading);

      const parent = parentDir(state.path);
      const [data, meta, access] = await Promise.all([
        state.data || apiFetch('/entity?path=' + encodeURIComponent(state.path)),
        options.propTypes
          ? Promise.resolve({ property_types: options.propTypes })
          : (parent ? apiFetch('/db-metadata?path=' + encodeURIComponent(parent), { silentError: true }).catch(() => null) : null),
        resolveReadOnly(state.path, options.readOnly),
      ]);
      if (state.disposed || root.dataset.meldexEntityDetail !== id) return false;
      state.data = data || {};
      root.replaceChildren();
      root.classList.add('meldex-entity-detail');

      if (options.showParent !== false && parent) {
        const parentButton = document.createElement('button');
        parentButton.type = 'button';
        parentButton.className = 'gb-float-panel-link-button meldex-entity-detail-parent';
        parentButton.dataset.e2eId = state.surface === 'float'
          ? 'gb-float-panel-entity-parent'
          : 'entity-detail-parent-link';
        parentButton.dataset.allowReadonly = '1';
        parentButton.textContent = '← ' + (parent.split('/').pop() || parent);
        parentButton.title = parent;
        parentButton.setAttribute('aria-label', '親シートを開く');
        parentButton.addEventListener('click', () => {
          if (typeof selectDatabase === 'function') selectDatabase(parent);
        });
        if (state.surface === 'main') parentButton.id = 'entity-parent-link';
        root.appendChild(parentButton);
      }

      const title = document.createElement('h2');
      title.className = 'meldex-entity-detail-title';
      title.textContent = entityName(data, state.path);
      if (state.surface === 'main') title.id = 'entity-title';
      root.appendChild(title);

      const actions = document.createElement('div');
      actions.className = 'meldex-entity-detail-actions';
      if (state.surface === 'main') actions.id = 'entity-create-note-btn';
      actions.appendChild(button('チャットを作成', 'messageSquare', () => openChat(state.path), 'entity-create-chat'));
      // 旧・専用コピー用ボタンは廃止した（シート表示・ビュー状態・エントリ操作の改善計画
      // 2026-08-04）。列一覧内の文字選択に応じたコピーポップアップ（gb-entity-props-selection.js）
      // に置き換わったため、専用ボタンは不要になった。
      const postId = xPostId(data);
      if (postId && typeof window.reimportXBookmarkPost === 'function') {
        actions.appendChild(button('Xからこのポストを再インポート', 'refreshCw', async () => {
          try {
            await flush();
            await window.reimportXBookmarkPost(postId);
            const refreshed = await apiFetch('/entity?path=' + encodeURIComponent(state.path), { silentError: true });
            if (!state.disposed) {
              state.data = refreshed;
              options.data = refreshed;
              await render();
            }
          } catch (error) {
            if (typeof showStatus === 'function') showStatus('再インポートに失敗: ' + (error?.userMessage || error?.message || error), true);
          }
        }));
      }
      root.appendChild(actions);

      const grid = document.createElement('div');
      grid.className = 'meldex-entity-detail-props';
      if (state.surface === 'main') grid.id = 'entity-props-grid';
      root.appendChild(grid);
      if (typeof renderEntityPropsGridInto === 'function') {
        renderEntityPropsGridInto(grid, data, state.path, {
          parentDb: parent,
          propTypes: meta?.property_types || options.propTypes || undefined,
          surface: state.surface,
          readOnly: access.readOnly,
        });
      }

      const raw = String(data?.page_content || '');
      const editor = document.createElement('div');
      editor.className = 'meldex-entity-detail-editor';
      editor.dataset.e2eId = 'entity-detail-editor';
      if (state.surface === 'main') editor.id = 'entity-freetext';
      editor.setAttribute('contenteditable', access.readOnly ? 'false' : 'true');
      editor.dataset.entityPath = state.path;
      editor.dataset.lastSavedMd = raw;
      editor.dataset.lastSavedRevision = (data?.revision != null) ? String(data.revision) : '';
      editor.dataset.lastSavedEtag = data?.freetext_etag || '';
      editor.dataset.lastSavedTransportRevision = '';
      editor.innerHTML = raw.trim() && typeof mdToHtml === 'function'
        ? (typeof applyAutoLinks === 'function' ? applyAutoLinks(mdToHtml(raw, { basePath: state.path }), state.path) : mdToHtml(raw))
        : '';
      state.editor = editor;
      if (typeof _bindEntityFreeTextParticipant === 'function') {
        _bindEntityFreeTextParticipant(editor, state.path);
      }
      const toolbar = buildToolbar(editor);
      if (state.surface === 'main') toolbar.id = 'entity-rt-toolbar';
      root.appendChild(toolbar);
      root.appendChild(editor);

      if (!raw.trim() && !access.readOnly) {
        editor.hidden = true;
        toolbar.hidden = true;
        const createNote = button('ノートを作成', 'filePlus', async () => {
          editor.hidden = false;
          toolbar.hidden = false;
          editor.innerHTML = '<p><br></p>';
          state.dirty = true;
          await flush();
          editor.focus();
          createNote.remove();
        }, 'entity-create-note');
        actions.insertBefore(createNote, actions.firstChild);
      }

      editor.addEventListener('click', event => {
        const link = event.target.closest?.('.auto-link');
        if (!link || typeof onAutoLinkClick !== 'function') return;
        event.preventDefault();
        onAutoLinkClick(link, event);
      });
      editor.addEventListener('input', () => {
        state.dirty = true;
        state.changeSeq += 1;
        clearTimeout(state.timer);
        state.timer = setTimeout(() => {
          save().catch(() => {
            if (typeof showStatus === 'function') showStatus('エントリ本文の自動保存に失敗しました', true);
          });
        }, 2000);
      });
      editor.addEventListener('blur', () => {
        flush().then(saved => {
          if (saved && typeof showStatus === 'function') showStatus('エントリ本文を保存しました', false, { passiveSave: true });
        }).catch(() => {
          if (typeof showStatus === 'function') showStatus('エントリ本文の保存に失敗しました', true);
        });
      });

      if (state.surface !== 'main') stripIds(root);
      applyReadOnly(root, access.readOnly, access.reason);
      delete root.dataset.loadFailed;
      if (typeof replaceIcons === 'function') replaceIcons();
      return true;
    }

    const controller = { get editor() { return state.editor; }, flush, dispose, ready: null };
    root._meldexEntityDetailController = controller;
    controller.ready = Promise.resolve(previousDispose).catch(() => false).then(render).catch(error => {
      if (!state.disposed) {
        root.replaceChildren();
        root.dataset.loadFailed = '1';
        const message = document.createElement('div');
        message.className = 'meldex-entity-detail-loading';
        message.textContent = 'エントリを読み込めませんでした';
        root.appendChild(message);
      }
      console.error('[entity-detail] render failed', error);
      return false;
    });
    return controller;
  }

  window.MeldexEntityDetail = { mount };
})();

;

/* === gb-archive-browser.js === */
;
(function () {
  'use strict';

  window._archiveBrowseContext = null;

  function virtualPath(archivePath, member) {
    return 'zip:' + archivePath + '!/' + String(member || '');
  }

  function archiveFileUrl(item) {
    return '/api/archive/file?path=' + encodeURIComponent(item.archive_path)
      + '&member=' + encodeURIComponent(item.archive_member);
  }

  function archiveViewerUrl(item) {
    return '/viewer?archive=' + encodeURIComponent(item.archive_path)
      + '&member=' + encodeURIComponent(item.archive_member);
  }

  function updateReadOnlyBadge(visible) {
    document.getElementById('folder-archive-readonly-badge')?.remove();
    if (!visible) return;
    const title = document.getElementById('folder-title');
    if (!title?.parentElement) return;
    const badge = document.createElement('span');
    badge.id = 'folder-archive-readonly-badge';
    badge.className = 'gb-badge';
    badge.style.cssText = 'margin-left:8px;white-space:nowrap;';
    badge.textContent = 'ZIP内は読み取り専用';
    title.after(badge);
  }

  async function openArchiveFolder(archivePath, member, opts) {
    const options = opts || {};
    const normalizedMember = String(member || '').replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
    const path = virtualPath(archivePath, normalizedMember);
    if (!options.skipShowView && typeof showView === 'function') showView('folder');
    if (typeof showLoading === 'function' && !options.silent) showLoading('ZIPの内容を読み込み中...');
    try {
      const data = await apiFetch('/archive/browse?path=' + encodeURIComponent(archivePath)
        + '&member=' + encodeURIComponent(normalizedMember), { silentError: true });
      window._archiveBrowseContext = {
        archivePath: data.archive_path || archivePath,
        member: data.member || '',
        virtualPath: path,
      };
      _folderPath = path;
      _folderItems = Array.isArray(data.items) ? data.items : [];
      _folderSelected = null;
      _folderSelectedItems = [];
      const title = data.name || String(archivePath).split(/[\\/]/).pop() || 'ZIP';
      document.getElementById('folder-title').textContent = title;
      const currentTitle = document.getElementById('current-title');
      if (currentTitle && !options.skipGlobalUi) currentTitle.textContent = title;
      updateReadOnlyBadge(true);
      if (typeof registerFileTypes === 'function') registerFileTypes(_folderItems);
      renderFolderGrid({ resetScrollTop: true });
      if (!options.skipNavPush && typeof navPush === 'function') {
        navPush({
          type: 'archive',
          label: title,
          path,
          archivePath: data.archive_path || archivePath,
          member: data.member || '',
        });
      }
      if (!options.skipSaveLastView && typeof saveLastView === 'function') {
        saveLastView({
          type: 'archive',
          label: title,
          path,
          archivePath: data.archive_path || archivePath,
          member: data.member || '',
        });
      }
      if (typeof showStatus === 'function' && !options.skipGlobalUi) {
        showStatus('ZIP内は読み取り専用です');
      }
      return true;
    } catch (error) {
      if (typeof showStatus === 'function') {
        showStatus('ZIPを開けませんでした: ' + (error?.userMessage || error?.message || error), true);
      }
      return false;
    } finally {
      if (typeof hideLoading === 'function' && !options.silent) hideLoading();
    }
  }

  function openArchiveItem(item) {
    if (!item?.archive_path || !item?.archive_member) return false;
    if (item.is_dir || item.type === 'folder') {
      openArchiveFolder(item.archive_path, item.archive_member);
      return true;
    }
    if (item.type === 'image' || (item.type === 'document' && /\.pdf$/i.test(item.name || ''))) {
      openViewer(archiveViewerUrl(item));
      return true;
    }
    if (item.type === 'video' || item.type === 'audio') {
      openMedia(item.name, item.path, item.type, { rawUrl: archiveFileUrl(item), skipHighlight: true });
      return true;
    }
    openViewer(archiveFileUrl(item), { skipHighlight: true });
    return true;
  }

  function showArchiveItemContextMenu(event, item) {
    event.preventDefault();
    document.querySelectorAll('.gb-context-menu').forEach(menu => menu.remove());
    const menu = document.createElement('div');
    menu.className = 'gb-context-menu';
    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'gb-context-menu-item';
    open.textContent = '開く';
    open.addEventListener('click', () => {
      menu.remove();
      if (item?.archive_path) openArchiveItem(item);
    });
    const info = document.createElement('div');
    info.className = 'gb-context-menu-item disabled';
    info.textContent = 'ZIP内は読み取り専用';
    menu.append(open, info);
    const rect = { left: event.clientX, right: event.clientX, top: event.clientY, bottom: event.clientY };
    if (typeof positionPopup === 'function') positionPopup(menu, rect, { prefer: 'below', gap: 4 });
    else {
      menu.style.left = event.clientX + 'px';
      menu.style.top = event.clientY + 'px';
      document.body.appendChild(menu);
    }
    setTimeout(() => {
      const close = click => {
        if (menu.contains(click.target)) return;
        menu.remove();
        document.removeEventListener('pointerdown', close);
      };
      document.addEventListener('pointerdown', close);
    }, 0);
  }

  window.openArchiveFolder = openArchiveFolder;
  window.openArchiveItem = openArchiveItem;
  window.showArchiveItemContextMenu = showArchiveItemContextMenu;
  window.MeldexArchiveBrowser = {
    openFolder: openArchiveFolder,
    openItem: openArchiveItem,
    fileUrl: archiveFileUrl,
    viewerUrl: archiveViewerUrl,
    clear() {
      window._archiveBrowseContext = null;
      updateReadOnlyBadge(false);
    },
  };
})();

;

/* === gb-viewer-sheet-context.js === */
;
(function () {
  'use strict';

  const contexts = new Map();
  const MAX_CONTEXTS = 80;

  function normalizePath(value) {
    return String(value || '').replace(/\\/g, '/').replace(/\/+$/, '');
  }

  function contextForEntityPath(entityPath) {
    const active = typeof _currentPaneState === 'function' ? _currentPaneState() : null;
    const candidates = [active];
    if (typeof state !== 'undefined') candidates.push(state);
    return candidates.find(candidate => {
      const dbPath = candidate?.dbPath || candidate?.currentDbPath || state?.currentDbPath || '';
      return dbPath && normalizePath(entityPath).startsWith(normalizePath(dbPath) + '/');
    }) || active || state;
  }

  function entityNameForPath(ctx, dbPath, entityPath) {
    const entities = ctx?.pivotData?.entities || state?.pivotData?.entities || {};
    const target = normalizePath(entityPath);
    return Object.keys(entities).find(name => {
      if (typeof _entityPath === 'function') {
        return normalizePath(_entityPath(dbPath, name, ctx?.pivotData || state?.pivotData)) === target;
      }
      return target.endsWith('/' + normalizePath(name).replace(/\.md$/i, ''))
        || target.endsWith('/' + normalizePath(name));
    }) || '';
  }

  function visibleRowOrder(ctx, dbPath) {
    if (Array.isArray(ctx?._lastEntityNames)) return [...ctx._lastEntityNames];
    if (typeof _dbSortedEntityNames === 'function') {
      return _dbSortedEntityNames(ctx?.pivotData || state?.pivotData, dbPath, ctx, {
        applyAdvancedFilters: true,
      });
    }
    return Object.keys(ctx?.pivotData?.entities || state?.pivotData?.entities || {});
  }

  function visibleValues(rawValues, filterMode) {
    const source = Array.isArray(rawValues) ? rawValues : [];
    return typeof filterValues === 'function'
      ? filterValues(source, undefined, filterMode)
      : source;
  }

  function serializeImage(item) {
    const path = typeof _imagePropOpenPath === 'function' ? _imagePropOpenPath(item) : '';
    const url = typeof _imageSrc === 'function' ? _imageSrc(item, false) : (item?.url || item?.src || '');
    return {
      id: String(item?.id || item?.content_hash || item?.hash || path || url || ''),
      name: String(item?.caption || item?.filename || path.split('/').pop() || '画像'),
      path,
      url,
      width: Number(item?.width || 0),
      height: Number(item?.height || 0),
    };
  }

  function cellImages(ctx, entityName, propName) {
    const entity = ctx?.pivotData?.entities?.[entityName]
      || state?.pivotData?.entities?.[entityName]
      || {};
    const values = visibleValues(entity[propName], ctx?.filter ?? state?.filter ?? 'disabled');
    const images = [];
    values.forEach(value => {
      const parsed = typeof parseImagePropertyValue === 'function'
        ? parseImagePropertyValue(value?.value)
        : [];
      parsed.forEach(item => images.push(serializeImage(item)));
    });
    return images.filter(item => item.url || item.path);
  }

  function imageKey(item) {
    return String(item?.id || item?.content_hash || item?.hash
      || (typeof _imagePropOpenPath === 'function' ? _imagePropOpenPath(item) : '')
      || (typeof _imageSrc === 'function' ? _imageSrc(item, false) : '')
      || '');
  }

  function remember(context) {
    contexts.set(context.id, context);
    while (contexts.size > MAX_CONTEXTS) contexts.delete(contexts.keys().next().value);
    return context;
  }

  function create(options) {
    const entityPath = String(options?.entityPath || '');
    const propName = String(options?.propName || '');
    const ctx = options?.ctx || contextForEntityPath(entityPath);
    const dbPath = ctx?.dbPath || state?.currentDbPath || '';
    const rowOrder = visibleRowOrder(ctx, dbPath);
    const entityName = entityNameForPath(ctx, dbPath, entityPath);
    const foundRowIndex = rowOrder.indexOf(entityName);
    const rowIndex = foundRowIndex >= 0 ? foundRowIndex : 0;
    const imagesByRow = rowOrder.map(name => cellImages(ctx, name, propName));
    const clickedKey = imageKey(options?.item);
    const foundImageIndex = imagesByRow[rowIndex]?.findIndex(image => image.id === clickedKey) ?? -1;
    const startIndex = foundImageIndex >= 0 ? foundImageIndex : 0;
    return remember({
      id: 'sheet-viewer-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2),
      dbPath,
      paneId: ctx?.paneId || (typeof GBLayout !== 'undefined' ? GBLayout.activePane : ''),
      propName,
      rowOrder,
      imagesByRow,
      rowIndex,
      startIndex,
      createdAt: Date.now(),
    });
  }

  function payload(context, options) {
    const rowIndex = Number.isInteger(options?.rowIndex) ? options.rowIndex : context.rowIndex;
    return {
      type: 'viewer-sheet-context-set',
      contextId: context.id,
      sheetPath: context.dbPath,
      column: context.propName,
      rowIndex,
      rowCount: context.rowOrder.length,
      rowName: context.rowOrder[rowIndex] || '',
      images: context.imagesByRow[rowIndex] || [],
      startIndex: Number.isInteger(options?.startIndex) ? options.startIndex : context.startIndex,
      boundary: !!options?.boundary,
      message: options?.message || '',
    };
  }

  function post(target, message) {
    target?.postMessage?.(message, location.origin && location.origin !== 'null' ? location.origin : '*');
  }

  function handleRequest(message, target) {
    const context = contexts.get(String(message?.contextId || ''));
    if (!context) {
      post(target, {
        type: 'viewer-sheet-context-set',
        contextId: String(message?.contextId || ''),
        images: [],
        boundary: true,
        message: 'シートの画像閲覧情報が見つかりません',
      });
      return true;
    }
    post(target, payload(context));
    return true;
  }

  function handleRowNavigation(message, target) {
    const context = contexts.get(String(message?.contextId || ''));
    if (!context) return handleRequest(message, target);
    const direction = Number(message?.direction) < 0 ? -1 : 1;
    let candidate = context.rowIndex + direction;
    while (candidate >= 0 && candidate < context.rowOrder.length) {
      if (context.imagesByRow[candidate]?.length) {
        context.rowIndex = candidate;
        context.startIndex = 0;
        post(target, payload(context, { rowIndex: candidate, startIndex: 0 }));
        return true;
      }
      candidate += direction;
    }
    post(target, payload(context, {
      boundary: true,
      message: direction < 0 ? '前に画像がある行はありません' : '次に画像がある行はありません',
    }));
    return true;
  }

  window.MeldexViewerSheetContext = {
    create,
    viewerUrl(context) {
      return '/viewer?sheetContext=' + encodeURIComponent(context.id);
    },
    handleRequest,
    handleRowNavigation,
    get(id) {
      return contexts.get(String(id || '')) || null;
    },
  };
})();

;

/* === gb-scriptnote-ruby-settings-ui.js === */
;
/* gb-scriptnote-ruby-settings-ui.js: shared RubyPresentation settings UI */
(function (global) {
  'use strict';

  const MODEL = () => global.MeldexRubyPresentation;
  const FIELD_DEFS = Object.freeze([
    { key: 'writingMode', label: '書字方向', type: 'select', options: [['horizontal', '横書き'], ['vertical', '縦書き']] },
    { key: 'sizePercent', label: 'サイズ（親文字比%）', type: 'number', min: 5, max: 200, step: 5, unit: '%' },
    { key: 'gapEm', label: '親文字との間隔', type: 'number', min: -2, max: 4, step: 0.05, unit: 'em' },
    { key: 'letterSpacingEm', label: 'ルビの字間', type: 'number', min: -2, max: 3, step: 0.05, unit: 'em' },
    { key: 'lineHeight', label: 'ルビ行の行間', type: 'number', min: 0.5, max: 5, step: 0.1, unit: '倍' },
    { key: 'align', label: '配置方法', type: 'select', options: [['center', '中付き'], ['start', '肩付き']] },
    { key: 'smallKana', label: '小書き仮名', type: 'select', options: [['keep', '小書きのまま'], ['fullsize', '直音に変換']] },
    { key: 'fontPreset', label: 'ルビ用フォント', type: 'select', options: [['inherit', '本文と同じ'], ['sans-jp', '日本語ゴシック'], ['serif-jp', '日本語明朝'], ['gothic-jp', '読みやすいゴシック']] },
    { key: 'defaultStyle', label: 'ルビ種類', type: 'select', options: [['group', 'グループ'], ['mono', 'モノ'], ['jukugo', '熟語']] },
  ]);

  function numberValue(raw) {
    if (typeof raw === 'number') return raw;
    const parsed = Number(String(raw ?? '').trim());
    return Number.isFinite(parsed) ? parsed : null;
  }

  function controlValue(control, def) {
    if (def.type !== 'number') return String(control.value || '');
    return numberValue(control.value);
  }

  function makeOption(value, label, current) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    option.selected = value === current;
    return option;
  }

  function refreshControl(control, def, presentation) {
    const value = presentation?.[def.key];
    control.value = value == null ? '' : String(value);
  }

  function syncWritingModeButtons(editor, presentation) {
    const root = editor?.host?.closest?.('.gb-scriptnote-root');
    if (!root?.querySelector) return;
    root.querySelector('#btn-horizontal')?.classList.toggle('active', presentation.writingMode === 'horizontal');
    root.querySelector('#btn-vertical')?.classList.toggle('active', presentation.writingMode === 'vertical');
  }

  function createField(editor, def, scope) {
    const row = document.createElement('label');
    row.className = 'sn2-ruby-field sn2-ruby-presentation-field';
    const label = document.createElement('span');
    label.className = 'sn2-ruby-field-label';
    label.textContent = def.label;
    row.appendChild(label);

    const control = document.createElement(def.type === 'select' ? 'select' : 'input');
    control.className = def.type === 'select'
      ? 'gb-select gb-select-sm sn2-ruby-presentation-control'
      : 'gb-num-input sn2-ruby-number-input sn2-ruby-presentation-control';
    control.dataset.rubyPresentationField = def.key;
    control.dataset.e2eId = `${scope}-ruby-${def.key}`;
    control.setAttribute('aria-label', def.label);
    control.title = def.label;
    if (def.type === 'select') {
      def.options.forEach(([value, text]) => control.appendChild(makeOption(value, text, '')));
    } else {
      control.type = 'number';
      control.min = String(def.min);
      control.max = String(def.max);
      control.step = String(def.step);
    }
    refreshControl(control, def, MODEL().ensureDocument(editor.doc));
    control.addEventListener('change', () => {
      const nextValue = controlValue(control, def);
      if (nextValue === null) {
        refreshControl(control, def, MODEL().ensureDocument(editor.doc));
        return;
      }
      editor._pushUndo?.(`ルビ${def.label}変更`);
      const presentation = MODEL().updateDocument(editor.doc, { [def.key]: nextValue });
      syncWritingModeButtons(editor, presentation);
      editor._render?.();
      editor._markDirty?.({ skipUndo: true });
      try {
        global.dispatchEvent?.(new CustomEvent('meldex:ruby-presentation-change', {
          detail: { doc: editor.doc, field: def.key },
        }));
      } catch (_) {}
    });
    row.appendChild(control);
    if (def.unit) {
      const unit = document.createElement('span');
      unit.className = 'sn2-ruby-unit';
      unit.textContent = def.unit;
      row.appendChild(unit);
    }
    return { row, control };
  }

  function createEditorSettings(editor, options = {}) {
    if (!editor?.doc || !MODEL()) return document.createElement('div');
    const scope = String(options.scope || 'scriptnote');
    const root = document.createElement('div');
    root.className = 'sn2-ruby-settings sn2-ruby-presentation-settings';
    root.dataset.rubyPresentationScope = scope;
    const controls = new Map();
    FIELD_DEFS.forEach(def => {
      const built = createField(editor, def, scope);
      controls.set(def.key, built.control);
      root.appendChild(built.row);
    });
    const compatibility = MODEL().ensureDocument(editor.doc).compatibility;
    if (compatibility?.useLegacySize || compatibility?.useLegacyGap) {
      const note = document.createElement('p');
      note.className = 'sn2-ruby-compatibility-note';
      note.dataset.e2eId = `${scope}-ruby-legacy-compatibility`;
      note.innerHTML = `旧文書の見た目を維持中です ${fieldHelp('サイズまたは間隔を変更すると、その項目だけ新しい方式へ切り替わります')}`;
      root.appendChild(note);
    }
    const refresh = event => {
      if (root.isConnected === false) {
        global.removeEventListener?.('meldex:ruby-presentation-change', refresh);
        return;
      }
      if (event?.detail?.doc && event.detail.doc !== editor.doc) return;
      const presentation = MODEL().ensureDocument(editor.doc);
      FIELD_DEFS.forEach(def => refreshControl(controls.get(def.key), def, presentation));
    };
    global.addEventListener?.('meldex:ruby-presentation-change', refresh);
    return root;
  }

  function esc(value) {
    return String(value ?? '').replace(/[&<>"']/g, char => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[char]));
  }

  function globalSettingsHtml() {
    const values = MODEL().getGlobalDefaults();
    const fields = FIELD_DEFS.map(def => {
      const attrs = `data-ruby-presentation-global-field="${esc(def.key)}" data-onchange="_meldexRubyPresentationGlobalChanged(this)" aria-label="${esc(def.label)}" title="${esc(def.label)}"`;
      let control;
      if (def.type === 'select') {
        const options = def.options.map(([value, label]) => `<option value="${esc(value)}"${values[def.key] === value ? ' selected' : ''}>${esc(label)}</option>`).join('');
        control = `<select class="gb-select gb-select-sm sn2-ruby-presentation-control" ${attrs}>${options}</select>`;
      } else {
        control = `<input type="number" class="cs-width-input cs-number-input sn2-ruby-presentation-control" min="${esc(def.min)}" max="${esc(def.max)}" step="${esc(def.step)}" value="${esc(values[def.key])}" ${attrs}>`;
      }
      return `<label class="cs-row-group cs-row-group--number sn2-ruby-presentation-global-field"><span class="cs-row-group-label">${esc(def.label)}</span>${control}${def.unit ? `<span class="cs-number-unit">${esc(def.unit)}</span>` : ''}</label>`;
    }).join('');
    return `<div class="cs-row cs-row--ruby-presentation"><span class="cs-row-label">ルビ表示</span><div class="sn2-ruby-presentation-global" data-e2e-id="settings-ruby-presentation-defaults">${fields}</div></div>`;
  }

  function globalChanged(control) {
    const key = control?.dataset?.rubyPresentationGlobalField;
    const def = FIELD_DEFS.find(item => item.key === key);
    if (!def) return;
    const value = controlValue(control, def);
    if (value === null) {
      control.value = String(MODEL().getGlobalDefaults()[key]);
      return;
    }
    const next = MODEL().setGlobalDefaults({ [key]: value });
    control.value = String(next[key]);
  }

  global.MeldexRubySettingsUI = Object.freeze({
    FIELD_DEFS,
    createEditorSettings,
    globalSettingsHtml,
  });
  global._meldexRubyPresentationGlobalChanged = globalChanged;
})(typeof window !== 'undefined' ? window : globalThis);

;
